export const MIGRATION_FILES: readonly MigrationFile[] = [
  { version: "0001_init", sql: "-- Banto 0001_init: コアスキーマ + RLS + 在庫 RPC\n-- 前方専用マイグレーション。ロールバックは書かない（CLAUDE.md §11）。\n-- すべてのテーブルに RLS を有効化し、最低1つのポリシーを付ける（CLAUDE.md §1-4、scripts/check-rls.mjs で検査）。\n--\n-- 実行主体のロール:\n--   anon          … ストアフロント（セッションなし）。published なものだけ SELECT。\n--   authenticated … 管理画面（owner の JWT）。自分の shop 配下だけ CRUD。\n--   service_role  … src/db/privileged.ts からのみ。在庫 RPC・注文確定・Webhook。\n\ncreate extension if not exists \"pgcrypto\";\n\n-- ---------- バージョン追跡（Step 7 の未適用マイグレーション検出に使う） ----------\n-- 各マイグレーションは末尾で自分の version を insert する。\ncreate table banto_migrations (\n  version text primary key,\n  applied_at timestamptz not null default now()\n);\n\n-- ---------- owner / shop ----------\ncreate table owners (\n  id uuid primary key references auth.users(id) on delete cascade,\n  created_at timestamptz not null default now()\n);\n\ncreate table shops (\n  id uuid primary key default gen_random_uuid(),\n  owner_id uuid not null references owners(id) on delete cascade,\n  slug text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{0,62}$'),\n  name text not null check (length(name) between 1 and 200),\n  published boolean not null default false,\n  -- 公開前チェック用（特商法表記・プライバシーポリシー・返品ポリシー）。\n  -- 未入力のあいだは公開できない（CLAUDE.md §9）。アプリ層だけでなく DB でも保証する。\n  legal_notice text,\n  privacy_policy text,\n  return_policy text,\n  stripe_account_id text,          -- Stripe Connect の接続済みアカウント ID のみ保持（シークレットは持たない）\n  settings jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint shops_publish_requires_legal check (\n    not published or (\n      nullif(btrim(legal_notice), '') is not null\n      and nullif(btrim(privacy_policy), '') is not null\n      and nullif(btrim(return_policy), '') is not null\n    )\n  )\n);\ncreate index on shops(owner_id);\n\n-- ---------- 商品 / SKU / 在庫 ----------\ncreate table products (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  slug text not null check (slug ~ '^[a-z0-9][a-z0-9-]{0,62}$'),\n  name text not null check (length(name) between 1 and 200),\n  description text,\n  published boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (shop_id, slug)\n);\ncreate index on products(shop_id);\n\ncreate table skus (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  product_id uuid not null references products(id) on delete cascade,\n  code text not null check (length(code) between 1 and 100),\n  name text,\n  price_jpy integer not null check (price_jpy >= 0),\n  created_at timestamptz not null default now(),\n  unique (shop_id, code)\n);\ncreate index on skus(product_id);\n\n-- 在庫の正はこの1行のみ（CLAUDE.md §6）。商品テーブルに在庫数を複製しない。\n-- 行は skus への insert 時にトリガーで自動生成する（available = 0）。\ncreate table inventory (\n  sku_id uuid primary key references skus(id) on delete cascade,\n  shop_id uuid not null references shops(id) on delete cascade,\n  available integer not null default 0 check (available >= 0),\n  updated_at timestamptz not null default now()\n);\ncreate index on inventory(shop_id);\n\ncreate table product_images (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  product_id uuid not null references products(id) on delete cascade,\n  storage_key text not null,      -- StorageAdapter のキー。URL は MEDIA_BASE_URL + key\n  sort_order integer not null default 0,\n  created_at timestamptz not null default now()\n);\ncreate index on product_images(product_id, sort_order);\n\n-- ---------- 予約 / 注文 ----------\ncreate type reservation_status as enum ('pending', 'confirmed', 'released');\ncreate table reservations (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  status reservation_status not null default 'pending',\n  items jsonb not null,            -- [{sku_id, qty, unit_price_jpy}] 予約時点の価格スナップショット\n  expires_at timestamptz not null,\n  created_at timestamptz not null default now()\n);\ncreate index on reservations(shop_id, status, expires_at);\n\ncreate type order_status as enum ('paid', 'shipped', 'cancelled', 'refunded');\ncreate table orders (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  reservation_id uuid references reservations(id),\n  status order_status not null default 'paid',\n  total_jpy integer not null check (total_jpy >= 0),\n  -- 個人情報。発送完了から一定期間後に mask_shipped_orders() でマスキング（CLAUDE.md §8）\n  customer_email text,\n  customer_name text,\n  shipping_address jsonb,\n  payment_provider text,           -- 'stripe' | 'komoju'\n  payment_ref text,                -- 決済事業者側の ID\n  shipped_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on orders(shop_id, created_at desc);\n-- 1予約 = 1注文（confirm_reservation の冪等性を DB でも保証する）\ncreate unique index orders_reservation_unique on orders(reservation_id) where reservation_id is not null;\n\ncreate table order_items (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  order_id uuid not null references orders(id) on delete cascade,\n  sku_id uuid not null references skus(id),\n  qty integer not null check (qty > 0),\n  unit_price_jpy integer not null check (unit_price_jpy >= 0)\n);\ncreate index on order_items(order_id);\n\n-- Webhook 冪等化（provider + event_id が主キー）\ncreate table webhook_events (\n  provider text not null,\n  event_id text not null,\n  received_at timestamptz not null default now(),\n  primary key (provider, event_id)\n);\n\n-- ---------- トリガー ----------\ncreate or replace function banto_set_updated_at()\nreturns trigger language plpgsql as $$\nbegin\n  new.updated_at := now();\n  return new;\nend;\n$$;\ncreate trigger shops_updated_at before update on shops for each row execute function banto_set_updated_at();\ncreate trigger products_updated_at before update on products for each row execute function banto_set_updated_at();\ncreate trigger orders_updated_at before update on orders for each row execute function banto_set_updated_at();\n\n-- SKU を作ったら在庫行を必ず持たせる。owner は inventory に直接 INSERT できないため security definer。\ncreate or replace function banto_init_inventory()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  insert into inventory (sku_id, shop_id) values (new.id, new.shop_id);\n  return new;\nend;\n$$;\ncreate trigger skus_init_inventory after insert on skus for each row execute function banto_init_inventory();\n\n-- ---------- RLS ----------\nalter table banto_migrations enable row level security;\nalter table owners enable row level security;\nalter table shops enable row level security;\nalter table products enable row level security;\nalter table skus enable row level security;\nalter table inventory enable row level security;\nalter table product_images enable row level security;\nalter table reservations enable row level security;\nalter table orders enable row level security;\nalter table order_items enable row level security;\nalter table webhook_events enable row level security;\n\n-- 「この shop は自分のものか」。ポリシーの共通部品。\ncreate or replace function banto_owns_shop(p_shop_id uuid)\nreturns boolean language sql stable security definer set search_path = public as $$\n  select exists (select 1 from shops s where s.id = p_shop_id and s.owner_id = auth.uid());\n$$;\n\n-- owner の自己登録は「まだ owner がいない」ときだけ許可する（乗っ取り防止）。\n-- 1デプロイ = 1運営者（CLAUDE.md §3）。将来スタッフを増やすときは招待制の別経路を足す。\ncreate or replace function banto_owner_signup_allowed()\nreturns boolean language sql stable security definer set search_path = public as $$\n  select not exists (select 1 from owners);\n$$;\n\n-- banto_migrations: owner は閲覧のみ（アップデート画面で使う）\ncreate policy migrations_owner_select on banto_migrations for select\n  using (auth.uid() is not null and exists (select 1 from owners o where o.id = auth.uid()));\n\n-- owners: 自分自身のみ。insert は上記ゲート付き。\ncreate policy owners_self_select on owners for select using (id = auth.uid());\ncreate policy owners_self_insert on owners for insert with check (id = auth.uid() and banto_owner_signup_allowed());\ncreate policy owners_self_delete on owners for delete using (id = auth.uid());\n\n-- shops: owner はフル、匿名は published のみ閲覧\ncreate policy shops_owner on shops for all\n  using (owner_id = auth.uid()) with check (owner_id = auth.uid());\ncreate policy shops_public on shops for select using (published = true);\n\n-- shop 配下のテーブル共通: owner はフル、匿名は shop と行が published のとき閲覧\ncreate policy products_owner on products for all\n  using (banto_owns_shop(shop_id)) with check (banto_owns_shop(shop_id));\ncreate policy products_public on products for select\n  using (published = true and exists (select 1 from shops s where s.id = products.shop_id and s.published = true));\n\ncreate policy skus_owner on skus for all\n  using (banto_owns_shop(shop_id)) with check (banto_owns_shop(shop_id));\ncreate policy skus_public on skus for select\n  using (exists (select 1 from products p join shops s on s.id = p.shop_id\n                 where p.id = skus.product_id and p.published and s.published));\n\n-- inventory: 閲覧のみ。変更は RPC（set_stock / reserve_stock / release）経由だけ。\ncreate policy inventory_owner on inventory for select using (banto_owns_shop(shop_id));\ncreate policy inventory_public on inventory for select\n  using (exists (select 1 from skus k join products p on p.id = k.product_id join shops s on s.id = p.shop_id\n                 where k.id = inventory.sku_id and p.published and s.published));\n\ncreate policy images_owner on product_images for all\n  using (banto_owns_shop(shop_id)) with check (banto_owns_shop(shop_id));\ncreate policy images_public on product_images for select\n  using (exists (select 1 from products p join shops s on s.id = p.shop_id\n                 where p.id = product_images.product_id and p.published and s.published));\n\n-- orders: owner は閲覧と更新（発送済み・キャンセル等）。作成は confirm_reservation（service_role）のみ。\ncreate policy orders_owner_select on orders for select using (banto_owns_shop(shop_id));\ncreate policy orders_owner_update on orders for update\n  using (banto_owns_shop(shop_id)) with check (banto_owns_shop(shop_id));\ncreate policy order_items_owner on order_items for select using (banto_owns_shop(shop_id));\ncreate policy reservations_owner on reservations for select using (banto_owns_shop(shop_id));\n\n-- webhook_events は service_role 専用。anon/authenticated からは見えない。\ncreate policy webhook_events_none on webhook_events for select using (false);\n\n-- ---------- 在庫 RPC（service_role 専用、CLAUDE.md §6）----------\n-- p_items: [{\"sku_id\": uuid, \"qty\": int}, ...]\n-- 条件付き UPDATE（available >= qty）で原子的に減算し、1行でも失敗したら例外で全体ロールバック。\n-- 戻り値: reservation id。items には予約時点の単価スナップショットを保存する。\ncreate or replace function reserve_stock(p_shop_id uuid, p_items jsonb, p_ttl_seconds integer default 900)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_item jsonb;\n  v_sku_id uuid;\n  v_qty integer;\n  v_price integer;\n  v_updated integer;\n  v_items jsonb := '[]'::jsonb;\n  v_reservation_id uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'reserve_stock: service_role only' using errcode = '42501';\n  end if;\n  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then\n    raise exception 'empty_items';\n  end if;\n  if p_ttl_seconds is null or p_ttl_seconds <= 0 then\n    raise exception 'invalid_ttl';\n  end if;\n\n  -- sku_id 順に処理し、複数予約が同じ SKU 群を逆順でロックしてデッドロックするのを防ぐ\n  for v_item in select e from jsonb_array_elements(p_items) e order by e->>'sku_id' loop\n    v_sku_id := (v_item->>'sku_id')::uuid;\n    v_qty := (v_item->>'qty')::integer;\n    if v_sku_id is null or v_qty is null or v_qty <= 0 then\n      raise exception 'invalid_item' using detail = coalesce(v_item::text, 'null');\n    end if;\n\n    -- SKU が shop に属し、商品と shop が公開中であること\n    select k.price_jpy into v_price\n      from skus k\n      join products p on p.id = k.product_id\n      join shops s on s.id = k.shop_id\n     where k.id = v_sku_id and k.shop_id = p_shop_id and p.published and s.published;\n    if not found then\n      raise exception 'sku_not_available' using detail = v_sku_id::text;\n    end if;\n\n    update inventory\n       set available = available - v_qty, updated_at = now()\n     where sku_id = v_sku_id and shop_id = p_shop_id and available >= v_qty;\n    get diagnostics v_updated = row_count;\n    if v_updated = 0 then\n      raise exception 'insufficient_stock' using detail = v_sku_id::text;\n    end if;\n\n    v_items := v_items || jsonb_build_object('sku_id', v_sku_id, 'qty', v_qty, 'unit_price_jpy', v_price);\n  end loop;\n\n  insert into reservations (shop_id, items, expires_at)\n  values (p_shop_id, v_items, now() + make_interval(secs => p_ttl_seconds))\n  returning id into v_reservation_id;\n\n  return v_reservation_id;\nend;\n$$;\n\n-- 決済 Webhook 受信時に予約を確定注文へ変換する。同じ reservation_id に対して冪等（同じ order id を返す）。\n-- p_order: {\"customer_email\", \"customer_name\", \"shipping_address\": {...}, \"payment_provider\", \"payment_ref\"}\n-- 予約が TTL 切れで released 済みなら同じ品目で再度在庫を引き、足りなければ例外（呼び出し側で返金する）。\ncreate or replace function confirm_reservation(p_reservation_id uuid, p_shop_id uuid, p_order jsonb default '{}'::jsonb)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res reservations%rowtype;\n  v_order_id uuid;\n  v_item jsonb;\n  v_updated integer;\n  v_total integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'confirm_reservation: service_role only' using errcode = '42501';\n  end if;\n\n  select * into v_res from reservations\n   where id = p_reservation_id and shop_id = p_shop_id\n   for update;\n  if not found then\n    raise exception 'reservation_not_found' using detail = p_reservation_id::text;\n  end if;\n\n  -- 冪等: すでに注文があればそれを返す\n  select id into v_order_id from orders where reservation_id = p_reservation_id;\n  if found then\n    return v_order_id;\n  end if;\n\n  if v_res.status = 'released' then\n    for v_item in select e from jsonb_array_elements(v_res.items) e order by e->>'sku_id' loop\n      update inventory\n         set available = available - (v_item->>'qty')::integer, updated_at = now()\n       where sku_id = (v_item->>'sku_id')::uuid and shop_id = p_shop_id\n         and available >= (v_item->>'qty')::integer;\n      get diagnostics v_updated = row_count;\n      if v_updated = 0 then\n        raise exception 'insufficient_stock_after_release' using detail = v_item->>'sku_id';\n      end if;\n    end loop;\n  end if;\n\n  select coalesce(sum((e->>'qty')::integer * (e->>'unit_price_jpy')::integer), 0)\n    into v_total\n    from jsonb_array_elements(v_res.items) e;\n\n  insert into orders (shop_id, reservation_id, status, total_jpy,\n                      customer_email, customer_name, shipping_address, payment_provider, payment_ref)\n  values (p_shop_id, p_reservation_id, 'paid', v_total,\n          p_order->>'customer_email', p_order->>'customer_name', p_order->'shipping_address',\n          p_order->>'payment_provider', p_order->>'payment_ref')\n  returning id into v_order_id;\n\n  insert into order_items (shop_id, order_id, sku_id, qty, unit_price_jpy)\n  select p_shop_id, v_order_id, (e->>'sku_id')::uuid, (e->>'qty')::integer, (e->>'unit_price_jpy')::integer\n    from jsonb_array_elements(v_res.items) e;\n\n  update reservations set status = 'confirmed' where id = p_reservation_id;\n\n  return v_order_id;\nend;\n$$;\n\n-- TTL 超過の未確定予約を在庫に戻す。Cron（SchedulerAdapter）から呼ぶ。戻り値は解放した予約数。\ncreate or replace function release_expired_reservations()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res record;\n  v_item jsonb;\n  v_count integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'release_expired_reservations: service_role only' using errcode = '42501';\n  end if;\n  for v_res in\n    select id, shop_id, items from reservations\n     where status = 'pending' and expires_at < now()\n     for update skip locked\n  loop\n    for v_item in select e from jsonb_array_elements(v_res.items) e order by e->>'sku_id' loop\n      update inventory set available = available + (v_item->>'qty')::integer, updated_at = now()\n       where sku_id = (v_item->>'sku_id')::uuid and shop_id = v_res.shop_id;\n    end loop;\n    update reservations set status = 'released' where id = v_res.id;\n    v_count := v_count + 1;\n  end loop;\n  return v_count;\nend;\n$$;\n\n-- 特定の予約を明示的に解放する（決済セッションの期限切れ・キャンセル Webhook から呼ぶ）。\n-- pending のときだけ在庫を戻す。confirmed / released なら何もしない（冪等）。戻り値: 解放したら true。\ncreate or replace function release_reservation(p_reservation_id uuid, p_shop_id uuid)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res reservations%rowtype;\n  v_item jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'release_reservation: service_role only' using errcode = '42501';\n  end if;\n  select * into v_res from reservations\n   where id = p_reservation_id and shop_id = p_shop_id\n   for update;\n  if not found or v_res.status <> 'pending' then\n    return false;\n  end if;\n  for v_item in select e from jsonb_array_elements(v_res.items) e order by e->>'sku_id' loop\n    update inventory set available = available + (v_item->>'qty')::integer, updated_at = now()\n     where sku_id = (v_item->>'sku_id')::uuid and shop_id = p_shop_id;\n  end loop;\n  update reservations set status = 'released' where id = p_reservation_id;\n  return true;\nend;\n$$;\n\n-- Webhook の冪等化。初見なら true、すでに処理済みなら false。\ncreate or replace function record_webhook_event(p_provider text, p_event_id text)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'record_webhook_event: service_role only' using errcode = '42501';\n  end if;\n  insert into webhook_events (provider, event_id) values (p_provider, p_event_id)\n  on conflict do nothing;\n  return found;\nend;\n$$;\n\n-- ---------- owner 用 RPC（authenticated、関数内で所有を検証） ----------\n-- 在庫数を直接セットする（入荷・棚卸し）。減算の経路は reserve_stock に一本化するため、\n-- owner にも inventory の UPDATE 権限は与えず、この関数だけを許す。\ncreate or replace function set_stock(p_sku_id uuid, p_available integer)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_shop_id uuid;\nbegin\n  if p_available is null or p_available < 0 then\n    raise exception 'invalid_available';\n  end if;\n  select shop_id into v_shop_id from skus where id = p_sku_id;\n  if not found or not banto_owns_shop(v_shop_id) then\n    raise exception 'sku_not_found' using errcode = '42501';\n  end if;\n  update inventory set available = p_available, updated_at = now() where sku_id = p_sku_id;\n  return p_available;\nend;\n$$;\n\n-- 顧客単位の削除依頼への対応（CLAUDE.md §8）。該当メールの注文の個人情報をマスキングする。\ncreate or replace function mask_customer(p_shop_id uuid, p_email text)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_count integer;\nbegin\n  if not banto_owns_shop(p_shop_id) then\n    raise exception 'shop_not_found' using errcode = '42501';\n  end if;\n  update orders\n     set customer_email = null, customer_name = '[masked]', shipping_address = null\n   where shop_id = p_shop_id and lower(customer_email) = lower(p_email);\n  get diagnostics v_count = row_count;\n  return v_count;\nend;\n$$;\n\n-- ---------- セットアップ状態（ウィザード用、anon から呼べる） ----------\n-- owner の有無・shop 数・適用済みマイグレーションだけを返す。個人情報や設定値は含めない。\ncreate or replace function banto_setup_state()\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'has_owner', exists (select 1 from owners),\n    'shop_count', (select count(*) from shops),\n    'migrations', (select coalesce(jsonb_agg(version order by version), '[]'::jsonb) from banto_migrations)\n  );\n$$;\n\n-- ---------- 個人情報の自動マスキング（CLAUDE.md §8、Cron から service_role で呼ぶ）----------\ncreate or replace function mask_shipped_orders(p_days integer default 180)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_count integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'mask_shipped_orders: service_role only' using errcode = '42501';\n  end if;\n  update orders\n     set customer_email = null, customer_name = '[masked]', shipping_address = null\n   where status = 'shipped' and shipped_at < now() - make_interval(days => p_days)\n     and (customer_name is distinct from '[masked]' or customer_email is not null or shipping_address is not null);\n  get diagnostics v_count = row_count;\n  return v_count;\nend;\n$$;\n\n-- ---------- 実行権限 ----------\n-- PostgreSQL は関数の EXECUTE を既定で PUBLIC に与えるため、public からも剥奪する。\nrevoke execute on function reserve_stock(uuid, jsonb, integer) from public, anon, authenticated;\nrevoke execute on function confirm_reservation(uuid, uuid, jsonb) from public, anon, authenticated;\nrevoke execute on function release_expired_reservations() from public, anon, authenticated;\nrevoke execute on function release_reservation(uuid, uuid) from public, anon, authenticated;\nrevoke execute on function record_webhook_event(text, text) from public, anon, authenticated;\nrevoke execute on function mask_shipped_orders(integer) from public, anon, authenticated;\ngrant execute on function reserve_stock(uuid, jsonb, integer) to service_role;\ngrant execute on function confirm_reservation(uuid, uuid, jsonb) to service_role;\ngrant execute on function release_expired_reservations() to service_role;\ngrant execute on function release_reservation(uuid, uuid) to service_role;\ngrant execute on function record_webhook_event(text, text) to service_role;\ngrant execute on function mask_shipped_orders(integer) to service_role;\n\nrevoke execute on function set_stock(uuid, integer) from public, anon;\nrevoke execute on function mask_customer(uuid, text) from public, anon;\ngrant execute on function set_stock(uuid, integer) to authenticated, service_role;\ngrant execute on function mask_customer(uuid, text) to authenticated, service_role;\n\n-- ポリシー内から呼ぶヘルパーは anon/authenticated にも実行を許す（security definer なので中身は見えない）\ngrant execute on function banto_owns_shop(uuid) to anon, authenticated, service_role;\ngrant execute on function banto_owner_signup_allowed() to anon, authenticated, service_role;\ngrant execute on function banto_setup_state() to anon, authenticated, service_role;\n\n-- トリガー関数・内部関数は直接呼ばせない\nrevoke execute on function banto_init_inventory() from public, anon, authenticated;\nrevoke execute on function banto_set_updated_at() from public, anon, authenticated;\n\ninsert into banto_migrations (version) values ('0001_init');\n" },
  { version: "0002_hooks", sql: "-- Banto 0002_hooks: hooks（署名付き Webhook 送信）と外部プラグインの登録先\n-- CLAUDE.md §5: order.created order.paid order.shipped order.cancelled customer.created product.updated inventory.low\n-- 失敗時は指数バックオフで最大5回再送。配信は Cron（SchedulerAdapter）から service_role で行う。\n\n-- ---------- 送信先（外部プラグイン / 任意の URL） ----------\ncreate table hook_endpoints (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  name text not null check (length(name) between 1 and 200),\n  url text not null check (url ~ '^https?://'),\n  -- 購読するイベント名。空なら何も受け取らない\n  events text[] not null default '{}',\n  enabled boolean not null default true,\n  -- 外部プラグインが返したマニフェスト（JSON）。シークレットは入れない（CLAUDE.md §1-5）\n  manifest jsonb,\n  -- マニフェストで宣言された設定項目の値。シークレット型は持たない\n  settings jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on hook_endpoints(shop_id);\ncreate trigger hook_endpoints_updated_at before update on hook_endpoints for each row execute function banto_set_updated_at();\n\n-- ---------- 配信キュー ----------\ncreate type hook_delivery_status as enum ('pending', 'delivered', 'failed');\ncreate table hook_deliveries (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  endpoint_id uuid not null references hook_endpoints(id) on delete cascade,\n  event text not null,\n  payload jsonb not null,\n  status hook_delivery_status not null default 'pending',\n  attempts integer not null default 0,\n  next_attempt_at timestamptz not null default now(),\n  last_status integer,\n  last_error text,\n  created_at timestamptz not null default now(),\n  delivered_at timestamptz\n);\ncreate index on hook_deliveries(status, next_attempt_at);\ncreate index on hook_deliveries(shop_id, created_at desc);\n\n-- ---------- RLS ----------\nalter table hook_endpoints enable row level security;\nalter table hook_deliveries enable row level security;\n\ncreate policy hook_endpoints_owner on hook_endpoints for all\n  using (banto_owns_shop(shop_id)) with check (banto_owns_shop(shop_id));\n-- 配信履歴は owner が閲覧のみ。作成は enqueue_hook、更新は Cron（service_role）。\ncreate policy hook_deliveries_owner_select on hook_deliveries for select using (banto_owns_shop(shop_id));\n\n-- ---------- RPC ----------\n-- イベントをキューに積む。shop の有効な送信先のうち、そのイベントを購読するものごとに1行。\n-- owner（authenticated、所有を検証）と service_role（DB 内の確定処理）から呼ぶ。戻り値: 積んだ件数。\ncreate or replace function enqueue_hook(p_shop_id uuid, p_event text, p_payload jsonb)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_count integer;\nbegin\n  if auth.role() is distinct from 'service_role' and not banto_owns_shop(p_shop_id) then\n    raise exception 'shop_not_found' using errcode = '42501';\n  end if;\n  if p_event is null or p_event !~ '^[a-z_]+\\.[a-z_]+$' then\n    raise exception 'invalid_event';\n  end if;\n  insert into hook_deliveries (shop_id, endpoint_id, event, payload)\n  select e.shop_id, e.id, p_event, coalesce(p_payload, '{}'::jsonb)\n    from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and p_event = any(e.events);\n  get diagnostics v_count = row_count;\n  return v_count;\nend;\n$$;\n\n-- 配信待ちを取り出す（Cron、service_role）。取り出した行は attempts を進め、10 分のリースを張って二重配信を防ぐ。\ncreate or replace function claim_hook_deliveries(p_limit integer default 50)\nreturns table (\n  id uuid, shop_id uuid, endpoint_id uuid, event text, payload jsonb, attempts integer,\n  url text, settings jsonb, created_at timestamptz\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'claim_hook_deliveries: service_role only' using errcode = '42501';\n  end if;\n  return query\n  with picked as (\n    select d.id from hook_deliveries d\n      join hook_endpoints e on e.id = d.endpoint_id\n     where d.status = 'pending' and d.next_attempt_at <= now() and e.enabled\n     order by d.next_attempt_at\n     limit greatest(1, least(p_limit, 500))\n     for update of d skip locked\n  ),\n  leased as (\n    update hook_deliveries d\n       set attempts = d.attempts + 1, next_attempt_at = now() + interval '10 minutes'\n      from picked\n     where d.id = picked.id\n    returning d.id, d.shop_id, d.endpoint_id, d.event, d.payload, d.attempts, d.created_at\n  )\n  select l.id, l.shop_id, l.endpoint_id, l.event, l.payload, l.attempts, e.url, e.settings, l.created_at\n    from leased l join hook_endpoints e on e.id = l.endpoint_id;\nend;\n$$;\n\n-- 配信結果を記録する。失敗は 2^attempts 分後に再送、5回失敗で failed（CLAUDE.md §5）。\ncreate or replace function finish_hook_delivery(p_id uuid, p_success boolean, p_status integer, p_error text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_attempts integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'finish_hook_delivery: service_role only' using errcode = '42501';\n  end if;\n  select attempts into v_attempts from hook_deliveries where id = p_id;\n  if not found then return; end if;\n  if p_success then\n    update hook_deliveries\n       set status = 'delivered', delivered_at = now(), last_status = p_status, last_error = null\n     where id = p_id;\n  elsif v_attempts >= 5 then\n    update hook_deliveries\n       set status = 'failed', last_status = p_status, last_error = left(p_error, 1000)\n     where id = p_id;\n  else\n    update hook_deliveries\n       set next_attempt_at = now() + make_interval(mins => power(2, v_attempts)::integer),\n           last_status = p_status, last_error = left(p_error, 1000)\n     where id = p_id;\n  end if;\nend;\n$$;\n\n-- ---------- 予約に購入者情報を一時保持（KOMOJU 等、決済ページが配送先を集めない場合） ----------\n-- 確定時に orders へ移して null にする。解放時も null にする（個人情報を残さない、CLAUDE.md §8）。\nalter table reservations add column customer jsonb;\n\ncreate or replace function attach_reservation_customer(p_reservation_id uuid, p_shop_id uuid, p_customer jsonb)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'attach_reservation_customer: service_role only' using errcode = '42501';\n  end if;\n  update reservations set customer = p_customer\n   where id = p_reservation_id and shop_id = p_shop_id and status = 'pending';\n  if not found then\n    raise exception 'reservation_not_found' using detail = p_reservation_id::text;\n  end if;\nend;\n$$;\n\n-- 解放時に購入者情報を消す（release_reservation / release_expired_reservations を差し替え）\ncreate or replace function release_reservation(p_reservation_id uuid, p_shop_id uuid)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res reservations%rowtype;\n  v_item jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'release_reservation: service_role only' using errcode = '42501';\n  end if;\n  select * into v_res from reservations\n   where id = p_reservation_id and shop_id = p_shop_id\n   for update;\n  if not found or v_res.status <> 'pending' then\n    return false;\n  end if;\n  for v_item in select e from jsonb_array_elements(v_res.items) e order by e->>'sku_id' loop\n    update inventory set available = available + (v_item->>'qty')::integer, updated_at = now()\n     where sku_id = (v_item->>'sku_id')::uuid and shop_id = p_shop_id;\n  end loop;\n  update reservations set status = 'released', customer = null where id = p_reservation_id;\n  return true;\nend;\n$$;\n\ncreate or replace function release_expired_reservations()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res record;\n  v_item jsonb;\n  v_count integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'release_expired_reservations: service_role only' using errcode = '42501';\n  end if;\n  for v_res in\n    select id, shop_id, items from reservations\n     where status = 'pending' and expires_at < now()\n     for update skip locked\n  loop\n    for v_item in select e from jsonb_array_elements(v_res.items) e order by e->>'sku_id' loop\n      update inventory set available = available + (v_item->>'qty')::integer, updated_at = now()\n       where sku_id = (v_item->>'sku_id')::uuid and shop_id = v_res.shop_id;\n    end loop;\n    update reservations set status = 'released', customer = null where id = v_res.id;\n    v_count := v_count + 1;\n  end loop;\n  return v_count;\nend;\n$$;\n\n-- ---------- ストアフロント用: 有効な同梱決済プラグインとその設定（シークレットは含まない） ----------\ncreate or replace function shop_payment_options(p_shop_id uuid)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce(jsonb_agg(jsonb_build_object(\n           'id', substr(e.url, length('https://banto.invalid/plugins/') + 1),\n           'settings', e.settings)), '[]'::jsonb)\n    from hook_endpoints e\n    join shops s on s.id = e.shop_id\n   where e.shop_id = p_shop_id and e.enabled and s.published\n     and e.url like 'https://banto.invalid/plugins/%';\n$$;\n\n-- 注文確定時に DB 内から order.created / order.paid / inventory.low を積む（confirm_reservation を差し替え）\ncreate or replace function confirm_reservation(p_reservation_id uuid, p_shop_id uuid, p_order jsonb default '{}'::jsonb)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res reservations%rowtype;\n  v_order_id uuid;\n  v_item jsonb;\n  v_updated integer;\n  v_total integer;\n  v_threshold integer;\n  v_available integer;\n  v_payload jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'confirm_reservation: service_role only' using errcode = '42501';\n  end if;\n\n  select * into v_res from reservations\n   where id = p_reservation_id and shop_id = p_shop_id\n   for update;\n  if not found then\n    raise exception 'reservation_not_found' using detail = p_reservation_id::text;\n  end if;\n\n  select id into v_order_id from orders where reservation_id = p_reservation_id;\n  if found then\n    return v_order_id;\n  end if;\n\n  if v_res.status = 'released' then\n    for v_item in select e from jsonb_array_elements(v_res.items) e order by e->>'sku_id' loop\n      update inventory\n         set available = available - (v_item->>'qty')::integer, updated_at = now()\n       where sku_id = (v_item->>'sku_id')::uuid and shop_id = p_shop_id\n         and available >= (v_item->>'qty')::integer;\n      get diagnostics v_updated = row_count;\n      if v_updated = 0 then\n        raise exception 'insufficient_stock_after_release' using detail = v_item->>'sku_id';\n      end if;\n    end loop;\n  end if;\n\n  select coalesce(sum((e->>'qty')::integer * (e->>'unit_price_jpy')::integer), 0)\n    into v_total\n    from jsonb_array_elements(v_res.items) e;\n\n  insert into orders (shop_id, reservation_id, status, total_jpy,\n                      customer_email, customer_name, shipping_address, payment_provider, payment_ref)\n  values (p_shop_id, p_reservation_id, 'paid', v_total,\n          coalesce(p_order->>'customer_email', v_res.customer->>'customer_email'),\n          coalesce(p_order->>'customer_name', v_res.customer->>'customer_name'),\n          coalesce(p_order->'shipping_address', v_res.customer->'shipping_address'),\n          p_order->>'payment_provider', p_order->>'payment_ref')\n  returning id into v_order_id;\n\n  insert into order_items (shop_id, order_id, sku_id, qty, unit_price_jpy)\n  select p_shop_id, v_order_id, (e->>'sku_id')::uuid, (e->>'qty')::integer, (e->>'unit_price_jpy')::integer\n    from jsonb_array_elements(v_res.items) e;\n\n  update reservations set status = 'confirmed', customer = null where id = p_reservation_id;\n\n  -- hooks: 注文（個人情報は含めない。必要ならプラグインがヘッドレス API で取る）\n  v_payload := jsonb_build_object(\n    'order_id', v_order_id, 'shop_id', p_shop_id, 'total_jpy', v_total, 'status', 'paid',\n    'payment_provider', p_order->>'payment_provider',\n    'items', v_res.items\n  );\n  perform enqueue_hook(p_shop_id, 'order.created', v_payload);\n  perform enqueue_hook(p_shop_id, 'order.paid', v_payload);\n\n  -- hooks: 在庫僅少（shops.settings.low_stock_threshold、既定 3）\n  select coalesce((s.settings->>'low_stock_threshold')::integer, 3) into v_threshold from shops s where s.id = p_shop_id;\n  for v_item in select e from jsonb_array_elements(v_res.items) e loop\n    select available into v_available from inventory where sku_id = (v_item->>'sku_id')::uuid;\n    if v_available is not null and v_available <= v_threshold then\n      perform enqueue_hook(p_shop_id, 'inventory.low',\n        jsonb_build_object('shop_id', p_shop_id, 'sku_id', v_item->>'sku_id', 'available', v_available, 'threshold', v_threshold));\n    end if;\n  end loop;\n\n  return v_order_id;\nend;\n$$;\n\n-- ---------- 実行権限 ----------\nrevoke execute on function enqueue_hook(uuid, text, jsonb) from public, anon;\ngrant execute on function enqueue_hook(uuid, text, jsonb) to authenticated, service_role;\nrevoke execute on function claim_hook_deliveries(integer) from public, anon, authenticated;\nrevoke execute on function finish_hook_delivery(uuid, boolean, integer, text) from public, anon, authenticated;\ngrant execute on function claim_hook_deliveries(integer) to service_role;\ngrant execute on function finish_hook_delivery(uuid, boolean, integer, text) to service_role;\nrevoke execute on function attach_reservation_customer(uuid, uuid, jsonb) from public, anon, authenticated;\ngrant execute on function attach_reservation_customer(uuid, uuid, jsonb) to service_role;\nrevoke execute on function release_reservation(uuid, uuid) from public, anon, authenticated;\ngrant execute on function release_reservation(uuid, uuid) to service_role;\nrevoke execute on function release_expired_reservations() from public, anon, authenticated;\ngrant execute on function release_expired_reservations() to service_role;\ngrant execute on function shop_payment_options(uuid) to anon, authenticated, service_role;\nrevoke execute on function confirm_reservation(uuid, uuid, jsonb) from public, anon, authenticated;\ngrant execute on function confirm_reservation(uuid, uuid, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0002_hooks');\n" },
  { version: "0003_api", sql: "-- Banto 0003_api: AI 用トークン（MCP / REST）と api_* RPC、売上集計\n-- 設計と脅威モデルは docs/ai-access.md。すべての api_* は api_require() でトークン・期限・失効・スコープを検証し、\n-- トークンに紐づく shop_id だけを対象にする（CLAUDE.md §3: service_role 経路は RPC 内で shop_id を検証）。\n\n-- ---------- トークン ----------\ncreate table api_tokens (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  owner_id uuid not null references owners(id) on delete cascade,\n  name text not null check (length(name) between 1 and 100),\n  -- SHA-256(hex) のみ保存。生のトークンは発行時に一度だけ表示する\n  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),\n  prefix text not null check (length(prefix) between 4 and 16),\n  scopes text[] not null default '{}',\n  expires_at timestamptz,\n  revoked_at timestamptz,\n  last_used_at timestamptz,\n  created_at timestamptz not null default now(),\n  constraint api_tokens_scopes_valid check (\n    scopes <@ array['products:read','products:write','orders:read','orders:pii','orders:write','shop:read','shop:write','stats:read']::text[]\n  )\n);\ncreate index on api_tokens(shop_id);\n\nalter table api_tokens enable row level security;\n-- owner はトークンの管理（発行・失効・削除）ができる。ハッシュ列も owner には見えるが、ハッシュから生トークンは作れない。\ncreate policy api_tokens_owner on api_tokens for all\n  using (banto_owns_shop(shop_id)) with check (banto_owns_shop(shop_id) and owner_id = auth.uid());\n\n-- ---------- 検証ヘルパー（内部用） ----------\n-- トークンを検証し、行を返す。失敗はすべて同じメッセージ（存在・失効・期限・スコープを区別させない）。\ncreate or replace function api_require(p_token_hash text, p_scope text)\nreturns api_tokens\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'api_require: service_role only' using errcode = '42501';\n  end if;\n  select * into v_tok from api_tokens\n   where token_hash = p_token_hash\n     and revoked_at is null\n     and (expires_at is null or expires_at > now());\n  if not found or not (p_scope = any(v_tok.scopes)) then\n    raise exception 'unauthorized' using errcode = '42501';\n  end if;\n  -- 最終利用は1分に1回だけ更新（書き込みを減らす）\n  if v_tok.last_used_at is null or v_tok.last_used_at < now() - interval '1 minute' then\n    update api_tokens set last_used_at = now() where id = v_tok.id;\n  end if;\n  return v_tok;\nend;\n$$;\n\ncreate or replace function api_has_scope(p_token_hash text, p_scope text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select exists (\n    select 1 from api_tokens\n     where token_hash = p_token_hash and revoked_at is null and (expires_at is null or expires_at > now())\n       and p_scope = any(scopes)\n  );\n$$;\n\n-- トークンが有効なら、紐づく shop_id だけを返す（スコープ不問。画像の保存先キーの組み立てに使う）\ncreate or replace function api_token_shop(p_token_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'api_token_shop: service_role only' using errcode = '42501';\n  end if;\n  select * into v_tok from api_tokens\n   where token_hash = p_token_hash and revoked_at is null and (expires_at is null or expires_at > now());\n  if not found then raise exception 'unauthorized' using errcode = '42501'; end if;\n  return jsonb_build_object('shop_id', v_tok.shop_id, 'scopes', to_jsonb(v_tok.scopes), 'name', v_tok.name);\nend;\n$$;\n\n-- ---------- 共通の JSON 整形 ----------\ncreate or replace function api_product_json(p_product products, p_with_skus boolean default true)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_product.id, 'slug', p_product.slug, 'name', p_product.name, 'description', p_product.description,\n    'published', p_product.published, 'created_at', p_product.created_at, 'updated_at', p_product.updated_at,\n    'images', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'storage_key', i.storage_key, 'sort_order', i.sort_order) order by i.sort_order), '[]'::jsonb)\n                 from product_images i where i.product_id = p_product.id),\n    'skus', case when p_with_skus then\n      (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'code', k.code, 'name', k.name, 'price_jpy', k.price_jpy,\n                                                     'available', coalesce(inv.available, 0)) order by k.created_at), '[]'::jsonb)\n         from skus k left join inventory inv on inv.sku_id = k.id where k.product_id = p_product.id)\n      else null end\n  );\n$$;\n\ncreate or replace function api_order_json(p_order orders, p_pii boolean)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_order.id, 'status', p_order.status, 'total_jpy', p_order.total_jpy,\n    'payment_provider', p_order.payment_provider, 'payment_ref', p_order.payment_ref,\n    'shipped_at', p_order.shipped_at, 'created_at', p_order.created_at, 'updated_at', p_order.updated_at,\n    'customer', case when p_pii then jsonb_build_object(\n        'email', p_order.customer_email, 'name', p_order.customer_name, 'shipping_address', p_order.shipping_address)\n      else jsonb_build_object('masked', true,\n        'prefecture', p_order.shipping_address->>'state') end,\n    'items', (select coalesce(jsonb_agg(jsonb_build_object(\n                 'sku_id', oi.sku_id, 'sku_code', k.code, 'sku_name', k.name, 'product_id', k.product_id, 'product_name', p.name,\n                 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy) order by oi.id), '[]'::jsonb)\n                from order_items oi\n                left join skus k on k.id = oi.sku_id\n                left join products p on p.id = k.product_id\n               where oi.order_id = p_order.id)\n  );\n$$;\n\n-- ---------- ショップ ----------\ncreate or replace function api_shop_get(p_token_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_shop shops%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'shop:read');\n  select * into v_shop from shops where id = v_tok.shop_id;\n  return jsonb_build_object(\n    'id', v_shop.id, 'slug', v_shop.slug, 'name', v_shop.name, 'published', v_shop.published,\n    'legal_notice', v_shop.legal_notice, 'privacy_policy', v_shop.privacy_policy, 'return_policy', v_shop.return_policy,\n    'low_stock_threshold', coalesce((v_shop.settings->>'low_stock_threshold')::integer, 3),\n    'stripe_connected', v_shop.stripe_account_id is not null,\n    'created_at', v_shop.created_at, 'updated_at', v_shop.updated_at);\nend;\n$$;\n\n-- 更新できる項目だけを受け付ける（settings 全体や stripe_account_id は触らせない）\ncreate or replace function api_shop_update(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_threshold integer;\nbegin\n  v_tok := api_require(p_token_hash, 'shop:write');\n  if p_values ? 'low_stock_threshold' then\n    v_threshold := (p_values->>'low_stock_threshold')::integer;\n    if v_threshold is null or v_threshold < 0 or v_threshold > 100000 then raise exception 'invalid_low_stock_threshold'; end if;\n  end if;\n  update shops set\n    name = coalesce(nullif(btrim(p_values->>'name'), ''), name),\n    legal_notice = case when p_values ? 'legal_notice' then nullif(btrim(p_values->>'legal_notice'), '') else legal_notice end,\n    privacy_policy = case when p_values ? 'privacy_policy' then nullif(btrim(p_values->>'privacy_policy'), '') else privacy_policy end,\n    return_policy = case when p_values ? 'return_policy' then nullif(btrim(p_values->>'return_policy'), '') else return_policy end,\n    published = coalesce((p_values->>'published')::boolean, published),\n    settings = case when v_threshold is not null then settings || jsonb_build_object('low_stock_threshold', v_threshold) else settings end\n  where id = v_tok.shop_id;\n  return api_shop_get(p_token_hash);\nend;\n$$;\n\n-- ---------- 商品 ----------\ncreate or replace function api_products_list(p_token_hash text, p_query text default null, p_published boolean default null,\n                                             p_limit integer default 50, p_offset integer default 0)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_limit integer; v_total integer; v_items jsonb;\nbegin\n  v_tok := api_require(p_token_hash, 'products:read');\n  v_limit := greatest(1, least(coalesce(p_limit, 50), 100));\n  select count(*) into v_total from products p\n   where p.shop_id = v_tok.shop_id\n     and (p_published is null or p.published = p_published)\n     and (p_query is null or p.name ilike '%' || p_query || '%' or p.slug ilike '%' || p_query || '%');\n  select coalesce(jsonb_agg(api_product_json(p, true) order by p.created_at desc), '[]'::jsonb) into v_items\n    from (select * from products p\n           where p.shop_id = v_tok.shop_id\n             and (p_published is null or p.published = p_published)\n             and (p_query is null or p.name ilike '%' || p_query || '%' or p.slug ilike '%' || p_query || '%')\n           order by p.created_at desc\n           limit v_limit offset greatest(0, coalesce(p_offset, 0))) p;\n  return jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', greatest(0, coalesce(p_offset, 0)));\nend;\n$$;\n\ncreate or replace function api_product_get(p_token_hash text, p_product_id uuid default null, p_slug text default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_p products%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'products:read');\n  select * into v_p from products where shop_id = v_tok.shop_id and (id = p_product_id or (p_product_id is null and slug = p_slug));\n  if not found then raise exception 'not_found'; end if;\n  return api_product_json(v_p, true);\nend;\n$$;\n\ncreate or replace function api_product_create(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_p products%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  insert into products (shop_id, slug, name, description, published)\n  values (v_tok.shop_id, p_values->>'slug', p_values->>'name', nullif(btrim(coalesce(p_values->>'description', '')), ''),\n          coalesce((p_values->>'published')::boolean, false))\n  returning * into v_p;\n  perform enqueue_hook(v_tok.shop_id, 'product.updated', jsonb_build_object('product_id', v_p.id, 'shop_id', v_tok.shop_id, 'slug', v_p.slug, 'name', v_p.name, 'published', v_p.published));\n  return api_product_json(v_p, true);\nend;\n$$;\n\ncreate or replace function api_product_update(p_token_hash text, p_product_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_p products%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  update products set\n    slug = coalesce(p_values->>'slug', slug),\n    name = coalesce(nullif(btrim(p_values->>'name'), ''), name),\n    description = case when p_values ? 'description' then nullif(btrim(p_values->>'description'), '') else description end,\n    published = coalesce((p_values->>'published')::boolean, published)\n  where id = p_product_id and shop_id = v_tok.shop_id\n  returning * into v_p;\n  if not found then raise exception 'not_found'; end if;\n  perform enqueue_hook(v_tok.shop_id, 'product.updated', jsonb_build_object('product_id', v_p.id, 'shop_id', v_tok.shop_id, 'slug', v_p.slug, 'name', v_p.name, 'published', v_p.published));\n  return api_product_json(v_p, true);\nend;\n$$;\n\n-- SKU: 作成（在庫の初期値つき）と更新（価格・名前・在庫）。在庫は set_stock と同じく値を直接セットする\ncreate or replace function api_sku_create(p_token_hash text, p_product_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_k skus%rowtype; v_available integer;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  if not exists (select 1 from products where id = p_product_id and shop_id = v_tok.shop_id) then raise exception 'not_found'; end if;\n  insert into skus (shop_id, product_id, code, name, price_jpy)\n  values (v_tok.shop_id, p_product_id, p_values->>'code', nullif(btrim(coalesce(p_values->>'name', '')), ''), (p_values->>'price_jpy')::integer)\n  returning * into v_k;\n  v_available := coalesce((p_values->>'available')::integer, 0);\n  if v_available < 0 then raise exception 'invalid_available'; end if;\n  update inventory set available = v_available, updated_at = now() where sku_id = v_k.id;\n  return api_product_get(p_token_hash, p_product_id);\nend;\n$$;\n\ncreate or replace function api_sku_update(p_token_hash text, p_sku_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_k skus%rowtype; v_available integer;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  update skus set\n    code = coalesce(p_values->>'code', code),\n    name = case when p_values ? 'name' then nullif(btrim(p_values->>'name'), '') else name end,\n    price_jpy = coalesce((p_values->>'price_jpy')::integer, price_jpy)\n  where id = p_sku_id and shop_id = v_tok.shop_id\n  returning * into v_k;\n  if not found then raise exception 'not_found'; end if;\n  if p_values ? 'available' then\n    v_available := (p_values->>'available')::integer;\n    if v_available is null or v_available < 0 then raise exception 'invalid_available'; end if;\n    update inventory set available = v_available, updated_at = now() where sku_id = v_k.id;\n  end if;\n  return api_product_get(p_token_hash, v_k.product_id);\nend;\n$$;\n\ncreate or replace function api_sku_delete(p_token_hash text, p_sku_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_product uuid;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  delete from skus where id = p_sku_id and shop_id = v_tok.shop_id returning product_id into v_product;\n  if not found then raise exception 'not_found'; end if;\n  return api_product_get(p_token_hash, v_product);\nend;\n$$;\n\n-- 画像: Worker がストレージに置いたあと行を登録する / 削除して storage_key を返す（Worker がストレージから消す）\ncreate or replace function api_image_add(p_token_hash text, p_product_id uuid, p_storage_key text, p_sort_order integer default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_sort integer;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  if not exists (select 1 from products where id = p_product_id and shop_id = v_tok.shop_id) then raise exception 'not_found'; end if;\n  if p_storage_key !~ ('^shops/' || v_tok.shop_id::text || '/') then raise exception 'invalid_storage_key'; end if;\n  select coalesce(p_sort_order, coalesce(max(sort_order), -1) + 1) into v_sort from product_images where product_id = p_product_id;\n  insert into product_images (shop_id, product_id, storage_key, sort_order) values (v_tok.shop_id, p_product_id, p_storage_key, v_sort);\n  return api_product_get(p_token_hash, p_product_id);\nend;\n$$;\n\ncreate or replace function api_image_delete(p_token_hash text, p_image_id uuid)\nreturns text\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_key text;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  delete from product_images where id = p_image_id and shop_id = v_tok.shop_id returning storage_key into v_key;\n  if not found then raise exception 'not_found'; end if;\n  return v_key;\nend;\n$$;\n\n-- ---------- 注文 ----------\ncreate or replace function api_orders_list(p_token_hash text, p_status text default null, p_from timestamptz default null,\n                                           p_to timestamptz default null, p_limit integer default 50, p_offset integer default 0)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_pii boolean; v_limit integer; v_total integer; v_items jsonb;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:read');\n  v_pii := 'orders:pii' = any(v_tok.scopes);\n  v_limit := greatest(1, least(coalesce(p_limit, 50), 100));\n  select count(*) into v_total from orders o\n   where o.shop_id = v_tok.shop_id\n     and (p_status is null or o.status::text = p_status)\n     and (p_from is null or o.created_at >= p_from) and (p_to is null or o.created_at < p_to);\n  select coalesce(jsonb_agg(api_order_json(o, v_pii) order by o.created_at desc), '[]'::jsonb) into v_items\n    from (select * from orders o\n           where o.shop_id = v_tok.shop_id\n             and (p_status is null or o.status::text = p_status)\n             and (p_from is null or o.created_at >= p_from) and (p_to is null or o.created_at < p_to)\n           order by o.created_at desc\n           limit v_limit offset greatest(0, coalesce(p_offset, 0))) o;\n  return jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', greatest(0, coalesce(p_offset, 0)), 'pii', v_pii);\nend;\n$$;\n\ncreate or replace function api_order_get(p_token_hash text, p_order_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_o orders%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:read');\n  select * into v_o from orders where id = p_order_id and shop_id = v_tok.shop_id;\n  if not found then raise exception 'not_found'; end if;\n  return api_order_json(v_o, 'orders:pii' = any(v_tok.scopes));\nend;\n$$;\n\ncreate or replace function api_order_update_status(p_token_hash text, p_order_id uuid, p_status text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_o orders%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:write');\n  if p_status not in ('shipped', 'cancelled') then raise exception 'invalid_status'; end if;\n  update orders set status = p_status::order_status,\n                    shipped_at = case when p_status = 'shipped' then now() else shipped_at end\n   where id = p_order_id and shop_id = v_tok.shop_id and status = 'paid'\n  returning * into v_o;\n  if not found then raise exception 'not_found'; end if;\n  perform enqueue_hook(v_tok.shop_id, 'order.' || p_status,\n    jsonb_build_object('order_id', v_o.id, 'shop_id', v_tok.shop_id, 'total_jpy', v_o.total_jpy, 'status', v_o.status, 'shipped_at', v_o.shipped_at));\n  return api_order_json(v_o, 'orders:pii' = any(v_tok.scopes));\nend;\n$$;\n\n-- ---------- 集計（owner の管理画面と AI で共用） ----------\n-- p_group_by: 'day' | 'month' | 'product'。キャンセル・返金は除く。\ncreate or replace function sales_summary_for_shop(p_shop_id uuid, p_from timestamptz, p_to timestamptz, p_group_by text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_rows jsonb; v_total jsonb;\nbegin\n  if p_group_by not in ('day', 'month', 'product') then raise exception 'invalid_group_by'; end if;\n  select jsonb_build_object(\n    'orders', count(*), 'revenue_jpy', coalesce(sum(o.total_jpy), 0),\n    'items', coalesce((select sum(oi.qty) from order_items oi join orders o2 on o2.id = oi.order_id\n                        where o2.shop_id = p_shop_id and o2.status in ('paid','shipped') and o2.created_at >= p_from and o2.created_at < p_to), 0),\n    'avg_order_jpy', coalesce(round(avg(o.total_jpy)), 0))\n    into v_total\n    from orders o where o.shop_id = p_shop_id and o.status in ('paid','shipped') and o.created_at >= p_from and o.created_at < p_to;\n\n  if p_group_by = 'product' then\n    select coalesce(jsonb_agg(r order by (r->>'revenue_jpy')::bigint desc), '[]'::jsonb) into v_rows from (\n      select jsonb_build_object('product_id', p.id, 'product_name', coalesce(p.name, '(削除済み)'), 'sku_code', k.code,\n                                'qty', sum(oi.qty), 'revenue_jpy', sum(oi.qty * oi.unit_price_jpy)) as r\n        from order_items oi\n        join orders o on o.id = oi.order_id\n        left join skus k on k.id = oi.sku_id\n        left join products p on p.id = k.product_id\n       where o.shop_id = p_shop_id and o.status in ('paid','shipped') and o.created_at >= p_from and o.created_at < p_to\n       group by p.id, p.name, k.code) x;\n  else\n    select coalesce(jsonb_agg(r order by r->>'period'), '[]'::jsonb) into v_rows from (\n      select jsonb_build_object('period', to_char(date_trunc(p_group_by, o.created_at at time zone 'Asia/Tokyo'), case when p_group_by = 'day' then 'YYYY-MM-DD' else 'YYYY-MM' end),\n                                'orders', count(*), 'revenue_jpy', sum(o.total_jpy)) as r\n        from orders o\n       where o.shop_id = p_shop_id and o.status in ('paid','shipped') and o.created_at >= p_from and o.created_at < p_to\n       group by date_trunc(p_group_by, o.created_at at time zone 'Asia/Tokyo')) x;\n  end if;\n  return jsonb_build_object('from', p_from, 'to', p_to, 'group_by', p_group_by, 'timezone', 'Asia/Tokyo', 'total', v_total, 'rows', v_rows);\nend;\n$$;\n\n-- owner（管理画面）用\ncreate or replace function sales_summary(p_shop_id uuid, p_from timestamptz, p_to timestamptz, p_group_by text default 'day')\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  return sales_summary_for_shop(p_shop_id, p_from, p_to, p_group_by);\nend;\n$$;\n\n-- AI 用\ncreate or replace function api_sales_summary(p_token_hash text, p_from timestamptz, p_to timestamptz, p_group_by text default 'day')\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens;\nbegin\n  v_tok := api_require(p_token_hash, 'stats:read');\n  return sales_summary_for_shop(v_tok.shop_id, p_from, p_to, p_group_by);\nend;\n$$;\n\ncreate or replace function api_inventory_low(p_token_hash text, p_threshold integer default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_threshold integer;\nbegin\n  v_tok := api_require(p_token_hash, 'stats:read');\n  select coalesce(p_threshold, coalesce((s.settings->>'low_stock_threshold')::integer, 3)) into v_threshold from shops s where s.id = v_tok.shop_id;\n  return (select coalesce(jsonb_agg(jsonb_build_object('sku_id', k.id, 'sku_code', k.code, 'sku_name', k.name, 'product_id', p.id, 'product_name', p.name,\n                                                       'available', inv.available, 'published', p.published) order by inv.available, p.name), '[]'::jsonb)\n            from inventory inv join skus k on k.id = inv.sku_id join products p on p.id = k.product_id\n           where inv.shop_id = v_tok.shop_id and inv.available <= v_threshold);\nend;\n$$;\n\n-- ---------- 実行権限 ----------\n-- api_* と内部ヘルパーは service_role 専用。sales_summary は owner（authenticated）。\ndo $$\ndeclare f record;\nbegin\n  for f in\n    select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n     where n.nspname = 'public' and (p.proname like 'api\\_%' or p.proname = 'sales_summary_for_shop')\n  loop\n    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);\n    execute format('grant execute on function %s to service_role', f.sig);\n  end loop;\nend $$;\nrevoke execute on function sales_summary(uuid, timestamptz, timestamptz, text) from public, anon;\ngrant execute on function sales_summary(uuid, timestamptz, timestamptz, text) to authenticated, service_role;\n\ninsert into banto_migrations (version) values ('0003_api');\n" },
  { version: "0004_commerce", sql: "-- Banto 0004_commerce: 送料、注文番号、キャンセル（在庫戻し）、購入者向け注文照会、会員（オプトイン）\n-- 前方専用。既存行には既定値が入る。\n\n-- ---------- 送料・注文番号 ----------\n-- 送料設定は shops.settings.shipping（JSON）。計算はアプリ層（src/commerce/shipping.ts）で行い、確定時の金額を予約と注文に残す。\nalter table reservations add column shipping_jpy integer not null default 0 check (shipping_jpy >= 0);\nalter table orders add column shipping_jpy integer not null default 0 check (shipping_jpy >= 0);\n-- ショップごとの連番（1001 から）。人が読める注文番号\nalter table shops add column order_seq integer not null default 1000;\nalter table orders add column number integer;\ncreate unique index orders_shop_number on orders(shop_id, number) where number is not null;\n-- 既存の注文に番号を振る（作成順）\nwith numbered as (\n  select id, shop_id, row_number() over (partition by shop_id order by created_at, id) as rn from orders\n)\nupdate orders o set number = 1000 + n.rn from numbered n where n.id = o.id;\nupdate shops s set order_seq = greatest(order_seq, coalesce((select max(number) from orders o where o.shop_id = s.id), 1000));\nalter table orders alter column number set not null;\n\n-- 会員（任意）。orders.customer_id は会員が購入した場合だけ入る\ncreate table customers (\n  id uuid not null references auth.users(id) on delete cascade,\n  shop_id uuid not null references shops(id) on delete cascade,\n  email text,\n  name text,\n  default_address jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  primary key (shop_id, id)\n);\ncreate trigger customers_updated_at before update on customers for each row execute function banto_set_updated_at();\nalter table orders add column customer_id uuid;\nalter table reservations add column customer_id uuid;\ncreate index on orders(shop_id, customer_id) where customer_id is not null;\n\nalter table customers enable row level security;\n-- 会員は自分の行だけ。owner は自ショップの会員を閲覧・削除（退会対応）できる\ncreate policy customers_self on customers for all\n  using (id = auth.uid()) with check (id = auth.uid());\ncreate policy customers_owner_select on customers for select using (banto_owns_shop(shop_id));\ncreate policy customers_owner_delete on customers for delete using (banto_owns_shop(shop_id));\n-- 会員は自分の注文を閲覧できる\ncreate policy orders_customer_select on orders for select using (customer_id is not null and customer_id = auth.uid());\ncreate policy order_items_customer_select on order_items for select\n  using (exists (select 1 from orders o where o.id = order_items.order_id and o.customer_id is not null and o.customer_id = auth.uid()));\n\n-- ---------- 予約に購入者情報・送料・会員を付ける（0002 の attach を差し替え） ----------\ncreate or replace function attach_reservation_customer(p_reservation_id uuid, p_shop_id uuid, p_customer jsonb)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_shipping integer; v_customer_id uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'attach_reservation_customer: service_role only' using errcode = '42501';\n  end if;\n  v_shipping := coalesce((p_customer->>'shipping_jpy')::integer, 0);\n  if v_shipping < 0 then raise exception 'invalid_shipping'; end if;\n  v_customer_id := nullif(p_customer->>'customer_id', '')::uuid;\n  update reservations\n     set customer = p_customer - 'shipping_jpy' - 'customer_id',\n         shipping_jpy = v_shipping,\n         customer_id = v_customer_id\n   where id = p_reservation_id and shop_id = p_shop_id and status = 'pending';\n  if not found then\n    raise exception 'reservation_not_found' using detail = p_reservation_id::text;\n  end if;\nend;\n$$;\n\n-- ---------- 注文確定（0002 を差し替え: 送料・番号・会員・hooks の送料） ----------\ncreate or replace function confirm_reservation(p_reservation_id uuid, p_shop_id uuid, p_order jsonb default '{}'::jsonb)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res reservations%rowtype;\n  v_order_id uuid;\n  v_item jsonb;\n  v_updated integer;\n  v_subtotal integer;\n  v_number integer;\n  v_threshold integer;\n  v_available integer;\n  v_payload jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'confirm_reservation: service_role only' using errcode = '42501';\n  end if;\n\n  select * into v_res from reservations\n   where id = p_reservation_id and shop_id = p_shop_id\n   for update;\n  if not found then\n    raise exception 'reservation_not_found' using detail = p_reservation_id::text;\n  end if;\n\n  select id into v_order_id from orders where reservation_id = p_reservation_id;\n  if found then\n    return v_order_id;\n  end if;\n\n  if v_res.status = 'released' then\n    for v_item in select e from jsonb_array_elements(v_res.items) e order by e->>'sku_id' loop\n      update inventory\n         set available = available - (v_item->>'qty')::integer, updated_at = now()\n       where sku_id = (v_item->>'sku_id')::uuid and shop_id = p_shop_id\n         and available >= (v_item->>'qty')::integer;\n      get diagnostics v_updated = row_count;\n      if v_updated = 0 then\n        raise exception 'insufficient_stock_after_release' using detail = v_item->>'sku_id';\n      end if;\n    end loop;\n  end if;\n\n  select coalesce(sum((e->>'qty')::integer * (e->>'unit_price_jpy')::integer), 0)\n    into v_subtotal\n    from jsonb_array_elements(v_res.items) e;\n\n  -- ショップごとの注文番号（shops の行ロックで直列化）\n  update shops set order_seq = order_seq + 1 where id = p_shop_id returning order_seq into v_number;\n\n  insert into orders (shop_id, reservation_id, status, total_jpy, shipping_jpy, number, customer_id,\n                      customer_email, customer_name, shipping_address, payment_provider, payment_ref)\n  values (p_shop_id, p_reservation_id, 'paid', v_subtotal + v_res.shipping_jpy, v_res.shipping_jpy, v_number, v_res.customer_id,\n          -- Banto のフォームで集めた値を優先し、無ければ決済事業者からの値\n          coalesce(v_res.customer->>'customer_email', p_order->>'customer_email'),\n          coalesce(v_res.customer->>'customer_name', p_order->>'customer_name'),\n          coalesce(v_res.customer->'shipping_address', p_order->'shipping_address'),\n          p_order->>'payment_provider', p_order->>'payment_ref')\n  returning id into v_order_id;\n\n  insert into order_items (shop_id, order_id, sku_id, qty, unit_price_jpy)\n  select p_shop_id, v_order_id, (e->>'sku_id')::uuid, (e->>'qty')::integer, (e->>'unit_price_jpy')::integer\n    from jsonb_array_elements(v_res.items) e;\n\n  update reservations set status = 'confirmed', customer = null where id = p_reservation_id;\n\n  v_payload := jsonb_build_object(\n    'order_id', v_order_id, 'order_number', v_number, 'shop_id', p_shop_id,\n    'subtotal_jpy', v_subtotal, 'shipping_jpy', v_res.shipping_jpy, 'total_jpy', v_subtotal + v_res.shipping_jpy,\n    'status', 'paid', 'payment_provider', p_order->>'payment_provider', 'customer_id', v_res.customer_id,\n    'items', v_res.items\n  );\n  perform enqueue_hook(p_shop_id, 'order.created', v_payload);\n  perform enqueue_hook(p_shop_id, 'order.paid', v_payload);\n\n  select coalesce((s.settings->>'low_stock_threshold')::integer, 3) into v_threshold from shops s where s.id = p_shop_id;\n  for v_item in select e from jsonb_array_elements(v_res.items) e loop\n    select available into v_available from inventory where sku_id = (v_item->>'sku_id')::uuid;\n    if v_available is not null and v_available <= v_threshold then\n      perform enqueue_hook(p_shop_id, 'inventory.low',\n        jsonb_build_object('shop_id', p_shop_id, 'sku_id', v_item->>'sku_id', 'available', v_available, 'threshold', v_threshold));\n    end if;\n  end loop;\n\n  return v_order_id;\nend;\n$$;\n\n-- ---------- キャンセル: 在庫を戻し、状態を cancelled / refunded にする（返金自体は Worker が決済事業者 API で行う） ----------\n-- 支払い済み（paid）の注文のみ。冪等（既に cancelled/refunded なら何もせず現在の状態を返す）。\ncreate or replace function cancel_order(p_order_id uuid, p_shop_id uuid, p_refunded boolean)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_o orders%rowtype; v_item record;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'cancel_order: service_role only' using errcode = '42501';\n  end if;\n  select * into v_o from orders where id = p_order_id and shop_id = p_shop_id for update;\n  if not found then raise exception 'not_found'; end if;\n  if v_o.status in ('cancelled', 'refunded') then\n    return jsonb_build_object('order_id', v_o.id, 'status', v_o.status, 'already', true);\n  end if;\n  if v_o.status <> 'paid' then raise exception 'not_cancellable' using detail = v_o.status::text; end if;\n  for v_item in select sku_id, qty from order_items where order_id = p_order_id loop\n    update inventory set available = available + v_item.qty, updated_at = now()\n     where sku_id = v_item.sku_id and shop_id = p_shop_id;\n  end loop;\n  update orders set status = case when p_refunded then 'refunded'::order_status else 'cancelled'::order_status end\n   where id = p_order_id;\n  perform enqueue_hook(p_shop_id, 'order.cancelled',\n    jsonb_build_object('order_id', v_o.id, 'order_number', v_o.number, 'shop_id', p_shop_id, 'total_jpy', v_o.total_jpy,\n                       'status', case when p_refunded then 'refunded' else 'cancelled' end, 'refunded', p_refunded, 'customer_id', v_o.customer_id));\n  return jsonb_build_object('order_id', v_o.id, 'status', case when p_refunded then 'refunded' else 'cancelled' end, 'already', false,\n                            'payment_provider', v_o.payment_provider, 'payment_ref', v_o.payment_ref);\nend;\n$$;\n\n-- 返金に必要な情報だけ（Worker のキャンセル処理が先に読む）\ncreate or replace function order_payment_info(p_order_id uuid, p_shop_id uuid)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when auth.role() is distinct from 'service_role' then null\n         else (select jsonb_build_object('order_id', o.id, 'status', o.status, 'payment_provider', o.payment_provider,\n                                         'payment_ref', o.payment_ref, 'total_jpy', o.total_jpy)\n                 from orders o where o.id = p_order_id and o.shop_id = p_shop_id) end;\n$$;\n\n-- ---------- 取引メール用: 注文の連絡先と明細（同梱メールプラグインが service_role で読む。hooks のペイロードには載せない） ----------\ncreate or replace function order_contact(p_order_id uuid, p_shop_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_o orders%rowtype; v_s shops%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'order_contact: service_role only' using errcode = '42501';\n  end if;\n  select * into v_o from orders where id = p_order_id and shop_id = p_shop_id;\n  if not found then raise exception 'not_found'; end if;\n  select * into v_s from shops where id = p_shop_id;\n  return jsonb_build_object(\n    'order_id', v_o.id, 'number', v_o.number, 'status', v_o.status, 'created_at', v_o.created_at,\n    'total_jpy', v_o.total_jpy, 'shipping_jpy', v_o.shipping_jpy, 'payment_provider', v_o.payment_provider,\n    'customer_email', v_o.customer_email, 'customer_name', v_o.customer_name, 'shipping_address', v_o.shipping_address,\n    'shop', jsonb_build_object('name', v_s.name, 'slug', v_s.slug,\n                               'contact_email', v_s.settings->>'contact_email', 'return_policy', v_s.return_policy),\n    'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy) order by oi.id), '[]'::jsonb)\n                from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = v_o.id));\nend;\n$$;\n\n-- ---------- 購入者向け注文照会（anon）: 注文番号 + メールで状態だけ返す。住所は返さない ----------\ncreate or replace function lookup_order(p_shop_id uuid, p_number integer, p_email text)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object('number', o.number, 'status', o.status, 'created_at', o.created_at, 'shipped_at', o.shipped_at,\n                            'total_jpy', o.total_jpy, 'shipping_jpy', o.shipping_jpy,\n                            'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy) order by oi.id), '[]'::jsonb)\n                                        from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = o.id))\n    from orders o join shops s on s.id = o.shop_id\n   where o.shop_id = p_shop_id and o.number = p_number and s.published\n     and o.customer_email is not null and lower(o.customer_email) = lower(btrim(p_email))\n   limit 1;\n$$;\n\n-- ---------- api_* の更新: 注文 JSON に番号・送料・会員、キャンセルは cancel_order 経由 ----------\ncreate or replace function api_order_json(p_order orders, p_pii boolean)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_order.id, 'number', p_order.number, 'status', p_order.status, 'total_jpy', p_order.total_jpy, 'shipping_jpy', p_order.shipping_jpy,\n    'payment_provider', p_order.payment_provider, 'payment_ref', p_order.payment_ref, 'customer_id', p_order.customer_id,\n    'shipped_at', p_order.shipped_at, 'created_at', p_order.created_at, 'updated_at', p_order.updated_at,\n    'customer', case when p_pii then jsonb_build_object(\n        'email', p_order.customer_email, 'name', p_order.customer_name, 'shipping_address', p_order.shipping_address)\n      else jsonb_build_object('masked', true, 'prefecture', p_order.shipping_address->>'state') end,\n    'items', (select coalesce(jsonb_agg(jsonb_build_object(\n                 'sku_id', oi.sku_id, 'sku_code', k.code, 'sku_name', k.name, 'product_id', k.product_id, 'product_name', p.name,\n                 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy) order by oi.id), '[]'::jsonb)\n                from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id\n               where oi.order_id = p_order.id)\n  );\n$$;\n\n-- 発送済みのみ。キャンセルは api_order_cancel（返金後に Worker が呼ぶ）\ncreate or replace function api_order_update_status(p_token_hash text, p_order_id uuid, p_status text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_o orders%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:write');\n  if p_status <> 'shipped' then raise exception 'invalid_status'; end if;\n  update orders set status = 'shipped', shipped_at = now()\n   where id = p_order_id and shop_id = v_tok.shop_id and status = 'paid'\n  returning * into v_o;\n  if not found then raise exception 'not_found'; end if;\n  perform enqueue_hook(v_tok.shop_id, 'order.shipped',\n    jsonb_build_object('order_id', v_o.id, 'order_number', v_o.number, 'shop_id', v_tok.shop_id, 'total_jpy', v_o.total_jpy, 'status', v_o.status, 'shipped_at', v_o.shipped_at, 'customer_id', v_o.customer_id));\n  return api_order_json(v_o, 'orders:pii' = any(v_tok.scopes));\nend;\n$$;\n\ncreate or replace function api_order_payment_info(p_token_hash text, p_order_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_r jsonb;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:write');\n  v_r := order_payment_info(p_order_id, v_tok.shop_id);\n  if v_r is null then raise exception 'not_found'; end if;\n  return v_r;\nend;\n$$;\n\ncreate or replace function api_order_cancel(p_token_hash text, p_order_id uuid, p_refunded boolean)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_r jsonb; v_o orders%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:write');\n  v_r := cancel_order(p_order_id, v_tok.shop_id, p_refunded);\n  select * into v_o from orders where id = p_order_id;\n  return api_order_json(v_o, 'orders:pii' = any(v_tok.scopes));\nend;\n$$;\n\n-- 注文検索（番号・メール・氏名）を一覧に追加。旧シグネチャは削除（オーバーロードの曖昧さを避ける）\ndrop function if exists api_orders_list(text, text, timestamptz, timestamptz, integer, integer);\ncreate or replace function api_orders_list(p_token_hash text, p_status text default null, p_from timestamptz default null,\n                                           p_to timestamptz default null, p_limit integer default 50, p_offset integer default 0,\n                                           p_query text default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_pii boolean; v_limit integer; v_total integer; v_items jsonb; v_number integer;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:read');\n  v_pii := 'orders:pii' = any(v_tok.scopes);\n  v_limit := greatest(1, least(coalesce(p_limit, 50), 100));\n  v_number := case when p_query ~ '^\\d+$' then p_query::integer else null end;\n  select count(*) into v_total from orders o\n   where o.shop_id = v_tok.shop_id\n     and (p_status is null or o.status::text = p_status)\n     and (p_from is null or o.created_at >= p_from) and (p_to is null or o.created_at < p_to)\n     and (p_query is null or o.number = v_number or (v_pii and (o.customer_email ilike '%' || p_query || '%' or o.customer_name ilike '%' || p_query || '%')));\n  select coalesce(jsonb_agg(api_order_json(o, v_pii) order by o.created_at desc), '[]'::jsonb) into v_items\n    from (select * from orders o\n           where o.shop_id = v_tok.shop_id\n             and (p_status is null or o.status::text = p_status)\n             and (p_from is null or o.created_at >= p_from) and (p_to is null or o.created_at < p_to)\n             and (p_query is null or o.number = v_number or (v_pii and (o.customer_email ilike '%' || p_query || '%' or o.customer_name ilike '%' || p_query || '%')))\n           order by o.created_at desc\n           limit v_limit offset greatest(0, coalesce(p_offset, 0))) o;\n  return jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', greatest(0, coalesce(p_offset, 0)), 'pii', v_pii);\nend;\n$$;\n\n-- 送料を含めた集計（revenue は商品代 + 送料 = total_jpy のまま。内訳として shipping を足す）\ncreate or replace function sales_summary_for_shop(p_shop_id uuid, p_from timestamptz, p_to timestamptz, p_group_by text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_rows jsonb; v_total jsonb;\nbegin\n  if p_group_by not in ('day', 'month', 'product') then raise exception 'invalid_group_by'; end if;\n  select jsonb_build_object(\n    'orders', count(*), 'revenue_jpy', coalesce(sum(o.total_jpy), 0), 'shipping_jpy', coalesce(sum(o.shipping_jpy), 0),\n    'items', coalesce((select sum(oi.qty) from order_items oi join orders o2 on o2.id = oi.order_id\n                        where o2.shop_id = p_shop_id and o2.status in ('paid','shipped') and o2.created_at >= p_from and o2.created_at < p_to), 0),\n    'avg_order_jpy', coalesce(round(avg(o.total_jpy)), 0))\n    into v_total\n    from orders o where o.shop_id = p_shop_id and o.status in ('paid','shipped') and o.created_at >= p_from and o.created_at < p_to;\n\n  if p_group_by = 'product' then\n    select coalesce(jsonb_agg(r order by (r->>'revenue_jpy')::bigint desc), '[]'::jsonb) into v_rows from (\n      select jsonb_build_object('product_id', p.id, 'product_name', coalesce(p.name, '(削除済み)'), 'sku_code', k.code,\n                                'qty', sum(oi.qty), 'revenue_jpy', sum(oi.qty * oi.unit_price_jpy)) as r\n        from order_items oi\n        join orders o on o.id = oi.order_id\n        left join skus k on k.id = oi.sku_id\n        left join products p on p.id = k.product_id\n       where o.shop_id = p_shop_id and o.status in ('paid','shipped') and o.created_at >= p_from and o.created_at < p_to\n       group by p.id, p.name, k.code) x;\n  else\n    select coalesce(jsonb_agg(r order by r->>'period'), '[]'::jsonb) into v_rows from (\n      select jsonb_build_object('period', to_char(date_trunc(p_group_by, o.created_at at time zone 'Asia/Tokyo'), case when p_group_by = 'day' then 'YYYY-MM-DD' else 'YYYY-MM' end),\n                                'orders', count(*), 'revenue_jpy', sum(o.total_jpy), 'shipping_jpy', sum(o.shipping_jpy)) as r\n        from orders o\n       where o.shop_id = p_shop_id and o.status in ('paid','shipped') and o.created_at >= p_from and o.created_at < p_to\n       group by date_trunc(p_group_by, o.created_at at time zone 'Asia/Tokyo')) x;\n  end if;\n  return jsonb_build_object('from', p_from, 'to', p_to, 'group_by', p_group_by, 'timezone', 'Asia/Tokyo', 'total', v_total, 'rows', v_rows);\nend;\n$$;\n\n-- api_token_shop に接続済み Stripe アカウント ID を含める（返金先の判定用。秘密ではない）\ncreate or replace function api_token_shop(p_token_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens%rowtype; v_acct text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'api_token_shop: service_role only' using errcode = '42501';\n  end if;\n  select * into v_tok from api_tokens\n   where token_hash = p_token_hash and revoked_at is null and (expires_at is null or expires_at > now());\n  if not found then raise exception 'unauthorized' using errcode = '42501'; end if;\n  select stripe_account_id into v_acct from shops where id = v_tok.shop_id;\n  return jsonb_build_object('shop_id', v_tok.shop_id, 'scopes', to_jsonb(v_tok.scopes), 'name', v_tok.name, 'stripe_account_id', v_acct);\nend;\n$$;\n\n-- ---------- 実行権限 ----------\nrevoke execute on function attach_reservation_customer(uuid, uuid, jsonb) from public, anon, authenticated;\ngrant execute on function attach_reservation_customer(uuid, uuid, jsonb) to service_role;\nrevoke execute on function confirm_reservation(uuid, uuid, jsonb) from public, anon, authenticated;\ngrant execute on function confirm_reservation(uuid, uuid, jsonb) to service_role;\nrevoke execute on function cancel_order(uuid, uuid, boolean) from public, anon, authenticated;\ngrant execute on function cancel_order(uuid, uuid, boolean) to service_role;\nrevoke execute on function order_payment_info(uuid, uuid) from public, anon, authenticated;\ngrant execute on function order_payment_info(uuid, uuid) to service_role;\nrevoke execute on function order_contact(uuid, uuid) from public, anon, authenticated;\ngrant execute on function order_contact(uuid, uuid) to service_role;\nrevoke execute on function lookup_order(uuid, integer, text) from public;\ngrant execute on function lookup_order(uuid, integer, text) to anon, authenticated, service_role;\ndo $$\ndeclare f record;\nbegin\n  for f in\n    select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n     where n.nspname = 'public' and (p.proname like 'api\\_%' or p.proname = 'sales_summary_for_shop')\n  loop\n    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);\n    execute format('grant execute on function %s to service_role', f.sig);\n  end loop;\nend $$;\n\ninsert into banto_migrations (version) values ('0004_commerce');\n" },
  { version: "0005_images", sql: "-- Banto 0005_images: 商品画像のサムネイルと寸法\n-- 前方専用。管理画面がブラウザ側で縮小した本画像（長辺 1600px）とサムネイル（長辺 400px）を R2 に置き、\n-- 行に thumb_key と寸法を残す。既存行・AI 経由で URL から取り込んだ画像は thumb_key が null のまま\n-- （テーマは本画像にフォールバックする）。サーバー側では画像処理をしない（Workers の CPU 制限と可搬性のため）。\n\nalter table product_images\n  add column thumb_key text,\n  add column width integer check (width is null or (width > 0 and width <= 20000)),\n  add column height integer check (height is null or (height > 0 and height <= 20000));\n\n-- AI 用 API の商品 JSON にサムネイルと寸法を載せる\ncreate or replace function api_product_json(p_product products, p_with_skus boolean default true)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_product.id, 'slug', p_product.slug, 'name', p_product.name, 'description', p_product.description,\n    'published', p_product.published, 'created_at', p_product.created_at, 'updated_at', p_product.updated_at,\n    'images', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'storage_key', i.storage_key, 'thumb_key', i.thumb_key,\n                                                             'width', i.width, 'height', i.height, 'sort_order', i.sort_order) order by i.sort_order), '[]'::jsonb)\n                 from product_images i where i.product_id = p_product.id),\n    'skus', case when p_with_skus then\n      (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'code', k.code, 'name', k.name, 'price_jpy', k.price_jpy,\n                                                     'available', coalesce(inv.available, 0)) order by k.created_at), '[]'::jsonb)\n         from skus k left join inventory inv on inv.sku_id = k.id where k.product_id = p_product.id)\n      else null end\n  );\n$$;\n\n-- 画像削除はサムネイルのキーも返す（Worker が両方をストレージから消す）。戻り値の型が変わるので作り直す。\ndrop function api_image_delete(text, uuid);\ncreate function api_image_delete(p_token_hash text, p_image_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_row product_images;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  delete from product_images where id = p_image_id and shop_id = v_tok.shop_id returning * into v_row;\n  if not found then raise exception 'not_found'; end if;\n  return jsonb_build_object('storage_key', v_row.storage_key, 'thumb_key', v_row.thumb_key);\nend;\n$$;\nrevoke all on function api_image_delete(text, uuid) from public, anon, authenticated;\ngrant execute on function api_image_delete(text, uuid) to service_role;\n\ninsert into banto_migrations (version) values ('0005_images');\n" },
  { version: "0006_ops", sql: "-- Banto 0006_ops: バックアップ JSON からの復元、Cron のハートビート\n-- 前方専用。\n\n-- ---------- Cron ハートビート ----------\n-- 5 分ごとの Cron が最後に動いた時刻。/health が「Cron が止まっている」を検出するために使う（docs/monitoring.md）。\ncreate table banto_heartbeats (\n  name text primary key,\n  ran_at timestamptz not null default now()\n);\nalter table banto_heartbeats enable row level security;\n-- owner は閲覧のみ（ダッシュボード用）。書き込みは service_role の RPC だけ。\ncreate policy heartbeats_owner_select on banto_heartbeats for select\n  using (exists (select 1 from owners o where o.id = auth.uid()));\n\ncreate or replace function record_heartbeat(p_name text)\nreturns void\nlanguage sql\nsecurity definer\nset search_path = public\nas $$\n  insert into banto_heartbeats (name, ran_at) values (p_name, now())\n  on conflict (name) do update set ran_at = excluded.ran_at;\n$$;\nrevoke all on function record_heartbeat(text) from public, anon, authenticated;\ngrant execute on function record_heartbeat(text) to service_role;\n\n-- anon から呼べる唯一の読み取り: 経過秒数だけを返す（時刻や名前の一覧は返さない）。無ければ null。\ncreate or replace function heartbeat_age_seconds(p_name text)\nreturns integer\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select extract(epoch from now() - ran_at)::integer from banto_heartbeats where name = p_name;\n$$;\nrevoke all on function heartbeat_age_seconds(text) from public;\ngrant execute on function heartbeat_age_seconds(text) to anon, authenticated, service_role;\n\n-- ---------- バックアップからの復元 ----------\n-- /admin/shops/:id/export.json の JSON（tables 以下）を、空のショップに流し込む。\n-- Worker 側が owner JWT で shop の所有を確認してから service_role で呼ぶ（src/db/privileged.ts）。\n-- id はすべて振り直す（同じプロジェクトに同じ id が残っている可能性があるため）。\n-- 画像の実体（R2）は対象外。storage_key はそのまま引き継ぐので、同じバケットなら表示される。\n-- 会員（customers）は auth.users に同じ id が残っている場合だけ戻す（別プロジェクトでは戻せない）。\ncreate or replace function restore_shop_data(p_shop_id uuid, p_data jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_products jsonb := coalesce(p_data->'products', '[]'::jsonb);\n  v_skus jsonb := coalesce(p_data->'skus', '[]'::jsonb);\n  v_inventory jsonb := coalesce(p_data->'inventory', '[]'::jsonb);\n  v_images jsonb := coalesce(p_data->'product_images', '[]'::jsonb);\n  v_orders jsonb := coalesce(p_data->'orders', '[]'::jsonb);\n  v_items jsonb := coalesce(p_data->'order_items', '[]'::jsonb);\n  v_customers jsonb := coalesce(p_data->'customers', '[]'::jsonb);\n  v_endpoints jsonb := coalesce(p_data->'hook_endpoints', '[]'::jsonb);\n  v_row jsonb;\n  v_new uuid;\n  v_old uuid;\n  v_product_map jsonb := '{}'::jsonb;\n  v_sku_map jsonb := '{}'::jsonb;\n  v_order_map jsonb := '{}'::jsonb;\n  v_customer_ok jsonb := '{}'::jsonb;\n  v_counts jsonb := '{}'::jsonb;\n  v_n integer;\n  v_skipped_items integer := 0;\n  v_skipped_customers integer := 0;\n  v_max_number integer;\nbegin\n  if not exists (select 1 from shops where id = p_shop_id) then raise exception 'shop_not_found'; end if;\n  if exists (select 1 from products where shop_id = p_shop_id) or exists (select 1 from orders where shop_id = p_shop_id) then\n    raise exception 'shop_not_empty';\n  end if;\n  if jsonb_typeof(v_products) <> 'array' or jsonb_typeof(v_orders) <> 'array' then raise exception 'invalid_export'; end if;\n\n  -- 商品\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_products) loop\n    v_old := (v_row->>'id')::uuid;\n    insert into products (shop_id, slug, name, description, published, created_at, updated_at)\n      values (p_shop_id, v_row->>'slug', v_row->>'name', v_row->>'description', coalesce((v_row->>'published')::boolean, false),\n              coalesce((v_row->>'created_at')::timestamptz, now()), coalesce((v_row->>'updated_at')::timestamptz, now()))\n      returning id into v_new;\n    v_product_map := v_product_map || jsonb_build_object(v_old::text, v_new::text);\n    v_n := v_n + 1;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('products', v_n);\n\n  -- SKU（inventory 行はトリガーで作られる）→ 在庫数を戻す\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_skus) loop\n    if v_product_map ? (v_row->>'product_id') then\n      v_old := (v_row->>'id')::uuid;\n      insert into skus (shop_id, product_id, code, name, price_jpy, created_at)\n        values (p_shop_id, (v_product_map->>(v_row->>'product_id'))::uuid, v_row->>'code', v_row->>'name', (v_row->>'price_jpy')::integer,\n                coalesce((v_row->>'created_at')::timestamptz, now()))\n        returning id into v_new;\n      v_sku_map := v_sku_map || jsonb_build_object(v_old::text, v_new::text);\n      v_n := v_n + 1;\n    end if;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('skus', v_n);\n  for v_row in select * from jsonb_array_elements(v_inventory) loop\n    if v_sku_map ? (v_row->>'sku_id') then\n      update inventory set available = greatest(0, coalesce((v_row->>'available')::integer, 0))\n        where sku_id = (v_sku_map->>(v_row->>'sku_id'))::uuid and shop_id = p_shop_id;\n    end if;\n  end loop;\n\n  -- 画像（R2 のキーはそのまま）\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_images) loop\n    if v_product_map ? (v_row->>'product_id') then\n      insert into product_images (shop_id, product_id, storage_key, thumb_key, width, height, sort_order, created_at)\n        values (p_shop_id, (v_product_map->>(v_row->>'product_id'))::uuid, v_row->>'storage_key', v_row->>'thumb_key',\n                (v_row->>'width')::integer, (v_row->>'height')::integer, coalesce((v_row->>'sort_order')::integer, 0),\n                coalesce((v_row->>'created_at')::timestamptz, now()));\n      v_n := v_n + 1;\n    end if;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('product_images', v_n);\n\n  -- 会員: auth.users に同じ id がある場合だけ\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_customers) loop\n    v_old := (v_row->>'id')::uuid;\n    if exists (select 1 from auth.users u where u.id = v_old) then\n      insert into customers (id, shop_id, email, name, default_address, created_at)\n        values (v_old, p_shop_id, v_row->>'email', v_row->>'name', v_row->'default_address', coalesce((v_row->>'created_at')::timestamptz, now()))\n        on conflict (shop_id, id) do nothing;\n      v_customer_ok := v_customer_ok || jsonb_build_object(v_old::text, true);\n      v_n := v_n + 1;\n    else\n      v_skipped_customers := v_skipped_customers + 1;\n    end if;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('customers', v_n, 'customers_skipped', v_skipped_customers);\n\n  -- 注文（予約との紐づけは切る。番号は維持）\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_orders) loop\n    v_old := (v_row->>'id')::uuid;\n    insert into orders (shop_id, reservation_id, status, total_jpy, shipping_jpy, number, customer_email, customer_name, shipping_address,\n                        payment_provider, payment_ref, shipped_at, customer_id, created_at, updated_at)\n      values (p_shop_id, null, coalesce((v_row->>'status')::order_status, 'paid'), coalesce((v_row->>'total_jpy')::integer, 0),\n              coalesce((v_row->>'shipping_jpy')::integer, 0), (v_row->>'number')::integer, v_row->>'customer_email', v_row->>'customer_name',\n              v_row->'shipping_address', v_row->>'payment_provider', v_row->>'payment_ref', (v_row->>'shipped_at')::timestamptz,\n              case when v_customer_ok ? (v_row->>'customer_id') then (v_row->>'customer_id')::uuid else null end,\n              coalesce((v_row->>'created_at')::timestamptz, now()), coalesce((v_row->>'updated_at')::timestamptz, now()))\n      returning id into v_new;\n    v_order_map := v_order_map || jsonb_build_object(v_old::text, v_new::text);\n    v_n := v_n + 1;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('orders', v_n);\n  select max(number) into v_max_number from orders where shop_id = p_shop_id;\n  if v_max_number is not null then\n    update shops set order_seq = greatest(order_seq, v_max_number) where id = p_shop_id;\n  end if;\n\n  -- 明細（SKU が復元されていない行は飛ばす: skus.id への FK があるため）\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_items) loop\n    if v_order_map ? (v_row->>'order_id') and v_sku_map ? (v_row->>'sku_id') then\n      insert into order_items (shop_id, order_id, sku_id, qty, unit_price_jpy)\n        values (p_shop_id, (v_order_map->>(v_row->>'order_id'))::uuid, (v_sku_map->>(v_row->>'sku_id'))::uuid,\n                (v_row->>'qty')::integer, (v_row->>'unit_price_jpy')::integer);\n      v_n := v_n + 1;\n    else\n      v_skipped_items := v_skipped_items + 1;\n    end if;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('order_items', v_n, 'order_items_skipped', v_skipped_items);\n\n  -- 連携先（id は振り直す = 署名シークレットも変わる。外部プラグイン側の再設定が要る）\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_endpoints) loop\n    insert into hook_endpoints (shop_id, name, url, events, enabled, manifest, settings, created_at)\n      values (p_shop_id, v_row->>'name', v_row->>'url',\n              coalesce((select array_agg(e) from jsonb_array_elements_text(coalesce(v_row->'events', '[]'::jsonb)) e), '{}'),\n              coalesce((v_row->>'enabled')::boolean, true), v_row->'manifest', coalesce(v_row->'settings', '{}'::jsonb),\n              coalesce((v_row->>'created_at')::timestamptz, now()));\n    v_n := v_n + 1;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('hook_endpoints', v_n);\n\n  return v_counts;\nend;\n$$;\nrevoke all on function restore_shop_data(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function restore_shop_data(uuid, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0006_ops');\n" },
  { version: "0007_tags", sql: "-- Banto 0007_tags: 商品のタグ（ヘッドレス API の絞り込み・ストアフロントのタグ別一覧）\n-- 前方専用。docs/headless.md\n\n-- タグは 1 商品 20 個まで、1 個 1〜40 文字、カンマと改行を含まない（正規化はアプリと RPC の両方で行う）\n-- CHECK 制約から呼ぶので、管理画面（authenticated）が直接 UPDATE できるよう EXECUTE は剥奪しない（副作用のない純関数）\ncreate or replace function banto_valid_tags(p_tags text[])\nreturns boolean\nlanguage sql\nimmutable\nset search_path = public\nas $$\n  select cardinality(p_tags) <= 20\n     and not exists (select 1 from unnest(p_tags) t where length(t) not between 1 and 40 or t ~ '[,\\r\\n]');\n$$;\n\n-- 入力（jsonb の配列）→ 正規化したタグ配列。前後の空白を除き、空と重複を捨て、20 個で切る\ncreate or replace function banto_normalize_tags(p_tags jsonb)\nreturns text[]\nlanguage sql\nimmutable\nset search_path = public\nas $$\n  select coalesce(array_agg(t order by first_pos), '{}')\n    from (select t, min(pos) as first_pos\n            from (select left(regexp_replace(btrim(value), '[,\\r\\n]', '', 'g'), 40) as t, ord as pos\n                    from jsonb_array_elements_text(case when jsonb_typeof(p_tags) = 'array' then p_tags else '[]'::jsonb end) with ordinality as e(value, ord)) x\n           where t <> ''\n           group by t\n           order by min(pos)\n           limit 20) y;\n$$;\n\nalter table products add column tags text[] not null default '{}' check (banto_valid_tags(tags));\ncreate index products_tags_idx on products using gin (tags);\n\n-- AI 用 API: 商品の JSON にタグを載せ、作成・更新でタグを受け付ける（0003_api.sql の同名関数を置き換える。権限は既存のまま）\ncreate or replace function api_product_json(p_product products, p_with_skus boolean default true)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_product.id, 'slug', p_product.slug, 'name', p_product.name, 'description', p_product.description,\n    'tags', to_jsonb(p_product.tags),\n    'published', p_product.published, 'created_at', p_product.created_at, 'updated_at', p_product.updated_at,\n    'images', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'storage_key', i.storage_key, 'sort_order', i.sort_order) order by i.sort_order), '[]'::jsonb)\n                 from product_images i where i.product_id = p_product.id),\n    'skus', case when p_with_skus then\n      (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'code', k.code, 'name', k.name, 'price_jpy', k.price_jpy,\n                                                     'available', coalesce(inv.available, 0)) order by k.created_at), '[]'::jsonb)\n         from skus k left join inventory inv on inv.sku_id = k.id where k.product_id = p_product.id)\n      else null end\n  );\n$$;\n\ncreate or replace function api_product_create(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_p products%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  insert into products (shop_id, slug, name, description, published, tags)\n  values (v_tok.shop_id, p_values->>'slug', p_values->>'name', nullif(btrim(coalesce(p_values->>'description', '')), ''),\n          coalesce((p_values->>'published')::boolean, false), banto_normalize_tags(p_values->'tags'))\n  returning * into v_p;\n  perform enqueue_hook(v_tok.shop_id, 'product.updated', jsonb_build_object('product_id', v_p.id, 'shop_id', v_tok.shop_id, 'slug', v_p.slug, 'name', v_p.name, 'published', v_p.published));\n  return api_product_json(v_p, true);\nend;\n$$;\n\ncreate or replace function api_product_update(p_token_hash text, p_product_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_p products%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  update products set\n    slug = coalesce(p_values->>'slug', slug),\n    name = coalesce(nullif(btrim(p_values->>'name'), ''), name),\n    description = case when p_values ? 'description' then nullif(btrim(p_values->>'description'), '') else description end,\n    published = coalesce((p_values->>'published')::boolean, published),\n    tags = case when p_values ? 'tags' then banto_normalize_tags(p_values->'tags') else tags end\n  where id = p_product_id and shop_id = v_tok.shop_id\n  returning * into v_p;\n  if not found then raise exception 'not_found'; end if;\n  perform enqueue_hook(v_tok.shop_id, 'product.updated', jsonb_build_object('product_id', v_p.id, 'shop_id', v_tok.shop_id, 'slug', v_p.slug, 'name', v_p.name, 'published', v_p.published));\n  return api_product_json(v_p, true);\nend;\n$$;\n\n-- バックアップからの復元: restore_shop_data（0006）の後に呼び、slug で突き合わせてタグを戻す（id は振り直されているため）\ncreate or replace function restore_product_tags(p_shop_id uuid, p_products jsonb)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_row jsonb; v_n integer := 0;\nbegin\n  if jsonb_typeof(p_products) <> 'array' then raise exception 'invalid_export'; end if;\n  for v_row in select * from jsonb_array_elements(p_products) loop\n    if jsonb_typeof(v_row->'tags') = 'array' and jsonb_array_length(v_row->'tags') > 0 then\n      update products set tags = banto_normalize_tags(v_row->'tags')\n       where shop_id = p_shop_id and slug = v_row->>'slug';\n      if found then v_n := v_n + 1; end if;\n    end if;\n  end loop;\n  return v_n;\nend;\n$$;\n\nrevoke all on function banto_normalize_tags(jsonb) from public, anon, authenticated;\nrevoke all on function restore_product_tags(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function restore_product_tags(uuid, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0007_tags');\n" },
  { version: "0008_catalog", sql: "-- Banto 0008_catalog: 商品マスタの拡張（コアの「汎用の器」。docs/knowledge/08-woo-migration.md）\n--   カテゴリー（階層、3 段まで）/ ブランド / カスタム項目の値 / SKU の選択肢（サイズ・色など）/ JAN・GTIN / 通常価格（セール表示用）\n-- 前方専用。\n\n-- ---------- カテゴリー ----------\ncreate table categories (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  parent_id uuid,\n  slug text not null check (slug ~ '^[a-z0-9][a-z0-9-]{0,62}$'),\n  name text not null check (length(name) between 1 and 100),\n  sort_order integer not null default 0,\n  created_at timestamptz not null default now(),\n  unique (shop_id, slug),\n  unique (id, shop_id),\n  -- 親は同じショップのカテゴリーだけ。親を消すと子は最上位になる\n  foreign key (parent_id, shop_id) references categories (id, shop_id) on delete set null (parent_id)\n);\ncreate index on categories(shop_id);\n\n-- 階層は 3 段まで、循環させない\ncreate or replace function banto_check_category_parent()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\ndeclare v_depth integer := 1; v_cur uuid := new.parent_id;\nbegin\n  while v_cur is not null loop\n    if v_cur = new.id then raise exception 'category_cycle'; end if;\n    v_depth := v_depth + 1;\n    if v_depth > 3 then raise exception 'category_too_deep'; end if;\n    select parent_id into v_cur from categories where id = v_cur;\n  end loop;\n  -- 子孫を含めて 3 段に収まるか（自分の下に子がいる状態で親を付け替えた場合）\n  if exists (\n    with recursive d(id, lvl) as (\n      select id, 1 from categories where parent_id = new.id\n      union all\n      select c.id, d.lvl + 1 from categories c join d on c.parent_id = d.id where d.lvl < 4\n    ) select 1 from d where v_depth + d.lvl > 3\n  ) then raise exception 'category_too_deep'; end if;\n  return new;\nend;\n$$;\ncreate trigger categories_parent_check before insert or update of parent_id on categories\n  for each row execute function banto_check_category_parent();\n\nalter table categories enable row level security;\ncreate policy categories_owner on categories for all\n  using (banto_owns_shop(shop_id)) with check (banto_owns_shop(shop_id));\ncreate policy categories_public on categories for select\n  using (exists (select 1 from shops s where s.id = categories.shop_id and s.published = true));\n\n-- ---------- 商品 ----------\nalter table products\n  add column category_id uuid,\n  add column brand text check (brand is null or length(brand) between 1 and 100),\n  -- カスタム項目の値（項目の定義は shops.settings.product_fields）。値は文字列か数値のみ\n  add column attributes jsonb not null default '{}'::jsonb\n    check (jsonb_typeof(attributes) = 'object' and octet_length(attributes::text) <= 16000),\n  add constraint products_category_fk foreign key (category_id, shop_id) references categories (id, shop_id) on delete set null (category_id);\ncreate index on products(category_id);\n\n-- ---------- SKU ----------\nalter table skus\n  -- 選択肢（例: {\"サイズ\": \"M\", \"色\": \"黒\"}）\n  add column options jsonb not null default '{}'::jsonb\n    check (jsonb_typeof(options) = 'object' and octet_length(options::text) <= 2000),\n  -- JAN / GTIN（8・12・13・14 桁）\n  add column gtin text check (gtin is null or gtin ~ '^([0-9]{8}|[0-9]{12,14})$'),\n  -- 通常価格（セール表示用の比較価格）。販売価格より高いときだけ持つ\n  add column compare_at_price_jpy integer check (compare_at_price_jpy is null or compare_at_price_jpy > price_jpy);\n\n-- ---------- 入力の正規化（AI 用 API と復元で共通） ----------\n-- オブジェクトのうち、キーが 1〜40 文字で値が文字列・数値のものだけ残す（文字列は 500 文字まで）。それ以外は捨てる\ncreate or replace function banto_clean_object(p jsonb, p_max_keys integer)\nreturns jsonb\nlanguage sql\nimmutable\nset search_path = public\nas $$\n  select coalesce(jsonb_object_agg(k, case when jsonb_typeof(v) = 'string' then to_jsonb(left(v #>> '{}', 500)) else v end), '{}'::jsonb)\n    from (select key as k, value as v from jsonb_each(case when jsonb_typeof(p) = 'object' then p else '{}'::jsonb end)\n           where length(btrim(key)) between 1 and 40 and jsonb_typeof(value) in ('string', 'number')\n           order by key limit p_max_keys) x;\n$$;\n\n-- ---------- AI 用 API（0003 / 0007 の同名関数を置き換える。権限は既存のまま） ----------\ncreate or replace function api_category_json(p_category categories)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when p_category.id is null then null else\n    jsonb_build_object('id', p_category.id, 'slug', p_category.slug, 'name', p_category.name, 'parent_id', p_category.parent_id, 'sort_order', p_category.sort_order) end;\n$$;\n\ncreate or replace function api_product_json(p_product products, p_with_skus boolean default true)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_product.id, 'slug', p_product.slug, 'name', p_product.name, 'description', p_product.description,\n    'tags', to_jsonb(p_product.tags), 'brand', p_product.brand, 'attributes', p_product.attributes,\n    'category', (select api_category_json(c) from categories c where c.id = p_product.category_id),\n    'published', p_product.published, 'created_at', p_product.created_at, 'updated_at', p_product.updated_at,\n    'images', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'storage_key', i.storage_key, 'sort_order', i.sort_order) order by i.sort_order), '[]'::jsonb)\n                 from product_images i where i.product_id = p_product.id),\n    'skus', case when p_with_skus then\n      (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'code', k.code, 'name', k.name, 'price_jpy', k.price_jpy,\n                                                     'compare_at_price_jpy', k.compare_at_price_jpy, 'options', k.options, 'gtin', k.gtin,\n                                                     'available', coalesce(inv.available, 0)) order by k.created_at), '[]'::jsonb)\n         from skus k left join inventory inv on inv.sku_id = k.id where k.product_id = p_product.id)\n      else null end\n  );\n$$;\n\n-- カテゴリーの指定（slug）→ id。空文字なら null（外す）。見つからなければ例外\ncreate or replace function api_category_ref(p_shop_id uuid, p_slug text)\nreturns uuid\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_id uuid;\nbegin\n  if p_slug is null or btrim(p_slug) = '' then return null; end if;\n  select id into v_id from categories where shop_id = p_shop_id and slug = btrim(p_slug);\n  if not found then raise exception 'category_not_found'; end if;\n  return v_id;\nend;\n$$;\n\ncreate or replace function api_product_create(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_p products%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  insert into products (shop_id, slug, name, description, published, tags, brand, attributes, category_id)\n  values (v_tok.shop_id, p_values->>'slug', p_values->>'name', nullif(btrim(coalesce(p_values->>'description', '')), ''),\n          coalesce((p_values->>'published')::boolean, false), banto_normalize_tags(p_values->'tags'),\n          nullif(btrim(coalesce(p_values->>'brand', '')), ''), banto_clean_object(p_values->'attributes', 50),\n          api_category_ref(v_tok.shop_id, p_values->>'category'))\n  returning * into v_p;\n  perform enqueue_hook(v_tok.shop_id, 'product.updated', jsonb_build_object('product_id', v_p.id, 'shop_id', v_tok.shop_id, 'slug', v_p.slug, 'name', v_p.name, 'published', v_p.published));\n  return api_product_json(v_p, true);\nend;\n$$;\n\ncreate or replace function api_product_update(p_token_hash text, p_product_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_p products%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  update products set\n    slug = coalesce(p_values->>'slug', slug),\n    name = coalesce(nullif(btrim(p_values->>'name'), ''), name),\n    description = case when p_values ? 'description' then nullif(btrim(p_values->>'description'), '') else description end,\n    published = coalesce((p_values->>'published')::boolean, published),\n    tags = case when p_values ? 'tags' then banto_normalize_tags(p_values->'tags') else tags end,\n    brand = case when p_values ? 'brand' then nullif(btrim(coalesce(p_values->>'brand', '')), '') else brand end,\n    attributes = case when p_values ? 'attributes' then banto_clean_object(p_values->'attributes', 50) else attributes end,\n    category_id = case when p_values ? 'category' then api_category_ref(v_tok.shop_id, p_values->>'category') else category_id end\n  where id = p_product_id and shop_id = v_tok.shop_id\n  returning * into v_p;\n  if not found then raise exception 'not_found'; end if;\n  perform enqueue_hook(v_tok.shop_id, 'product.updated', jsonb_build_object('product_id', v_p.id, 'shop_id', v_tok.shop_id, 'slug', v_p.slug, 'name', v_p.name, 'published', v_p.published));\n  return api_product_json(v_p, true);\nend;\n$$;\n\ncreate or replace function api_sku_create(p_token_hash text, p_product_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_k skus%rowtype; v_available integer;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  if not exists (select 1 from products where id = p_product_id and shop_id = v_tok.shop_id) then raise exception 'not_found'; end if;\n  insert into skus (shop_id, product_id, code, name, price_jpy, options, gtin, compare_at_price_jpy)\n  values (v_tok.shop_id, p_product_id, p_values->>'code', nullif(btrim(coalesce(p_values->>'name', '')), ''), (p_values->>'price_jpy')::integer,\n          banto_clean_object(p_values->'options', 5), nullif(btrim(coalesce(p_values->>'gtin', '')), ''), (p_values->>'compare_at_price_jpy')::integer)\n  returning * into v_k;\n  v_available := coalesce((p_values->>'available')::integer, 0);\n  if v_available < 0 then raise exception 'invalid_available'; end if;\n  update inventory set available = v_available, updated_at = now() where sku_id = v_k.id;\n  return api_product_get(p_token_hash, p_product_id);\nend;\n$$;\n\ncreate or replace function api_sku_update(p_token_hash text, p_sku_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_k skus%rowtype; v_available integer;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  update skus set\n    code = coalesce(p_values->>'code', code),\n    name = case when p_values ? 'name' then nullif(btrim(p_values->>'name'), '') else name end,\n    price_jpy = coalesce((p_values->>'price_jpy')::integer, price_jpy),\n    options = case when p_values ? 'options' then banto_clean_object(p_values->'options', 5) else options end,\n    gtin = case when p_values ? 'gtin' then nullif(btrim(coalesce(p_values->>'gtin', '')), '') else gtin end,\n    compare_at_price_jpy = case when p_values ? 'compare_at_price_jpy' then (p_values->>'compare_at_price_jpy')::integer else compare_at_price_jpy end\n  where id = p_sku_id and shop_id = v_tok.shop_id\n  returning * into v_k;\n  if not found then raise exception 'not_found'; end if;\n  if p_values ? 'available' then\n    v_available := (p_values->>'available')::integer;\n    if v_available is null or v_available < 0 then raise exception 'invalid_available'; end if;\n    update inventory set available = v_available, updated_at = now() where sku_id = v_k.id;\n  end if;\n  return api_product_get(p_token_hash, v_k.product_id);\nend;\n$$;\n\n-- カテゴリーの一覧と作成・更新（slug で突き合わせ。parent は親の slug、空なら最上位）\ncreate or replace function api_categories_list(p_token_hash text)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens;\nbegin\n  v_tok := api_require(p_token_hash, 'products:read');\n  return (select coalesce(jsonb_agg(api_category_json(c) order by c.sort_order, c.name), '[]'::jsonb) from categories c where c.shop_id = v_tok.shop_id);\nend;\n$$;\n\ncreate or replace function api_category_save(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_c categories%rowtype; v_parent uuid;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  v_parent := api_category_ref(v_tok.shop_id, p_values->>'parent');\n  insert into categories (shop_id, slug, name, parent_id, sort_order)\n  values (v_tok.shop_id, btrim(p_values->>'slug'), btrim(p_values->>'name'), v_parent, coalesce((p_values->>'sort_order')::integer, 0))\n  on conflict (shop_id, slug) do update set\n    name = coalesce(nullif(btrim(excluded.name), ''), categories.name),\n    parent_id = case when p_values ? 'parent' then excluded.parent_id else categories.parent_id end,\n    sort_order = case when p_values ? 'sort_order' then excluded.sort_order else categories.sort_order end\n  returning * into v_c;\n  return api_category_json(v_c);\nend;\n$$;\n\n-- ---------- バックアップからの復元 ----------\n-- restore_shop_data（0006）の後に呼ぶ。0006 が知らない列（タグ・カテゴリー・ブランド・カスタム項目・SKU の拡張）を\n-- slug / code で突き合わせて戻す（id は振り直されているため）。戻した件数を返す。\ncreate or replace function restore_catalog(p_shop_id uuid, p_data jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_cat_map jsonb := '{}'::jsonb; v_new uuid; v_n_cat integer := 0; v_n_prod integer := 0; v_n_sku integer := 0;\n  v_cats jsonb := coalesce(p_data->'categories', '[]'::jsonb);\n  v_products jsonb := coalesce(p_data->'products', '[]'::jsonb);\n  v_skus jsonb := coalesce(p_data->'skus', '[]'::jsonb);\nbegin\n  if jsonb_typeof(v_cats) <> 'array' or jsonb_typeof(v_products) <> 'array' or jsonb_typeof(v_skus) <> 'array' then raise exception 'invalid_export'; end if;\n  -- カテゴリー: まず親なしで作り、次に親を付ける（並び順に依存しない）\n  for v_row in select * from jsonb_array_elements(v_cats) loop\n    insert into categories (shop_id, slug, name, sort_order)\n    values (p_shop_id, v_row->>'slug', v_row->>'name', coalesce((v_row->>'sort_order')::integer, 0))\n    on conflict (shop_id, slug) do update set name = excluded.name\n    returning id into v_new;\n    v_cat_map := v_cat_map || jsonb_build_object(v_row->>'id', v_new::text);\n    v_n_cat := v_n_cat + 1;\n  end loop;\n  for v_row in select * from jsonb_array_elements(v_cats) loop\n    if v_cat_map ? (v_row->>'parent_id') then\n      update categories set parent_id = (v_cat_map->>(v_row->>'parent_id'))::uuid\n       where shop_id = p_shop_id and slug = v_row->>'slug';\n    end if;\n  end loop;\n  -- 商品\n  for v_row in select * from jsonb_array_elements(v_products) loop\n    update products set\n      tags = banto_normalize_tags(v_row->'tags'),\n      brand = nullif(btrim(coalesce(v_row->>'brand', '')), ''),\n      attributes = banto_clean_object(v_row->'attributes', 50),\n      category_id = case when v_cat_map ? (v_row->>'category_id') then (v_cat_map->>(v_row->>'category_id'))::uuid else null end\n     where shop_id = p_shop_id and slug = v_row->>'slug';\n    if found then v_n_prod := v_n_prod + 1; end if;\n  end loop;\n  -- SKU\n  for v_row in select * from jsonb_array_elements(v_skus) loop\n    update skus set\n      options = banto_clean_object(v_row->'options', 5),\n      gtin = nullif(btrim(coalesce(v_row->>'gtin', '')), ''),\n      compare_at_price_jpy = (v_row->>'compare_at_price_jpy')::integer\n     where shop_id = p_shop_id and code = v_row->>'code';\n    if found then v_n_sku := v_n_sku + 1; end if;\n  end loop;\n  return jsonb_build_object('categories', v_n_cat, 'products_extended', v_n_prod, 'skus_extended', v_n_sku);\nend;\n$$;\n\n-- ---------- 実行権限 ----------\n-- 新しい api_* と内部ヘルパーは service_role 専用（0003 と同じ）\ndo $$\ndeclare f record;\nbegin\n  for f in\n    select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n     where n.nspname = 'public' and p.proname in ('api_category_json', 'api_category_ref', 'api_categories_list', 'api_category_save', 'banto_clean_object', 'restore_catalog')\n  loop\n    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);\n    execute format('grant execute on function %s to service_role', f.sig);\n  end loop;\nend $$;\n-- CHECK 制約から呼ぶものではないが、トリガー関数は所有者権限で動くので剥奪してよい\nrevoke all on function banto_check_category_parent() from public, anon, authenticated;\n\ninsert into banto_migrations (version) values ('0008_catalog');\n" },
  { version: "0009_catalog_import", sql: "-- Banto 0009_catalog_import: 商品マスタの一括取り込み（コアの部品。WooCommerce インポーター等の同梱モジュールが使う）\n-- 前方専用。docs/knowledge/08-woo-migration.md\n--\n-- import_catalog(p_shop_id, p_batch) は owner（authenticated）が呼び、ショップの所有を関数内で確かめる（set_stock と同じ）。\n-- 1 回の呼び出しでカテゴリー・商品・SKU・在庫をまとめて書く（Workers の 1 リクエストあたりのサブリクエスト上限に当たらないように）。\n-- 商品は slug、SKU は code、カテゴリーは slug で突き合わせるので、同じ内容を何度取り込んでも重複しない。\n-- 商品ごとに例外を受け止め、1 件の不備で他の商品を巻き込まない（エラーは結果の errors に返す）。\n--\n-- p_batch:\n--   { \"categories\": [{ \"slug\", \"name\", \"parent_slug\"?, \"sort_order\"? }],      親が先に来る順で並べる\n--     \"products\":   [{ \"slug\", \"name\", \"description\"?, \"published\"?, \"tags\"?, \"brand\"?, \"attributes\"?, \"category_slug\"?,\n--                      \"skus\": [{ \"code\", \"name\"?, \"price_jpy\", \"compare_at_price_jpy\"?, \"gtin\"?, \"options\"?, \"available\"? }] }],\n--     \"overwrite_stock\": true | false }                                      false なら既存 SKU の在庫は変えない（新規 SKU には入れる）\n-- 戻り値: { categories, products_created, products_updated, skus_created, skus_updated, errors: [{ slug, message }] }\n\ncreate or replace function import_catalog(p_shop_id uuid, p_batch jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_sku jsonb; v_cat_id uuid; v_parent uuid; v_pid uuid; v_kid uuid; v_existing uuid; v_avail integer;\n  v_price integer; v_compare integer; v_gtin text; v_created boolean;\n  v_n_cat integer := 0; v_p_new integer := 0; v_p_upd integer := 0; v_k_new integer := 0; v_k_upd integer := 0;\n  l_p_new integer; l_k_new integer; l_k_upd integer;\n  v_errors jsonb := '[]'::jsonb;\n  v_overwrite boolean := coalesce((p_batch->>'overwrite_stock')::boolean, true);\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n\n  -- カテゴリー（親が先）\n  for v_row in select * from jsonb_array_elements(coalesce(p_batch->'categories', '[]'::jsonb)) loop\n    v_parent := null;\n    if coalesce(v_row->>'parent_slug', '') <> '' then\n      select id into v_parent from categories where shop_id = p_shop_id and slug = v_row->>'parent_slug';\n    end if;\n    insert into categories (shop_id, slug, name, parent_id, sort_order)\n    values (p_shop_id, v_row->>'slug', left(btrim(v_row->>'name'), 100), v_parent, coalesce((v_row->>'sort_order')::integer, 0))\n    on conflict (shop_id, slug) do update set name = excluded.name, parent_id = excluded.parent_id;\n    v_n_cat := v_n_cat + 1;\n  end loop;\n\n  -- 商品と SKU\n  for v_row in select * from jsonb_array_elements(coalesce(p_batch->'products', '[]'::jsonb)) loop\n    begin\n      l_p_new := 0; l_k_new := 0; l_k_upd := 0;\n      v_cat_id := null;\n      if coalesce(v_row->>'category_slug', '') <> '' then\n        select id into v_cat_id from categories where shop_id = p_shop_id and slug = v_row->>'category_slug';\n      end if;\n      select id into v_pid from products where shop_id = p_shop_id and slug = v_row->>'slug';\n      if v_pid is null then\n        insert into products (shop_id, slug, name, description, published, tags, brand, attributes, category_id)\n        values (p_shop_id, v_row->>'slug', left(btrim(v_row->>'name'), 200), nullif(btrim(coalesce(v_row->>'description', '')), ''),\n                coalesce((v_row->>'published')::boolean, false), banto_normalize_tags(v_row->'tags'),\n                nullif(left(btrim(coalesce(v_row->>'brand', '')), 100), ''), banto_clean_object(v_row->'attributes', 200), v_cat_id)\n        returning id into v_pid;\n        l_p_new := 1;\n      else\n        -- カスタム項目は既存の値に上書きでマージする（取り込み元に無い項目を消さない）\n        update products set\n          name = left(btrim(v_row->>'name'), 200),\n          description = nullif(btrim(coalesce(v_row->>'description', '')), ''),\n          published = coalesce((v_row->>'published')::boolean, published),\n          tags = banto_normalize_tags(v_row->'tags'),\n          brand = nullif(left(btrim(coalesce(v_row->>'brand', '')), 100), ''),\n          attributes = attributes || banto_clean_object(v_row->'attributes', 200),\n          category_id = v_cat_id\n        where id = v_pid;\n      end if;\n\n      for v_sku in select * from jsonb_array_elements(coalesce(v_row->'skus', '[]'::jsonb)) loop\n        v_price := (v_sku->>'price_jpy')::integer;\n        v_compare := (v_sku->>'compare_at_price_jpy')::integer;\n        if v_compare is not null and v_compare <= v_price then v_compare := null; end if;\n        v_gtin := nullif(btrim(coalesce(v_sku->>'gtin', '')), '');\n        if v_gtin is not null and v_gtin !~ '^([0-9]{8}|[0-9]{12,14})$' then v_gtin := null; end if;\n        select id, product_id into v_kid, v_existing from skus where shop_id = p_shop_id and code = v_sku->>'code';\n        v_created := v_kid is null;\n        if v_created then\n          insert into skus (shop_id, product_id, code, name, price_jpy, compare_at_price_jpy, gtin, options)\n          values (p_shop_id, v_pid, v_sku->>'code', nullif(left(btrim(coalesce(v_sku->>'name', '')), 200), ''), v_price, v_compare, v_gtin,\n                  banto_clean_object(v_sku->'options', 5))\n          returning id into v_kid;\n          l_k_new := l_k_new + 1;\n        else\n          if v_existing <> v_pid then raise exception 'sku_belongs_to_other_product: %', v_sku->>'code'; end if;\n          update skus set name = nullif(left(btrim(coalesce(v_sku->>'name', '')), 200), ''), price_jpy = v_price, compare_at_price_jpy = v_compare,\n                          gtin = v_gtin, options = banto_clean_object(v_sku->'options', 5)\n           where id = v_kid;\n          l_k_upd := l_k_upd + 1;\n        end if;\n        -- 在庫（inventory 行は skus の insert でトリガーが作る）\n        if v_sku ? 'available' and (v_created or v_overwrite) then\n          v_avail := greatest(0, coalesce((v_sku->>'available')::integer, 0));\n          update inventory set available = v_avail, updated_at = now() where sku_id = v_kid;\n        end if;\n      end loop;\n\n      perform enqueue_hook(p_shop_id, 'product.updated', jsonb_build_object('product_id', v_pid, 'shop_id', p_shop_id, 'slug', v_row->>'slug'));\n      -- 件数はこの商品が最後まで通ったときだけ数える（例外なら全部取り消されるため）\n      v_p_new := v_p_new + l_p_new; v_p_upd := v_p_upd + (1 - l_p_new); v_k_new := v_k_new + l_k_new; v_k_upd := v_k_upd + l_k_upd;\n    exception when others then\n      -- この商品だけ取り消して続ける（plpgsql の例外ブロックはセーブポイントとして働く）\n      v_errors := v_errors || jsonb_build_object('slug', v_row->>'slug', 'message', sqlerrm);\n    end;\n  end loop;\n\n  return jsonb_build_object('categories', v_n_cat, 'products_created', v_p_new, 'products_updated', v_p_upd,\n                            'skus_created', v_k_new, 'skus_updated', v_k_upd, 'errors', v_errors);\nend;\n$$;\n\nrevoke execute on function import_catalog(uuid, jsonb) from public, anon;\ngrant execute on function import_catalog(uuid, jsonb) to authenticated, service_role;\n\ninsert into banto_migrations (version) values ('0009_catalog_import');\n" },
  { version: "0010_coupons", sql: "-- Banto 0010_coupons: クーポン（値引き）の器と、在庫と同じ一本道での回数の予約。docs/knowledge/09-coupons.md\n-- 前方専用。\n--\n-- 値引きはお金に関わるので判定はコア（CLAUDE.md §7 の基準 (1)）。計算は src/commerce/discounts.ts の 1 か所、\n-- 回数（全体の上限・1 人あたり）は予約と同じく Postgres の中で原子的に数える。管理画面は同梱モジュール coupons（既定 OFF）。\n--\n--   coupon_campaigns   キャンペーン（値引きの内容と条件。条件は宣言型の JSON）\n--   coupon_slots       全体の上限の「枠」。上限の数だけ行を作り、空き枠を FOR UPDATE SKIP LOCKED で取り合う\n--                      （1 つのカウンターを全員で書き換えないので、先着のキャンペーンでも順番待ちが起きない）\n--   coupon_redemptions 使用の記録。予約中 held → 確定 used、決済ページの期限切れ・キャンセルで released\n--\n-- 1 人あたりの回数は subject（会員なら 'c:<会員 ID>'、ゲストなら 'e:<メールアドレスの SHA-256>'）で数える。\n-- メールアドレスそのものは持たない（個人情報を増やさない）。\n\n-- ---------- キャンペーン ----------\ncreate table coupon_campaigns (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  name text not null check (length(name) between 1 and 100),\n  -- 公開コード（大文字に正規化）。null ならコードでは使えない（会員への発行など、後で足す使い方のため）\n  code text check (code ~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'),\n  kind text not null check (kind in ('percent', 'fixed', 'free_shipping')),\n  -- percent: 1〜100（%）、fixed: 円、free_shipping: 0\n  value integer not null default 0 check (value >= 0),\n  starts_at timestamptz,\n  ends_at timestamptz,\n  -- 全体の上限（null なら無制限）。この数だけ coupon_slots を作る\n  usage_limit integer check (usage_limit between 1 and 100000),\n  -- 1 人あたりの上限（null なら無制限）\n  per_customer_limit integer check (per_customer_limit between 1 and 1000),\n  -- 他のクーポンと併用できるか（併用できないクーポンは 1 注文に 1 枚だけ）\n  combinable boolean not null default false,\n  -- public: 誰でも / members: ログイン中の会員だけ\n  audience text not null default 'public' check (audience in ('public', 'members')),\n  -- 対象と条件（src/commerce/discounts.ts の Conditions）。任意のコードは動かさない\n  conditions jsonb not null default '{}'::jsonb check (jsonb_typeof(conditions) = 'object'),\n  active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  check (kind <> 'percent' or value between 1 and 100),\n  check (kind <> 'fixed' or value >= 1),\n  check (starts_at is null or ends_at is null or starts_at < ends_at)\n);\ncreate unique index coupon_campaigns_code on coupon_campaigns(shop_id, code) where code is not null;\ncreate index on coupon_campaigns(shop_id);\ncreate trigger coupon_campaigns_updated_at before update on coupon_campaigns for each row execute function banto_set_updated_at();\n\n-- ---------- 全体の上限の枠 ----------\ncreate table coupon_slots (\n  id bigint generated always as identity primary key,\n  campaign_id uuid not null references coupon_campaigns(id) on delete cascade,\n  shop_id uuid not null references shops(id) on delete cascade,\n  status text not null default 'free' check (status in ('free', 'held', 'used')),\n  reservation_id uuid references reservations(id) on delete set null\n);\n-- 空き枠だけの部分索引（使われた枠が増えても、空き枠を探す速さは変わらない）\ncreate index coupon_slots_free on coupon_slots(campaign_id) where status = 'free';\ncreate index on coupon_slots(reservation_id) where reservation_id is not null;\n\n-- ---------- 使用の記録 ----------\ncreate table coupon_redemptions (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  campaign_id uuid not null references coupon_campaigns(id) on delete cascade,\n  reservation_id uuid not null references reservations(id) on delete cascade,\n  order_id uuid references orders(id) on delete set null,\n  subject text not null check (subject ~ '^(c|e):[0-9a-f-]{32,64}$'),\n  slot_id bigint references coupon_slots(id) on delete set null,\n  amount_jpy integer not null default 0 check (amount_jpy >= 0),\n  status text not null default 'held' check (status in ('held', 'used', 'released')),\n  created_at timestamptz not null default now()\n);\n-- 1 人あたりの回数: そのキャンペーン × その人の、戻していない行だけを索引で引く\ncreate index coupon_redemptions_subject on coupon_redemptions(campaign_id, subject) where status <> 'released';\ncreate index on coupon_redemptions(reservation_id);\ncreate index on coupon_redemptions(order_id) where order_id is not null;\ncreate index on coupon_redemptions(shop_id, campaign_id);\n\n-- ---------- 予約・注文に値引きを残す ----------\n-- discount_jpy は値引きの合計（商品の値引き + 送料の値引き）。合計 = 小計 + 送料 - discount_jpy\n-- discounts は適用したクーポンのスナップショット [{campaign_id, code, name, kind, amount_jpy}]\n-- 商品ごとの値引き（税率ごとの区分に使う）は予約の items の discount_jpy と order_items.discount_jpy\nalter table reservations add column discount_jpy integer not null default 0 check (discount_jpy >= 0);\nalter table reservations add column discounts jsonb;\nalter table orders add column discount_jpy integer not null default 0 check (discount_jpy >= 0);\nalter table orders add column discounts jsonb;\n-- 決済事業者が受け取った額（照合用。Banto の計算と違えば管理画面で知らせる）\nalter table orders add column amount_paid_jpy integer;\nalter table order_items add column discount_jpy integer not null default 0 check (discount_jpy >= 0);\n\n-- ---------- RLS ----------\nalter table coupon_campaigns enable row level security;\nalter table coupon_slots enable row level security;\nalter table coupon_redemptions enable row level security;\n-- owner は自ショップのキャンペーンを管理する。購入者（anon / 会員）は直接読めない（判定は service_role の RPC 経由）\ncreate policy coupon_campaigns_owner on coupon_campaigns for all\n  using (banto_owns_shop(shop_id)) with check (banto_owns_shop(shop_id));\ncreate policy coupon_slots_owner_select on coupon_slots for select using (banto_owns_shop(shop_id));\ncreate policy coupon_redemptions_owner_select on coupon_redemptions for select using (banto_owns_shop(shop_id));\n\n-- ---------- 枠の数を上限に合わせる ----------\n-- owner がキャンペーンを作る・上限を変えると、空き枠を足す / 減らす。使用中・使用済みの枠より少なくはできない。\n-- 上限を後から付けた場合、それまでの使用は数えない（上限は設定した時点からの数）\ncreate or replace function banto_sync_coupon_slots()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_taken integer; v_have integer;\nbegin\n  if new.usage_limit is null then\n    delete from coupon_slots where campaign_id = new.id and status = 'free';\n    return new;\n  end if;\n  select count(*) filter (where status <> 'free'), count(*) into v_taken, v_have from coupon_slots where campaign_id = new.id;\n  if new.usage_limit < v_taken then\n    raise exception 'usage_limit_below_used' using detail = v_taken::text;\n  end if;\n  if v_have < new.usage_limit then\n    insert into coupon_slots (campaign_id, shop_id)\n    select new.id, new.shop_id from generate_series(1, new.usage_limit - v_have);\n  elsif v_have > new.usage_limit then\n    delete from coupon_slots where id in (\n      select id from coupon_slots where campaign_id = new.id and status = 'free' limit v_have - new.usage_limit\n    );\n  end if;\n  return new;\nend;\n$$;\ncreate trigger coupon_campaigns_slots after insert or update of usage_limit on coupon_campaigns\n  for each row execute function banto_sync_coupon_slots();\nrevoke execute on function banto_sync_coupon_slots() from public, anon, authenticated;\n\n-- ---------- 判定の材料（service_role） ----------\n-- コードからキャンペーンを引く（索引で 1 件ずつ）。subject があれば、その人の使用回数も返す。\n-- 全体の上限は「空き枠が 1 つでもあるか」だけを見る（数えない）\ncreate or replace function coupon_lookup(p_shop_id uuid, p_codes text[], p_subject text default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_out jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'coupon_lookup: service_role only' using errcode = '42501';\n  end if;\n  select coalesce(jsonb_agg(jsonb_build_object(\n      'id', c.id, 'name', c.name, 'code', c.code, 'kind', c.kind, 'value', c.value,\n      'starts_at', c.starts_at, 'ends_at', c.ends_at, 'usage_limit', c.usage_limit, 'per_customer_limit', c.per_customer_limit,\n      'combinable', c.combinable, 'audience', c.audience, 'conditions', c.conditions, 'active', c.active,\n      'used_by_subject', case when p_subject is null or c.per_customer_limit is null then 0 else (\n        select count(*) from coupon_redemptions r where r.campaign_id = c.id and r.subject = p_subject and r.status <> 'released') end,\n      'available', c.usage_limit is null or exists (select 1 from coupon_slots s where s.campaign_id = c.id and s.status = 'free')\n    )), '[]'::jsonb)\n    into v_out\n    from coupon_campaigns c\n   where c.shop_id = p_shop_id and c.code = any (select upper(btrim(x)) from unnest(coalesce(p_codes, '{}'::text[])) x limit 5);\n  return v_out;\nend;\n$$;\n\n-- ---------- 予約に値引きを付け、回数を予約する（service_role） ----------\n-- placeOrder が reserve_stock → attach_reservation_customer の直後に呼ぶ。金額は Worker の discounts.ts が計算した値\n-- （service_role からしか呼べない）。ここでは回数と期間・有効状態だけを確かめ直す。1 つでも取れなければ全体を取り消し、\n-- 呼び出し側が予約ごと解放する。\n--   p_discounts: { total_jpy, lines: [{sku_id, discount_jpy}], applied: [{campaign_id, code, name, kind, amount_jpy}] }\ncreate or replace function apply_reservation_discounts(p_reservation_id uuid, p_shop_id uuid, p_subject text, p_discounts jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res reservations%rowtype;\n  v_a jsonb;\n  v_c coupon_campaigns%rowtype;\n  v_used integer;\n  v_slot bigint;\n  v_total integer := coalesce((p_discounts->>'total_jpy')::integer, 0);\n  v_lines jsonb := coalesce(p_discounts->'lines', '[]'::jsonb);\n  v_subtotal integer;\n  v_items jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'apply_reservation_discounts: service_role only' using errcode = '42501';\n  end if;\n  if p_subject is null or p_subject !~ '^(c|e):[0-9a-f-]{32,64}$' then raise exception 'invalid_subject'; end if;\n  select * into v_res from reservations where id = p_reservation_id and shop_id = p_shop_id and status = 'pending' for update;\n  if not found then raise exception 'reservation_not_found' using detail = p_reservation_id::text; end if;\n  select coalesce(sum((e->>'qty')::integer * (e->>'unit_price_jpy')::integer), 0) into v_subtotal from jsonb_array_elements(v_res.items) e;\n  if v_total < 0 or v_total > v_subtotal + v_res.shipping_jpy then raise exception 'invalid_discount'; end if;\n\n  for v_a in select e from jsonb_array_elements(coalesce(p_discounts->'applied', '[]'::jsonb)) e loop\n    select * into v_c from coupon_campaigns where id = (v_a->>'campaign_id')::uuid and shop_id = p_shop_id;\n    if not found or not v_c.active or (v_c.starts_at is not null and v_c.starts_at > now()) or (v_c.ends_at is not null and v_c.ends_at < now()) then\n      raise exception 'coupon_unavailable' using detail = coalesce(v_a->>'code', '');\n    end if;\n    -- 会員限定は会員の subject だけ（Worker 側でも判定済み。ここは念のための二重の確認）\n    if v_c.audience = 'members' and p_subject !~ '^c:' then\n      raise exception 'coupon_unavailable' using detail = coalesce(v_c.code, '');\n    end if;\n    -- 1 人あたり: 同じ人の同時の申込みだけを直列にする（他の人は待たない）\n    if v_c.per_customer_limit is not null then\n      perform pg_advisory_xact_lock(hashtextextended(v_c.id::text || '|' || p_subject, 0));\n      select count(*) into v_used from coupon_redemptions where campaign_id = v_c.id and subject = p_subject and status <> 'released';\n      if v_used >= v_c.per_customer_limit then raise exception 'coupon_limit_reached' using detail = coalesce(v_c.code, ''); end if;\n    end if;\n    -- 全体の上限: 誰も触っていない空き枠を 1 つ取る\n    v_slot := null;\n    if v_c.usage_limit is not null then\n      update coupon_slots set status = 'held', reservation_id = p_reservation_id\n       where id = (select id from coupon_slots where campaign_id = v_c.id and status = 'free' limit 1 for update skip locked)\n      returning id into v_slot;\n      if v_slot is null then raise exception 'coupon_exhausted' using detail = coalesce(v_c.code, ''); end if;\n    end if;\n    insert into coupon_redemptions (shop_id, campaign_id, reservation_id, subject, slot_id, amount_jpy)\n    values (p_shop_id, v_c.id, p_reservation_id, p_subject, v_slot, greatest(0, coalesce((v_a->>'amount_jpy')::integer, 0)));\n  end loop;\n\n  -- 商品ごとの値引きを予約の items に書き込む\n  select jsonb_agg(e || jsonb_build_object('discount_jpy',\n           least((e->>'qty')::integer * (e->>'unit_price_jpy')::integer,\n                 greatest(0, coalesce((select (l->>'discount_jpy')::integer from jsonb_array_elements(v_lines) l where l->>'sku_id' = e->>'sku_id' limit 1), 0)))))\n    into v_items from jsonb_array_elements(v_res.items) e;\n  update reservations set discount_jpy = v_total, discounts = p_discounts->'applied', items = coalesce(v_items, items) where id = p_reservation_id;\n  return jsonb_build_object('discount_jpy', v_total);\nend;\n$$;\n\n-- ---------- 枠と使用の記録を戻す（解放・キャンセルで共通） ----------\ncreate or replace function banto_release_coupons(p_reservation_id uuid)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  update coupon_slots set status = 'free', reservation_id = null where reservation_id = p_reservation_id;\n  update coupon_redemptions set status = 'released' where reservation_id = p_reservation_id and status <> 'released';\nend;\n$$;\nrevoke execute on function banto_release_coupons(uuid) from public, anon, authenticated;\n\n-- ---------- 解放（0002 を差し替え: クーポンの枠と使用の記録も戻す） ----------\ncreate or replace function release_reservation(p_reservation_id uuid, p_shop_id uuid)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res reservations%rowtype;\n  v_item jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'release_reservation: service_role only' using errcode = '42501';\n  end if;\n  select * into v_res from reservations\n   where id = p_reservation_id and shop_id = p_shop_id\n   for update;\n  if not found or v_res.status <> 'pending' then\n    return false;\n  end if;\n  for v_item in select e from jsonb_array_elements(v_res.items) e order by e->>'sku_id' loop\n    update inventory set available = available + (v_item->>'qty')::integer, updated_at = now()\n     where sku_id = (v_item->>'sku_id')::uuid and shop_id = p_shop_id;\n  end loop;\n  perform banto_release_coupons(p_reservation_id);\n  update reservations set status = 'released', customer = null where id = p_reservation_id;\n  return true;\nend;\n$$;\n\ncreate or replace function release_expired_reservations()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res record;\n  v_item jsonb;\n  v_count integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'release_expired_reservations: service_role only' using errcode = '42501';\n  end if;\n  for v_res in\n    select id, shop_id, items from reservations\n     where status = 'pending' and expires_at < now()\n     for update skip locked\n  loop\n    for v_item in select e from jsonb_array_elements(v_res.items) e order by e->>'sku_id' loop\n      update inventory set available = available + (v_item->>'qty')::integer, updated_at = now()\n       where sku_id = (v_item->>'sku_id')::uuid and shop_id = v_res.shop_id;\n    end loop;\n    perform banto_release_coupons(v_res.id);\n    update reservations set status = 'released', customer = null where id = v_res.id;\n    v_count := v_count + 1;\n  end loop;\n  return v_count;\nend;\n$$;\n\n-- ---------- 注文確定（0004 を差し替え: 値引き・決済額・クーポンの確定） ----------\ncreate or replace function confirm_reservation(p_reservation_id uuid, p_shop_id uuid, p_order jsonb default '{}'::jsonb)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res reservations%rowtype;\n  v_order_id uuid;\n  v_item jsonb;\n  v_updated integer;\n  v_subtotal integer;\n  v_total integer;\n  v_number integer;\n  v_threshold integer;\n  v_available integer;\n  v_payload jsonb;\n  v_r record;\n  v_slot bigint;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'confirm_reservation: service_role only' using errcode = '42501';\n  end if;\n\n  select * into v_res from reservations\n   where id = p_reservation_id and shop_id = p_shop_id\n   for update;\n  if not found then\n    raise exception 'reservation_not_found' using detail = p_reservation_id::text;\n  end if;\n\n  select id into v_order_id from orders where reservation_id = p_reservation_id;\n  if found then\n    return v_order_id;\n  end if;\n\n  if v_res.status = 'released' then\n    for v_item in select e from jsonb_array_elements(v_res.items) e order by e->>'sku_id' loop\n      update inventory\n         set available = available - (v_item->>'qty')::integer, updated_at = now()\n       where sku_id = (v_item->>'sku_id')::uuid and shop_id = p_shop_id\n         and available >= (v_item->>'qty')::integer;\n      get diagnostics v_updated = row_count;\n      if v_updated = 0 then\n        raise exception 'insufficient_stock_after_release' using detail = v_item->>'sku_id';\n      end if;\n    end loop;\n    -- 決済は値引き後の額で済んでいるので、値引きはそのまま有効にする。戻した枠は空いていれば取り直す\n    -- （空きが無ければ枠なしで使用済みにする。上限を 1 回超えることがあるが、購入者はもう支払っている）\n    for v_r in select id, campaign_id from coupon_redemptions where reservation_id = p_reservation_id and status = 'released' loop\n      update coupon_slots set status = 'held', reservation_id = p_reservation_id\n       where id = (select id from coupon_slots where campaign_id = v_r.campaign_id and status = 'free' limit 1 for update skip locked)\n      returning id into v_slot;\n      update coupon_redemptions set status = 'held', slot_id = v_slot where id = v_r.id;\n    end loop;\n  end if;\n\n  select coalesce(sum((e->>'qty')::integer * (e->>'unit_price_jpy')::integer), 0)\n    into v_subtotal\n    from jsonb_array_elements(v_res.items) e;\n  v_total := greatest(0, v_subtotal + v_res.shipping_jpy - v_res.discount_jpy);\n\n  -- ショップごとの注文番号（shops の行ロックで直列化）\n  update shops set order_seq = order_seq + 1 where id = p_shop_id returning order_seq into v_number;\n\n  insert into orders (shop_id, reservation_id, status, total_jpy, shipping_jpy, discount_jpy, discounts, amount_paid_jpy, number, customer_id,\n                      customer_email, customer_name, shipping_address, payment_provider, payment_ref)\n  values (p_shop_id, p_reservation_id, 'paid', v_total, v_res.shipping_jpy, v_res.discount_jpy, v_res.discounts,\n          nullif(p_order->>'amount_paid_jpy', '')::integer, v_number, v_res.customer_id,\n          -- Banto のフォームで集めた値を優先し、無ければ決済事業者からの値\n          coalesce(v_res.customer->>'customer_email', p_order->>'customer_email'),\n          coalesce(v_res.customer->>'customer_name', p_order->>'customer_name'),\n          coalesce(v_res.customer->'shipping_address', p_order->'shipping_address'),\n          p_order->>'payment_provider', p_order->>'payment_ref')\n  returning id into v_order_id;\n\n  insert into order_items (shop_id, order_id, sku_id, qty, unit_price_jpy, discount_jpy)\n  select p_shop_id, v_order_id, (e->>'sku_id')::uuid, (e->>'qty')::integer, (e->>'unit_price_jpy')::integer, coalesce((e->>'discount_jpy')::integer, 0)\n    from jsonb_array_elements(v_res.items) e;\n\n  update coupon_slots set status = 'used' where reservation_id = p_reservation_id and status = 'held';\n  update coupon_redemptions set status = 'used', order_id = v_order_id where reservation_id = p_reservation_id and status = 'held';\n  update reservations set status = 'confirmed', customer = null where id = p_reservation_id;\n\n  v_payload := jsonb_build_object(\n    'order_id', v_order_id, 'order_number', v_number, 'shop_id', p_shop_id,\n    'subtotal_jpy', v_subtotal, 'shipping_jpy', v_res.shipping_jpy, 'discount_jpy', v_res.discount_jpy, 'total_jpy', v_total,\n    'status', 'paid', 'payment_provider', p_order->>'payment_provider', 'customer_id', v_res.customer_id,\n    'items', v_res.items\n  );\n  perform enqueue_hook(p_shop_id, 'order.created', v_payload);\n  perform enqueue_hook(p_shop_id, 'order.paid', v_payload);\n\n  select coalesce((s.settings->>'low_stock_threshold')::integer, 3) into v_threshold from shops s where s.id = p_shop_id;\n  for v_item in select e from jsonb_array_elements(v_res.items) e loop\n    select available into v_available from inventory where sku_id = (v_item->>'sku_id')::uuid;\n    if v_available is not null and v_available <= v_threshold then\n      perform enqueue_hook(p_shop_id, 'inventory.low',\n        jsonb_build_object('shop_id', p_shop_id, 'sku_id', v_item->>'sku_id', 'available', v_available, 'threshold', v_threshold));\n    end if;\n  end loop;\n\n  return v_order_id;\nend;\n$$;\n\n-- ---------- キャンセル（0004 を差し替え: クーポンの回数も戻す。WooCommerce と同じ） ----------\ncreate or replace function cancel_order(p_order_id uuid, p_shop_id uuid, p_refunded boolean)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_o orders%rowtype; v_item record;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'cancel_order: service_role only' using errcode = '42501';\n  end if;\n  select * into v_o from orders where id = p_order_id and shop_id = p_shop_id for update;\n  if not found then raise exception 'not_found'; end if;\n  if v_o.status in ('cancelled', 'refunded') then\n    return jsonb_build_object('order_id', v_o.id, 'status', v_o.status, 'already', true);\n  end if;\n  if v_o.status <> 'paid' then raise exception 'not_cancellable' using detail = v_o.status::text; end if;\n  for v_item in select sku_id, qty from order_items where order_id = p_order_id loop\n    update inventory set available = available + v_item.qty, updated_at = now()\n     where sku_id = v_item.sku_id and shop_id = p_shop_id;\n  end loop;\n  if v_o.reservation_id is not null then perform banto_release_coupons(v_o.reservation_id); end if;\n  update orders set status = case when p_refunded then 'refunded'::order_status else 'cancelled'::order_status end\n   where id = p_order_id;\n  perform enqueue_hook(p_shop_id, 'order.cancelled',\n    jsonb_build_object('order_id', v_o.id, 'order_number', v_o.number, 'shop_id', p_shop_id, 'total_jpy', v_o.total_jpy,\n                       'status', case when p_refunded then 'refunded' else 'cancelled' end, 'refunded', p_refunded, 'customer_id', v_o.customer_id));\n  return jsonb_build_object('order_id', v_o.id, 'status', case when p_refunded then 'refunded' else 'cancelled' end, 'already', false,\n                            'payment_provider', v_o.payment_provider, 'payment_ref', v_o.payment_ref);\nend;\n$$;\n\n-- ---------- 注文の表示に値引きを足す（0004 を差し替え） ----------\n-- 値引きは、コード・名前・額だけを出す（キャンペーンの条件は出さない）\ncreate or replace function lookup_order(p_shop_id uuid, p_number integer, p_email text)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object('number', o.number, 'status', o.status, 'created_at', o.created_at, 'shipped_at', o.shipped_at,\n                            'total_jpy', o.total_jpy, 'shipping_jpy', o.shipping_jpy, 'discount_jpy', o.discount_jpy,\n                            'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                                            from jsonb_array_elements(coalesce(o.discounts, '[]'::jsonb)) d),\n                            'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy) order by oi.id), '[]'::jsonb)\n                                        from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = o.id))\n    from orders o join shops s on s.id = o.shop_id\n   where o.shop_id = p_shop_id and o.number = p_number and s.published\n     and o.customer_email is not null and lower(o.customer_email) = lower(btrim(p_email))\n   limit 1;\n$$;\n\ncreate or replace function order_contact(p_order_id uuid, p_shop_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_o orders%rowtype; v_s shops%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'order_contact: service_role only' using errcode = '42501';\n  end if;\n  select * into v_o from orders where id = p_order_id and shop_id = p_shop_id;\n  if not found then raise exception 'not_found'; end if;\n  select * into v_s from shops where id = p_shop_id;\n  return jsonb_build_object(\n    'order_id', v_o.id, 'number', v_o.number, 'status', v_o.status, 'created_at', v_o.created_at,\n    'total_jpy', v_o.total_jpy, 'shipping_jpy', v_o.shipping_jpy, 'discount_jpy', v_o.discount_jpy, 'payment_provider', v_o.payment_provider,\n    'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                    from jsonb_array_elements(coalesce(v_o.discounts, '[]'::jsonb)) d),\n    'customer_email', v_o.customer_email, 'customer_name', v_o.customer_name, 'shipping_address', v_o.shipping_address,\n    'shop', jsonb_build_object('name', v_s.name, 'slug', v_s.slug,\n                               'contact_email', v_s.settings->>'contact_email', 'return_policy', v_s.return_policy),\n    'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy) order by oi.id), '[]'::jsonb)\n                from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = v_o.id));\nend;\n$$;\n\ncreate or replace function api_order_json(p_order orders, p_pii boolean)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_order.id, 'number', p_order.number, 'status', p_order.status, 'total_jpy', p_order.total_jpy, 'shipping_jpy', p_order.shipping_jpy,\n    'discount_jpy', p_order.discount_jpy,\n    'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                    from jsonb_array_elements(coalesce(p_order.discounts, '[]'::jsonb)) d),\n    'payment_provider', p_order.payment_provider, 'payment_ref', p_order.payment_ref, 'customer_id', p_order.customer_id,\n    'shipped_at', p_order.shipped_at, 'created_at', p_order.created_at, 'updated_at', p_order.updated_at,\n    'customer', case when p_pii then jsonb_build_object(\n        'email', p_order.customer_email, 'name', p_order.customer_name, 'shipping_address', p_order.shipping_address)\n      else jsonb_build_object('masked', true, 'prefecture', p_order.shipping_address->>'state') end,\n    'items', (select coalesce(jsonb_agg(jsonb_build_object(\n                 'sku_id', oi.sku_id, 'sku_code', k.code, 'sku_name', k.name, 'product_id', k.product_id, 'product_name', p.name,\n                 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy, 'discount_jpy', oi.discount_jpy) order by oi.id), '[]'::jsonb)\n                from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id\n               where oi.order_id = p_order.id)\n  );\n$$;\n\n-- ---------- 管理画面の集計（owner） ----------\n-- キャンペーンごとの使用済み・予約中の回数。所有していないショップなら null\ncreate or replace function coupon_stats(p_shop_id uuid)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when banto_owns_shop(p_shop_id) then coalesce((\n    select jsonb_object_agg(campaign_id, jsonb_build_object('used', used, 'held', held))\n      from (select campaign_id, count(*) filter (where status = 'used') as used, count(*) filter (where status = 'held') as held\n              from coupon_redemptions where shop_id = p_shop_id group by campaign_id) x), '{}'::jsonb) end;\n$$;\nrevoke execute on function coupon_stats(uuid) from public, anon;\ngrant execute on function coupon_stats(uuid) to authenticated, service_role;\n\nrevoke execute on function coupon_lookup(uuid, text[], text) from public, anon, authenticated;\nrevoke execute on function apply_reservation_discounts(uuid, uuid, text, jsonb) from public, anon, authenticated;\ngrant execute on function coupon_lookup(uuid, text[], text) to service_role;\ngrant execute on function apply_reservation_discounts(uuid, uuid, text, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0010_coupons');\n" },
  { version: "0011_customer_import", sql: "-- Banto 0011_customer_import: 会員の一括取り込み（WooCommerce からの移行。docs/members.md）\n-- 前方専用。\n--\n-- 会員 = Supabase Auth のユーザー + ショップごとの customers 行（0004）。取り込みは管理画面のインポーターが行う:\n--   1. banto_users_by_email で、メールアドレスがすでに Auth にあるかを引く\n--   2. 無ければ Auth の管理 API でユーザーを作る（パスワードなし、メール確認済み。会員はメールでのログインか再設定でパスワードを決める）\n--   3. import_customers で customers 行を作る / 足りない項目だけ埋める（会員が自分で入れた値は上書きしない）\n-- どちらも service_role だけ。呼び出し側（管理画面）が owner の JWT でショップの所有を確かめてから呼ぶ（restore_shop_data と同じ）。\n-- パスワード（WordPress のハッシュ）は扱わない（形式が Supabase と合わず、Banto に機微な情報を持たないため）。\n\ncreate or replace function banto_users_by_email(p_emails text[])\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_out jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'banto_users_by_email: service_role only' using errcode = '42501';\n  end if;\n  select coalesce(jsonb_object_agg(lower(u.email), u.id), '{}'::jsonb) into v_out\n    from auth.users u\n   where lower(u.email) = any (select lower(btrim(x)) from unnest(coalesce(p_emails, '{}'::text[])) x limit 100);\n  return v_out;\nend;\n$$;\n\n-- p_rows: [{ user_id, email, name, default_address }]（最大 100 件）\ncreate or replace function import_customers(p_shop_id uuid, p_rows jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb;\n  v_created integer := 0;\n  v_updated integer := 0;\n  v_exists boolean;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'import_customers: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id) then raise exception 'shop_not_found'; end if;\n  if jsonb_array_length(coalesce(p_rows, '[]'::jsonb)) > 100 then raise exception 'too_many_rows'; end if;\n  for v_row in select e from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) e loop\n    if not exists (select 1 from auth.users where id = (v_row->>'user_id')::uuid) then raise exception 'user_not_found' using detail = coalesce(v_row->>'email', ''); end if;\n    select exists (select 1 from customers where shop_id = p_shop_id and id = (v_row->>'user_id')::uuid) into v_exists;\n    insert into customers (id, shop_id, email, name, default_address)\n    values ((v_row->>'user_id')::uuid, p_shop_id, nullif(left(btrim(coalesce(v_row->>'email', '')), 200), ''),\n            nullif(left(btrim(coalesce(v_row->>'name', '')), 200), ''),\n            case when jsonb_typeof(v_row->'default_address') = 'object' then v_row->'default_address' end)\n    on conflict (shop_id, id) do update\n       set email = coalesce(customers.email, excluded.email),\n           name = coalesce(customers.name, excluded.name),\n           default_address = coalesce(customers.default_address, excluded.default_address);\n    if v_exists then v_updated := v_updated + 1; else v_created := v_created + 1; end if;\n  end loop;\n  return jsonb_build_object('created', v_created, 'updated', v_updated);\nend;\n$$;\n\nrevoke execute on function banto_users_by_email(text[]) from public, anon, authenticated;\nrevoke execute on function import_customers(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function banto_users_by_email(text[]) to service_role;\ngrant execute on function import_customers(uuid, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0011_customer_import');\n" },
  { version: "0012_member_auth", sql: "-- Banto 0012_member_auth: 会員のアカウントを店ごとに Banto が持つ（docs/knowledge/10-members-identity.md）\n-- 前方専用。\n--\n-- 会員 = ショップごとの customers 行（Supabase Auth のユーザーではなくなる）。運営者は今までどおり Supabase Auth。\n-- ログインはパスワードなし: メールに届く 6 桁のコードか、ログインのリンク。\n--   - コード・リンクのトークン・IP は Worker が HMAC（サイトの秘密）にしてから渡す。生の値は DB に来ない。\n--     DB だけが漏れても 6 桁のコードを逆算できないようにするため（素の SHA-256 なら一瞬で総当たりできる）。\n--   - 照合・回数の制限・失効・使い捨ては、すべてこのファイルの関数の中で行う（Worker の書き間違いで制限をすり抜けられないように）。\n--   - セッションは Worker の署名付き Cookie / トークン。customers.session_epoch を上げると、それより前のセッションは一斉に無効。\n-- すべて service_role だけ（member_set_email は owner）。呼び出しは src/db/privileged.ts から。\n-- 実稼働の前に入れたので、Supabase Auth 版の会員（0004 の RLS の経路・0011 の取り込み）は残さず消す。\n\n-- ---------- customers: Auth のユーザーとの結びつきを外す ----------\nalter table customers drop constraint if exists customers_id_fkey;\nalter table customers alter column id set default gen_random_uuid();\nalter table customers add column if not exists session_epoch integer not null default 0;\nalter table customers add column if not exists last_login_at timestamptz;\n-- 店の中でメールアドレスは 1 人（大文字小文字を区別しない）。照合はこの索引で引く\ncreate unique index if not exists customers_shop_email_key on customers (shop_id, lower(email)) where email is not null;\n\n-- ---------- ログインのチャレンジ（発行したコードとリンク） ----------\ncreate table member_login_challenges (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  -- 送り先（小文字）。初回のログインで会員を作るときにも使う\n  email text not null check (length(email) between 3 and 254),\n  code_hash text not null check (code_hash ~ '^[0-9a-f]{64}$'),\n  link_hash text not null check (link_hash ~ '^[0-9a-f]{64}$'),\n  ip_hash text check (ip_hash ~ '^[0-9a-f]{64}$'),\n  -- ヘッドレスのリンクの戻り先（Worker が許可リストで確かめたもの）\n  return_to text,\n  attempts smallint not null default 0,\n  created_at timestamptz not null default now(),\n  expires_at timestamptz not null,\n  consumed_at timestamptz\n);\ncreate index member_login_challenges_email_idx on member_login_challenges (shop_id, email, created_at);\ncreate index member_login_challenges_ip_idx on member_login_challenges (shop_id, ip_hash, created_at) where ip_hash is not null;\nalter table member_login_challenges enable row level security;\n-- 誰にも見せない（service_role は RLS を通らない。関数からだけ触る）\ncreate policy member_login_challenges_none on member_login_challenges for select using (false);\n\n-- ---------- ログインを始める ----------\n-- 回数の制限（10-members-identity.md §6）: 同じ人（店 × メールアドレス）に 15 分で 5 回・1 日 20 回、同じ IP から 1 時間に 30 回。\n-- 超えたら送らない。応答の形は変えない（send = false と、使われない ID）。\n-- 送信元は、そのショップで有効な同梱のメールプラグイン（Resend）の「送信元」。無ければ mail_not_configured。\n-- 戻り値: { send, challenge_id, mail_from }\ncreate or replace function member_login_start(p_shop_id uuid, p_email text, p_code_hash text, p_link_hash text, p_ip_hash text, p_return_to text, p_ttl_seconds integer default 900)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_email text := lower(btrim(coalesce(p_email, '')));\n  v_from text;\n  v_id uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_login_start: service_role only' using errcode = '42501';\n  end if;\n  if length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  if not exists (select 1 from shops where id = p_shop_id and coalesce(settings->>'members_enabled', 'false') = 'true') then\n    raise exception 'members_disabled';\n  end if;\n  select nullif(btrim(e.settings->>'from'), '') into v_from\n    from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and e.url = 'https://banto.invalid/plugins/email_resend'\n   limit 1;\n  if v_from is null then raise exception 'mail_not_configured'; end if;\n\n  -- 同じ人の同時の申込みだけを直列にする（数えてから入れるまでの間に割り込まれないように）\n  perform pg_advisory_xact_lock(hashtextextended('member_login|' || p_shop_id::text || '|' || v_email, 0));\n  if (select count(*) from member_login_challenges where shop_id = p_shop_id and email = v_email and created_at > now() - interval '15 minutes') >= 5\n     or (select count(*) from member_login_challenges where shop_id = p_shop_id and email = v_email and created_at > now() - interval '1 day') >= 20\n     or (p_ip_hash is not null and (select count(*) from member_login_challenges where shop_id = p_shop_id and ip_hash = p_ip_hash and created_at > now() - interval '1 hour') >= 30) then\n    return jsonb_build_object('send', false, 'challenge_id', gen_random_uuid(), 'mail_from', v_from);\n  end if;\n\n  -- 有効なコードは常に 1 つ（前のコードを無効にする。出し直しで試せる数を増やさない）\n  update member_login_challenges set consumed_at = now()\n   where shop_id = p_shop_id and email = v_email and consumed_at is null;\n  insert into member_login_challenges (shop_id, email, code_hash, link_hash, ip_hash, return_to, expires_at)\n  values (p_shop_id, v_email, p_code_hash, p_link_hash, p_ip_hash, nullif(left(p_return_to, 500), ''),\n          now() + make_interval(secs => greatest(60, least(coalesce(p_ttl_seconds, 900), 3600))))\n  returning id into v_id;\n  return jsonb_build_object('send', true, 'challenge_id', v_id, 'mail_from', v_from);\nend;\n$$;\n\n-- ---------- 照合する ----------\n-- コード（p_code_hash）かリンクのトークン（p_link_hash）のどちらか。5 回間違えたらそのチャレンジは無効。\n-- 失敗は例外にしない（例外にすると間違えた回数の加算まで取り消される）。\n-- 成功したら使用済みにし、会員を引く（無ければ作る = 初回のログインが会員登録）。\n-- 戻り値: { ok: true, customer_id, session_epoch, email, created, return_to } / { ok: false, reason: 'invalid' | 'expired' }\ncreate or replace function member_login_verify(p_shop_id uuid, p_challenge_id uuid, p_code_hash text, p_link_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_ch member_login_challenges%rowtype;\n  v_customer customers%rowtype;\n  v_created boolean := false;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_login_verify: service_role only' using errcode = '42501';\n  end if;\n  -- 同じチャレンジを同時に照合しても、成功は 1 回だけ\n  select * into v_ch from member_login_challenges where id = p_challenge_id and shop_id = p_shop_id for update;\n  if not found then return jsonb_build_object('ok', false, 'reason', 'invalid'); end if;\n  if v_ch.consumed_at is not null or v_ch.expires_at < now() or v_ch.attempts >= 5 then\n    return jsonb_build_object('ok', false, 'reason', 'expired');\n  end if;\n  if not ((p_code_hash is not null and v_ch.code_hash = p_code_hash) or (p_link_hash is not null and v_ch.link_hash = p_link_hash)) then\n    update member_login_challenges\n       set attempts = attempts + 1,\n           consumed_at = case when attempts + 1 >= 5 then now() else consumed_at end\n     where id = v_ch.id;\n    return jsonb_build_object('ok', false, 'reason', case when v_ch.attempts + 1 >= 5 then 'expired' else 'invalid' end);\n  end if;\n  update member_login_challenges set consumed_at = now() where id = v_ch.id;\n  if not exists (select 1 from shops where id = p_shop_id and coalesce(settings->>'members_enabled', 'false') = 'true') then\n    return jsonb_build_object('ok', false, 'reason', 'expired');\n  end if;\n\n  select * into v_customer from customers where shop_id = p_shop_id and lower(email) = v_ch.email;\n  if not found then\n    insert into customers (shop_id, email) values (p_shop_id, v_ch.email)\n    on conflict (shop_id, lower(email)) where email is not null do nothing\n    returning * into v_customer;\n    if v_customer.id is null then\n      select * into v_customer from customers where shop_id = p_shop_id and lower(email) = v_ch.email;\n    else\n      v_created := true;\n    end if;\n  end if;\n  update customers set last_login_at = now() where shop_id = p_shop_id and id = v_customer.id;\n  return jsonb_build_object('ok', true, 'customer_id', v_customer.id, 'session_epoch', v_customer.session_epoch,\n                            'email', v_customer.email, 'created', v_created, 'return_to', v_ch.return_to);\nend;\n$$;\n\n-- メールのリンクを開いた先の確認画面に出すアドレス（使わない・数えない。トークンは推測できない長さなので回数の制限は要らない）。\n-- 合わない・期限切れなら null。画面にはアドレスを伏せて出す（他人のリンクを踏まされたときに気づけるように）\ncreate or replace function member_login_peek(p_shop_id uuid, p_challenge_id uuid, p_link_hash text)\nreturns text\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when auth.role() = 'service_role' then (\n    select email from member_login_challenges\n     where id = p_challenge_id and shop_id = p_shop_id and link_hash = p_link_hash\n       and consumed_at is null and expires_at > now() and attempts < 5) end;\n$$;\n\n-- ---------- ログイン中の会員の読み書き（世代が合うときだけ） ----------\n-- 会員の行と、このショップでの注文（新しい順に 50 件）。世代が違う・退会済みなら null\ncreate or replace function member_get(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_with_orders boolean default false)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_c customers%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_get: service_role only' using errcode = '42501';\n  end if;\n  select * into v_c from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch;\n  if not found then return null; end if;\n  return jsonb_build_object(\n    'customer', jsonb_build_object('id', v_c.id, 'shop_id', v_c.shop_id, 'email', v_c.email, 'name', v_c.name, 'default_address', v_c.default_address),\n    'orders', case when p_with_orders then coalesce((\n      select jsonb_agg(o order by o.created_at desc) from (\n        select id, number, status, total_jpy, shipping_jpy, coalesce(discount_jpy, 0) as discount_jpy, created_at, shipped_at\n          from orders where shop_id = p_shop_id and customer_id = p_customer_id\n         order by created_at desc limit 50) o), '[]'::jsonb) else '[]'::jsonb end);\nend;\n$$;\n\ncreate or replace function member_save_address(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_name text, p_address jsonb)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_save_address: service_role only' using errcode = '42501';\n  end if;\n  update customers\n     set name = nullif(left(btrim(coalesce(p_name, '')), 200), ''),\n         default_address = case when jsonb_typeof(p_address) = 'object' then p_address end\n   where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch;\n  return found;\nend;\n$$;\n\n-- 退会: customers 行を消す（注文は残る）\ncreate or replace function member_withdraw(p_shop_id uuid, p_customer_id uuid, p_epoch integer)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_withdraw: service_role only' using errcode = '42501';\n  end if;\n  delete from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch;\n  return found;\nend;\n$$;\n\n-- 全端末からログアウト（世代を上げる）\ncreate or replace function member_logout_all(p_shop_id uuid, p_customer_id uuid, p_epoch integer)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_logout_all: service_role only' using errcode = '42501';\n  end if;\n  update customers set session_epoch = session_epoch + 1\n   where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch;\n  return found;\nend;\n$$;\n\n-- ---------- 運営者が会員のメールアドレスを変える（メールを失った会員の救済） ----------\n-- owner の JWT で呼ぶ。世代を上げて今のセッションを無効にする。前後のアドレスへの知らせは Worker が送る。\n-- 戻り値: { old_email, new_email }\ncreate or replace function member_set_email(p_shop_id uuid, p_customer_id uuid, p_email text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_email text := lower(btrim(coalesce(p_email, '')));\n  v_old text;\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  select email into v_old from customers where shop_id = p_shop_id and id = p_customer_id for update;\n  if not found then raise exception 'customer_not_found'; end if;\n  if exists (select 1 from customers where shop_id = p_shop_id and lower(email) = v_email and id <> p_customer_id) then\n    raise exception 'email_taken';\n  end if;\n  update customers set email = v_email, session_epoch = session_epoch + 1 where shop_id = p_shop_id and id = p_customer_id;\n  -- 未使用のチャレンジは前のアドレスのものも含めて無効にする\n  update member_login_challenges set consumed_at = now()\n   where shop_id = p_shop_id and email in (lower(coalesce(v_old, '')), v_email) and consumed_at is null;\n  return jsonb_build_object('old_email', v_old, 'new_email', v_email);\nend;\n$$;\n\n-- ---------- 一括取り込み（WooCommerce から。0011 の import_customers の置き換え） ----------\n-- p_rows: [{ email, name, default_address }]（最大 100 件）。メールアドレスで引き、無ければ作る。足りない項目だけ埋める\ncreate or replace function import_members(p_shop_id uuid, p_rows jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb;\n  v_email text;\n  v_created integer := 0;\n  v_updated integer := 0;\n  v_skipped integer := 0;\n  v_new boolean;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'import_members: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id) then raise exception 'shop_not_found'; end if;\n  if jsonb_array_length(coalesce(p_rows, '[]'::jsonb)) > 100 then raise exception 'too_many_rows'; end if;\n  for v_row in select e from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) e loop\n    v_email := lower(btrim(coalesce(v_row->>'email', '')));\n    if length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then\n      v_skipped := v_skipped + 1;\n      continue;\n    end if;\n    insert into customers (shop_id, email, name, default_address)\n    values (p_shop_id, v_email, nullif(left(btrim(coalesce(v_row->>'name', '')), 200), ''),\n            case when jsonb_typeof(v_row->'default_address') = 'object' then v_row->'default_address' end)\n    on conflict (shop_id, lower(email)) where email is not null do update\n       set name = coalesce(customers.name, excluded.name),\n           default_address = coalesce(customers.default_address, excluded.default_address)\n    returning (xmax = 0) into v_new;\n    if v_new then v_created := v_created + 1; else v_updated := v_updated + 1; end if;\n  end loop;\n  return jsonb_build_object('created', v_created, 'updated', v_updated, 'skipped', v_skipped);\nend;\n$$;\n\n-- ---------- 予約に会員を付けるときに世代を確かめる（0004 の attach を差し替え） ----------\n-- p_customer.customer_id があるときは p_customer.customer_epoch が今の世代と一致すること（全端末からログアウトした後の古いセッションで注文させない）\ncreate or replace function attach_reservation_customer(p_reservation_id uuid, p_shop_id uuid, p_customer jsonb)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_shipping integer; v_customer_id uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'attach_reservation_customer: service_role only' using errcode = '42501';\n  end if;\n  v_shipping := coalesce((p_customer->>'shipping_jpy')::integer, 0);\n  if v_shipping < 0 then raise exception 'invalid_shipping'; end if;\n  v_customer_id := nullif(p_customer->>'customer_id', '')::uuid;\n  if v_customer_id is not null and not exists (\n       select 1 from customers where shop_id = p_shop_id and id = v_customer_id\n          and session_epoch = coalesce(nullif(p_customer->>'customer_epoch', '')::integer, -1)) then\n    raise exception 'member_session_invalid';\n  end if;\n  update reservations\n     set customer = p_customer - 'shipping_jpy' - 'customer_id' - 'customer_epoch',\n         shipping_jpy = v_shipping,\n         customer_id = v_customer_id\n   where id = p_reservation_id and shop_id = p_shop_id and status = 'pending';\n  if not found then\n    raise exception 'reservation_not_found' using detail = p_reservation_id::text;\n  end if;\nend;\n$$;\n\n-- ---------- 片付け（Cron） ----------\ncreate or replace function member_login_cleanup()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_login_cleanup: service_role only' using errcode = '42501';\n  end if;\n  delete from member_login_challenges where created_at < now() - interval '2 days';\n  get diagnostics v_n = row_count;\n  return v_n;\nend;\n$$;\n\n-- ---------- Supabase Auth を前提にした会員の経路を消す（実稼働の前なので 2 段階にしない） ----------\n-- 会員は auth.uid() を持たない（service_role の member_* RPC で読み書きする）。owner の経路（customers_owner_*）は残す\ndrop policy if exists customers_self on customers;\ndrop policy if exists orders_customer_select on orders;\ndrop policy if exists order_items_customer_select on order_items;\n-- 0011 の取り込み（Auth のユーザーを作る版）は import_members に置き換えた\ndrop function if exists banto_users_by_email(text[]);\ndrop function if exists import_customers(uuid, jsonb);\n\n-- ---------- バックアップからの復元（0006 を差し替え: 会員を auth.users と突き合わせない） ----------\ncreate or replace function restore_shop_data(p_shop_id uuid, p_data jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_products jsonb := coalesce(p_data->'products', '[]'::jsonb);\n  v_skus jsonb := coalesce(p_data->'skus', '[]'::jsonb);\n  v_inventory jsonb := coalesce(p_data->'inventory', '[]'::jsonb);\n  v_images jsonb := coalesce(p_data->'product_images', '[]'::jsonb);\n  v_orders jsonb := coalesce(p_data->'orders', '[]'::jsonb);\n  v_items jsonb := coalesce(p_data->'order_items', '[]'::jsonb);\n  v_customers jsonb := coalesce(p_data->'customers', '[]'::jsonb);\n  v_endpoints jsonb := coalesce(p_data->'hook_endpoints', '[]'::jsonb);\n  v_row jsonb;\n  v_new uuid;\n  v_old uuid;\n  v_product_map jsonb := '{}'::jsonb;\n  v_sku_map jsonb := '{}'::jsonb;\n  v_order_map jsonb := '{}'::jsonb;\n  v_customer_ok jsonb := '{}'::jsonb;\n  v_counts jsonb := '{}'::jsonb;\n  v_n integer;\n  v_skipped_items integer := 0;\n  v_skipped_customers integer := 0;\n  v_max_number integer;\nbegin\n  if not exists (select 1 from shops where id = p_shop_id) then raise exception 'shop_not_found'; end if;\n  if exists (select 1 from products where shop_id = p_shop_id) or exists (select 1 from orders where shop_id = p_shop_id) then\n    raise exception 'shop_not_empty';\n  end if;\n  if jsonb_typeof(v_products) <> 'array' or jsonb_typeof(v_orders) <> 'array' then raise exception 'invalid_export'; end if;\n\n  -- 商品\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_products) loop\n    v_old := (v_row->>'id')::uuid;\n    insert into products (shop_id, slug, name, description, published, created_at, updated_at)\n      values (p_shop_id, v_row->>'slug', v_row->>'name', v_row->>'description', coalesce((v_row->>'published')::boolean, false),\n              coalesce((v_row->>'created_at')::timestamptz, now()), coalesce((v_row->>'updated_at')::timestamptz, now()))\n      returning id into v_new;\n    v_product_map := v_product_map || jsonb_build_object(v_old::text, v_new::text);\n    v_n := v_n + 1;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('products', v_n);\n\n  -- SKU（inventory 行はトリガーで作られる）→ 在庫数を戻す\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_skus) loop\n    if v_product_map ? (v_row->>'product_id') then\n      v_old := (v_row->>'id')::uuid;\n      insert into skus (shop_id, product_id, code, name, price_jpy, created_at)\n        values (p_shop_id, (v_product_map->>(v_row->>'product_id'))::uuid, v_row->>'code', v_row->>'name', (v_row->>'price_jpy')::integer,\n                coalesce((v_row->>'created_at')::timestamptz, now()))\n        returning id into v_new;\n      v_sku_map := v_sku_map || jsonb_build_object(v_old::text, v_new::text);\n      v_n := v_n + 1;\n    end if;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('skus', v_n);\n  for v_row in select * from jsonb_array_elements(v_inventory) loop\n    if v_sku_map ? (v_row->>'sku_id') then\n      update inventory set available = greatest(0, coalesce((v_row->>'available')::integer, 0))\n        where sku_id = (v_sku_map->>(v_row->>'sku_id'))::uuid and shop_id = p_shop_id;\n    end if;\n  end loop;\n\n  -- 画像（R2 のキーはそのまま）\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_images) loop\n    if v_product_map ? (v_row->>'product_id') then\n      insert into product_images (shop_id, product_id, storage_key, thumb_key, width, height, sort_order, created_at)\n        values (p_shop_id, (v_product_map->>(v_row->>'product_id'))::uuid, v_row->>'storage_key', v_row->>'thumb_key',\n                (v_row->>'width')::integer, (v_row->>'height')::integer, coalesce((v_row->>'sort_order')::integer, 0),\n                coalesce((v_row->>'created_at')::timestamptz, now()));\n      v_n := v_n + 1;\n    end if;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('product_images', v_n);\n\n  -- 会員: 0012 から会員は Supabase Auth と関係ないので、すべて戻す（同じ id のまま。主キーは (shop_id, id)）。\n  -- 同じメールアドレスが重なる行・メールアドレスの無い行は飛ばす\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_customers) loop\n    v_old := (v_row->>'id')::uuid;\n    if nullif(btrim(coalesce(v_row->>'email', '')), '') is not null\n       and not exists (select 1 from customers c where c.shop_id = p_shop_id and lower(c.email) = lower(btrim(v_row->>'email'))) then\n      insert into customers (id, shop_id, email, name, default_address, created_at)\n        values (v_old, p_shop_id, lower(btrim(v_row->>'email')), v_row->>'name', v_row->'default_address', coalesce((v_row->>'created_at')::timestamptz, now()))\n        on conflict do nothing;\n      v_customer_ok := v_customer_ok || jsonb_build_object(v_old::text, true);\n      v_n := v_n + 1;\n    else\n      v_skipped_customers := v_skipped_customers + 1;\n    end if;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('customers', v_n, 'customers_skipped', v_skipped_customers);\n\n  -- 注文（予約との紐づけは切る。番号は維持）\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_orders) loop\n    v_old := (v_row->>'id')::uuid;\n    insert into orders (shop_id, reservation_id, status, total_jpy, shipping_jpy, number, customer_email, customer_name, shipping_address,\n                        payment_provider, payment_ref, shipped_at, customer_id, created_at, updated_at)\n      values (p_shop_id, null, coalesce((v_row->>'status')::order_status, 'paid'), coalesce((v_row->>'total_jpy')::integer, 0),\n              coalesce((v_row->>'shipping_jpy')::integer, 0), (v_row->>'number')::integer, v_row->>'customer_email', v_row->>'customer_name',\n              v_row->'shipping_address', v_row->>'payment_provider', v_row->>'payment_ref', (v_row->>'shipped_at')::timestamptz,\n              case when v_customer_ok ? (v_row->>'customer_id') then (v_row->>'customer_id')::uuid else null end,\n              coalesce((v_row->>'created_at')::timestamptz, now()), coalesce((v_row->>'updated_at')::timestamptz, now()))\n      returning id into v_new;\n    v_order_map := v_order_map || jsonb_build_object(v_old::text, v_new::text);\n    v_n := v_n + 1;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('orders', v_n);\n  select max(number) into v_max_number from orders where shop_id = p_shop_id;\n  if v_max_number is not null then\n    update shops set order_seq = greatest(order_seq, v_max_number) where id = p_shop_id;\n  end if;\n\n  -- 明細（SKU が復元されていない行は飛ばす: skus.id への FK があるため）\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_items) loop\n    if v_order_map ? (v_row->>'order_id') and v_sku_map ? (v_row->>'sku_id') then\n      insert into order_items (shop_id, order_id, sku_id, qty, unit_price_jpy)\n        values (p_shop_id, (v_order_map->>(v_row->>'order_id'))::uuid, (v_sku_map->>(v_row->>'sku_id'))::uuid,\n                (v_row->>'qty')::integer, (v_row->>'unit_price_jpy')::integer);\n      v_n := v_n + 1;\n    else\n      v_skipped_items := v_skipped_items + 1;\n    end if;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('order_items', v_n, 'order_items_skipped', v_skipped_items);\n\n  -- 連携先（id は振り直す = 署名シークレットも変わる。外部プラグイン側の再設定が要る）\n  v_n := 0;\n  for v_row in select * from jsonb_array_elements(v_endpoints) loop\n    insert into hook_endpoints (shop_id, name, url, events, enabled, manifest, settings, created_at)\n      values (p_shop_id, v_row->>'name', v_row->>'url',\n              coalesce((select array_agg(e) from jsonb_array_elements_text(coalesce(v_row->'events', '[]'::jsonb)) e), '{}'),\n              coalesce((v_row->>'enabled')::boolean, true), v_row->'manifest', coalesce(v_row->'settings', '{}'::jsonb),\n              coalesce((v_row->>'created_at')::timestamptz, now()));\n    v_n := v_n + 1;\n  end loop;\n  v_counts := v_counts || jsonb_build_object('hook_endpoints', v_n);\n\n  return v_counts;\nend;\n$$;\n\n-- ---------- 実行権限 ----------\nrevoke execute on function member_login_start(uuid, text, text, text, text, text, integer) from public, anon, authenticated;\nrevoke execute on function member_login_verify(uuid, uuid, text, text) from public, anon, authenticated;\nrevoke execute on function member_login_peek(uuid, uuid, text) from public, anon, authenticated;\nrevoke execute on function member_get(uuid, uuid, integer, boolean) from public, anon, authenticated;\nrevoke execute on function member_save_address(uuid, uuid, integer, text, jsonb) from public, anon, authenticated;\nrevoke execute on function member_withdraw(uuid, uuid, integer) from public, anon, authenticated;\nrevoke execute on function member_logout_all(uuid, uuid, integer) from public, anon, authenticated;\nrevoke execute on function member_set_email(uuid, uuid, text) from public, anon;\nrevoke execute on function import_members(uuid, jsonb) from public, anon, authenticated;\nrevoke execute on function attach_reservation_customer(uuid, uuid, jsonb) from public, anon, authenticated;\nrevoke execute on function member_login_cleanup() from public, anon, authenticated;\nrevoke all on function restore_shop_data(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function member_login_start(uuid, text, text, text, text, text, integer) to service_role;\ngrant execute on function member_login_verify(uuid, uuid, text, text) to service_role;\ngrant execute on function member_login_peek(uuid, uuid, text) to service_role;\ngrant execute on function member_get(uuid, uuid, integer, boolean) to service_role;\ngrant execute on function member_save_address(uuid, uuid, integer, text, jsonb) to service_role;\ngrant execute on function member_withdraw(uuid, uuid, integer) to service_role;\ngrant execute on function member_logout_all(uuid, uuid, integer) to service_role;\ngrant execute on function member_set_email(uuid, uuid, text) to authenticated;\ngrant execute on function import_members(uuid, jsonb) to service_role;\ngrant execute on function attach_reservation_customer(uuid, uuid, jsonb) to service_role;\ngrant execute on function member_login_cleanup() to service_role;\ngrant execute on function restore_shop_data(uuid, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0012_member_auth');\n" },
  { version: "0013_member_password", sql: "-- Banto 0013_member_password: 会員のパスワード（店ごとに選べる）と、WordPress のパスワードの取り込み\n-- 前方専用。設計は docs/knowledge/10-members-identity.md §13。\n--\n-- - パスワードでのログインは店ごとの設定（shops.settings.members_password = true）。コードとリンクはいつでも使える（忘れたときの入口）。\n-- - 照合は pgcrypto の bcrypt（crypt）。Worker の CPU（Workers 無料プランは 10ms）を使わない。\n--   回数の制限は重い計算の「前」に数える（総当たりで DB の CPU を使い切られないように）。\n-- - WordPress のパスワードは bcrypt の形式だけを取り込む: `$wp$2y$…`（6.8 以降。パスワードを HMAC-SHA384（鍵 wp-sha384）にかけて\n--   base64 にしたものを bcrypt）と `$2y$…`（bcrypt にしているプラグイン）。`$P$…`（phpass、MD5 ベース）は取り込まない。\n--   pgcrypto は `$2y$` / `$2b$` を読めない（DES と見なす）ので、`$2a$` に読み替えて照合する（同じ形式）。\n--   初めてログインに成功した時点で Banto の bcrypt に保存し直し、元のハッシュは捨てる。180 日使われなければ消す。\n-- Supabase では pgcrypto は extensions スキーマにある。素の PostgreSQL（テスト）では public にある。両方を search_path に入れる。\n\ncreate schema if not exists extensions;\ncreate extension if not exists pgcrypto;\n\nalter table customers add column if not exists password_hash text;\nalter table customers add column if not exists password_updated_at timestamptz;\nalter table customers add column if not exists legacy_password_hash text;\nalter table customers add column if not exists legacy_password_expires_at timestamptz;\n\n-- パスワードの失敗（回数の制限に使う。2 日で消す）\ncreate table member_login_failures (\n  id bigserial primary key,\n  shop_id uuid not null references shops(id) on delete cascade,\n  email text not null,\n  ip_hash text check (ip_hash ~ '^[0-9a-f]{64}$'),\n  created_at timestamptz not null default now()\n);\ncreate index member_login_failures_email_idx on member_login_failures (shop_id, email, created_at);\ncreate index member_login_failures_ip_idx on member_login_failures (shop_id, ip_hash, created_at) where ip_hash is not null;\nalter table member_login_failures enable row level security;\ncreate policy member_login_failures_none on member_login_failures for select using (false);\n\n-- WordPress の bcrypt 形式のハッシュと照合する（外からは呼ばない）\ncreate or replace function banto_wp_password_matches(p_password text, p_hash text)\nreturns boolean\nlanguage plpgsql\nstable\nset search_path = public, extensions\nas $$\ndeclare v_hash text; v_input text;\nbegin\n  if p_password is null or p_hash is null then return false; end if;\n  if p_hash ~ '^\\$wp\\$2[aby]\\$[0-9]{2}\\$' then\n    v_hash := '$2a$' || substr(p_hash, 8);\n    v_input := encode(hmac(p_password, 'wp-sha384', 'sha384'), 'base64');\n  elsif p_hash ~ '^\\$2[aby]\\$[0-9]{2}\\$' then\n    v_hash := '$2a$' || substr(p_hash, 5);\n    v_input := p_password;\n  else\n    return false;\n  end if;\n  return crypt(v_input, v_hash) = v_hash;\nend;\n$$;\n\n-- パスワードでログインする。戻り値: { ok: true, customer_id, session_epoch, email } /\n-- { ok: false, reason: 'invalid' | 'locked' | 'disabled' }。失敗は例外にしない（失敗の記録まで取り消されるため）\n-- 上限: 同じ人に 15 分で 5 回、同じ IP から 1 時間に 30 回の失敗で、しばらくパスワードでは入れない（コードでは入れる）\ncreate or replace function member_password_login(p_shop_id uuid, p_email text, p_password text, p_ip_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  v_email text := lower(btrim(coalesce(p_email, '')));\n  v_c customers%rowtype;\n  v_ok boolean := false;\n  v_found boolean;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_password_login: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id\n                  and coalesce(settings->>'members_enabled', 'false') = 'true'\n                  and coalesce(settings->>'members_password', 'false') = 'true') then\n    return jsonb_build_object('ok', false, 'reason', 'disabled');\n  end if;\n  if p_password is null or length(p_password) = 0 or length(p_password) > 200 or length(v_email) > 254 then\n    return jsonb_build_object('ok', false, 'reason', 'invalid');\n  end if;\n  perform pg_advisory_xact_lock(hashtextextended('member_password|' || p_shop_id::text || '|' || v_email, 0));\n  if (select count(*) from member_login_failures where shop_id = p_shop_id and email = v_email and created_at > now() - interval '15 minutes') >= 5\n     or (p_ip_hash is not null and (select count(*) from member_login_failures where shop_id = p_shop_id and ip_hash = p_ip_hash and created_at > now() - interval '1 hour') >= 30) then\n    return jsonb_build_object('ok', false, 'reason', 'locked');\n  end if;\n\n  select * into v_c from customers where shop_id = p_shop_id and lower(email) = v_email for update;\n  v_found := found;\n  if v_found and v_c.password_hash is not null then\n    v_ok := crypt(p_password, v_c.password_hash) = v_c.password_hash;\n  elsif v_found and v_c.legacy_password_hash is not null and (v_c.legacy_password_expires_at is null or v_c.legacy_password_expires_at > now()) then\n    -- WordPress は保存するときに前後の空白を落としている\n    v_ok := banto_wp_password_matches(p_password, v_c.legacy_password_hash)\n            or (btrim(p_password) <> p_password and banto_wp_password_matches(btrim(p_password), v_c.legacy_password_hash));\n    if v_ok then\n      update customers set password_hash = crypt(p_password, gen_salt('bf', 10)), password_updated_at = now(),\n                           legacy_password_hash = null, legacy_password_expires_at = null\n       where shop_id = p_shop_id and id = v_c.id;\n    end if;\n  else\n    -- 会員がいない・パスワードが無いときも同じくらいの時間をかける（応答の時間で登録の有無が分からないように）\n    perform crypt(p_password, '$2a$10$' || repeat('a', 53));\n  end if;\n  if not v_ok then\n    insert into member_login_failures (shop_id, email, ip_hash) values (p_shop_id, v_email, p_ip_hash);\n    return jsonb_build_object('ok', false, 'reason', 'invalid');\n  end if;\n  update customers set last_login_at = now() where shop_id = p_shop_id and id = v_c.id;\n  return jsonb_build_object('ok', true, 'customer_id', v_c.id, 'session_epoch', v_c.session_epoch, 'email', v_c.email);\nend;\n$$;\n\n-- パスワードを決める・変える（ログイン中の会員）。世代を上げてほかの端末をログアウトし、新しい世代を返す（合わなければ null）\ncreate or replace function member_set_password(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_password text)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare v_epoch integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_set_password: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id and coalesce(settings->>'members_password', 'false') = 'true') then\n    raise exception 'password_disabled';\n  end if;\n  if p_password is null or length(p_password) < 8 or length(p_password) > 200 then raise exception 'weak_password'; end if;\n  update customers\n     set password_hash = crypt(p_password, gen_salt('bf', 10)), password_updated_at = now(),\n         legacy_password_hash = null, legacy_password_expires_at = null,\n         session_epoch = session_epoch + 1\n   where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch\n  returning session_epoch into v_epoch;\n  return v_epoch;\nend;\n$$;\n\n-- WordPress のパスワードの取り込み（運営者、同梱モジュール woo_import から）。p_rows: [{ email, hash }]（最大 100 件）\n-- bcrypt の形式だけ。会員がいなければ作る。Banto のパスワードを決めた会員は上書きしない\ncreate or replace function import_member_passwords(p_shop_id uuid, p_rows jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb;\n  v_email text;\n  v_hash text;\n  v_id uuid;\n  v_has boolean;\n  v_imported integer := 0;\n  v_created integer := 0;\n  v_format integer := 0;\n  v_has_password integer := 0;\n  v_bad_email integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'import_member_passwords: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id) then raise exception 'shop_not_found'; end if;\n  if jsonb_array_length(coalesce(p_rows, '[]'::jsonb)) > 100 then raise exception 'too_many_rows'; end if;\n  for v_row in select e from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) e loop\n    v_email := lower(btrim(coalesce(v_row->>'email', '')));\n    v_hash := btrim(coalesce(v_row->>'hash', ''));\n    if length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then v_bad_email := v_bad_email + 1; continue; end if;\n    if v_hash !~ '^(\\$wp)?\\$2[aby]\\$[0-9]{2}\\$[./A-Za-z0-9]{53}$' then v_format := v_format + 1; continue; end if;\n    v_id := null;\n    select id, password_hash is not null into v_id, v_has from customers where shop_id = p_shop_id and lower(email) = v_email;\n    if v_id is null then\n      insert into customers (shop_id, email) values (p_shop_id, v_email) returning id into v_id;\n      v_created := v_created + 1;\n      v_has := false;\n    end if;\n    if v_has then v_has_password := v_has_password + 1; continue; end if;\n    update customers set legacy_password_hash = v_hash, legacy_password_expires_at = now() + interval '180 days'\n     where shop_id = p_shop_id and id = v_id;\n    v_imported := v_imported + 1;\n  end loop;\n  return jsonb_build_object('imported', v_imported, 'created', v_created, 'skipped_format', v_format,\n                            'skipped_has_password', v_has_password, 'skipped_invalid_email', v_bad_email);\nend;\n$$;\n\n-- 会員ページの表示（0012 を差し替え: パスワードの有無を足す）\ncreate or replace function member_get(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_with_orders boolean default false)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_c customers%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_get: service_role only' using errcode = '42501';\n  end if;\n  select * into v_c from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch;\n  if not found then return null; end if;\n  return jsonb_build_object(\n    'customer', jsonb_build_object('id', v_c.id, 'shop_id', v_c.shop_id, 'email', v_c.email, 'name', v_c.name, 'default_address', v_c.default_address,\n                                   'has_password', v_c.password_hash is not null or v_c.legacy_password_hash is not null),\n    'orders', case when p_with_orders then coalesce((\n      select jsonb_agg(o order by o.created_at desc) from (\n        select id, number, status, total_jpy, shipping_jpy, coalesce(discount_jpy, 0) as discount_jpy, created_at, shipped_at\n          from orders where shop_id = p_shop_id and customer_id = p_customer_id\n         order by created_at desc limit 50) o), '[]'::jsonb) else '[]'::jsonb end);\nend;\n$$;\n\n-- 片付け（0012 を差し替え: 失敗の記録と、期限の切れた WordPress のハッシュも消す）\ncreate or replace function member_login_cleanup()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer; v_m integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_login_cleanup: service_role only' using errcode = '42501';\n  end if;\n  delete from member_login_challenges where created_at < now() - interval '2 days';\n  get diagnostics v_n = row_count;\n  delete from member_login_failures where created_at < now() - interval '2 days';\n  get diagnostics v_m = row_count;\n  update customers set legacy_password_hash = null, legacy_password_expires_at = null\n   where legacy_password_expires_at is not null and legacy_password_expires_at < now();\n  return v_n + v_m;\nend;\n$$;\n\nrevoke execute on function banto_wp_password_matches(text, text) from public, anon, authenticated;\nrevoke execute on function member_password_login(uuid, text, text, text) from public, anon, authenticated;\nrevoke execute on function member_set_password(uuid, uuid, integer, text) from public, anon, authenticated;\nrevoke execute on function import_member_passwords(uuid, jsonb) from public, anon, authenticated;\nrevoke execute on function member_get(uuid, uuid, integer, boolean) from public, anon, authenticated;\nrevoke execute on function member_login_cleanup() from public, anon, authenticated;\ngrant execute on function member_password_login(uuid, text, text, text) to service_role;\ngrant execute on function member_set_password(uuid, uuid, integer, text) to service_role;\ngrant execute on function import_member_passwords(uuid, jsonb) to service_role;\ngrant execute on function member_get(uuid, uuid, integer, boolean) to service_role;\ngrant execute on function member_login_cleanup() to service_role;\n\ninsert into banto_migrations (version) values ('0013_member_password');\n" },
  { version: "0014_member_oauth", sql: "-- Banto 0014_member_oauth: 外部のアカウントでのログイン（LINE・Google。同梱モジュール line_login / google_login、既定 OFF）\n-- 前方専用。設計は docs/knowledge/10-members-identity.md §14。\n--\n-- - 会員と外部のアカウントの結びつきは、提供元の利用者 ID（sub）で持つ（メールアドレスでは結ばない）。\n-- - 確認済みのメールアドレスが返ったときだけ、同じアドレスの既存会員に自動で結びつける。\n--   ログイン中の会員が自分で「連携する」を押したときは、その会員に結びつける。\n-- - ヘッドレスは、Banto が提供元から戻った後に 1 回限り・2 分の引き換え券（handoff）を連携側に渡し、連携側が /members/verify で\n--   会員のトークンに引き換える（トークンを URL に載せない）。\n-- - **提供元の秘密（LINE のチャネルシークレット・Google のクライアントシークレット）はショップごと**（人間の決定、2026-10-16。\n--   複数のショップで同意画面にショップの名前を出すため）。CLAUDE.md §1-5 の例外: Worker がサイトの秘密から作った鍵で AES-GCM で暗号化し、\n--   暗号文だけを shop_oauth_clients に置く。鍵は DB に無い。暗号文はショップと提供元に結びつける（行を入れ替えても読めない）。\n--   運営者は暗号文の列を読めない（列の権限）。読むのは service_role の shop_oauth_client だけ。\n\ncreate table member_identities (\n  shop_id uuid not null,\n  provider text not null check (provider in ('line', 'google')),\n  subject text not null check (length(subject) between 1 and 200),\n  customer_id uuid not null,\n  created_at timestamptz not null default now(),\n  primary key (shop_id, provider, subject),\n  unique (shop_id, customer_id, provider),\n  foreign key (shop_id, customer_id) references customers (shop_id, id) on delete cascade\n);\nalter table member_identities enable row level security;\ncreate policy member_identities_none on member_identities for select using (false);\n\n-- ショップごとの提供元の設定。client_id は公開してよい値（ストアフロントのボタンにも使うので shops.settings.oauth にも写す）\ncreate table shop_oauth_clients (\n  shop_id uuid not null references shops(id) on delete cascade,\n  provider text not null check (provider in ('line', 'google')),\n  client_id text not null check (length(client_id) between 1 and 200),\n  -- \"v1.<iv>.<暗号文>\"（base64url）。Worker の src/members/secret-box.ts\n  secret_box text not null check (secret_box ~ '^v1\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$'),\n  updated_at timestamptz not null default now(),\n  primary key (shop_id, provider)\n);\nalter table shop_oauth_clients enable row level security;\ncreate policy shop_oauth_clients_owner on shop_oauth_clients for select using (banto_owns_shop(shop_id));\n-- 運営者にも暗号文は見せない（書き込みは shop_oauth_client_save だけ）\nrevoke all on shop_oauth_clients from anon, authenticated;\ngrant select (shop_id, provider, client_id, updated_at) on shop_oauth_clients to authenticated;\n\n-- 運営者が保存する（owner の JWT）。shops.settings.oauth.<provider>.client_id も一緒に書く\ncreate or replace function shop_oauth_client_save(p_shop_id uuid, p_provider text, p_client_id text, p_secret_box text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if p_provider not in ('line', 'google') then raise exception 'invalid_provider'; end if;\n  if p_client_id is null or length(btrim(p_client_id)) not between 1 and 200 or btrim(p_client_id) ~ '\\s' then raise exception 'invalid_client_id'; end if;\n  if p_secret_box is null then\n    -- client_id だけ変える（シークレットは今のまま）\n    update shop_oauth_clients set client_id = btrim(p_client_id), updated_at = now() where shop_id = p_shop_id and provider = p_provider;\n    if not found then raise exception 'secret_required'; end if;\n  else\n    insert into shop_oauth_clients (shop_id, provider, client_id, secret_box) values (p_shop_id, p_provider, btrim(p_client_id), p_secret_box)\n    on conflict (shop_id, provider) do update set client_id = excluded.client_id, secret_box = excluded.secret_box, updated_at = now();\n  end if;\n  update shops\n     set settings = jsonb_set(coalesce(settings, '{}'::jsonb), '{oauth}',\n                              coalesce(settings->'oauth', '{}'::jsonb) || jsonb_build_object(p_provider, jsonb_build_object('client_id', btrim(p_client_id))), true)\n   where id = p_shop_id;\nend;\n$$;\n\ncreate or replace function shop_oauth_client_delete(p_shop_id uuid, p_provider text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  delete from shop_oauth_clients where shop_id = p_shop_id and provider = p_provider;\n  update shops set settings = settings #- array['oauth', p_provider] where id = p_shop_id;\nend;\n$$;\n\n-- ログインの最中に Worker が読む（service_role）\ncreate or replace function shop_oauth_client(p_shop_id uuid, p_provider text)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when auth.role() = 'service_role' then (\n    select jsonb_build_object('client_id', client_id, 'secret_box', secret_box)\n      from shop_oauth_clients where shop_id = p_shop_id and provider = p_provider) end;\n$$;\n\ncreate table member_handoffs (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  customer_id uuid not null,\n  session_epoch integer not null,\n  token_hash text not null check (token_hash ~ '^[0-9a-f]{64}$'),\n  created_at timestamptz not null default now(),\n  expires_at timestamptz not null,\n  consumed_at timestamptz\n);\nalter table member_handoffs enable row level security;\ncreate policy member_handoffs_none on member_handoffs for select using (false);\n\n-- 外部のアカウントでログインする（無ければ会員登録）。p_link_customer_id があれば、ログイン中のその会員に結びつける。\n-- 戻り値: { ok: true, customer_id, session_epoch, email, created, linked } / { ok: false, reason }\n--   reason: disabled（会員機能かモジュールが OFF）/ already_linked（その外部アカウントは別の会員に結びついている）/\n--           other_linked（この会員には別の外部アカウントが結びついている）/ session（ログイン中の会員の世代が合わない）\ncreate or replace function member_oauth_login(p_shop_id uuid, p_provider text, p_subject text, p_email text, p_email_verified boolean,\n                                              p_link_customer_id uuid, p_link_epoch integer)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_email text := nullif(lower(btrim(coalesce(p_email, ''))), '');\n  v_customer_id uuid;\n  v_c customers%rowtype;\n  v_created boolean := false;\n  v_linked boolean := false;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_oauth_login: service_role only' using errcode = '42501';\n  end if;\n  if p_provider not in ('line', 'google') or p_subject is null or length(p_subject) not between 1 and 200 then raise exception 'invalid_identity'; end if;\n  if not exists (select 1 from shops where id = p_shop_id\n                  and coalesce(settings->>'members_enabled', 'false') = 'true'\n                  and coalesce(settings->'modules'->>(p_provider || '_login'), 'false') = 'true') then\n    return jsonb_build_object('ok', false, 'reason', 'disabled');\n  end if;\n  if v_email is not null and (length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$') then v_email := null; end if;\n  perform pg_advisory_xact_lock(hashtextextended('member_oauth|' || p_shop_id::text || '|' || p_provider || '|' || p_subject, 0));\n\n  select customer_id into v_customer_id from member_identities where shop_id = p_shop_id and provider = p_provider and subject = p_subject;\n\n  if p_link_customer_id is not null then\n    -- ログイン中の会員が自分で連携する\n    if not exists (select 1 from customers where shop_id = p_shop_id and id = p_link_customer_id and session_epoch = coalesce(p_link_epoch, -1)) then\n      return jsonb_build_object('ok', false, 'reason', 'session');\n    end if;\n    if v_customer_id is not null and v_customer_id <> p_link_customer_id then return jsonb_build_object('ok', false, 'reason', 'already_linked'); end if;\n    if v_customer_id is null then\n      if exists (select 1 from member_identities where shop_id = p_shop_id and customer_id = p_link_customer_id and provider = p_provider) then\n        return jsonb_build_object('ok', false, 'reason', 'other_linked');\n      end if;\n      insert into member_identities (shop_id, provider, subject, customer_id) values (p_shop_id, p_provider, p_subject, p_link_customer_id);\n      v_linked := true;\n    end if;\n    v_customer_id := p_link_customer_id;\n  elsif v_customer_id is null then\n    -- 確認済みのアドレスなら、同じアドレスの会員に結びつける（その会員に同じ提供元の別アカウントが無いときだけ）\n    if v_email is not null and p_email_verified then\n      select id into v_customer_id from customers c where c.shop_id = p_shop_id and lower(c.email) = v_email\n         and not exists (select 1 from member_identities i where i.shop_id = p_shop_id and i.customer_id = c.id and i.provider = p_provider);\n    end if;\n    if v_customer_id is null then\n      insert into customers (shop_id, email)\n      values (p_shop_id, case when p_email_verified and v_email is not null\n                               and not exists (select 1 from customers where shop_id = p_shop_id and lower(email) = v_email) then v_email end)\n      returning id into v_customer_id;\n      v_created := true;\n    end if;\n    insert into member_identities (shop_id, provider, subject, customer_id) values (p_shop_id, p_provider, p_subject, v_customer_id);\n    v_linked := true;\n  end if;\n\n  update customers set last_login_at = now() where shop_id = p_shop_id and id = v_customer_id returning * into v_c;\n  return jsonb_build_object('ok', true, 'customer_id', v_c.id, 'session_epoch', v_c.session_epoch, 'email', v_c.email,\n                            'created', v_created, 'linked', v_linked);\nend;\n$$;\n\n-- 連携を外す。ほかに入る方法（メールアドレスかパスワード）が無い会員は外せない（入れなくなるため）\ncreate or replace function member_unlink_identity(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_provider text)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_c customers%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_unlink_identity: service_role only' using errcode = '42501';\n  end if;\n  select * into v_c from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch;\n  if not found then return false; end if;\n  if v_c.email is null then raise exception 'last_login_method'; end if;\n  delete from member_identities where shop_id = p_shop_id and customer_id = p_customer_id and provider = p_provider;\n  return found;\nend;\n$$;\n\n-- ヘッドレスの引き換え券（2 分・1 回限り）。token は Worker が HMAC にしたもの\ncreate or replace function member_handoff_create(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_token_hash text)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_id uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_handoff_create: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then\n    raise exception 'member_session_invalid';\n  end if;\n  insert into member_handoffs (shop_id, customer_id, session_epoch, token_hash, expires_at)\n  values (p_shop_id, p_customer_id, p_epoch, p_token_hash, now() + interval '2 minutes')\n  returning id into v_id;\n  return v_id;\nend;\n$$;\n\ncreate or replace function member_handoff_redeem(p_shop_id uuid, p_id uuid, p_token_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_h member_handoffs%rowtype; v_c customers%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_handoff_redeem: service_role only' using errcode = '42501';\n  end if;\n  select * into v_h from member_handoffs where id = p_id and shop_id = p_shop_id for update;\n  if not found or v_h.token_hash <> p_token_hash or v_h.consumed_at is not null or v_h.expires_at < now() then\n    return jsonb_build_object('ok', false, 'reason', 'expired');\n  end if;\n  update member_handoffs set consumed_at = now() where id = v_h.id;\n  select * into v_c from customers where shop_id = p_shop_id and id = v_h.customer_id and session_epoch = v_h.session_epoch;\n  if not found then return jsonb_build_object('ok', false, 'reason', 'expired'); end if;\n  return jsonb_build_object('ok', true, 'customer_id', v_c.id, 'session_epoch', v_c.session_epoch, 'email', v_c.email);\nend;\n$$;\n\n-- 会員ページの表示（0013 を差し替え: 結びついた外部アカウントを足す）\ncreate or replace function member_get(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_with_orders boolean default false)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_c customers%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_get: service_role only' using errcode = '42501';\n  end if;\n  select * into v_c from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch;\n  if not found then return null; end if;\n  return jsonb_build_object(\n    'customer', jsonb_build_object('id', v_c.id, 'shop_id', v_c.shop_id, 'email', v_c.email, 'name', v_c.name, 'default_address', v_c.default_address,\n                                   'has_password', v_c.password_hash is not null or v_c.legacy_password_hash is not null,\n                                   'providers', coalesce((select jsonb_agg(provider order by provider) from member_identities\n                                                           where shop_id = p_shop_id and customer_id = v_c.id), '[]'::jsonb)),\n    'orders', case when p_with_orders then coalesce((\n      select jsonb_agg(o order by o.created_at desc) from (\n        select id, number, status, total_jpy, shipping_jpy, coalesce(discount_jpy, 0) as discount_jpy, created_at, shipped_at\n          from orders where shop_id = p_shop_id and customer_id = p_customer_id\n         order by created_at desc limit 50) o), '[]'::jsonb) else '[]'::jsonb end);\nend;\n$$;\n\n-- 片付け（0013 を差し替え: 引き換え券も消す）\ncreate or replace function member_login_cleanup()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer; v_m integer; v_h integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_login_cleanup: service_role only' using errcode = '42501';\n  end if;\n  delete from member_login_challenges where created_at < now() - interval '2 days';\n  get diagnostics v_n = row_count;\n  delete from member_login_failures where created_at < now() - interval '2 days';\n  get diagnostics v_m = row_count;\n  delete from member_handoffs where created_at < now() - interval '1 day';\n  get diagnostics v_h = row_count;\n  update customers set legacy_password_hash = null, legacy_password_expires_at = null\n   where legacy_password_expires_at is not null and legacy_password_expires_at < now();\n  return v_n + v_m + v_h;\nend;\n$$;\n\nrevoke execute on function shop_oauth_client_save(uuid, text, text, text) from public, anon;\nrevoke execute on function shop_oauth_client_delete(uuid, text) from public, anon;\nrevoke execute on function shop_oauth_client(uuid, text) from public, anon, authenticated;\ngrant execute on function shop_oauth_client_save(uuid, text, text, text) to authenticated;\ngrant execute on function shop_oauth_client_delete(uuid, text) to authenticated;\ngrant execute on function shop_oauth_client(uuid, text) to service_role;\nrevoke execute on function member_oauth_login(uuid, text, text, text, boolean, uuid, integer) from public, anon, authenticated;\nrevoke execute on function member_unlink_identity(uuid, uuid, integer, text) from public, anon, authenticated;\nrevoke execute on function member_handoff_create(uuid, uuid, integer, text) from public, anon, authenticated;\nrevoke execute on function member_handoff_redeem(uuid, uuid, text) from public, anon, authenticated;\nrevoke execute on function member_get(uuid, uuid, integer, boolean) from public, anon, authenticated;\nrevoke execute on function member_login_cleanup() from public, anon, authenticated;\ngrant execute on function member_oauth_login(uuid, text, text, text, boolean, uuid, integer) to service_role;\ngrant execute on function member_unlink_identity(uuid, uuid, integer, text) to service_role;\ngrant execute on function member_handoff_create(uuid, uuid, integer, text) to service_role;\ngrant execute on function member_handoff_redeem(uuid, uuid, text) to service_role;\ngrant execute on function member_get(uuid, uuid, integer, boolean) to service_role;\ngrant execute on function member_login_cleanup() to service_role;\n\ninsert into banto_migrations (version) values ('0014_member_oauth');\n" },
  { version: "0015_shop_domain", sql: "-- 0015_shop_domain: ショップごとの独自ドメイン（docs/custom-domain.md、docs/knowledge/10-members-identity.md §15）\n--\n-- shops.domain に入れたホスト名（例 shop.example.jp）へのアクセスは、そのショップのストアフロントになる（パスにスラッグが要らない）。\n-- 会員のログインの戻り先（LINE・Google の redirect_uri）・ログインのメールのリンク・決済後の戻り先・canonical も、このドメインを使う。\n-- ホスト名は公開情報なので、公開中のショップなら anon からも読める（shops_public のポリシーのまま）。\n\nalter table shops add column if not exists domain text;\n\nalter table shops drop constraint if exists shops_domain_format;\nalter table shops add constraint shops_domain_format check (\n  domain is null or (\n    length(domain) <= 253\n    and domain = lower(domain)\n    and domain ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z]([a-z0-9-]{0,61}[a-z0-9])?$'\n  )\n);\n\n-- 同じドメインを 2 つのショップに付けない\ncreate unique index if not exists shops_domain_key on shops (domain) where domain is not null;\n\n-- 取引メールの「注文の確認」のリンクもショップのドメインにする\ncreate or replace function order_contact(p_order_id uuid, p_shop_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_o orders%rowtype; v_s shops%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'order_contact: service_role only' using errcode = '42501';\n  end if;\n  select * into v_o from orders where id = p_order_id and shop_id = p_shop_id;\n  if not found then raise exception 'not_found'; end if;\n  select * into v_s from shops where id = p_shop_id;\n  return jsonb_build_object(\n    'order_id', v_o.id, 'number', v_o.number, 'status', v_o.status, 'created_at', v_o.created_at,\n    'total_jpy', v_o.total_jpy, 'shipping_jpy', v_o.shipping_jpy, 'discount_jpy', v_o.discount_jpy, 'payment_provider', v_o.payment_provider,\n    'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                    from jsonb_array_elements(coalesce(v_o.discounts, '[]'::jsonb)) d),\n    'customer_email', v_o.customer_email, 'customer_name', v_o.customer_name, 'shipping_address', v_o.shipping_address,\n    'shop', jsonb_build_object('name', v_s.name, 'slug', v_s.slug, 'domain', v_s.domain,\n                               'contact_email', v_s.settings->>'contact_email', 'return_policy', v_s.return_policy),\n    'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy) order by oi.id), '[]'::jsonb)\n                from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = v_o.id));\nend;\n$$;\n\ninsert into banto_migrations (version) values ('0015_shop_domain');\n" },
  { version: "0016_member_notice", sql: "-- 0016_member_notice: パスワードでのログインを会員に知らせる（docs/knowledge/10-members-identity.md §16）\n--\n-- member_password_login（0013）を差し替え、成功したときに知らせのメールの送信元（メール通知プラグインの「送信元」）も返す。\n-- メールを送るのは Worker（src/members/notice.ts）。この端末で前にログインしたことがあれば送らない（署名付きの Cookie で覚える）。\n-- 0016 を適用する前は mail_from が返らないので、知らせは送らない（ログインはそのまま動く）。\n\ncreate or replace function member_password_login(p_shop_id uuid, p_email text, p_password text, p_ip_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  v_email text := lower(btrim(coalesce(p_email, '')));\n  v_c customers%rowtype;\n  v_ok boolean := false;\n  v_found boolean;\n  v_from text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_password_login: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id\n                  and coalesce(settings->>'members_enabled', 'false') = 'true'\n                  and coalesce(settings->>'members_password', 'false') = 'true') then\n    return jsonb_build_object('ok', false, 'reason', 'disabled');\n  end if;\n  if p_password is null or length(p_password) = 0 or length(p_password) > 200 or length(v_email) > 254 then\n    return jsonb_build_object('ok', false, 'reason', 'invalid');\n  end if;\n  perform pg_advisory_xact_lock(hashtextextended('member_password|' || p_shop_id::text || '|' || v_email, 0));\n  if (select count(*) from member_login_failures where shop_id = p_shop_id and email = v_email and created_at > now() - interval '15 minutes') >= 5\n     or (p_ip_hash is not null and (select count(*) from member_login_failures where shop_id = p_shop_id and ip_hash = p_ip_hash and created_at > now() - interval '1 hour') >= 30) then\n    return jsonb_build_object('ok', false, 'reason', 'locked');\n  end if;\n\n  select * into v_c from customers where shop_id = p_shop_id and lower(email) = v_email for update;\n  v_found := found;\n  if v_found and v_c.password_hash is not null then\n    v_ok := crypt(p_password, v_c.password_hash) = v_c.password_hash;\n  elsif v_found and v_c.legacy_password_hash is not null and (v_c.legacy_password_expires_at is null or v_c.legacy_password_expires_at > now()) then\n    -- WordPress は保存するときに前後の空白を落としている\n    v_ok := banto_wp_password_matches(p_password, v_c.legacy_password_hash)\n            or (btrim(p_password) <> p_password and banto_wp_password_matches(btrim(p_password), v_c.legacy_password_hash));\n    if v_ok then\n      update customers set password_hash = crypt(p_password, gen_salt('bf', 10)), password_updated_at = now(),\n                           legacy_password_hash = null, legacy_password_expires_at = null\n       where shop_id = p_shop_id and id = v_c.id;\n    end if;\n  else\n    -- 会員がいない・パスワードが無いときも同じくらいの時間をかける（応答の時間で登録の有無が分からないように）\n    perform crypt(p_password, '$2a$10$' || repeat('a', 53));\n  end if;\n  if not v_ok then\n    insert into member_login_failures (shop_id, email, ip_hash) values (p_shop_id, v_email, p_ip_hash);\n    return jsonb_build_object('ok', false, 'reason', 'invalid');\n  end if;\n  update customers set last_login_at = now() where shop_id = p_shop_id and id = v_c.id;\n  -- 知らせのメールの送信元（メール通知プラグインの設定。無ければ null = 送らない）\n  select nullif(btrim(e.settings->>'from'), '') into v_from\n    from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and e.url = 'https://banto.invalid/plugins/email_resend'\n   limit 1;\n  return jsonb_build_object('ok', true, 'customer_id', v_c.id, 'session_epoch', v_c.session_epoch, 'email', v_c.email, 'mail_from', v_from);\nend;\n$$;\n\nrevoke execute on function member_password_login(uuid, text, text, text) from public, anon, authenticated;\ngrant execute on function member_password_login(uuid, text, text, text) to service_role;\n\ninsert into banto_migrations (version) values ('0016_member_notice');\n" },
  { version: "0017_tax", sql: "-- 0017_tax: 軽減税率（8%）とインボイスの領収書（docs/tax.md、docs/knowledge/02-decisions.md 2026-10-17）\n--\n-- - 価格はすべて税込のまま（総額表示）。税率は商品ごとの区分 products.tax_class（standard / reduced / exempt）で決める（人間の決定）。\n--   税率の数値はショップの設定（settings.tax_rate = 標準・既定 10、settings.tax_rate_reduced = 軽減・既定 8）。exempt は 0%（非課税・不課税）。\n-- - 注文を確定した時点の税率を残す（後で区分や設定を変えても、過去の注文の領収書は変わらない）:\n--     order_items.tax_rate … 明細ごとの税率（トリガーで商品の区分から入れる）\n--     orders.shipping_tax_rate … 送料の税率（標準税率）\n--     orders.tax_rounding … 消費税額の端数の扱い（floor / round / ceil、ショップの設定 settings.tax_rounding、既定 floor）\n--   確定の関数（confirm_reservation など）は触らない。どの経路（Webhook・0 円・復元）で入っても同じトリガーが入れる。\n-- - 税率ごとの対象額と消費税額の計算は src/commerce/tax.ts だけ（インボイスの決まり: 税率ごとに 1 回だけ端数を処理する）。\n-- - 0017 を適用する前の注文は税率が null。読む側は標準税率として扱う。\n\nalter table products add column if not exists tax_class text not null default 'standard';\nalter table products drop constraint if exists products_tax_class_check;\nalter table products add constraint products_tax_class_check check (tax_class in ('standard', 'reduced', 'exempt'));\n\nalter table order_items add column if not exists tax_rate numeric(5,2) check (tax_rate is null or (tax_rate >= 0 and tax_rate <= 100));\nalter table orders add column if not exists shipping_tax_rate numeric(5,2) check (shipping_tax_rate is null or (shipping_tax_rate >= 0 and shipping_tax_rate <= 100));\nalter table orders add column if not exists tax_rounding text check (tax_rounding is null or tax_rounding in ('floor', 'round', 'ceil'));\n\n-- ショップの設定から税率を読む（数値でなければ既定）\ncreate or replace function banto_shop_tax_rate(p_settings jsonb, p_class text)\nreturns numeric\nlanguage sql\nimmutable\nset search_path = public\nas $$\n  select case p_class\n    when 'exempt' then 0::numeric\n    when 'reduced' then case when coalesce(p_settings->>'tax_rate_reduced', '') ~ '^[0-9]{1,2}(\\.[0-9]{1,2})?$' then (p_settings->>'tax_rate_reduced')::numeric else 8 end\n    else case when coalesce(p_settings->>'tax_rate', '') ~ '^[0-9]{1,2}(\\.[0-9]{1,2})?$' then (p_settings->>'tax_rate')::numeric else 10 end\n  end;\n$$;\n\ncreate or replace function banto_order_items_tax()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if new.tax_rate is null then\n    select banto_shop_tax_rate(s.settings, p.tax_class) into new.tax_rate\n      from skus k join products p on p.id = k.product_id join shops s on s.id = k.shop_id\n     where k.id = new.sku_id;\n  end if;\n  return new;\nend;\n$$;\n\ncreate or replace function banto_orders_tax()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_settings jsonb;\nbegin\n  select settings into v_settings from shops where id = new.shop_id;\n  if new.shipping_tax_rate is null then new.shipping_tax_rate := banto_shop_tax_rate(v_settings, 'standard'); end if;\n  if new.tax_rounding is null then\n    new.tax_rounding := case when v_settings->>'tax_rounding' in ('floor', 'round', 'ceil') then v_settings->>'tax_rounding' else 'floor' end;\n  end if;\n  return new;\nend;\n$$;\n\ndrop trigger if exists order_items_tax on order_items;\ncreate trigger order_items_tax before insert on order_items for each row execute function banto_order_items_tax();\ndrop trigger if exists orders_tax on orders;\ncreate trigger orders_tax before insert on orders for each row execute function banto_orders_tax();\n\nrevoke execute on function banto_shop_tax_rate(jsonb, text) from public, anon, authenticated;\nrevoke execute on function banto_order_items_tax() from public, anon, authenticated;\nrevoke execute on function banto_orders_tax() from public, anon, authenticated;\n\n-- 購入者向けの注文照会（0010 を差し替え: 領収書のために税率・端数の扱い・注文の id を足す。住所は返さない）\ncreate or replace function lookup_order(p_shop_id uuid, p_number integer, p_email text)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object('number', o.number, 'status', o.status, 'created_at', o.created_at, 'shipped_at', o.shipped_at,\n                            'total_jpy', o.total_jpy, 'shipping_jpy', o.shipping_jpy, 'discount_jpy', o.discount_jpy,\n                            'shipping_tax_rate', o.shipping_tax_rate, 'tax_rounding', o.tax_rounding, 'payment_provider', o.payment_provider,\n                            'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                                            from jsonb_array_elements(coalesce(o.discounts, '[]'::jsonb)) d),\n                            'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy, 'tax_rate', oi.tax_rate, 'discount_jpy', oi.discount_jpy) order by oi.id), '[]'::jsonb)\n                                        from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = o.id))\n    from orders o join shops s on s.id = o.shop_id\n   where o.shop_id = p_shop_id and o.number = p_number and s.published\n     and o.customer_email is not null and lower(o.customer_email) = lower(btrim(p_email))\n   limit 1;\n$$;\n\n-- 会員の注文 1 件（会員ページの領収書。lookup_order と同じ形）。世代が合わなければ null\ncreate or replace function member_order(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_number integer)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_order: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then return null; end if;\n  return (\n    select jsonb_build_object('number', o.number, 'status', o.status, 'created_at', o.created_at, 'shipped_at', o.shipped_at,\n                              'total_jpy', o.total_jpy, 'shipping_jpy', o.shipping_jpy, 'discount_jpy', o.discount_jpy,\n                              'shipping_tax_rate', o.shipping_tax_rate, 'tax_rounding', o.tax_rounding, 'payment_provider', o.payment_provider,\n                              'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                                              from jsonb_array_elements(coalesce(o.discounts, '[]'::jsonb)) d),\n                              'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy, 'tax_rate', oi.tax_rate, 'discount_jpy', oi.discount_jpy) order by oi.id), '[]'::jsonb)\n                                          from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = o.id))\n      from orders o\n     where o.shop_id = p_shop_id and o.customer_id = p_customer_id and o.number = p_number);\nend;\n$$;\n\nrevoke execute on function lookup_order(uuid, integer, text) from public;\ngrant execute on function lookup_order(uuid, integer, text) to anon, authenticated, service_role;\nrevoke execute on function member_order(uuid, uuid, integer, integer) from public, anon, authenticated;\ngrant execute on function member_order(uuid, uuid, integer, integer) to service_role;\n\n-- バックアップからの復元の後で、税の区分と注文の税率を戻す（restore_shop_data・restore_catalog は 0017 の列を知らない）。\n-- 復元は空のショップにだけ入るので、ここで触るのは復元したばかりの行だけ。商品は slug、注文は注文番号で突き合わせる。\n-- 明細の税率は、戻した商品の区分とショップの設定から入れ直す（書き出しの時点の明細の税率とは、区分を後で変えていれば違うことがある）。\ncreate or replace function restore_tax(p_shop_id uuid, p_products jsonb, p_orders jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_p integer := 0; v_o integer := 0; v_row jsonb; v_n integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'restore_tax: service_role only' using errcode = '42501';\n  end if;\n  for v_row in select e from jsonb_array_elements(coalesce(p_products, '[]'::jsonb)) e loop\n    if v_row->>'tax_class' in ('standard', 'reduced', 'exempt') then\n      update products set tax_class = v_row->>'tax_class' where shop_id = p_shop_id and slug = v_row->>'slug';\n      get diagnostics v_n = row_count; v_p := v_p + v_n;\n    end if;\n  end loop;\n  update order_items oi set tax_rate = banto_shop_tax_rate(s.settings, p.tax_class)\n    from skus k join products p on p.id = k.product_id join shops s on s.id = k.shop_id\n   where oi.shop_id = p_shop_id and k.id = oi.sku_id;\n  for v_row in select e from jsonb_array_elements(coalesce(p_orders, '[]'::jsonb)) e loop\n    if v_row ? 'number' and (v_row->>'number') ~ '^[0-9]+$' then\n      update orders set\n        shipping_tax_rate = coalesce(case when coalesce(v_row->>'shipping_tax_rate', '') ~ '^[0-9]{1,2}(\\.[0-9]{1,2})?$' then (v_row->>'shipping_tax_rate')::numeric end, shipping_tax_rate),\n        tax_rounding = coalesce(case when v_row->>'tax_rounding' in ('floor', 'round', 'ceil') then v_row->>'tax_rounding' end, tax_rounding)\n       where shop_id = p_shop_id and number = (v_row->>'number')::integer;\n      get diagnostics v_n = row_count; v_o := v_o + v_n;\n    end if;\n  end loop;\n  return jsonb_build_object('tax_classes', v_p, 'order_tax', v_o);\nend;\n$$;\n\nrevoke execute on function restore_tax(uuid, jsonb, jsonb) from public, anon, authenticated;\ngrant execute on function restore_tax(uuid, jsonb, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0017_tax');\n" },
  { version: "0018_delivery", sql: "-- 0018_delivery: 注文の「配送の指定」（汎用の器。docs/delivery-time.md）\n--\n-- orders.delivery jsonb … 配送の指定（同梱モジュール delivery_time が { date: 'YYYY-MM-DD' | null, slot: 'am' | '14-16' | … | null } を入れる）。\n-- チェックアウトは予約の customer（attach_reservation_customer、0012）に delivery を載せ、注文を入れるときにトリガーで写す。\n-- 確定の関数（confirm_reservation）は触らない。個人情報ではないのでマスキングの対象にしない。\n\nalter table orders add column if not exists delivery jsonb check (delivery is null or jsonb_typeof(delivery) = 'object');\n\ncreate or replace function banto_orders_delivery()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if new.delivery is null and new.reservation_id is not null then\n    select case when jsonb_typeof(r.customer->'delivery') = 'object' then r.customer->'delivery' end into new.delivery\n      from reservations r where r.id = new.reservation_id;\n  end if;\n  return new;\nend;\n$$;\n\ndrop trigger if exists orders_delivery on orders;\ncreate trigger orders_delivery before insert on orders for each row execute function banto_orders_delivery();\nrevoke execute on function banto_orders_delivery() from public, anon, authenticated;\n\ninsert into banto_migrations (version) values ('0018_delivery');\n" },
  { version: "0019_coupon_grants", sql: "-- 0019_coupon_grants: 配布型のクーポン（発行済みのクーポン）。docs/knowledge/09-coupons.md §5-2、docs/coupons.md\n--\n--   coupon_grants … 1 枚ずつの発行済みクーポン。コード（ショップの中で一意）を必ず持つ。\n--                   customer_id があればその会員だけが使える（会員への発行）。無ければコードを知っている人が 1 回だけ使える（使い捨てコード）。\n--                   available → held（予約中）→ used（確定）。決済ページの期限切れ・キャンセルで available に戻る。revoked は運営者が取り消した。\n--                   1 枚ごとの期限 expires_at（キャンペーンの grant_valid_days 日。無ければキャンペーンの期間だけ）。\n-- 判定は今までどおり src/commerce/discounts.ts（coupon_lookup がコードからキャンペーンと発行済みのクーポンを返す）。\n-- 回数は「発行済みの行そのものが枠」: apply_reservation_discounts がその行を FOR UPDATE で取る（全体の上限・1 人あたりは見ない）。\n-- 確定・解放は coupon_redemptions の状態が変わったときのトリガーで写す（確定・解放の関数は触らない）。\n\nalter table coupon_campaigns add column if not exists grant_valid_days integer check (grant_valid_days is null or grant_valid_days between 1 and 3650);\n\ncreate table coupon_grants (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  campaign_id uuid not null references coupon_campaigns(id) on delete cascade,\n  code text not null check (code ~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'),\n  customer_id uuid,\n  status text not null default 'available' check (status in ('available', 'held', 'used', 'revoked')),\n  expires_at timestamptz,\n  reservation_id uuid references reservations(id) on delete set null,\n  created_at timestamptz not null default now(),\n  used_at timestamptz,\n  foreign key (shop_id, customer_id) references customers(shop_id, id) on delete cascade\n);\ncreate unique index coupon_grants_code on coupon_grants(shop_id, code);\ncreate index coupon_grants_customer on coupon_grants(shop_id, customer_id) where customer_id is not null and status = 'available';\ncreate index on coupon_grants(campaign_id);\ncreate index on coupon_grants(reservation_id) where reservation_id is not null;\n\nalter table coupon_grants enable row level security;\n-- owner は自ショップの発行済みクーポンを読む（書くのは下の関数だけ）。購入者は直接読めない\ncreate policy coupon_grants_owner_select on coupon_grants for select using (banto_owns_shop(shop_id));\n\nalter table coupon_redemptions add column if not exists grant_id uuid references coupon_grants(id) on delete set null;\n\n-- ---------- 使用の記録の状態を発行済みのクーポンに写す ----------\ncreate or replace function banto_coupon_grant_status()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if new.grant_id is null or new.status = old.status then return new; end if;\n  if new.status = 'used' then\n    update coupon_grants set status = 'used', used_at = now() where id = new.grant_id and status in ('held', 'available');\n  elsif new.status = 'released' then\n    -- 解放・キャンセル: この予約が押さえていた（使っていた）ものだけを戻す\n    update coupon_grants set status = 'available', reservation_id = null, used_at = null\n     where id = new.grant_id and status in ('held', 'used') and reservation_id = new.reservation_id;\n  end if;\n  return new;\nend;\n$$;\ndrop trigger if exists coupon_redemptions_grant on coupon_redemptions;\ncreate trigger coupon_redemptions_grant after update of status on coupon_redemptions for each row execute function banto_coupon_grant_status();\nrevoke execute on function banto_coupon_grant_status() from public, anon, authenticated;\n\n-- ---------- 発行（owner） ----------\n-- p_customer_ids があれば会員ごとに 1 枚（その会員に使っていない同じキャンペーンのクーポンがあれば足さない）、\n-- p_count があればコードだけのクーポンを p_count 枚（最大 5000）。戻り値: { issued }\ncreate or replace function coupon_grants_issue(p_shop_id uuid, p_campaign_id uuid, p_customer_ids uuid[], p_count integer)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_c coupon_campaigns%rowtype;\n  v_expires timestamptz;\n  v_n integer := 0;\n  v_cid uuid;\n  v_i integer;\n  v_code text;\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  select * into v_c from coupon_campaigns where id = p_campaign_id and shop_id = p_shop_id;\n  if not found then raise exception 'campaign_not_found'; end if;\n  if coalesce(p_count, 0) < 0 or coalesce(p_count, 0) > 5000 or coalesce(array_length(p_customer_ids, 1), 0) > 5000 then raise exception 'too_many'; end if;\n  v_expires := case when v_c.grant_valid_days is not null then now() + make_interval(days => v_c.grant_valid_days) end;\n  if v_c.ends_at is not null and (v_expires is null or v_expires > v_c.ends_at) then v_expires := v_c.ends_at; end if;\n  foreach v_cid in array coalesce(p_customer_ids, '{}'::uuid[]) loop\n    if not exists (select 1 from customers where shop_id = p_shop_id and id = v_cid) then continue; end if;\n    if exists (select 1 from coupon_grants where campaign_id = v_c.id and customer_id = v_cid and status in ('available', 'held')) then continue; end if;\n    loop\n      v_code := banto_grant_code();\n      begin\n        insert into coupon_grants (shop_id, campaign_id, code, customer_id, expires_at) values (p_shop_id, v_c.id, v_code, v_cid, v_expires);\n        exit;\n      exception when unique_violation then null; -- まれにコードが重なったら作り直す\n      end;\n    end loop;\n    v_n := v_n + 1;\n  end loop;\n  for v_i in 1 .. coalesce(p_count, 0) loop\n    loop\n      v_code := banto_grant_code();\n      begin\n        insert into coupon_grants (shop_id, campaign_id, code, expires_at) values (p_shop_id, v_c.id, v_code, v_expires);\n        exit;\n      exception when unique_violation then null;\n      end;\n    end loop;\n    v_n := v_n + 1;\n  end loop;\n  return jsonb_build_object('issued', v_n);\nend;\n$$;\n\n-- 推測されにくいコード（XXXX-XXXX-XXXX、0/O・1/I を使わない 32 文字から。gen_random_uuid の乱数を使う）\ncreate or replace function banto_grant_code()\nreturns text\nlanguage plpgsql\nvolatile\nset search_path = public\nas $$\ndeclare\n  v_alpha constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';\n  v_hex text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');\n  v_out text := '';\n  v_i integer;\nbegin\n  for v_i in 0 .. 11 loop\n    v_out := v_out || substr(v_alpha, (('x' || substr(v_hex, v_i * 2 + 1, 2))::bit(8)::integer % 32) + 1, 1);\n    if v_i in (3, 7) then v_out := v_out || '-'; end if;\n  end loop;\n  return v_out;\nend;\n$$;\n\n-- 取り消し（owner）。使っていないものだけ\ncreate or replace function coupon_grant_revoke(p_shop_id uuid, p_grant_id uuid)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  update coupon_grants set status = 'revoked' where id = p_grant_id and shop_id = p_shop_id and status = 'available';\n  return found;\nend;\n$$;\n\n-- ---------- 会員のマイクーポン（service_role、世代を確かめる） ----------\ncreate or replace function member_coupons(p_shop_id uuid, p_customer_id uuid, p_epoch integer)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_coupons: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then return null; end if;\n  return coalesce((\n    select jsonb_agg(jsonb_build_object('code', g.code, 'name', c.name, 'kind', c.kind, 'value', c.value, 'expires_at', coalesce(g.expires_at, c.ends_at))\n                     order by coalesce(g.expires_at, c.ends_at) nulls last, g.created_at)\n      from coupon_grants g join coupon_campaigns c on c.id = g.campaign_id\n     where g.shop_id = p_shop_id and g.customer_id = p_customer_id and g.status = 'available' and c.active\n       and (g.expires_at is null or g.expires_at > now()) and (c.ends_at is null or c.ends_at > now())), '[]'::jsonb);\nend;\n$$;\n\n-- ---------- 判定の材料（0010 を差し替え: 発行済みのクーポンのコードも引く） ----------\n-- キャンペーンのコードに無いコードは、発行済みのクーポンから引く。そのときは code に発行済みのコード、grant に状態を入れて返す\ncreate or replace function coupon_lookup(p_shop_id uuid, p_codes text[], p_subject text default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_codes text[]; v_out jsonb; v_grants jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'coupon_lookup: service_role only' using errcode = '42501';\n  end if;\n  select array_agg(x) into v_codes from (select upper(btrim(x)) as x from unnest(coalesce(p_codes, '{}'::text[])) x limit 5) t;\n  select coalesce(jsonb_agg(jsonb_build_object(\n      'id', c.id, 'name', c.name, 'code', c.code, 'kind', c.kind, 'value', c.value,\n      'starts_at', c.starts_at, 'ends_at', c.ends_at, 'usage_limit', c.usage_limit, 'per_customer_limit', c.per_customer_limit,\n      'combinable', c.combinable, 'audience', c.audience, 'conditions', c.conditions, 'active', c.active,\n      'used_by_subject', case when p_subject is null or c.per_customer_limit is null then 0 else (\n        select count(*) from coupon_redemptions r where r.campaign_id = c.id and r.subject = p_subject and r.status <> 'released') end,\n      'available', c.usage_limit is null or exists (select 1 from coupon_slots s where s.campaign_id = c.id and s.status = 'free')\n    )), '[]'::jsonb)\n    into v_out\n    from coupon_campaigns c\n   where c.shop_id = p_shop_id and c.code = any (coalesce(v_codes, '{}'::text[]));\n  select coalesce(jsonb_agg(jsonb_build_object(\n      'id', c.id, 'name', c.name, 'code', g.code, 'kind', c.kind, 'value', c.value,\n      'starts_at', c.starts_at, 'ends_at', c.ends_at, 'usage_limit', null, 'per_customer_limit', null,\n      'combinable', c.combinable, 'audience', c.audience, 'conditions', c.conditions, 'active', c.active,\n      'used_by_subject', 0, 'available', true,\n      'grant', jsonb_build_object('id', g.id, 'status', g.status, 'expires_at', g.expires_at, 'customer_id', g.customer_id)\n    )), '[]'::jsonb)\n    into v_grants\n    from coupon_grants g join coupon_campaigns c on c.id = g.campaign_id\n   where g.shop_id = p_shop_id and g.code = any (coalesce(v_codes, '{}'::text[]))\n     and not exists (select 1 from coupon_campaigns c2 where c2.shop_id = p_shop_id and c2.code = g.code);\n  return v_out || v_grants;\nend;\n$$;\n\n-- ---------- 予約に値引きを付け、回数を予約する（0010 を差し替え: 発行済みのクーポンはその行を取る） ----------\ncreate or replace function apply_reservation_discounts(p_reservation_id uuid, p_shop_id uuid, p_subject text, p_discounts jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res reservations%rowtype;\n  v_a jsonb;\n  v_c coupon_campaigns%rowtype;\n  v_g coupon_grants%rowtype;\n  v_used integer;\n  v_slot bigint;\n  v_grant uuid;\n  v_total integer := coalesce((p_discounts->>'total_jpy')::integer, 0);\n  v_lines jsonb := coalesce(p_discounts->'lines', '[]'::jsonb);\n  v_subtotal integer;\n  v_items jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'apply_reservation_discounts: service_role only' using errcode = '42501';\n  end if;\n  if p_subject is null or p_subject !~ '^(c|e):[0-9a-f-]{32,64}$' then raise exception 'invalid_subject'; end if;\n  select * into v_res from reservations where id = p_reservation_id and shop_id = p_shop_id and status = 'pending' for update;\n  if not found then raise exception 'reservation_not_found' using detail = p_reservation_id::text; end if;\n  select coalesce(sum((e->>'qty')::integer * (e->>'unit_price_jpy')::integer), 0) into v_subtotal from jsonb_array_elements(v_res.items) e;\n  if v_total < 0 or v_total > v_subtotal + v_res.shipping_jpy then raise exception 'invalid_discount'; end if;\n\n  for v_a in select e from jsonb_array_elements(coalesce(p_discounts->'applied', '[]'::jsonb)) e loop\n    select * into v_c from coupon_campaigns where id = (v_a->>'campaign_id')::uuid and shop_id = p_shop_id;\n    if not found or not v_c.active or (v_c.starts_at is not null and v_c.starts_at > now()) or (v_c.ends_at is not null and v_c.ends_at < now()) then\n      raise exception 'coupon_unavailable' using detail = coalesce(v_a->>'code', '');\n    end if;\n    if v_c.audience = 'members' and p_subject !~ '^c:' then\n      raise exception 'coupon_unavailable' using detail = coalesce(v_c.code, '');\n    end if;\n    v_slot := null;\n    v_grant := null;\n    if nullif(v_a->>'grant_id', '') is not null then\n      -- 発行済みのクーポン: その 1 枚を押さえる（同じコードの同時の申込みは、この行のロックで 1 つだけ通る）\n      select * into v_g from coupon_grants where id = (v_a->>'grant_id')::uuid and shop_id = p_shop_id and campaign_id = v_c.id for update;\n      if not found or v_g.status <> 'available' or (v_g.expires_at is not null and v_g.expires_at < now())\n         or (v_g.customer_id is not null and p_subject <> 'c:' || v_g.customer_id::text) then\n        raise exception 'coupon_unavailable' using detail = coalesce(v_a->>'code', '');\n      end if;\n      update coupon_grants set status = 'held', reservation_id = p_reservation_id where id = v_g.id;\n      v_grant := v_g.id;\n    else\n      if v_c.per_customer_limit is not null then\n        perform pg_advisory_xact_lock(hashtextextended(v_c.id::text || '|' || p_subject, 0));\n        select count(*) into v_used from coupon_redemptions where campaign_id = v_c.id and subject = p_subject and status <> 'released';\n        if v_used >= v_c.per_customer_limit then raise exception 'coupon_limit_reached' using detail = coalesce(v_c.code, ''); end if;\n      end if;\n      if v_c.usage_limit is not null then\n        update coupon_slots set status = 'held', reservation_id = p_reservation_id\n         where id = (select id from coupon_slots where campaign_id = v_c.id and status = 'free' limit 1 for update skip locked)\n        returning id into v_slot;\n        if v_slot is null then raise exception 'coupon_exhausted' using detail = coalesce(v_c.code, ''); end if;\n      end if;\n    end if;\n    insert into coupon_redemptions (shop_id, campaign_id, reservation_id, subject, slot_id, amount_jpy, grant_id)\n    values (p_shop_id, v_c.id, p_reservation_id, p_subject, v_slot, greatest(0, coalesce((v_a->>'amount_jpy')::integer, 0)), v_grant);\n  end loop;\n\n  select jsonb_agg(e || jsonb_build_object('discount_jpy',\n           least((e->>'qty')::integer * (e->>'unit_price_jpy')::integer,\n                 greatest(0, coalesce((select (l->>'discount_jpy')::integer from jsonb_array_elements(v_lines) l where l->>'sku_id' = e->>'sku_id' limit 1), 0)))))\n    into v_items from jsonb_array_elements(v_res.items) e;\n  update reservations set discount_jpy = v_total, discounts = p_discounts->'applied', items = coalesce(v_items, items) where id = p_reservation_id;\n  return jsonb_build_object('discount_jpy', v_total);\nend;\n$$;\n\nrevoke execute on function coupon_grants_issue(uuid, uuid, uuid[], integer) from public, anon;\ngrant execute on function coupon_grants_issue(uuid, uuid, uuid[], integer) to authenticated;\nrevoke execute on function banto_grant_code() from public, anon, authenticated;\nrevoke execute on function coupon_grant_revoke(uuid, uuid) from public, anon;\ngrant execute on function coupon_grant_revoke(uuid, uuid) to authenticated;\nrevoke execute on function member_coupons(uuid, uuid, integer) from public, anon, authenticated;\ngrant execute on function member_coupons(uuid, uuid, integer) to service_role;\nrevoke execute on function coupon_lookup(uuid, text[], text) from public, anon, authenticated;\ngrant execute on function coupon_lookup(uuid, text[], text) to service_role;\nrevoke execute on function apply_reservation_discounts(uuid, uuid, text, jsonb) from public, anon, authenticated;\ngrant execute on function apply_reservation_discounts(uuid, uuid, text, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0019_coupon_grants');\n" },
  { version: "0020_coupon_auto", sql: "-- 0020_coupon_auto: クーポンの自動発行と、先着の「クーポンを獲得する」（docs/coupons.md §7、09-coupons.md §5-3）\n--\n-- coupon_campaigns.auto_grant … 'first_login'（会員が初めてログインしたとき = 会員登録。取り込んだ会員は初回のログインで）\n--                                'after_purchase'（会員の注文が確定したとき。次回使えるクーポン）\n-- coupon_campaigns.claimable  … 先着の獲得ページ（/<ショップ>/coupons/<キャンペーン>）で、ログイン中の会員が 1 人 1 枚もらえる。\n--                                全体の上限（usage_limit）があれば、獲得のときに空き枠（coupon_slots）を取り合う。\n--                                獲得したらその会員のクーポン（coupon_grants）になるので、使うときに取り合いは起きない。\n-- 発行はどれも「使っていない同じキャンペーンのクーポンを持っていなければ 1 枚」（0019 の発行と同じ）。\n\nalter table coupon_campaigns add column if not exists auto_grant text check (auto_grant is null or auto_grant in ('first_login', 'after_purchase'));\nalter table coupon_campaigns add column if not exists claimable boolean not null default false;\n\n-- 1 枚発行する（中で使うだけ。外からは呼べない）。発行したら true\ncreate or replace function banto_grant_to_customer(p_campaign coupon_campaigns, p_customer_id uuid)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_expires timestamptz; v_code text;\nbegin\n  if exists (select 1 from coupon_grants where campaign_id = p_campaign.id and customer_id = p_customer_id and status in ('available', 'held')) then\n    return false;\n  end if;\n  v_expires := case when p_campaign.grant_valid_days is not null then now() + make_interval(days => p_campaign.grant_valid_days) end;\n  if p_campaign.ends_at is not null and (v_expires is null or v_expires > p_campaign.ends_at) then v_expires := p_campaign.ends_at; end if;\n  loop\n    v_code := banto_grant_code();\n    begin\n      insert into coupon_grants (shop_id, campaign_id, code, customer_id, expires_at) values (p_campaign.shop_id, p_campaign.id, v_code, p_customer_id, v_expires);\n      return true;\n    exception when unique_violation then null;\n    end;\n  end loop;\nend;\n$$;\nrevoke execute on function banto_grant_to_customer(coupon_campaigns, uuid) from public, anon, authenticated;\n\n-- 有効で期間内のキャンペーンだけ\ncreate or replace function banto_campaign_live(p_c coupon_campaigns)\nreturns boolean\nlanguage sql\nstable\nset search_path = public\nas $$\n  select p_c.active and (p_c.starts_at is null or p_c.starts_at <= now()) and (p_c.ends_at is null or p_c.ends_at > now());\n$$;\nrevoke execute on function banto_campaign_live(coupon_campaigns) from public, anon, authenticated;\n\n-- 初めてログインしたとき\ncreate or replace function banto_coupon_first_login()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_c coupon_campaigns%rowtype;\nbegin\n  if old.last_login_at is not null or new.last_login_at is null then return new; end if;\n  for v_c in select * from coupon_campaigns where shop_id = new.shop_id and auto_grant = 'first_login' loop\n    if banto_campaign_live(v_c) then perform banto_grant_to_customer(v_c, new.id); end if;\n  end loop;\n  return new;\nend;\n$$;\ndrop trigger if exists customers_coupon_first_login on customers;\ncreate trigger customers_coupon_first_login after update of last_login_at on customers for each row execute function banto_coupon_first_login();\nrevoke execute on function banto_coupon_first_login() from public, anon, authenticated;\n\n-- 会員の注文が確定したとき（次回使えるクーポン）\ncreate or replace function banto_coupon_after_purchase()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_c coupon_campaigns%rowtype;\nbegin\n  if new.customer_id is null then return new; end if;\n  for v_c in select * from coupon_campaigns where shop_id = new.shop_id and auto_grant = 'after_purchase' loop\n    if banto_campaign_live(v_c) and exists (select 1 from customers where shop_id = new.shop_id and id = new.customer_id) then\n      perform banto_grant_to_customer(v_c, new.customer_id);\n    end if;\n  end loop;\n  return new;\nend;\n$$;\ndrop trigger if exists orders_coupon_after_purchase on orders;\ncreate trigger orders_coupon_after_purchase after insert on orders for each row execute function banto_coupon_after_purchase();\nrevoke execute on function banto_coupon_after_purchase() from public, anon, authenticated;\n\n-- 先着の獲得ページに出すキャンペーン（anon。公開中のショップの、獲得できるキャンペーンの表示に要る値だけ）\ncreate or replace function coupon_claim_info(p_shop_id uuid, p_campaign_id uuid)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object('id', c.id, 'name', c.name, 'kind', c.kind, 'value', c.value, 'starts_at', c.starts_at, 'ends_at', c.ends_at,\n                            'live', banto_campaign_live(c), 'conditions', jsonb_build_object('min_subtotal_jpy', c.conditions->'min_subtotal_jpy'),\n                            'remaining', case when c.usage_limit is null then null else (select count(*) from coupon_slots s where s.campaign_id = c.id and s.status = 'free') end)\n    from coupon_campaigns c join shops s on s.id = c.shop_id\n   where c.id = p_campaign_id and c.shop_id = p_shop_id and c.claimable and s.published;\n$$;\n\n-- 獲得する（service_role、会員の世代を確かめる）。戻り値: { ok, reason?, code? }\ncreate or replace function member_claim_coupon(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_campaign_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_c coupon_campaigns%rowtype; v_slot bigint; v_code text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_claim_coupon: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then\n    return jsonb_build_object('ok', false, 'reason', 'session');\n  end if;\n  select * into v_c from coupon_campaigns where id = p_campaign_id and shop_id = p_shop_id and claimable;\n  if not found or not banto_campaign_live(v_c) then return jsonb_build_object('ok', false, 'reason', 'unavailable'); end if;\n  -- 1 人 1 枚（使ったものも数える。取り消されたものは数えない）。同じ人の同時の申込みだけ直列にする\n  perform pg_advisory_xact_lock(hashtextextended('claim|' || v_c.id::text || '|' || p_customer_id::text, 0));\n  if exists (select 1 from coupon_grants where campaign_id = v_c.id and customer_id = p_customer_id and status <> 'revoked') then\n    return jsonb_build_object('ok', false, 'reason', 'already');\n  end if;\n  if v_c.usage_limit is not null then\n    update coupon_slots set status = 'used'\n     where id = (select id from coupon_slots where campaign_id = v_c.id and status = 'free' limit 1 for update skip locked)\n    returning id into v_slot;\n    if v_slot is null then return jsonb_build_object('ok', false, 'reason', 'exhausted'); end if;\n  end if;\n  perform banto_grant_to_customer(v_c, p_customer_id);\n  select code into v_code from coupon_grants where campaign_id = v_c.id and customer_id = p_customer_id and status = 'available' order by created_at desc limit 1;\n  return jsonb_build_object('ok', true, 'code', v_code);\nend;\n$$;\n\nrevoke execute on function coupon_claim_info(uuid, uuid) from public;\ngrant execute on function coupon_claim_info(uuid, uuid) to anon, authenticated, service_role;\nrevoke execute on function member_claim_coupon(uuid, uuid, integer, uuid) from public, anon, authenticated;\ngrant execute on function member_claim_coupon(uuid, uuid, integer, uuid) to service_role;\n\ninsert into banto_migrations (version) values ('0020_coupon_auto');\n" },
  { version: "0021_line_messaging", sql: "-- 0021_line_messaging: ショップごとの LINE 公式アカウント（Messaging API）で、購入者に注文を知らせる（docs/line.md）\n--\n-- shop_secret_boxes … ショップごとの外部サービスの秘密の暗号文（今は purpose = 'line_messaging' のチャネルアクセストークンだけ）。\n--   CLAUDE.md §1-5 の例外を広げる（人間の決定 2026-10-17）: Worker がサイトの秘密から作った鍵で AES-GCM で暗号化し、\n--   暗号文だけを置く（src/members/secret-box.ts、追加認証データはショップと用途）。運営者にも暗号文の列は読ませない。\n-- 送り先は LINE でログインした会員の LINE の利用者 ID（member_identities、0014）。LINE ログインのチャネルと\n-- Messaging API のチャネルが同じ「プロバイダー」なら、利用者 ID は同じになる。\n\ncreate table shop_secret_boxes (\n  shop_id uuid not null references shops(id) on delete cascade,\n  purpose text not null check (purpose in ('line_messaging')),\n  secret_box text not null check (secret_box ~ '^v1\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$'),\n  updated_at timestamptz not null default now(),\n  primary key (shop_id, purpose)\n);\nalter table shop_secret_boxes enable row level security;\ncreate policy shop_secret_boxes_owner_select on shop_secret_boxes for select using (banto_owns_shop(shop_id));\n-- 運営者は「設定済みか」だけ読める（暗号文の列は読めない）\nrevoke all on shop_secret_boxes from anon, authenticated;\ngrant select (shop_id, purpose, updated_at) on shop_secret_boxes to authenticated;\n\n-- 保存・削除（owner）。p_secret_box が null なら消す\ncreate or replace function shop_secret_save(p_shop_id uuid, p_purpose text, p_secret_box text)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if p_purpose not in ('line_messaging') then raise exception 'invalid_purpose'; end if;\n  if p_secret_box is null then\n    delete from shop_secret_boxes where shop_id = p_shop_id and purpose = p_purpose;\n    return true;\n  end if;\n  insert into shop_secret_boxes (shop_id, purpose, secret_box) values (p_shop_id, p_purpose, p_secret_box)\n  on conflict (shop_id, purpose) do update set secret_box = excluded.secret_box, updated_at = now();\n  return true;\nend;\n$$;\n\n-- 暗号文を読む（service_role。同梱プラグインが送るときだけ）\ncreate or replace function shop_secret(p_shop_id uuid, p_purpose text)\nreturns text\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'shop_secret: service_role only' using errcode = '42501';\n  end if;\n  return (select secret_box from shop_secret_boxes where shop_id = p_shop_id and purpose = p_purpose);\nend;\n$$;\n\n-- 注文を LINE で知らせる相手（service_role）。会員の注文で、その会員が LINE と結びついているときだけ。\n-- 返すのは LINE の利用者 ID と、知らせる文に要る値（注文番号・合計・ショップ名）だけ（住所・氏名は返さない）\ncreate or replace function order_line_recipient(p_order_id uuid, p_shop_id uuid)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'order_line_recipient: service_role only' using errcode = '42501';\n  end if;\n  return (\n    select jsonb_build_object('line_user_id', i.subject, 'number', o.number, 'total_jpy', o.total_jpy, 'shop_name', s.name, 'status', o.status)\n      from orders o join shops s on s.id = o.shop_id\n      join member_identities i on i.shop_id = o.shop_id and i.customer_id = o.customer_id and i.provider = 'line'\n     where o.id = p_order_id and o.shop_id = p_shop_id and o.customer_id is not null\n     limit 1);\nend;\n$$;\n\nrevoke execute on function shop_secret_save(uuid, text, text) from public, anon;\ngrant execute on function shop_secret_save(uuid, text, text) to authenticated;\nrevoke execute on function shop_secret(uuid, text) from public, anon, authenticated;\ngrant execute on function shop_secret(uuid, text) to service_role;\nrevoke execute on function order_line_recipient(uuid, uuid) from public, anon, authenticated;\ngrant execute on function order_line_recipient(uuid, uuid) to service_role;\n\ninsert into banto_migrations (version) values ('0021_line_messaging');\n" },
  { version: "0022_tracking", sql: "-- 0022_tracking: 送り状番号（お問い合わせ番号）の取り込み・注文メールの税率ごとの内訳・WooCommerce の税区分・バックアップの復元の続き\n--\n-- - orders.tracking_carrier / tracking_number … 発送したときの運送会社とお問い合わせ番号（docs/shipping-labels.md §5）。\n--   ship_orders（authenticated、所有を検証）が注文番号で突き合わせて入れ、支払い済みの注文は発送済みにして order.shipped を送る。\n--   hooks のペイロードには載せない（届け先の地域が分かるため）。購入者には注文照会（lookup_order）とメールで見せる。\n-- - order_contact（メール通知）に税率・端数の扱い・明細の値引き・お問い合わせ番号を足す（計算は src/commerce/tax.ts）。\n-- - import_tax_classes … WooCommerce の取り込みで、商品の税区分（0017）を slug で入れる（import_catalog は 0017 の列を知らない）。\n-- - restore_commerce … バックアップからの復元の続き: クーポン（キャンペーン・使用済みの数・発行済み）、注文の値引き・配送の指定・\n--   お問い合わせ番号、明細の値引き。1 人あたりの使用回数（coupon_redemptions）は予約に紐づくので戻さない（docs/backup.md）。\n\nalter table orders add column if not exists tracking_carrier text check (tracking_carrier is null or tracking_carrier in ('yamato', 'sagawa', 'japanpost', 'other'));\nalter table orders add column if not exists tracking_number text check (tracking_number is null or tracking_number ~ '^[0-9A-Za-z]{4,40}$');\n\n-- ---------- 送り状番号の取り込み ----------\n-- p_items: [{ number, carrier, tracking }]。番号の区切り（- と空白）は外す。\n-- 支払い済み → 発送済みにして order.shipped。発送済み → 番号だけ入れ直す（通知はしない）。それ以外（キャンセル等）・見つからない注文は飛ばす。\ncreate or replace function ship_orders(p_shop_id uuid, p_items jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_o orders%rowtype; v_num text; v_carrier text; v_tracking text;\n  v_shipped integer := 0; v_updated integer := 0; v_invalid integer := 0;\n  v_missing jsonb := '[]'::jsonb;\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 500 then raise exception 'invalid_items'; end if;\n  for v_row in select e from jsonb_array_elements(p_items) e loop\n    v_num := btrim(coalesce(v_row->>'number', ''));\n    v_carrier := v_row->>'carrier';\n    v_tracking := regexp_replace(coalesce(v_row->>'tracking', ''), '[\\s-]', '', 'g');\n    if v_num !~ '^[0-9]{1,9}$' or v_carrier is null or v_carrier not in ('yamato', 'sagawa', 'japanpost', 'other') or v_tracking !~ '^[0-9A-Za-z]{4,40}$' then\n      v_invalid := v_invalid + 1;\n      continue;\n    end if;\n    select * into v_o from orders where shop_id = p_shop_id and number = v_num::integer and status in ('paid', 'shipped') for update;\n    if not found then\n      if jsonb_array_length(v_missing) < 50 then v_missing := v_missing || to_jsonb(v_num::integer); end if;\n      continue;\n    end if;\n    if v_o.status = 'paid' then\n      update orders set status = 'shipped', shipped_at = now(), tracking_carrier = v_carrier, tracking_number = v_tracking, updated_at = now()\n       where id = v_o.id returning * into v_o;\n      perform enqueue_hook(p_shop_id, 'order.shipped',\n        jsonb_build_object('order_id', v_o.id, 'order_number', v_o.number, 'shop_id', p_shop_id, 'total_jpy', v_o.total_jpy, 'status', v_o.status,\n                           'shipped_at', v_o.shipped_at, 'customer_id', v_o.customer_id));\n      v_shipped := v_shipped + 1;\n    else\n      update orders set tracking_carrier = v_carrier, tracking_number = v_tracking, updated_at = now() where id = v_o.id;\n      v_updated := v_updated + 1;\n    end if;\n  end loop;\n  return jsonb_build_object('shipped', v_shipped, 'updated', v_updated, 'invalid', v_invalid, 'missing', v_missing);\nend;\n$$;\n\n-- ---------- 購入者向けの注文照会（0017 を差し替え: お問い合わせ番号を足す。住所は返さない） ----------\ncreate or replace function lookup_order(p_shop_id uuid, p_number integer, p_email text)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object('number', o.number, 'status', o.status, 'created_at', o.created_at, 'shipped_at', o.shipped_at,\n                            'total_jpy', o.total_jpy, 'shipping_jpy', o.shipping_jpy, 'discount_jpy', o.discount_jpy,\n                            'shipping_tax_rate', o.shipping_tax_rate, 'tax_rounding', o.tax_rounding, 'payment_provider', o.payment_provider,\n                            'tracking', case when o.tracking_number is not null then jsonb_build_object('carrier', o.tracking_carrier, 'number', o.tracking_number) end,\n                            'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                                            from jsonb_array_elements(coalesce(o.discounts, '[]'::jsonb)) d),\n                            'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy, 'tax_rate', oi.tax_rate, 'discount_jpy', oi.discount_jpy) order by oi.id), '[]'::jsonb)\n                                        from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = o.id))\n    from orders o join shops s on s.id = o.shop_id\n   where o.shop_id = p_shop_id and o.number = p_number and s.published\n     and o.customer_email is not null and lower(o.customer_email) = lower(btrim(p_email))\n   limit 1;\n$$;\n\n-- ---------- メール通知の連絡先（0015 を差し替え: 税率・端数・明細の値引き・ショップの税の設定・お問い合わせ番号） ----------\ncreate or replace function order_contact(p_order_id uuid, p_shop_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_o orders%rowtype; v_s shops%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'order_contact: service_role only' using errcode = '42501';\n  end if;\n  select * into v_o from orders where id = p_order_id and shop_id = p_shop_id;\n  if not found then raise exception 'not_found'; end if;\n  select * into v_s from shops where id = p_shop_id;\n  return jsonb_build_object(\n    'order_id', v_o.id, 'number', v_o.number, 'status', v_o.status, 'created_at', v_o.created_at,\n    'total_jpy', v_o.total_jpy, 'shipping_jpy', v_o.shipping_jpy, 'discount_jpy', v_o.discount_jpy, 'payment_provider', v_o.payment_provider,\n    'shipping_tax_rate', v_o.shipping_tax_rate, 'tax_rounding', v_o.tax_rounding,\n    'tracking', case when v_o.tracking_number is not null then jsonb_build_object('carrier', v_o.tracking_carrier, 'number', v_o.tracking_number) end,\n    'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                    from jsonb_array_elements(coalesce(v_o.discounts, '[]'::jsonb)) d),\n    'customer_email', v_o.customer_email, 'customer_name', v_o.customer_name, 'shipping_address', v_o.shipping_address,\n    'shop', jsonb_build_object('name', v_s.name, 'slug', v_s.slug, 'domain', v_s.domain,\n                               'contact_email', v_s.settings->>'contact_email', 'return_policy', v_s.return_policy,\n                               'tax', jsonb_build_object('tax_rate', v_s.settings->'tax_rate', 'tax_rate_reduced', v_s.settings->'tax_rate_reduced', 'tax_rounding', v_s.settings->'tax_rounding')),\n    'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy,\n                                                           'tax_rate', oi.tax_rate, 'discount_jpy', oi.discount_jpy) order by oi.id), '[]'::jsonb)\n                from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = v_o.id));\nend;\n$$;\n\n-- ---------- WooCommerce の取り込み: 税区分 ----------\n-- p_items: [{ slug, tax_class }]。区分の値が違う行・見つからない商品は飛ばす。入れた件数を返す\ncreate or replace function import_tax_classes(p_shop_id uuid, p_items jsonb)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_row jsonb; v_n integer; v_total integer := 0;\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 1000 then raise exception 'invalid_items'; end if;\n  for v_row in select e from jsonb_array_elements(p_items) e loop\n    if v_row->>'tax_class' in ('standard', 'reduced', 'exempt') then\n      update products set tax_class = v_row->>'tax_class', updated_at = now()\n       where shop_id = p_shop_id and slug = v_row->>'slug' and tax_class is distinct from v_row->>'tax_class';\n      get diagnostics v_n = row_count; v_total := v_total + v_n;\n    end if;\n  end loop;\n  return v_total;\nend;\n$$;\n\n-- ---------- バックアップからの復元の続き ----------\n-- restore_shop_data（0012）・restore_catalog（0008）・restore_tax（0017）の後に呼ぶ。p_data は書き出しの tables そのまま。\n-- 商品は slug、カテゴリーは slug、注文は注文番号、SKU は品番で突き合わせる（id は振り直されているため）。会員は同じ id で戻っている。\ncreate or replace function restore_commerce(p_shop_id uuid, p_data jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_new uuid; v_n integer;\n  v_product_map jsonb := '{}'::jsonb;\n  v_category_map jsonb := '{}'::jsonb;\n  v_campaign_map jsonb := '{}'::jsonb;\n  v_order_num jsonb := '{}'::jsonb;\n  v_sku_code jsonb := '{}'::jsonb;\n  v_cond jsonb; v_key text; v_used integer;\n  v_campaigns integer := 0; v_grants integer := 0; v_grants_skipped integer := 0; v_orders integer := 0; v_items integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'restore_commerce: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id) then raise exception 'shop_not_found'; end if;\n\n  -- 旧 id → 新 id（slug で）\n  for v_row in select e from jsonb_array_elements(coalesce(p_data->'products', '[]'::jsonb)) e loop\n    select id into v_new from products where shop_id = p_shop_id and slug = v_row->>'slug';\n    if v_new is not null and v_row ? 'id' then v_product_map := v_product_map || jsonb_build_object(v_row->>'id', v_new::text); end if;\n  end loop;\n  for v_row in select e from jsonb_array_elements(coalesce(p_data->'categories', '[]'::jsonb)) e loop\n    select id into v_new from categories where shop_id = p_shop_id and slug = v_row->>'slug';\n    if v_new is not null and v_row ? 'id' then v_category_map := v_category_map || jsonb_build_object(v_row->>'id', v_new::text); end if;\n  end loop;\n\n  -- クーポン（キャンペーンがまだ無いショップにだけ。2 回目の呼び出しで二重にしない）\n  if not exists (select 1 from coupon_campaigns where shop_id = p_shop_id) then\n    for v_row in select e from jsonb_array_elements(coalesce(p_data->'coupon_campaigns', '[]'::jsonb)) e loop\n      -- 対象の商品・カテゴリーの id を振り直す（戻らなかったものは外す）\n      v_cond := case when jsonb_typeof(v_row->'conditions') = 'object' then v_row->'conditions' else '{}'::jsonb end;\n      foreach v_key in array array['product_ids', 'exclude_product_ids'] loop\n        if jsonb_typeof(v_cond->v_key) = 'array' then\n          v_cond := jsonb_set(v_cond, array[v_key], coalesce((select jsonb_agg(v_product_map->(x #>> '{}')) from jsonb_array_elements(v_cond->v_key) x where v_product_map ? (x #>> '{}')), '[]'::jsonb));\n        end if;\n      end loop;\n      foreach v_key in array array['category_ids', 'exclude_category_ids'] loop\n        if jsonb_typeof(v_cond->v_key) = 'array' then\n          v_cond := jsonb_set(v_cond, array[v_key], coalesce((select jsonb_agg(v_category_map->(x #>> '{}')) from jsonb_array_elements(v_cond->v_key) x where v_category_map ? (x #>> '{}')), '[]'::jsonb));\n        end if;\n      end loop;\n      insert into coupon_campaigns (shop_id, name, code, kind, value, starts_at, ends_at, usage_limit, per_customer_limit, combinable, audience,\n                                    conditions, active, grant_valid_days, auto_grant, claimable, created_at, updated_at)\n      values (p_shop_id, v_row->>'name', v_row->>'code', v_row->>'kind', coalesce((v_row->>'value')::integer, 0),\n              (v_row->>'starts_at')::timestamptz, (v_row->>'ends_at')::timestamptz, (v_row->>'usage_limit')::integer, (v_row->>'per_customer_limit')::integer,\n              coalesce((v_row->>'combinable')::boolean, false), coalesce(v_row->>'audience', 'public'), v_cond, coalesce((v_row->>'active')::boolean, true),\n              (v_row->>'grant_valid_days')::integer, v_row->>'auto_grant', coalesce((v_row->>'claimable')::boolean, false),\n              coalesce((v_row->>'created_at')::timestamptz, now()), coalesce((v_row->>'updated_at')::timestamptz, now()))\n      returning id into v_new;\n      v_campaign_map := v_campaign_map || jsonb_build_object(v_row->>'id', v_new::text);\n      v_campaigns := v_campaigns + 1;\n      -- 全体の上限の使用済みの数（書き出しの coupon_slots は使用済みの行だけ）\n      select count(*) into v_used from jsonb_array_elements(coalesce(p_data->'coupon_slots', '[]'::jsonb)) s\n       where s->>'campaign_id' = v_row->>'id' and s->>'status' = 'used';\n      if v_used > 0 then\n        update coupon_slots set status = 'used'\n         where id in (select id from coupon_slots where campaign_id = v_new and status = 'free' order by id limit v_used);\n      end if;\n    end loop;\n\n    -- 発行済みのクーポン。会員に発行したもので、その会員が戻っていないものは飛ばす（誰でも使えるコードにしない）\n    for v_row in select e from jsonb_array_elements(coalesce(p_data->'coupon_grants', '[]'::jsonb)) e loop\n      if not (v_campaign_map ? (v_row->>'campaign_id'))\n         or (nullif(v_row->>'customer_id', '') is not null and not exists (select 1 from customers where shop_id = p_shop_id and id = (v_row->>'customer_id')::uuid)) then\n        v_grants_skipped := v_grants_skipped + 1;\n        continue;\n      end if;\n      insert into coupon_grants (shop_id, campaign_id, code, customer_id, status, expires_at, created_at, used_at)\n      values (p_shop_id, (v_campaign_map->>(v_row->>'campaign_id'))::uuid, v_row->>'code', nullif(v_row->>'customer_id', '')::uuid,\n              case when v_row->>'status' in ('used', 'revoked') then v_row->>'status' else 'available' end,\n              (v_row->>'expires_at')::timestamptz, coalesce((v_row->>'created_at')::timestamptz, now()),\n              case when v_row->>'status' = 'used' then (v_row->>'used_at')::timestamptz end)\n      on conflict (shop_id, code) do nothing;\n      get diagnostics v_n = row_count;\n      if v_n = 1 then v_grants := v_grants + 1; else v_grants_skipped := v_grants_skipped + 1; end if;\n    end loop;\n  end if;\n\n  -- 注文: 値引き・配送の指定・お問い合わせ番号（restore_shop_data は 0010 以降の列を知らない）\n  for v_row in select e from jsonb_array_elements(coalesce(p_data->'orders', '[]'::jsonb)) e loop\n    if coalesce(v_row->>'number', '') !~ '^[0-9]{1,9}$' then continue; end if;\n    if v_row ? 'id' then v_order_num := v_order_num || jsonb_build_object(v_row->>'id', v_row->'number'); end if;\n    update orders set\n      discount_jpy = greatest(0, coalesce((v_row->>'discount_jpy')::integer, discount_jpy)),\n      discounts = case when jsonb_typeof(v_row->'discounts') = 'array' then v_row->'discounts' else discounts end,\n      amount_paid_jpy = coalesce((v_row->>'amount_paid_jpy')::integer, amount_paid_jpy),\n      delivery = case when jsonb_typeof(v_row->'delivery') = 'object' then v_row->'delivery' else delivery end,\n      tracking_carrier = case when v_row->>'tracking_carrier' in ('yamato', 'sagawa', 'japanpost', 'other') and coalesce(v_row->>'tracking_number', '') ~ '^[0-9A-Za-z]{4,40}$'\n                              then v_row->>'tracking_carrier' else tracking_carrier end,\n      tracking_number = case when v_row->>'tracking_carrier' in ('yamato', 'sagawa', 'japanpost', 'other') and coalesce(v_row->>'tracking_number', '') ~ '^[0-9A-Za-z]{4,40}$'\n                             then v_row->>'tracking_number' else tracking_number end\n     where shop_id = p_shop_id and number = (v_row->>'number')::integer;\n    get diagnostics v_n = row_count; v_orders := v_orders + v_n;\n  end loop;\n\n  -- 明細の値引き（注文番号 + SKU の品番で）\n  for v_row in select e from jsonb_array_elements(coalesce(p_data->'skus', '[]'::jsonb)) e loop\n    if v_row ? 'id' and v_row ? 'code' then v_sku_code := v_sku_code || jsonb_build_object(v_row->>'id', v_row->>'code'); end if;\n  end loop;\n  for v_row in select e from jsonb_array_elements(coalesce(p_data->'order_items', '[]'::jsonb)) e loop\n    if coalesce((v_row->>'discount_jpy')::integer, 0) > 0 and v_order_num ? (v_row->>'order_id') and v_sku_code ? (v_row->>'sku_id') then\n      update order_items oi set discount_jpy = (v_row->>'discount_jpy')::integer\n        from orders o, skus k\n       where o.shop_id = p_shop_id and o.number = (v_order_num->>(v_row->>'order_id'))::integer\n         and k.shop_id = p_shop_id and k.code = v_sku_code->>(v_row->>'sku_id')\n         and oi.order_id = o.id and oi.sku_id = k.id and oi.qty = coalesce((v_row->>'qty')::integer, oi.qty);\n      get diagnostics v_n = row_count; v_items := v_items + v_n;\n    end if;\n  end loop;\n\n  return jsonb_build_object('coupon_campaigns', v_campaigns, 'coupon_grants', v_grants, 'coupon_grants_skipped', v_grants_skipped,\n                            'order_discounts', v_orders, 'item_discounts', v_items);\nend;\n$$;\n\nrevoke execute on function ship_orders(uuid, jsonb) from public, anon;\ngrant execute on function ship_orders(uuid, jsonb) to authenticated, service_role;\nrevoke execute on function lookup_order(uuid, integer, text) from public;\ngrant execute on function lookup_order(uuid, integer, text) to anon, authenticated, service_role;\nrevoke execute on function order_contact(uuid, uuid) from public, anon, authenticated;\ngrant execute on function order_contact(uuid, uuid) to service_role;\nrevoke execute on function import_tax_classes(uuid, jsonb) from public, anon;\ngrant execute on function import_tax_classes(uuid, jsonb) to authenticated, service_role;\nrevoke execute on function restore_commerce(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function restore_commerce(uuid, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0022_tracking');\n" },
  { version: "0023_woo_history", sql: "-- 0023_woo_history: WooCommerce からの移行の続き（docs/woo-import.md）\n--\n-- - 過去の注文の取り込み（import_orders、authenticated・所有を検証）。WooCommerce の注文番号のまま入れ、ショップの連番はその続きから。\n--   在庫・クーポンの回数・hooks・自動発行のクーポンには触らない（過去の記録として入れるだけ）。\n--     orders.external_ref … 取り込み元の ID（'woocommerce:<ID>'）。同じ注文を二重に入れない\n--     order_items.sku_id … null を許す（Banto に無い商品の明細）。item_name / item_variant … 取り込んだ時点の品名\n-- - クーポンの 1 人ごとの使用回数（import_coupon_usage）: 予約に紐づかない「使用済み」の使用記録として入れる。\n--   1 人あたりの上限の数え方（coupon_lookup・apply_reservation_discounts）は使用記録の行を数えるので、関数は変えない。\n-- - メールアドレスで使える人を絞ったクーポン（coupon_grants_for_emails）: その人ごとに発行済みのクーポンにする（0019）。\n--     coupon_campaigns.external_ref … 取り込み元の ID。コードを持たないキャンペーンでも二重に作らない\n-- - restore_history … バックアップの復元で、取り込み元の ID と明細の品名、SKU の無い明細を戻す（0022 の restore_commerce の後）\n\nalter table orders add column if not exists external_ref text check (external_ref is null or length(external_ref) between 1 and 100);\ncreate unique index if not exists orders_external_ref on orders(shop_id, external_ref) where external_ref is not null;\nalter table coupon_campaigns add column if not exists external_ref text check (external_ref is null or length(external_ref) between 1 and 100);\ncreate unique index if not exists coupon_campaigns_external_ref on coupon_campaigns(shop_id, external_ref) where external_ref is not null;\n\nalter table order_items alter column sku_id drop not null;\nalter table order_items add column if not exists item_name text check (item_name is null or length(item_name) <= 200);\nalter table order_items add column if not exists item_variant text check (item_variant is null or length(item_variant) <= 200);\n\n-- 取り込んだ使用は予約を持たない（使用済みのまま。解放・キャンセルの対象にならない）\nalter table coupon_redemptions alter column reservation_id drop not null;\nalter table coupon_redemptions drop constraint if exists coupon_redemptions_imported_used;\nalter table coupon_redemptions add constraint coupon_redemptions_imported_used check (reservation_id is not null or status = 'used');\n\n-- 会員の注文の自動発行（0020 を差し替え）: 取り込んだ過去の注文では配らない\ncreate or replace function banto_coupon_after_purchase()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_c coupon_campaigns%rowtype;\nbegin\n  if new.customer_id is null or new.external_ref is not null then return new; end if;\n  for v_c in select * from coupon_campaigns where shop_id = new.shop_id and auto_grant = 'after_purchase' loop\n    if banto_campaign_live(v_c) and exists (select 1 from customers where shop_id = new.shop_id and id = new.customer_id) then\n      perform banto_grant_to_customer(v_c, new.customer_id);\n    end if;\n  end loop;\n  return new;\nend;\n$$;\n\n-- クーポンの使用者の識別子（src/commerce/discounts.ts の couponSubject と同じ: メールアドレスは小文字にして SHA-256）\ncreate or replace function banto_email_subject(p_email text)\nreturns text\nlanguage sql\nimmutable\nset search_path = public\nas $$\n  select 'e:' || encode(sha256(convert_to(lower(btrim(p_email)), 'UTF8')), 'hex');\n$$;\n\n-- ---------- 過去の注文の取り込み ----------\n-- p_orders: [{ ref, number, status, created_at, shipped_at, total_jpy, shipping_jpy, discount_jpy, shipping_tax_rate,\n--              customer_email, customer_name, shipping_address, payment_ref,\n--              items: [{ sku, name, variant, qty, unit_price_jpy, discount_jpy, tax_rate }] }]\n-- 会員はメールアドレスで結ぶ。SKU は品番で結び、無ければ品名だけの明細にする。\ncreate or replace function import_orders(p_shop_id uuid, p_orders jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_it jsonb; v_id uuid; v_num integer; v_ref text; v_status text; v_cid uuid; v_sku uuid; v_rate numeric;\n  v_created integer := 0; v_existing integer := 0; v_items integer := 0; v_no_sku integer := 0; v_invalid integer := 0;\n  v_conflicts jsonb := '[]'::jsonb;\n  v_max integer;\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if jsonb_typeof(p_orders) <> 'array' or jsonb_array_length(p_orders) > 100 then raise exception 'invalid_orders'; end if;\n  for v_row in select e from jsonb_array_elements(p_orders) e loop\n    v_ref := left(btrim(coalesce(v_row->>'ref', '')), 100);\n    v_status := v_row->>'status';\n    if v_ref = '' or coalesce(v_row->>'number', '') !~ '^[0-9]{1,9}$' or v_status is null or v_status not in ('paid', 'shipped', 'cancelled', 'refunded')\n       or coalesce(v_row->>'total_jpy', '') !~ '^[0-9]{1,9}$' or jsonb_typeof(v_row->'items') <> 'array' then\n      v_invalid := v_invalid + 1;\n      continue;\n    end if;\n    if exists (select 1 from orders where shop_id = p_shop_id and external_ref = v_ref) then\n      v_existing := v_existing + 1;\n      continue;\n    end if;\n    v_num := (v_row->>'number')::integer;\n    if exists (select 1 from orders where shop_id = p_shop_id and number = v_num) then\n      if jsonb_array_length(v_conflicts) < 50 then v_conflicts := v_conflicts || to_jsonb(v_num); end if;\n      continue;\n    end if;\n    v_cid := null;\n    if nullif(btrim(coalesce(v_row->>'customer_email', '')), '') is not null then\n      select id into v_cid from customers where shop_id = p_shop_id and lower(email) = lower(btrim(v_row->>'customer_email')) limit 1;\n    end if;\n    v_rate := case when coalesce(v_row->>'shipping_tax_rate', '') ~ '^[0-9]{1,2}(\\.[0-9]{1,2})?$' then (v_row->>'shipping_tax_rate')::numeric end;\n    insert into orders (shop_id, reservation_id, status, total_jpy, shipping_jpy, discount_jpy, amount_paid_jpy, number, customer_id,\n                        customer_email, customer_name, shipping_address, payment_provider, payment_ref, shipped_at, shipping_tax_rate,\n                        external_ref, created_at, updated_at)\n    values (p_shop_id, null, v_status::order_status, (v_row->>'total_jpy')::integer, greatest(0, coalesce((v_row->>'shipping_jpy')::integer, 0)),\n            greatest(0, coalesce((v_row->>'discount_jpy')::integer, 0)), (v_row->>'total_jpy')::integer, v_num, v_cid,\n            nullif(lower(btrim(coalesce(v_row->>'customer_email', ''))), ''), left(nullif(btrim(coalesce(v_row->>'customer_name', '')), ''), 200),\n            case when jsonb_typeof(v_row->'shipping_address') = 'object' then v_row->'shipping_address' end,\n            'woocommerce', left(nullif(v_row->>'payment_ref', ''), 200),\n            case when v_status = 'shipped' then coalesce((v_row->>'shipped_at')::timestamptz, (v_row->>'created_at')::timestamptz, now()) end,\n            v_rate, v_ref, coalesce((v_row->>'created_at')::timestamptz, now()), coalesce((v_row->>'created_at')::timestamptz, now()))\n    returning id into v_id;\n    v_created := v_created + 1;\n    for v_it in select e from jsonb_array_elements(v_row->'items') e loop\n      if coalesce(v_it->>'qty', '') !~ '^[0-9]{1,6}$' or (v_it->>'qty')::integer <= 0 or coalesce(v_it->>'unit_price_jpy', '') !~ '^[0-9]{1,9}$' then continue; end if;\n      v_sku := null;\n      if nullif(btrim(coalesce(v_it->>'sku', '')), '') is not null then\n        select id into v_sku from skus where shop_id = p_shop_id and code = btrim(v_it->>'sku');\n      end if;\n      if v_sku is null then v_no_sku := v_no_sku + 1; end if;\n      insert into order_items (shop_id, order_id, sku_id, qty, unit_price_jpy, discount_jpy, tax_rate, item_name, item_variant)\n      values (p_shop_id, v_id, v_sku, (v_it->>'qty')::integer, (v_it->>'unit_price_jpy')::integer, greatest(0, coalesce((v_it->>'discount_jpy')::integer, 0)),\n              case when coalesce(v_it->>'tax_rate', '') ~ '^[0-9]{1,2}(\\.[0-9]{1,2})?$' then (v_it->>'tax_rate')::numeric end,\n              left(nullif(btrim(coalesce(v_it->>'name', '')), ''), 200), left(nullif(btrim(coalesce(v_it->>'variant', '')), ''), 200));\n      v_items := v_items + 1;\n    end loop;\n  end loop;\n  -- 新しい注文の番号は、取り込んだ番号の続きから\n  select max(number) into v_max from orders where shop_id = p_shop_id;\n  if v_max is not null then update shops set order_seq = greatest(order_seq, v_max) where id = p_shop_id; end if;\n  return jsonb_build_object('created', v_created, 'existing', v_existing, 'invalid', v_invalid, 'items', v_items, 'items_without_sku', v_no_sku, 'conflicts', v_conflicts);\nend;\n$$;\n\n-- ---------- クーポンの 1 人ごとの使用回数 ----------\n-- p_emails は使った人のメールアドレス（使った回数だけ並ぶ）。p_reset なら、そのキャンペーンに取り込んだ使用を入れ直す（何度流しても重ならない）。\n-- メールアドレスの識別子（ゲストの購入）と、同じアドレスの会員の識別子の両方に入れる（どちらで買っても数に入る）\ncreate or replace function import_coupon_usage(p_shop_id uuid, p_code text, p_emails text[], p_reset boolean)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_campaign uuid; v_email text; v_cid uuid; v_n integer := 0;\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if coalesce(array_length(p_emails, 1), 0) > 5000 then raise exception 'too_many'; end if;\n  select id into v_campaign from coupon_campaigns where shop_id = p_shop_id and code = upper(btrim(p_code));\n  if v_campaign is null then return jsonb_build_object('found', false, 'uses', 0); end if;\n  if p_reset then delete from coupon_redemptions where campaign_id = v_campaign and reservation_id is null; end if;\n  foreach v_email in array coalesce(p_emails, '{}'::text[]) loop\n    if position('@' in coalesce(v_email, '')) = 0 then continue; end if;\n    insert into coupon_redemptions (shop_id, campaign_id, reservation_id, subject, status) values (p_shop_id, v_campaign, null, banto_email_subject(v_email), 'used');\n    select id into v_cid from customers where shop_id = p_shop_id and lower(email) = lower(btrim(v_email)) limit 1;\n    if v_cid is not null then\n      insert into coupon_redemptions (shop_id, campaign_id, reservation_id, subject, status) values (p_shop_id, v_campaign, null, 'c:' || v_cid::text, 'used');\n    end if;\n    v_n := v_n + 1;\n  end loop;\n  return jsonb_build_object('found', true, 'uses', v_n);\nend;\n$$;\n\n-- ---------- メールアドレスで絞ったクーポン → その人ごとの発行済みクーポン ----------\n-- 会員がいればその会員に（マイクーポンに出る）、いなければコードだけのものを発行して返す（運営者が渡す）。\n-- 同じ会員に使える発行済みが既にあれば、それを返す。返すのは [{ email, code, member }]\ncreate or replace function coupon_grants_for_emails(p_shop_id uuid, p_campaign_id uuid, p_emails text[])\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_c coupon_campaigns%rowtype; v_email text; v_cid uuid; v_code text; v_expires timestamptz;\n  v_out jsonb := '[]'::jsonb;\nbegin\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if coalesce(array_length(p_emails, 1), 0) > 5000 then raise exception 'too_many'; end if;\n  select * into v_c from coupon_campaigns where id = p_campaign_id and shop_id = p_shop_id;\n  if not found then raise exception 'campaign_not_found'; end if;\n  v_expires := case when v_c.grant_valid_days is not null then now() + make_interval(days => v_c.grant_valid_days) end;\n  if v_c.ends_at is not null and (v_expires is null or v_expires > v_c.ends_at) then v_expires := v_c.ends_at; end if;\n  for v_email in select distinct lower(btrim(e)) from unnest(coalesce(p_emails, '{}'::text[])) e where position('@' in coalesce(e, '')) > 0 and position('*' in e) = 0 order by 1 loop\n    select id into v_cid from customers where shop_id = p_shop_id and lower(email) = v_email limit 1;\n    v_code := null;\n    if v_cid is not null then\n      select code into v_code from coupon_grants where campaign_id = v_c.id and customer_id = v_cid and status in ('available', 'held') limit 1;\n    end if;\n    if v_code is null then\n      loop\n        v_code := banto_grant_code();\n        begin\n          insert into coupon_grants (shop_id, campaign_id, code, customer_id, expires_at) values (p_shop_id, v_c.id, v_code, v_cid, v_expires);\n          exit;\n        exception when unique_violation then null;\n        end;\n      end loop;\n    end if;\n    v_out := v_out || jsonb_build_object('email', v_email, 'code', v_code, 'member', v_cid is not null);\n  end loop;\n  return v_out;\nend;\n$$;\n\n-- ---------- 購入者向けの注文照会・会員の注文 1 件（0022・0017 を差し替え: 取り込んだ明細の品名） ----------\ncreate or replace function lookup_order(p_shop_id uuid, p_number integer, p_email text)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object('number', o.number, 'status', o.status, 'created_at', o.created_at, 'shipped_at', o.shipped_at,\n                            'total_jpy', o.total_jpy, 'shipping_jpy', o.shipping_jpy, 'discount_jpy', o.discount_jpy,\n                            'shipping_tax_rate', o.shipping_tax_rate, 'tax_rounding', o.tax_rounding, 'payment_provider', o.payment_provider,\n                            'tracking', case when o.tracking_number is not null then jsonb_build_object('carrier', o.tracking_carrier, 'number', o.tracking_number) end,\n                            'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                                            from jsonb_array_elements(coalesce(o.discounts, '[]'::jsonb)) d),\n                            'items', (select coalesce(jsonb_agg(jsonb_build_object('name', coalesce(oi.item_name, p.name), 'sku', coalesce(oi.item_variant, k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy, 'tax_rate', oi.tax_rate, 'discount_jpy', oi.discount_jpy) order by oi.id), '[]'::jsonb)\n                                        from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = o.id))\n    from orders o join shops s on s.id = o.shop_id\n   where o.shop_id = p_shop_id and o.number = p_number and s.published\n     and o.customer_email is not null and lower(o.customer_email) = lower(btrim(p_email))\n   limit 1;\n$$;\n\ncreate or replace function member_order(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_number integer)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_order: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then return null; end if;\n  return (\n    select jsonb_build_object('number', o.number, 'status', o.status, 'created_at', o.created_at, 'shipped_at', o.shipped_at,\n                              'total_jpy', o.total_jpy, 'shipping_jpy', o.shipping_jpy, 'discount_jpy', o.discount_jpy,\n                              'shipping_tax_rate', o.shipping_tax_rate, 'tax_rounding', o.tax_rounding, 'payment_provider', o.payment_provider,\n                              'tracking', case when o.tracking_number is not null then jsonb_build_object('carrier', o.tracking_carrier, 'number', o.tracking_number) end,\n                              'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                                              from jsonb_array_elements(coalesce(o.discounts, '[]'::jsonb)) d),\n                              'items', (select coalesce(jsonb_agg(jsonb_build_object('name', coalesce(oi.item_name, p.name), 'sku', coalesce(oi.item_variant, k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy, 'tax_rate', oi.tax_rate, 'discount_jpy', oi.discount_jpy) order by oi.id), '[]'::jsonb)\n                                          from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = o.id))\n      from orders o\n     where o.shop_id = p_shop_id and o.customer_id = p_customer_id and o.number = p_number);\nend;\n$$;\n\n-- ---------- バックアップからの復元の続き ----------\n-- restore_commerce（0022）の後に呼ぶ。注文と明細の 0023 の列を注文番号・品番で戻し、SKU の無い明細（restore_shop_data が飛ばす）を入れる\ncreate or replace function restore_history(p_shop_id uuid, p_data jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_n integer; v_order uuid;\n  v_order_num jsonb := '{}'::jsonb; v_sku_code jsonb := '{}'::jsonb;\n  v_orders integer := 0; v_items integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'restore_history: service_role only' using errcode = '42501';\n  end if;\n  for v_row in select e from jsonb_array_elements(coalesce(p_data->'orders', '[]'::jsonb)) e loop\n    if coalesce(v_row->>'number', '') !~ '^[0-9]{1,9}$' then continue; end if;\n    if v_row ? 'id' then v_order_num := v_order_num || jsonb_build_object(v_row->>'id', v_row->'number'); end if;\n    if nullif(v_row->>'external_ref', '') is not null then\n      update orders set external_ref = left(v_row->>'external_ref', 100)\n       where shop_id = p_shop_id and number = (v_row->>'number')::integer and external_ref is null\n         and not exists (select 1 from orders x where x.shop_id = p_shop_id and x.external_ref = v_row->>'external_ref');\n      get diagnostics v_n = row_count; v_orders := v_orders + v_n;\n    end if;\n  end loop;\n  for v_row in select e from jsonb_array_elements(coalesce(p_data->'skus', '[]'::jsonb)) e loop\n    if v_row ? 'id' and v_row ? 'code' then v_sku_code := v_sku_code || jsonb_build_object(v_row->>'id', v_row->>'code'); end if;\n  end loop;\n  for v_row in select e from jsonb_array_elements(coalesce(p_data->'order_items', '[]'::jsonb)) e loop\n    if not (v_order_num ? (v_row->>'order_id')) or coalesce(v_row->>'qty', '') !~ '^[0-9]{1,6}$' or coalesce(v_row->>'unit_price_jpy', '') !~ '^[0-9]{1,9}$' then continue; end if;\n    select id into v_order from orders where shop_id = p_shop_id and number = (v_order_num->>(v_row->>'order_id'))::integer;\n    if v_order is null then continue; end if;\n    if nullif(v_row->>'sku_id', '') is null then\n      -- 2 回目の呼び出しで重ねない\n      if exists (select 1 from order_items where order_id = v_order and sku_id is null and item_name is not distinct from left(v_row->>'item_name', 200) and qty = (v_row->>'qty')::integer) then continue; end if;\n      insert into order_items (shop_id, order_id, sku_id, qty, unit_price_jpy, discount_jpy, item_name, item_variant)\n      values (p_shop_id, v_order, null, (v_row->>'qty')::integer, (v_row->>'unit_price_jpy')::integer, greatest(0, coalesce((v_row->>'discount_jpy')::integer, 0)),\n              left(v_row->>'item_name', 200), left(v_row->>'item_variant', 200));\n      v_items := v_items + 1;\n    elsif (nullif(v_row->>'item_name', '') is not null or nullif(v_row->>'item_variant', '') is not null) and v_sku_code ? (v_row->>'sku_id') then\n      update order_items oi set item_name = left(v_row->>'item_name', 200), item_variant = left(v_row->>'item_variant', 200)\n        from skus k\n       where oi.order_id = v_order and k.shop_id = p_shop_id and k.code = v_sku_code->>(v_row->>'sku_id') and oi.sku_id = k.id\n         and oi.qty = (v_row->>'qty')::integer and oi.item_name is null;\n      get diagnostics v_n = row_count; v_items := v_items + v_n;\n    end if;\n  end loop;\n  return jsonb_build_object('history_orders', v_orders, 'history_items', v_items);\nend;\n$$;\n\nrevoke execute on function banto_email_subject(text) from public, anon, authenticated;\nrevoke execute on function import_orders(uuid, jsonb) from public, anon;\ngrant execute on function import_orders(uuid, jsonb) to authenticated, service_role;\nrevoke execute on function import_coupon_usage(uuid, text, text[], boolean) from public, anon;\ngrant execute on function import_coupon_usage(uuid, text, text[], boolean) to authenticated, service_role;\nrevoke execute on function coupon_grants_for_emails(uuid, uuid, text[]) from public, anon;\ngrant execute on function coupon_grants_for_emails(uuid, uuid, text[]) to authenticated, service_role;\nrevoke execute on function lookup_order(uuid, integer, text) from public;\ngrant execute on function lookup_order(uuid, integer, text) to anon, authenticated, service_role;\nrevoke execute on function member_order(uuid, uuid, integer, integer) from public, anon, authenticated;\ngrant execute on function member_order(uuid, uuid, integer, integer) to service_role;\nrevoke execute on function restore_history(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function restore_history(uuid, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0023_woo_history');\n" },
  { version: "0024_organizations", sql: "-- 0024_organizations: 組織・メンバー・役割・権限の項目（docs/knowledge/11-organizations.md、人間の決定 2026-10-17）\n--\n-- organizations       … 事業者（会社）。ショップと実店舗（0025）の持ち主\n-- org_members         … 運営側の人（Supabase Auth のユーザー）と組織の役割（owner / admin / member）\n-- org_member_shops    … member にショップごとの権限の項目を割り当てる（catalog / orders / orders_cancel / customers /\n--                        marketing / reports / stores / settings / integrations）\n-- org_invitations     … 招待（トークンは SHA-256 にして置く。7 日・1 回限り）\n-- shops.org_id        … ショップの持ち主の組織。owner_id は 1 マイナー残して後で消す（2 段階の規約）。新しいショップはトリガーで入れる\n--\n-- 判定は security definer の関数に集める:\n--   banto_org_admin(org_id)          … 組織の owner / admin か\n--   banto_owns_shop(shop_id)         … そのショップの全権（組織の owner / admin）。作り替え。既存のポリシーと関数はこれで owner / admin に今までどおり効く\n--   banto_shop_perm(shop_id, perm)   … 全権か、member でそのショップにその項目を持つか\n-- 項目ごとの権限は、既存のポリシーに「足す」形で入れる（permissive なポリシーは OR）。既存のポリシーは書き換えない。\n-- 権限を確かめている関数は、対応する項目で確かめるように差し替える（下の一覧）。差し替えていない関数は owner / admin だけが通る（安全側）。\n\ncreate table organizations (\n  id uuid primary key default gen_random_uuid(),\n  name text not null check (length(name) between 1 and 100),\n  created_at timestamptz not null default now()\n);\n\ncreate table org_members (\n  org_id uuid not null references organizations(id) on delete cascade,\n  user_id uuid not null references auth.users(id) on delete cascade,\n  role text not null check (role in ('owner', 'admin', 'member')),\n  created_at timestamptz not null default now(),\n  primary key (org_id, user_id)\n);\ncreate index on org_members(user_id);\n\n-- ショップの権限の項目（§3-1）\ncreate or replace function banto_shop_perms_all()\nreturns text[]\nlanguage sql\nimmutable\nas $$ select array['catalog', 'orders', 'orders_cancel', 'customers', 'marketing', 'reports', 'stores', 'settings', 'integrations'] $$;\n\ncreate table org_member_shops (\n  org_id uuid not null,\n  user_id uuid not null,\n  shop_id uuid not null references shops(id) on delete cascade,\n  perms text[] not null default '{}' check (perms <@ array['catalog', 'orders', 'orders_cancel', 'customers', 'marketing', 'reports', 'stores', 'settings', 'integrations']),\n  primary key (user_id, shop_id),\n  foreign key (org_id, user_id) references org_members(org_id, user_id) on delete cascade\n);\ncreate index on org_member_shops(shop_id);\n\ncreate table org_invitations (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references organizations(id) on delete cascade,\n  email text not null check (position('@' in email) > 1 and length(email) <= 254),\n  role text not null check (role in ('owner', 'admin', 'member')),\n  -- [{ shop_id, perms: [...] }]\n  shops jsonb not null default '[]'::jsonb check (jsonb_typeof(shops) = 'array'),\n  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),\n  expires_at timestamptz not null,\n  accepted_at timestamptz,\n  accepted_by uuid,\n  invited_by uuid,\n  created_at timestamptz not null default now()\n);\ncreate index on org_invitations(org_id);\n\nalter table shops add column if not exists org_id uuid references organizations(id);\ncreate index if not exists shops_org_id on shops(org_id);\n-- 招待で入った管理者は owners の行を持たない（owners は「最初の 1 人」の入口）。新しいショップの owner_id は空でよい\nalter table shops alter column owner_id drop not null;\n-- AI 用トークンを発行した人も同じ（発行した人の記録として残す。権限の判定はショップ単位）\nalter table api_tokens drop constraint if exists api_tokens_owner_id_fkey;\nalter table api_tokens add constraint api_tokens_owner_id_fkey foreign key (owner_id) references auth.users(id) on delete cascade;\n\n-- ---------- 判定の関数 ----------\ncreate or replace function banto_org_role(p_org_id uuid)\nreturns text language sql stable security definer set search_path = public as $$\n  select role from org_members where org_id = p_org_id and user_id = auth.uid();\n$$;\n\ncreate or replace function banto_org_admin(p_org_id uuid)\nreturns boolean language sql stable security definer set search_path = public as $$\n  select exists (select 1 from org_members where org_id = p_org_id and user_id = auth.uid() and role in ('owner', 'admin'));\n$$;\n\n-- そのショップの全権（組織の owner / admin）。組織に入る前のショップ（org_id が空）は今までどおり owner 本人\ncreate or replace function banto_owns_shop(p_shop_id uuid)\nreturns boolean language sql stable security definer set search_path = public as $$\n  select exists (\n    select 1 from shops s\n     where s.id = p_shop_id\n       and ((s.org_id is not null and exists (select 1 from org_members m where m.org_id = s.org_id and m.user_id = auth.uid() and m.role in ('owner', 'admin')))\n            or (s.org_id is null and s.owner_id = auth.uid())));\n$$;\n\ncreate or replace function banto_shop_perm(p_shop_id uuid, p_perm text)\nreturns boolean language sql stable security definer set search_path = public as $$\n  select banto_owns_shop(p_shop_id) or exists (\n    select 1 from org_member_shops ms join shops s on s.id = ms.shop_id\n     where ms.shop_id = p_shop_id and ms.user_id = auth.uid() and ms.org_id = s.org_id and p_perm = any(ms.perms));\n$$;\n\n-- 管理画面がショップを開くときの 1 回の往復: ショップの行と自分の役割・項目（触れないショップなら null）\ncreate or replace function banto_admin_shop(p_shop_id uuid)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select case\n    when banto_owns_shop(s.id) then jsonb_build_object('shop', to_jsonb(s), 'role', coalesce(banto_org_role(s.org_id), 'owner'), 'perms', to_jsonb(banto_shop_perms_all()))\n    when ms.perms is not null and cardinality(ms.perms) > 0 then jsonb_build_object('shop', to_jsonb(s), 'role', 'member', 'perms', to_jsonb(ms.perms))\n    end\n    from shops s\n    left join org_member_shops ms on ms.shop_id = s.id and ms.user_id = auth.uid() and ms.org_id = s.org_id\n   where s.id = p_shop_id;\n$$;\n\n-- 自分が触れるショップ（ダッシュボード）\ncreate or replace function banto_my_shops()\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'slug', s.slug, 'name', s.name, 'published', s.published, 'org_id', s.org_id,\n                                               'perms', case when banto_owns_shop(s.id) then to_jsonb(banto_shop_perms_all()) else to_jsonb(ms.perms) end)\n                            order by s.created_at), '[]'::jsonb)\n    from shops s\n    left join org_member_shops ms on ms.shop_id = s.id and ms.user_id = auth.uid() and ms.org_id = s.org_id\n   where banto_owns_shop(s.id) or (ms.perms is not null and cardinality(ms.perms) > 0);\n$$;\n\n-- ---------- 最初の 1 人 = 最初の組織の owner ----------\n-- owners の行（自己登録の入口、0001）ができたら、その人の組織を作る（まだどの組織にも入っていなければ）\ncreate or replace function banto_owner_org()\nreturns trigger language plpgsql security definer set search_path = public as $$\ndeclare v_org uuid;\nbegin\n  if exists (select 1 from org_members where user_id = new.id) then return new; end if;\n  insert into organizations (name) values ('マイ組織') returning id into v_org;\n  insert into org_members (org_id, user_id, role) values (v_org, new.id, 'owner');\n  return new;\nend;\n$$;\ndrop trigger if exists owners_org on owners;\ncreate trigger owners_org after insert on owners for each row execute function banto_owner_org();\n\n-- 新しいショップ: 組織は「自分が owner / admin の組織」（いちばん古いもの）。持ち主を後から変えさせない。\n-- Stripe の接続先（入金先）は integrations の項目を持つ人だけが変えられる\ncreate or replace function banto_shops_guard()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if tg_op = 'INSERT' then\n    if new.org_id is null and auth.uid() is not null then\n      select m.org_id into new.org_id from org_members m join organizations o on o.id = m.org_id\n       where m.user_id = auth.uid() and m.role in ('owner', 'admin') order by o.created_at limit 1;\n    end if;\n    if new.owner_id is not null and not exists (select 1 from owners where id = new.owner_id) then new.owner_id := null; end if;\n    return new;\n  end if;\n  if auth.role() = 'authenticated' then\n    if new.org_id is distinct from old.org_id and old.org_id is not null then raise exception 'org_immutable' using errcode = '42501'; end if;\n    if new.owner_id is distinct from old.owner_id then raise exception 'owner_immutable' using errcode = '42501'; end if;\n    if new.stripe_account_id is distinct from old.stripe_account_id and not banto_shop_perm(old.id, 'integrations') then\n      raise exception 'integrations_required' using errcode = '42501';\n    end if;\n  end if;\n  return new;\nend;\n$$;\ndrop trigger if exists shops_guard on shops;\ncreate trigger shops_guard before insert or update on shops for each row execute function banto_shops_guard();\n\n-- 既存のデータ: owner ごとに組織を 1 つ作り、その owner を owner にして、ショップに組織を入れる\ndo $$\ndeclare v_owner record; v_org uuid;\nbegin\n  for v_owner in select o.id, (select name from shops s where s.owner_id = o.id order by created_at limit 1) as shop_name\n                   from owners o where not exists (select 1 from org_members m where m.user_id = o.id) loop\n    insert into organizations (name) values (left(coalesce(v_owner.shop_name, 'マイ組織'), 100)) returning id into v_org;\n    insert into org_members (org_id, user_id, role) values (v_org, v_owner.id, 'owner');\n  end loop;\n  update shops s set org_id = (select m.org_id from org_members m where m.user_id = s.owner_id and m.role = 'owner' limit 1)\n   where s.org_id is null and s.owner_id is not null;\nend;\n$$;\n\n-- ---------- RLS ----------\nalter table organizations enable row level security;\nalter table org_members enable row level security;\nalter table org_member_shops enable row level security;\nalter table org_invitations enable row level security;\n\ncreate policy organizations_member_select on organizations for select using (banto_org_role(id) is not null);\ncreate policy organizations_admin_update on organizations for update using (banto_org_admin(id)) with check (banto_org_admin(id));\n-- メンバーと割り当ては、自分の分と、組織の owner / admin が読める。書くのは下の関数だけ\ncreate policy org_members_select on org_members for select using (user_id = auth.uid() or banto_org_admin(org_id));\ncreate policy org_member_shops_select on org_member_shops for select using (user_id = auth.uid() or banto_org_admin(org_id));\ncreate policy org_invitations_admin_select on org_invitations for select using (banto_org_admin(org_id));\n\n-- shops: 全権は組織の owner / admin（作成・削除も）。member は割り当てたショップを読め、settings の項目があれば更新できる\ndrop policy if exists shops_owner on shops;\n-- 行の列で判定する（banto_owns_shop は表を引き直すので、INSERT ... RETURNING の新しい行が見えない）\ncreate policy shops_admin on shops for all\n  using (case when org_id is null then owner_id = auth.uid() else banto_org_admin(org_id) end)\n  with check (case when org_id is null then owner_id = auth.uid() else banto_org_admin(org_id) end);\ncreate policy shops_member_select on shops for select\n  using (exists (select 1 from org_member_shops ms where ms.shop_id = shops.id and ms.user_id = auth.uid() and ms.org_id = shops.org_id and cardinality(ms.perms) > 0));\ncreate policy shops_member_update on shops for update using (banto_shop_perm(id, 'settings')) with check (banto_shop_perm(id, 'settings'));\n\n-- 項目ごとの権限（既存の owner のポリシーに足す）\ncreate policy products_catalog on products for all using (banto_shop_perm(shop_id, 'catalog')) with check (banto_shop_perm(shop_id, 'catalog'));\ncreate policy skus_catalog on skus for all using (banto_shop_perm(shop_id, 'catalog')) with check (banto_shop_perm(shop_id, 'catalog'));\ncreate policy images_catalog on product_images for all using (banto_shop_perm(shop_id, 'catalog')) with check (banto_shop_perm(shop_id, 'catalog'));\ncreate policy categories_catalog on categories for all using (banto_shop_perm(shop_id, 'catalog')) with check (banto_shop_perm(shop_id, 'catalog'));\ncreate policy inventory_catalog on inventory for select using (banto_shop_perm(shop_id, 'catalog'));\ncreate policy orders_perm_select on orders for select using (banto_shop_perm(shop_id, 'orders'));\ncreate policy orders_perm_update on orders for update using (banto_shop_perm(shop_id, 'orders')) with check (banto_shop_perm(shop_id, 'orders'));\ncreate policy order_items_perm on order_items for select using (banto_shop_perm(shop_id, 'orders'));\ncreate policy reservations_perm on reservations for select using (banto_shop_perm(shop_id, 'orders'));\ncreate policy customers_perm_select on customers for select using (banto_shop_perm(shop_id, 'customers'));\ncreate policy customers_perm_delete on customers for delete using (banto_shop_perm(shop_id, 'customers'));\ncreate policy coupon_campaigns_marketing on coupon_campaigns for all using (banto_shop_perm(shop_id, 'marketing')) with check (banto_shop_perm(shop_id, 'marketing'));\ncreate policy coupon_slots_marketing on coupon_slots for select using (banto_shop_perm(shop_id, 'marketing'));\ncreate policy coupon_redemptions_marketing on coupon_redemptions for select using (banto_shop_perm(shop_id, 'marketing'));\ncreate policy coupon_grants_marketing on coupon_grants for select using (banto_shop_perm(shop_id, 'marketing'));\ncreate policy hook_endpoints_integrations on hook_endpoints for all using (banto_shop_perm(shop_id, 'integrations')) with check (banto_shop_perm(shop_id, 'integrations'));\ncreate policy hook_deliveries_integrations on hook_deliveries for select using (banto_shop_perm(shop_id, 'integrations'));\ndrop policy if exists api_tokens_owner on api_tokens;\ncreate policy api_tokens_integrations on api_tokens for all\n  using (banto_shop_perm(shop_id, 'integrations')) with check (banto_shop_perm(shop_id, 'integrations') and owner_id = auth.uid());\ncreate policy shop_oauth_clients_integrations on shop_oauth_clients for select using (banto_shop_perm(shop_id, 'integrations'));\ncreate policy shop_secret_boxes_integrations on shop_secret_boxes for select using (banto_shop_perm(shop_id, 'integrations'));\n-- アップデート・稼働の画面は組織の owner / admin にも\ncreate policy migrations_org_admin_select on banto_migrations for select\n  using (exists (select 1 from org_members m where m.user_id = auth.uid() and m.role in ('owner', 'admin')));\ncreate policy heartbeats_org_admin_select on banto_heartbeats for select\n  using (exists (select 1 from org_members m where m.user_id = auth.uid() and m.role in ('owner', 'admin')));\n\n-- ---------- メンバーの管理（組織の owner / admin） ----------\n-- 規則: owner を作る・外す・owner の役割を変えるのは owner だけ。最後の owner は外せない・降格できない\ncreate or replace function banto_org_guard(p_org_id uuid, p_target_role text, p_current_role text)\nreturns void language plpgsql stable security definer set search_path = public as $$\ndeclare v_me text := banto_org_role(p_org_id);\nbegin\n  if v_me is null or v_me not in ('owner', 'admin') then raise exception 'org_not_found' using errcode = '42501'; end if;\n  if v_me <> 'owner' and ('owner' in (coalesce(p_target_role, ''), coalesce(p_current_role, ''))) then raise exception 'owner_only' using errcode = '42501'; end if;\nend;\n$$;\n\n-- p_shops: [{ shop_id, perms: [...] }]（member のとき）。その組織のショップの、決まった項目だけ入れる\ncreate or replace function banto_set_member_shops(p_org_id uuid, p_user_id uuid, p_shops jsonb)\nreturns void language plpgsql security definer set search_path = public as $$\ndeclare v_row jsonb;\nbegin\n  delete from org_member_shops where org_id = p_org_id and user_id = p_user_id;\n  for v_row in select e from jsonb_array_elements(coalesce(p_shops, '[]'::jsonb)) e loop\n    if exists (select 1 from shops where id = nullif(v_row->>'shop_id', '')::uuid and org_id = p_org_id) then\n      insert into org_member_shops (org_id, user_id, shop_id, perms)\n      values (p_org_id, p_user_id, (v_row->>'shop_id')::uuid,\n              coalesce((select array_agg(distinct p) from jsonb_array_elements_text(coalesce(v_row->'perms', '[]'::jsonb)) p where p = any(banto_shop_perms_all())), '{}'))\n      on conflict (user_id, shop_id) do update set perms = excluded.perms;\n    end if;\n  end loop;\nend;\n$$;\n\ncreate or replace function org_member_set(p_org_id uuid, p_user_id uuid, p_role text, p_shops jsonb)\nreturns void language plpgsql security definer set search_path = public as $$\ndeclare v_current text;\nbegin\n  if p_role not in ('owner', 'admin', 'member') then raise exception 'invalid_role'; end if;\n  select role into v_current from org_members where org_id = p_org_id and user_id = p_user_id for update;\n  if not found then raise exception 'member_not_found'; end if;\n  perform banto_org_guard(p_org_id, p_role, v_current);\n  if v_current = 'owner' and p_role <> 'owner' and (select count(*) from org_members where org_id = p_org_id and role = 'owner') <= 1 then\n    raise exception 'last_owner';\n  end if;\n  update org_members set role = p_role where org_id = p_org_id and user_id = p_user_id;\n  perform banto_set_member_shops(p_org_id, p_user_id, case when p_role = 'member' then p_shops else '[]'::jsonb end);\nend;\n$$;\n\ncreate or replace function org_member_remove(p_org_id uuid, p_user_id uuid)\nreturns void language plpgsql security definer set search_path = public as $$\ndeclare v_current text;\nbegin\n  select role into v_current from org_members where org_id = p_org_id and user_id = p_user_id for update;\n  if not found then raise exception 'member_not_found'; end if;\n  perform banto_org_guard(p_org_id, null, v_current);\n  if v_current = 'owner' and (select count(*) from org_members where org_id = p_org_id and role = 'owner') <= 1 then raise exception 'last_owner'; end if;\n  delete from org_members where org_id = p_org_id and user_id = p_user_id;\nend;\n$$;\n\n-- メンバーの一覧（メールアドレスは auth.users から。組織の owner / admin だけ）\ncreate or replace function org_members_list(p_org_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  if not banto_org_admin(p_org_id) then raise exception 'org_not_found' using errcode = '42501'; end if;\n  return (select coalesce(jsonb_agg(jsonb_build_object('user_id', m.user_id, 'email', u.email, 'role', m.role, 'created_at', m.created_at,\n                                                       'shops', (select coalesce(jsonb_agg(jsonb_build_object('shop_id', ms.shop_id, 'perms', to_jsonb(ms.perms))), '[]'::jsonb)\n                                                                   from org_member_shops ms where ms.org_id = m.org_id and ms.user_id = m.user_id))\n                                    order by m.created_at), '[]'::jsonb)\n            from org_members m join auth.users u on u.id = m.user_id where m.org_id = p_org_id);\nend;\n$$;\n\n-- ---------- 招待 ----------\n-- 同じ組織・同じメールアドレスの受け入れ前の招待は置き換える。\n-- 戻り値: { id, mail_from }。mail_from は組織のショップのメール通知プラグインの送信元（無ければ null → 画面にリンクを出す）\ncreate or replace function org_invite(p_org_id uuid, p_email text, p_role text, p_shops jsonb, p_token_hash text)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_id uuid; v_from text;\nbegin\n  if length(btrim(coalesce(p_email, ''))) > 254 or btrim(coalesce(p_email, '')) !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  if p_role not in ('owner', 'admin', 'member') then raise exception 'invalid_role'; end if;\n  perform banto_org_guard(p_org_id, p_role, null);\n  if exists (select 1 from org_members m join auth.users u on u.id = m.user_id where m.org_id = p_org_id and lower(u.email) = lower(btrim(p_email))) then\n    raise exception 'already_member';\n  end if;\n  delete from org_invitations where org_id = p_org_id and lower(email) = lower(btrim(p_email)) and accepted_at is null;\n  insert into org_invitations (org_id, email, role, shops, token_hash, expires_at, invited_by)\n  values (p_org_id, lower(btrim(p_email)), p_role, case when p_role = 'member' then coalesce(p_shops, '[]'::jsonb) else '[]'::jsonb end,\n          p_token_hash, now() + interval '7 days', auth.uid())\n  returning id into v_id;\n  select nullif(btrim(e.settings->>'from'), '') into v_from\n    from hook_endpoints e join shops s on s.id = e.shop_id\n   where s.org_id = p_org_id and e.enabled and e.url = 'https://banto.invalid/plugins/email_resend' and nullif(btrim(e.settings->>'from'), '') is not null\n   order by s.created_at limit 1;\n  return jsonb_build_object('id', v_id, 'mail_from', v_from);\nend;\n$$;\n\ncreate or replace function org_invitation_revoke(p_org_id uuid, p_invitation_id uuid)\nreturns void language plpgsql security definer set search_path = public as $$\nbegin\n  perform banto_org_guard(p_org_id, (select role from org_invitations where id = p_invitation_id and org_id = p_org_id), null);\n  delete from org_invitations where id = p_invitation_id and org_id = p_org_id and accepted_at is null;\nend;\n$$;\n\n-- 招待のリンクを開いたときの確認（service_role。メールアドレス・組織の名前・有効か）\ncreate or replace function org_invitation_peek(p_token_hash text)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  if auth.role() is distinct from 'service_role' then raise exception 'org_invitation_peek: service_role only' using errcode = '42501'; end if;\n  return (select jsonb_build_object('email', i.email, 'org_name', o.name, 'role', i.role,\n                                    'valid', i.accepted_at is null and i.expires_at > now(),\n                                    'user_exists', exists (select 1 from auth.users u where lower(u.email) = i.email))\n            from org_invitations i join organizations o on o.id = i.org_id where i.token_hash = p_token_hash);\nend;\n$$;\n\n-- 受け入れ（招待された本人。JWT のメールアドレスが招待と同じであること）\ncreate or replace function org_invitation_accept(p_token_hash text)\nreturns uuid language plpgsql security definer set search_path = public as $$\ndeclare v_i org_invitations%rowtype; v_email text := lower(coalesce(auth.jwt()->>'email', ''));\nbegin\n  if auth.uid() is null then raise exception 'login_required' using errcode = '42501'; end if;\n  select * into v_i from org_invitations where token_hash = p_token_hash for update;\n  if not found or v_i.accepted_at is not null or v_i.expires_at <= now() then raise exception 'invitation_invalid'; end if;\n  if v_i.email <> v_email then raise exception 'invitation_email_mismatch'; end if;\n  insert into org_members (org_id, user_id, role) values (v_i.org_id, auth.uid(), v_i.role)\n  on conflict (org_id, user_id) do nothing;\n  if v_i.role = 'member' then perform banto_set_member_shops(v_i.org_id, auth.uid(), v_i.shops); end if;\n  update org_invitations set accepted_at = now(), accepted_by = auth.uid() where id = v_i.id;\n  return v_i.org_id;\nend;\n$$;\n\n-- ---------- 権限を確かめている関数を項目で確かめる（中身は元のまま、判定だけ差し替え） ----------\n-- enqueue_hook（0002 を差し替え）: 管理画面から送るのは order.shipped（orders）と product.updated（catalog）\ncreate or replace function enqueue_hook(p_shop_id uuid, p_event text, p_payload jsonb)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_count integer;\nbegin\n  if auth.role() is distinct from 'service_role' and not (banto_shop_perm(p_shop_id, 'orders') or banto_shop_perm(p_shop_id, 'catalog')) then\n    raise exception 'shop_not_found' using errcode = '42501';\n  end if;\n  if p_event is null or p_event !~ '^[a-z_]+\\.[a-z_]+$' then\n    raise exception 'invalid_event';\n  end if;\n  insert into hook_deliveries (shop_id, endpoint_id, event, payload)\n  select e.shop_id, e.id, p_event, coalesce(p_payload, '{}'::jsonb)\n    from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and p_event = any(e.events);\n  get diagnostics v_count = row_count;\n  return v_count;\nend;\n$$;\n\n-- coupon_grant_revoke（0019_coupon_grants.sql を差し替え: marketing）\ncreate or replace function coupon_grant_revoke(p_shop_id uuid, p_grant_id uuid)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_shop_perm(p_shop_id, 'marketing') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  update coupon_grants set status = 'revoked' where id = p_grant_id and shop_id = p_shop_id and status = 'available';\n  return found;\nend;\n$$;\n\n-- coupon_grants_for_emails（0023_woo_history.sql を差し替え: marketing）\ncreate or replace function coupon_grants_for_emails(p_shop_id uuid, p_campaign_id uuid, p_emails text[])\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_c coupon_campaigns%rowtype; v_email text; v_cid uuid; v_code text; v_expires timestamptz;\n  v_out jsonb := '[]'::jsonb;\nbegin\n  if not banto_shop_perm(p_shop_id, 'marketing') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if coalesce(array_length(p_emails, 1), 0) > 5000 then raise exception 'too_many'; end if;\n  select * into v_c from coupon_campaigns where id = p_campaign_id and shop_id = p_shop_id;\n  if not found then raise exception 'campaign_not_found'; end if;\n  v_expires := case when v_c.grant_valid_days is not null then now() + make_interval(days => v_c.grant_valid_days) end;\n  if v_c.ends_at is not null and (v_expires is null or v_expires > v_c.ends_at) then v_expires := v_c.ends_at; end if;\n  for v_email in select distinct lower(btrim(e)) from unnest(coalesce(p_emails, '{}'::text[])) e where position('@' in coalesce(e, '')) > 0 and position('*' in e) = 0 order by 1 loop\n    select id into v_cid from customers where shop_id = p_shop_id and lower(email) = v_email limit 1;\n    v_code := null;\n    if v_cid is not null then\n      select code into v_code from coupon_grants where campaign_id = v_c.id and customer_id = v_cid and status in ('available', 'held') limit 1;\n    end if;\n    if v_code is null then\n      loop\n        v_code := banto_grant_code();\n        begin\n          insert into coupon_grants (shop_id, campaign_id, code, customer_id, expires_at) values (p_shop_id, v_c.id, v_code, v_cid, v_expires);\n          exit;\n        exception when unique_violation then null;\n        end;\n      end loop;\n    end if;\n    v_out := v_out || jsonb_build_object('email', v_email, 'code', v_code, 'member', v_cid is not null);\n  end loop;\n  return v_out;\nend;\n$$;\n\n-- coupon_grants_issue（0019_coupon_grants.sql を差し替え: marketing）\ncreate or replace function coupon_grants_issue(p_shop_id uuid, p_campaign_id uuid, p_customer_ids uuid[], p_count integer)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_c coupon_campaigns%rowtype;\n  v_expires timestamptz;\n  v_n integer := 0;\n  v_cid uuid;\n  v_i integer;\n  v_code text;\nbegin\n  if not banto_shop_perm(p_shop_id, 'marketing') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  select * into v_c from coupon_campaigns where id = p_campaign_id and shop_id = p_shop_id;\n  if not found then raise exception 'campaign_not_found'; end if;\n  if coalesce(p_count, 0) < 0 or coalesce(p_count, 0) > 5000 or coalesce(array_length(p_customer_ids, 1), 0) > 5000 then raise exception 'too_many'; end if;\n  v_expires := case when v_c.grant_valid_days is not null then now() + make_interval(days => v_c.grant_valid_days) end;\n  if v_c.ends_at is not null and (v_expires is null or v_expires > v_c.ends_at) then v_expires := v_c.ends_at; end if;\n  foreach v_cid in array coalesce(p_customer_ids, '{}'::uuid[]) loop\n    if not exists (select 1 from customers where shop_id = p_shop_id and id = v_cid) then continue; end if;\n    if exists (select 1 from coupon_grants where campaign_id = v_c.id and customer_id = v_cid and status in ('available', 'held')) then continue; end if;\n    loop\n      v_code := banto_grant_code();\n      begin\n        insert into coupon_grants (shop_id, campaign_id, code, customer_id, expires_at) values (p_shop_id, v_c.id, v_code, v_cid, v_expires);\n        exit;\n      exception when unique_violation then null; -- まれにコードが重なったら作り直す\n      end;\n    end loop;\n    v_n := v_n + 1;\n  end loop;\n  for v_i in 1 .. coalesce(p_count, 0) loop\n    loop\n      v_code := banto_grant_code();\n      begin\n        insert into coupon_grants (shop_id, campaign_id, code, expires_at) values (p_shop_id, v_c.id, v_code, v_expires);\n        exit;\n      exception when unique_violation then null;\n      end;\n    end loop;\n    v_n := v_n + 1;\n  end loop;\n  return jsonb_build_object('issued', v_n);\nend;\n$$;\n\n-- coupon_stats（0010_coupons.sql を差し替え: marketing）\ncreate or replace function coupon_stats(p_shop_id uuid)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when banto_shop_perm(p_shop_id, 'marketing') then coalesce((\n    select jsonb_object_agg(campaign_id, jsonb_build_object('used', used, 'held', held))\n      from (select campaign_id, count(*) filter (where status = 'used') as used, count(*) filter (where status = 'held') as held\n              from coupon_redemptions where shop_id = p_shop_id group by campaign_id) x), '{}'::jsonb) end;\n$$;\n\n-- import_catalog（0009_catalog_import.sql を差し替え: catalog）\ncreate or replace function import_catalog(p_shop_id uuid, p_batch jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_sku jsonb; v_cat_id uuid; v_parent uuid; v_pid uuid; v_kid uuid; v_existing uuid; v_avail integer;\n  v_price integer; v_compare integer; v_gtin text; v_created boolean;\n  v_n_cat integer := 0; v_p_new integer := 0; v_p_upd integer := 0; v_k_new integer := 0; v_k_upd integer := 0;\n  l_p_new integer; l_k_new integer; l_k_upd integer;\n  v_errors jsonb := '[]'::jsonb;\n  v_overwrite boolean := coalesce((p_batch->>'overwrite_stock')::boolean, true);\nbegin\n  if not banto_shop_perm(p_shop_id, 'catalog') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n\n  -- カテゴリー（親が先）\n  for v_row in select * from jsonb_array_elements(coalesce(p_batch->'categories', '[]'::jsonb)) loop\n    v_parent := null;\n    if coalesce(v_row->>'parent_slug', '') <> '' then\n      select id into v_parent from categories where shop_id = p_shop_id and slug = v_row->>'parent_slug';\n    end if;\n    insert into categories (shop_id, slug, name, parent_id, sort_order)\n    values (p_shop_id, v_row->>'slug', left(btrim(v_row->>'name'), 100), v_parent, coalesce((v_row->>'sort_order')::integer, 0))\n    on conflict (shop_id, slug) do update set name = excluded.name, parent_id = excluded.parent_id;\n    v_n_cat := v_n_cat + 1;\n  end loop;\n\n  -- 商品と SKU\n  for v_row in select * from jsonb_array_elements(coalesce(p_batch->'products', '[]'::jsonb)) loop\n    begin\n      l_p_new := 0; l_k_new := 0; l_k_upd := 0;\n      v_cat_id := null;\n      if coalesce(v_row->>'category_slug', '') <> '' then\n        select id into v_cat_id from categories where shop_id = p_shop_id and slug = v_row->>'category_slug';\n      end if;\n      select id into v_pid from products where shop_id = p_shop_id and slug = v_row->>'slug';\n      if v_pid is null then\n        insert into products (shop_id, slug, name, description, published, tags, brand, attributes, category_id)\n        values (p_shop_id, v_row->>'slug', left(btrim(v_row->>'name'), 200), nullif(btrim(coalesce(v_row->>'description', '')), ''),\n                coalesce((v_row->>'published')::boolean, false), banto_normalize_tags(v_row->'tags'),\n                nullif(left(btrim(coalesce(v_row->>'brand', '')), 100), ''), banto_clean_object(v_row->'attributes', 200), v_cat_id)\n        returning id into v_pid;\n        l_p_new := 1;\n      else\n        -- カスタム項目は既存の値に上書きでマージする（取り込み元に無い項目を消さない）\n        update products set\n          name = left(btrim(v_row->>'name'), 200),\n          description = nullif(btrim(coalesce(v_row->>'description', '')), ''),\n          published = coalesce((v_row->>'published')::boolean, published),\n          tags = banto_normalize_tags(v_row->'tags'),\n          brand = nullif(left(btrim(coalesce(v_row->>'brand', '')), 100), ''),\n          attributes = attributes || banto_clean_object(v_row->'attributes', 200),\n          category_id = v_cat_id\n        where id = v_pid;\n      end if;\n\n      for v_sku in select * from jsonb_array_elements(coalesce(v_row->'skus', '[]'::jsonb)) loop\n        v_price := (v_sku->>'price_jpy')::integer;\n        v_compare := (v_sku->>'compare_at_price_jpy')::integer;\n        if v_compare is not null and v_compare <= v_price then v_compare := null; end if;\n        v_gtin := nullif(btrim(coalesce(v_sku->>'gtin', '')), '');\n        if v_gtin is not null and v_gtin !~ '^([0-9]{8}|[0-9]{12,14})$' then v_gtin := null; end if;\n        select id, product_id into v_kid, v_existing from skus where shop_id = p_shop_id and code = v_sku->>'code';\n        v_created := v_kid is null;\n        if v_created then\n          insert into skus (shop_id, product_id, code, name, price_jpy, compare_at_price_jpy, gtin, options)\n          values (p_shop_id, v_pid, v_sku->>'code', nullif(left(btrim(coalesce(v_sku->>'name', '')), 200), ''), v_price, v_compare, v_gtin,\n                  banto_clean_object(v_sku->'options', 5))\n          returning id into v_kid;\n          l_k_new := l_k_new + 1;\n        else\n          if v_existing <> v_pid then raise exception 'sku_belongs_to_other_product: %', v_sku->>'code'; end if;\n          update skus set name = nullif(left(btrim(coalesce(v_sku->>'name', '')), 200), ''), price_jpy = v_price, compare_at_price_jpy = v_compare,\n                          gtin = v_gtin, options = banto_clean_object(v_sku->'options', 5)\n           where id = v_kid;\n          l_k_upd := l_k_upd + 1;\n        end if;\n        -- 在庫（inventory 行は skus の insert でトリガーが作る）\n        if v_sku ? 'available' and (v_created or v_overwrite) then\n          v_avail := greatest(0, coalesce((v_sku->>'available')::integer, 0));\n          update inventory set available = v_avail, updated_at = now() where sku_id = v_kid;\n        end if;\n      end loop;\n\n      perform enqueue_hook(p_shop_id, 'product.updated', jsonb_build_object('product_id', v_pid, 'shop_id', p_shop_id, 'slug', v_row->>'slug'));\n      -- 件数はこの商品が最後まで通ったときだけ数える（例外なら全部取り消されるため）\n      v_p_new := v_p_new + l_p_new; v_p_upd := v_p_upd + (1 - l_p_new); v_k_new := v_k_new + l_k_new; v_k_upd := v_k_upd + l_k_upd;\n    exception when others then\n      -- この商品だけ取り消して続ける（plpgsql の例外ブロックはセーブポイントとして働く）\n      v_errors := v_errors || jsonb_build_object('slug', v_row->>'slug', 'message', sqlerrm);\n    end;\n  end loop;\n\n  return jsonb_build_object('categories', v_n_cat, 'products_created', v_p_new, 'products_updated', v_p_upd,\n                            'skus_created', v_k_new, 'skus_updated', v_k_upd, 'errors', v_errors);\nend;\n$$;\n\n-- import_coupon_usage（0023_woo_history.sql を差し替え: marketing）\ncreate or replace function import_coupon_usage(p_shop_id uuid, p_code text, p_emails text[], p_reset boolean)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_campaign uuid; v_email text; v_cid uuid; v_n integer := 0;\nbegin\n  if not banto_shop_perm(p_shop_id, 'marketing') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if coalesce(array_length(p_emails, 1), 0) > 5000 then raise exception 'too_many'; end if;\n  select id into v_campaign from coupon_campaigns where shop_id = p_shop_id and code = upper(btrim(p_code));\n  if v_campaign is null then return jsonb_build_object('found', false, 'uses', 0); end if;\n  if p_reset then delete from coupon_redemptions where campaign_id = v_campaign and reservation_id is null; end if;\n  foreach v_email in array coalesce(p_emails, '{}'::text[]) loop\n    if position('@' in coalesce(v_email, '')) = 0 then continue; end if;\n    insert into coupon_redemptions (shop_id, campaign_id, reservation_id, subject, status) values (p_shop_id, v_campaign, null, banto_email_subject(v_email), 'used');\n    select id into v_cid from customers where shop_id = p_shop_id and lower(email) = lower(btrim(v_email)) limit 1;\n    if v_cid is not null then\n      insert into coupon_redemptions (shop_id, campaign_id, reservation_id, subject, status) values (p_shop_id, v_campaign, null, 'c:' || v_cid::text, 'used');\n    end if;\n    v_n := v_n + 1;\n  end loop;\n  return jsonb_build_object('found', true, 'uses', v_n);\nend;\n$$;\n\n-- import_orders（0023_woo_history.sql を差し替え: orders）\ncreate or replace function import_orders(p_shop_id uuid, p_orders jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_it jsonb; v_id uuid; v_num integer; v_ref text; v_status text; v_cid uuid; v_sku uuid; v_rate numeric;\n  v_created integer := 0; v_existing integer := 0; v_items integer := 0; v_no_sku integer := 0; v_invalid integer := 0;\n  v_conflicts jsonb := '[]'::jsonb;\n  v_max integer;\nbegin\n  if not banto_shop_perm(p_shop_id, 'orders') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if jsonb_typeof(p_orders) <> 'array' or jsonb_array_length(p_orders) > 100 then raise exception 'invalid_orders'; end if;\n  for v_row in select e from jsonb_array_elements(p_orders) e loop\n    v_ref := left(btrim(coalesce(v_row->>'ref', '')), 100);\n    v_status := v_row->>'status';\n    if v_ref = '' or coalesce(v_row->>'number', '') !~ '^[0-9]{1,9}$' or v_status is null or v_status not in ('paid', 'shipped', 'cancelled', 'refunded')\n       or coalesce(v_row->>'total_jpy', '') !~ '^[0-9]{1,9}$' or jsonb_typeof(v_row->'items') <> 'array' then\n      v_invalid := v_invalid + 1;\n      continue;\n    end if;\n    if exists (select 1 from orders where shop_id = p_shop_id and external_ref = v_ref) then\n      v_existing := v_existing + 1;\n      continue;\n    end if;\n    v_num := (v_row->>'number')::integer;\n    if exists (select 1 from orders where shop_id = p_shop_id and number = v_num) then\n      if jsonb_array_length(v_conflicts) < 50 then v_conflicts := v_conflicts || to_jsonb(v_num); end if;\n      continue;\n    end if;\n    v_cid := null;\n    if nullif(btrim(coalesce(v_row->>'customer_email', '')), '') is not null then\n      select id into v_cid from customers where shop_id = p_shop_id and lower(email) = lower(btrim(v_row->>'customer_email')) limit 1;\n    end if;\n    v_rate := case when coalesce(v_row->>'shipping_tax_rate', '') ~ '^[0-9]{1,2}(\\.[0-9]{1,2})?$' then (v_row->>'shipping_tax_rate')::numeric end;\n    insert into orders (shop_id, reservation_id, status, total_jpy, shipping_jpy, discount_jpy, amount_paid_jpy, number, customer_id,\n                        customer_email, customer_name, shipping_address, payment_provider, payment_ref, shipped_at, shipping_tax_rate,\n                        external_ref, created_at, updated_at)\n    values (p_shop_id, null, v_status::order_status, (v_row->>'total_jpy')::integer, greatest(0, coalesce((v_row->>'shipping_jpy')::integer, 0)),\n            greatest(0, coalesce((v_row->>'discount_jpy')::integer, 0)), (v_row->>'total_jpy')::integer, v_num, v_cid,\n            nullif(lower(btrim(coalesce(v_row->>'customer_email', ''))), ''), left(nullif(btrim(coalesce(v_row->>'customer_name', '')), ''), 200),\n            case when jsonb_typeof(v_row->'shipping_address') = 'object' then v_row->'shipping_address' end,\n            'woocommerce', left(nullif(v_row->>'payment_ref', ''), 200),\n            case when v_status = 'shipped' then coalesce((v_row->>'shipped_at')::timestamptz, (v_row->>'created_at')::timestamptz, now()) end,\n            v_rate, v_ref, coalesce((v_row->>'created_at')::timestamptz, now()), coalesce((v_row->>'created_at')::timestamptz, now()))\n    returning id into v_id;\n    v_created := v_created + 1;\n    for v_it in select e from jsonb_array_elements(v_row->'items') e loop\n      if coalesce(v_it->>'qty', '') !~ '^[0-9]{1,6}$' or (v_it->>'qty')::integer <= 0 or coalesce(v_it->>'unit_price_jpy', '') !~ '^[0-9]{1,9}$' then continue; end if;\n      v_sku := null;\n      if nullif(btrim(coalesce(v_it->>'sku', '')), '') is not null then\n        select id into v_sku from skus where shop_id = p_shop_id and code = btrim(v_it->>'sku');\n      end if;\n      if v_sku is null then v_no_sku := v_no_sku + 1; end if;\n      insert into order_items (shop_id, order_id, sku_id, qty, unit_price_jpy, discount_jpy, tax_rate, item_name, item_variant)\n      values (p_shop_id, v_id, v_sku, (v_it->>'qty')::integer, (v_it->>'unit_price_jpy')::integer, greatest(0, coalesce((v_it->>'discount_jpy')::integer, 0)),\n              case when coalesce(v_it->>'tax_rate', '') ~ '^[0-9]{1,2}(\\.[0-9]{1,2})?$' then (v_it->>'tax_rate')::numeric end,\n              left(nullif(btrim(coalesce(v_it->>'name', '')), ''), 200), left(nullif(btrim(coalesce(v_it->>'variant', '')), ''), 200));\n      v_items := v_items + 1;\n    end loop;\n  end loop;\n  -- 新しい注文の番号は、取り込んだ番号の続きから\n  select max(number) into v_max from orders where shop_id = p_shop_id;\n  if v_max is not null then update shops set order_seq = greatest(order_seq, v_max) where id = p_shop_id; end if;\n  return jsonb_build_object('created', v_created, 'existing', v_existing, 'invalid', v_invalid, 'items', v_items, 'items_without_sku', v_no_sku, 'conflicts', v_conflicts);\nend;\n$$;\n\n-- import_tax_classes（0022_tracking.sql を差し替え: catalog）\ncreate or replace function import_tax_classes(p_shop_id uuid, p_items jsonb)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_row jsonb; v_n integer; v_total integer := 0;\nbegin\n  if not banto_shop_perm(p_shop_id, 'catalog') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 1000 then raise exception 'invalid_items'; end if;\n  for v_row in select e from jsonb_array_elements(p_items) e loop\n    if v_row->>'tax_class' in ('standard', 'reduced', 'exempt') then\n      update products set tax_class = v_row->>'tax_class', updated_at = now()\n       where shop_id = p_shop_id and slug = v_row->>'slug' and tax_class is distinct from v_row->>'tax_class';\n      get diagnostics v_n = row_count; v_total := v_total + v_n;\n    end if;\n  end loop;\n  return v_total;\nend;\n$$;\n\n-- mask_customer（0001_init.sql を差し替え: customers）\ncreate or replace function mask_customer(p_shop_id uuid, p_email text)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_count integer;\nbegin\n  if not banto_shop_perm(p_shop_id, 'customers') then\n    raise exception 'shop_not_found' using errcode = '42501';\n  end if;\n  update orders\n     set customer_email = null, customer_name = '[masked]', shipping_address = null\n   where shop_id = p_shop_id and lower(customer_email) = lower(p_email);\n  get diagnostics v_count = row_count;\n  return v_count;\nend;\n$$;\n\n-- member_set_email（0012_member_auth.sql を差し替え: customers）\ncreate or replace function member_set_email(p_shop_id uuid, p_customer_id uuid, p_email text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_email text := lower(btrim(coalesce(p_email, '')));\n  v_old text;\nbegin\n  if not banto_shop_perm(p_shop_id, 'customers') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  select email into v_old from customers where shop_id = p_shop_id and id = p_customer_id for update;\n  if not found then raise exception 'customer_not_found'; end if;\n  if exists (select 1 from customers where shop_id = p_shop_id and lower(email) = v_email and id <> p_customer_id) then\n    raise exception 'email_taken';\n  end if;\n  update customers set email = v_email, session_epoch = session_epoch + 1 where shop_id = p_shop_id and id = p_customer_id;\n  -- 未使用のチャレンジは前のアドレスのものも含めて無効にする\n  update member_login_challenges set consumed_at = now()\n   where shop_id = p_shop_id and email in (lower(coalesce(v_old, '')), v_email) and consumed_at is null;\n  return jsonb_build_object('old_email', v_old, 'new_email', v_email);\nend;\n$$;\n\n-- sales_summary（0003_api.sql を差し替え: reports）\ncreate or replace function sales_summary(p_shop_id uuid, p_from timestamptz, p_to timestamptz, p_group_by text default 'day')\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_shop_perm(p_shop_id, 'reports') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  return sales_summary_for_shop(p_shop_id, p_from, p_to, p_group_by);\nend;\n$$;\n\n-- set_stock（0001_init.sql を差し替え: catalog）\ncreate or replace function set_stock(p_sku_id uuid, p_available integer)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_shop_id uuid;\nbegin\n  if p_available is null or p_available < 0 then\n    raise exception 'invalid_available';\n  end if;\n  select shop_id into v_shop_id from skus where id = p_sku_id;\n  if not found or not banto_shop_perm(v_shop_id, 'catalog') then\n    raise exception 'sku_not_found' using errcode = '42501';\n  end if;\n  update inventory set available = p_available, updated_at = now() where sku_id = p_sku_id;\n  return p_available;\nend;\n$$;\n\n-- ship_orders（0022_tracking.sql を差し替え: orders）\ncreate or replace function ship_orders(p_shop_id uuid, p_items jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_o orders%rowtype; v_num text; v_carrier text; v_tracking text;\n  v_shipped integer := 0; v_updated integer := 0; v_invalid integer := 0;\n  v_missing jsonb := '[]'::jsonb;\nbegin\n  if not banto_shop_perm(p_shop_id, 'orders') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 500 then raise exception 'invalid_items'; end if;\n  for v_row in select e from jsonb_array_elements(p_items) e loop\n    v_num := btrim(coalesce(v_row->>'number', ''));\n    v_carrier := v_row->>'carrier';\n    v_tracking := regexp_replace(coalesce(v_row->>'tracking', ''), '[\\s-]', '', 'g');\n    if v_num !~ '^[0-9]{1,9}$' or v_carrier is null or v_carrier not in ('yamato', 'sagawa', 'japanpost', 'other') or v_tracking !~ '^[0-9A-Za-z]{4,40}$' then\n      v_invalid := v_invalid + 1;\n      continue;\n    end if;\n    select * into v_o from orders where shop_id = p_shop_id and number = v_num::integer and status in ('paid', 'shipped') for update;\n    if not found then\n      if jsonb_array_length(v_missing) < 50 then v_missing := v_missing || to_jsonb(v_num::integer); end if;\n      continue;\n    end if;\n    if v_o.status = 'paid' then\n      update orders set status = 'shipped', shipped_at = now(), tracking_carrier = v_carrier, tracking_number = v_tracking, updated_at = now()\n       where id = v_o.id returning * into v_o;\n      perform enqueue_hook(p_shop_id, 'order.shipped',\n        jsonb_build_object('order_id', v_o.id, 'order_number', v_o.number, 'shop_id', p_shop_id, 'total_jpy', v_o.total_jpy, 'status', v_o.status,\n                           'shipped_at', v_o.shipped_at, 'customer_id', v_o.customer_id));\n      v_shipped := v_shipped + 1;\n    else\n      update orders set tracking_carrier = v_carrier, tracking_number = v_tracking, updated_at = now() where id = v_o.id;\n      v_updated := v_updated + 1;\n    end if;\n  end loop;\n  return jsonb_build_object('shipped', v_shipped, 'updated', v_updated, 'invalid', v_invalid, 'missing', v_missing);\nend;\n$$;\n\n-- shop_oauth_client_delete（0014_member_oauth.sql を差し替え: integrations）\ncreate or replace function shop_oauth_client_delete(p_shop_id uuid, p_provider text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_shop_perm(p_shop_id, 'integrations') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  delete from shop_oauth_clients where shop_id = p_shop_id and provider = p_provider;\n  update shops set settings = settings #- array['oauth', p_provider] where id = p_shop_id;\nend;\n$$;\n\n-- shop_oauth_client_save（0014_member_oauth.sql を差し替え: integrations）\ncreate or replace function shop_oauth_client_save(p_shop_id uuid, p_provider text, p_client_id text, p_secret_box text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_shop_perm(p_shop_id, 'integrations') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if p_provider not in ('line', 'google') then raise exception 'invalid_provider'; end if;\n  if p_client_id is null or length(btrim(p_client_id)) not between 1 and 200 or btrim(p_client_id) ~ '\\s' then raise exception 'invalid_client_id'; end if;\n  if p_secret_box is null then\n    -- client_id だけ変える（シークレットは今のまま）\n    update shop_oauth_clients set client_id = btrim(p_client_id), updated_at = now() where shop_id = p_shop_id and provider = p_provider;\n    if not found then raise exception 'secret_required'; end if;\n  else\n    insert into shop_oauth_clients (shop_id, provider, client_id, secret_box) values (p_shop_id, p_provider, btrim(p_client_id), p_secret_box)\n    on conflict (shop_id, provider) do update set client_id = excluded.client_id, secret_box = excluded.secret_box, updated_at = now();\n  end if;\n  update shops\n     set settings = jsonb_set(coalesce(settings, '{}'::jsonb), '{oauth}',\n                              coalesce(settings->'oauth', '{}'::jsonb) || jsonb_build_object(p_provider, jsonb_build_object('client_id', btrim(p_client_id))), true)\n   where id = p_shop_id;\nend;\n$$;\n\n-- shop_secret_save（0021_line_messaging.sql を差し替え: integrations）\ncreate or replace function shop_secret_save(p_shop_id uuid, p_purpose text, p_secret_box text)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_shop_perm(p_shop_id, 'integrations') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if p_purpose not in ('line_messaging') then raise exception 'invalid_purpose'; end if;\n  if p_secret_box is null then\n    delete from shop_secret_boxes where shop_id = p_shop_id and purpose = p_purpose;\n    return true;\n  end if;\n  insert into shop_secret_boxes (shop_id, purpose, secret_box) values (p_shop_id, p_purpose, p_secret_box)\n  on conflict (shop_id, purpose) do update set secret_box = excluded.secret_box, updated_at = now();\n  return true;\nend;\n$$;\n-- ---------- 実行権限 ----------\nrevoke execute on function banto_shop_perms_all() from public;\ngrant execute on function banto_shop_perms_all() to anon, authenticated, service_role;\ngrant execute on function banto_org_role(uuid) to anon, authenticated, service_role;\ngrant execute on function banto_org_admin(uuid) to anon, authenticated, service_role;\ngrant execute on function banto_shop_perm(uuid, text) to anon, authenticated, service_role;\nrevoke execute on function banto_admin_shop(uuid) from public, anon;\ngrant execute on function banto_admin_shop(uuid) to authenticated;\nrevoke execute on function banto_my_shops() from public, anon;\ngrant execute on function banto_my_shops() to authenticated;\nrevoke execute on function banto_owner_org() from public, anon, authenticated;\nrevoke execute on function banto_shops_guard() from public, anon, authenticated;\nrevoke execute on function banto_org_guard(uuid, text, text) from public, anon, authenticated;\nrevoke execute on function banto_set_member_shops(uuid, uuid, jsonb) from public, anon, authenticated;\nrevoke execute on function org_member_set(uuid, uuid, text, jsonb) from public, anon;\ngrant execute on function org_member_set(uuid, uuid, text, jsonb) to authenticated;\nrevoke execute on function org_member_remove(uuid, uuid) from public, anon;\ngrant execute on function org_member_remove(uuid, uuid) to authenticated;\nrevoke execute on function org_members_list(uuid) from public, anon;\ngrant execute on function org_members_list(uuid) to authenticated;\nrevoke execute on function org_invite(uuid, text, text, jsonb, text) from public, anon;\ngrant execute on function org_invite(uuid, text, text, jsonb, text) to authenticated;\nrevoke execute on function org_invitation_revoke(uuid, uuid) from public, anon;\ngrant execute on function org_invitation_revoke(uuid, uuid) to authenticated;\nrevoke execute on function org_invitation_peek(text) from public, anon, authenticated;\ngrant execute on function org_invitation_peek(text) to service_role;\nrevoke execute on function org_invitation_accept(text) from public, anon;\ngrant execute on function org_invitation_accept(text) to authenticated;\n\ninsert into banto_migrations (version) values ('0024_organizations');\n" },
  { version: "0025_store_tryon", sql: "-- 0025_store_tryon: 実店舗（組織の正本）と同梱モジュール「お店で試着」（docs/store-tryon.md、docs/knowledge/11-organizations.md）\n--\n-- お客様がネットで選んだ商品を、実店舗で試着できるよう取り置く。決済はしない（購入は店舗のレジ）。\n-- - stores … 組織の実店舗（正本。店頭受け取りなどでも使う汎用の器）。営業時間（曜日ごと）と臨時休業・臨時営業を持つ。\n--     hours        … {\"0\": [[\"10:00\",\"20:00\"]], …, \"6\": []}。キーは曜日（0 = 日曜）、空の配列は定休日。1 日に時間帯を 2 つまで（昼休み）\n--     special_days … [{ \"date\": \"2026-12-31\", \"closed\": true, \"note\": \"年末休業\" } | { \"date\": …, \"hours\": [[\"11:00\",\"17:00\"]], \"note\": \"臨時営業\" }]\n--     購入者（anon）には表を読ませない。お客様の画面は shop_store_list（公開の列だけ）で読む\n-- - shop_stores … ショップで使う実店舗（試着を受けるか・並び順）。ショップと実店舗は同じ組織のものだけ\n-- - org_member_stores … member に実店舗ごとの項目を割り当てる（tryon = 試着の申し込みを扱う、hours = 営業時間・臨時休業を直す）。\n--     実店舗のスタッフは連絡先は見えるが、在庫を EC に戻すことはできない（人間の決定 2026-10-17）\n-- - tryon_requests / tryon_items … 試着の申し込みと明細。書くのは下の関数だけ。\n--     読めるのは、ショップの stores の項目を持つ人と、その実店舗の tryon の項目を持つ人\n-- - 在庫は申し込みの時点で減らす（tryon_request、条件付き UPDATE。CLAUDE.md §1-7）。戻すのはショップの stores の項目を持つ人が選んだときだけ（tryon_restock）\n-- - hooks: tryon.requested（申し込み）・tryon.updated（状態が変わった）。ペイロードに個人情報は載せない\n\nalter table shops add column if not exists tryon_seq integer not null default 0;\n\ncreate or replace function banto_store_perms_all()\nreturns text[]\nlanguage sql\nimmutable\nas $$ select array['tryon', 'hours'] $$;\n\ncreate table stores (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references organizations(id) on delete cascade,\n  name text not null check (length(name) between 1 and 100),\n  postal_code text check (postal_code is null or length(postal_code) <= 10),\n  address text check (address is null or length(address) <= 200),\n  phone text check (phone is null or length(phone) <= 20),\n  email text check (email is null or (length(email) <= 254 and position('@' in email) > 1)),\n  hours jsonb not null default '{}'::jsonb check (jsonb_typeof(hours) = 'object'),\n  special_days jsonb not null default '[]'::jsonb check (jsonb_typeof(special_days) = 'array' and jsonb_array_length(special_days) <= 400),\n  note text check (note is null or length(note) <= 500),\n  notify_email boolean not null default false,\n  active boolean not null default true,\n  sort_order integer not null default 0,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on stores(org_id, sort_order);\n\ncreate table shop_stores (\n  shop_id uuid not null references shops(id) on delete cascade,\n  store_id uuid not null references stores(id) on delete cascade,\n  tryon boolean not null default true,\n  sort_order integer not null default 0,\n  created_at timestamptz not null default now(),\n  primary key (shop_id, store_id)\n);\ncreate index on shop_stores(store_id);\n\ncreate table org_member_stores (\n  org_id uuid not null,\n  user_id uuid not null,\n  store_id uuid not null references stores(id) on delete cascade,\n  perms text[] not null default '{}' check (perms <@ array['tryon', 'hours']),\n  primary key (user_id, store_id),\n  foreign key (org_id, user_id) references org_members(org_id, user_id) on delete cascade\n);\ncreate index on org_member_stores(store_id);\n\n-- ---------- 判定の関数 ----------\n-- その実店舗の項目: 組織の owner / admin なら常に true、member ならその実店舗の perms\ncreate or replace function banto_store_perm(p_store_id uuid, p_perm text)\nreturns boolean language sql stable security definer set search_path = public as $$\n  select exists (\n    select 1 from stores st\n     where st.id = p_store_id\n       and (banto_org_admin(st.org_id)\n            or exists (select 1 from org_member_stores ms where ms.store_id = st.id and ms.org_id = st.org_id and ms.user_id = auth.uid() and p_perm = any(ms.perms))));\n$$;\n\n-- 実店舗を読めるか: owner / admin、その実店舗の項目を持つ人、同じ組織のショップで stores の項目を持つ人（ショップで使う店舗を選ぶため）\ncreate or replace function banto_store_visible(p_store_id uuid)\nreturns boolean language sql stable security definer set search_path = public as $$\n  select exists (\n    select 1 from stores st\n     where st.id = p_store_id\n       and (banto_org_admin(st.org_id)\n            or exists (select 1 from org_member_stores ms where ms.store_id = st.id and ms.org_id = st.org_id and ms.user_id = auth.uid() and cardinality(ms.perms) > 0)\n            or exists (select 1 from org_member_shops ms where ms.org_id = st.org_id and ms.user_id = auth.uid() and 'stores' = any(ms.perms))));\n$$;\n\n-- ショップと実店舗は同じ組織のものだけ結べる\ncreate or replace function banto_shop_stores_guard()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if not exists (select 1 from shops s join stores st on st.org_id = s.org_id where s.id = new.shop_id and st.id = new.store_id) then\n    raise exception 'store_not_in_org' using errcode = '42501';\n  end if;\n  return new;\nend;\n$$;\ncreate trigger shop_stores_guard before insert or update on shop_stores for each row execute function banto_shop_stores_guard();\n\n-- ---------- RLS ----------\nalter table stores enable row level security;\nalter table shop_stores enable row level security;\nalter table org_member_stores enable row level security;\n-- 実店舗の追加・変更・削除は組織の owner / admin。営業時間だけは hours の項目を持つ人も（store_set_hours・stores_set_special_days）\ncreate policy stores_select on stores for select using (banto_store_visible(id));\ncreate policy stores_admin on stores for all using (banto_org_admin(org_id)) with check (banto_org_admin(org_id));\ncreate policy shop_stores_perm on shop_stores for all using (banto_shop_perm(shop_id, 'stores')) with check (banto_shop_perm(shop_id, 'stores'));\ncreate policy org_member_stores_select on org_member_stores for select using (user_id = auth.uid() or banto_org_admin(org_id));\nrevoke all on stores, shop_stores, org_member_stores from anon;\n\ncreate table tryon_requests (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  store_id uuid not null references stores(id),\n  number integer not null,\n  status text not null default 'requested' check (status in ('requested', 'sent', 'ready', 'purchased', 'not_purchased', 'expired', 'cancelled')),\n  -- 来店予定日（お客様が選ぶ形のとき）と、取り置きの期限（店舗に届いたときに決まる）。ショップの時間帯の日付\n  visit_date date,\n  hold_until date,\n  customer_id uuid,\n  -- 個人情報。終わった申し込みは mask_tryon_requests で一定期間後に消す（CLAUDE.md §8 と同じ扱い）\n  customer_email text,\n  customer_name text,\n  customer_phone text,\n  note text check (note is null or length(note) <= 500),\n  -- 減らした在庫を EC に戻したか\n  restocked boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  closed_at timestamptz,\n  foreign key (shop_id, customer_id) references customers(shop_id, id) on delete set null (customer_id)\n);\ncreate unique index tryon_requests_number on tryon_requests(shop_id, number);\ncreate index on tryon_requests(shop_id, status, created_at desc);\ncreate index on tryon_requests(store_id, status, created_at desc);\nalter table tryon_requests enable row level security;\ncreate policy tryon_requests_select on tryon_requests for select using (banto_shop_perm(shop_id, 'stores') or banto_store_perm(store_id, 'tryon'));\n\ncreate table tryon_items (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  request_id uuid not null references tryon_requests(id) on delete cascade,\n  sku_id uuid not null references skus(id),\n  qty integer not null check (qty between 1 and 99),\n  unit_price_jpy integer not null check (unit_price_jpy >= 0)\n);\ncreate index on tryon_items(request_id);\nalter table tryon_items enable row level security;\ncreate policy tryon_items_select on tryon_items for select\n  using (banto_shop_perm(shop_id, 'stores') or exists (select 1 from tryon_requests r where r.id = tryon_items.request_id and banto_store_perm(r.store_id, 'tryon')));\n\n-- ---------- hooks（試着の関数から。権限は呼び出し元の関数で確かめてある） ----------\n-- enqueue_hook（0024）は orders / catalog の項目を求めるので、実店舗のスタッフの操作から積めない。ここは関数の中からだけ使う\ncreate or replace function banto_enqueue_tryon_hook(p_shop_id uuid, p_event text, p_payload jsonb)\nreturns void language sql security definer set search_path = public as $$\n  insert into hook_deliveries (shop_id, endpoint_id, event, payload)\n  select e.shop_id, e.id, p_event, coalesce(p_payload, '{}'::jsonb)\n    from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and p_event = any(e.events);\n$$;\n\n-- ---------- お客様の画面の実店舗（anon。公開中のショップで使っている、営業中の店舗の公開の列だけ） ----------\ncreate or replace function shop_store_list(p_shop_id uuid)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select coalesce(jsonb_agg(jsonb_build_object('id', st.id, 'shop_id', ss.shop_id, 'name', st.name, 'postal_code', st.postal_code, 'address', st.address,\n                                               'phone', st.phone, 'hours', st.hours, 'special_days', st.special_days, 'note', st.note,\n                                               'tryon', ss.tryon, 'active', st.active, 'sort_order', ss.sort_order)\n                            order by ss.sort_order, st.sort_order, st.name), '[]'::jsonb)\n    from shop_stores ss join stores st on st.id = ss.store_id join shops s on s.id = ss.shop_id\n   where ss.shop_id = p_shop_id and s.published and st.active;\n$$;\n\n-- 自分が項目を持つ実店舗（スタッフの最初の画面）\ncreate or replace function banto_my_stores()\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select coalesce(jsonb_agg(jsonb_build_object('id', st.id, 'org_id', st.org_id, 'name', st.name, 'perms', to_jsonb(ms.perms)) order by st.sort_order, st.name), '[]'::jsonb)\n    from org_member_stores ms join stores st on st.id = ms.store_id and st.org_id = ms.org_id\n   where ms.user_id = auth.uid() and cardinality(ms.perms) > 0;\n$$;\n\n-- ---------- 営業時間（組織の owner / admin と hours の項目を持つ人） ----------\ncreate or replace function store_set_hours(p_store_id uuid, p_hours jsonb, p_special_days jsonb)\nreturns boolean language plpgsql security definer set search_path = public as $$\nbegin\n  if not banto_store_perm(p_store_id, 'hours') then raise exception 'store_not_found' using errcode = '42501'; end if;\n  if jsonb_typeof(p_hours) <> 'object' or jsonb_typeof(p_special_days) <> 'array' then raise exception 'invalid_hours'; end if;\n  update stores set hours = p_hours, special_days = p_special_days, updated_at = now() where id = p_store_id;\n  return true;\nend;\n$$;\n\n-- 臨時休業・臨時営業をまとめて登録する（全店舗 / 選んだ店舗に「12/31〜1/3 年末年始休業」など）。\n-- p_days: [{ date, closed, hours, note } | { date, remove: true }]。同じ日付は置き換え、remove は消す。30 日より前の日付は掃除する。\n-- 項目を持たない店舗は飛ばす。戻り値: 書き換えた店舗の数\ncreate or replace function stores_set_special_days(p_org_id uuid, p_store_ids uuid[], p_days jsonb)\nreturns integer language plpgsql security definer set search_path = public as $$\ndeclare v_store stores%rowtype; v_n integer := 0; v_dates text[]; v_next jsonb;\nbegin\n  if jsonb_typeof(p_days) <> 'array' or jsonb_array_length(p_days) = 0 or jsonb_array_length(p_days) > 400 then raise exception 'invalid_days'; end if;\n  if exists (select 1 from jsonb_array_elements(p_days) d where coalesce(d->>'date', '') !~ '^\\d{4}-\\d{2}-\\d{2}$') then raise exception 'invalid_days'; end if;\n  select array_agg(d->>'date') into v_dates from jsonb_array_elements(p_days) d;\n  for v_store in select * from stores where org_id = p_org_id and id = any(p_store_ids) for update loop\n    if not banto_store_perm(v_store.id, 'hours') then continue; end if;\n    select coalesce(jsonb_agg(e order by e->>'date'), '[]'::jsonb) into v_next from (\n      select e from jsonb_array_elements(v_store.special_days) e\n       where not (e->>'date' = any(v_dates)) and e->>'date' >= to_char(current_date - 30, 'YYYY-MM-DD')\n      union all\n      select d - 'remove' from jsonb_array_elements(p_days) d where coalesce((d->>'remove')::boolean, false) = false\n    ) x(e);\n    if jsonb_array_length(v_next) > 400 then raise exception 'too_many_days'; end if;\n    update stores set special_days = v_next, updated_at = now() where id = v_store.id;\n    v_n := v_n + 1;\n  end loop;\n  return v_n;\nend;\n$$;\n\n-- ---------- メンバーの割り当て（0024 を差し替え: [{ store_id, perms }] も受け取る） ----------\n-- p_shops: [{ shop_id, perms: [...] } | { store_id, perms: ['tryon','hours'] }]。その組織のショップ・実店舗の、決まった項目だけ入れる\ncreate or replace function banto_set_member_shops(p_org_id uuid, p_user_id uuid, p_shops jsonb)\nreturns void language plpgsql security definer set search_path = public as $$\ndeclare v_row jsonb;\nbegin\n  delete from org_member_shops where org_id = p_org_id and user_id = p_user_id;\n  delete from org_member_stores where org_id = p_org_id and user_id = p_user_id;\n  for v_row in select e from jsonb_array_elements(coalesce(p_shops, '[]'::jsonb)) e loop\n    if v_row ? 'store_id' then\n      if exists (select 1 from stores where id = nullif(v_row->>'store_id', '')::uuid and org_id = p_org_id) then\n        insert into org_member_stores (org_id, user_id, store_id, perms)\n        values (p_org_id, p_user_id, (v_row->>'store_id')::uuid,\n                coalesce((select array_agg(distinct p) from jsonb_array_elements_text(coalesce(v_row->'perms', '[]'::jsonb)) p where p = any(banto_store_perms_all())), '{}'))\n        on conflict (user_id, store_id) do update set perms = excluded.perms;\n      end if;\n    elsif exists (select 1 from shops where id = nullif(v_row->>'shop_id', '')::uuid and org_id = p_org_id) then\n      insert into org_member_shops (org_id, user_id, shop_id, perms)\n      values (p_org_id, p_user_id, (v_row->>'shop_id')::uuid,\n              coalesce((select array_agg(distinct p) from jsonb_array_elements_text(coalesce(v_row->'perms', '[]'::jsonb)) p where p = any(banto_shop_perms_all())), '{}'))\n      on conflict (user_id, shop_id) do update set perms = excluded.perms;\n    end if;\n  end loop;\nend;\n$$;\n\n-- メンバーの一覧（0024 を差し替え: 実店舗の割り当ても返す）\ncreate or replace function org_members_list(p_org_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  if not banto_org_admin(p_org_id) then raise exception 'org_not_found' using errcode = '42501'; end if;\n  return (select coalesce(jsonb_agg(jsonb_build_object('user_id', m.user_id, 'email', u.email, 'role', m.role, 'created_at', m.created_at,\n                                                       'shops', (select coalesce(jsonb_agg(jsonb_build_object('shop_id', ms.shop_id, 'perms', to_jsonb(ms.perms))), '[]'::jsonb)\n                                                                   from org_member_shops ms where ms.org_id = m.org_id and ms.user_id = m.user_id),\n                                                       'stores', (select coalesce(jsonb_agg(jsonb_build_object('store_id', ms.store_id, 'perms', to_jsonb(ms.perms))), '[]'::jsonb)\n                                                                    from org_member_stores ms where ms.org_id = m.org_id and ms.user_id = m.user_id))\n                                    order by m.created_at), '[]'::jsonb)\n            from org_members m join auth.users u on u.id = m.user_id where m.org_id = p_org_id);\nend;\n$$;\n\n-- ---------- 申し込み（service_role。ストアフロントとヘッドレスから） ----------\n-- p_items: [{ sku_id, qty }]、p_customer: { customer_email, customer_name, customer_phone, note, customer_id }。\n-- 店舗がそのショップで試着を受けている営業中の店舗か・SKU が公開中かを確かめ、在庫を条件付きで減らす（1 行でも足りなければ全体を取り消す）\ncreate or replace function tryon_request(p_shop_id uuid, p_store_id uuid, p_items jsonb, p_customer jsonb, p_visit_date date default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_it jsonb; v_sku skus%rowtype; v_qty integer; v_n integer; v_id uuid; v_number integer; v_cid uuid; v_total integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'tryon_request: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id and published) then raise exception 'shop_not_found'; end if;\n  if not exists (select 1 from shop_stores ss join stores st on st.id = ss.store_id where ss.shop_id = p_shop_id and ss.store_id = p_store_id and ss.tryon and st.active) then\n    raise exception 'store_not_available';\n  end if;\n  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > 20 then raise exception 'invalid_items'; end if;\n  if position('@' in coalesce(p_customer->>'customer_email', '')) < 2 then raise exception 'invalid_customer'; end if;\n  v_cid := nullif(p_customer->>'customer_id', '')::uuid;\n  if v_cid is not null and not exists (select 1 from customers where shop_id = p_shop_id and id = v_cid) then v_cid := null; end if;\n\n  update shops set tryon_seq = tryon_seq + 1 where id = p_shop_id returning tryon_seq into v_number;\n  insert into tryon_requests (shop_id, store_id, number, visit_date, customer_id, customer_email, customer_name, customer_phone, note)\n  values (p_shop_id, p_store_id, v_number, p_visit_date, v_cid, lower(btrim(p_customer->>'customer_email')),\n          left(nullif(btrim(coalesce(p_customer->>'customer_name', '')), ''), 100), left(nullif(btrim(coalesce(p_customer->>'customer_phone', '')), ''), 20),\n          left(nullif(btrim(coalesce(p_customer->>'note', '')), ''), 500))\n  returning id into v_id;\n\n  for v_it in select e from jsonb_array_elements(p_items) e loop\n    v_qty := case when coalesce(v_it->>'qty', '') ~ '^[0-9]{1,2}$' then (v_it->>'qty')::integer else 0 end;\n    if v_qty <= 0 then raise exception 'invalid_items'; end if;\n    select k.* into v_sku from skus k join products p on p.id = k.product_id\n     where k.id = nullif(v_it->>'sku_id', '')::uuid and k.shop_id = p_shop_id and p.published;\n    if not found then raise exception 'sku_not_available'; end if;\n    update inventory set available = available - v_qty where sku_id = v_sku.id and shop_id = p_shop_id and available >= v_qty;\n    get diagnostics v_n = row_count;\n    if v_n = 0 then raise exception 'insufficient_stock' using detail = v_sku.id::text; end if;\n    insert into tryon_items (shop_id, request_id, sku_id, qty, unit_price_jpy) values (p_shop_id, v_id, v_sku.id, v_qty, v_sku.price_jpy);\n    v_total := v_total + v_qty;\n  end loop;\n  if v_total > 20 then raise exception 'invalid_items'; end if;\n\n  perform banto_enqueue_tryon_hook(p_shop_id, 'tryon.requested',\n    jsonb_build_object('request_id', v_id, 'number', v_number, 'shop_id', p_shop_id, 'store_id', p_store_id, 'status', 'requested',\n                       'visit_date', p_visit_date, 'customer_id', v_cid));\n  return jsonb_build_object('id', v_id, 'number', v_number);\nend;\n$$;\n\n-- ---------- 申し込み 1 件（管理画面。ショップの stores の項目か、その実店舗の tryon の項目） ----------\n-- 実店舗のスタッフは商品の表を読めないので、明細の品名もここで返す\ncreate or replace function tryon_request_detail(p_request_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\ndeclare v_r tryon_requests%rowtype;\nbegin\n  select * into v_r from tryon_requests where id = p_request_id;\n  if not found or not (banto_shop_perm(v_r.shop_id, 'stores') or banto_store_perm(v_r.store_id, 'tryon')) then return null; end if;\n  return jsonb_build_object(\n    'request', to_jsonb(v_r),\n    'store', (select jsonb_build_object('id', st.id, 'name', st.name, 'hours', st.hours, 'special_days', st.special_days) from stores st where st.id = v_r.store_id),\n    'shop', (select jsonb_build_object('id', s.id, 'name', s.name, 'settings', jsonb_build_object('store_tryon', s.settings->'store_tryon')) from shops s where s.id = v_r.shop_id),\n    'can_restock', banto_shop_perm(v_r.shop_id, 'stores'),\n    'items', (select coalesce(jsonb_agg(jsonb_build_object('sku_id', t.sku_id, 'code', k.code, 'product', p.name, 'sku', k.name, 'qty', t.qty, 'unit_price_jpy', t.unit_price_jpy) order by t.id), '[]'::jsonb)\n                from tryon_items t join skus k on k.id = t.sku_id join products p on p.id = k.product_id where t.request_id = v_r.id));\nend;\n$$;\n\n-- ---------- 状態を進める（ショップの stores の項目か、その実店舗の tryon の項目） ----------\n-- 申し込み → 店舗へ発送済み → 取り置き中（期限） → 購入 / 購入なし / 期限切れ。終わる前ならキャンセルできる\ncreate or replace function tryon_update(p_shop_id uuid, p_request_id uuid, p_status text, p_hold_until date default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_r tryon_requests%rowtype; v_ok boolean;\nbegin\n  select * into v_r from tryon_requests where id = p_request_id and shop_id = p_shop_id for update;\n  if not found or not (banto_shop_perm(p_shop_id, 'stores') or banto_store_perm(v_r.store_id, 'tryon')) then\n    raise exception 'not_found' using errcode = '42501';\n  end if;\n  v_ok := case p_status\n    when 'sent' then v_r.status = 'requested'\n    when 'ready' then v_r.status in ('requested', 'sent', 'ready')\n    when 'purchased' then v_r.status in ('ready', 'expired')\n    when 'not_purchased' then v_r.status in ('ready', 'expired')\n    when 'expired' then v_r.status = 'ready'\n    when 'cancelled' then v_r.status in ('requested', 'sent', 'ready')\n    else false end;\n  if not v_ok then raise exception 'invalid_transition' using detail = v_r.status || ' -> ' || coalesce(p_status, ''); end if;\n  if p_status = 'ready' and p_hold_until is null then raise exception 'hold_until_required'; end if;\n  update tryon_requests set status = p_status, updated_at = now(),\n    hold_until = case when p_status = 'ready' then p_hold_until else hold_until end,\n    closed_at = case when p_status in ('purchased', 'not_purchased', 'expired', 'cancelled') then now() end\n   where id = v_r.id returning * into v_r;\n  perform banto_enqueue_tryon_hook(p_shop_id, 'tryon.updated',\n    jsonb_build_object('request_id', v_r.id, 'number', v_r.number, 'shop_id', p_shop_id, 'store_id', v_r.store_id, 'status', v_r.status,\n                       'hold_until', v_r.hold_until, 'customer_id', v_r.customer_id));\n  return jsonb_build_object('id', v_r.id, 'status', v_r.status, 'hold_until', v_r.hold_until);\nend;\n$$;\n\n-- ---------- 減らした在庫を EC に戻す（ショップの stores の項目を持つ人が選んだときだけ。実店舗のスタッフはできない） ----------\ncreate or replace function tryon_restock(p_shop_id uuid, p_request_id uuid)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_r tryon_requests%rowtype; v_n integer := 0;\nbegin\n  if not banto_shop_perm(p_shop_id, 'stores') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  select * into v_r from tryon_requests where id = p_request_id and shop_id = p_shop_id for update;\n  if not found then raise exception 'not_found'; end if;\n  if v_r.status not in ('not_purchased', 'expired', 'cancelled') then raise exception 'not_restockable'; end if;\n  if v_r.restocked then return 0; end if;\n  update inventory i set available = i.available + t.qty\n    from (select sku_id, sum(qty)::integer as qty from tryon_items where request_id = v_r.id group by sku_id) t\n   where i.sku_id = t.sku_id and i.shop_id = p_shop_id;\n  get diagnostics v_n = row_count;\n  update tryon_requests set restocked = true, updated_at = now() where id = v_r.id;\n  return v_n;\nend;\n$$;\n\n-- ---------- 取り置きの期限切れ（Cron。p_today はショップの時間帯の今日） ----------\ncreate or replace function tryon_expire(p_today date)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_r tryon_requests%rowtype; v_n integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'tryon_expire: service_role only' using errcode = '42501';\n  end if;\n  for v_r in update tryon_requests set status = 'expired', closed_at = now(), updated_at = now()\n              where status = 'ready' and hold_until < p_today returning * loop\n    perform banto_enqueue_tryon_hook(v_r.shop_id, 'tryon.updated',\n      jsonb_build_object('request_id', v_r.id, 'number', v_r.number, 'shop_id', v_r.shop_id, 'store_id', v_r.store_id, 'status', 'expired',\n                         'hold_until', v_r.hold_until, 'customer_id', v_r.customer_id));\n    v_n := v_n + 1;\n  end loop;\n  return v_n;\nend;\n$$;\n\n-- ---------- 終わった申し込みの個人情報を消す（Cron。CLAUDE.md §8） ----------\ncreate or replace function mask_tryon_requests(p_days integer)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'mask_tryon_requests: service_role only' using errcode = '42501';\n  end if;\n  update tryon_requests set customer_email = null, customer_name = '[masked]', customer_phone = null, note = null\n   where closed_at is not null and closed_at < now() - make_interval(days => greatest(p_days, 1)) and customer_email is not null;\n  get diagnostics v_n = row_count;\n  return v_n;\nend;\n$$;\n\n-- ---------- お知らせ用（メール通知・LINE のプラグインが読む。service_role） ----------\ncreate or replace function tryon_contact(p_request_id uuid, p_shop_id uuid)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_r tryon_requests%rowtype; v_st stores%rowtype; v_s shops%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'tryon_contact: service_role only' using errcode = '42501';\n  end if;\n  select * into v_r from tryon_requests where id = p_request_id and shop_id = p_shop_id;\n  if not found then raise exception 'not_found'; end if;\n  select * into v_st from stores where id = v_r.store_id;\n  select * into v_s from shops where id = p_shop_id;\n  return jsonb_build_object(\n    'request_id', v_r.id, 'number', v_r.number, 'status', v_r.status, 'visit_date', v_r.visit_date, 'hold_until', v_r.hold_until,\n    'customer_email', v_r.customer_email, 'customer_name', v_r.customer_name, 'customer_phone', v_r.customer_phone, 'note', v_r.note,\n    'store', jsonb_build_object('name', v_st.name, 'postal_code', v_st.postal_code, 'address', v_st.address, 'phone', v_st.phone,\n                                'email', v_st.email, 'notify_email', v_st.notify_email, 'hours', v_st.hours, 'special_days', v_st.special_days),\n    'shop', jsonb_build_object('name', v_s.name, 'slug', v_s.slug, 'domain', v_s.domain, 'contact_email', v_s.settings->>'contact_email', 'settings', v_s.settings->'store_tryon'),\n    'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', t.qty, 'unit_price_jpy', t.unit_price_jpy) order by t.id), '[]'::jsonb)\n                from tryon_items t join skus k on k.id = t.sku_id join products p on p.id = k.product_id where t.request_id = v_r.id));\nend;\n$$;\n\ncreate or replace function tryon_line_recipient(p_request_id uuid, p_shop_id uuid)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'tryon_line_recipient: service_role only' using errcode = '42501';\n  end if;\n  return (\n    select jsonb_build_object('line_user_id', i.subject, 'number', r.number, 'status', r.status, 'hold_until', r.hold_until,\n                              'store_name', st.name, 'shop_name', s.name)\n      from tryon_requests r join shops s on s.id = r.shop_id join stores st on st.id = r.store_id\n      join member_identities i on i.shop_id = r.shop_id and i.customer_id = r.customer_id and i.provider = 'line'\n     where r.id = p_request_id and r.shop_id = p_shop_id and r.customer_id is not null\n     limit 1);\nend;\n$$;\n\n-- 同梱のメール通知・LINE 通知のプラグインを有効にしているショップは、試着のお知らせも受け取る（有効化の時点のイベントの一覧に足す）\nupdate hook_endpoints\n   set events = (select array_agg(distinct e) from unnest(events || array['tryon.requested', 'tryon.updated']) e)\n where url in ('https://banto.invalid/plugins/email_resend', 'https://banto.invalid/plugins/line_buyer_notify');\n\nrevoke execute on function banto_store_perms_all() from public;\ngrant execute on function banto_store_perms_all() to anon, authenticated, service_role;\ngrant execute on function banto_store_perm(uuid, text) to anon, authenticated, service_role;\ngrant execute on function banto_store_visible(uuid) to anon, authenticated, service_role;\nrevoke execute on function banto_shop_stores_guard() from public, anon, authenticated;\nrevoke execute on function banto_enqueue_tryon_hook(uuid, text, jsonb) from public, anon, authenticated, service_role;\nrevoke execute on function shop_store_list(uuid) from public;\ngrant execute on function shop_store_list(uuid) to anon, authenticated, service_role;\nrevoke execute on function banto_my_stores() from public, anon;\ngrant execute on function banto_my_stores() to authenticated;\nrevoke execute on function store_set_hours(uuid, jsonb, jsonb) from public, anon;\ngrant execute on function store_set_hours(uuid, jsonb, jsonb) to authenticated;\nrevoke execute on function stores_set_special_days(uuid, uuid[], jsonb) from public, anon;\ngrant execute on function stores_set_special_days(uuid, uuid[], jsonb) to authenticated;\nrevoke execute on function banto_set_member_shops(uuid, uuid, jsonb) from public, anon, authenticated;\nrevoke execute on function org_members_list(uuid) from public, anon;\ngrant execute on function org_members_list(uuid) to authenticated;\nrevoke execute on function tryon_request(uuid, uuid, jsonb, jsonb, date) from public, anon, authenticated;\ngrant execute on function tryon_request(uuid, uuid, jsonb, jsonb, date) to service_role;\nrevoke execute on function tryon_request_detail(uuid) from public, anon;\ngrant execute on function tryon_request_detail(uuid) to authenticated;\nrevoke execute on function tryon_update(uuid, uuid, text, date) from public, anon;\ngrant execute on function tryon_update(uuid, uuid, text, date) to authenticated;\nrevoke execute on function tryon_restock(uuid, uuid) from public, anon;\ngrant execute on function tryon_restock(uuid, uuid) to authenticated;\nrevoke execute on function tryon_expire(date) from public, anon, authenticated;\ngrant execute on function tryon_expire(date) to service_role;\nrevoke execute on function mask_tryon_requests(integer) from public, anon, authenticated;\ngrant execute on function mask_tryon_requests(integer) to service_role;\nrevoke execute on function tryon_contact(uuid, uuid) from public, anon, authenticated;\ngrant execute on function tryon_contact(uuid, uuid) to service_role;\nrevoke execute on function tryon_line_recipient(uuid, uuid) from public, anon, authenticated;\ngrant execute on function tryon_line_recipient(uuid, uuid) to service_role;\n\ninsert into banto_migrations (version) values ('0025_store_tryon');\n" },
  { version: "0026_tryon_api", sql: "-- 0026_tryon_api: お店で試着を AI 用トークン・会員から使う（docs/store-tryon.md、docs/ai-access.md）と、AI 用トークンの発行者の確認\n--\n-- - AI 用トークン（api_*）: 試着の申し込みは注文に準じて orders:read（一覧・1 件）・orders:write（状態を進める）、\n--   お客様の名前・メール・電話・ご要望は orders:pii があるときだけ返す。終わった申し込みの在庫を EC に戻す操作も orders:write で出す\n--   （人間の決定 2026-10-17。実店舗のスタッフには戻させない決定はそのまま）。\n--   実店舗の一覧（営業時間・臨時休業）は shop:read。\n-- - 会員（service_role の member_*、世代を確かめる）: 自分の申し込みの一覧と、取り置きが終わる前の取り消し。\n-- - AI 用トークンは、発行した人がそのショップの integrations の項目（組織の owner / admin を含む）を持っている間だけ使える\n--   （0024 で招待したメンバーを外したり項目を外したりしても、トークンが残って使えてしまうのを防ぐ）。\n-- 状態の遷移は 1 か所（banto_tryon_transition）、在庫を戻すのも 1 か所（banto_tryon_restock）にまとめ、管理画面と AI が同じものを通る。\n\n-- ---------- AI 用トークンの発行者の確認 ----------\ncreate or replace function banto_token_issuer_ok(p_owner_id uuid, p_shop_id uuid)\nreturns boolean language sql stable security definer set search_path = public as $$\n  select exists (\n    select 1 from shops s\n     where s.id = p_shop_id\n       and ((s.org_id is null and s.owner_id = p_owner_id)\n            or (s.org_id is not null and (\n                  exists (select 1 from org_members m where m.org_id = s.org_id and m.user_id = p_owner_id and m.role in ('owner', 'admin'))\n                  or exists (select 1 from org_member_shops ms where ms.org_id = s.org_id and ms.shop_id = s.id and ms.user_id = p_owner_id and 'integrations' = any(ms.perms))))));\n$$;\n\ncreate or replace function api_require(p_token_hash text, p_scope text)\nreturns api_tokens\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'api_require: service_role only' using errcode = '42501';\n  end if;\n  select * into v_tok from api_tokens\n   where token_hash = p_token_hash\n     and revoked_at is null\n     and (expires_at is null or expires_at > now());\n  if not found or not (p_scope = any(v_tok.scopes)) or not banto_token_issuer_ok(v_tok.owner_id, v_tok.shop_id) then\n    raise exception 'unauthorized' using errcode = '42501';\n  end if;\n  -- 最終利用は1分に1回だけ更新（書き込みを減らす）\n  if v_tok.last_used_at is null or v_tok.last_used_at < now() - interval '1 minute' then\n    update api_tokens set last_used_at = now() where id = v_tok.id;\n  end if;\n  return v_tok;\nend;\n$$;\n\ncreate or replace function api_has_scope(p_token_hash text, p_scope text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select exists (\n    select 1 from api_tokens\n     where token_hash = p_token_hash and revoked_at is null and (expires_at is null or expires_at > now())\n       and p_scope = any(scopes) and banto_token_issuer_ok(owner_id, shop_id)\n  );\n$$;\n\ncreate or replace function api_token_shop(p_token_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens%rowtype; v_acct text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'api_token_shop: service_role only' using errcode = '42501';\n  end if;\n  select * into v_tok from api_tokens\n   where token_hash = p_token_hash and revoked_at is null and (expires_at is null or expires_at > now());\n  if not found or not banto_token_issuer_ok(v_tok.owner_id, v_tok.shop_id) then raise exception 'unauthorized' using errcode = '42501'; end if;\n  select stripe_account_id into v_acct from shops where id = v_tok.shop_id;\n  return jsonb_build_object('shop_id', v_tok.shop_id, 'scopes', to_jsonb(v_tok.scopes), 'name', v_tok.name, 'stripe_account_id', v_acct);\nend;\n$$;\n\n-- ---------- 状態の遷移（権限は呼び出し元で確かめる。内部用） ----------\n-- 申し込み → 店舗へ発送済み → 取り置き中（期限） → 購入 / 購入なし / 期限切れ。終わる前ならキャンセルできる\ncreate or replace function banto_tryon_transition(p_shop_id uuid, p_request_id uuid, p_status text, p_hold_until date)\nreturns tryon_requests\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_r tryon_requests%rowtype; v_ok boolean;\nbegin\n  select * into v_r from tryon_requests where id = p_request_id and shop_id = p_shop_id for update;\n  if not found then raise exception 'not_found'; end if;\n  v_ok := case p_status\n    when 'sent' then v_r.status = 'requested'\n    when 'ready' then v_r.status in ('requested', 'sent', 'ready')\n    when 'purchased' then v_r.status in ('ready', 'expired')\n    when 'not_purchased' then v_r.status in ('ready', 'expired')\n    when 'expired' then v_r.status = 'ready'\n    when 'cancelled' then v_r.status in ('requested', 'sent', 'ready')\n    else false end;\n  if not v_ok then raise exception 'invalid_transition' using detail = v_r.status || ' -> ' || coalesce(p_status, ''); end if;\n  if p_status = 'ready' and p_hold_until is null then raise exception 'hold_until_required'; end if;\n  update tryon_requests set status = p_status, updated_at = now(),\n    hold_until = case when p_status = 'ready' then p_hold_until else hold_until end,\n    closed_at = case when p_status in ('purchased', 'not_purchased', 'expired', 'cancelled') then now() end\n   where id = v_r.id returning * into v_r;\n  perform banto_enqueue_tryon_hook(p_shop_id, 'tryon.updated',\n    jsonb_build_object('request_id', v_r.id, 'number', v_r.number, 'shop_id', p_shop_id, 'store_id', v_r.store_id, 'status', v_r.status,\n                       'hold_until', v_r.hold_until, 'customer_id', v_r.customer_id));\n  return v_r;\nend;\n$$;\n\n-- 管理画面（0025 を差し替え: 遷移は banto_tryon_transition）\ncreate or replace function tryon_update(p_shop_id uuid, p_request_id uuid, p_status text, p_hold_until date default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_r tryon_requests%rowtype;\nbegin\n  select * into v_r from tryon_requests where id = p_request_id and shop_id = p_shop_id;\n  if not found or not (banto_shop_perm(p_shop_id, 'stores') or banto_store_perm(v_r.store_id, 'tryon')) then\n    raise exception 'not_found' using errcode = '42501';\n  end if;\n  v_r := banto_tryon_transition(p_shop_id, p_request_id, p_status, p_hold_until);\n  return jsonb_build_object('id', v_r.id, 'status', v_r.status, 'hold_until', v_r.hold_until);\nend;\n$$;\n\n-- ---------- 減らした在庫を EC に戻す（権限は呼び出し元で確かめる。内部用。1 回だけ） ----------\ncreate or replace function banto_tryon_restock(p_shop_id uuid, p_request_id uuid)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_r tryon_requests%rowtype; v_n integer := 0;\nbegin\n  select * into v_r from tryon_requests where id = p_request_id and shop_id = p_shop_id for update;\n  if not found then raise exception 'not_found'; end if;\n  if v_r.status not in ('not_purchased', 'expired', 'cancelled') then raise exception 'not_restockable'; end if;\n  if v_r.restocked then return 0; end if;\n  update inventory i set available = i.available + t.qty\n    from (select sku_id, sum(qty)::integer as qty from tryon_items where request_id = v_r.id group by sku_id) t\n   where i.sku_id = t.sku_id and i.shop_id = p_shop_id;\n  get diagnostics v_n = row_count;\n  update tryon_requests set restocked = true, updated_at = now() where id = v_r.id;\n  return v_n;\nend;\n$$;\n\n-- 管理画面（0025 を差し替え: 中身は banto_tryon_restock。ショップの stores の項目だけ）\ncreate or replace function tryon_restock(p_shop_id uuid, p_request_id uuid)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_shop_perm(p_shop_id, 'stores') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  return banto_tryon_restock(p_shop_id, p_request_id);\nend;\n$$;\n\n-- ---------- AI 用トークン ----------\ncreate or replace function api_tryon_json(p_r tryon_requests, p_pii boolean)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select jsonb_build_object(\n    'id', p_r.id, 'number', p_r.number, 'status', p_r.status, 'store_id', p_r.store_id,\n    'store_name', (select name from stores where id = p_r.store_id),\n    'visit_date', p_r.visit_date, 'hold_until', p_r.hold_until, 'customer_id', p_r.customer_id, 'restocked', p_r.restocked,\n    'created_at', p_r.created_at, 'updated_at', p_r.updated_at, 'closed_at', p_r.closed_at,\n    'items', (select coalesce(jsonb_agg(jsonb_build_object('sku_id', t.sku_id, 'sku_code', k.code, 'product_name', p.name, 'sku_name', k.name,\n                                                           'qty', t.qty, 'unit_price_jpy', t.unit_price_jpy) order by t.id), '[]'::jsonb)\n                from tryon_items t join skus k on k.id = t.sku_id join products p on p.id = k.product_id where t.request_id = p_r.id))\n  || case when p_pii then jsonb_build_object('customer', jsonb_build_object('email', p_r.customer_email, 'name', p_r.customer_name, 'phone', p_r.customer_phone, 'note', p_r.note))\n          else '{}'::jsonb end;\n$$;\n\ncreate or replace function api_tryon_requests_list(p_token_hash text, p_status text default null, p_store_id uuid default null,\n                                                   p_limit integer default 50, p_offset integer default 0)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_pii boolean; v_limit integer; v_total integer; v_items jsonb;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:read');\n  v_pii := 'orders:pii' = any(v_tok.scopes);\n  v_limit := greatest(1, least(coalesce(p_limit, 50), 100));\n  select count(*) into v_total from tryon_requests r\n   where r.shop_id = v_tok.shop_id and (p_status is null or r.status = p_status) and (p_store_id is null or r.store_id = p_store_id);\n  select coalesce(jsonb_agg(api_tryon_json(r, v_pii) order by r.created_at desc), '[]'::jsonb) into v_items\n    from (select * from tryon_requests r\n           where r.shop_id = v_tok.shop_id and (p_status is null or r.status = p_status) and (p_store_id is null or r.store_id = p_store_id)\n           order by r.created_at desc limit v_limit offset greatest(0, coalesce(p_offset, 0))) r;\n  return jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', greatest(0, coalesce(p_offset, 0)), 'pii', v_pii);\nend;\n$$;\n\ncreate or replace function api_tryon_request_get(p_token_hash text, p_number integer)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_r tryon_requests%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:read');\n  select * into v_r from tryon_requests where shop_id = v_tok.shop_id and number = p_number;\n  if not found then raise exception 'not_found'; end if;\n  return api_tryon_json(v_r, 'orders:pii' = any(v_tok.scopes));\nend;\n$$;\n\ncreate or replace function api_tryon_request_update(p_token_hash text, p_number integer, p_status text, p_hold_until date default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_r tryon_requests%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:write');\n  select * into v_r from tryon_requests where shop_id = v_tok.shop_id and number = p_number;\n  if not found then raise exception 'not_found'; end if;\n  if p_status not in ('sent', 'ready', 'purchased', 'not_purchased', 'cancelled') then raise exception 'invalid_status'; end if;\n  v_r := banto_tryon_transition(v_tok.shop_id, v_r.id, p_status, p_hold_until);\n  return api_tryon_json(v_r, 'orders:pii' = any(v_tok.scopes));\nend;\n$$;\n\n-- 終わった申し込み（購入なし・期限切れ・取り消し）の在庫を EC に戻す。2 回目は何もしない（restocked: true のまま）\ncreate or replace function api_tryon_request_restock(p_token_hash text, p_number integer)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_r tryon_requests%rowtype; v_n integer;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:write');\n  select * into v_r from tryon_requests where shop_id = v_tok.shop_id and number = p_number;\n  if not found then raise exception 'not_found'; end if;\n  v_n := banto_tryon_restock(v_tok.shop_id, v_r.id);\n  select * into v_r from tryon_requests where id = v_r.id;\n  return api_tryon_json(v_r, 'orders:pii' = any(v_tok.scopes)) || jsonb_build_object('restocked_skus', v_n);\nend;\n$$;\n\ncreate or replace function api_stores_list(p_token_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens;\nbegin\n  v_tok := api_require(p_token_hash, 'shop:read');\n  return (select coalesce(jsonb_agg(jsonb_build_object('id', st.id, 'name', st.name, 'postal_code', st.postal_code, 'address', st.address, 'phone', st.phone,\n                                                       'hours', st.hours, 'special_days', st.special_days, 'note', st.note, 'active', st.active,\n                                                       'tryon', ss.tryon, 'sort_order', ss.sort_order)\n                                    order by ss.sort_order, st.sort_order, st.name), '[]'::jsonb)\n            from shop_stores ss join stores st on st.id = ss.store_id where ss.shop_id = v_tok.shop_id);\nend;\n$$;\n\n-- ---------- 会員（service_role。世代を確かめる） ----------\n-- 自分の申し込み（新しい順に 50 件）。世代が合わなければ null\ncreate or replace function member_tryon_requests(p_shop_id uuid, p_customer_id uuid, p_epoch integer)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_tryon_requests: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then return null; end if;\n  return (select coalesce(jsonb_agg(jsonb_build_object(\n            'number', r.number, 'status', r.status, 'store_id', r.store_id, 'store_name', st.name, 'visit_date', r.visit_date, 'hold_until', r.hold_until,\n            'created_at', r.created_at,\n            'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', t.qty) order by t.id), '[]'::jsonb)\n                        from tryon_items t join skus k on k.id = t.sku_id join products p on p.id = k.product_id where t.request_id = r.id))\n          order by r.created_at desc), '[]'::jsonb)\n            from (select * from tryon_requests where shop_id = p_shop_id and customer_id = p_customer_id order by created_at desc limit 50) r\n            join stores st on st.id = r.store_id);\nend;\n$$;\n\n-- 自分の申し込みを取り消す（取り置きが終わる前: 申し込み・発送済み・取り置き中）。戻り値: { ok } | { ok: false, reason: session | not_found | not_cancellable }\n-- 在庫は今までどおり、ショップの担当者が「EC の在庫に戻す」を押したときに戻る（商品が店舗に向かっていることがあるため）\ncreate or replace function member_tryon_cancel(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_number integer)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_r tryon_requests%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_tryon_cancel: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then\n    return jsonb_build_object('ok', false, 'reason', 'session');\n  end if;\n  select * into v_r from tryon_requests where shop_id = p_shop_id and customer_id = p_customer_id and number = p_number for update;\n  if not found then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;\n  if v_r.status not in ('requested', 'sent', 'ready') then return jsonb_build_object('ok', false, 'reason', 'not_cancellable'); end if;\n  perform banto_tryon_transition(p_shop_id, v_r.id, 'cancelled', null);\n  return jsonb_build_object('ok', true);\nend;\n$$;\n\nrevoke execute on function banto_token_issuer_ok(uuid, uuid) from public, anon, authenticated;\nrevoke execute on function api_require(text, text) from public, anon, authenticated;\ngrant execute on function api_require(text, text) to service_role;\nrevoke execute on function api_has_scope(text, text) from public, anon, authenticated;\ngrant execute on function api_has_scope(text, text) to service_role;\nrevoke execute on function api_token_shop(text) from public, anon, authenticated;\ngrant execute on function api_token_shop(text) to service_role;\nrevoke execute on function banto_tryon_transition(uuid, uuid, text, date) from public, anon, authenticated, service_role;\nrevoke execute on function tryon_update(uuid, uuid, text, date) from public, anon;\ngrant execute on function tryon_update(uuid, uuid, text, date) to authenticated;\nrevoke execute on function api_tryon_json(tryon_requests, boolean) from public, anon, authenticated, service_role;\nrevoke execute on function api_tryon_requests_list(text, text, uuid, integer, integer) from public, anon, authenticated;\ngrant execute on function api_tryon_requests_list(text, text, uuid, integer, integer) to service_role;\nrevoke execute on function api_tryon_request_get(text, integer) from public, anon, authenticated;\ngrant execute on function api_tryon_request_get(text, integer) to service_role;\nrevoke execute on function api_tryon_request_update(text, integer, text, date) from public, anon, authenticated;\ngrant execute on function api_tryon_request_update(text, integer, text, date) to service_role;\nrevoke execute on function banto_tryon_restock(uuid, uuid) from public, anon, authenticated, service_role;\nrevoke execute on function tryon_restock(uuid, uuid) from public, anon;\ngrant execute on function tryon_restock(uuid, uuid) to authenticated;\nrevoke execute on function api_tryon_request_restock(text, integer) from public, anon, authenticated;\ngrant execute on function api_tryon_request_restock(text, integer) to service_role;\nrevoke execute on function api_stores_list(text) from public, anon, authenticated;\ngrant execute on function api_stores_list(text) to service_role;\nrevoke execute on function member_tryon_requests(uuid, uuid, integer) from public, anon, authenticated;\ngrant execute on function member_tryon_requests(uuid, uuid, integer) to service_role;\nrevoke execute on function member_tryon_cancel(uuid, uuid, integer, integer) from public, anon, authenticated;\ngrant execute on function member_tryon_cancel(uuid, uuid, integer, integer) to service_role;\n\ninsert into banto_migrations (version) values ('0026_tryon_api');\n" },
  { version: "0027_tryon_shop_names", sql: "-- 0027_tryon_shop_names: 実店舗のスタッフの申し込みの一覧にショップ名を出す（docs/store-tryon.md）\n--\n-- 実店舗のスタッフ（org_member_stores の tryon）はショップの表を読めない（0024 の RLS）。同じ店舗を複数のショップで使うと、\n-- どのショップの申し込みか分からないので、その店舗の申し込みがあるショップ・その店舗を使うショップの名前だけを返す。\n-- 名前と id 以外（設定・法務・入金先）は返さない。tryon の項目が無ければ空。\ncreate or replace function tryon_store_shops(p_store_id uuid)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select case when banto_store_perm(p_store_id, 'tryon') then (\n    select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name) order by s.created_at), '[]'::jsonb)\n      from shops s\n     where s.org_id = (select org_id from stores where id = p_store_id)\n       and (exists (select 1 from shop_stores ss where ss.shop_id = s.id and ss.store_id = p_store_id)\n            or exists (select 1 from tryon_requests r where r.shop_id = s.id and r.store_id = p_store_id)))\n  else '[]'::jsonb end;\n$$;\n\nrevoke execute on function tryon_store_shops(uuid) from public, anon;\ngrant execute on function tryon_store_shops(uuid) to authenticated;\n\ninsert into banto_migrations (version) values ('0027_tryon_shop_names');\n" },
  { version: "0028_security_hardening", sql: "-- Banto 0028_security_hardening: セキュリティ監査（2026-10-18 のコード監査）の H1 / M3 / M4 / M5 / M6 / M11\n-- 前方専用。方針: 権限の判定は SQL に置く（CLAUDE.md §7b）。0024 で足した「ショップごとの項目」に、表・列・関数の側を追従させる。\n--\n--  H1  AI 用トークンのスコープは、発行者がその項目を今も持つときだけ有効（発行時のトリガー + 使用時の api_require）\n--  M3  orders は authenticated から status / shipped_at しか更新できず、状態の遷移は paid → shipped だけ（キャンセル・返金は cancel_order）\n--  M4  customers のパスワードのハッシュ等は運営者・スタッフに見せない（列単位の権限）\n--  M5  anon に見せる shops の列を絞り、ストアフロントは shop_public_get / shop_public_list で公開の settings だけを受け取る\n--  M6  shop_payment_options は決済プラグインの表示に要る設定だけ返す\n--  M11 enqueue_hook は管理画面から積めるイベントを項目ごとに限定する\n\n-- ---------- 共通: 任意の利用者の項目を確かめる（banto_shop_perm の auth.uid() を引数にしたもの） ----------\ncreate or replace function banto_user_shop_perm(p_user uuid, p_shop_id uuid, p_perm text)\nreturns boolean language sql stable security definer set search_path = public as $$\n  select exists (\n    select 1 from shops s\n     where s.id = p_shop_id\n       and ((s.org_id is null and s.owner_id = p_user)\n            or (s.org_id is not null and (\n                  exists (select 1 from org_members m where m.org_id = s.org_id and m.user_id = p_user and m.role in ('owner', 'admin'))\n                  or exists (select 1 from org_member_shops ms\n                              where ms.org_id = s.org_id and ms.shop_id = s.id and ms.user_id = p_user and p_perm = any(ms.perms))))));\n$$;\nrevoke execute on function banto_user_shop_perm(uuid, uuid, text) from public, anon, authenticated;\n\n-- ---------- H1: スコープ → 項目 ----------\n-- shop:read は「トークンを発行できる人（integrations）なら誰でも」。それ以外は管理画面と同じ項目を求める。\ncreate or replace function banto_scope_perm(p_scope text)\nreturns text language sql immutable as $$\n  select case p_scope\n    when 'products:read' then 'catalog'\n    when 'products:write' then 'catalog'\n    when 'orders:read' then 'orders'\n    when 'orders:write' then 'orders'\n    when 'orders:pii' then 'customers'\n    when 'shop:read' then 'integrations'\n    when 'shop:write' then 'settings'\n    when 'stats:read' then 'reports'\n  end;\n$$;\nrevoke execute on function banto_scope_perm(text) from public, anon, authenticated;\n\ncreate or replace function banto_token_scope_ok(p_owner_id uuid, p_shop_id uuid, p_scope text)\nreturns boolean language sql stable security definer set search_path = public as $$\n  select banto_scope_perm(p_scope) is not null\n     and banto_user_shop_perm(p_owner_id, p_shop_id, 'integrations')\n     and banto_user_shop_perm(p_owner_id, p_shop_id, banto_scope_perm(p_scope));\n$$;\nrevoke execute on function banto_token_scope_ok(uuid, uuid, text) from public, anon, authenticated;\n\ncreate or replace function banto_token_scopes_ok(p_owner_id uuid, p_shop_id uuid, p_scopes text[])\nreturns boolean language sql stable security definer set search_path = public as $$\n  select banto_user_shop_perm(p_owner_id, p_shop_id, 'integrations')\n     -- 語彙に無いスコープは CHECK（api_tokens_scopes_valid）に任せる\n     and not exists (select 1 from unnest(coalesce(p_scopes, '{}'::text[])) s\n                      where banto_scope_perm(s) is not null and not banto_token_scope_ok(p_owner_id, p_shop_id, s));\n$$;\nrevoke execute on function banto_token_scopes_ok(uuid, uuid, text[]) from public, anon, authenticated;\n\n-- 発行時: 発行者が持たない項目のスコープは付けられない（管理画面も PostgREST 直叩きも同じ）\ncreate or replace function banto_api_tokens_guard()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if not banto_token_scopes_ok(new.owner_id, new.shop_id, new.scopes) then\n    raise exception 'scope_not_permitted' using errcode = '42501';\n  end if;\n  return new;\nend;\n$$;\nrevoke execute on function banto_api_tokens_guard() from public, anon, authenticated;\ndrop trigger if exists api_tokens_guard on api_tokens;\ncreate trigger api_tokens_guard before insert or update of scopes, owner_id, shop_id on api_tokens\n  for each row execute function banto_api_tokens_guard();\n\n-- 使用時: そのスコープに対応する項目を発行者が今も持つときだけ（項目を外したら、そのスコープだけ効かなくなる）\ncreate or replace function api_require(p_token_hash text, p_scope text)\nreturns api_tokens\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'api_require: service_role only' using errcode = '42501';\n  end if;\n  select * into v_tok from api_tokens\n   where token_hash = p_token_hash\n     and revoked_at is null\n     and (expires_at is null or expires_at > now());\n  if not found or not (p_scope = any(v_tok.scopes)) or not banto_token_scope_ok(v_tok.owner_id, v_tok.shop_id, p_scope) then\n    raise exception 'unauthorized' using errcode = '42501';\n  end if;\n  -- 最終利用は1分に1回だけ更新（書き込みを減らす）\n  if v_tok.last_used_at is null or v_tok.last_used_at < now() - interval '1 minute' then\n    update api_tokens set last_used_at = now() where id = v_tok.id;\n  end if;\n  return v_tok;\nend;\n$$;\n\ncreate or replace function api_has_scope(p_token_hash text, p_scope text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select exists (\n    select 1 from api_tokens\n     where token_hash = p_token_hash and revoked_at is null and (expires_at is null or expires_at > now())\n       and p_scope = any(scopes) and banto_token_scope_ok(owner_id, shop_id, p_scope)\n  );\n$$;\n\n-- キャンセル（返金）は管理画面と同じく orders_cancel の項目が要る（orders:write だけでは返金できない）\ncreate or replace function api_order_payment_info(p_token_hash text, p_order_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_r jsonb;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:write');\n  if not banto_user_shop_perm(v_tok.owner_id, v_tok.shop_id, 'orders_cancel') then\n    raise exception 'unauthorized' using errcode = '42501';\n  end if;\n  v_r := order_payment_info(p_order_id, v_tok.shop_id);\n  if v_r is null then raise exception 'not_found'; end if;\n  return v_r;\nend;\n$$;\n\ncreate or replace function api_order_cancel(p_token_hash text, p_order_id uuid, p_refunded boolean)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_r jsonb; v_o orders%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'orders:write');\n  if not banto_user_shop_perm(v_tok.owner_id, v_tok.shop_id, 'orders_cancel') then\n    raise exception 'unauthorized' using errcode = '42501';\n  end if;\n  v_r := cancel_order(p_order_id, v_tok.shop_id, p_refunded);\n  select * into v_o from orders where id = p_order_id;\n  return api_order_json(v_o, 'orders:pii' = any(v_tok.scopes));\nend;\n$$;\n\n-- ---------- M3: orders の直接更新は status / shipped_at だけ、遷移は paid → shipped だけ ----------\n-- キャンセル・返金は cancel_order（service_role、返金の後）、送り状番号は ship_orders（SECURITY DEFINER）を通る。\nrevoke all on orders from anon;\nrevoke update on orders from authenticated;\ngrant update (status, shipped_at) on orders to authenticated;\n\ncreate or replace function banto_orders_guard()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if auth.role() = 'authenticated' and new.status is distinct from old.status\n     and not (old.status = 'paid' and new.status = 'shipped') then\n    raise exception 'use_cancel_order' using errcode = '42501';\n  end if;\n  return new;\nend;\n$$;\nrevoke execute on function banto_orders_guard() from public, anon, authenticated;\ndrop trigger if exists orders_guard on orders;\ncreate trigger orders_guard before update on orders for each row execute function banto_orders_guard();\n\n-- ---------- M4: customers のパスワードのハッシュ・世代は運営者・スタッフに見せない ----------\n-- 会員の読み書きは service_role の member_* RPC（0012）。運営者・customers の項目は一覧（名前・メール・住所）と削除だけ。\nrevoke all on customers from anon;\nrevoke select on customers from authenticated;\ngrant select (id, shop_id, email, name, default_address, created_at, updated_at, last_login_at) on customers to authenticated;\n\n-- ---------- M5: anon に見せる shops の列を絞る ----------\n-- 公開ショップの行は anon だけに（他の組織の運営者にも見せない。管理画面は banto_admin_shop / banto_my_shops で引く）。\n-- settings・stripe_account_id・order_seq・tryon_seq・owner_id・org_id は anon に渡さない。\ndrop policy if exists shops_public on shops;\ncreate policy shops_public on shops for select to anon using (published = true);\nrevoke all on shops from anon;\ngrant select (id, slug, name, published, legal_notice, privacy_policy, return_policy, domain, created_at, updated_at) on shops to anon;\n\n-- ストアフロントに要る settings の鍵だけ（allowlist）。足すときは src/storefront/data.ts の PUBLIC_SETTINGS_KEYS と test/fake-supabase.ts も揃える。\n-- headless は戻り先の許可リストだけ、oauth は提供元ごとの client_id と bot_prompt だけ。\ncreate or replace function banto_shop_public_settings(p jsonb)\nreturns jsonb language sql immutable as $$\n  select coalesce((select jsonb_object_agg(k, v) from jsonb_each(case when jsonb_typeof(p) = 'object' then p else '{}'::jsonb end) e(k, v)\n                    where k in ('theme', 'theme_settings', 'notice', 'shipping', 'modules', 'members_enabled', 'members_password',\n                                'checkout_terms', 'delivery_time', 'store_tryon', 'receipt', 'product_fields',\n                                'tax_rate', 'tax_rate_reduced', 'tax_rounding')), '{}'::jsonb)\n      || case when jsonb_typeof(p->'headless') = 'object'\n              then jsonb_build_object('headless', jsonb_build_object('return_origins', coalesce(p->'headless'->'return_origins', '[]'::jsonb)))\n              else '{}'::jsonb end\n      || case when jsonb_typeof(p->'oauth') = 'object'\n              then jsonb_build_object('oauth', coalesce((\n                     select jsonb_object_agg(k, coalesce((select jsonb_object_agg(k2, v2) from jsonb_each(v) f(k2, v2) where k2 in ('client_id', 'bot_prompt')), '{}'::jsonb))\n                       from jsonb_each(p->'oauth') e(k, v) where jsonb_typeof(v) = 'object'), '{}'::jsonb))\n              else '{}'::jsonb end;\n$$;\nrevoke execute on function banto_shop_public_settings(jsonb) from public, anon, authenticated;\n\ncreate or replace function banto_shop_public_json(s shops)\nreturns jsonb language sql stable as $$\n  select jsonb_build_object(\n    'id', s.id, 'slug', s.slug, 'name', s.name, 'published', s.published,\n    'legal_notice', s.legal_notice, 'privacy_policy', s.privacy_policy, 'return_policy', s.return_policy,\n    'domain', s.domain, 'stripe_connected', s.stripe_account_id is not null,\n    'settings', banto_shop_public_settings(s.settings));\n$$;\nrevoke execute on function banto_shop_public_json(shops) from public, anon, authenticated;\n\n-- スラッグか独自ドメインで公開中のショップを 1 件（無ければ null）\ncreate or replace function shop_public_get(p_slug text default null, p_domain text default null)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select banto_shop_public_json(s) from shops s\n   where s.published\n     and ((p_slug is not null and s.slug = p_slug) or (p_domain is not null and s.domain = p_domain))\n   limit 1;\n$$;\ngrant execute on function shop_public_get(text, text) to anon, authenticated, service_role;\n\ncreate or replace function shop_public_list()\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select coalesce(jsonb_agg(banto_shop_public_json(s) order by s.created_at), '[]'::jsonb) from shops s where s.published;\n$$;\ngrant execute on function shop_public_list() to anon, authenticated, service_role;\n\n-- ---------- M6: 決済プラグインの表示に要る設定だけ（0002 を差し替え） ----------\ncreate or replace function shop_payment_options(p_shop_id uuid)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce(jsonb_agg(jsonb_build_object(\n           'id', substr(e.url, length('https://banto.invalid/plugins/') + 1),\n           'settings', coalesce((select jsonb_object_agg(k, v) from jsonb_each(e.settings) f(k, v) where k in ('payment_types', 'reservation_hours')), '{}'::jsonb))), '[]'::jsonb)\n    from hook_endpoints e\n    join shops s on s.id = e.shop_id\n   where e.shop_id = p_shop_id and e.enabled and s.published\n     and e.url in ('https://banto.invalid/plugins/stripe', 'https://banto.invalid/plugins/komoju');\n$$;\n\n-- ---------- M11: 管理画面から積めるイベントを項目ごとに限定（0024 を差し替え） ----------\n-- catalog → product.updated、orders → order.shipped。それ以外（注文の確定・試着など）は DB の中（service_role）だけが積む。\ncreate or replace function enqueue_hook(p_shop_id uuid, p_event text, p_payload jsonb)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_count integer; v_perm text;\nbegin\n  if p_event is null or p_event !~ '^[a-z_]+\\.[a-z_]+$' then\n    raise exception 'invalid_event';\n  end if;\n  if auth.role() is distinct from 'service_role' then\n    v_perm := case p_event when 'product.updated' then 'catalog' when 'order.shipped' then 'orders' end;\n    if v_perm is null then\n      raise exception 'event_not_permitted' using errcode = '42501';\n    end if;\n    if not banto_shop_perm(p_shop_id, v_perm) then\n      raise exception 'shop_not_found' using errcode = '42501';\n    end if;\n  end if;\n  insert into hook_deliveries (shop_id, endpoint_id, event, payload)\n  select e.shop_id, e.id, p_event, coalesce(p_payload, '{}'::jsonb)\n    from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and p_event = any(e.events);\n  get diagnostics v_count = row_count;\n  return v_count;\nend;\n$$;\n\ninsert into banto_migrations (version) values ('0028_security_hardening');\n" },
  { version: "0029_reservation_limits", sql: "-- Banto 0029_reservation_limits: セキュリティ監査（2026-10-18 のコード監査）の段階 2 のうち DB で閉じる分\n-- 前方専用。\n--\n--  H2  決済せずに在庫を押さえ続けられる → quote は 1 回限り（同じ quote で未確定・確定済みの予約が既にあれば拒む）、\n--      同じ人（メールの HMAC）・同じ IP の未確定の予約の数に上限。お店で試着の申し込みも同じ人・同じ IP で上限\n--  M7  Webhook が支払額・通貨を予約と照合しない → confirm_reservation が照合し、違えば amount_mismatch（Worker が返金して解放）\n--  M8  他人のアドレスのログインを止められる → 発行の枠を「同じ IP からの申込み」と「アドレス全体」に分け、\n--      新しいコードを出しても直近 3 つまでは有効のまま。照合の失敗はアドレスごとに 1 日 50 回まで\n--  M10 ログインのメールがショップ全体で無制限 → ショップ単位の上限（1 時間 100 通・1 日 500 通。settings.members_login_limits で変更）\n\n-- ---------- 予約に quote・申込者・IP を残す ----------\nalter table reservations add column if not exists quote_id text check (quote_id is null or length(quote_id) between 8 and 64);\nalter table reservations add column if not exists subject_hash text check (subject_hash is null or subject_hash ~ '^[0-9a-f]{64}$');\nalter table reservations add column if not exists ip_hash text check (ip_hash is null or ip_hash ~ '^[0-9a-f]{64}$');\n-- 同じ quote から 2 つ目の生きた予約は作れない（解放された後の出し直しは許す）\ncreate unique index if not exists reservations_quote_live on reservations (shop_id, quote_id) where quote_id is not null and status in ('pending', 'confirmed');\ncreate index if not exists reservations_pending_subject on reservations (shop_id, subject_hash) where status = 'pending' and subject_hash is not null;\ncreate index if not exists reservations_pending_ip on reservations (shop_id, ip_hash) where status = 'pending' and ip_hash is not null;\n\nalter table tryon_requests add column if not exists ip_hash text check (ip_hash is null or ip_hash ~ '^[0-9a-f]{64}$');\ncreate index if not exists tryon_requests_open_email on tryon_requests (shop_id, customer_email) where status in ('requested', 'sent', 'ready');\ncreate index if not exists tryon_requests_open_ip on tryon_requests (shop_id, ip_hash) where status in ('requested', 'sent', 'ready') and ip_hash is not null;\n\n-- ショップごとの上限（settings.checkout.max_pending_per_customer / max_pending_per_ip、settings.store_tryon.max_open_per_customer / max_open_per_ip）\ncreate or replace function banto_shop_limit(p_shop_id uuid, p_section text, p_key text, p_default integer)\nreturns integer language sql stable security definer set search_path = public as $$\n  select coalesce(\n    (select case when (s.settings->p_section->>p_key) ~ '^[0-9]{1,4}$' then (s.settings->p_section->>p_key)::integer end from shops s where s.id = p_shop_id),\n    p_default);\n$$;\nrevoke execute on function banto_shop_limit(uuid, text, text, integer) from public, anon, authenticated;\n\n-- ---------- reserve_stock（0001 を差し替え: quote・同じ人・同じ IP の上限） ----------\ndrop function if exists reserve_stock(uuid, jsonb, integer);\ncreate or replace function reserve_stock(p_shop_id uuid, p_items jsonb, p_ttl_seconds integer default 900,\n                                         p_quote_id text default null, p_subject_hash text default null, p_ip_hash text default null)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_item jsonb;\n  v_sku_id uuid;\n  v_qty integer;\n  v_price integer;\n  v_updated integer;\n  v_items jsonb := '[]'::jsonb;\n  v_reservation_id uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'reserve_stock: service_role only' using errcode = '42501';\n  end if;\n  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then\n    raise exception 'empty_items';\n  end if;\n  if p_ttl_seconds is null or p_ttl_seconds <= 0 then\n    raise exception 'invalid_ttl';\n  end if;\n\n  -- 同じ quote で生きた予約があれば拒む（決済ページを開かずに在庫だけ押さえ続けるのを止める）\n  if p_quote_id is not null and exists (select 1 from reservations where shop_id = p_shop_id and quote_id = p_quote_id and status in ('pending', 'confirmed')) then\n    raise exception 'quote_already_used';\n  end if;\n  -- 同じ人・同じ IP の未確定の予約の数（数えてから入れるまでを直列にする）\n  if p_subject_hash is not null then\n    perform pg_advisory_xact_lock(hashtextextended('reservation|' || p_shop_id::text || '|' || p_subject_hash, 0));\n    if (select count(*) from reservations where shop_id = p_shop_id and subject_hash = p_subject_hash and status = 'pending')\n       >= banto_shop_limit(p_shop_id, 'checkout', 'max_pending_per_customer', 3) then\n      raise exception 'too_many_reservations' using detail = 'customer';\n    end if;\n  end if;\n  if p_ip_hash is not null then\n    perform pg_advisory_xact_lock(hashtextextended('reservation-ip|' || p_shop_id::text || '|' || p_ip_hash, 0));\n    if (select count(*) from reservations where shop_id = p_shop_id and ip_hash = p_ip_hash and status = 'pending')\n       >= banto_shop_limit(p_shop_id, 'checkout', 'max_pending_per_ip', 20) then\n      raise exception 'too_many_reservations' using detail = 'ip';\n    end if;\n  end if;\n\n  -- sku_id 順に処理し、複数予約が同じ SKU 群を逆順でロックしてデッドロックするのを防ぐ\n  for v_item in select e from jsonb_array_elements(p_items) e order by e->>'sku_id' loop\n    v_sku_id := (v_item->>'sku_id')::uuid;\n    v_qty := (v_item->>'qty')::integer;\n    if v_sku_id is null or v_qty is null or v_qty <= 0 then\n      raise exception 'invalid_item' using detail = coalesce(v_item::text, 'null');\n    end if;\n\n    select k.price_jpy into v_price\n      from skus k\n      join products p on p.id = k.product_id\n      join shops s on s.id = k.shop_id\n     where k.id = v_sku_id and k.shop_id = p_shop_id and p.published and s.published;\n    if not found then\n      raise exception 'sku_not_available' using detail = v_sku_id::text;\n    end if;\n\n    update inventory\n       set available = available - v_qty, updated_at = now()\n     where sku_id = v_sku_id and shop_id = p_shop_id and available >= v_qty;\n    get diagnostics v_updated = row_count;\n    if v_updated = 0 then\n      raise exception 'insufficient_stock' using detail = v_sku_id::text;\n    end if;\n\n    v_items := v_items || jsonb_build_object('sku_id', v_sku_id, 'qty', v_qty, 'unit_price_jpy', v_price);\n  end loop;\n\n  insert into reservations (shop_id, items, expires_at, quote_id, subject_hash, ip_hash)\n  values (p_shop_id, v_items, now() + make_interval(secs => p_ttl_seconds), p_quote_id, p_subject_hash, p_ip_hash)\n  returning id into v_reservation_id;\n\n  return v_reservation_id;\nend;\n$$;\nrevoke execute on function reserve_stock(uuid, jsonb, integer, text, text, text) from public, anon, authenticated;\ngrant execute on function reserve_stock(uuid, jsonb, integer, text, text, text) to service_role;\n\n-- ---------- confirm_reservation（0010 を差し替え: 支払額・通貨の照合） ----------\ncreate or replace function confirm_reservation(p_reservation_id uuid, p_shop_id uuid, p_order jsonb default '{}'::jsonb)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_res reservations%rowtype;\n  v_order_id uuid;\n  v_item jsonb;\n  v_updated integer;\n  v_subtotal integer;\n  v_total integer;\n  v_number integer;\n  v_threshold integer;\n  v_available integer;\n  v_payload jsonb;\n  v_r record;\n  v_slot bigint;\n  v_paid integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'confirm_reservation: service_role only' using errcode = '42501';\n  end if;\n\n  select * into v_res from reservations\n   where id = p_reservation_id and shop_id = p_shop_id\n   for update;\n  if not found then\n    raise exception 'reservation_not_found' using detail = p_reservation_id::text;\n  end if;\n\n  select id into v_order_id from orders where reservation_id = p_reservation_id;\n  if found then\n    return v_order_id;\n  end if;\n\n  -- 決済事業者が受け取った額・通貨が Banto の計算と違えば確定しない（在庫は動かさない。Worker が返金して解放する）\n  select coalesce(sum((e->>'qty')::integer * (e->>'unit_price_jpy')::integer), 0)\n    into v_subtotal\n    from jsonb_array_elements(v_res.items) e;\n  v_total := greatest(0, v_subtotal + v_res.shipping_jpy - v_res.discount_jpy);\n  v_paid := case when (p_order->>'amount_paid_jpy') ~ '^-?[0-9]{1,9}$' then (p_order->>'amount_paid_jpy')::integer end;\n  if v_paid is not null and v_paid <> v_total then\n    raise exception 'amount_mismatch' using detail = format('paid=%s expected=%s', v_paid, v_total);\n  end if;\n  if coalesce(p_order->>'currency', 'jpy') !~* '^jpy$' then\n    raise exception 'amount_mismatch' using detail = format('currency=%s', p_order->>'currency');\n  end if;\n\n  if v_res.status = 'released' then\n    for v_item in select e from jsonb_array_elements(v_res.items) e order by e->>'sku_id' loop\n      update inventory\n         set available = available - (v_item->>'qty')::integer, updated_at = now()\n       where sku_id = (v_item->>'sku_id')::uuid and shop_id = p_shop_id\n         and available >= (v_item->>'qty')::integer;\n      get diagnostics v_updated = row_count;\n      if v_updated = 0 then\n        raise exception 'insufficient_stock_after_release' using detail = v_item->>'sku_id';\n      end if;\n    end loop;\n    for v_r in select id, campaign_id from coupon_redemptions where reservation_id = p_reservation_id and status = 'released' loop\n      update coupon_slots set status = 'held', reservation_id = p_reservation_id\n       where id = (select id from coupon_slots where campaign_id = v_r.campaign_id and status = 'free' limit 1 for update skip locked)\n      returning id into v_slot;\n      update coupon_redemptions set status = 'held', slot_id = v_slot where id = v_r.id;\n    end loop;\n  end if;\n\n  update shops set order_seq = order_seq + 1 where id = p_shop_id returning order_seq into v_number;\n\n  insert into orders (shop_id, reservation_id, status, total_jpy, shipping_jpy, discount_jpy, discounts, amount_paid_jpy, number, customer_id,\n                      customer_email, customer_name, shipping_address, payment_provider, payment_ref)\n  values (p_shop_id, p_reservation_id, 'paid', v_total, v_res.shipping_jpy, v_res.discount_jpy, v_res.discounts,\n          v_paid, v_number, v_res.customer_id,\n          coalesce(v_res.customer->>'customer_email', p_order->>'customer_email'),\n          coalesce(v_res.customer->>'customer_name', p_order->>'customer_name'),\n          coalesce(v_res.customer->'shipping_address', p_order->'shipping_address'),\n          p_order->>'payment_provider', p_order->>'payment_ref')\n  returning id into v_order_id;\n\n  insert into order_items (shop_id, order_id, sku_id, qty, unit_price_jpy, discount_jpy)\n  select p_shop_id, v_order_id, (e->>'sku_id')::uuid, (e->>'qty')::integer, (e->>'unit_price_jpy')::integer, coalesce((e->>'discount_jpy')::integer, 0)\n    from jsonb_array_elements(v_res.items) e;\n\n  update coupon_slots set status = 'used' where reservation_id = p_reservation_id and status = 'held';\n  update coupon_redemptions set status = 'used', order_id = v_order_id where reservation_id = p_reservation_id and status = 'held';\n  update reservations set status = 'confirmed', customer = null where id = p_reservation_id;\n\n  v_payload := jsonb_build_object(\n    'order_id', v_order_id, 'order_number', v_number, 'shop_id', p_shop_id,\n    'subtotal_jpy', v_subtotal, 'shipping_jpy', v_res.shipping_jpy, 'discount_jpy', v_res.discount_jpy, 'total_jpy', v_total,\n    'status', 'paid', 'payment_provider', p_order->>'payment_provider', 'customer_id', v_res.customer_id,\n    'items', v_res.items\n  );\n  perform enqueue_hook(p_shop_id, 'order.created', v_payload);\n  perform enqueue_hook(p_shop_id, 'order.paid', v_payload);\n\n  select coalesce((s.settings->>'low_stock_threshold')::integer, 3) into v_threshold from shops s where s.id = p_shop_id;\n  for v_item in select e from jsonb_array_elements(v_res.items) e loop\n    select available into v_available from inventory where sku_id = (v_item->>'sku_id')::uuid;\n    if v_available is not null and v_available <= v_threshold then\n      perform enqueue_hook(p_shop_id, 'inventory.low',\n        jsonb_build_object('shop_id', p_shop_id, 'sku_id', v_item->>'sku_id', 'available', v_available, 'threshold', v_threshold));\n    end if;\n  end loop;\n\n  return v_order_id;\nend;\n$$;\n\n-- ---------- tryon_request（0025 を差し替え: 同じ人・同じ IP の開いている申し込みの上限。IP は p_customer.ip_hash で受ける） ----------\ncreate or replace function tryon_request(p_shop_id uuid, p_store_id uuid, p_items jsonb, p_customer jsonb, p_visit_date date default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_it jsonb; v_sku skus%rowtype; v_qty integer; v_n integer; v_id uuid; v_number integer; v_cid uuid; v_total integer := 0;\n  v_email text; v_ip text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'tryon_request: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id and published) then raise exception 'shop_not_found'; end if;\n  if not exists (select 1 from shop_stores ss join stores st on st.id = ss.store_id where ss.shop_id = p_shop_id and ss.store_id = p_store_id and ss.tryon and st.active) then\n    raise exception 'store_not_available';\n  end if;\n  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > 20 then raise exception 'invalid_items'; end if;\n  if position('@' in coalesce(p_customer->>'customer_email', '')) < 2 then raise exception 'invalid_customer'; end if;\n  v_email := lower(btrim(p_customer->>'customer_email'));\n  v_ip := case when (p_customer->>'ip_hash') ~ '^[0-9a-f]{64}$' then p_customer->>'ip_hash' end;\n  v_cid := nullif(p_customer->>'customer_id', '')::uuid;\n  if v_cid is not null and not exists (select 1 from customers where shop_id = p_shop_id and id = v_cid) then v_cid := null; end if;\n\n  perform pg_advisory_xact_lock(hashtextextended('tryon|' || p_shop_id::text || '|' || v_email, 0));\n  if (select count(*) from tryon_requests where shop_id = p_shop_id and customer_email = v_email and status in ('requested', 'sent', 'ready'))\n     >= banto_shop_limit(p_shop_id, 'store_tryon', 'max_open_per_customer', 3) then\n    raise exception 'too_many_requests' using detail = 'customer';\n  end if;\n  if v_ip is not null and (select count(*) from tryon_requests where shop_id = p_shop_id and ip_hash = v_ip and status in ('requested', 'sent', 'ready'))\n     >= banto_shop_limit(p_shop_id, 'store_tryon', 'max_open_per_ip', 10) then\n    raise exception 'too_many_requests' using detail = 'ip';\n  end if;\n\n  update shops set tryon_seq = tryon_seq + 1 where id = p_shop_id returning tryon_seq into v_number;\n  insert into tryon_requests (shop_id, store_id, number, visit_date, customer_id, customer_email, customer_name, customer_phone, note, ip_hash)\n  values (p_shop_id, p_store_id, v_number, p_visit_date, v_cid, v_email,\n          left(nullif(btrim(coalesce(p_customer->>'customer_name', '')), ''), 100), left(nullif(btrim(coalesce(p_customer->>'customer_phone', '')), ''), 20),\n          left(nullif(btrim(coalesce(p_customer->>'note', '')), ''), 500), v_ip)\n  returning id into v_id;\n\n  for v_it in select e from jsonb_array_elements(p_items) e loop\n    v_qty := case when coalesce(v_it->>'qty', '') ~ '^[0-9]{1,2}$' then (v_it->>'qty')::integer else 0 end;\n    if v_qty <= 0 then raise exception 'invalid_items'; end if;\n    select k.* into v_sku from skus k join products p on p.id = k.product_id\n     where k.id = nullif(v_it->>'sku_id', '')::uuid and k.shop_id = p_shop_id and p.published;\n    if not found then raise exception 'sku_not_available'; end if;\n    update inventory set available = available - v_qty where sku_id = v_sku.id and shop_id = p_shop_id and available >= v_qty;\n    get diagnostics v_n = row_count;\n    if v_n = 0 then raise exception 'insufficient_stock' using detail = v_sku.id::text; end if;\n    insert into tryon_items (shop_id, request_id, sku_id, qty, unit_price_jpy) values (p_shop_id, v_id, v_sku.id, v_qty, v_sku.price_jpy);\n    v_total := v_total + v_qty;\n  end loop;\n  if v_total > 20 then raise exception 'invalid_items'; end if;\n  perform banto_enqueue_tryon_hook(p_shop_id, 'tryon.requested',\n    jsonb_build_object('request_id', v_id, 'number', v_number, 'shop_id', p_shop_id, 'store_id', p_store_id, 'status', 'requested',\n                       'visit_date', p_visit_date, 'customer_id', v_cid));\n  return jsonb_build_object('id', v_id, 'number', v_number);\nend;\n$$;\n\n-- ---------- member_login_start（0012 を差し替え: 枠の分離・ショップ単位の上限・直近 3 つまで有効） ----------\ncreate or replace function member_login_start(p_shop_id uuid, p_email text, p_code_hash text, p_link_hash text, p_ip_hash text, p_return_to text, p_ttl_seconds integer default 900)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_email text := lower(btrim(coalesce(p_email, '')));\n  v_from text;\n  v_id uuid;\n  v_limited boolean := false;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_login_start: service_role only' using errcode = '42501';\n  end if;\n  if length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  if not exists (select 1 from shops where id = p_shop_id and coalesce(settings->>'members_enabled', 'false') = 'true') then\n    raise exception 'members_disabled';\n  end if;\n  select nullif(btrim(e.settings->>'from'), '') into v_from\n    from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and e.url = 'https://banto.invalid/plugins/email_resend'\n   limit 1;\n  if v_from is null then raise exception 'mail_not_configured'; end if;\n\n  perform pg_advisory_xact_lock(hashtextextended('member_login|' || p_shop_id::text || '|' || v_email, 0));\n  if p_ip_hash is not null then\n    -- 同じ IP から同じアドレスへ: 15 分に 3 回・1 日 10 回（他人が被害者の枠を使い切れないように、IP ごとに分ける）\n    v_limited := (select count(*) from member_login_challenges where shop_id = p_shop_id and email = v_email and ip_hash = p_ip_hash and created_at > now() - interval '15 minutes') >= 3\n              or (select count(*) from member_login_challenges where shop_id = p_shop_id and email = v_email and ip_hash = p_ip_hash and created_at > now() - interval '1 day') >= 10\n              -- 同じ IP から誰へでも: 1 時間に 30 回\n              or (select count(*) from member_login_challenges where shop_id = p_shop_id and ip_hash = p_ip_hash and created_at > now() - interval '1 hour') >= 30;\n  else\n    -- IP が分からない（Node でヘッダー未設定）: アドレスだけで数える\n    v_limited := (select count(*) from member_login_challenges where shop_id = p_shop_id and email = v_email and created_at > now() - interval '15 minutes') >= 5;\n  end if;\n  -- アドレス全体: 1 日 30 通（メール爆撃の上限）。ショップ全体: 1 時間・1 日の上限（送信元の評判と Resend の枠を守る）\n  v_limited := v_limited\n    or (select count(*) from member_login_challenges where shop_id = p_shop_id and email = v_email and created_at > now() - interval '1 day') >= 30\n    or (select count(*) from member_login_challenges where shop_id = p_shop_id and created_at > now() - interval '1 hour')\n       >= banto_shop_limit(p_shop_id, 'members_login_limits', 'per_hour', 100)\n    or (select count(*) from member_login_challenges where shop_id = p_shop_id and created_at > now() - interval '1 day')\n       >= banto_shop_limit(p_shop_id, 'members_login_limits', 'per_day', 500);\n  if v_limited then\n    return jsonb_build_object('send', false, 'challenge_id', gen_random_uuid(), 'mail_from', v_from);\n  end if;\n\n  -- 直近 3 つまで有効（新しいコードを出しても、届いたばかりの前のコードが無効にならない）。それより古いものは無効にする\n  update member_login_challenges set consumed_at = now()\n   where shop_id = p_shop_id and email = v_email and consumed_at is null\n     and id not in (select id from member_login_challenges where shop_id = p_shop_id and email = v_email and consumed_at is null order by created_at desc limit 2);\n  insert into member_login_challenges (shop_id, email, code_hash, link_hash, ip_hash, return_to, expires_at)\n  values (p_shop_id, v_email, p_code_hash, p_link_hash, p_ip_hash, nullif(left(p_return_to, 500), ''),\n          now() + make_interval(secs => greatest(60, least(coalesce(p_ttl_seconds, 900), 3600))))\n  returning id into v_id;\n  return jsonb_build_object('send', true, 'challenge_id', v_id, 'mail_from', v_from);\nend;\n$$;\n\n-- 全体で 1 日の照合の失敗がアドレスごとに 50 回を超えたら、どのチャレンジも通らない（有効なチャレンジが 3 つになった分の歯止め）\ncreate index if not exists member_login_challenges_email_day on member_login_challenges (shop_id, email, created_at) include (attempts);\n\ncreate or replace function member_login_verify(p_shop_id uuid, p_challenge_id uuid, p_code_hash text, p_link_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_ch member_login_challenges%rowtype;\n  v_customer customers%rowtype;\n  v_created boolean := false;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_login_verify: service_role only' using errcode = '42501';\n  end if;\n  select * into v_ch from member_login_challenges where id = p_challenge_id and shop_id = p_shop_id for update;\n  if not found then return jsonb_build_object('ok', false, 'reason', 'invalid'); end if;\n  if v_ch.consumed_at is not null or v_ch.expires_at < now() or v_ch.attempts >= 5 then\n    return jsonb_build_object('ok', false, 'reason', 'expired');\n  end if;\n  if (select coalesce(sum(attempts), 0) from member_login_challenges where shop_id = p_shop_id and email = v_ch.email and created_at > now() - interval '1 day') >= 50 then\n    return jsonb_build_object('ok', false, 'reason', 'expired');\n  end if;\n  if not ((p_code_hash is not null and v_ch.code_hash = p_code_hash) or (p_link_hash is not null and v_ch.link_hash = p_link_hash)) then\n    update member_login_challenges\n       set attempts = attempts + 1,\n           consumed_at = case when attempts + 1 >= 5 then now() else consumed_at end\n     where id = v_ch.id;\n    return jsonb_build_object('ok', false, 'reason', case when v_ch.attempts + 1 >= 5 then 'expired' else 'invalid' end);\n  end if;\n  update member_login_challenges set consumed_at = now() where id = v_ch.id;\n  if not exists (select 1 from shops where id = p_shop_id and coalesce(settings->>'members_enabled', 'false') = 'true') then\n    return jsonb_build_object('ok', false, 'reason', 'expired');\n  end if;\n\n  select * into v_customer from customers where shop_id = p_shop_id and lower(email) = v_ch.email;\n  if not found then\n    insert into customers (shop_id, email) values (p_shop_id, v_ch.email)\n    on conflict (shop_id, lower(email)) where email is not null do nothing\n    returning * into v_customer;\n    if v_customer.id is null then\n      select * into v_customer from customers where shop_id = p_shop_id and lower(email) = v_ch.email;\n    else\n      v_created := true;\n    end if;\n  end if;\n  update customers set last_login_at = now() where shop_id = p_shop_id and id = v_customer.id;\n  return jsonb_build_object('ok', true, 'customer_id', v_customer.id, 'session_epoch', v_customer.session_epoch,\n                            'email', v_customer.email, 'created', v_created, 'return_to', v_ch.return_to);\nend;\n$$;\n\ninsert into banto_migrations (version) values ('0029_reservation_limits');\n" },
  { version: "0030_admin_sessions", sql: "-- Banto 0030_admin_sessions: セキュリティ監査（2026-10-18 のコード監査）の段階 3（運営者側の入口）\n-- 前方専用。\n--\n--  M1  最初の運営者の Auth ユーザーを消すと owners が空になり、セットアップの運営者登録が匿名に再び開く\n--      → 「運営者がいない」は owners・org_members・shops のどれも空のときだけ（RLS のゲートと setup_state の両方）\n--  M2  管理者ログインに Banto 側の回数制限が無い → admin_login_attempts に失敗を記録し、計算（Supabase への問い合わせ）の前に判定する\n--  M13 ログアウトしても Cookie が 1 時間有効・全端末からログアウトできない → 運営者ごとの世代（admin_users.session_epoch）。\n--      Cookie に世代を入れ、毎リクエストの運営者の確認（banto_admin_me）で照合する。ログアウトで世代を上げる（全端末が切れる）\n\n-- ---------- M1 ----------\n-- 最初の運営者の Auth ユーザーを消すと、owners の行が消え（cascade）、0001 では shops.owner_id の外部キーも cascade だったので\n-- その人のショップと注文・商品までまとめて消えていた。ショップは組織のもの（0024）なので、owner_id を空にするだけにする\nalter table shops drop constraint if exists shops_owner_id_fkey;\nalter table shops add constraint shops_owner_id_fkey foreign key (owner_id) references owners(id) on delete set null;\n\ncreate or replace function banto_owner_signup_allowed()\nreturns boolean language sql stable security definer set search_path = public as $$\n  select not exists (select 1 from owners) and not exists (select 1 from org_members) and not exists (select 1 from shops);\n$$;\n\ncreate or replace function banto_setup_state()\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'has_owner', exists (select 1 from owners) or exists (select 1 from org_members) or exists (select 1 from shops),\n    'shop_count', (select count(*) from shops),\n    'migrations', (select coalesce(jsonb_agg(version order by version), '[]'::jsonb) from banto_migrations)\n  );\n$$;\n\n-- ---------- M13: 運営者のセッションの世代 ----------\ncreate table if not exists admin_users (\n  user_id uuid primary key references auth.users(id) on delete cascade,\n  session_epoch integer not null default 0,\n  updated_at timestamptz not null default now()\n);\nalter table admin_users enable row level security;\n-- 表は誰にも見せない（関数からだけ触る）\ncreate policy admin_users_none on admin_users for select using (false);\n\n-- 毎リクエストの確認: どこかの組織のメンバーか、その人の世代。メンバーでなければ { member: false }\ncreate or replace function banto_admin_me()\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_epoch integer;\nbegin\n  if auth.uid() is null then return jsonb_build_object('member', false); end if;\n  if not exists (select 1 from org_members where user_id = auth.uid()) then return jsonb_build_object('member', false); end if;\n  select session_epoch into v_epoch from admin_users where user_id = auth.uid();\n  if not found then\n    insert into admin_users (user_id) values (auth.uid()) on conflict (user_id) do nothing;\n    v_epoch := 0;\n  end if;\n  return jsonb_build_object('member', true, 'epoch', v_epoch);\nend;\n$$;\nrevoke execute on function banto_admin_me() from public, anon;\ngrant execute on function banto_admin_me() to authenticated;\n\n-- ログアウト（全端末）・パスワードの変更のとき: 世代を上げる。戻り値は新しい世代\ncreate or replace function admin_session_bump()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_epoch integer;\nbegin\n  if auth.uid() is null then raise exception 'unauthorized' using errcode = '42501'; end if;\n  insert into admin_users (user_id, session_epoch, updated_at) values (auth.uid(), 1, now())\n  on conflict (user_id) do update set session_epoch = admin_users.session_epoch + 1, updated_at = now()\n  returning session_epoch into v_epoch;\n  return v_epoch;\nend;\n$$;\nrevoke execute on function admin_session_bump() from public, anon;\ngrant execute on function admin_session_bump() to authenticated;\n\n-- ---------- M2: 管理者ログインの回数の制限 ----------\n-- メールアドレス・IP は Worker が HMAC（サイトの秘密）にしてから渡す（会員のログインと同じ）。\ncreate table if not exists admin_login_attempts (\n  id bigserial primary key,\n  email_hash text not null check (email_hash ~ '^[0-9a-f]{64}$'),\n  ip_hash text check (ip_hash is null or ip_hash ~ '^[0-9a-f]{64}$'),\n  success boolean not null default false,\n  created_at timestamptz not null default now()\n);\ncreate index if not exists admin_login_attempts_email on admin_login_attempts (email_hash, created_at);\ncreate index if not exists admin_login_attempts_ip on admin_login_attempts (ip_hash, created_at) where ip_hash is not null;\nalter table admin_login_attempts enable row level security;\ncreate policy admin_login_attempts_none on admin_login_attempts for select using (false);\n\n-- 同じアドレスは 15 分に 5 回、同じ IP は 15 分に 20 回まで失敗できる。超えていれば allowed=false（Supabase には問い合わせない）\ncreate or replace function admin_login_check(p_email_hash text, p_ip_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_email integer; v_ip integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'admin_login_check: service_role only' using errcode = '42501';\n  end if;\n  select count(*) into v_email from admin_login_attempts where email_hash = p_email_hash and not success and created_at > now() - interval '15 minutes';\n  if p_ip_hash is not null then\n    select count(*) into v_ip from admin_login_attempts where ip_hash = p_ip_hash and not success and created_at > now() - interval '15 minutes';\n  end if;\n  return jsonb_build_object('allowed', v_email < 5 and v_ip < 20, 'retry_after_seconds', 900);\nend;\n$$;\nrevoke execute on function admin_login_check(text, text) from public, anon, authenticated;\ngrant execute on function admin_login_check(text, text) to service_role;\n\n-- 結果を記録する。成功したらそのアドレスの失敗を消す（本人が入れたのだから鍵を開ける）。1 日より古い行は捨てる\ncreate or replace function admin_login_record(p_email_hash text, p_ip_hash text, p_success boolean)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'admin_login_record: service_role only' using errcode = '42501';\n  end if;\n  delete from admin_login_attempts where created_at < now() - interval '1 day';\n  if p_success then\n    delete from admin_login_attempts where email_hash = p_email_hash and not success;\n  end if;\n  insert into admin_login_attempts (email_hash, ip_hash, success) values (p_email_hash, p_ip_hash, coalesce(p_success, false));\nend;\n$$;\nrevoke execute on function admin_login_record(text, text, boolean) from public, anon, authenticated;\ngrant execute on function admin_login_record(text, text, boolean) to service_role;\n\ninsert into banto_migrations (version) values ('0030_admin_sessions');\n" },
  { version: "0031_low_fixes", sql: "-- Banto 0031_low_fixes: セキュリティ監査（2026-10-18 のコード監査）§3 の Low のうち、v0.1.0 の前に直す分（人間の決定 2026-10-18「A を進める」）\n-- 前方専用。\n--\n--  - cancel_order: WooCommerce から取り込んだ注文・復元した注文（予約が無い）をキャンセルしても在庫を戻さない（実際には動いていない在庫が増えていた）\n--  - mask_shipped_orders: 発送済みだけでなく、キャンセル・返金済みの注文も同じ日数で個人情報を消す（180 日の約束を状態で欠かさない）\n--  - mask_customer: 注文だけでなく、お店で試着の申し込みの氏名・電話・メモも消す（削除依頼の対応）\n--  - shops: settings の項目のメンバーは slug / domain / order_seq / tryon_seq を変えられない（注文番号の巻き戻し・ドメインの付け替えは owner / admin だけ）\n--  - member_set_email: 会員のメールアドレスの変更（= ログインの乗っ取りの入口）は組織の owner / admin だけ（0012 の形に戻す）\n--  - hook_endpoints: 同梱プラグインの行（https://banto.invalid/plugins/<id>）はショップごとに 1 つ（重複すると注文メール・LINE 通知が二重に届く）\n\n-- ---------- cancel_order（0010 を差し替え） ----------\ncreate or replace function cancel_order(p_order_id uuid, p_shop_id uuid, p_refunded boolean)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_o orders%rowtype; v_item record; v_restock boolean;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'cancel_order: service_role only' using errcode = '42501';\n  end if;\n  select * into v_o from orders where id = p_order_id and shop_id = p_shop_id for update;\n  if not found then raise exception 'not_found'; end if;\n  if v_o.status in ('cancelled', 'refunded') then\n    return jsonb_build_object('order_id', v_o.id, 'status', v_o.status, 'already', true);\n  end if;\n  if v_o.status <> 'paid' then raise exception 'not_cancellable' using detail = v_o.status::text; end if;\n  -- 在庫を戻すのは Banto で予約して確定した注文だけ。取り込んだ注文（external_ref）と復元した注文（予約なし）は在庫を動かしていない\n  v_restock := v_o.reservation_id is not null and v_o.external_ref is null;\n  if v_restock then\n    for v_item in select sku_id, qty from order_items where order_id = p_order_id and sku_id is not null loop\n      update inventory set available = available + v_item.qty, updated_at = now()\n       where sku_id = v_item.sku_id and shop_id = p_shop_id;\n    end loop;\n    perform banto_release_coupons(v_o.reservation_id);\n  end if;\n  update orders set status = case when p_refunded then 'refunded'::order_status else 'cancelled'::order_status end\n   where id = p_order_id;\n  perform enqueue_hook(p_shop_id, 'order.cancelled',\n    jsonb_build_object('order_id', v_o.id, 'order_number', v_o.number, 'shop_id', p_shop_id, 'total_jpy', v_o.total_jpy,\n                       'status', case when p_refunded then 'refunded' else 'cancelled' end, 'refunded', p_refunded, 'customer_id', v_o.customer_id,\n                       'restocked', v_restock));\n  return jsonb_build_object('order_id', v_o.id, 'status', case when p_refunded then 'refunded' else 'cancelled' end, 'already', false,\n                            'restocked', v_restock, 'payment_provider', v_o.payment_provider, 'payment_ref', v_o.payment_ref);\nend;\n$$;\n\n-- ---------- mask_shipped_orders（0001 を差し替え: キャンセル・返金済みも） ----------\ncreate or replace function mask_shipped_orders(p_days integer default 180)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_count integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'mask_shipped_orders: service_role only' using errcode = '42501';\n  end if;\n  update orders\n     set customer_email = null, customer_name = '[masked]', shipping_address = null\n   where ((status = 'shipped' and shipped_at < now() - make_interval(days => p_days))\n          or (status in ('cancelled', 'refunded') and updated_at < now() - make_interval(days => p_days)))\n     and (customer_name is distinct from '[masked]' or customer_email is not null or shipping_address is not null);\n  get diagnostics v_count = row_count;\n  return v_count;\nend;\n$$;\n\n-- ---------- mask_customer（0024 を差し替え: 試着の申し込みも） ----------\ncreate or replace function mask_customer(p_shop_id uuid, p_email text)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_count integer; v_tryon integer;\nbegin\n  if not banto_shop_perm(p_shop_id, 'customers') then\n    raise exception 'shop_not_found' using errcode = '42501';\n  end if;\n  update orders\n     set customer_email = null, customer_name = '[masked]', shipping_address = null\n   where shop_id = p_shop_id and lower(customer_email) = lower(btrim(p_email));\n  get diagnostics v_count = row_count;\n  update tryon_requests\n     set customer_email = null, customer_name = '[masked]', customer_phone = null, note = null\n   where shop_id = p_shop_id and lower(customer_email) = lower(btrim(p_email));\n  get diagnostics v_tryon = row_count;\n  return v_count + v_tryon;\nend;\n$$;\n\n-- ---------- shops: 識別と連番は owner / admin だけ（0024 の banto_shops_guard を差し替え） ----------\ncreate or replace function banto_shops_guard()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if tg_op = 'INSERT' then\n    if new.org_id is null and auth.uid() is not null then\n      select m.org_id into new.org_id from org_members m join organizations o on o.id = m.org_id\n       where m.user_id = auth.uid() and m.role in ('owner', 'admin') order by o.created_at limit 1;\n    end if;\n    if new.owner_id is not null and not exists (select 1 from owners where id = new.owner_id) then new.owner_id := null; end if;\n    return new;\n  end if;\n  if auth.role() = 'authenticated' then\n    if new.org_id is distinct from old.org_id and old.org_id is not null then raise exception 'org_immutable' using errcode = '42501'; end if;\n    if new.owner_id is distinct from old.owner_id then raise exception 'owner_immutable' using errcode = '42501'; end if;\n    if new.stripe_account_id is distinct from old.stripe_account_id and not banto_shop_perm(old.id, 'integrations') then\n      raise exception 'integrations_required' using errcode = '42501';\n    end if;\n    -- スラッグ・独自ドメイン・注文番号と試着の連番は、settings の項目では変えられない（0031）\n    if (new.slug is distinct from old.slug or new.domain is distinct from old.domain\n        or new.order_seq is distinct from old.order_seq or new.tryon_seq is distinct from old.tryon_seq)\n       and not banto_owns_shop(old.id) then\n      raise exception 'admin_required' using errcode = '42501';\n    end if;\n  end if;\n  return new;\nend;\n$$;\n\n-- ---------- member_set_email（0024 を差し替え: owner / admin だけ） ----------\ncreate or replace function member_set_email(p_shop_id uuid, p_customer_id uuid, p_email text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_email text := lower(btrim(coalesce(p_email, '')));\n  v_old text;\nbegin\n  -- 会員のアドレスを書き換えられる人は、その会員としてログインできる。customers の項目ではなく組織の owner / admin に限る（0031）\n  if not banto_owns_shop(p_shop_id) then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  select email into v_old from customers where shop_id = p_shop_id and id = p_customer_id for update;\n  if not found then raise exception 'customer_not_found'; end if;\n  if exists (select 1 from customers where shop_id = p_shop_id and lower(email) = v_email and id <> p_customer_id) then\n    raise exception 'email_taken';\n  end if;\n  update customers set email = v_email, session_epoch = session_epoch + 1 where shop_id = p_shop_id and id = p_customer_id;\n  update member_login_challenges set consumed_at = now()\n   where shop_id = p_shop_id and email in (lower(coalesce(v_old, '')), v_email) and consumed_at is null;\n  return jsonb_build_object('old_email', v_old, 'new_email', v_email);\nend;\n$$;\n\n-- ---------- hook_endpoints: 同梱プラグインの行はショップごとに 1 つ ----------\n-- 既にある重複は、いちばん古い行を残して消す（配信の履歴は endpoint_id の cascade で一緒に消える）\ndelete from hook_endpoints e\n using hook_endpoints d\n where e.url like 'https://banto.invalid/plugins/%' and d.shop_id = e.shop_id and d.url = e.url and d.created_at < e.created_at;\ncreate unique index if not exists hook_endpoints_bundled_unique on hook_endpoints (shop_id, url) where url like 'https://banto.invalid/plugins/%';\n\ninsert into banto_migrations (version) values ('0031_low_fixes');\n" },
  { version: "0032_api_checkout_terms", sql: "-- Banto 0032_api_checkout_terms: 購入前の確認画面の文言（shops.settings.checkout_terms）を AI 用トークンで読み書きする\n-- 前方専用。WordPress 等の連携側の管理画面から、Banto の表示を Banto に置いたまま編集するため（docs/api.md「ショップ」）。\n--\n--  - api_shop_get: checkout_terms（delivery / cancellation / payment_note。未設定は null）を返す\n--  - api_shop_update: checkout_terms を受け付ける。渡した鍵だけ変え、null か空文字で消す。1 項目 2000 文字まで（管理画面と同じ）\n--    settings 全体は今までどおり触らせない（受け付けるのはこの 3 つの鍵だけ）\n\ncreate or replace function api_shop_get(p_token_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_shop shops%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'shop:read');\n  select * into v_shop from shops where id = v_tok.shop_id;\n  return jsonb_build_object(\n    'id', v_shop.id, 'slug', v_shop.slug, 'name', v_shop.name, 'published', v_shop.published,\n    'legal_notice', v_shop.legal_notice, 'privacy_policy', v_shop.privacy_policy, 'return_policy', v_shop.return_policy,\n    'checkout_terms', jsonb_build_object(\n      'delivery', nullif(btrim(v_shop.settings->'checkout_terms'->>'delivery'), ''),\n      'cancellation', nullif(btrim(v_shop.settings->'checkout_terms'->>'cancellation'), ''),\n      'payment_note', nullif(btrim(v_shop.settings->'checkout_terms'->>'payment_note'), '')),\n    'low_stock_threshold', coalesce((v_shop.settings->>'low_stock_threshold')::integer, 3),\n    'stripe_connected', v_shop.stripe_account_id is not null,\n    'created_at', v_shop.created_at, 'updated_at', v_shop.updated_at);\nend;\n$$;\n\n-- 更新できる項目だけを受け付ける（settings 全体や stripe_account_id は触らせない）\ncreate or replace function api_shop_update(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_tok api_tokens;\n  v_threshold integer;\n  v_patch jsonb := '{}'::jsonb;\n  v_in jsonb;\n  v_terms jsonb;\n  v_key text;\n  v_val text;\nbegin\n  v_tok := api_require(p_token_hash, 'shop:write');\n  if p_values ? 'low_stock_threshold' then\n    v_threshold := (p_values->>'low_stock_threshold')::integer;\n    if v_threshold is null or v_threshold < 0 or v_threshold > 100000 then raise exception 'invalid_low_stock_threshold'; end if;\n    v_patch := v_patch || jsonb_build_object('low_stock_threshold', v_threshold);\n  end if;\n  if p_values ? 'checkout_terms' then\n    v_in := p_values->'checkout_terms';\n    if jsonb_typeof(v_in) is distinct from 'object' then raise exception 'invalid_checkout_terms'; end if;\n    select case when jsonb_typeof(settings->'checkout_terms') = 'object' then settings->'checkout_terms' else '{}'::jsonb end\n      into v_terms from shops where id = v_tok.shop_id for update;\n    foreach v_key in array array['delivery', 'cancellation', 'payment_note'] loop\n      continue when not v_in ? v_key;\n      case jsonb_typeof(v_in->v_key)\n        when 'null' then v_val := '';\n        when 'string' then v_val := btrim(replace(v_in->>v_key, E'\\r\\n', E'\\n'));\n        else raise exception 'invalid_checkout_terms';\n      end case;\n      if length(v_val) > 2000 then raise exception 'invalid_checkout_terms'; end if;\n      v_terms := v_terms || jsonb_build_object(v_key, v_val);\n    end loop;\n    v_patch := v_patch || jsonb_build_object('checkout_terms', v_terms);\n  end if;\n  update shops set\n    name = coalesce(nullif(btrim(p_values->>'name'), ''), name),\n    legal_notice = case when p_values ? 'legal_notice' then nullif(btrim(p_values->>'legal_notice'), '') else legal_notice end,\n    privacy_policy = case when p_values ? 'privacy_policy' then nullif(btrim(p_values->>'privacy_policy'), '') else privacy_policy end,\n    return_policy = case when p_values ? 'return_policy' then nullif(btrim(p_values->>'return_policy'), '') else return_policy end,\n    published = coalesce((p_values->>'published')::boolean, published),\n    settings = settings || v_patch\n  where id = v_tok.shop_id;\n  return api_shop_get(p_token_hash);\nend;\n$$;\n\ninsert into banto_migrations (version) values ('0032_api_checkout_terms');\n" },
  { version: "0033_relay_limits", sql: "-- Banto 0033_relay_limits: 中継元の IP と、IP ごとの上限の設定（外部レビューの指摘 2026-10-18、docs/headless.md「サーバー側で中継するとき」）\n-- 前方専用。\n--\n-- WordPress などの連携側がサーバーで Banto を中継すると、Banto から見た購入者の IP は全員その 1 台になり、\n-- 0029 の「同じ IP の未確定の予約は 20 まで」「同じ IP から会員のコード発行は 1 時間 30 回」がサイト全体の上限に化ける。\n--  - settings.headless.relay_ips: 信頼する中継元の IP。公開の settings に含め、Worker はそこから来た通信だけ X-Banto-Client-IP を購入者の IP として使う\n--  - member_login_start: 同じ IP からの 1 時間の回数を settings.members_login_limits.per_ip_per_hour（既定 30）で変えられるようにする\n--  - api_shop_get / api_shop_update: max_pending_per_ip と login_per_ip_per_hour を AI 用トークン（shop:read / shop:write）からも読み書きできる\n--    （0032_api_checkout_terms の checkout_terms の扱いはそのまま引き継ぐ。この 2 本は同じ関数を差し替えるので、後の版がすべてを含む）\n\n-- ---------- 公開の settings に headless.relay_ips（0028 を差し替え） ----------\ncreate or replace function banto_shop_public_settings(p jsonb)\nreturns jsonb language sql immutable as $$\n  select coalesce((select jsonb_object_agg(k, v) from jsonb_each(case when jsonb_typeof(p) = 'object' then p else '{}'::jsonb end) e(k, v)\n                    where k in ('theme', 'theme_settings', 'notice', 'shipping', 'modules', 'members_enabled', 'members_password',\n                                'checkout_terms', 'delivery_time', 'store_tryon', 'receipt', 'product_fields',\n                                'tax_rate', 'tax_rate_reduced', 'tax_rounding')), '{}'::jsonb)\n      || case when jsonb_typeof(p->'headless') = 'object'\n              then jsonb_build_object('headless', jsonb_build_object('return_origins', coalesce(p->'headless'->'return_origins', '[]'::jsonb),\n                                                                      'relay_ips', coalesce(p->'headless'->'relay_ips', '[]'::jsonb)))\n              else '{}'::jsonb end\n      || case when jsonb_typeof(p->'oauth') = 'object'\n              then jsonb_build_object('oauth', coalesce((\n                     select jsonb_object_agg(k, coalesce((select jsonb_object_agg(k2, v2) from jsonb_each(v) f(k2, v2) where k2 in ('client_id', 'bot_prompt')), '{}'::jsonb))\n                       from jsonb_each(p->'oauth') e(k, v) where jsonb_typeof(v) = 'object'), '{}'::jsonb))\n              else '{}'::jsonb end;\n$$;\nrevoke execute on function banto_shop_public_settings(jsonb) from public, anon, authenticated;\n\n-- ---------- member_login_start（0029 を差し替え: 同じ IP からの 1 時間の回数をショップの設定で） ----------\ncreate or replace function member_login_start(p_shop_id uuid, p_email text, p_code_hash text, p_link_hash text, p_ip_hash text, p_return_to text, p_ttl_seconds integer default 900)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_email text := lower(btrim(coalesce(p_email, '')));\n  v_from text;\n  v_id uuid;\n  v_limited boolean := false;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_login_start: service_role only' using errcode = '42501';\n  end if;\n  if length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  if not exists (select 1 from shops where id = p_shop_id and coalesce(settings->>'members_enabled', 'false') = 'true') then\n    raise exception 'members_disabled';\n  end if;\n  select nullif(btrim(e.settings->>'from'), '') into v_from\n    from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and e.url = 'https://banto.invalid/plugins/email_resend'\n   limit 1;\n  if v_from is null then raise exception 'mail_not_configured'; end if;\n\n  perform pg_advisory_xact_lock(hashtextextended('member_login|' || p_shop_id::text || '|' || v_email, 0));\n  if p_ip_hash is not null then\n    -- 同じ IP から同じアドレスへ: 15 分に 3 回・1 日 10 回（他人が被害者の枠を使い切れないように、IP ごとに分ける）\n    v_limited := (select count(*) from member_login_challenges where shop_id = p_shop_id and email = v_email and ip_hash = p_ip_hash and created_at > now() - interval '15 minutes') >= 3\n              or (select count(*) from member_login_challenges where shop_id = p_shop_id and email = v_email and ip_hash = p_ip_hash and created_at > now() - interval '1 day') >= 10\n              -- 同じ IP から誰へでも: 1 時間に 30 回（0033: settings.members_login_limits.per_ip_per_hour。中継する構成では中継元の宣言のほうを使う）\n              or (select count(*) from member_login_challenges where shop_id = p_shop_id and ip_hash = p_ip_hash and created_at > now() - interval '1 hour')\n                 >= banto_shop_limit(p_shop_id, 'members_login_limits', 'per_ip_per_hour', 30);\n  else\n    -- IP が分からない（Node でヘッダー未設定、中継元が申告しない）: アドレスだけで数える\n    v_limited := (select count(*) from member_login_challenges where shop_id = p_shop_id and email = v_email and created_at > now() - interval '15 minutes') >= 5;\n  end if;\n  -- アドレス全体: 1 日 30 通（メール爆撃の上限）。ショップ全体: 1 時間・1 日の上限（送信元の評判と Resend の枠を守る）\n  v_limited := v_limited\n    or (select count(*) from member_login_challenges where shop_id = p_shop_id and email = v_email and created_at > now() - interval '1 day') >= 30\n    or (select count(*) from member_login_challenges where shop_id = p_shop_id and created_at > now() - interval '1 hour')\n       >= banto_shop_limit(p_shop_id, 'members_login_limits', 'per_hour', 100)\n    or (select count(*) from member_login_challenges where shop_id = p_shop_id and created_at > now() - interval '1 day')\n       >= banto_shop_limit(p_shop_id, 'members_login_limits', 'per_day', 500);\n  if v_limited then\n    return jsonb_build_object('send', false, 'challenge_id', gen_random_uuid(), 'mail_from', v_from);\n  end if;\n\n  -- 直近 3 つまで有効（新しいコードを出しても、届いたばかりの前のコードが無効にならない）。それより古いものは無効にする\n  update member_login_challenges set consumed_at = now()\n   where shop_id = p_shop_id and email = v_email and consumed_at is null\n     and id not in (select id from member_login_challenges where shop_id = p_shop_id and email = v_email and consumed_at is null order by created_at desc limit 2);\n  insert into member_login_challenges (shop_id, email, code_hash, link_hash, ip_hash, return_to, expires_at)\n  values (p_shop_id, v_email, p_code_hash, p_link_hash, p_ip_hash, nullif(left(p_return_to, 500), ''),\n          now() + make_interval(secs => greatest(60, least(coalesce(p_ttl_seconds, 900), 3600))))\n  returning id into v_id;\n  return jsonb_build_object('send', true, 'challenge_id', v_id, 'mail_from', v_from);\nend;\n$$;\n\n-- ---------- AI 用: IP ごとの上限を読み書き（0032_api_checkout_terms を差し替え。checkout_terms の扱いは同じ） ----------\ncreate or replace function api_shop_get(p_token_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_shop shops%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'shop:read');\n  select * into v_shop from shops where id = v_tok.shop_id;\n  return jsonb_build_object(\n    'id', v_shop.id, 'slug', v_shop.slug, 'name', v_shop.name, 'published', v_shop.published,\n    'legal_notice', v_shop.legal_notice, 'privacy_policy', v_shop.privacy_policy, 'return_policy', v_shop.return_policy,\n    'checkout_terms', jsonb_build_object(\n      'delivery', nullif(btrim(v_shop.settings->'checkout_terms'->>'delivery'), ''),\n      'cancellation', nullif(btrim(v_shop.settings->'checkout_terms'->>'cancellation'), ''),\n      'payment_note', nullif(btrim(v_shop.settings->'checkout_terms'->>'payment_note'), '')),\n    'low_stock_threshold', coalesce((v_shop.settings->>'low_stock_threshold')::integer, 3),\n    'max_pending_per_ip', banto_shop_limit(v_shop.id, 'checkout', 'max_pending_per_ip', 20),\n    'login_per_ip_per_hour', banto_shop_limit(v_shop.id, 'members_login_limits', 'per_ip_per_hour', 30),\n    'stripe_connected', v_shop.stripe_account_id is not null,\n    'created_at', v_shop.created_at, 'updated_at', v_shop.updated_at);\nend;\n$$;\n\n-- 更新できる項目だけを受け付ける（settings 全体や stripe_account_id は触らせない）\ncreate or replace function api_shop_update(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_tok api_tokens;\n  v_threshold integer;\n  v_per_ip integer;\n  v_login_ip integer;\n  v_patch jsonb := '{}'::jsonb;\n  v_in jsonb;\n  v_terms jsonb;\n  v_key text;\n  v_val text;\n  v_settings jsonb;\nbegin\n  v_tok := api_require(p_token_hash, 'shop:write');\n  select settings into v_settings from shops where id = v_tok.shop_id for update;\n  if p_values ? 'low_stock_threshold' then\n    v_threshold := (p_values->>'low_stock_threshold')::integer;\n    if v_threshold is null or v_threshold < 0 or v_threshold > 100000 then raise exception 'invalid_low_stock_threshold'; end if;\n    v_patch := v_patch || jsonb_build_object('low_stock_threshold', v_threshold);\n  end if;\n  -- 購入前の確認画面の文言（0032）: 渡した鍵だけ変え、null か空文字で消す。1 項目 2000 文字まで\n  if p_values ? 'checkout_terms' then\n    v_in := p_values->'checkout_terms';\n    if jsonb_typeof(v_in) is distinct from 'object' then raise exception 'invalid_checkout_terms'; end if;\n    v_terms := case when jsonb_typeof(v_settings->'checkout_terms') = 'object' then v_settings->'checkout_terms' else '{}'::jsonb end;\n    foreach v_key in array array['delivery', 'cancellation', 'payment_note'] loop\n      continue when not v_in ? v_key;\n      case jsonb_typeof(v_in->v_key)\n        when 'null' then v_val := '';\n        when 'string' then v_val := btrim(replace(v_in->>v_key, E'\\r\\n', E'\\n'));\n        else raise exception 'invalid_checkout_terms';\n      end case;\n      if length(v_val) > 2000 then raise exception 'invalid_checkout_terms'; end if;\n      v_terms := v_terms || jsonb_build_object(v_key, v_val);\n    end loop;\n    v_patch := v_patch || jsonb_build_object('checkout_terms', v_terms);\n  end if;\n  -- IP ごとの上限（0033。banto_shop_limit が読むのは 1〜4 桁）。同じ節のほかの値は残す\n  if p_values ? 'max_pending_per_ip' then\n    v_per_ip := (p_values->>'max_pending_per_ip')::integer;\n    if v_per_ip is null or v_per_ip < 1 or v_per_ip > 9999 then raise exception 'invalid_max_pending_per_ip'; end if;\n    v_patch := v_patch || jsonb_build_object('checkout',\n      coalesce(case when jsonb_typeof(v_settings->'checkout') = 'object' then v_settings->'checkout' end, '{}'::jsonb) || jsonb_build_object('max_pending_per_ip', v_per_ip));\n  end if;\n  if p_values ? 'login_per_ip_per_hour' then\n    v_login_ip := (p_values->>'login_per_ip_per_hour')::integer;\n    if v_login_ip is null or v_login_ip < 1 or v_login_ip > 9999 then raise exception 'invalid_login_per_ip_per_hour'; end if;\n    v_patch := v_patch || jsonb_build_object('members_login_limits',\n      coalesce(case when jsonb_typeof(v_settings->'members_login_limits') = 'object' then v_settings->'members_login_limits' end, '{}'::jsonb) || jsonb_build_object('per_ip_per_hour', v_login_ip));\n  end if;\n  update shops set\n    name = coalesce(nullif(btrim(p_values->>'name'), ''), name),\n    legal_notice = case when p_values ? 'legal_notice' then nullif(btrim(p_values->>'legal_notice'), '') else legal_notice end,\n    privacy_policy = case when p_values ? 'privacy_policy' then nullif(btrim(p_values->>'privacy_policy'), '') else privacy_policy end,\n    return_policy = case when p_values ? 'return_policy' then nullif(btrim(p_values->>'return_policy'), '') else return_policy end,\n    published = coalesce((p_values->>'published')::boolean, published),\n    settings = settings || v_patch\n  where id = v_tok.shop_id;\n  return api_shop_get(p_token_hash);\nend;\n$$;\n\ninsert into banto_migrations (version) values ('0033_relay_limits');\n" },
  { version: "0034_relay_ips_private", sql: "-- Banto 0034_relay_ips_private: 中継元の IP（settings.headless.relay_ips）を公開の settings から外す（外部レビューの指摘 2026-10-18 その 2）\n-- 前方専用。\n--\n-- 0033 では relay_ips を公開の settings（shop_public_get / shop_public_list、anon が呼べる）に含めていた。\n-- これは連携側（WordPress 等）のサーバーの素の IP で、CDN / WAF の後ろに置いていても直接攻撃できてしまう。\n-- 判定に使うのは Worker だけなので、公開しない。Worker は service_role で shops.settings を読み（X-Banto-Client-IP が付いた通信のときだけ）、\n-- ショップ行と同じ時間だけキャッシュする（src/routes/common.ts の clientIpFor）。\n\ncreate or replace function banto_shop_public_settings(p jsonb)\nreturns jsonb language sql immutable as $$\n  select coalesce((select jsonb_object_agg(k, v) from jsonb_each(case when jsonb_typeof(p) = 'object' then p else '{}'::jsonb end) e(k, v)\n                    where k in ('theme', 'theme_settings', 'notice', 'shipping', 'modules', 'members_enabled', 'members_password',\n                                'checkout_terms', 'delivery_time', 'store_tryon', 'receipt', 'product_fields',\n                                'tax_rate', 'tax_rate_reduced', 'tax_rounding')), '{}'::jsonb)\n      || case when jsonb_typeof(p->'headless') = 'object'\n              then jsonb_build_object('headless', jsonb_build_object('return_origins', coalesce(p->'headless'->'return_origins', '[]'::jsonb)))\n              else '{}'::jsonb end\n      || case when jsonb_typeof(p->'oauth') = 'object'\n              then jsonb_build_object('oauth', coalesce((\n                     select jsonb_object_agg(k, coalesce((select jsonb_object_agg(k2, v2) from jsonb_each(v) f(k2, v2) where k2 in ('client_id', 'bot_prompt')), '{}'::jsonb))\n                       from jsonb_each(p->'oauth') e(k, v) where jsonb_typeof(v) = 'object'), '{}'::jsonb))\n              else '{}'::jsonb end;\n$$;\nrevoke execute on function banto_shop_public_settings(jsonb) from public, anon, authenticated;\n\ninsert into banto_migrations (version) values ('0034_relay_ips_private');\n" },
  { version: "0035_checkout_status", sql: "-- Banto 0035_checkout_status: 決済ページから戻った画面で「この注文は確定したか」を引く（外部レビューの指摘 2026-10-18）\n-- 前方専用。\n--\n-- 注文の確定は Webhook のみ（CLAUDE.md §5）なので、戻り先の画面はそのままでは注文番号も確定したかも知らない。\n-- Worker は確定の直前に quote の識別子（reservations.quote_id、0029）を署名した照会トークン（個人情報なし、24 時間）を出し、\n-- 戻り先はそれでこの関数を呼ぶ（GET /api/shops/<slug>/checkout/status、同梱テーマの /checkout/done）。\n-- 返すのは注文番号・状態・合計だけ。宛先や連絡先は返さない（それは注文照会 lookup_order の仕事）。\n\ncreate or replace function checkout_status(p_shop_id uuid, p_quote_id text)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_r reservations%rowtype; v_o orders%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'checkout_status: service_role only' using errcode = '42501';\n  end if;\n  select * into v_r from reservations where shop_id = p_shop_id and quote_id = p_quote_id order by created_at desc limit 1;\n  if not found then return jsonb_build_object('status', 'not_found', 'order', null, 'expires_at', null); end if;\n  select * into v_o from orders where reservation_id = v_r.id;\n  if found then\n    return jsonb_build_object('status', 'confirmed', 'expires_at', v_r.expires_at,\n      'order', jsonb_build_object('number', v_o.number, 'status', v_o.status, 'total_jpy', v_o.total_jpy, 'payment_provider', v_o.payment_provider, 'created_at', v_o.created_at));\n  end if;\n  return jsonb_build_object('status', v_r.status::text, 'order', null, 'expires_at', v_r.expires_at);\nend;\n$$;\nrevoke execute on function checkout_status(uuid, text) from public, anon, authenticated;\ngrant execute on function checkout_status(uuid, text) to service_role;\n\ninsert into banto_migrations (version) values ('0035_checkout_status');\n" },
  { version: "0036_api_coupons_customers", sql: "-- Banto 0036_api_coupons_customers: AI 用トークン（/api/v1・/mcp）でクーポンと会員（顧客）を扱う。docs/ai-access.md\n-- 前方専用。WordPress のプラグインなど、外部のサーバーからクーポンの管理と会員の参照・管理をするための窓口。\n--\n-- 新しいスコープと、発行者に求める項目（0028 の banto_scope_perm に足す。管理画面と同じ項目）:\n--   coupons:read    クーポン（キャンペーン）と発行済みのクーポンの参照        → marketing\n--   coupons:write   クーポンの作成・更新・削除、発行・取り消し                → marketing\n--   customers:read  会員の参照（メールアドレス・氏名・住所。個人情報そのもの）  → customers\n--   customers:write 会員の作成・氏名と住所の更新・削除（退会）                → customers\n--\n-- 方針:\n--  - 判定は SQL だけ（api_require）。Worker は形を整えて渡すだけ。\n--  - クーポンはモジュール coupons が ON のショップだけ（OFF なら module_disabled）。管理画面と同じ。\n--  - 会員のメールアドレスは API では変えられない。会員はメールのコードで入るので、アドレスを変えられることは\n--    乗っ取りの入り口になる（トークンが漏れたときの被害を広げない）。変更は管理画面（member_set_email、前後に通知）だけ。\n--  - パスワードのハッシュ・ログインの世代などは返さない。\n--  - 使用済み・使用中のクーポンは削除させない（履歴が消えるため。止めるときは active = false）。\n--  - 発行済みのクーポンを会員に配るのは会員 ID で（メールアドレスでは受けない。coupons:write だけのトークンで\n--    「このアドレスは会員か」を調べられないように。アドレスから ID を引くのは customers:read の仕事）。\n\n-- ---------- スコープ ----------\nalter table api_tokens drop constraint if exists api_tokens_scopes_valid;\nalter table api_tokens add constraint api_tokens_scopes_valid check (\n  scopes <@ array['products:read','products:write','orders:read','orders:pii','orders:write','shop:read','shop:write','stats:read',\n                  'coupons:read','coupons:write','customers:read','customers:write']::text[]\n);\n\ncreate or replace function banto_scope_perm(p_scope text)\nreturns text language sql immutable as $$\n  select case p_scope\n    when 'products:read' then 'catalog'\n    when 'products:write' then 'catalog'\n    when 'orders:read' then 'orders'\n    when 'orders:write' then 'orders'\n    when 'orders:pii' then 'customers'\n    when 'shop:read' then 'integrations'\n    when 'shop:write' then 'settings'\n    when 'stats:read' then 'reports'\n    when 'coupons:read' then 'marketing'\n    when 'coupons:write' then 'marketing'\n    when 'customers:read' then 'customers'\n    when 'customers:write' then 'customers'\n  end;\n$$;\nrevoke execute on function banto_scope_perm(text) from public, anon, authenticated;\n\n-- ---------- 共通 ----------\n-- LIKE の特殊文字を文字として扱う（検索語の % や _ で全件に当たらないように）\ncreate or replace function banto_like_escape(p text)\nreturns text language sql immutable as $$\n  select replace(replace(replace(p, '\\', '\\\\'), '%', '\\%'), '_', '\\_');\n$$;\nrevoke execute on function banto_like_escape(text) from public, anon, authenticated;\n\n-- クーポンのモジュールが ON か（管理画面の moduleEnabled と同じ: settings.modules.coupons が true）\ncreate or replace function banto_api_coupons_require(p_token_hash text, p_scope text)\nreturns api_tokens\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens;\nbegin\n  v_tok := api_require(p_token_hash, p_scope);\n  if not exists (select 1 from shops where id = v_tok.shop_id and settings->'modules'->'coupons' = 'true'::jsonb) then\n    raise exception 'module_disabled';\n  end if;\n  return v_tok;\nend;\n$$;\nrevoke execute on function banto_api_coupons_require(text, text) from public, anon, authenticated;\n\n-- ---------- クーポン: JSON ----------\ncreate or replace function api_coupon_json(p_c coupon_campaigns)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_c.id, 'name', p_c.name, 'code', p_c.code, 'kind', p_c.kind, 'value', p_c.value,\n    'starts_at', p_c.starts_at, 'ends_at', p_c.ends_at,\n    'usage_limit', p_c.usage_limit, 'per_customer_limit', p_c.per_customer_limit,\n    'combinable', p_c.combinable, 'audience', p_c.audience, 'conditions', p_c.conditions, 'active', p_c.active,\n    'grant_valid_days', p_c.grant_valid_days, 'auto_grant', p_c.auto_grant, 'claimable', p_c.claimable,\n    'external_ref', p_c.external_ref, 'created_at', p_c.created_at, 'updated_at', p_c.updated_at,\n    'usage', (select jsonb_build_object('used', count(*) filter (where r.status = 'used'), 'held', count(*) filter (where r.status = 'held'))\n                from coupon_redemptions r where r.shop_id = p_c.shop_id and r.campaign_id = p_c.id),\n    'grants', (select jsonb_build_object('available', count(*) filter (where g.status = 'available'), 'held', count(*) filter (where g.status = 'held'),\n                                         'used', count(*) filter (where g.status = 'used'), 'revoked', count(*) filter (where g.status = 'revoked'))\n                 from coupon_grants g where g.campaign_id = p_c.id)\n  );\n$$;\nrevoke execute on function api_coupon_json(coupon_campaigns) from public, anon, authenticated;\n\n-- ---------- クーポン: 値の検査 ----------\n-- p_values の鍵だけを p_c に当てて返す（作成は既定値の行、更新は今の行に）。知らない鍵・型の違い・範囲外は invalid_<鍵>。\n-- 条件（conditions）は src/commerce/discounts.ts の CouponConditions の鍵だけ。商品・カテゴリーはこのショップのものだけ。\ncreate or replace function banto_api_coupon_apply(p_shop_id uuid, p_c coupon_campaigns, p_values jsonb)\nreturns coupon_campaigns\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_key text; v_val jsonb; v_cond jsonb; v_ck text; v_cv jsonb; v_ids uuid[]; v_n integer; v_s text;\nbegin\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key, v_val in select * from jsonb_each(p_values) loop\n    case v_key\n      when 'name' then\n        v_s := btrim(coalesce(v_val #>> '{}', ''));\n        if jsonb_typeof(v_val) <> 'string' or length(v_s) not between 1 and 100 then raise exception 'invalid_name'; end if;\n        p_c.name := v_s;\n      when 'code' then\n        if jsonb_typeof(v_val) = 'null' or btrim(v_val #>> '{}') = '' then p_c.code := null;\n        else\n          v_s := upper(btrim(v_val #>> '{}'));\n          if jsonb_typeof(v_val) <> 'string' or v_s !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$' then raise exception 'invalid_code'; end if;\n          p_c.code := v_s;\n        end if;\n      when 'kind' then\n        if jsonb_typeof(v_val) <> 'string' or v_val #>> '{}' not in ('percent', 'fixed', 'free_shipping') then raise exception 'invalid_kind'; end if;\n        p_c.kind := v_val #>> '{}';\n      when 'value' then\n        if jsonb_typeof(v_val) <> 'number' or (v_val #>> '{}') !~ '^\\d+$' then raise exception 'invalid_value'; end if;\n        p_c.value := (v_val #>> '{}')::integer;\n      when 'starts_at', 'ends_at' then\n        if jsonb_typeof(v_val) not in ('string', 'null') then raise exception 'invalid_%', v_key; end if;\n        begin\n          if v_key = 'starts_at' then p_c.starts_at := (v_val #>> '{}')::timestamptz; else p_c.ends_at := (v_val #>> '{}')::timestamptz; end if;\n        exception when others then raise exception 'invalid_%', v_key;\n        end;\n      when 'usage_limit', 'per_customer_limit', 'grant_valid_days' then\n        if jsonb_typeof(v_val) = 'null' then v_n := null;\n        elsif jsonb_typeof(v_val) = 'number' and (v_val #>> '{}') ~ '^\\d{1,7}$' then v_n := (v_val #>> '{}')::integer;\n        else raise exception 'invalid_%', v_key;\n        end if;\n        if v_key = 'usage_limit' then\n          if v_n is not null and v_n not between 1 and 100000 then raise exception 'invalid_usage_limit'; end if;\n          p_c.usage_limit := v_n;\n        elsif v_key = 'per_customer_limit' then\n          if v_n is not null and v_n not between 1 and 1000 then raise exception 'invalid_per_customer_limit'; end if;\n          p_c.per_customer_limit := v_n;\n        else\n          if v_n is not null and v_n not between 1 and 3650 then raise exception 'invalid_grant_valid_days'; end if;\n          p_c.grant_valid_days := v_n;\n        end if;\n      when 'combinable', 'active', 'claimable' then\n        if jsonb_typeof(v_val) <> 'boolean' then raise exception 'invalid_%', v_key; end if;\n        if v_key = 'combinable' then p_c.combinable := v_val::boolean;\n        elsif v_key = 'active' then p_c.active := v_val::boolean;\n        else p_c.claimable := v_val::boolean;\n        end if;\n      when 'audience' then\n        if jsonb_typeof(v_val) <> 'string' or v_val #>> '{}' not in ('public', 'members') then raise exception 'invalid_audience'; end if;\n        p_c.audience := v_val #>> '{}';\n      when 'auto_grant' then\n        if jsonb_typeof(v_val) = 'null' then p_c.auto_grant := null;\n        elsif jsonb_typeof(v_val) = 'string' and v_val #>> '{}' in ('first_login', 'after_purchase') then p_c.auto_grant := v_val #>> '{}';\n        else raise exception 'invalid_auto_grant';\n        end if;\n      when 'external_ref' then\n        if jsonb_typeof(v_val) = 'null' or btrim(v_val #>> '{}') = '' then p_c.external_ref := null;\n        elsif jsonb_typeof(v_val) = 'string' and length(btrim(v_val #>> '{}')) <= 100 then p_c.external_ref := btrim(v_val #>> '{}');\n        else raise exception 'invalid_external_ref';\n        end if;\n      when 'conditions' then\n        if jsonb_typeof(v_val) = 'null' then v_val := '{}'::jsonb; end if;\n        if jsonb_typeof(v_val) <> 'object' then raise exception 'invalid_conditions'; end if;\n        v_cond := '{}'::jsonb;\n        for v_ck, v_cv in select * from jsonb_each(v_val) loop\n          if jsonb_typeof(v_cv) = 'null' then continue; end if;\n          case v_ck\n            when 'product_ids', 'exclude_product_ids', 'category_ids', 'exclude_category_ids' then\n              if jsonb_typeof(v_cv) <> 'array' or jsonb_array_length(v_cv) > 200\n                 or exists (select 1 from jsonb_array_elements(v_cv) e\n                             where jsonb_typeof(e) <> 'string' or (e #>> '{}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              select coalesce(array_agg(distinct (e #>> '{}')::uuid), '{}') into v_ids from jsonb_array_elements(v_cv) e;\n              if v_ck in ('product_ids', 'exclude_product_ids') then\n                if (select count(*) from products where shop_id = p_shop_id and id = any(v_ids)) <> coalesce(array_length(v_ids, 1), 0) then raise exception 'invalid_conditions_unknown_products'; end if;\n              else\n                if (select count(*) from categories where shop_id = p_shop_id and id = any(v_ids)) <> coalesce(array_length(v_ids, 1), 0) then raise exception 'invalid_conditions_unknown_categories'; end if;\n              end if;\n              if coalesce(array_length(v_ids, 1), 0) > 0 then v_cond := v_cond || jsonb_build_object(v_ck, to_jsonb(v_ids)); end if;\n            when 'exclude_sale' then\n              if jsonb_typeof(v_cv) <> 'boolean' then raise exception 'invalid_conditions_exclude_sale'; end if;\n              if v_cv::boolean then v_cond := v_cond || jsonb_build_object('exclude_sale', true); end if;\n            when 'min_subtotal_jpy', 'max_subtotal_jpy', 'min_qty' then\n              -- 上限: 点数は 999、金額は 1 億円（管理画面と同じ）\n              v_n := 100000000;\n              if v_ck = 'min_qty' then v_n := 999; end if;\n              if jsonb_typeof(v_cv) <> 'number' or (v_cv #>> '{}') !~ '^\\d{1,9}$' or (v_cv #>> '{}')::integer > v_n then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              v_cond := v_cond || jsonb_build_object(v_ck, (v_cv #>> '{}')::integer);\n            else raise exception 'invalid_conditions_unknown_key';\n          end case;\n        end loop;\n        p_c.conditions := v_cond;\n      else raise exception 'invalid_field_%', left(v_key, 40);\n    end case;\n  end loop;\n  -- 種類と値の組み合わせ（テーブルの CHECK と同じ。わかりやすい理由で返す）\n  if p_c.kind = 'free_shipping' then p_c.value := 0;\n  elsif p_c.kind = 'percent' and p_c.value not between 1 and 100 then raise exception 'invalid_value';\n  elsif p_c.kind = 'fixed' and p_c.value not between 1 and 10000000 then raise exception 'invalid_value';\n  end if;\n  if p_c.starts_at is not null and p_c.ends_at is not null and p_c.starts_at >= p_c.ends_at then raise exception 'invalid_ends_at'; end if;\n  return p_c;\nend;\n$$;\nrevoke execute on function banto_api_coupon_apply(uuid, coupon_campaigns, jsonb) from public, anon, authenticated;\n\n-- ---------- クーポン: RPC ----------\ncreate or replace function api_coupons_list(p_token_hash text, p_query text default null, p_active boolean default null,\n                                            p_limit integer default 50, p_offset integer default 0)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_limit integer; v_offset integer; v_total integer; v_items jsonb; v_q text;\nbegin\n  v_tok := banto_api_coupons_require(p_token_hash, 'coupons:read');\n  v_limit := greatest(1, least(coalesce(p_limit, 50), 100));\n  v_offset := greatest(0, coalesce(p_offset, 0));\n  v_q := case when nullif(btrim(p_query), '') is not null then '%' || banto_like_escape(btrim(p_query)) || '%' end;\n  select count(*) into v_total from coupon_campaigns c\n   where c.shop_id = v_tok.shop_id and (p_active is null or c.active = p_active)\n     and (v_q is null or c.name ilike v_q or c.code ilike v_q);\n  select coalesce(jsonb_agg(api_coupon_json(c) order by c.created_at desc), '[]'::jsonb) into v_items\n    from (select * from coupon_campaigns c\n           where c.shop_id = v_tok.shop_id and (p_active is null or c.active = p_active)\n             and (v_q is null or c.name ilike v_q or c.code ilike v_q)\n           order by c.created_at desc limit v_limit offset v_offset) c;\n  return jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', v_offset);\nend;\n$$;\n\n-- id かコードで 1 件\ncreate or replace function api_coupon_get(p_token_hash text, p_campaign_id uuid default null, p_code text default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_c coupon_campaigns%rowtype;\nbegin\n  v_tok := banto_api_coupons_require(p_token_hash, 'coupons:read');\n  if p_campaign_id is not null then\n    select * into v_c from coupon_campaigns where shop_id = v_tok.shop_id and id = p_campaign_id;\n  else\n    select * into v_c from coupon_campaigns where shop_id = v_tok.shop_id and code = upper(btrim(coalesce(p_code, '')));\n  end if;\n  if not found then raise exception 'not_found'; end if;\n  return api_coupon_json(v_c);\nend;\n$$;\n\ncreate or replace function api_coupon_create(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_c coupon_campaigns%rowtype;\nbegin\n  v_tok := banto_api_coupons_require(p_token_hash, 'coupons:write');\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  if not (p_values ? 'name') then raise exception 'invalid_name'; end if;\n  if not (p_values ? 'kind') then raise exception 'invalid_kind'; end if;\n  -- 既定値（管理画面の新規作成と同じ）\n  v_c.id := gen_random_uuid();\n  v_c.shop_id := v_tok.shop_id;\n  v_c.value := 0;\n  v_c.combinable := false;\n  v_c.audience := 'public';\n  v_c.conditions := '{}'::jsonb;\n  v_c.active := true;\n  v_c.claimable := false;\n  v_c := banto_api_coupon_apply(v_tok.shop_id, v_c, p_values);\n  insert into coupon_campaigns (id, shop_id, name, code, kind, value, starts_at, ends_at, usage_limit, per_customer_limit,\n                                combinable, audience, conditions, active, grant_valid_days, auto_grant, claimable, external_ref)\n  values (v_c.id, v_c.shop_id, v_c.name, v_c.code, v_c.kind, v_c.value, v_c.starts_at, v_c.ends_at, v_c.usage_limit, v_c.per_customer_limit,\n          v_c.combinable, v_c.audience, v_c.conditions, v_c.active, v_c.grant_valid_days, v_c.auto_grant, v_c.claimable, v_c.external_ref)\n  returning * into v_c;\n  return api_coupon_json(v_c);\nend;\n$$;\n\ncreate or replace function api_coupon_update(p_token_hash text, p_campaign_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_c coupon_campaigns%rowtype;\nbegin\n  v_tok := banto_api_coupons_require(p_token_hash, 'coupons:write');\n  select * into v_c from coupon_campaigns where shop_id = v_tok.shop_id and id = p_campaign_id for update;\n  if not found then raise exception 'not_found'; end if;\n  v_c := banto_api_coupon_apply(v_tok.shop_id, v_c, p_values);\n  update coupon_campaigns\n     set name = v_c.name, code = v_c.code, kind = v_c.kind, value = v_c.value, starts_at = v_c.starts_at, ends_at = v_c.ends_at,\n         usage_limit = v_c.usage_limit, per_customer_limit = v_c.per_customer_limit, combinable = v_c.combinable,\n         audience = v_c.audience, conditions = v_c.conditions, active = v_c.active, grant_valid_days = v_c.grant_valid_days,\n         auto_grant = v_c.auto_grant, claimable = v_c.claimable, external_ref = v_c.external_ref\n   where id = v_c.id and shop_id = v_tok.shop_id\n  returning * into v_c;\n  return api_coupon_json(v_c);\nend;\n$$;\n\n-- 使われた（使用中の）ことのないクーポンだけ消せる。使ったものは active = false で止める\ncreate or replace function api_coupon_delete(p_token_hash text, p_campaign_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens;\nbegin\n  v_tok := banto_api_coupons_require(p_token_hash, 'coupons:write');\n  perform 1 from coupon_campaigns where shop_id = v_tok.shop_id and id = p_campaign_id for update;\n  if not found then raise exception 'not_found'; end if;\n  if exists (select 1 from coupon_redemptions where campaign_id = p_campaign_id and status in ('held', 'used'))\n     or exists (select 1 from coupon_grants where campaign_id = p_campaign_id and status in ('held', 'used')) then\n    raise exception 'coupon_in_use';\n  end if;\n  delete from coupon_campaigns where shop_id = v_tok.shop_id and id = p_campaign_id;\n  return jsonb_build_object('deleted', true, 'id', p_campaign_id);\nend;\n$$;\n\n-- ---------- 発行済みのクーポン（0019） ----------\ncreate or replace function api_coupon_grants_list(p_token_hash text, p_campaign_id uuid, p_status text default null,\n                                                  p_limit integer default 50, p_offset integer default 0)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_limit integer; v_offset integer; v_total integer; v_items jsonb;\nbegin\n  v_tok := banto_api_coupons_require(p_token_hash, 'coupons:read');\n  if not exists (select 1 from coupon_campaigns where shop_id = v_tok.shop_id and id = p_campaign_id) then raise exception 'not_found'; end if;\n  if p_status is not null and p_status not in ('available', 'held', 'used', 'revoked') then raise exception 'invalid_status'; end if;\n  v_limit := greatest(1, least(coalesce(p_limit, 50), 100));\n  v_offset := greatest(0, coalesce(p_offset, 0));\n  select count(*) into v_total from coupon_grants g where g.campaign_id = p_campaign_id and (p_status is null or g.status = p_status);\n  select coalesce(jsonb_agg(jsonb_build_object('id', g.id, 'code', g.code, 'customer_id', g.customer_id, 'status', g.status,\n                                               'expires_at', g.expires_at, 'created_at', g.created_at, 'used_at', g.used_at)\n                            order by g.created_at desc), '[]'::jsonb) into v_items\n    from (select * from coupon_grants g where g.campaign_id = p_campaign_id and (p_status is null or g.status = p_status)\n           order by g.created_at desc limit v_limit offset v_offset) g;\n  return jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', v_offset);\nend;\n$$;\n\n-- 会員（ID）ごとに 1 枚と、誰でも 1 回使えるコードを p_count 枚。1 回 500 枚まで。発行したものを返す。\n-- 会員が同じキャンペーンの使っていないクーポンを持っていれば、その人には発行しない（管理画面の発行と同じ）\ncreate or replace function api_coupon_grants_issue(p_token_hash text, p_campaign_id uuid, p_customer_ids uuid[] default null, p_count integer default 0)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_tok api_tokens; v_c coupon_campaigns%rowtype; v_expires timestamptz; v_cid uuid; v_i integer; v_code text;\n  v_g coupon_grants%rowtype; v_out jsonb := '[]'::jsonb; v_skipped integer := 0;\nbegin\n  v_tok := banto_api_coupons_require(p_token_hash, 'coupons:write');\n  select * into v_c from coupon_campaigns where shop_id = v_tok.shop_id and id = p_campaign_id;\n  if not found then raise exception 'not_found'; end if;\n  if coalesce(p_count, 0) < 0 or coalesce(p_count, 0) + coalesce(array_length(p_customer_ids, 1), 0) > 500 then raise exception 'invalid_count'; end if;\n  if coalesce(p_count, 0) + coalesce(array_length(p_customer_ids, 1), 0) = 0 then raise exception 'invalid_count'; end if;\n  v_expires := case when v_c.grant_valid_days is not null then now() + make_interval(days => v_c.grant_valid_days) end;\n  if v_c.ends_at is not null and (v_expires is null or v_expires > v_c.ends_at) then v_expires := v_c.ends_at; end if;\n  foreach v_cid in array coalesce(p_customer_ids, '{}'::uuid[]) loop\n    -- 他のショップの会員・存在しない ID・既に持っている人は飛ばす（数だけ返す。存在を言い分けない）\n    if not exists (select 1 from customers where shop_id = v_tok.shop_id and id = v_cid)\n       or exists (select 1 from coupon_grants where campaign_id = v_c.id and customer_id = v_cid and status in ('available', 'held')) then\n      v_skipped := v_skipped + 1;\n      continue;\n    end if;\n    loop\n      v_code := banto_grant_code();\n      begin\n        insert into coupon_grants (shop_id, campaign_id, code, customer_id, expires_at) values (v_tok.shop_id, v_c.id, v_code, v_cid, v_expires) returning * into v_g;\n        exit;\n      exception when unique_violation then null;\n      end;\n    end loop;\n    v_out := v_out || jsonb_build_object('id', v_g.id, 'code', v_g.code, 'customer_id', v_g.customer_id, 'expires_at', v_g.expires_at);\n  end loop;\n  for v_i in 1 .. coalesce(p_count, 0) loop\n    loop\n      v_code := banto_grant_code();\n      begin\n        insert into coupon_grants (shop_id, campaign_id, code, expires_at) values (v_tok.shop_id, v_c.id, v_code, v_expires) returning * into v_g;\n        exit;\n      exception when unique_violation then null;\n      end;\n    end loop;\n    v_out := v_out || jsonb_build_object('id', v_g.id, 'code', v_g.code, 'customer_id', null, 'expires_at', v_g.expires_at);\n  end loop;\n  return jsonb_build_object('issued', jsonb_array_length(v_out), 'skipped', v_skipped, 'grants', v_out);\nend;\n$$;\n\ncreate or replace function api_coupon_grant_revoke(p_token_hash text, p_grant_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_status text;\nbegin\n  v_tok := banto_api_coupons_require(p_token_hash, 'coupons:write');\n  select status into v_status from coupon_grants where shop_id = v_tok.shop_id and id = p_grant_id for update;\n  if not found then raise exception 'not_found'; end if;\n  if v_status = 'available' then\n    update coupon_grants set status = 'revoked' where id = p_grant_id;\n    v_status := 'revoked';\n  elsif v_status <> 'revoked' then\n    raise exception 'invalid_transition';\n  end if;\n  return jsonb_build_object('id', p_grant_id, 'status', v_status);\nend;\n$$;\n\n-- ---------- 会員（顧客） ----------\n-- 返すのは画面に出している項目だけ（パスワードのハッシュ・世代は返さない）。注文の件数と合計は確定済み（paid / shipped）\ncreate or replace function api_customer_json(p_c customers)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_c.id, 'email', p_c.email, 'name', p_c.name, 'default_address', p_c.default_address,\n    'created_at', p_c.created_at, 'updated_at', p_c.updated_at, 'last_login_at', p_c.last_login_at,\n    'orders', (select jsonb_build_object('count', count(*), 'total_jpy', coalesce(sum(o.total_jpy), 0), 'last_order_at', max(o.created_at))\n                 from orders o where o.shop_id = p_c.shop_id and o.customer_id = p_c.id and o.status in ('paid', 'shipped'))\n  );\n$$;\nrevoke execute on function api_customer_json(customers) from public, anon, authenticated;\n\n-- 住所: 決まった鍵の文字列だけ（各 200 文字まで）。null で消す\ncreate or replace function banto_api_address(p jsonb)\nreturns jsonb\nlanguage plpgsql\nimmutable\nas $$\ndeclare v_k text; v_v jsonb; v_out jsonb := '{}'::jsonb;\nbegin\n  if p is null or jsonb_typeof(p) = 'null' then return null; end if;\n  if jsonb_typeof(p) <> 'object' then raise exception 'invalid_default_address'; end if;\n  for v_k, v_v in select * from jsonb_each(p) loop\n    if v_k not in ('name', 'phone', 'postal_code', 'country', 'state', 'city', 'line1', 'line2') then raise exception 'invalid_default_address'; end if;\n    if jsonb_typeof(v_v) = 'null' then continue; end if;\n    if jsonb_typeof(v_v) <> 'string' or length(v_v #>> '{}') > 200 then raise exception 'invalid_default_address'; end if;\n    v_out := v_out || jsonb_build_object(v_k, btrim(v_v #>> '{}'));\n  end loop;\n  return v_out;\nend;\n$$;\nrevoke execute on function banto_api_address(jsonb) from public, anon, authenticated;\n\n-- 一覧・検索。p_query はメールアドレス・氏名の部分一致、p_email は完全一致（大文字小文字は区別しない）\ncreate or replace function api_customers_list(p_token_hash text, p_query text default null, p_email text default null,\n                                              p_limit integer default 50, p_offset integer default 0)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_limit integer; v_offset integer; v_total integer; v_items jsonb; v_q text; v_email text;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:read');\n  v_limit := greatest(1, least(coalesce(p_limit, 50), 100));\n  v_offset := greatest(0, coalesce(p_offset, 0));\n  v_q := case when nullif(btrim(p_query), '') is not null then '%' || banto_like_escape(btrim(p_query)) || '%' end;\n  v_email := nullif(lower(btrim(p_email)), '');\n  select count(*) into v_total from customers c\n   where c.shop_id = v_tok.shop_id\n     and (v_email is null or lower(c.email) = v_email)\n     and (v_q is null or c.email ilike v_q or c.name ilike v_q);\n  select coalesce(jsonb_agg(api_customer_json(c) order by c.created_at desc), '[]'::jsonb) into v_items\n    from (select * from customers c\n           where c.shop_id = v_tok.shop_id\n             and (v_email is null or lower(c.email) = v_email)\n             and (v_q is null or c.email ilike v_q or c.name ilike v_q)\n           order by c.created_at desc limit v_limit offset v_offset) c;\n  return jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', v_offset);\nend;\n$$;\n\n-- 1 件。orders:read もあるトークンには、最近の注文（20 件、個人情報なし）を付ける\ncreate or replace function api_customer_get(p_token_hash text, p_customer_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_c customers%rowtype; v_out jsonb;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:read');\n  select * into v_c from customers where shop_id = v_tok.shop_id and id = p_customer_id;\n  if not found then raise exception 'not_found'; end if;\n  v_out := api_customer_json(v_c);\n  if 'orders:read' = any(v_tok.scopes) and banto_token_scope_ok(v_tok.owner_id, v_tok.shop_id, 'orders:read') then\n    v_out := v_out || jsonb_build_object('recent_orders', (\n      select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'number', o.number, 'status', o.status, 'total_jpy', o.total_jpy, 'created_at', o.created_at)\n                                order by o.created_at desc), '[]'::jsonb)\n        from (select * from orders o where o.shop_id = v_tok.shop_id and o.customer_id = v_c.id order by o.created_at desc limit 20) o));\n  end if;\n  return v_out;\nend;\n$$;\n\n-- 作る。同じメールアドレスの会員があれば email_taken（上書きしない）。Banto からは何も知らせない\ncreate or replace function api_customer_create(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_email text; v_name text; v_c customers%rowtype; v_key text;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:write');\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key in select jsonb_object_keys(p_values) loop\n    if v_key not in ('email', 'name', 'default_address') then raise exception 'invalid_field_%', left(v_key, 40); end if;\n  end loop;\n  v_email := lower(btrim(coalesce(p_values->>'email', '')));\n  if jsonb_typeof(p_values->'email') <> 'string' or length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  if p_values ? 'name' and jsonb_typeof(p_values->'name') not in ('string', 'null') then raise exception 'invalid_name'; end if;\n  v_name := nullif(btrim(coalesce(p_values->>'name', '')), '');\n  if length(v_name) > 200 then raise exception 'invalid_name'; end if;\n  if exists (select 1 from customers where shop_id = v_tok.shop_id and lower(email) = v_email) then raise exception 'email_taken'; end if;\n  insert into customers (shop_id, email, name, default_address)\n  values (v_tok.shop_id, v_email, v_name, banto_api_address(p_values->'default_address'))\n  returning * into v_c;\n  return api_customer_json(v_c);\nend;\n$$;\n\n-- 氏名と住所だけ変える。メールアドレスは変えない（email_change_not_allowed。管理画面の「メールアドレスの変更」で）\ncreate or replace function api_customer_update(p_token_hash text, p_customer_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_c customers%rowtype; v_key text; v_name text;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:write');\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key in select jsonb_object_keys(p_values) loop\n    if v_key = 'email' then raise exception 'email_change_not_allowed'; end if;\n    if v_key not in ('name', 'default_address') then raise exception 'invalid_field_%', left(v_key, 40); end if;\n  end loop;\n  select * into v_c from customers where shop_id = v_tok.shop_id and id = p_customer_id for update;\n  if not found then raise exception 'not_found'; end if;\n  if p_values ? 'name' then\n    if jsonb_typeof(p_values->'name') not in ('string', 'null') then raise exception 'invalid_name'; end if;\n    v_name := nullif(btrim(coalesce(p_values->>'name', '')), '');\n    if length(v_name) > 200 then raise exception 'invalid_name'; end if;\n    v_c.name := v_name;\n  end if;\n  if p_values ? 'default_address' then v_c.default_address := banto_api_address(p_values->'default_address'); end if;\n  update customers set name = v_c.name, default_address = v_c.default_address\n   where shop_id = v_tok.shop_id and id = p_customer_id\n  returning * into v_c;\n  return api_customer_json(v_c);\nend;\n$$;\n\n-- 削除（退会）。注文は残る（管理画面の削除と同じ）。会員のクーポン・ログインの記録は会員と一緒に消える\ncreate or replace function api_customer_delete(p_token_hash text, p_customer_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:write');\n  delete from customers where shop_id = v_tok.shop_id and id = p_customer_id;\n  if not found then raise exception 'not_found'; end if;\n  return jsonb_build_object('deleted', true, 'id', p_customer_id);\nend;\n$$;\n\n-- ---------- 実行権限（service_role だけ。Worker は src/db/privileged.ts の apiRpc から呼ぶ） ----------\nrevoke execute on function api_coupons_list(text, text, boolean, integer, integer) from public, anon, authenticated;\nrevoke execute on function api_coupon_get(text, uuid, text) from public, anon, authenticated;\nrevoke execute on function api_coupon_create(text, jsonb) from public, anon, authenticated;\nrevoke execute on function api_coupon_update(text, uuid, jsonb) from public, anon, authenticated;\nrevoke execute on function api_coupon_delete(text, uuid) from public, anon, authenticated;\nrevoke execute on function api_coupon_grants_list(text, uuid, text, integer, integer) from public, anon, authenticated;\nrevoke execute on function api_coupon_grants_issue(text, uuid, uuid[], integer) from public, anon, authenticated;\nrevoke execute on function api_coupon_grant_revoke(text, uuid) from public, anon, authenticated;\nrevoke execute on function api_customers_list(text, text, text, integer, integer) from public, anon, authenticated;\nrevoke execute on function api_customer_get(text, uuid) from public, anon, authenticated;\nrevoke execute on function api_customer_create(text, jsonb) from public, anon, authenticated;\nrevoke execute on function api_customer_update(text, uuid, jsonb) from public, anon, authenticated;\nrevoke execute on function api_customer_delete(text, uuid) from public, anon, authenticated;\ngrant execute on function api_coupons_list(text, text, boolean, integer, integer) to service_role;\ngrant execute on function api_coupon_get(text, uuid, text) to service_role;\ngrant execute on function api_coupon_create(text, jsonb) to service_role;\ngrant execute on function api_coupon_update(text, uuid, jsonb) to service_role;\ngrant execute on function api_coupon_delete(text, uuid) to service_role;\ngrant execute on function api_coupon_grants_list(text, uuid, text, integer, integer) to service_role;\ngrant execute on function api_coupon_grants_issue(text, uuid, uuid[], integer) to service_role;\ngrant execute on function api_coupon_grant_revoke(text, uuid) to service_role;\ngrant execute on function api_customers_list(text, text, text, integer, integer) to service_role;\ngrant execute on function api_customer_get(text, uuid) to service_role;\ngrant execute on function api_customer_create(text, jsonb) to service_role;\ngrant execute on function api_customer_update(text, uuid, jsonb) to service_role;\ngrant execute on function api_customer_delete(text, uuid) to service_role;\n\ninsert into banto_migrations (version) values ('0036_api_coupons_customers');\n" },
  { version: "0037_api_image_upload", sql: "-- Banto 0037_api_image_upload: AI 用トークンで商品画像のファイルを送る（POST /api/v1/products/{id}/images/upload）。docs/api.md\n-- 前方専用。URL からの取り込み（api_image_add、0003）と違い、サムネイルと寸法も一緒に登録できる。\n-- Worker が中身を確かめて（先頭のバイトで種類を決め、5MB / サムネイル 1MB まで）ストレージに置いたあと、この関数で行を作る。\n-- 置き場所のキーは Worker が作るが、ここでも「このショップのこの商品の下」であること・サムネイルが本画像の隣であることを確かめる。\n\n-- 商品の JSON に画像のサムネイルと寸法を戻す（0005 で足したが、0008 の作り直しで落ちていた。ほかは 0008 と同じ）\ncreate or replace function api_product_json(p_product products, p_with_skus boolean default true)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_product.id, 'slug', p_product.slug, 'name', p_product.name, 'description', p_product.description,\n    'tags', to_jsonb(p_product.tags), 'brand', p_product.brand, 'attributes', p_product.attributes,\n    'category', (select api_category_json(c) from categories c where c.id = p_product.category_id),\n    'published', p_product.published, 'created_at', p_product.created_at, 'updated_at', p_product.updated_at,\n    'images', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'storage_key', i.storage_key, 'thumb_key', i.thumb_key,\n                                                             'width', i.width, 'height', i.height, 'sort_order', i.sort_order) order by i.sort_order), '[]'::jsonb)\n                 from product_images i where i.product_id = p_product.id),\n    'skus', case when p_with_skus then\n      (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'code', k.code, 'name', k.name, 'price_jpy', k.price_jpy,\n                                                     'compare_at_price_jpy', k.compare_at_price_jpy, 'options', k.options, 'gtin', k.gtin,\n                                                     'available', coalesce(inv.available, 0)) order by k.created_at), '[]'::jsonb)\n         from skus k left join inventory inv on inv.sku_id = k.id where k.product_id = p_product.id)\n      else null end\n  );\n$$;\n\ncreate or replace function api_image_add_file(p_token_hash text, p_product_id uuid, p_storage_key text,\n                                              p_thumb_key text default null, p_width integer default null, p_height integer default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_sort integer; v_prefix text; v_id uuid;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  if not exists (select 1 from products where id = p_product_id and shop_id = v_tok.shop_id) then raise exception 'not_found'; end if;\n  v_prefix := 'shops/' || v_tok.shop_id::text || '/products/' || p_product_id::text || '/';\n  if p_storage_key is null or left(p_storage_key, length(v_prefix)) <> v_prefix\n     or substr(p_storage_key, length(v_prefix) + 1) !~ '^[0-9a-f]{24}\\.(jpg|png|webp|gif|avif)$' then\n    raise exception 'invalid_storage_key';\n  end if;\n  if p_thumb_key is not null and (left(p_thumb_key, length(v_prefix)) <> v_prefix\n     or substr(p_thumb_key, length(v_prefix) + 1) !~ ('^' || substr(p_storage_key, length(v_prefix) + 1, 24) || '\\.thumb\\.(jpg|png|webp|gif|avif)$')) then\n    raise exception 'invalid_thumb_key';\n  end if;\n  if (p_width is null) <> (p_height is null) or p_width not between 1 and 20000 or p_height not between 1 and 20000 then\n    raise exception 'invalid_dimensions';\n  end if;\n  select coalesce(max(sort_order), -1) + 1 into v_sort from product_images where product_id = p_product_id;\n  insert into product_images (shop_id, product_id, storage_key, thumb_key, width, height, sort_order)\n  values (v_tok.shop_id, p_product_id, p_storage_key, p_thumb_key, p_width, p_height, v_sort)\n  returning id into v_id;\n  -- products:write だけのトークンでも結果を返せるよう、api_product_get（products:read）ではなく整形だけを使う\n  return jsonb_build_object('image_id', v_id, 'product', (select api_product_json(p) from products p where p.id = p_product_id));\nend;\n$$;\nrevoke execute on function api_image_add_file(text, uuid, text, text, integer, integer) from public, anon, authenticated;\ngrant execute on function api_image_add_file(text, uuid, text, text, integer, integer) to service_role;\n\ninsert into banto_migrations (version) values ('0037_api_image_upload');\n" },
  { version: "0038_site_settings", sql: "-- Banto 0038_site_settings: デプロイ全体（運営者の Cloudflare アカウント）の設定。docs/knowledge/02-decisions.md 2026-10-19\n-- 前方専用。ショップごとの設定（shops.settings）では表せない「このデプロイがどの環境で動いているか」を持つ汎用の器（CLAUDE.md §7 の基準 (2)）。\n--\n--   workers_plan … 'free'（既定。Cloudflare Workers の無料プラン）/ 'paid'（Workers Paid、または Node で動かすとき）\n--                  裏で動く処理（Cron）が 1 回に進める量を、この値で決める（無料プランは 1 回の通信の回数の上限が小さい）\n--\n-- 1 行だけの表。読み書きは組織の owner / admin（/admin/update と同じ人）。書き込みは site_settings_set だけで、鍵と値を確かめる。\n\ncreate table banto_site_settings (\n  id boolean primary key default true check (id),\n  settings jsonb not null default '{}'::jsonb check (jsonb_typeof(settings) = 'object'),\n  updated_at timestamptz not null default now()\n);\ninsert into banto_site_settings (id) values (true);\n\nalter table banto_site_settings enable row level security;\ncreate policy site_settings_org_admin_select on banto_site_settings for select\n  using (exists (select 1 from org_members m where m.user_id = auth.uid() and m.role in ('owner', 'admin')));\n\n-- 鍵ごとに値を確かめて 1 つ変える。戻り値は変えたあとの settings\ncreate or replace function site_settings_set(p_key text, p_value jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_out jsonb;\nbegin\n  if not exists (select 1 from org_members m where m.user_id = auth.uid() and m.role in ('owner', 'admin')) then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n  case p_key\n    when 'workers_plan' then\n      if p_value is null or jsonb_typeof(p_value) <> 'string' or p_value #>> '{}' not in ('free', 'paid') then raise exception 'invalid_value'; end if;\n    else raise exception 'invalid_key';\n  end case;\n  update banto_site_settings set settings = settings || jsonb_build_object(p_key, p_value), updated_at = now() where id\n  returning settings into v_out;\n  return v_out;\nend;\n$$;\nrevoke execute on function site_settings_set(text, jsonb) from public, anon;\ngrant execute on function site_settings_set(text, jsonb) to authenticated, service_role;\n\n-- 中で使う: Workers のプラン（未設定は free）\ncreate or replace function banto_workers_plan()\nreturns text\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce((select settings->>'workers_plan' from banto_site_settings where id), 'free');\n$$;\nrevoke execute on function banto_workers_plan() from public, anon, authenticated;\n\ninsert into banto_migrations (version) values ('0038_site_settings');\n" },
  { version: "0039_mod_woo_import_queue", sql: "-- Banto 0039_mod_woo_import_queue: 同梱モジュール woo_import の「画像を裏で取り込む」。docs/woo-import.md\n-- 前方専用。ブラウザで画像の URL の一覧を予約し、Cron（src/modules/woo-import/job.ts）が少しずつ取得 → ストレージ → 商品に紐づける。\n-- ページを閉じても進む。1 回に進める枚数はデプロイの設定（0038 の workers_plan）で決める: free 12 枚 / paid 150 枚。\n--\n-- 予約に置くのは公開の画像の URL だけ（WooCommerce の API キーは置かない。CLAUDE.md §1-5）。\n-- 状態: pending（待ち）→ running（取り出し済み。10 分のリース。切れたらまた取り出す）→ done / failed（理由は last_error）。\n-- 一時的な失敗（つながらない・429・5xx・保存の失敗）は 3 回までやり直す（10 分・20 分あけて）。\n\ncreate table image_import_jobs (\n  id bigint generated always as identity primary key,\n  shop_id uuid not null references shops(id) on delete cascade,\n  product_id uuid not null references products(id) on delete cascade,\n  url text not null check (url ~ '^https?://' and length(url) <= 2000),\n  status text not null default 'pending' check (status in ('pending', 'running', 'done', 'failed')),\n  attempts integer not null default 0,\n  next_attempt_at timestamptz not null default now(),\n  last_error text check (last_error is null or last_error ~ '^[a-z0-9_]{1,40}$'),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (product_id, url)\n);\ncreate index image_import_jobs_due on image_import_jobs (next_attempt_at, id) where status in ('pending', 'running');\ncreate index on image_import_jobs (shop_id, status);\ncreate trigger image_import_jobs_updated_at before update on image_import_jobs for each row execute function banto_set_updated_at();\n\nalter table image_import_jobs enable row level security;\n-- 読めるのは商品を扱う人だけ（書き込みは下の関数だけ）\ncreate policy image_import_jobs_catalog_select on image_import_jobs for select using (banto_shop_perm(shop_id, 'catalog'));\n\n-- 1 回に進める枚数（無料プランは 1 回の Cron の通信が 50 回まで: 1 枚で取得と保存の 2 回、ほかのジョブの分を残す）\ncreate or replace function banto_image_import_batch()\nreturns integer language sql stable security definer set search_path = public as $$\n  select case banto_workers_plan() when 'paid' then 150 else 12 end;\n$$;\nrevoke execute on function banto_image_import_batch() from public, anon, authenticated;\n\n-- ---------- 管理画面（authenticated、catalog の項目） ----------\n-- p_items: [{ slug, urls: [{ url, tag }] }]（1 回 100 商品・1 商品 50 枚まで）。tag は Worker が URL から作る置き場所のキーの目印（/wc-<hash>.）。\n-- 商品の画像にその目印のキーが既にあれば取り込み済みとして飛ばす。予約の取り込み済み（done）はそのまま、失敗（failed）は待ちに戻す。\n-- Banto に無い商品は missing に数える\ncreate or replace function image_import_enqueue(p_shop_id uuid, p_items jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_item jsonb; v_u jsonb; v_pid uuid; v_url text; v_tag text; v_n integer := 0; v_skipped integer := 0; v_missing integer := 0; v_hit integer;\nbegin\n  if not banto_shop_perm(p_shop_id, 'catalog') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 100 then raise exception 'invalid_items'; end if;\n  for v_item in select e from jsonb_array_elements(p_items) e loop\n    if jsonb_typeof(v_item->'urls') <> 'array' or jsonb_array_length(v_item->'urls') > 50 then raise exception 'invalid_items'; end if;\n    select id into v_pid from products where shop_id = p_shop_id and slug = v_item->>'slug';\n    if v_pid is null then v_missing := v_missing + 1; continue; end if;\n    for v_u in select e from jsonb_array_elements(v_item->'urls') e loop\n      v_url := v_u->>'url';\n      v_tag := v_u->>'tag';\n      if v_url is null or v_url !~ '^https?://' or length(v_url) > 2000 or v_tag is null or v_tag !~ '^/wc-[0-9a-z]{1,13}\\.$' then\n        v_skipped := v_skipped + 1;\n        continue;\n      end if;\n      if exists (select 1 from product_images where product_id = v_pid and position(v_tag in storage_key) > 0) then\n        v_skipped := v_skipped + 1;\n        continue;\n      end if;\n      insert into image_import_jobs (shop_id, product_id, url) values (p_shop_id, v_pid, v_url)\n      on conflict (product_id, url) do update set status = 'pending', attempts = 0, next_attempt_at = now(), last_error = null\n        where image_import_jobs.status = 'failed';\n      get diagnostics v_hit = row_count;\n      if v_hit > 0 then v_n := v_n + 1; else v_skipped := v_skipped + 1; end if;\n    end loop;\n  end loop;\n  return jsonb_build_object('queued', v_n, 'skipped', v_skipped, 'missing', v_missing);\nend;\n$$;\n\n-- 進み具合と、取り込めなかった画像（新しい順に 2,000 件まで）\ncreate or replace function image_import_summary(p_shop_id uuid)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when banto_shop_perm(p_shop_id, 'catalog') then jsonb_build_object(\n    'pending', (select count(*) from image_import_jobs where shop_id = p_shop_id and status = 'pending'),\n    'running', (select count(*) from image_import_jobs where shop_id = p_shop_id and status = 'running'),\n    'done', (select count(*) from image_import_jobs where shop_id = p_shop_id and status = 'done'),\n    'failed', (select count(*) from image_import_jobs where shop_id = p_shop_id and status = 'failed'),\n    'last_done_at', (select max(updated_at) from image_import_jobs where shop_id = p_shop_id and status = 'done'),\n    'batch', banto_image_import_batch(),\n    'plan', banto_workers_plan(),\n    'failures', (select coalesce(jsonb_agg(jsonb_build_object('slug', p.slug, 'url', j.url, 'code', j.last_error) order by j.updated_at desc), '[]'::jsonb)\n                   from (select * from image_import_jobs where shop_id = p_shop_id and status = 'failed' order by updated_at desc limit 2000) j\n                   join products p on p.id = j.product_id)\n  ) end;\n$$;\n\n-- 待ちと失敗を消す（取り出し中のものはそのまま終わる）。取り込み済みの記録は残す（次に予約したとき飛ばすため）\ncreate or replace function image_import_cancel(p_shop_id uuid)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer;\nbegin\n  if not banto_shop_perm(p_shop_id, 'catalog') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  delete from image_import_jobs where shop_id = p_shop_id and status in ('pending', 'failed');\n  get diagnostics v_n = row_count;\n  return v_n;\nend;\n$$;\n\n-- 失敗したものを待ちに戻す\ncreate or replace function image_import_retry(p_shop_id uuid)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer;\nbegin\n  if not banto_shop_perm(p_shop_id, 'catalog') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  update image_import_jobs set status = 'pending', attempts = 0, next_attempt_at = now(), last_error = null where shop_id = p_shop_id and status = 'failed';\n  get diagnostics v_n = row_count;\n  return v_n;\nend;\n$$;\n\n-- ---------- Cron（service_role） ----------\n-- 期限の来た待ちと、リースの切れた取り出し中を、決まった枚数だけ取り出す\ncreate or replace function image_import_claim()\nreturns table (id bigint, shop_id uuid, product_id uuid, url text)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'image_import_claim: service_role only' using errcode = '42501';\n  end if;\n  return query\n  with picked as (\n    select j.id from image_import_jobs j\n      join shops s on s.id = j.shop_id\n     where j.status in ('pending', 'running') and j.next_attempt_at <= now()\n       -- モジュールを OFF にしたショップの予約は進めない（ON に戻せば続きから）\n       and s.settings->'modules'->'woo_import' = 'true'::jsonb\n     order by j.next_attempt_at, j.id\n     limit banto_image_import_batch()\n     for update of j skip locked\n  )\n  update image_import_jobs j\n     set status = 'running', attempts = j.attempts + 1, next_attempt_at = now() + interval '10 minutes'\n    from picked where j.id = picked.id\n  returning j.id, j.shop_id, j.product_id, j.url;\nend;\n$$;\n\n-- 結果を書く: [{ id, storage_key }] か [{ id, error }]。成功は商品の画像の末尾に足す（同じキーが既にあれば足さない）\ncreate or replace function image_import_finish(p_results jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_r jsonb; v_j image_import_jobs%rowtype; v_key text; v_err text; v_done integer := 0; v_failed integer := 0; v_retry integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'image_import_finish: service_role only' using errcode = '42501';\n  end if;\n  for v_r in select e from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) e loop\n    select * into v_j from image_import_jobs where id = (v_r->>'id')::bigint and status = 'running' for update;\n    if not found then continue; end if;\n    v_key := v_r->>'storage_key';\n    -- 置き場所はこのショップのこの商品の下だけ（違えば登録しない）\n    if v_key is not null and left(v_key, length('shops/' || v_j.shop_id || '/products/' || v_j.product_id || '/wc-')) <> 'shops/' || v_j.shop_id || '/products/' || v_j.product_id || '/wc-' then\n      v_key := null;\n      v_r := v_r || '{\"error\":\"invalid_storage_key\"}'::jsonb;\n    end if;\n    if v_key is not null then\n      if exists (select 1 from products where id = v_j.product_id)\n         and not exists (select 1 from product_images where product_id = v_j.product_id and storage_key = v_key) then\n        insert into product_images (shop_id, product_id, storage_key, sort_order)\n        values (v_j.shop_id, v_j.product_id, v_key, (select coalesce(max(sort_order), -1) + 1 from product_images where product_id = v_j.product_id));\n      end if;\n      update image_import_jobs set status = 'done', last_error = null where id = v_j.id;\n      v_done := v_done + 1;\n    else\n      v_err := coalesce(nullif(v_r->>'error', ''), 'error');\n      if v_err !~ '^[a-z0-9_]{1,40}$' then v_err := 'error'; end if;\n      if v_j.attempts < 3 and (v_err in ('fetch_failed', 'storage', 'http_429', 'http_408') or v_err ~ '^http_5') then\n        update image_import_jobs set status = 'pending', last_error = v_err, next_attempt_at = now() + make_interval(mins => 10 * v_j.attempts) where id = v_j.id;\n        v_retry := v_retry + 1;\n      else\n        update image_import_jobs set status = 'failed', last_error = v_err where id = v_j.id;\n        v_failed := v_failed + 1;\n      end if;\n    end if;\n  end loop;\n  return jsonb_build_object('done', v_done, 'retry', v_retry, 'failed', v_failed);\nend;\n$$;\n\nrevoke execute on function image_import_enqueue(uuid, jsonb) from public, anon;\nrevoke execute on function image_import_summary(uuid) from public, anon;\nrevoke execute on function image_import_cancel(uuid) from public, anon;\nrevoke execute on function image_import_retry(uuid) from public, anon;\ngrant execute on function image_import_enqueue(uuid, jsonb) to authenticated, service_role;\ngrant execute on function image_import_summary(uuid) to authenticated, service_role;\ngrant execute on function image_import_cancel(uuid) to authenticated, service_role;\ngrant execute on function image_import_retry(uuid) to authenticated, service_role;\nrevoke execute on function image_import_claim() from public, anon, authenticated;\nrevoke execute on function image_import_finish(jsonb) from public, anon, authenticated;\ngrant execute on function image_import_claim() to service_role;\ngrant execute on function image_import_finish(jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0039_mod_woo_import_queue');\n" },
  { version: "0040_mod_woo_import_resolve", sql: "-- Banto 0040_mod_woo_import_resolve: 大きすぎる画像を管理画面のブラウザで縮小して取り込んだとき、裏の取り込みの予約を「取り込み済み」にする。docs/woo-import.md\n-- 前方専用。Cron は 5MB を超える画像を too_large で失敗にする（サーバーでは縮小しない）。管理画面がブラウザで縮小して送ったら、\n-- その URL の予約（失敗・待ち）を done にして、「取り込めなかった画像」から外す。\n\ncreate or replace function image_import_resolve(p_shop_id uuid, p_product_id uuid, p_url text)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer;\nbegin\n  if not banto_shop_perm(p_shop_id, 'catalog') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  update image_import_jobs set status = 'done', last_error = null\n   where shop_id = p_shop_id and product_id = p_product_id and url = p_url and status in ('pending', 'failed');\n  get diagnostics v_n = row_count;\n  return v_n;\nend;\n$$;\nrevoke execute on function image_import_resolve(uuid, uuid, text) from public, anon;\ngrant execute on function image_import_resolve(uuid, uuid, text) to authenticated, service_role;\n\ninsert into banto_migrations (version) values ('0040_mod_woo_import_resolve');\n" },
  { version: "0041_storefront_settings", sql: "-- Banto 0041_storefront_settings: お店の画面の使い方（storefront）と GA4（analytics）を、お客様の画面に渡す settings に足す。docs/storefront.md\n-- 前方専用。値の形は管理画面と src/storefront/mode.ts・src/modules/ga4/ga4.ts が確かめる。ここは公開してよい鍵の allowlist だけ。\n--\n--   storefront.mode        'full'（既定）/ 'checkout'（商品の一覧と詳細は外のサイト、カートと購入は Banto）/ 'off'（Banto の画面を使わない）\n--   storefront.site_url    使わない画面を開かれたときの転送先（https）\n--   storefront.product_url 商品ページの転送先（{slug} を商品のスラッグに置き換える。任意）\n--   analytics.ga4_id       GA4 の測定 ID（G-XXXXXXXX）。同梱モジュール ga4 が ON のショップのお店の画面だけに入れる（docs/ga4.md）\n--\n-- どれもお客様の画面の HTML や転送先に出る値なので、公開して困るものではない。\n\ncreate or replace function banto_shop_public_settings(p jsonb)\nreturns jsonb language sql immutable as $$\n  select coalesce((select jsonb_object_agg(k, v) from jsonb_each(case when jsonb_typeof(p) = 'object' then p else '{}'::jsonb end) e(k, v)\n                    where k in ('theme', 'theme_settings', 'notice', 'shipping', 'modules', 'members_enabled', 'members_password',\n                                'checkout_terms', 'delivery_time', 'store_tryon', 'receipt', 'product_fields',\n                                'tax_rate', 'tax_rate_reduced', 'tax_rounding', 'storefront', 'analytics')), '{}'::jsonb)\n      || case when jsonb_typeof(p->'headless') = 'object'\n              then jsonb_build_object('headless', jsonb_build_object('return_origins', coalesce(p->'headless'->'return_origins', '[]'::jsonb)))\n              else '{}'::jsonb end\n      || case when jsonb_typeof(p->'oauth') = 'object'\n              then jsonb_build_object('oauth', coalesce((\n                     select jsonb_object_agg(k, coalesce((select jsonb_object_agg(k2, v2) from jsonb_each(v) f(k2, v2) where k2 in ('client_id', 'bot_prompt')), '{}'::jsonb))\n                       from jsonb_each(p->'oauth') e(k, v) where jsonb_typeof(v) = 'object'), '{}'::jsonb))\n              else '{}'::jsonb end;\n$$;\nrevoke execute on function banto_shop_public_settings(jsonb) from public, anon, authenticated;\n\ninsert into banto_migrations (version) values ('0041_storefront_settings');\n" },
  { version: "0042_product_extra_categories", sql: "-- Banto 0042_product_extra_categories: 商品の追加カテゴリー（複数）と、クーポンのタグの条件。\n-- 前方専用。人間の決定 2026-10-19（docs/knowledge/02-decisions.md）。\n--   主カテゴリー（products.category_id、1 つ）はそのまま。パンくず・canonical・商品フィードの分類に使う。\n--   追加カテゴリー（products.extra_category_ids）は「売り場の棚」。お店の画面と公開 API のカテゴリーの絞り込みと、\n--   クーポンのカテゴリーの条件で、主カテゴリーと同じに扱う（どれか 1 つが合えば。src/products/categories.ts の productCategoryIds）。\n--   表ではなく配列の列にしたのは、お店の画面がキャッシュした商品の行をメモリで絞り込むため（DB 往復を増やさない）。\n--   同じショップのカテゴリーだけ・カテゴリーを消したら外す、はトリガーで保証する。\n-- クーポンの条件に tags / exclude_tags（商品のタグ）を足す。判定は src/commerce/discounts.ts だけ。\n\n-- ---------- 列 ----------\nalter table products\n  add column extra_category_ids uuid[] not null default '{}' check (cardinality(extra_category_ids) <= 20);\ncreate index products_extra_category_ids_idx on products using gin (extra_category_ids);\n\n-- 重複・null・主カテゴリーと同じものを外し、新しく足したものが同じショップのカテゴリーかを確かめる。\n-- 外すだけの変更（カテゴリーの削除で消えた id）は確かめない（ショップの削除の連鎖の途中でも止めない）\ncreate or replace function banto_product_extra_categories()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\ndeclare v_before uuid[] := '{}'; v_added uuid[];\nbegin\n  if tg_op = 'UPDATE' then v_before := old.extra_category_ids; end if;\n  select coalesce(array_agg(id order by ord), '{}') into new.extra_category_ids\n    from (select id, min(ord) as ord from unnest(new.extra_category_ids) with ordinality u(id, ord)\n           where id is not null and id is distinct from new.category_id group by id) x;\n  select coalesce(array_agg(id), '{}') into v_added\n    from unnest(new.extra_category_ids) id\n   where not (id = any(v_before));\n  if cardinality(v_added) > 0\n     and (select count(*) from categories where shop_id = new.shop_id and id = any(v_added)) <> cardinality(v_added) then\n    raise exception 'category_not_found';\n  end if;\n  return new;\nend;\n$$;\ncreate trigger products_extra_categories before insert or update of extra_category_ids, category_id on products\n  for each row execute function banto_product_extra_categories();\n\n-- カテゴリーを消したら、追加カテゴリーからも外す（主カテゴリーは外部キーの on delete set null で外れる）\ncreate or replace function banto_category_deleted()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  update products set extra_category_ids = array_remove(extra_category_ids, old.id)\n   where shop_id = old.shop_id and extra_category_ids @> array[old.id];\n  return old;\nend;\n$$;\ncreate trigger categories_deleted after delete on categories\n  for each row execute function banto_category_deleted();\n\nrevoke all on function banto_product_extra_categories() from public, anon, authenticated;\nrevoke all on function banto_category_deleted() from public, anon, authenticated;\n\n-- ---------- AI 用 API（0008 / 0037 の同名関数を置き換える。権限は既存のまま） ----------\n-- 追加カテゴリーの指定（slug の配列）→ id の配列。null・空なら空。見つからなければ例外\ncreate or replace function api_category_refs(p_shop_id uuid, p_slugs jsonb)\nreturns uuid[]\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_slug text; v_out uuid[] := '{}';\nbegin\n  if p_slugs is null or jsonb_typeof(p_slugs) = 'null' then return v_out; end if;\n  if jsonb_typeof(p_slugs) <> 'array' or jsonb_array_length(p_slugs) > 20\n     or exists (select 1 from jsonb_array_elements(p_slugs) e where jsonb_typeof(e) <> 'string') then\n    raise exception 'invalid_extra_categories';\n  end if;\n  for v_slug in select value from jsonb_array_elements_text(p_slugs) loop\n    v_out := v_out || api_category_ref(p_shop_id, v_slug);\n  end loop;\n  return array_remove(v_out, null);\nend;\n$$;\nrevoke execute on function api_category_refs(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function api_category_refs(uuid, jsonb) to service_role;\n\ncreate or replace function api_product_json(p_product products, p_with_skus boolean default true)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_product.id, 'slug', p_product.slug, 'name', p_product.name, 'description', p_product.description,\n    'tags', to_jsonb(p_product.tags), 'brand', p_product.brand, 'attributes', p_product.attributes,\n    'category', (select api_category_json(c) from categories c where c.id = p_product.category_id),\n    'extra_categories', (select coalesce(jsonb_agg(api_category_json(c) order by x.ord), '[]'::jsonb)\n                           from unnest(p_product.extra_category_ids) with ordinality x(id, ord) join categories c on c.id = x.id),\n    'published', p_product.published, 'created_at', p_product.created_at, 'updated_at', p_product.updated_at,\n    'images', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'storage_key', i.storage_key, 'thumb_key', i.thumb_key,\n                                                             'width', i.width, 'height', i.height, 'sort_order', i.sort_order) order by i.sort_order), '[]'::jsonb)\n                 from product_images i where i.product_id = p_product.id),\n    'skus', case when p_with_skus then\n      (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'code', k.code, 'name', k.name, 'price_jpy', k.price_jpy,\n                                                     'compare_at_price_jpy', k.compare_at_price_jpy, 'options', k.options, 'gtin', k.gtin,\n                                                     'available', coalesce(inv.available, 0)) order by k.created_at), '[]'::jsonb)\n         from skus k left join inventory inv on inv.sku_id = k.id where k.product_id = p_product.id)\n      else null end\n  );\n$$;\n\ncreate or replace function api_product_create(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_p products%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  insert into products (shop_id, slug, name, description, published, tags, brand, attributes, category_id, extra_category_ids)\n  values (v_tok.shop_id, p_values->>'slug', p_values->>'name', nullif(btrim(coalesce(p_values->>'description', '')), ''),\n          coalesce((p_values->>'published')::boolean, false), banto_normalize_tags(p_values->'tags'),\n          nullif(btrim(coalesce(p_values->>'brand', '')), ''), banto_clean_object(p_values->'attributes', 50),\n          api_category_ref(v_tok.shop_id, p_values->>'category'), api_category_refs(v_tok.shop_id, p_values->'extra_categories'))\n  returning * into v_p;\n  perform enqueue_hook(v_tok.shop_id, 'product.updated', jsonb_build_object('product_id', v_p.id, 'shop_id', v_tok.shop_id, 'slug', v_p.slug, 'name', v_p.name, 'published', v_p.published));\n  return api_product_json(v_p, true);\nend;\n$$;\n\ncreate or replace function api_product_update(p_token_hash text, p_product_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_p products%rowtype;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  update products set\n    slug = coalesce(p_values->>'slug', slug),\n    name = coalesce(nullif(btrim(p_values->>'name'), ''), name),\n    description = case when p_values ? 'description' then nullif(btrim(p_values->>'description'), '') else description end,\n    published = coalesce((p_values->>'published')::boolean, published),\n    tags = case when p_values ? 'tags' then banto_normalize_tags(p_values->'tags') else tags end,\n    brand = case when p_values ? 'brand' then nullif(btrim(coalesce(p_values->>'brand', '')), '') else brand end,\n    attributes = case when p_values ? 'attributes' then banto_clean_object(p_values->'attributes', 50) else attributes end,\n    category_id = case when p_values ? 'category' then api_category_ref(v_tok.shop_id, p_values->>'category') else category_id end,\n    extra_category_ids = case when p_values ? 'extra_categories' then api_category_refs(v_tok.shop_id, p_values->'extra_categories') else extra_category_ids end\n  where id = p_product_id and shop_id = v_tok.shop_id\n  returning * into v_p;\n  if not found then raise exception 'not_found'; end if;\n  perform enqueue_hook(v_tok.shop_id, 'product.updated', jsonb_build_object('product_id', v_p.id, 'shop_id', v_tok.shop_id, 'slug', v_p.slug, 'name', v_p.name, 'published', v_p.published));\n  return api_product_json(v_p, true);\nend;\n$$;\n\n-- ---------- 一括取り込み（0024 を置き換える。extra_category_slugs を受け付ける。権限は既存のまま） ----------\ncreate or replace function import_catalog(p_shop_id uuid, p_batch jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_sku jsonb; v_cat_id uuid; v_extra uuid[]; v_parent uuid; v_pid uuid; v_kid uuid; v_existing uuid; v_avail integer;\n  v_price integer; v_compare integer; v_gtin text; v_created boolean;\n  v_n_cat integer := 0; v_p_new integer := 0; v_p_upd integer := 0; v_k_new integer := 0; v_k_upd integer := 0;\n  l_p_new integer; l_k_new integer; l_k_upd integer;\n  v_errors jsonb := '[]'::jsonb;\n  v_overwrite boolean := coalesce((p_batch->>'overwrite_stock')::boolean, true);\nbegin\n  if not banto_shop_perm(p_shop_id, 'catalog') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n\n  -- カテゴリー（親が先）\n  for v_row in select * from jsonb_array_elements(coalesce(p_batch->'categories', '[]'::jsonb)) loop\n    v_parent := null;\n    if coalesce(v_row->>'parent_slug', '') <> '' then\n      select id into v_parent from categories where shop_id = p_shop_id and slug = v_row->>'parent_slug';\n    end if;\n    insert into categories (shop_id, slug, name, parent_id, sort_order)\n    values (p_shop_id, v_row->>'slug', left(btrim(v_row->>'name'), 100), v_parent, coalesce((v_row->>'sort_order')::integer, 0))\n    on conflict (shop_id, slug) do update set name = excluded.name, parent_id = excluded.parent_id;\n    v_n_cat := v_n_cat + 1;\n  end loop;\n\n  -- 商品と SKU\n  for v_row in select * from jsonb_array_elements(coalesce(p_batch->'products', '[]'::jsonb)) loop\n    begin\n      l_p_new := 0; l_k_new := 0; l_k_upd := 0;\n      v_cat_id := null;\n      if coalesce(v_row->>'category_slug', '') <> '' then\n        select id into v_cat_id from categories where shop_id = p_shop_id and slug = v_row->>'category_slug';\n      end if;\n      -- 追加カテゴリー（slug の配列）。鍵が無ければ既存の値を変えない（古い取り込み画面から送られても消さない）。見つからない slug は飛ばす\n      v_extra := null;\n      if jsonb_typeof(v_row->'extra_category_slugs') = 'array' then\n        select coalesce(array_agg(c.id order by e.ord), '{}') into v_extra\n          from jsonb_array_elements_text(v_row->'extra_category_slugs') with ordinality e(slug, ord)\n          join categories c on c.shop_id = p_shop_id and c.slug = e.slug;\n        v_extra := v_extra[1:20];\n      end if;\n      select id into v_pid from products where shop_id = p_shop_id and slug = v_row->>'slug';\n      if v_pid is null then\n        insert into products (shop_id, slug, name, description, published, tags, brand, attributes, category_id, extra_category_ids)\n        values (p_shop_id, v_row->>'slug', left(btrim(v_row->>'name'), 200), nullif(btrim(coalesce(v_row->>'description', '')), ''),\n                coalesce((v_row->>'published')::boolean, false), banto_normalize_tags(v_row->'tags'),\n                nullif(left(btrim(coalesce(v_row->>'brand', '')), 100), ''), banto_clean_object(v_row->'attributes', 200), v_cat_id, coalesce(v_extra, '{}'))\n        returning id into v_pid;\n        l_p_new := 1;\n      else\n        -- カスタム項目は既存の値に上書きでマージする（取り込み元に無い項目を消さない）\n        update products set\n          name = left(btrim(v_row->>'name'), 200),\n          description = nullif(btrim(coalesce(v_row->>'description', '')), ''),\n          published = coalesce((v_row->>'published')::boolean, published),\n          tags = banto_normalize_tags(v_row->'tags'),\n          brand = nullif(left(btrim(coalesce(v_row->>'brand', '')), 100), ''),\n          attributes = attributes || banto_clean_object(v_row->'attributes', 200),\n          category_id = v_cat_id,\n          extra_category_ids = coalesce(v_extra, extra_category_ids)\n        where id = v_pid;\n      end if;\n\n      for v_sku in select * from jsonb_array_elements(coalesce(v_row->'skus', '[]'::jsonb)) loop\n        v_price := (v_sku->>'price_jpy')::integer;\n        v_compare := (v_sku->>'compare_at_price_jpy')::integer;\n        if v_compare is not null and v_compare <= v_price then v_compare := null; end if;\n        v_gtin := nullif(btrim(coalesce(v_sku->>'gtin', '')), '');\n        if v_gtin is not null and v_gtin !~ '^([0-9]{8}|[0-9]{12,14})$' then v_gtin := null; end if;\n        select id, product_id into v_kid, v_existing from skus where shop_id = p_shop_id and code = v_sku->>'code';\n        v_created := v_kid is null;\n        if v_created then\n          insert into skus (shop_id, product_id, code, name, price_jpy, compare_at_price_jpy, gtin, options)\n          values (p_shop_id, v_pid, v_sku->>'code', nullif(left(btrim(coalesce(v_sku->>'name', '')), 200), ''), v_price, v_compare, v_gtin,\n                  banto_clean_object(v_sku->'options', 5))\n          returning id into v_kid;\n          l_k_new := l_k_new + 1;\n        else\n          if v_existing <> v_pid then raise exception 'sku_belongs_to_other_product: %', v_sku->>'code'; end if;\n          update skus set name = nullif(left(btrim(coalesce(v_sku->>'name', '')), 200), ''), price_jpy = v_price, compare_at_price_jpy = v_compare,\n                          gtin = v_gtin, options = banto_clean_object(v_sku->'options', 5)\n           where id = v_kid;\n          l_k_upd := l_k_upd + 1;\n        end if;\n        -- 在庫（inventory 行は skus の insert でトリガーが作る）\n        if v_sku ? 'available' and (v_created or v_overwrite) then\n          v_avail := greatest(0, coalesce((v_sku->>'available')::integer, 0));\n          update inventory set available = v_avail, updated_at = now() where sku_id = v_kid;\n        end if;\n      end loop;\n\n      perform enqueue_hook(p_shop_id, 'product.updated', jsonb_build_object('product_id', v_pid, 'shop_id', p_shop_id, 'slug', v_row->>'slug'));\n      -- 件数はこの商品が最後まで通ったときだけ数える（例外なら全部取り消されるため）\n      v_p_new := v_p_new + l_p_new; v_p_upd := v_p_upd + (1 - l_p_new); v_k_new := v_k_new + l_k_new; v_k_upd := v_k_upd + l_k_upd;\n    exception when others then\n      -- この商品だけ取り消して続ける（plpgsql の例外ブロックはセーブポイントとして働く）\n      v_errors := v_errors || jsonb_build_object('slug', v_row->>'slug', 'message', sqlerrm);\n    end;\n  end loop;\n\n  return jsonb_build_object('categories', v_n_cat, 'products_created', v_p_new, 'products_updated', v_p_upd,\n                            'skus_created', v_k_new, 'skus_updated', v_k_upd, 'errors', v_errors);\nend;\n$$;\n\n-- ---------- バックアップからの復元（0008 を置き換える。追加カテゴリーの id を振り直す） ----------\ncreate or replace function restore_catalog(p_shop_id uuid, p_data jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_cat_map jsonb := '{}'::jsonb; v_new uuid; v_n_cat integer := 0; v_n_prod integer := 0; v_n_sku integer := 0;\n  v_cats jsonb := coalesce(p_data->'categories', '[]'::jsonb);\n  v_products jsonb := coalesce(p_data->'products', '[]'::jsonb);\n  v_skus jsonb := coalesce(p_data->'skus', '[]'::jsonb);\nbegin\n  if jsonb_typeof(v_cats) <> 'array' or jsonb_typeof(v_products) <> 'array' or jsonb_typeof(v_skus) <> 'array' then raise exception 'invalid_export'; end if;\n  -- カテゴリー: まず親なしで作り、次に親を付ける（並び順に依存しない）\n  for v_row in select * from jsonb_array_elements(v_cats) loop\n    insert into categories (shop_id, slug, name, sort_order)\n    values (p_shop_id, v_row->>'slug', v_row->>'name', coalesce((v_row->>'sort_order')::integer, 0))\n    on conflict (shop_id, slug) do update set name = excluded.name\n    returning id into v_new;\n    v_cat_map := v_cat_map || jsonb_build_object(v_row->>'id', v_new::text);\n    v_n_cat := v_n_cat + 1;\n  end loop;\n  for v_row in select * from jsonb_array_elements(v_cats) loop\n    if v_cat_map ? (v_row->>'parent_id') then\n      update categories set parent_id = (v_cat_map->>(v_row->>'parent_id'))::uuid\n       where shop_id = p_shop_id and slug = v_row->>'slug';\n    end if;\n  end loop;\n  -- 商品\n  for v_row in select * from jsonb_array_elements(v_products) loop\n    update products set\n      tags = banto_normalize_tags(v_row->'tags'),\n      brand = nullif(btrim(coalesce(v_row->>'brand', '')), ''),\n      attributes = banto_clean_object(v_row->'attributes', 50),\n      category_id = case when v_cat_map ? (v_row->>'category_id') then (v_cat_map->>(v_row->>'category_id'))::uuid else null end,\n      -- 追加カテゴリー（0042）。戻らなかったカテゴリーは外す\n      extra_category_ids = coalesce((select array_agg((v_cat_map->>x.id)::uuid order by x.ord)\n                                       from jsonb_array_elements_text(case when jsonb_typeof(v_row->'extra_category_ids') = 'array' then v_row->'extra_category_ids' else '[]'::jsonb end)\n                                            with ordinality x(id, ord)\n                                      where v_cat_map ? x.id), '{}')\n     where shop_id = p_shop_id and slug = v_row->>'slug';\n    if found then v_n_prod := v_n_prod + 1; end if;\n  end loop;\n  -- SKU\n  for v_row in select * from jsonb_array_elements(v_skus) loop\n    update skus set\n      options = banto_clean_object(v_row->'options', 5),\n      gtin = nullif(btrim(coalesce(v_row->>'gtin', '')), ''),\n      compare_at_price_jpy = (v_row->>'compare_at_price_jpy')::integer\n     where shop_id = p_shop_id and code = v_row->>'code';\n    if found then v_n_sku := v_n_sku + 1; end if;\n  end loop;\n  return jsonb_build_object('categories', v_n_cat, 'products_extended', v_n_prod, 'skus_extended', v_n_sku);\nend;\n$$;\n\n-- ---------- クーポンの条件の検査（0036 を置き換える。tags / exclude_tags を受け付ける） ----------\ncreate or replace function banto_api_coupon_apply(p_shop_id uuid, p_c coupon_campaigns, p_values jsonb)\nreturns coupon_campaigns\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_key text; v_val jsonb; v_cond jsonb; v_ck text; v_cv jsonb; v_ids uuid[]; v_n integer; v_s text; v_tags text[];\nbegin\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key, v_val in select * from jsonb_each(p_values) loop\n    case v_key\n      when 'name' then\n        v_s := btrim(coalesce(v_val #>> '{}', ''));\n        if jsonb_typeof(v_val) <> 'string' or length(v_s) not between 1 and 100 then raise exception 'invalid_name'; end if;\n        p_c.name := v_s;\n      when 'code' then\n        if jsonb_typeof(v_val) = 'null' or btrim(v_val #>> '{}') = '' then p_c.code := null;\n        else\n          v_s := upper(btrim(v_val #>> '{}'));\n          if jsonb_typeof(v_val) <> 'string' or v_s !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$' then raise exception 'invalid_code'; end if;\n          p_c.code := v_s;\n        end if;\n      when 'kind' then\n        if jsonb_typeof(v_val) <> 'string' or v_val #>> '{}' not in ('percent', 'fixed', 'free_shipping') then raise exception 'invalid_kind'; end if;\n        p_c.kind := v_val #>> '{}';\n      when 'value' then\n        if jsonb_typeof(v_val) <> 'number' or (v_val #>> '{}') !~ '^\\d+$' then raise exception 'invalid_value'; end if;\n        p_c.value := (v_val #>> '{}')::integer;\n      when 'starts_at', 'ends_at' then\n        if jsonb_typeof(v_val) not in ('string', 'null') then raise exception 'invalid_%', v_key; end if;\n        begin\n          if v_key = 'starts_at' then p_c.starts_at := (v_val #>> '{}')::timestamptz; else p_c.ends_at := (v_val #>> '{}')::timestamptz; end if;\n        exception when others then raise exception 'invalid_%', v_key;\n        end;\n      when 'usage_limit', 'per_customer_limit', 'grant_valid_days' then\n        if jsonb_typeof(v_val) = 'null' then v_n := null;\n        elsif jsonb_typeof(v_val) = 'number' and (v_val #>> '{}') ~ '^\\d{1,7}$' then v_n := (v_val #>> '{}')::integer;\n        else raise exception 'invalid_%', v_key;\n        end if;\n        if v_key = 'usage_limit' then\n          if v_n is not null and v_n not between 1 and 100000 then raise exception 'invalid_usage_limit'; end if;\n          p_c.usage_limit := v_n;\n        elsif v_key = 'per_customer_limit' then\n          if v_n is not null and v_n not between 1 and 1000 then raise exception 'invalid_per_customer_limit'; end if;\n          p_c.per_customer_limit := v_n;\n        else\n          if v_n is not null and v_n not between 1 and 3650 then raise exception 'invalid_grant_valid_days'; end if;\n          p_c.grant_valid_days := v_n;\n        end if;\n      when 'combinable', 'active', 'claimable' then\n        if jsonb_typeof(v_val) <> 'boolean' then raise exception 'invalid_%', v_key; end if;\n        if v_key = 'combinable' then p_c.combinable := v_val::boolean;\n        elsif v_key = 'active' then p_c.active := v_val::boolean;\n        else p_c.claimable := v_val::boolean;\n        end if;\n      when 'audience' then\n        if jsonb_typeof(v_val) <> 'string' or v_val #>> '{}' not in ('public', 'members') then raise exception 'invalid_audience'; end if;\n        p_c.audience := v_val #>> '{}';\n      when 'auto_grant' then\n        if jsonb_typeof(v_val) = 'null' then p_c.auto_grant := null;\n        elsif jsonb_typeof(v_val) = 'string' and v_val #>> '{}' in ('first_login', 'after_purchase') then p_c.auto_grant := v_val #>> '{}';\n        else raise exception 'invalid_auto_grant';\n        end if;\n      when 'external_ref' then\n        if jsonb_typeof(v_val) = 'null' or btrim(v_val #>> '{}') = '' then p_c.external_ref := null;\n        elsif jsonb_typeof(v_val) = 'string' and length(btrim(v_val #>> '{}')) <= 100 then p_c.external_ref := btrim(v_val #>> '{}');\n        else raise exception 'invalid_external_ref';\n        end if;\n      when 'conditions' then\n        if jsonb_typeof(v_val) = 'null' then v_val := '{}'::jsonb; end if;\n        if jsonb_typeof(v_val) <> 'object' then raise exception 'invalid_conditions'; end if;\n        v_cond := '{}'::jsonb;\n        for v_ck, v_cv in select * from jsonb_each(v_val) loop\n          if jsonb_typeof(v_cv) = 'null' then continue; end if;\n          case v_ck\n            when 'product_ids', 'exclude_product_ids', 'category_ids', 'exclude_category_ids' then\n              if jsonb_typeof(v_cv) <> 'array' or jsonb_array_length(v_cv) > 200\n                 or exists (select 1 from jsonb_array_elements(v_cv) e\n                             where jsonb_typeof(e) <> 'string' or (e #>> '{}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              select coalesce(array_agg(distinct (e #>> '{}')::uuid), '{}') into v_ids from jsonb_array_elements(v_cv) e;\n              if v_ck in ('product_ids', 'exclude_product_ids') then\n                if (select count(*) from products where shop_id = p_shop_id and id = any(v_ids)) <> coalesce(array_length(v_ids, 1), 0) then raise exception 'invalid_conditions_unknown_products'; end if;\n              else\n                if (select count(*) from categories where shop_id = p_shop_id and id = any(v_ids)) <> coalesce(array_length(v_ids, 1), 0) then raise exception 'invalid_conditions_unknown_categories'; end if;\n              end if;\n              if coalesce(array_length(v_ids, 1), 0) > 0 then v_cond := v_cond || jsonb_build_object(v_ck, to_jsonb(v_ids)); end if;\n            when 'tags', 'exclude_tags' then\n              -- タグ（0042）。商品のタグと同じ正規化（src/products/tags.ts）。20 個まで\n              if jsonb_typeof(v_cv) <> 'array' or jsonb_array_length(v_cv) > 20\n                 or exists (select 1 from jsonb_array_elements(v_cv) e where jsonb_typeof(e) <> 'string') then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              v_tags := banto_normalize_tags(v_cv);\n              if coalesce(array_length(v_tags, 1), 0) > 0 then v_cond := v_cond || jsonb_build_object(v_ck, to_jsonb(v_tags)); end if;\n            when 'exclude_sale' then\n              if jsonb_typeof(v_cv) <> 'boolean' then raise exception 'invalid_conditions_exclude_sale'; end if;\n              if v_cv::boolean then v_cond := v_cond || jsonb_build_object('exclude_sale', true); end if;\n            when 'min_subtotal_jpy', 'max_subtotal_jpy', 'min_qty' then\n              -- 上限: 点数は 999、金額は 1 億円（管理画面と同じ）\n              v_n := 100000000;\n              if v_ck = 'min_qty' then v_n := 999; end if;\n              if jsonb_typeof(v_cv) <> 'number' or (v_cv #>> '{}') !~ '^\\d{1,9}$' or (v_cv #>> '{}')::integer > v_n then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              v_cond := v_cond || jsonb_build_object(v_ck, (v_cv #>> '{}')::integer);\n            else raise exception 'invalid_conditions_unknown_key';\n          end case;\n        end loop;\n        p_c.conditions := v_cond;\n      else raise exception 'invalid_field_%', left(v_key, 40);\n    end case;\n  end loop;\n  -- 種類と値の組み合わせ（テーブルの CHECK と同じ。わかりやすい理由で返す）\n  if p_c.kind = 'free_shipping' then p_c.value := 0;\n  elsif p_c.kind = 'percent' and p_c.value not between 1 and 100 then raise exception 'invalid_value';\n  elsif p_c.kind = 'fixed' and p_c.value not between 1 and 10000000 then raise exception 'invalid_value';\n  end if;\n  if p_c.starts_at is not null and p_c.ends_at is not null and p_c.starts_at >= p_c.ends_at then raise exception 'invalid_ends_at'; end if;\n  return p_c;\nend;\n$$;\n\ninsert into banto_migrations (version) values ('0042_product_extra_categories');\n" },
  { version: "0043_coupon_import", sql: "-- Banto 0043_coupon_import: クーポンの CSV 取り込み（同梱モジュール coupons の「CSV から取り込む」。docs/coupon-csv.md）\n-- 前方専用。人間の要望 2026-10-20（ほかのカートのプラグイン独自の制限を、人や AI が Banto の形に直して入れる口）。\n--   Worker は CSV を行ごとの JSON に直して 1 回で渡すだけ（Workers のサブリクエストの上限に当たらない）。\n--   値の検査は AI 用 API と同じ banto_api_coupon_apply（0036 / 0042）。商品・カテゴリーは slug でこのショップのものだけ。\n--   member_emails（この会員だけが使える）は、全員がこのショップの会員でなければ、その行を作らない（制限を外して作らない）。\n--   既にあるクーポン（同じコード、または同じ external_ref）は作らない（何度流しても重複しない）。\n--   p_dry_run = true なら何も書かずに、行ごとの結果だけを返す（確認の画面）。\n\ncreate or replace function import_coupons(p_shop_id uuid, p_rows jsonb, p_dry_run boolean default true)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb; v_values jsonb; v_cond jsonb; v_c coupon_campaigns%rowtype; v_new coupon_campaigns%rowtype;\n  v_slugs text[]; v_missing text[]; v_ids uuid[]; v_emails text[]; v_key text;\n  v_out jsonb := '[]'::jsonb; v_seen text[] := '{}'; v_result jsonb; v_grants integer; v_code text; v_ref text;\n  v_total_emails integer := 0;\nbegin\n  if not banto_shop_perm(p_shop_id, 'marketing') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  if not exists (select 1 from shops where id = p_shop_id and settings->'modules'->'coupons' = 'true'::jsonb) then raise exception 'module_disabled'; end if;\n  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then raise exception 'invalid_rows'; end if;\n  if jsonb_array_length(p_rows) > 500 then raise exception 'too_many_rows'; end if;\n\n  for v_row in select * from jsonb_array_elements(p_rows) loop\n    v_result := jsonb_build_object('line', v_row->'line');\n    begin\n      if jsonb_typeof(v_row->'values') <> 'object' then raise exception 'invalid_row'; end if;\n      v_values := v_row->'values';\n      v_cond := case when jsonb_typeof(v_row->'conditions') = 'object' then v_row->'conditions' else '{}'::jsonb end;\n\n      -- 商品・カテゴリー（slug → id）。ひとつでも見つからなければ作らない（対象を変えて作らない）\n      foreach v_key in array array['product_slugs', 'exclude_product_slugs', 'category_slugs', 'exclude_category_slugs'] loop\n        if jsonb_typeof(v_row->v_key) <> 'array' or jsonb_array_length(v_row->v_key) = 0 then continue; end if;\n        if jsonb_array_length(v_row->v_key) > 200 then raise exception 'too_many_%', v_key; end if;\n        select coalesce(array_agg(distinct lower(btrim(x))), '{}') into v_slugs from jsonb_array_elements_text(v_row->v_key) x where btrim(x) <> '';\n        if v_key like '%product%' then\n          select coalesce(array_agg(id), '{}') into v_ids from products where shop_id = p_shop_id and slug = any(v_slugs);\n          select coalesce(array_agg(s order by s), '{}') into v_missing from unnest(v_slugs) s where not exists (select 1 from products where shop_id = p_shop_id and slug = s);\n          if cardinality(v_missing) > 0 then raise exception 'unknown_products: %', array_to_string(v_missing[1:10], ', '); end if;\n        else\n          select coalesce(array_agg(id), '{}') into v_ids from categories where shop_id = p_shop_id and slug = any(v_slugs);\n          select coalesce(array_agg(s order by s), '{}') into v_missing from unnest(v_slugs) s where not exists (select 1 from categories where shop_id = p_shop_id and slug = s);\n          if cardinality(v_missing) > 0 then raise exception 'unknown_categories: %', array_to_string(v_missing[1:10], ', '); end if;\n        end if;\n        v_cond := v_cond || jsonb_build_object(replace(v_key, '_slugs', '_ids'), to_jsonb(v_ids));\n      end loop;\n      v_values := v_values || jsonb_build_object('conditions', v_cond);\n\n      -- この会員だけが使えるクーポン: 共通のコードは作らず、会員ごとに発行する。全員が会員でなければ作らない\n      v_emails := '{}';\n      if jsonb_typeof(v_row->'member_emails') = 'array' and jsonb_array_length(v_row->'member_emails') > 0 then\n        if jsonb_array_length(v_row->'member_emails') > 5000 then raise exception 'too_many_member_emails'; end if;\n        select coalesce(array_agg(distinct lower(btrim(x))), '{}') into v_emails from jsonb_array_elements_text(v_row->'member_emails') x where btrim(x) <> '';\n        v_total_emails := v_total_emails + cardinality(v_emails);\n        if v_total_emails > 20000 then raise exception 'too_many_member_emails'; end if;\n        select coalesce(array_agg(e order by e), '{}') into v_missing from unnest(v_emails) e\n         where not exists (select 1 from customers where shop_id = p_shop_id and lower(email) = e);\n        if cardinality(v_missing) > 0 then\n          raise exception 'not_members: % (%)', array_to_string(v_missing[1:10], ', '), cardinality(v_missing);\n        end if;\n        v_code := nullif(upper(btrim(coalesce(v_values->>'code', ''))), '');\n        if not (v_values ? 'external_ref') and v_code is not null then v_values := v_values || jsonb_build_object('external_ref', 'csv:' || v_code); end if;\n        v_values := v_values || jsonb_build_object('code', null);\n      end if;\n\n      -- 値の検査（AI 用 API と同じ）。既定値は管理画面の新規作成と同じ\n      if not (v_values ? 'name') then raise exception 'invalid_name'; end if;\n      if not (v_values ? 'kind') then raise exception 'invalid_kind'; end if;\n      v_c := null;\n      v_c.id := gen_random_uuid();\n      v_c.shop_id := p_shop_id;\n      v_c.value := 0;\n      v_c.combinable := false;\n      v_c.audience := 'public';\n      v_c.conditions := '{}'::jsonb;\n      v_c.active := true;\n      v_c.claimable := false;\n      v_c := banto_api_coupon_apply(p_shop_id, v_c, v_values);\n\n      -- 既にあるもの（同じコード・同じ external_ref。このファイルの中の重なりも）\n      v_ref := v_c.external_ref;\n      if (v_c.code is not null and (exists (select 1 from coupon_campaigns where shop_id = p_shop_id and code = v_c.code) or ('code:' || v_c.code) = any(v_seen)))\n         or (v_ref is not null and (exists (select 1 from coupon_campaigns where shop_id = p_shop_id and external_ref = v_ref) or ('ref:' || v_ref) = any(v_seen))) then\n        v_out := v_out || (v_result || jsonb_build_object('status', 'existing', 'code', v_c.code, 'name', v_c.name));\n        continue;\n      end if;\n      if v_c.code is not null then v_seen := v_seen || ('code:' || v_c.code); end if;\n      if v_ref is not null then v_seen := v_seen || ('ref:' || v_ref); end if;\n\n      v_grants := cardinality(v_emails);\n      if not p_dry_run then\n        insert into coupon_campaigns (id, shop_id, name, code, kind, value, starts_at, ends_at, usage_limit, per_customer_limit,\n                                      combinable, audience, conditions, active, grant_valid_days, auto_grant, claimable, external_ref)\n        values (v_c.id, v_c.shop_id, v_c.name, v_c.code, v_c.kind, v_c.value, v_c.starts_at, v_c.ends_at, v_c.usage_limit, v_c.per_customer_limit,\n                v_c.combinable, v_c.audience, v_c.conditions, v_c.active, v_c.grant_valid_days, v_c.auto_grant, v_c.claimable, v_c.external_ref)\n        returning * into v_new;\n        if cardinality(v_emails) > 0 then\n          select count(*) into v_grants from jsonb_array_elements(coupon_grants_for_emails(p_shop_id, v_new.id, v_emails)) g where (g->>'member')::boolean;\n        end if;\n      end if;\n      v_out := v_out || (v_result || jsonb_build_object('status', case when p_dry_run then 'ok' else 'created' end, 'code', v_c.code, 'name', v_c.name,\n                                                        'campaign_id', case when p_dry_run then null else v_c.id end, 'members', v_grants, 'active', v_c.active));\n    exception when others then\n      -- この行だけ取り消して続ける（plpgsql の例外ブロックはセーブポイントとして働く）\n      v_out := v_out || (v_result || jsonb_build_object('status', 'error', 'error', left(sqlerrm, 300)));\n    end;\n  end loop;\n  return v_out;\nend;\n$$;\nrevoke execute on function import_coupons(uuid, jsonb, boolean) from public, anon;\ngrant execute on function import_coupons(uuid, jsonb, boolean) to authenticated;\n\ninsert into banto_migrations (version) values ('0043_coupon_import');\n" },
  { version: "0044_coupon_brand_payment", sql: "-- Banto 0044_coupon_brand_payment: クーポンの条件にブランドと支払い方法を足す（人間の決定 2026-10-21）。前方専用。\n--   brands / exclude_brands … 商品のブランド（products.brand）で絞る。WooCommerce 本体のクーポンの「ブランド」「除くブランド」に当たる\n--   payment_methods … 使える支払い方法（stripe / komoju / komoju:<種類>）。確認画面と確定で判定し、\n--                     KOMOJU の決済ページに出す種類もクーポンが許すものだけにする（src/commerce/checkout.ts）\n-- 判定は src/commerce/discounts.ts だけ。ここは AI 用 API と CSV の取り込み（import_coupons）の値の検査を置き換えるだけ。\n\n-- ---------- クーポンの条件の検査（0042 を置き換える。brands / exclude_brands / payment_methods を受け付ける） ----------\ncreate or replace function banto_api_coupon_apply(p_shop_id uuid, p_c coupon_campaigns, p_values jsonb)\nreturns coupon_campaigns\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_key text; v_val jsonb; v_cond jsonb; v_ck text; v_cv jsonb; v_ids uuid[]; v_n integer; v_s text; v_tags text[];\nbegin\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key, v_val in select * from jsonb_each(p_values) loop\n    case v_key\n      when 'name' then\n        v_s := btrim(coalesce(v_val #>> '{}', ''));\n        if jsonb_typeof(v_val) <> 'string' or length(v_s) not between 1 and 100 then raise exception 'invalid_name'; end if;\n        p_c.name := v_s;\n      when 'code' then\n        if jsonb_typeof(v_val) = 'null' or btrim(v_val #>> '{}') = '' then p_c.code := null;\n        else\n          v_s := upper(btrim(v_val #>> '{}'));\n          if jsonb_typeof(v_val) <> 'string' or v_s !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$' then raise exception 'invalid_code'; end if;\n          p_c.code := v_s;\n        end if;\n      when 'kind' then\n        if jsonb_typeof(v_val) <> 'string' or v_val #>> '{}' not in ('percent', 'fixed', 'free_shipping') then raise exception 'invalid_kind'; end if;\n        p_c.kind := v_val #>> '{}';\n      when 'value' then\n        if jsonb_typeof(v_val) <> 'number' or (v_val #>> '{}') !~ '^\\d+$' then raise exception 'invalid_value'; end if;\n        p_c.value := (v_val #>> '{}')::integer;\n      when 'starts_at', 'ends_at' then\n        if jsonb_typeof(v_val) not in ('string', 'null') then raise exception 'invalid_%', v_key; end if;\n        begin\n          if v_key = 'starts_at' then p_c.starts_at := (v_val #>> '{}')::timestamptz; else p_c.ends_at := (v_val #>> '{}')::timestamptz; end if;\n        exception when others then raise exception 'invalid_%', v_key;\n        end;\n      when 'usage_limit', 'per_customer_limit', 'grant_valid_days' then\n        if jsonb_typeof(v_val) = 'null' then v_n := null;\n        elsif jsonb_typeof(v_val) = 'number' and (v_val #>> '{}') ~ '^\\d{1,7}$' then v_n := (v_val #>> '{}')::integer;\n        else raise exception 'invalid_%', v_key;\n        end if;\n        if v_key = 'usage_limit' then\n          if v_n is not null and v_n not between 1 and 100000 then raise exception 'invalid_usage_limit'; end if;\n          p_c.usage_limit := v_n;\n        elsif v_key = 'per_customer_limit' then\n          if v_n is not null and v_n not between 1 and 1000 then raise exception 'invalid_per_customer_limit'; end if;\n          p_c.per_customer_limit := v_n;\n        else\n          if v_n is not null and v_n not between 1 and 3650 then raise exception 'invalid_grant_valid_days'; end if;\n          p_c.grant_valid_days := v_n;\n        end if;\n      when 'combinable', 'active', 'claimable' then\n        if jsonb_typeof(v_val) <> 'boolean' then raise exception 'invalid_%', v_key; end if;\n        if v_key = 'combinable' then p_c.combinable := v_val::boolean;\n        elsif v_key = 'active' then p_c.active := v_val::boolean;\n        else p_c.claimable := v_val::boolean;\n        end if;\n      when 'audience' then\n        if jsonb_typeof(v_val) <> 'string' or v_val #>> '{}' not in ('public', 'members') then raise exception 'invalid_audience'; end if;\n        p_c.audience := v_val #>> '{}';\n      when 'auto_grant' then\n        if jsonb_typeof(v_val) = 'null' then p_c.auto_grant := null;\n        elsif jsonb_typeof(v_val) = 'string' and v_val #>> '{}' in ('first_login', 'after_purchase') then p_c.auto_grant := v_val #>> '{}';\n        else raise exception 'invalid_auto_grant';\n        end if;\n      when 'external_ref' then\n        if jsonb_typeof(v_val) = 'null' or btrim(v_val #>> '{}') = '' then p_c.external_ref := null;\n        elsif jsonb_typeof(v_val) = 'string' and length(btrim(v_val #>> '{}')) <= 100 then p_c.external_ref := btrim(v_val #>> '{}');\n        else raise exception 'invalid_external_ref';\n        end if;\n      when 'conditions' then\n        if jsonb_typeof(v_val) = 'null' then v_val := '{}'::jsonb; end if;\n        if jsonb_typeof(v_val) <> 'object' then raise exception 'invalid_conditions'; end if;\n        v_cond := '{}'::jsonb;\n        for v_ck, v_cv in select * from jsonb_each(v_val) loop\n          if jsonb_typeof(v_cv) = 'null' then continue; end if;\n          case v_ck\n            when 'product_ids', 'exclude_product_ids', 'category_ids', 'exclude_category_ids' then\n              if jsonb_typeof(v_cv) <> 'array' or jsonb_array_length(v_cv) > 200\n                 or exists (select 1 from jsonb_array_elements(v_cv) e\n                             where jsonb_typeof(e) <> 'string' or (e #>> '{}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              select coalesce(array_agg(distinct (e #>> '{}')::uuid), '{}') into v_ids from jsonb_array_elements(v_cv) e;\n              if v_ck in ('product_ids', 'exclude_product_ids') then\n                if (select count(*) from products where shop_id = p_shop_id and id = any(v_ids)) <> coalesce(array_length(v_ids, 1), 0) then raise exception 'invalid_conditions_unknown_products'; end if;\n              else\n                if (select count(*) from categories where shop_id = p_shop_id and id = any(v_ids)) <> coalesce(array_length(v_ids, 1), 0) then raise exception 'invalid_conditions_unknown_categories'; end if;\n              end if;\n              if coalesce(array_length(v_ids, 1), 0) > 0 then v_cond := v_cond || jsonb_build_object(v_ck, to_jsonb(v_ids)); end if;\n            when 'tags', 'exclude_tags' then\n              -- タグ（0042）。商品のタグと同じ正規化（src/products/tags.ts）。20 個まで\n              if jsonb_typeof(v_cv) <> 'array' or jsonb_array_length(v_cv) > 20\n                 or exists (select 1 from jsonb_array_elements(v_cv) e where jsonb_typeof(e) <> 'string') then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              v_tags := banto_normalize_tags(v_cv);\n              if coalesce(array_length(v_tags, 1), 0) > 0 then v_cond := v_cond || jsonb_build_object(v_ck, to_jsonb(v_tags)); end if;\n            when 'brands', 'exclude_brands' then\n              -- ブランド（0044）。商品のブランドと前後の空白・大文字小文字を区別せずに比べる。20 個・1 個 100 文字まで\n              if jsonb_typeof(v_cv) <> 'array' or jsonb_array_length(v_cv) > 20\n                 or exists (select 1 from jsonb_array_elements(v_cv) e where jsonb_typeof(e) <> 'string' or length(btrim(e #>> '{}')) not between 1 and 100) then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              select coalesce(array_agg(distinct btrim(e #>> '{}')), '{}') into v_tags from jsonb_array_elements(v_cv) e;\n              if coalesce(array_length(v_tags, 1), 0) > 0 then v_cond := v_cond || jsonb_build_object(v_ck, to_jsonb(v_tags)); end if;\n            when 'payment_methods' then\n              -- 支払い方法（0044）: stripe / komoju / komoju:<種類>。判定は src/commerce/discounts.ts\n              if jsonb_typeof(v_cv) <> 'array' or jsonb_array_length(v_cv) > 20\n                 or exists (select 1 from jsonb_array_elements(v_cv) e where jsonb_typeof(e) <> 'string' or (e #>> '{}') !~ '^(stripe|komoju|komoju:[a-z_]{1,40})$') then\n                raise exception 'invalid_conditions_payment_methods';\n              end if;\n              select coalesce(array_agg(distinct e #>> '{}'), '{}') into v_tags from jsonb_array_elements(v_cv) e;\n              if coalesce(array_length(v_tags, 1), 0) > 0 then v_cond := v_cond || jsonb_build_object('payment_methods', to_jsonb(v_tags)); end if;\n            when 'exclude_sale' then\n              if jsonb_typeof(v_cv) <> 'boolean' then raise exception 'invalid_conditions_exclude_sale'; end if;\n              if v_cv::boolean then v_cond := v_cond || jsonb_build_object('exclude_sale', true); end if;\n            when 'min_subtotal_jpy', 'max_subtotal_jpy', 'min_qty' then\n              -- 上限: 点数は 999、金額は 1 億円（管理画面と同じ）\n              v_n := 100000000;\n              if v_ck = 'min_qty' then v_n := 999; end if;\n              if jsonb_typeof(v_cv) <> 'number' or (v_cv #>> '{}') !~ '^\\d{1,9}$' or (v_cv #>> '{}')::integer > v_n then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              v_cond := v_cond || jsonb_build_object(v_ck, (v_cv #>> '{}')::integer);\n            else raise exception 'invalid_conditions_unknown_key';\n          end case;\n        end loop;\n        p_c.conditions := v_cond;\n      else raise exception 'invalid_field_%', left(v_key, 40);\n    end case;\n  end loop;\n  -- 種類と値の組み合わせ（テーブルの CHECK と同じ。わかりやすい理由で返す）\n  if p_c.kind = 'free_shipping' then p_c.value := 0;\n  elsif p_c.kind = 'percent' and p_c.value not between 1 and 100 then raise exception 'invalid_value';\n  elsif p_c.kind = 'fixed' and p_c.value not between 1 and 10000000 then raise exception 'invalid_value';\n  end if;\n  if p_c.starts_at is not null and p_c.ends_at is not null and p_c.starts_at >= p_c.ends_at then raise exception 'invalid_ends_at'; end if;\n  return p_c;\nend;\n$$;\n\ninsert into banto_migrations (version) values ('0044_coupon_brand_payment');\n" },
  { version: "0045_member_sessions", sql: "-- Banto 0045_member_sessions: 会員のセッションを端末ごとに持つ（監査 M9）。前方専用。\n--\n-- これまで会員のセッション（Cookie・ヘッドレスのトークン）はサーバーに状態が無く、取り消せるのは「全端末からログアウト」（世代を上げる）だけだった。\n-- ログアウトしても盗まれた Cookie は 30 日使えたし、ヘッドレスの refresh は回転もしなかった。\n--   - ログインのたびに 1 行（member_sessions）。Cookie とトークンにはこの行の ID（sid）を入れる。\n--   - Cookie は数分ごとに member_session_check で行を確かめる（毎回は問い合わせない。速度の予算、src/routes/storefront/members.ts）。\n--   - ヘッドレスの refresh は 1 回ごとに回す（refresh_gen）。前の世代を使い回したら、その行ごと取り消す（盗まれたと見なす）。\n--     同時に refresh したとき（タブを 2 つ開いていた等）のために、回した直後の短い間だけ 1 つ前の世代も通す。\n--   - 行には絶対の期限（expires_at）がある。開くたびに延びるのは Cookie の期限だけで、行の期限は延ばさない。\n--   - 世代（customers.session_epoch）は今までどおり。上げれば、それより前の世代の行はすべて通らなくなる。\n-- 行に置くのは端末の目安（ブラウザと OS の名前だけ。Worker が User-Agent から作る）と日時だけ。IP・User-Agent そのものは置かない。\n-- すべて service_role だけ。呼び出しは src/db/privileged.ts から。\n\ncreate table member_sessions (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  customer_id uuid not null,\n  -- 作ったときの customers.session_epoch。今の世代と違えば通らない\n  session_epoch integer not null,\n  -- web: お店の画面の Cookie / api: ヘッドレスのトークン\n  kind text not null check (kind in ('web', 'api')),\n  label text check (char_length(label) <= 60),\n  -- ヘッドレスの refresh の世代（web では使わない）\n  refresh_gen integer not null default 0,\n  rotated_at timestamptz,\n  created_at timestamptz not null default now(),\n  last_seen_at timestamptz not null default now(),\n  expires_at timestamptz not null,\n  revoked_at timestamptz,\n  revoked_reason text check (revoked_reason in ('logout', 'revoked', 'reuse', 'limit')),\n  -- 退会（customers 行の削除）で消える\n  foreign key (shop_id, customer_id) references customers (shop_id, id) on delete cascade\n);\ncreate index member_sessions_customer_idx on member_sessions (shop_id, customer_id, created_at);\ncreate index member_sessions_expires_idx on member_sessions (expires_at);\nalter table member_sessions enable row level security;\n-- 誰にも見せない（service_role は RLS を通らない。関数からだけ触る）\ncreate policy member_sessions_none on member_sessions for select using (false);\n\n-- 1 人の会員が同時に持てるセッションの数。超えたら古いものから取り消す（行が際限なく増えないように）\ncreate or replace function banto_member_session_limit() returns integer language sql immutable as $$ select 20 $$;\n\n-- ---------- セッションを作る（ログインの直後に Worker が呼ぶ） ----------\n-- 世代が今と違えば（ログインの途中で全端末からログアウトされた等）null。戻り値は sid\ncreate or replace function member_session_start(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_kind text, p_label text, p_ttl_seconds integer)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_id uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_session_start: service_role only' using errcode = '42501';\n  end if;\n  if p_kind not in ('web', 'api') or p_ttl_seconds is null or p_ttl_seconds not between 60 and 366 * 86400 then\n    raise exception 'invalid_session';\n  end if;\n  perform 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch for update;\n  if not found then return null; end if;\n  -- この会員の終わった行を片付ける\n  delete from member_sessions\n   where shop_id = p_shop_id and customer_id = p_customer_id\n     and (expires_at < now() or revoked_at < now() - interval '1 day' or session_epoch <> p_epoch);\n  insert into member_sessions (shop_id, customer_id, session_epoch, kind, label, expires_at)\n  values (p_shop_id, p_customer_id, p_epoch, p_kind, nullif(left(btrim(coalesce(p_label, '')), 60), ''), now() + make_interval(secs => p_ttl_seconds))\n  returning id into v_id;\n  update member_sessions set revoked_at = now(), revoked_reason = 'limit'\n   where id in (\n     select id from member_sessions\n      where shop_id = p_shop_id and customer_id = p_customer_id and revoked_at is null\n      order by created_at desc, id\n      offset banto_member_session_limit());\n  return v_id;\nend;\n$$;\n\n-- 生きているか（取り消されていない・期限内・世代が今と同じ）\ncreate or replace function banto_member_session_live(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_session_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select exists (\n    select 1 from member_sessions s join customers c on c.id = s.customer_id\n     where s.id = p_session_id and s.shop_id = p_shop_id and s.customer_id = p_customer_id\n       and s.session_epoch = p_epoch and c.session_epoch = p_epoch and c.shop_id = p_shop_id\n       and s.revoked_at is null and s.expires_at > now());\n$$;\n\n-- ---------- Cookie のセッションを確かめる（数分ごと） ----------\ncreate or replace function member_session_check(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_session_id uuid)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_session_check: service_role only' using errcode = '42501';\n  end if;\n  if not banto_member_session_live(p_shop_id, p_customer_id, p_epoch, p_session_id) then return false; end if;\n  update member_sessions set last_seen_at = now() where id = p_session_id;\n  return true;\nend;\n$$;\n\n-- ---------- ヘッドレスの refresh を回す ----------\n-- p_gen はトークンに入っていた世代。今の世代なら 1 つ進めて返す。\n-- 1 つ前の世代でも、回してから p_grace_seconds 秒以内なら今の世代を返す（同時に refresh した 2 つ目の呼び出し）。\n-- それより古い世代 = 使い回し。行を取り消して reuse を返す（盗んだ側と本人のどちらが先に使ったかは分からないので、両方を止める）。\n-- 戻り値: { ok: true, gen, expires_at } / { ok: false, reason: 'invalid' | 'reuse' }\ncreate or replace function member_session_refresh(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_session_id uuid, p_gen integer, p_grace_seconds integer default 30)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_s member_sessions;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_session_refresh: service_role only' using errcode = '42501';\n  end if;\n  select * into v_s from member_sessions\n   where id = p_session_id and shop_id = p_shop_id and customer_id = p_customer_id and kind = 'api'\n   for update;\n  if not found or not banto_member_session_live(p_shop_id, p_customer_id, p_epoch, p_session_id) then\n    return jsonb_build_object('ok', false, 'reason', 'invalid');\n  end if;\n  if p_gen = v_s.refresh_gen then\n    update member_sessions set refresh_gen = refresh_gen + 1, rotated_at = now(), last_seen_at = now()\n     where id = p_session_id returning * into v_s;\n    return jsonb_build_object('ok', true, 'gen', v_s.refresh_gen, 'expires_at', v_s.expires_at);\n  end if;\n  if p_gen = v_s.refresh_gen - 1 and v_s.rotated_at > now() - make_interval(secs => greatest(coalesce(p_grace_seconds, 0), 0)) then\n    update member_sessions set last_seen_at = now() where id = p_session_id;\n    return jsonb_build_object('ok', true, 'gen', v_s.refresh_gen, 'expires_at', v_s.expires_at);\n  end if;\n  update member_sessions set revoked_at = now(), revoked_reason = 'reuse' where id = p_session_id;\n  return jsonb_build_object('ok', false, 'reason', 'reuse');\nend;\n$$;\n\n-- ---------- 取り消す ----------\n-- 自分のセッション（ログアウト）か、自分のほかの端末（ログイン中の端末の一覧から）。p_epoch は呼び出し側のセッションの世代。\n-- 世代が合わない（呼び出し側がもう無効）なら何もしない\ncreate or replace function member_session_revoke(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_session_id uuid, p_reason text default 'revoked')\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_session_revoke: service_role only' using errcode = '42501';\n  end if;\n  if p_reason not in ('logout', 'revoked') then raise exception 'invalid_reason'; end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then\n    return false;\n  end if;\n  update member_sessions set revoked_at = now(), revoked_reason = p_reason\n   where id = p_session_id and shop_id = p_shop_id and customer_id = p_customer_id and revoked_at is null;\n  return found;\nend;\n$$;\n\n-- ---------- ログイン中の端末の一覧 ----------\n-- 世代が合わなければ null。今の世代の、取り消されていない・期限内の行だけ（新しく使った順）\ncreate or replace function member_sessions_list(p_shop_id uuid, p_customer_id uuid, p_epoch integer)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_sessions_list: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then\n    return null;\n  end if;\n  return coalesce((\n    select jsonb_agg(jsonb_build_object('id', id, 'kind', kind, 'label', label, 'created_at', created_at, 'last_seen_at', last_seen_at) order by last_seen_at desc, id)\n      from member_sessions\n     where shop_id = p_shop_id and customer_id = p_customer_id and session_epoch = p_epoch\n       and revoked_at is null and expires_at > now()), '[]'::jsonb);\nend;\n$$;\n\n-- ---------- 片付け（Cron） ----------\ncreate or replace function member_session_cleanup()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_session_cleanup: service_role only' using errcode = '42501';\n  end if;\n  delete from member_sessions s\n   where s.expires_at < now()\n      or s.revoked_at < now() - interval '1 day'\n      or exists (select 1 from customers c where c.id = s.customer_id and c.session_epoch <> s.session_epoch);\n  get diagnostics v_n = row_count;\n  return v_n;\nend;\n$$;\n\nrevoke execute on function banto_member_session_limit() from public, anon, authenticated;\nrevoke execute on function banto_member_session_live(uuid, uuid, integer, uuid) from public, anon, authenticated;\nrevoke execute on function member_session_start(uuid, uuid, integer, text, text, integer) from public, anon, authenticated;\nrevoke execute on function member_session_check(uuid, uuid, integer, uuid) from public, anon, authenticated;\nrevoke execute on function member_session_refresh(uuid, uuid, integer, uuid, integer, integer) from public, anon, authenticated;\nrevoke execute on function member_session_revoke(uuid, uuid, integer, uuid, text) from public, anon, authenticated;\nrevoke execute on function member_sessions_list(uuid, uuid, integer) from public, anon, authenticated;\nrevoke execute on function member_session_cleanup() from public, anon, authenticated;\ngrant execute on function member_session_start(uuid, uuid, integer, text, text, integer) to service_role;\ngrant execute on function member_session_check(uuid, uuid, integer, uuid) to service_role;\ngrant execute on function member_session_refresh(uuid, uuid, integer, uuid, integer, integer) to service_role;\ngrant execute on function member_session_revoke(uuid, uuid, integer, uuid, text) to service_role;\ngrant execute on function member_sessions_list(uuid, uuid, integer) to service_role;\ngrant execute on function member_session_cleanup() to service_role;\n\ninsert into banto_migrations (version) values ('0045_member_sessions');\n" },
  { version: "0046_mod_passkey", sql: "-- Banto 0046_mod_passkey: パスキーでのログイン（同梱モジュール passkey、既定 OFF。docs/knowledge/10-members-identity.md §18）。前方専用。\n--\n-- 人間の決定（2026-10-23）: RP ID はショップのドメインそのもの。独自ドメイン（shops.domain）の無いショップには出さない\n-- （Banto の URL にパスで同居するショップ同士で RP ID を共有しないため）。ヘッドレスは Banto の画面でパスキーを使い、引き換え券で戻す。\n--   - 署名の検証は Worker（src/members/webauthn.ts、WebCrypto）。ここは「challenge は 1 回限り・5 分・誰のものか」と\n--     「署名の回数が戻っていないか」と「パスキーは誰のものか」を確かめる。\n--   - challenge は Worker が HMAC（サイトの秘密）にしてから渡す。生の値は DB に来ない。\n--   - パスキーの追加は、ログインしてから 15 分以内のセッション（0045 の member_sessions）だけ。盗まれた Cookie でパスキーを\n--     足されると、セッションを取り消しても入れてしまうため。追加したら本人にメールで知らせる（Worker）。\n--   - パスキーはログインの入口の 1 つ。なくしてもメールのコードで入れる。全端末からログアウト（世代）では消さない。\n-- すべて service_role だけ。呼び出しは src/db/privileged.ts から。\n\ncreate table member_passkeys (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  customer_id uuid not null,\n  -- base64url（PostgreSQL の正規表現の繰り返しは 255 回までなので、長さは別に確かめる）\n  credential_id text not null check (credential_id ~ '^[A-Za-z0-9_-]+$' and char_length(credential_id) between 22 and 1364),\n  -- COSE の公開鍵（base64url）\n  public_key text not null check (public_key ~ '^[A-Za-z0-9_-]+$' and char_length(public_key) between 20 and 2048),\n  alg integer not null check (alg in (-7, -8, -257)),\n  -- 登録したときのショップのドメイン。ドメインが変わったら使えない（ログインのときに今のドメインと比べる）\n  rp_id text not null check (char_length(rp_id) between 1 and 253),\n  sign_count bigint not null default 0 check (sign_count between 0 and 4294967295),\n  backed_up boolean not null default false,\n  label text check (char_length(label) <= 60),\n  created_at timestamptz not null default now(),\n  last_used_at timestamptz,\n  unique (shop_id, credential_id),\n  -- 退会（customers 行の削除）で消える\n  foreign key (shop_id, customer_id) references customers (shop_id, id) on delete cascade\n);\ncreate index member_passkeys_customer_idx on member_passkeys (shop_id, customer_id);\nalter table member_passkeys enable row level security;\n-- 誰にも見せない（service_role は RLS を通らない。関数からだけ触る）\ncreate policy member_passkeys_none on member_passkeys for select using (false);\n\ncreate table member_passkey_challenges (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  purpose text not null check (purpose in ('login', 'register')),\n  challenge_hash text not null check (challenge_hash ~ '^[0-9a-f]{64}$'),\n  -- register だけ: 誰の・どのセッションの追加か\n  customer_id uuid,\n  session_id uuid,\n  ip_hash text check (ip_hash ~ '^[0-9a-f]{64}$'),\n  created_at timestamptz not null default now(),\n  expires_at timestamptz not null,\n  consumed_at timestamptz\n);\ncreate index member_passkey_challenges_ip_idx on member_passkey_challenges (shop_id, ip_hash, created_at) where ip_hash is not null;\ncreate index member_passkey_challenges_created_idx on member_passkey_challenges (shop_id, created_at);\nalter table member_passkey_challenges enable row level security;\ncreate policy member_passkey_challenges_none on member_passkey_challenges for select using (false);\n\n-- パスキーが使えるショップか（会員機能・モジュールが ON・独自ドメインがある）\ncreate or replace function banto_passkey_shop(p_shop_id uuid)\nreturns text\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select s.domain from shops s\n   where s.id = p_shop_id and s.domain is not null\n     and coalesce(s.settings->>'members_enabled', 'false') = 'true'\n     and coalesce(s.settings #>> '{modules,passkey}', 'false') = 'true';\n$$;\n\n-- 1 人の会員が持てるパスキーの数\ncreate or replace function banto_passkey_limit() returns integer language sql immutable as $$ select 10 $$;\n\n-- ---------- challenge を出す ----------\n-- login: 誰でも（同じ IP から 10 分に 30 回、ショップ全体で 10 分に 3000 回まで）。\n-- register: ログイン中の会員の、ログインしてから 15 分以内のセッション（p_session_id）だけ。\n-- 戻り値: { ok: true, challenge_id, rp_id, exclude: [credential_id]（register）, user: { email, name }（register） }\n--        / { ok: false, reason: 'disabled' | 'limited' | 'session' | 'reauth' | 'too_many' }\ncreate or replace function member_passkey_begin(p_shop_id uuid, p_purpose text, p_challenge_hash text, p_ip_hash text, p_customer_id uuid default null, p_epoch integer default null, p_session_id uuid default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_domain text; v_c customers; v_id uuid; v_n integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_passkey_begin: service_role only' using errcode = '42501';\n  end if;\n  if p_purpose not in ('login', 'register') then raise exception 'invalid_purpose'; end if;\n  v_domain := banto_passkey_shop(p_shop_id);\n  if v_domain is null then return jsonb_build_object('ok', false, 'reason', 'disabled'); end if;\n\n  if p_purpose = 'login' then\n    if p_ip_hash is not null then\n      select count(*) into v_n from member_passkey_challenges\n       where shop_id = p_shop_id and ip_hash = p_ip_hash and created_at > now() - interval '10 minutes';\n      if v_n >= 30 then return jsonb_build_object('ok', false, 'reason', 'limited'); end if;\n    end if;\n    select count(*) into v_n from member_passkey_challenges where shop_id = p_shop_id and created_at > now() - interval '10 minutes';\n    if v_n >= 3000 then return jsonb_build_object('ok', false, 'reason', 'limited'); end if;\n    insert into member_passkey_challenges (shop_id, purpose, challenge_hash, ip_hash, expires_at)\n    values (p_shop_id, 'login', p_challenge_hash, p_ip_hash, now() + interval '5 minutes')\n    returning id into v_id;\n    return jsonb_build_object('ok', true, 'challenge_id', v_id, 'rp_id', v_domain);\n  end if;\n\n  select * into v_c from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch;\n  if not found or p_session_id is null or not banto_member_session_live(p_shop_id, p_customer_id, p_epoch, p_session_id) then\n    return jsonb_build_object('ok', false, 'reason', 'session');\n  end if;\n  if not exists (select 1 from member_sessions where id = p_session_id and kind = 'web' and created_at > now() - interval '15 minutes') then\n    return jsonb_build_object('ok', false, 'reason', 'reauth');\n  end if;\n  if (select count(*) from member_passkeys where shop_id = p_shop_id and customer_id = p_customer_id) >= banto_passkey_limit() then\n    return jsonb_build_object('ok', false, 'reason', 'too_many');\n  end if;\n  insert into member_passkey_challenges (shop_id, purpose, challenge_hash, customer_id, session_id, ip_hash, expires_at)\n  values (p_shop_id, 'register', p_challenge_hash, p_customer_id, p_session_id, p_ip_hash, now() + interval '5 minutes')\n  returning id into v_id;\n  return jsonb_build_object('ok', true, 'challenge_id', v_id, 'rp_id', v_domain,\n    'user', jsonb_build_object('email', v_c.email, 'name', v_c.name),\n    'exclude', coalesce((select jsonb_agg(credential_id order by created_at) from member_passkeys\n                          where shop_id = p_shop_id and customer_id = p_customer_id and rp_id = v_domain), '[]'::jsonb));\nend;\n$$;\n\n-- challenge を使う（1 回限り）。合わなければ null\ncreate or replace function banto_passkey_consume(p_shop_id uuid, p_challenge_id uuid, p_challenge_hash text, p_purpose text)\nreturns member_passkey_challenges\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_ch member_passkey_challenges;\nbegin\n  select * into v_ch from member_passkey_challenges\n   where id = p_challenge_id and shop_id = p_shop_id and purpose = p_purpose\n   for update;\n  if not found or v_ch.consumed_at is not null or v_ch.expires_at <= now() or v_ch.challenge_hash <> p_challenge_hash then\n    return null;\n  end if;\n  update member_passkey_challenges set consumed_at = now() where id = v_ch.id;\n  return v_ch;\nend;\n$$;\n\n-- ---------- 登録 ----------\n-- Worker が応答を確かめた後に呼ぶ。戻り値: { ok: true, id, email, mail_from } / { ok: false, reason: 'expired' | 'session' | 'reauth' | 'duplicate' | 'too_many' | 'disabled' }\ncreate or replace function member_passkey_register(\n  p_shop_id uuid, p_challenge_id uuid, p_challenge_hash text, p_customer_id uuid, p_epoch integer, p_session_id uuid,\n  p_credential_id text, p_public_key text, p_alg integer, p_sign_count bigint, p_rp_id text, p_backed_up boolean, p_label text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_ch member_passkey_challenges; v_domain text; v_id uuid; v_email text; v_from text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_passkey_register: service_role only' using errcode = '42501';\n  end if;\n  v_domain := banto_passkey_shop(p_shop_id);\n  if v_domain is null or v_domain <> p_rp_id then return jsonb_build_object('ok', false, 'reason', 'disabled'); end if;\n  v_ch := banto_passkey_consume(p_shop_id, p_challenge_id, p_challenge_hash, 'register');\n  if v_ch.id is null or v_ch.customer_id is distinct from p_customer_id or v_ch.session_id is distinct from p_session_id then\n    return jsonb_build_object('ok', false, 'reason', 'expired');\n  end if;\n  if not banto_member_session_live(p_shop_id, p_customer_id, p_epoch, p_session_id) then\n    return jsonb_build_object('ok', false, 'reason', 'session');\n  end if;\n  if not exists (select 1 from member_sessions where id = p_session_id and kind = 'web' and created_at > now() - interval '20 minutes') then\n    return jsonb_build_object('ok', false, 'reason', 'reauth');\n  end if;\n  perform 1 from customers where shop_id = p_shop_id and id = p_customer_id for update;\n  if (select count(*) from member_passkeys where shop_id = p_shop_id and customer_id = p_customer_id) >= banto_passkey_limit() then\n    return jsonb_build_object('ok', false, 'reason', 'too_many');\n  end if;\n  if exists (select 1 from member_passkeys where shop_id = p_shop_id and credential_id = p_credential_id) then\n    return jsonb_build_object('ok', false, 'reason', 'duplicate');\n  end if;\n  insert into member_passkeys (shop_id, customer_id, credential_id, public_key, alg, rp_id, sign_count, backed_up, label)\n  values (p_shop_id, p_customer_id, p_credential_id, p_public_key, p_alg, p_rp_id, coalesce(p_sign_count, 0), coalesce(p_backed_up, false),\n          nullif(left(btrim(coalesce(p_label, '')), 60), ''))\n  returning id into v_id;\n  select email into v_email from customers where shop_id = p_shop_id and id = p_customer_id;\n  -- 知らせのメールの送信元（メール通知プラグインの設定。無ければ null = 送らない）\n  select nullif(btrim(e.settings->>'from'), '') into v_from\n    from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and e.url = 'https://banto.invalid/plugins/email_resend'\n   limit 1;\n  return jsonb_build_object('ok', true, 'id', v_id, 'email', v_email, 'mail_from', v_from);\nend;\n$$;\n\n-- ---------- ログイン ----------\n-- 署名を確かめるための公開鍵を引く（読むだけ）。今のドメインで登録したものだけ。無ければ null\ncreate or replace function member_passkey_lookup(p_shop_id uuid, p_credential_id text)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_domain text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_passkey_lookup: service_role only' using errcode = '42501';\n  end if;\n  v_domain := banto_passkey_shop(p_shop_id);\n  if v_domain is null then return null; end if;\n  return (select jsonb_build_object('id', id, 'customer_id', customer_id, 'public_key', public_key, 'alg', alg)\n            from member_passkeys where shop_id = p_shop_id and credential_id = p_credential_id and rp_id = v_domain);\nend;\n$$;\n\n-- Worker が署名を確かめた後に呼ぶ。challenge を使い、署名の回数を確かめて、会員としてログインさせる。\n-- 戻り値: { ok: true, customer_id, session_epoch, email } / { ok: false, reason: 'expired' | 'invalid' | 'counter' | 'disabled' }\n-- counter: 認証器の署名の回数が前より進んでいない（パスキーが複製された疑い）。どちらも 0 なら数えない認証器（同期するパスキー）\ncreate or replace function member_passkey_login(p_shop_id uuid, p_challenge_id uuid, p_challenge_hash text, p_passkey_id uuid, p_sign_count bigint, p_backed_up boolean)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_ch member_passkey_challenges; v_pk member_passkeys; v_c customers; v_domain text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_passkey_login: service_role only' using errcode = '42501';\n  end if;\n  v_domain := banto_passkey_shop(p_shop_id);\n  if v_domain is null then return jsonb_build_object('ok', false, 'reason', 'disabled'); end if;\n  v_ch := banto_passkey_consume(p_shop_id, p_challenge_id, p_challenge_hash, 'login');\n  if v_ch.id is null then return jsonb_build_object('ok', false, 'reason', 'expired'); end if;\n  select * into v_pk from member_passkeys where id = p_passkey_id and shop_id = p_shop_id and rp_id = v_domain for update;\n  if not found then return jsonb_build_object('ok', false, 'reason', 'invalid'); end if;\n  if (coalesce(p_sign_count, 0) > 0 or v_pk.sign_count > 0) and coalesce(p_sign_count, 0) <= v_pk.sign_count then\n    return jsonb_build_object('ok', false, 'reason', 'counter');\n  end if;\n  update member_passkeys set sign_count = coalesce(p_sign_count, 0), backed_up = coalesce(p_backed_up, backed_up), last_used_at = now()\n   where id = v_pk.id;\n  update customers set last_login_at = now() where shop_id = p_shop_id and id = v_pk.customer_id returning * into v_c;\n  return jsonb_build_object('ok', true, 'customer_id', v_c.id, 'session_epoch', v_c.session_epoch, 'email', v_c.email);\nend;\n$$;\n\n-- ---------- 会員の画面 ----------\n-- 世代が合わなければ null。current はショップの今のドメインで使えるか\ncreate or replace function member_passkeys_list(p_shop_id uuid, p_customer_id uuid, p_epoch integer)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_domain text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_passkeys_list: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then\n    return null;\n  end if;\n  select domain into v_domain from shops where id = p_shop_id;\n  return coalesce((\n    select jsonb_agg(jsonb_build_object('id', id, 'label', label, 'created_at', created_at, 'last_used_at', last_used_at,\n                                        'backed_up', backed_up, 'usable', rp_id = v_domain) order by created_at)\n      from member_passkeys where shop_id = p_shop_id and customer_id = p_customer_id), '[]'::jsonb);\nend;\n$$;\n\ncreate or replace function member_passkey_delete(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_id uuid)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_passkey_delete: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then\n    return false;\n  end if;\n  delete from member_passkeys where id = p_id and shop_id = p_shop_id and customer_id = p_customer_id;\n  return found;\nend;\n$$;\n\n-- ---------- 運営者: 会員のパスキーを全部消す（乗っ取られた会員の救済。メールアドレスの変更と組み合わせる） ----------\n-- owner の JWT で呼ぶ（会員の項目 customers が要る）。戻り値は消した数\ncreate or replace function member_passkeys_reset(p_shop_id uuid, p_customer_id uuid)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer;\nbegin\n  if not banto_shop_perm(p_shop_id, 'customers') then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n  delete from member_passkeys where shop_id = p_shop_id and customer_id = p_customer_id;\n  get diagnostics v_n = row_count;\n  return v_n;\nend;\n$$;\n\n-- ---------- 片付け（Cron） ----------\ncreate or replace function member_passkey_cleanup()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_passkey_cleanup: service_role only' using errcode = '42501';\n  end if;\n  delete from member_passkey_challenges where created_at < now() - interval '1 day';\n  get diagnostics v_n = row_count;\n  return v_n;\nend;\n$$;\n\nrevoke execute on function banto_passkey_shop(uuid) from public, anon, authenticated;\nrevoke execute on function banto_passkey_limit() from public, anon, authenticated;\nrevoke execute on function banto_passkey_consume(uuid, uuid, text, text) from public, anon, authenticated;\nrevoke execute on function member_passkey_begin(uuid, text, text, text, uuid, integer, uuid) from public, anon, authenticated;\nrevoke execute on function member_passkey_register(uuid, uuid, text, uuid, integer, uuid, text, text, integer, bigint, text, boolean, text) from public, anon, authenticated;\nrevoke execute on function member_passkey_lookup(uuid, text) from public, anon, authenticated;\nrevoke execute on function member_passkey_login(uuid, uuid, text, uuid, bigint, boolean) from public, anon, authenticated;\nrevoke execute on function member_passkeys_list(uuid, uuid, integer) from public, anon, authenticated;\nrevoke execute on function member_passkey_delete(uuid, uuid, integer, uuid) from public, anon, authenticated;\nrevoke execute on function member_passkeys_reset(uuid, uuid) from public, anon;\nrevoke execute on function member_passkey_cleanup() from public, anon, authenticated;\ngrant execute on function member_passkey_begin(uuid, text, text, text, uuid, integer, uuid) to service_role;\ngrant execute on function member_passkey_register(uuid, uuid, text, uuid, integer, uuid, text, text, integer, bigint, text, boolean, text) to service_role;\ngrant execute on function member_passkey_lookup(uuid, text) to service_role;\ngrant execute on function member_passkey_login(uuid, uuid, text, uuid, bigint, boolean) to service_role;\ngrant execute on function member_passkeys_list(uuid, uuid, integer) to service_role;\ngrant execute on function member_passkey_delete(uuid, uuid, integer, uuid) to service_role;\ngrant execute on function member_passkeys_reset(uuid, uuid) to authenticated;\ngrant execute on function member_passkey_cleanup() to service_role;\n\ninsert into banto_migrations (version) values ('0046_mod_passkey');\n" },
  { version: "0047_customer_master", sql: "-- Banto 0047_customer_master: 顧客マスタの外部連携の器（人間の決定 2026-10-23、docs/knowledge/13-external-customer-master.md）。前方専用。\n--\n-- 方針（項目ごとに向きを 1 つ。同じ項目を両側で直す双方向は持たない）:\n--   身元（email・ログイン・セッション・世代）     … Banto が正。外へ知らせるだけ。外部から変えない（0036 と同じ）\n--   氏名・住所                                     … Banto が正（本人が会員ページで直せる）。Banto → 外部\n--   マーケティングの属性（ランク・同意・タグ等）   … 外部が正。外部 → Banto（customers.attributes）。Banto は読むだけ\n-- 外部 → Banto は既存の AI 用トークンの API（customers:write）を通る。Banto の行が唯一の正で、入口が 2 つあるだけ。\n--\n-- このマイグレーションで足すもの:\n--   customers.external_ref  … {\"provider\": \"hubspot\", \"id\": \"…\"}。ショップ × provider × id で一意\n--   customers.attributes    … 独自項目の値。定義は shops.settings.customer_fields（products.attributes / product_fields と同じ宣言型）。\n--                             定義に無い鍵は受け付けない（banto_customer_attributes）\n--   hooks customer.created / customer.updated / customer.deleted … customers のトリガーで積む。ペイロードは id と external_ref だけ（個人情報なし）\n--   api_customers_list      … external_ref と updated_since で絞る（同期の取り込み向け）\n--   api_customer_create / update … attributes と external_ref を受ける\n--   api_customer_upsert     … メールアドレスで引いて無ければ作る（email は変えない）\n--   restore_customer_master … 復元の後で external_ref と attributes を戻す\n\n-- ---------- 列 ----------\nalter table customers add column if not exists external_ref jsonb;\nalter table customers add column if not exists attributes jsonb not null default '{}'::jsonb;\n\n-- external_ref の形: provider と id の 2 つの文字列だけ\ncreate or replace function banto_external_ref_ok(p jsonb)\nreturns boolean language sql immutable as $$\n  select p is null\n      or (jsonb_typeof(p) = 'object'\n          and jsonb_typeof(p->'provider') = 'string' and jsonb_typeof(p->'id') = 'string'\n          and (p->>'provider') ~ '^[a-z][a-z0-9_]{0,31}$'\n          and char_length(p->>'id') between 1 and 200\n          and (p - 'provider' - 'id') = '{}'::jsonb)\n$$;\nrevoke execute on function banto_external_ref_ok(jsonb) from public, anon, authenticated;\n\nalter table customers add constraint customers_external_ref_shape check (banto_external_ref_ok(external_ref));\nalter table customers add constraint customers_attributes_shape check (jsonb_typeof(attributes) = 'object');\ncreate unique index customers_external_ref_uniq on customers (shop_id, (external_ref->>'provider'), (external_ref->>'id')) where external_ref is not null;\n\n-- 運営者（管理画面）は読める（0028 の列ごとの権限に足す。パスワードの列は引き続き読めない）\ngrant select (external_ref, attributes) on customers to authenticated;\n\n-- ---------- 独自項目の値の検査 ----------\n-- 定義（shops.settings.customer_fields: [{key, label, type, options}]）にある鍵だけ。型は product_fields と同じ\n-- text / textarea / number / url / select。null の値は「消す」（戻り値に含めない）。知らない鍵は invalid_attribute_<鍵>\ncreate or replace function banto_customer_attributes(p_shop_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_defs jsonb; v_def jsonb; v_k text; v_v jsonb; v_out jsonb := '{}'::jsonb; v_type text; v_s text; v_max integer;\nbegin\n  if p_values is null or jsonb_typeof(p_values) = 'null' then return '{}'::jsonb; end if;\n  if jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_attributes'; end if;\n  select settings->'customer_fields' into v_defs from shops where id = p_shop_id;\n  if v_defs is null or jsonb_typeof(v_defs) <> 'array' then v_defs := '[]'::jsonb; end if;\n  for v_k, v_v in select * from jsonb_each(p_values) loop\n    select d into v_def from jsonb_array_elements(v_defs) d\n     where jsonb_typeof(d) = 'object' and d->>'key' = v_k and (d->>'key') ~ '^[a-z][a-z0-9_]{0,39}$' limit 1;\n    if v_def is null then raise exception 'invalid_attribute_%', left(v_k, 40); end if;\n    if jsonb_typeof(v_v) = 'null' then continue; end if;\n    v_type := coalesce(v_def->>'type', 'text');\n    if v_type = 'number' then\n      if jsonb_typeof(v_v) = 'number' then\n        v_out := v_out || jsonb_build_object(v_k, v_v);\n      elsif jsonb_typeof(v_v) = 'string' and btrim(v_v #>> '{}') ~ '^-?[0-9]{1,15}(\\.[0-9]{1,6})?$' then\n        v_out := v_out || jsonb_build_object(v_k, (btrim(v_v #>> '{}'))::numeric);\n      else\n        raise exception 'invalid_attribute_%', left(v_k, 40);\n      end if;\n    else\n      if jsonb_typeof(v_v) not in ('string', 'number') then raise exception 'invalid_attribute_%', left(v_k, 40); end if;\n      v_s := btrim(v_v #>> '{}');\n      if v_s = '' then continue; end if;\n      v_max := 200; if v_type = 'textarea' then v_max := 500; end if;\n      if char_length(v_s) > v_max then raise exception 'invalid_attribute_%', left(v_k, 40); end if;\n      if v_type = 'url' and v_s !~ '^https?://' then raise exception 'invalid_attribute_%', left(v_k, 40); end if;\n      if v_type = 'select' and not (jsonb_typeof(v_def->'options') = 'array' and v_def->'options' @> to_jsonb(v_s)) then\n        raise exception 'invalid_attribute_%', left(v_k, 40);\n      end if;\n      v_out := v_out || jsonb_build_object(v_k, v_s);\n    end if;\n  end loop;\n  return v_out;\nend;\n$$;\nrevoke execute on function banto_customer_attributes(uuid, jsonb) from public, anon, authenticated;\n\n-- 今の値に p_values を重ねる（null の鍵は消す）\ncreate or replace function banto_customer_attributes_merge(p_shop_id uuid, p_current jsonb, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_clean jsonb; v_out jsonb;\nbegin\n  v_clean := banto_customer_attributes(p_shop_id, p_values);\n  v_out := coalesce(p_current, '{}'::jsonb);\n  if p_values is not null and jsonb_typeof(p_values) = 'object' then\n    v_out := v_out - array(select jsonb_object_keys(p_values));\n  end if;\n  return v_out || v_clean;\nend;\n$$;\nrevoke execute on function banto_customer_attributes_merge(uuid, jsonb, jsonb) from public, anon, authenticated;\n\n-- external_ref の入力（API）。null で外す。形が違えば invalid_external_ref\ncreate or replace function banto_customer_external_ref(p jsonb)\nreturns jsonb\nlanguage plpgsql\nimmutable\nas $$\ndeclare v jsonb;\nbegin\n  if p is null or jsonb_typeof(p) = 'null' then return null; end if;\n  if jsonb_typeof(p) <> 'object' or jsonb_typeof(p->'provider') <> 'string' or jsonb_typeof(p->'id') <> 'string' then raise exception 'invalid_external_ref'; end if;\n  v := jsonb_build_object('provider', btrim(p->>'provider'), 'id', btrim(p->>'id'));\n  if not banto_external_ref_ok(v) or (p - 'provider' - 'id') <> '{}'::jsonb then raise exception 'invalid_external_ref'; end if;\n  return v;\nend;\n$$;\nrevoke execute on function banto_customer_external_ref(jsonb) from public, anon, authenticated;\n\n-- ---------- hooks: customer.created / customer.updated / customer.deleted ----------\n-- enqueue_hook は呼び手の役割で積めるイベントを絞る（0028 の M11）ので、トリガーは hook_deliveries に直接積む。\n-- 行が変わるのは RLS か service_role の RPC を通ったときだけなので、ここで権限を見直す必要は無い。\n-- updated はプロフィール（email・name・default_address・attributes・external_ref）が変わったときだけ。\n-- ログインの時刻・世代・パスワードの列では積まない。ペイロードに個人情報は載せない（要るプラグインは customers:read で引く）。\ncreate or replace function banto_customers_hook()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_shop uuid; v_id uuid; v_event text; v_ref jsonb;\nbegin\n  if tg_op = 'DELETE' then\n    v_shop := old.shop_id; v_id := old.id; v_ref := old.external_ref; v_event := 'customer.deleted';\n  elsif tg_op = 'INSERT' then\n    v_shop := new.shop_id; v_id := new.id; v_ref := new.external_ref; v_event := 'customer.created';\n  else\n    if new.email is not distinct from old.email and new.name is not distinct from old.name\n       and new.default_address is not distinct from old.default_address\n       and new.attributes is not distinct from old.attributes\n       and new.external_ref is not distinct from old.external_ref then\n      return null;\n    end if;\n    v_shop := new.shop_id; v_id := new.id; v_ref := new.external_ref; v_event := 'customer.updated';\n  end if;\n  insert into hook_deliveries (shop_id, endpoint_id, event, payload)\n  select e.shop_id, e.id, v_event, jsonb_build_object('customer_id', v_id, 'shop_id', v_shop, 'external_ref', v_ref)\n    from hook_endpoints e\n   where e.shop_id = v_shop and e.enabled and v_event = any(e.events);\n  return null;\nend;\n$$;\nrevoke execute on function banto_customers_hook() from public, anon, authenticated;\ndrop trigger if exists customers_hooks on customers;\ncreate trigger customers_hooks after insert or update or delete on customers for each row execute function banto_customers_hook();\n\n-- ---------- AI 用 API（0036 を差し替え） ----------\ncreate or replace function api_customer_json(p_c customers)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_c.id, 'email', p_c.email, 'name', p_c.name, 'default_address', p_c.default_address,\n    'external_ref', p_c.external_ref, 'attributes', coalesce(p_c.attributes, '{}'::jsonb),\n    'created_at', p_c.created_at, 'updated_at', p_c.updated_at, 'last_login_at', p_c.last_login_at,\n    'orders', (select jsonb_build_object('count', count(*), 'total_jpy', coalesce(sum(o.total_jpy), 0), 'last_order_at', max(o.created_at))\n                 from orders o where o.shop_id = p_c.shop_id and o.customer_id = p_c.id and o.status in ('paid', 'shipped'))\n  );\n$$;\nrevoke execute on function api_customer_json(customers) from public, anon, authenticated;\n\n-- 一覧・検索。external_ref（provider と id の完全一致。id を省けば provider だけ）と updated_since（その時刻以後に変わった会員、updated_at の昇順）を足す\ndrop function if exists api_customers_list(text, text, text, integer, integer);\ncreate or replace function api_customers_list(p_token_hash text, p_query text default null, p_email text default null,\n                                              p_limit integer default 50, p_offset integer default 0,\n                                              p_external_provider text default null, p_external_id text default null,\n                                              p_updated_since timestamptz default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_limit integer; v_offset integer; v_total integer; v_items jsonb; v_q text; v_email text; v_prov text; v_ext text;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:read');\n  v_limit := greatest(1, least(coalesce(p_limit, 50), 100));\n  v_offset := greatest(0, coalesce(p_offset, 0));\n  v_q := case when nullif(btrim(p_query), '') is not null then '%' || banto_like_escape(btrim(p_query)) || '%' end;\n  v_email := nullif(lower(btrim(p_email)), '');\n  v_prov := nullif(btrim(p_external_provider), '');\n  v_ext := nullif(btrim(p_external_id), '');\n  if v_ext is not null and v_prov is null then raise exception 'invalid_external_ref'; end if;\n  select count(*) into v_total from customers c\n   where c.shop_id = v_tok.shop_id\n     and (v_email is null or lower(c.email) = v_email)\n     and (v_q is null or c.email ilike v_q or c.name ilike v_q)\n     and (v_prov is null or c.external_ref->>'provider' = v_prov)\n     and (v_ext is null or c.external_ref->>'id' = v_ext)\n     and (p_updated_since is null or c.updated_at >= p_updated_since);\n  select coalesce(jsonb_agg(api_customer_json(c)), '[]'::jsonb) into v_items\n    from (select * from customers c\n           where c.shop_id = v_tok.shop_id\n             and (v_email is null or lower(c.email) = v_email)\n             and (v_q is null or c.email ilike v_q or c.name ilike v_q)\n             and (v_prov is null or c.external_ref->>'provider' = v_prov)\n             and (v_ext is null or c.external_ref->>'id' = v_ext)\n             and (p_updated_since is null or c.updated_at >= p_updated_since)\n           order by case when p_updated_since is null then null else c.updated_at end asc,\n                    case when p_updated_since is null then c.created_at end desc, c.id\n           limit v_limit offset v_offset) c;\n  return jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', v_offset);\nend;\n$$;\n\n-- 作る。attributes と external_ref も受ける\ncreate or replace function api_customer_create(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_email text; v_name text; v_c customers%rowtype; v_key text;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:write');\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key in select jsonb_object_keys(p_values) loop\n    if v_key not in ('email', 'name', 'default_address', 'attributes', 'external_ref') then raise exception 'invalid_field_%', left(v_key, 40); end if;\n  end loop;\n  v_email := lower(btrim(coalesce(p_values->>'email', '')));\n  if jsonb_typeof(p_values->'email') <> 'string' or length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  if p_values ? 'name' and jsonb_typeof(p_values->'name') not in ('string', 'null') then raise exception 'invalid_name'; end if;\n  v_name := nullif(btrim(coalesce(p_values->>'name', '')), '');\n  if length(v_name) > 200 then raise exception 'invalid_name'; end if;\n  if exists (select 1 from customers where shop_id = v_tok.shop_id and lower(email) = v_email) then raise exception 'email_taken'; end if;\n  begin\n    insert into customers (shop_id, email, name, default_address, attributes, external_ref)\n    values (v_tok.shop_id, v_email, v_name, banto_api_address(p_values->'default_address'),\n            banto_customer_attributes(v_tok.shop_id, p_values->'attributes'), banto_customer_external_ref(p_values->'external_ref'))\n    returning * into v_c;\n  exception when unique_violation then\n    raise exception 'external_ref_taken';\n  end;\n  return api_customer_json(v_c);\nend;\n$$;\n\n-- 氏名・住所・属性・外部の ID を変える。メールアドレスは変えない（email_change_not_allowed）。attributes は渡した鍵だけ重ねる（null で消す）\ncreate or replace function api_customer_update(p_token_hash text, p_customer_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_c customers%rowtype; v_key text; v_name text;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:write');\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key in select jsonb_object_keys(p_values) loop\n    if v_key = 'email' then raise exception 'email_change_not_allowed'; end if;\n    if v_key not in ('name', 'default_address', 'attributes', 'external_ref') then raise exception 'invalid_field_%', left(v_key, 40); end if;\n  end loop;\n  select * into v_c from customers where shop_id = v_tok.shop_id and id = p_customer_id for update;\n  if not found then raise exception 'not_found'; end if;\n  if p_values ? 'name' then\n    if jsonb_typeof(p_values->'name') not in ('string', 'null') then raise exception 'invalid_name'; end if;\n    v_name := nullif(btrim(coalesce(p_values->>'name', '')), '');\n    if length(v_name) > 200 then raise exception 'invalid_name'; end if;\n    v_c.name := v_name;\n  end if;\n  if p_values ? 'default_address' then v_c.default_address := banto_api_address(p_values->'default_address'); end if;\n  if p_values ? 'attributes' then v_c.attributes := banto_customer_attributes_merge(v_tok.shop_id, v_c.attributes, p_values->'attributes'); end if;\n  if p_values ? 'external_ref' then v_c.external_ref := banto_customer_external_ref(p_values->'external_ref'); end if;\n  begin\n    update customers set name = v_c.name, default_address = v_c.default_address, attributes = v_c.attributes, external_ref = v_c.external_ref\n     where shop_id = v_tok.shop_id and id = p_customer_id\n    returning * into v_c;\n  exception when unique_violation then\n    raise exception 'external_ref_taken';\n  end;\n  return api_customer_json(v_c);\nend;\n$$;\n\n-- メールアドレスで引いて、あれば渡した鍵だけ更新、無ければ作る（外部のマスタからの同期の窓口）。\n-- email は身元なので変えない: 外部で変わったアドレスで呼ぶと、別の会員として作られる。そのとき同じ external_ref が\n-- 既にあれば external_ref_taken で止まる（連携側が気づいて、運営者が管理画面で変える）。戻り値に created を付ける\ncreate or replace function api_customer_upsert(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_email text; v_c customers%rowtype; v_key text; v_out jsonb;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:write');\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key in select jsonb_object_keys(p_values) loop\n    if v_key not in ('email', 'name', 'default_address', 'attributes', 'external_ref') then raise exception 'invalid_field_%', left(v_key, 40); end if;\n  end loop;\n  v_email := lower(btrim(coalesce(p_values->>'email', '')));\n  if jsonb_typeof(p_values->'email') <> 'string' or length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  -- 同じアドレスの同時の呼び出しを直列にする（2 人作らない）\n  perform pg_advisory_xact_lock(hashtext('customer_upsert:' || v_tok.shop_id::text || ':' || v_email));\n  select * into v_c from customers where shop_id = v_tok.shop_id and lower(email) = v_email for update;\n  if found then\n    v_out := api_customer_update(p_token_hash, v_c.id, p_values - 'email');\n    return v_out || jsonb_build_object('created', false);\n  end if;\n  v_out := api_customer_create(p_token_hash, p_values);\n  return v_out || jsonb_build_object('created', true);\nend;\n$$;\n\nrevoke execute on function api_customers_list(text, text, text, integer, integer, text, text, timestamptz) from public, anon, authenticated;\nrevoke execute on function api_customer_create(text, jsonb) from public, anon, authenticated;\nrevoke execute on function api_customer_update(text, uuid, jsonb) from public, anon, authenticated;\nrevoke execute on function api_customer_upsert(text, jsonb) from public, anon, authenticated;\ngrant execute on function api_customers_list(text, text, text, integer, integer, text, text, timestamptz) to service_role;\ngrant execute on function api_customer_create(text, jsonb) to service_role;\ngrant execute on function api_customer_update(text, uuid, jsonb) to service_role;\ngrant execute on function api_customer_upsert(text, jsonb) to service_role;\n\n-- ---------- 復元 ----------\n-- restore_shop_data（0012）の後に呼ぶ。会員は同じ id で戻っているので、id で突き合わせて external_ref と attributes を戻す。\n-- 形の合わない external_ref・重なる external_ref は飛ばす（attributes は定義を通さずそのまま戻す。書き出したときの値のため）\ncreate or replace function restore_customer_master(p_shop_id uuid, p_data jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_row jsonb; v_n integer := 0; v_customers jsonb := coalesce(p_data->'customers', '[]'::jsonb); v_ref jsonb; v_attrs jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'restore_customer_master: service_role only' using errcode = '42501';\n  end if;\n  if jsonb_typeof(v_customers) <> 'array' then raise exception 'invalid_export'; end if;\n  for v_row in select * from jsonb_array_elements(v_customers) loop\n    if jsonb_typeof(v_row) <> 'object' or (v_row->>'id') is null then continue; end if;\n    v_ref := case when banto_external_ref_ok(v_row->'external_ref') then v_row->'external_ref' end;\n    v_attrs := case when jsonb_typeof(v_row->'attributes') = 'object' then v_row->'attributes' else '{}'::jsonb end;\n    if v_ref is null and v_attrs = '{}'::jsonb then continue; end if;\n    begin\n      update customers set external_ref = v_ref, attributes = v_attrs\n       where shop_id = p_shop_id and id = (v_row->>'id')::uuid;\n      if found then v_n := v_n + 1; end if;\n    exception when unique_violation or invalid_text_representation then\n      null;\n    end;\n  end loop;\n  return jsonb_build_object('customer_master', v_n);\nend;\n$$;\nrevoke execute on function restore_customer_master(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function restore_customer_master(uuid, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0047_customer_master');\n" },
  { version: "0048_customer_attributes_admin", sql: "-- Banto 0048_customer_attributes_admin: 運営者が管理画面で会員の独自項目（customers.attributes、0047）を直す（人間の決定 2026-10-23）。前方専用。\n--\n-- CRM を契約しない運営者は Banto 自身を顧客マスタとして使う。そのために「会員の項目を手で直せる・絞れる・CSV に書き出せる」\n-- までを管理画面に置く（docs/knowledge/13-external-customer-master.md）。メール配信や営業の進捗のような CRM の機能はコアに入れない。\n-- 絞り込みと CSV は読むだけ（owner の RLS の経路、0047 で列の権限を付けた）。書くのはこの関数だけ:\n--   customer_set_attributes(shop, customer, values) … 項目 customers を持つ人。値の検査は 0047 の banto_customer_attributes と同じ\n--   （定義に無い鍵は受け付けない。渡した鍵だけ重ね、null で消す）。customers への直接の UPDATE は引き続き誰にも許さない。\ncreate or replace function customer_set_attributes(p_shop_id uuid, p_customer_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_c customers%rowtype; v_out jsonb;\nbegin\n  if not banto_shop_perm(p_shop_id, 'customers') then\n    raise exception 'shop_not_found' using errcode = '42501';\n  end if;\n  select * into v_c from customers where shop_id = p_shop_id and id = p_customer_id for update;\n  if not found then raise exception 'customer_not_found'; end if;\n  update customers set attributes = banto_customer_attributes_merge(p_shop_id, v_c.attributes, p_values)\n   where shop_id = p_shop_id and id = p_customer_id\n  returning attributes into v_out;\n  return v_out;\nend;\n$$;\nrevoke execute on function customer_set_attributes(uuid, uuid, jsonb) from public, anon;\ngrant execute on function customer_set_attributes(uuid, uuid, jsonb) to authenticated, service_role;\n\ninsert into banto_migrations (version) values ('0048_customer_attributes_admin');\n" },
  { version: "0049_coupon_attributes", sql: "-- Banto 0049_coupon_attributes: クーポンの条件に会員の独自項目（customers.attributes、0047）を足す（人間の要望 2026-10-23）。前方専用。\n--   conditions.attributes … { \"<鍵>\": [\"値\", ...] }。ログイン中の会員のその項目の値が、どれかに合うときだけ使える（鍵が複数なら全部）。\n--                           ゲストには使えない。鍵はショップの設定「会員の項目」（customer_fields）にあるものだけ\n-- 判定は src/commerce/discounts.ts だけ（CLAUDE.md §7 基準 (1)）。ここは値の検査（banto_api_coupon_apply、AI 用 API と CSV の取り込み）と、\n-- 判定の材料（coupon_lookup）にログイン中の会員の attributes を載せるだけ。DB の往復は増やさない（速度の予算）。\n\n-- ---------- クーポンの条件の検査（0044 を置き換える。attributes を受け付ける） ----------\ncreate or replace function banto_api_coupon_apply(p_shop_id uuid, p_c coupon_campaigns, p_values jsonb)\nreturns coupon_campaigns\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_key text; v_val jsonb; v_cond jsonb; v_ck text; v_cv jsonb; v_ids uuid[]; v_n integer; v_s text; v_tags text[];\n  v_defs jsonb; v_def jsonb; v_ak text; v_av jsonb; v_attr jsonb;\nbegin\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key, v_val in select * from jsonb_each(p_values) loop\n    case v_key\n      when 'name' then\n        v_s := btrim(coalesce(v_val #>> '{}', ''));\n        if jsonb_typeof(v_val) <> 'string' or length(v_s) not between 1 and 100 then raise exception 'invalid_name'; end if;\n        p_c.name := v_s;\n      when 'code' then\n        if jsonb_typeof(v_val) = 'null' or btrim(v_val #>> '{}') = '' then p_c.code := null;\n        else\n          v_s := upper(btrim(v_val #>> '{}'));\n          if jsonb_typeof(v_val) <> 'string' or v_s !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$' then raise exception 'invalid_code'; end if;\n          p_c.code := v_s;\n        end if;\n      when 'kind' then\n        if jsonb_typeof(v_val) <> 'string' or v_val #>> '{}' not in ('percent', 'fixed', 'free_shipping') then raise exception 'invalid_kind'; end if;\n        p_c.kind := v_val #>> '{}';\n      when 'value' then\n        if jsonb_typeof(v_val) <> 'number' or (v_val #>> '{}') !~ '^\\d+$' then raise exception 'invalid_value'; end if;\n        p_c.value := (v_val #>> '{}')::integer;\n      when 'starts_at', 'ends_at' then\n        if jsonb_typeof(v_val) not in ('string', 'null') then raise exception 'invalid_%', v_key; end if;\n        begin\n          if v_key = 'starts_at' then p_c.starts_at := (v_val #>> '{}')::timestamptz; else p_c.ends_at := (v_val #>> '{}')::timestamptz; end if;\n        exception when others then raise exception 'invalid_%', v_key;\n        end;\n      when 'usage_limit', 'per_customer_limit', 'grant_valid_days' then\n        if jsonb_typeof(v_val) = 'null' then v_n := null;\n        elsif jsonb_typeof(v_val) = 'number' and (v_val #>> '{}') ~ '^\\d{1,7}$' then v_n := (v_val #>> '{}')::integer;\n        else raise exception 'invalid_%', v_key;\n        end if;\n        if v_key = 'usage_limit' then\n          if v_n is not null and v_n not between 1 and 100000 then raise exception 'invalid_usage_limit'; end if;\n          p_c.usage_limit := v_n;\n        elsif v_key = 'per_customer_limit' then\n          if v_n is not null and v_n not between 1 and 1000 then raise exception 'invalid_per_customer_limit'; end if;\n          p_c.per_customer_limit := v_n;\n        else\n          if v_n is not null and v_n not between 1 and 3650 then raise exception 'invalid_grant_valid_days'; end if;\n          p_c.grant_valid_days := v_n;\n        end if;\n      when 'combinable', 'active', 'claimable' then\n        if jsonb_typeof(v_val) <> 'boolean' then raise exception 'invalid_%', v_key; end if;\n        if v_key = 'combinable' then p_c.combinable := v_val::boolean;\n        elsif v_key = 'active' then p_c.active := v_val::boolean;\n        else p_c.claimable := v_val::boolean;\n        end if;\n      when 'audience' then\n        if jsonb_typeof(v_val) <> 'string' or v_val #>> '{}' not in ('public', 'members') then raise exception 'invalid_audience'; end if;\n        p_c.audience := v_val #>> '{}';\n      when 'auto_grant' then\n        if jsonb_typeof(v_val) = 'null' then p_c.auto_grant := null;\n        elsif jsonb_typeof(v_val) = 'string' and v_val #>> '{}' in ('first_login', 'after_purchase') then p_c.auto_grant := v_val #>> '{}';\n        else raise exception 'invalid_auto_grant';\n        end if;\n      when 'external_ref' then\n        if jsonb_typeof(v_val) = 'null' or btrim(v_val #>> '{}') = '' then p_c.external_ref := null;\n        elsif jsonb_typeof(v_val) = 'string' and length(btrim(v_val #>> '{}')) <= 100 then p_c.external_ref := btrim(v_val #>> '{}');\n        else raise exception 'invalid_external_ref';\n        end if;\n      when 'conditions' then\n        if jsonb_typeof(v_val) = 'null' then v_val := '{}'::jsonb; end if;\n        if jsonb_typeof(v_val) <> 'object' then raise exception 'invalid_conditions'; end if;\n        v_cond := '{}'::jsonb;\n        for v_ck, v_cv in select * from jsonb_each(v_val) loop\n          if jsonb_typeof(v_cv) = 'null' then continue; end if;\n          case v_ck\n            when 'product_ids', 'exclude_product_ids', 'category_ids', 'exclude_category_ids' then\n              if jsonb_typeof(v_cv) <> 'array' or jsonb_array_length(v_cv) > 200\n                 or exists (select 1 from jsonb_array_elements(v_cv) e\n                             where jsonb_typeof(e) <> 'string' or (e #>> '{}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              select coalesce(array_agg(distinct (e #>> '{}')::uuid), '{}') into v_ids from jsonb_array_elements(v_cv) e;\n              if v_ck in ('product_ids', 'exclude_product_ids') then\n                if (select count(*) from products where shop_id = p_shop_id and id = any(v_ids)) <> coalesce(array_length(v_ids, 1), 0) then raise exception 'invalid_conditions_unknown_products'; end if;\n              else\n                if (select count(*) from categories where shop_id = p_shop_id and id = any(v_ids)) <> coalesce(array_length(v_ids, 1), 0) then raise exception 'invalid_conditions_unknown_categories'; end if;\n              end if;\n              if coalesce(array_length(v_ids, 1), 0) > 0 then v_cond := v_cond || jsonb_build_object(v_ck, to_jsonb(v_ids)); end if;\n            when 'tags', 'exclude_tags' then\n              -- タグ（0042）。商品のタグと同じ正規化（src/products/tags.ts）。20 個まで\n              if jsonb_typeof(v_cv) <> 'array' or jsonb_array_length(v_cv) > 20\n                 or exists (select 1 from jsonb_array_elements(v_cv) e where jsonb_typeof(e) <> 'string') then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              v_tags := banto_normalize_tags(v_cv);\n              if coalesce(array_length(v_tags, 1), 0) > 0 then v_cond := v_cond || jsonb_build_object(v_ck, to_jsonb(v_tags)); end if;\n            when 'brands', 'exclude_brands' then\n              -- ブランド（0044）。商品のブランドと前後の空白・大文字小文字を区別せずに比べる。20 個・1 個 100 文字まで\n              if jsonb_typeof(v_cv) <> 'array' or jsonb_array_length(v_cv) > 20\n                 or exists (select 1 from jsonb_array_elements(v_cv) e where jsonb_typeof(e) <> 'string' or length(btrim(e #>> '{}')) not between 1 and 100) then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              select coalesce(array_agg(distinct btrim(e #>> '{}')), '{}') into v_tags from jsonb_array_elements(v_cv) e;\n              if coalesce(array_length(v_tags, 1), 0) > 0 then v_cond := v_cond || jsonb_build_object(v_ck, to_jsonb(v_tags)); end if;\n            when 'payment_methods' then\n              -- 支払い方法（0044）: stripe / komoju / komoju:<種類>。判定は src/commerce/discounts.ts\n              if jsonb_typeof(v_cv) <> 'array' or jsonb_array_length(v_cv) > 20\n                 or exists (select 1 from jsonb_array_elements(v_cv) e where jsonb_typeof(e) <> 'string' or (e #>> '{}') !~ '^(stripe|komoju|komoju:[a-z_]{1,40})$') then\n                raise exception 'invalid_conditions_payment_methods';\n              end if;\n              select coalesce(array_agg(distinct e #>> '{}'), '{}') into v_tags from jsonb_array_elements(v_cv) e;\n              if coalesce(array_length(v_tags, 1), 0) > 0 then v_cond := v_cond || jsonb_build_object('payment_methods', to_jsonb(v_tags)); end if;\n            when 'exclude_sale' then\n              if jsonb_typeof(v_cv) <> 'boolean' then raise exception 'invalid_conditions_exclude_sale'; end if;\n              if v_cv::boolean then v_cond := v_cond || jsonb_build_object('exclude_sale', true); end if;\n            when 'min_subtotal_jpy', 'max_subtotal_jpy', 'min_qty' then\n              -- 上限: 点数は 999、金額は 1 億円（管理画面と同じ）\n              v_n := 100000000;\n              if v_ck = 'min_qty' then v_n := 999; end if;\n              if jsonb_typeof(v_cv) <> 'number' or (v_cv #>> '{}') !~ '^\\d{1,9}$' or (v_cv #>> '{}')::integer > v_n then\n                raise exception 'invalid_conditions_%', v_ck;\n              end if;\n              v_cond := v_cond || jsonb_build_object(v_ck, (v_cv #>> '{}')::integer);\n            when 'attributes' then\n              -- 会員の独自項目（0049）: { \"<鍵>\": [\"値\", ...] }。鍵はショップの設定 customer_fields にあるものだけ（10 個まで）、\n              -- 値は文字列か数で 1 個 100 文字・20 個まで。select の項目は選択肢の中だけ。判定は src/commerce/discounts.ts\n              if jsonb_typeof(v_cv) <> 'object' then raise exception 'invalid_conditions_attributes'; end if;\n              select settings->'customer_fields' into v_defs from shops where id = p_shop_id;\n              if v_defs is null or jsonb_typeof(v_defs) <> 'array' then v_defs := '[]'::jsonb; end if;\n              v_attr := '{}'::jsonb;\n              for v_ak, v_av in select * from jsonb_each(v_cv) loop\n                if jsonb_typeof(v_av) = 'null' then continue; end if;\n                select d into v_def from jsonb_array_elements(v_defs) d where jsonb_typeof(d) = 'object' and d->>'key' = v_ak limit 1;\n                if v_def is null then raise exception 'invalid_conditions_attributes_%', left(v_ak, 40); end if;\n                if jsonb_typeof(v_av) <> 'array' or jsonb_array_length(v_av) > 20\n                   or exists (select 1 from jsonb_array_elements(v_av) e\n                               where jsonb_typeof(e) not in ('string', 'number') or length(btrim(e #>> '{}')) not between 1 and 100) then\n                  raise exception 'invalid_conditions_attributes_%', left(v_ak, 40);\n                end if;\n                select coalesce(array_agg(distinct btrim(e #>> '{}')), '{}') into v_tags from jsonb_array_elements(v_av) e;\n                if v_def->>'type' = 'select' and exists (select 1 from unnest(v_tags) t where not (coalesce(v_def->'options', '[]'::jsonb) @> to_jsonb(t))) then\n                  raise exception 'invalid_conditions_attributes_%', left(v_ak, 40);\n                end if;\n                if coalesce(array_length(v_tags, 1), 0) > 0 then v_attr := v_attr || jsonb_build_object(v_ak, to_jsonb(v_tags)); end if;\n              end loop;\n              if (select count(*) from jsonb_object_keys(v_attr)) > 10 then raise exception 'invalid_conditions_attributes'; end if;\n              if v_attr <> '{}'::jsonb then v_cond := v_cond || jsonb_build_object('attributes', v_attr); end if;\n            else raise exception 'invalid_conditions_unknown_key';\n          end case;\n        end loop;\n        p_c.conditions := v_cond;\n      else raise exception 'invalid_field_%', left(v_key, 40);\n    end case;\n  end loop;\n  -- 種類と値の組み合わせ（テーブルの CHECK と同じ。わかりやすい理由で返す）\n  if p_c.kind = 'free_shipping' then p_c.value := 0;\n  elsif p_c.kind = 'percent' and p_c.value not between 1 and 100 then raise exception 'invalid_value';\n  elsif p_c.kind = 'fixed' and p_c.value not between 1 and 10000000 then raise exception 'invalid_value';\n  end if;\n  if p_c.starts_at is not null and p_c.ends_at is not null and p_c.starts_at >= p_c.ends_at then raise exception 'invalid_ends_at'; end if;\n  return p_c;\nend;\n$$;\n\n-- ---------- 判定の材料（0019 を差し替え: p_customer_id を受け、会員の attributes を各行に載せる） ----------\ndrop function if exists coupon_lookup(uuid, text[], text);\ncreate or replace function coupon_lookup(p_shop_id uuid, p_codes text[], p_subject text default null, p_customer_id uuid default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_codes text[]; v_out jsonb; v_grants jsonb; v_attrs jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'coupon_lookup: service_role only' using errcode = '42501';\n  end if;\n  select array_agg(x) into v_codes from (select upper(btrim(x)) as x from unnest(coalesce(p_codes, '{}'::text[])) x limit 5) t;\n  -- ログイン中の会員の独自項目（0047）。会員でなければ null（条件 attributes のあるクーポンは使えない）\n  if p_customer_id is not null then\n    select attributes into v_attrs from customers where shop_id = p_shop_id and id = p_customer_id;\n  end if;\n  select coalesce(jsonb_agg(jsonb_build_object(\n      'id', c.id, 'name', c.name, 'code', c.code, 'kind', c.kind, 'value', c.value,\n      'starts_at', c.starts_at, 'ends_at', c.ends_at, 'usage_limit', c.usage_limit, 'per_customer_limit', c.per_customer_limit,\n      'combinable', c.combinable, 'audience', c.audience, 'conditions', c.conditions, 'active', c.active,\n      'used_by_subject', case when p_subject is null or c.per_customer_limit is null then 0 else (\n        select count(*) from coupon_redemptions r where r.campaign_id = c.id and r.subject = p_subject and r.status <> 'released') end,\n      'available', c.usage_limit is null or exists (select 1 from coupon_slots s where s.campaign_id = c.id and s.status = 'free'),\n      'customer_attributes', v_attrs\n    )), '[]'::jsonb)\n    into v_out\n    from coupon_campaigns c\n   where c.shop_id = p_shop_id and c.code = any (coalesce(v_codes, '{}'::text[]));\n  select coalesce(jsonb_agg(jsonb_build_object(\n      'id', c.id, 'name', c.name, 'code', g.code, 'kind', c.kind, 'value', c.value,\n      'starts_at', c.starts_at, 'ends_at', c.ends_at, 'usage_limit', null, 'per_customer_limit', null,\n      'combinable', c.combinable, 'audience', c.audience, 'conditions', c.conditions, 'active', c.active,\n      'used_by_subject', 0, 'available', true, 'customer_attributes', v_attrs,\n      'grant', jsonb_build_object('id', g.id, 'status', g.status, 'expires_at', g.expires_at, 'customer_id', g.customer_id)\n    )), '[]'::jsonb)\n    into v_grants\n    from coupon_grants g join coupon_campaigns c on c.id = g.campaign_id\n   where g.shop_id = p_shop_id and g.code = any (coalesce(v_codes, '{}'::text[]))\n     and not exists (select 1 from coupon_campaigns c2 where c2.shop_id = p_shop_id and c2.code = g.code);\n  return v_out || v_grants;\nend;\n$$;\nrevoke execute on function coupon_lookup(uuid, text[], text, uuid) from public, anon, authenticated;\ngrant execute on function coupon_lookup(uuid, text[], text, uuid) to service_role;\n\ninsert into banto_migrations (version) values ('0049_coupon_attributes');\n" },
  { version: "0050_marketing_consent", sql: "-- Banto 0050_marketing_consent: 「お得な情報やセールの案内を受け取る」の同意（人間の決定 2026-10-23、docs/knowledge/13-external-customer-master.md 段階 1c）。前方専用。\n--\n-- 同意は本人が Banto の画面で行う行為なので、Banto が規定の列として持つ（attributes には置かない。基準 (1) 法務 → 記録はコア）。\n--   customers.marketing_consent         true / false / null（未回答）\n--   customers.marketing_consent_at      いつ\n--   customers.marketing_consent_source  どこで: checkout / account / import / api / admin\n--   orders.marketing_consent            注文のときの選択（ゲストの注文はここにだけ残る）\n-- 向き（この列だけ特別）:\n--   true  … 本人の行為だけ（レジ・会員ページ。取り込みは import）。外部の API・運営者からは付けられない\n--   false … どこで起きても正しい（MA の配信停止 → API、会員ページ、運営者の「同意を外す」）\n-- 出す / 出さないはショップの設定 settings.marketing_consent（既定 OFF）。ON のショップのレジと会員ページにチェックが出る。\n-- 文言の適法性は、最終確認画面と同じく専門家の確認が未実施（docs/members.md）。\n\n-- ---------- 列 ----------\nalter table customers add column if not exists marketing_consent boolean;\nalter table customers add column if not exists marketing_consent_at timestamptz;\nalter table customers add column if not exists marketing_consent_source text check (marketing_consent_source in ('checkout', 'account', 'import', 'api', 'admin'));\nalter table orders add column if not exists marketing_consent boolean;\ngrant select (marketing_consent, marketing_consent_at, marketing_consent_source) on customers to authenticated;\n\n-- API の値（false だけ受ける。true は consent_requires_person）\ncreate or replace function banto_api_consent_false(p_values jsonb)\nreturns boolean\nlanguage plpgsql\nimmutable\nas $$\nbegin\n  if p_values is null or not (p_values ? 'marketing_consent') then return false; end if;\n  if jsonb_typeof(p_values->'marketing_consent') = 'boolean' and not (p_values->'marketing_consent')::boolean then return true; end if;\n  if jsonb_typeof(p_values->'marketing_consent') = 'boolean' then raise exception 'consent_requires_person'; end if;\n  raise exception 'invalid_marketing_consent';\nend;\n$$;\nrevoke execute on function banto_api_consent_false(jsonb) from public, anon, authenticated;\n\n-- ---------- 注文 → 会員（レジで選んだ同意を写す） ----------\n-- 予約の購入者情報（attach_reservation_customer の JSON）に marketing_consent があれば、confirm_reservation が作る注文の行に写し（before insert）、\n-- 会員の注文なら customers にも写す（after insert、source = checkout）。confirm_reservation 自体は触らない\ncreate or replace function banto_orders_consent_before()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_consent text;\nbegin\n  if new.marketing_consent is null and new.reservation_id is not null then\n    select r.customer->>'marketing_consent' into v_consent from reservations r where r.id = new.reservation_id;\n    if v_consent in ('true', 'false') then new.marketing_consent := v_consent::boolean; end if;\n  end if;\n  return new;\nend;\n$$;\ncreate or replace function banto_orders_consent_after()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if new.customer_id is not null and new.marketing_consent is not null then\n    update customers\n       set marketing_consent = new.marketing_consent, marketing_consent_at = now(), marketing_consent_source = 'checkout'\n     where shop_id = new.shop_id and id = new.customer_id and marketing_consent is distinct from new.marketing_consent;\n  end if;\n  return null;\nend;\n$$;\nrevoke execute on function banto_orders_consent_before() from public, anon, authenticated;\nrevoke execute on function banto_orders_consent_after() from public, anon, authenticated;\ndrop trigger if exists orders_consent_before on orders;\ndrop trigger if exists orders_consent_after on orders;\ncreate trigger orders_consent_before before insert on orders for each row execute function banto_orders_consent_before();\ncreate trigger orders_consent_after after insert on orders for each row execute function banto_orders_consent_after();\n\n-- ---------- 会員ページ（本人の行為。service_role、世代を確かめる） ----------\ncreate or replace function member_set_marketing_consent(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_consent boolean)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_set_marketing_consent: service_role only' using errcode = '42501';\n  end if;\n  if p_consent is null then raise exception 'invalid_marketing_consent'; end if;\n  update customers\n     set marketing_consent = p_consent, marketing_consent_at = now(), marketing_consent_source = 'account'\n   where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch;\n  return found;\nend;\n$$;\nrevoke execute on function member_set_marketing_consent(uuid, uuid, integer, boolean) from public, anon, authenticated;\ngrant execute on function member_set_marketing_consent(uuid, uuid, integer, boolean) to service_role;\n\n-- ---------- 運営者: 同意を外す（付けることはできない） ----------\ncreate or replace function customer_marketing_consent_withdraw(p_shop_id uuid, p_customer_id uuid)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not banto_shop_perm(p_shop_id, 'customers') then\n    raise exception 'shop_not_found' using errcode = '42501';\n  end if;\n  update customers\n     set marketing_consent = false, marketing_consent_at = now(), marketing_consent_source = 'admin'\n   where shop_id = p_shop_id and id = p_customer_id and marketing_consent is distinct from false;\n  return found;\nend;\n$$;\nrevoke execute on function customer_marketing_consent_withdraw(uuid, uuid) from public, anon;\ngrant execute on function customer_marketing_consent_withdraw(uuid, uuid) to authenticated, service_role;\n\n-- ---------- 会員ページの読み取り（0014 を差し替え: marketing_consent を返す） ----------\ncreate or replace function member_get(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_with_orders boolean default false)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_c customers%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_get: service_role only' using errcode = '42501';\n  end if;\n  select * into v_c from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch;\n  if not found then return null; end if;\n  return jsonb_build_object(\n    'customer', jsonb_build_object('id', v_c.id, 'shop_id', v_c.shop_id, 'email', v_c.email, 'name', v_c.name, 'default_address', v_c.default_address,\n                                   'marketing_consent', v_c.marketing_consent,\n                                   'has_password', v_c.password_hash is not null or v_c.legacy_password_hash is not null,\n                                   'providers', coalesce((select jsonb_agg(provider order by provider) from member_identities\n                                                           where shop_id = p_shop_id and customer_id = v_c.id), '[]'::jsonb)),\n    'orders', case when p_with_orders then coalesce((\n      select jsonb_agg(o order by o.created_at desc) from (\n        select id, number, status, total_jpy, shipping_jpy, coalesce(discount_jpy, 0) as discount_jpy, created_at, shipped_at\n          from orders where shop_id = p_shop_id and customer_id = p_customer_id\n         order by created_at desc limit 50) o), '[]'::jsonb) else '[]'::jsonb end);\nend;\n$$;\n\n-- ---------- お客様の画面に渡す settings（0041 を差し替え: marketing_consent の設定） ----------\ncreate or replace function banto_shop_public_settings(p jsonb)\nreturns jsonb language sql immutable as $$\n  select coalesce((select jsonb_object_agg(k, v) from jsonb_each(case when jsonb_typeof(p) = 'object' then p else '{}'::jsonb end) e(k, v)\n                    where k in ('theme', 'theme_settings', 'notice', 'shipping', 'modules', 'members_enabled', 'members_password',\n                                'checkout_terms', 'delivery_time', 'store_tryon', 'receipt', 'product_fields',\n                                'tax_rate', 'tax_rate_reduced', 'tax_rounding', 'storefront', 'analytics', 'marketing_consent')), '{}'::jsonb)\n      || case when jsonb_typeof(p->'headless') = 'object'\n              then jsonb_build_object('headless', jsonb_build_object('return_origins', coalesce(p->'headless'->'return_origins', '[]'::jsonb)))\n              else '{}'::jsonb end\n      || case when jsonb_typeof(p->'oauth') = 'object'\n              then jsonb_build_object('oauth', coalesce((\n                     select jsonb_object_agg(k, coalesce((select jsonb_object_agg(k2, v2) from jsonb_each(v) f(k2, v2) where k2 in ('client_id', 'bot_prompt')), '{}'::jsonb))\n                       from jsonb_each(p->'oauth') e(k, v) where jsonb_typeof(v) = 'object'), '{}'::jsonb))\n              else '{}'::jsonb end;\n$$;\nrevoke execute on function banto_shop_public_settings(jsonb) from public, anon, authenticated;\n\n-- ---------- hooks（0047 を差し替え: ペイロードに marketing_consent、同意の変化でも customer.updated） ----------\ncreate or replace function banto_customers_hook()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_shop uuid; v_id uuid; v_event text; v_ref jsonb; v_consent boolean;\nbegin\n  if tg_op = 'DELETE' then\n    v_shop := old.shop_id; v_id := old.id; v_ref := old.external_ref; v_consent := old.marketing_consent; v_event := 'customer.deleted';\n  elsif tg_op = 'INSERT' then\n    v_shop := new.shop_id; v_id := new.id; v_ref := new.external_ref; v_consent := new.marketing_consent; v_event := 'customer.created';\n  else\n    if new.email is not distinct from old.email and new.name is not distinct from old.name\n       and new.default_address is not distinct from old.default_address\n       and new.attributes is not distinct from old.attributes\n       and new.external_ref is not distinct from old.external_ref\n       and new.marketing_consent is not distinct from old.marketing_consent then\n      return null;\n    end if;\n    v_shop := new.shop_id; v_id := new.id; v_ref := new.external_ref; v_consent := new.marketing_consent; v_event := 'customer.updated';\n  end if;\n  insert into hook_deliveries (shop_id, endpoint_id, event, payload)\n  select e.shop_id, e.id, v_event, jsonb_build_object('customer_id', v_id, 'shop_id', v_shop, 'external_ref', v_ref, 'marketing_consent', v_consent)\n    from hook_endpoints e\n   where e.shop_id = v_shop and e.enabled and v_event = any(e.events);\n  return null;\nend;\n$$;\nrevoke execute on function banto_customers_hook() from public, anon, authenticated;\n\n-- ---------- AI 用 API（0047 を差し替え） ----------\ncreate or replace function api_customer_json(p_c customers)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_c.id, 'email', p_c.email, 'name', p_c.name, 'default_address', p_c.default_address,\n    'external_ref', p_c.external_ref, 'attributes', coalesce(p_c.attributes, '{}'::jsonb),\n    'marketing_consent', p_c.marketing_consent, 'marketing_consent_at', p_c.marketing_consent_at, 'marketing_consent_source', p_c.marketing_consent_source,\n    'created_at', p_c.created_at, 'updated_at', p_c.updated_at, 'last_login_at', p_c.last_login_at,\n    'orders', (select jsonb_build_object('count', count(*), 'total_jpy', coalesce(sum(o.total_jpy), 0), 'last_order_at', max(o.created_at))\n                 from orders o where o.shop_id = p_c.shop_id and o.customer_id = p_c.id and o.status in ('paid', 'shipped'))\n  );\n$$;\nrevoke execute on function api_customer_json(customers) from public, anon, authenticated;\n\n-- 一覧・検索（0047 を差し替え: marketing_consent で絞る。MA が同意した会員だけを引くため）\ndrop function if exists api_customers_list(text, text, text, integer, integer, text, text, timestamptz);\ncreate or replace function api_customers_list(p_token_hash text, p_query text default null, p_email text default null,\n                                              p_limit integer default 50, p_offset integer default 0,\n                                              p_external_provider text default null, p_external_id text default null,\n                                              p_updated_since timestamptz default null, p_marketing_consent boolean default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_limit integer; v_offset integer; v_total integer; v_items jsonb; v_q text; v_email text; v_prov text; v_ext text;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:read');\n  v_limit := greatest(1, least(coalesce(p_limit, 50), 100));\n  v_offset := greatest(0, coalesce(p_offset, 0));\n  v_q := case when nullif(btrim(p_query), '') is not null then '%' || banto_like_escape(btrim(p_query)) || '%' end;\n  v_email := nullif(lower(btrim(p_email)), '');\n  v_prov := nullif(btrim(p_external_provider), '');\n  v_ext := nullif(btrim(p_external_id), '');\n  if v_ext is not null and v_prov is null then raise exception 'invalid_external_ref'; end if;\n  select count(*) into v_total from customers c\n   where c.shop_id = v_tok.shop_id\n     and (v_email is null or lower(c.email) = v_email)\n     and (v_q is null or c.email ilike v_q or c.name ilike v_q)\n     and (v_prov is null or c.external_ref->>'provider' = v_prov)\n     and (v_ext is null or c.external_ref->>'id' = v_ext)\n     and (p_updated_since is null or c.updated_at >= p_updated_since)\n     and (p_marketing_consent is null or c.marketing_consent = p_marketing_consent);\n  select coalesce(jsonb_agg(api_customer_json(c)), '[]'::jsonb) into v_items\n    from (select * from customers c\n           where c.shop_id = v_tok.shop_id\n             and (v_email is null or lower(c.email) = v_email)\n             and (v_q is null or c.email ilike v_q or c.name ilike v_q)\n             and (v_prov is null or c.external_ref->>'provider' = v_prov)\n             and (v_ext is null or c.external_ref->>'id' = v_ext)\n             and (p_updated_since is null or c.updated_at >= p_updated_since)\n             and (p_marketing_consent is null or c.marketing_consent = p_marketing_consent)\n           order by case when p_updated_since is null then null else c.updated_at end asc,\n                    case when p_updated_since is null then c.created_at end desc, c.id\n           limit v_limit offset v_offset) c;\n  return jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', v_offset);\nend;\n$$;\n\n\n-- 作る（0047 を差し替え: marketing_consent は false だけ受ける。同意は本人の行為なので API では付けられない）\ncreate or replace function api_customer_create(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_email text; v_name text; v_c customers%rowtype; v_key text;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:write');\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key in select jsonb_object_keys(p_values) loop\n    if v_key not in ('email', 'name', 'default_address', 'attributes', 'external_ref', 'marketing_consent') then raise exception 'invalid_field_%', left(v_key, 40); end if;\n  end loop;\n  v_email := lower(btrim(coalesce(p_values->>'email', '')));\n  if jsonb_typeof(p_values->'email') <> 'string' or length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  if p_values ? 'name' and jsonb_typeof(p_values->'name') not in ('string', 'null') then raise exception 'invalid_name'; end if;\n  v_name := nullif(btrim(coalesce(p_values->>'name', '')), '');\n  if length(v_name) > 200 then raise exception 'invalid_name'; end if;\n  if exists (select 1 from customers where shop_id = v_tok.shop_id and lower(email) = v_email) then raise exception 'email_taken'; end if;\n  begin\n    insert into customers (shop_id, email, name, default_address, attributes, external_ref, marketing_consent, marketing_consent_at, marketing_consent_source)\n    values (v_tok.shop_id, v_email, v_name, banto_api_address(p_values->'default_address'),\n            banto_customer_attributes(v_tok.shop_id, p_values->'attributes'), banto_customer_external_ref(p_values->'external_ref'),\n            case when banto_api_consent_false(p_values) then false end, case when banto_api_consent_false(p_values) then now() end, case when banto_api_consent_false(p_values) then 'api' end)\n    returning * into v_c;\n  exception when unique_violation then\n    raise exception 'external_ref_taken';\n  end;\n  return api_customer_json(v_c);\nend;\n$$;\n\n\n-- 氏名・住所・属性・外部の ID・同意の取り下げ（0047 を差し替え）。メールアドレスは変えない（email_change_not_allowed）。attributes は渡した鍵だけ重ねる（null で消す）\ncreate or replace function api_customer_update(p_token_hash text, p_customer_id uuid, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_c customers%rowtype; v_key text; v_name text;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:write');\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key in select jsonb_object_keys(p_values) loop\n    if v_key = 'email' then raise exception 'email_change_not_allowed'; end if;\n    if v_key not in ('name', 'default_address', 'attributes', 'external_ref', 'marketing_consent') then raise exception 'invalid_field_%', left(v_key, 40); end if;\n  end loop;\n  select * into v_c from customers where shop_id = v_tok.shop_id and id = p_customer_id for update;\n  if not found then raise exception 'not_found'; end if;\n  if p_values ? 'name' then\n    if jsonb_typeof(p_values->'name') not in ('string', 'null') then raise exception 'invalid_name'; end if;\n    v_name := nullif(btrim(coalesce(p_values->>'name', '')), '');\n    if length(v_name) > 200 then raise exception 'invalid_name'; end if;\n    v_c.name := v_name;\n  end if;\n  if p_values ? 'default_address' then v_c.default_address := banto_api_address(p_values->'default_address'); end if;\n  if p_values ? 'attributes' then v_c.attributes := banto_customer_attributes_merge(v_tok.shop_id, v_c.attributes, p_values->'attributes'); end if;\n  if p_values ? 'external_ref' then v_c.external_ref := banto_customer_external_ref(p_values->'external_ref'); end if;\n  if banto_api_consent_false(p_values) and v_c.marketing_consent is distinct from false then\n    v_c.marketing_consent := false; v_c.marketing_consent_at := now(); v_c.marketing_consent_source := 'api';\n  end if;\n  begin\n    update customers set name = v_c.name, default_address = v_c.default_address, attributes = v_c.attributes, external_ref = v_c.external_ref,\n                         marketing_consent = v_c.marketing_consent, marketing_consent_at = v_c.marketing_consent_at, marketing_consent_source = v_c.marketing_consent_source\n     where shop_id = v_tok.shop_id and id = p_customer_id\n    returning * into v_c;\n  exception when unique_violation then\n    raise exception 'external_ref_taken';\n  end;\n  return api_customer_json(v_c);\nend;\n$$;\n\n\n-- メールアドレスで引いて、あれば渡した鍵だけ更新、無ければ作る（外部のマスタからの同期の窓口）。\n-- email は身元なので変えない: 外部で変わったアドレスで呼ぶと、別の会員として作られる。そのとき同じ external_ref が\n-- 既にあれば external_ref_taken で止まる（連携側が気づいて、運営者が管理画面で変える）。戻り値に created を付ける\ncreate or replace function api_customer_upsert(p_token_hash text, p_values jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_email text; v_c customers%rowtype; v_key text; v_out jsonb;\nbegin\n  v_tok := api_require(p_token_hash, 'customers:write');\n  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'invalid_body'; end if;\n  for v_key in select jsonb_object_keys(p_values) loop\n    if v_key not in ('email', 'name', 'default_address', 'attributes', 'external_ref', 'marketing_consent') then raise exception 'invalid_field_%', left(v_key, 40); end if;\n  end loop;\n  v_email := lower(btrim(coalesce(p_values->>'email', '')));\n  if jsonb_typeof(p_values->'email') <> 'string' or length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n  -- 同じアドレスの同時の呼び出しを直列にする（2 人作らない）\n  perform pg_advisory_xact_lock(hashtext('customer_upsert:' || v_tok.shop_id::text || ':' || v_email));\n  select * into v_c from customers where shop_id = v_tok.shop_id and lower(email) = v_email for update;\n  if found then\n    v_out := api_customer_update(p_token_hash, v_c.id, p_values - 'email');\n    return v_out || jsonb_build_object('created', false);\n  end if;\n  v_out := api_customer_create(p_token_hash, p_values);\n  return v_out || jsonb_build_object('created', true);\nend;\n$$;\n\nrevoke execute on function api_customers_list(text, text, text, integer, integer, text, text, timestamptz, boolean) from public, anon, authenticated;\nrevoke execute on function api_customer_create(text, jsonb) from public, anon, authenticated;\nrevoke execute on function api_customer_update(text, uuid, jsonb) from public, anon, authenticated;\nrevoke execute on function api_customer_upsert(text, jsonb) from public, anon, authenticated;\ngrant execute on function api_customers_list(text, text, text, integer, integer, text, text, timestamptz, boolean) to service_role;\ngrant execute on function api_customer_create(text, jsonb) to service_role;\ngrant execute on function api_customer_update(text, uuid, jsonb) to service_role;\ngrant execute on function api_customer_upsert(text, jsonb) to service_role;\n\n-- ---------- 復元（0047 を差し替え: 同意も戻す） ----------\ncreate or replace function restore_customer_master(p_shop_id uuid, p_data jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_row jsonb; v_n integer := 0; v_customers jsonb := coalesce(p_data->'customers', '[]'::jsonb); v_ref jsonb; v_attrs jsonb; v_consent boolean;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'restore_customer_master: service_role only' using errcode = '42501';\n  end if;\n  if jsonb_typeof(v_customers) <> 'array' then raise exception 'invalid_export'; end if;\n  for v_row in select * from jsonb_array_elements(v_customers) loop\n    if jsonb_typeof(v_row) <> 'object' or (v_row->>'id') is null then continue; end if;\n    v_ref := case when banto_external_ref_ok(v_row->'external_ref') then v_row->'external_ref' end;\n    v_attrs := case when jsonb_typeof(v_row->'attributes') = 'object' then v_row->'attributes' else '{}'::jsonb end;\n    v_consent := case when jsonb_typeof(v_row->'marketing_consent') = 'boolean' then (v_row->>'marketing_consent')::boolean end;\n    if v_ref is null and v_attrs = '{}'::jsonb and v_consent is null then continue; end if;\n    begin\n      update customers set external_ref = v_ref, attributes = v_attrs,\n                           marketing_consent = v_consent,\n                           marketing_consent_at = case when v_consent is null then null else coalesce((v_row->>'marketing_consent_at')::timestamptz, now()) end,\n                           marketing_consent_source = case when v_consent is null then null when (v_row->>'marketing_consent_source') in ('checkout', 'account', 'import', 'api', 'admin') then v_row->>'marketing_consent_source' else 'import' end\n       where shop_id = p_shop_id and id = (v_row->>'id')::uuid;\n      if found then v_n := v_n + 1; end if;\n    exception when unique_violation or invalid_text_representation then\n      null;\n    end;\n  end loop;\n  return jsonb_build_object('customer_master', v_n);\nend;\n$$;\nrevoke execute on function restore_customer_master(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function restore_customer_master(uuid, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0050_marketing_consent');\n" },
  { version: "0051_audit_log", sql: "-- Banto 0051_audit_log: 監査ログ（人間の決定 2026-10-23、docs/knowledge/02-decisions.md）。前方専用。\n--\n-- 「誰が・いつ・何を変えたか」を 1 つの表に残す。書くのはこのファイルのトリガーだけ（Worker からは insert しない）。\n-- 記録する出来事（最小）:\n--   customer.email_changed / customer.deleted           会員のメールアドレスの変更・会員の削除\n--   order.status_changed                                 注文の状態（paid → shipped / cancelled / refunded）\n--   org_member.added / role_changed / removed            組織のメンバー\n--   org_member.shop_perms / store_perms                  ショップ・実店舗ごとの項目\n--   api_token.issued / revoked                           AI 用トークン\n--   shop.domain_changed / stripe_account_changed / published_changed\n-- 誰が（actor_kind / actor_id）は banto_audit_actor() が決める（優先順）:\n--   1. banto.actor … api_require が同じトランザクションに置く（AI 用トークン）\n--   2. service_role のリクエストの X-Banto-Actor ヘッダ（PostgREST の request.headers。Worker の特権経路が名乗る。\n--      利用者の JWT では読まないので偽れない）。形は \"user:<uuid>\" / \"api_token:<uuid>\"\n--   3. auth.uid()（管理画面の JWT）\n--   4. system（Webhook・Cron）\n-- 個人情報は入れない: メールアドレスは小文字の SHA-256 の先頭 16 桁だけ。注文は番号、人とトークンは id。\n-- 読めるのは組織の owner / admin（RLS）。insert / update / delete のポリシーは無い。\n-- ショップを消しても行は残す（shop_id に外部キーを張らない）。組織を消せば一緒に消える。保持は prune_audit_log（Cron、既定 365 日）。\n\n-- ---------- 表 ----------\ncreate table audit_log (\n  id bigint generated always as identity primary key,\n  org_id uuid not null references organizations(id) on delete cascade,\n  shop_id uuid,\n  actor_kind text not null check (actor_kind in ('user', 'api_token', 'system')),\n  actor_id uuid,\n  action text not null check (length(action) between 1 and 60),\n  target_type text not null check (length(target_type) between 1 and 40),\n  target_id text check (length(target_id) <= 100),\n  detail jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now()\n);\ncreate index audit_log_org_idx on audit_log (org_id, id desc);\ncreate index audit_log_shop_idx on audit_log (shop_id, id desc) where shop_id is not null;\n\nalter table audit_log enable row level security;\ncreate policy audit_log_org_admin_select on audit_log for select using (banto_org_admin(org_id));\nrevoke all on audit_log from public, anon, authenticated;\ngrant select on audit_log to authenticated;\n\n-- ---------- 誰が ----------\ncreate or replace function banto_audit_actor()\nreturns table (kind text, id uuid)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_raw text; v_headers jsonb; v_kind text; v_id uuid;\nbegin\n  -- 1. 同じトランザクションの中で api_require が置いた AI 用トークン\n  v_raw := nullif(current_setting('banto.actor', true), '');\n  -- 2. service_role のリクエストだけ、Worker が名乗ったヘッダ\n  if v_raw is null and auth.role() = 'service_role' then\n    begin\n      v_headers := nullif(current_setting('request.headers', true), '')::jsonb;\n    exception when others then\n      v_headers := null;\n    end;\n    v_raw := v_headers->>'x-banto-actor';\n  end if;\n  if v_raw is not null and v_raw ~ '^(user|api_token):[0-9a-fA-F-]{36}$' then\n    v_kind := split_part(v_raw, ':', 1);\n    begin\n      v_id := split_part(v_raw, ':', 2)::uuid;\n    exception when others then\n      v_id := null;\n    end;\n    if v_id is not null then return query select v_kind, v_id; return; end if;\n  end if;\n  -- 3. 管理画面の JWT\n  if auth.uid() is not null then return query select 'user'::text, auth.uid(); return; end if;\n  -- 4. Webhook・Cron\n  return query select 'system'::text, null::uuid;\nend;\n$$;\nrevoke execute on function banto_audit_actor() from public, anon, authenticated;\n\n-- ---------- 書く ----------\n-- 組織が無い（消えた・まだ入っていない）ときは書かない（組織の削除の連鎖の途中で外部キーに当たらないため）\ncreate or replace function banto_audit(p_org_id uuid, p_shop_id uuid, p_action text, p_target_type text, p_target_id text, p_detail jsonb)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_actor record;\nbegin\n  if p_org_id is null or not exists (select 1 from organizations where id = p_org_id) then return; end if;\n  select * into v_actor from banto_audit_actor() limit 1;\n  insert into audit_log (org_id, shop_id, actor_kind, actor_id, action, target_type, target_id, detail)\n  values (p_org_id, p_shop_id, v_actor.kind, v_actor.id, p_action, p_target_type, left(p_target_id, 100), coalesce(p_detail, '{}'::jsonb));\nend;\n$$;\nrevoke execute on function banto_audit(uuid, uuid, text, text, text, jsonb) from public, anon, authenticated;\n\n-- メールアドレスの突き合わせ用の値（個人情報を残さない）\ncreate or replace function banto_audit_email_hash(p_email text)\nreturns text\nlanguage sql\nimmutable\nset search_path = public, extensions\nas $$\n  select case when p_email is null or btrim(p_email) = '' then null\n              else left(encode(digest(lower(btrim(p_email)), 'sha256'), 'hex'), 16) end;\n$$;\nrevoke execute on function banto_audit_email_hash(text) from public, anon, authenticated;\n\ncreate or replace function banto_shop_org(p_shop_id uuid)\nreturns uuid\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select org_id from shops where id = p_shop_id;\n$$;\nrevoke execute on function banto_shop_org(uuid) from public, anon, authenticated;\n\n-- ---------- 会員 ----------\ncreate or replace function banto_audit_customers()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if tg_op = 'UPDATE' then\n    perform banto_audit(banto_shop_org(new.shop_id), new.shop_id, 'customer.email_changed', 'customer', new.id::text,\n                        jsonb_build_object('old_email_hash', banto_audit_email_hash(old.email), 'new_email_hash', banto_audit_email_hash(new.email)));\n    return new;\n  end if;\n  perform banto_audit(banto_shop_org(old.shop_id), old.shop_id, 'customer.deleted', 'customer', old.id::text,\n                      jsonb_build_object('email_hash', banto_audit_email_hash(old.email)));\n  return old;\nend;\n$$;\nrevoke execute on function banto_audit_customers() from public, anon, authenticated;\ndrop trigger if exists customers_audit_email on customers;\ncreate trigger customers_audit_email after update of email on customers\n  for each row when (old.email is distinct from new.email) execute function banto_audit_customers();\ndrop trigger if exists customers_audit_delete on customers;\ncreate trigger customers_audit_delete after delete on customers for each row execute function banto_audit_customers();\n\n-- ---------- 注文の状態 ----------\ncreate or replace function banto_audit_orders()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform banto_audit(banto_shop_org(new.shop_id), new.shop_id, 'order.status_changed', 'order', new.id::text,\n                      jsonb_build_object('number', new.number, 'from', old.status::text, 'to', new.status::text));\n  return new;\nend;\n$$;\nrevoke execute on function banto_audit_orders() from public, anon, authenticated;\ndrop trigger if exists orders_audit_status on orders;\ncreate trigger orders_audit_status after update of status on orders\n  for each row when (old.status is distinct from new.status) execute function banto_audit_orders();\n\n-- ---------- 組織のメンバー ----------\ncreate or replace function banto_audit_org_members()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if tg_op = 'INSERT' then\n    perform banto_audit(new.org_id, null, 'org_member.added', 'user', new.user_id::text, jsonb_build_object('role', new.role));\n    return new;\n  elsif tg_op = 'UPDATE' then\n    perform banto_audit(new.org_id, null, 'org_member.role_changed', 'user', new.user_id::text, jsonb_build_object('from', old.role, 'to', new.role));\n    return new;\n  end if;\n  perform banto_audit(old.org_id, null, 'org_member.removed', 'user', old.user_id::text, jsonb_build_object('role', old.role));\n  return old;\nend;\n$$;\nrevoke execute on function banto_audit_org_members() from public, anon, authenticated;\ndrop trigger if exists org_members_audit_insert on org_members;\ncreate trigger org_members_audit_insert after insert on org_members for each row execute function banto_audit_org_members();\ndrop trigger if exists org_members_audit_role on org_members;\ncreate trigger org_members_audit_role after update of role on org_members\n  for each row when (old.role is distinct from new.role) execute function banto_audit_org_members();\ndrop trigger if exists org_members_audit_delete on org_members;\ncreate trigger org_members_audit_delete after delete on org_members for each row execute function banto_audit_org_members();\n\n-- ショップごと・実店舗ごとの項目（org_member_set は消して入れ直すので、消えた分と入った分がそれぞれ残る）\ncreate or replace function banto_audit_member_perms()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_org uuid; v_user uuid; v_shop uuid; v_store uuid; v_old jsonb; v_new jsonb;\nbegin\n  if tg_op = 'INSERT' then\n    v_org := new.org_id; v_user := new.user_id; v_old := null; v_new := to_jsonb(new.perms);\n  elsif tg_op = 'UPDATE' then\n    if old.perms = new.perms then return new; end if;\n    v_org := new.org_id; v_user := new.user_id; v_old := to_jsonb(old.perms); v_new := to_jsonb(new.perms);\n  else\n    v_org := old.org_id; v_user := old.user_id; v_old := to_jsonb(old.perms); v_new := null;\n  end if;\n  if tg_table_name = 'org_member_shops' then\n    v_shop := case when tg_op = 'DELETE' then old.shop_id else new.shop_id end;\n    perform banto_audit(v_org, v_shop, 'org_member.shop_perms', 'user', v_user::text, jsonb_build_object('from', v_old, 'to', v_new));\n  else\n    v_store := case when tg_op = 'DELETE' then old.store_id else new.store_id end;\n    perform banto_audit(v_org, null, 'org_member.store_perms', 'user', v_user::text, jsonb_build_object('store_id', v_store, 'from', v_old, 'to', v_new));\n  end if;\n  if tg_op = 'DELETE' then return old; end if;\n  return new;\nend;\n$$;\nrevoke execute on function banto_audit_member_perms() from public, anon, authenticated;\ndrop trigger if exists org_member_shops_audit on org_member_shops;\ncreate trigger org_member_shops_audit after insert or update or delete on org_member_shops for each row execute function banto_audit_member_perms();\ndrop trigger if exists org_member_stores_audit on org_member_stores;\ncreate trigger org_member_stores_audit after insert or update or delete on org_member_stores for each row execute function banto_audit_member_perms();\n\n-- ---------- AI 用トークン ----------\ncreate or replace function banto_audit_api_tokens()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if tg_op = 'INSERT' then\n    perform banto_audit(banto_shop_org(new.shop_id), new.shop_id, 'api_token.issued', 'api_token', new.id::text,\n                        jsonb_build_object('name', new.name, 'prefix', new.prefix, 'scopes', to_jsonb(new.scopes), 'expires_at', new.expires_at));\n    return new;\n  end if;\n  perform banto_audit(banto_shop_org(new.shop_id), new.shop_id, 'api_token.revoked', 'api_token', new.id::text,\n                      jsonb_build_object('name', new.name, 'prefix', new.prefix));\n  return new;\nend;\n$$;\nrevoke execute on function banto_audit_api_tokens() from public, anon, authenticated;\ndrop trigger if exists api_tokens_audit_insert on api_tokens;\ncreate trigger api_tokens_audit_insert after insert on api_tokens for each row execute function banto_audit_api_tokens();\ndrop trigger if exists api_tokens_audit_revoke on api_tokens;\ncreate trigger api_tokens_audit_revoke after update of revoked_at on api_tokens\n  for each row when (old.revoked_at is null and new.revoked_at is not null) execute function banto_audit_api_tokens();\n\n-- ---------- ショップ（独自ドメイン・Stripe の接続先・公開） ----------\ncreate or replace function banto_audit_shops()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if old.domain is distinct from new.domain then\n    perform banto_audit(new.org_id, new.id, 'shop.domain_changed', 'shop', new.id::text, jsonb_build_object('from', old.domain, 'to', new.domain));\n  end if;\n  if old.stripe_account_id is distinct from new.stripe_account_id then\n    perform banto_audit(new.org_id, new.id, 'shop.stripe_account_changed', 'shop', new.id::text, jsonb_build_object('from', old.stripe_account_id, 'to', new.stripe_account_id));\n  end if;\n  if old.published is distinct from new.published then\n    perform banto_audit(new.org_id, new.id, 'shop.published_changed', 'shop', new.id::text, jsonb_build_object('published', new.published));\n  end if;\n  return new;\nend;\n$$;\nrevoke execute on function banto_audit_shops() from public, anon, authenticated;\ndrop trigger if exists shops_audit on shops;\ncreate trigger shops_audit after update of domain, stripe_account_id, published on shops for each row execute function banto_audit_shops();\n\n-- ---------- AI 用トークンを actor として残す ----------\n-- 0028 の api_require に「同じトランザクションのあいだだけ banto.actor を置く」を足しただけ。判定は変えない\ncreate or replace function api_require(p_token_hash text, p_scope text)\nreturns api_tokens\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'api_require: service_role only' using errcode = '42501';\n  end if;\n  select * into v_tok from api_tokens\n   where token_hash = p_token_hash\n     and revoked_at is null\n     and (expires_at is null or expires_at > now());\n  if not found or not (p_scope = any(v_tok.scopes)) or not banto_token_scope_ok(v_tok.owner_id, v_tok.shop_id, p_scope) then\n    raise exception 'unauthorized' using errcode = '42501';\n  end if;\n  -- 最終利用は1分に1回だけ更新（書き込みを減らす）\n  if v_tok.last_used_at is null or v_tok.last_used_at < now() - interval '1 minute' then\n    update api_tokens set last_used_at = now() where id = v_tok.id;\n  end if;\n  perform set_config('banto.actor', 'api_token:' || v_tok.id::text, true);\n  return v_tok;\nend;\n$$;\n\n-- ---------- 保持 ----------\ncreate or replace function prune_audit_log(p_days integer default 365)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'prune_audit_log: service_role only' using errcode = '42501';\n  end if;\n  delete from audit_log where created_at < now() - make_interval(days => greatest(coalesce(p_days, 365), 30));\n  get diagnostics v_n = row_count;\n  return v_n;\nend;\n$$;\nrevoke execute on function prune_audit_log(integer) from public, anon, authenticated;\ngrant execute on function prune_audit_log(integer) to service_role;\n\ninsert into banto_migrations (version) values ('0051_audit_log');\n" },
  { version: "0052_plan_limits", sql: "-- Banto 0052_plan_limits: プランの上限（人間の決定 2026-10-23、docs/knowledge/02-decisions.md）。前方専用。\n--\n-- デプロイ全体の設定（0038 banto_site_settings）に鍵 plan_limits を足す:\n--   { \"shops\": 3, \"products\": 1000, \"customers\": 5000, \"members\": 5 }   … 鍵は任意、値は 1〜1,000,000 の整数。{} で上限なし\n-- 数えるのはデプロイ全体（1 デプロイ = 1 契約）。判定は文単位の AFTER INSERT トリガーで、その鍵に上限があるときだけ count(*) する。\n-- 超えていれば 'plan_limit_exceeded:<種類>:<上限>' を投げ、文ごと巻き戻る。\n-- 書けるのは service_role と、JWT の無い直接の SQL（Supabase の SQL エディタ・Management API）だけ。組織の owner / admin は forbidden\n-- （ホスティングで貸すとき、借り手が自分の上限を外せてはいけない）。使用量は banto_plan_usage()（組織の owner / admin）。\n\n-- ---------- 値の検査 ----------\ncreate or replace function banto_plan_limits_valid(p_value jsonb)\nreturns boolean\nlanguage plpgsql\nimmutable\nas $$\ndeclare v_key text; v_val jsonb;\nbegin\n  if p_value is null or jsonb_typeof(p_value) <> 'object' then return false; end if;\n  for v_key, v_val in select * from jsonb_each(p_value) loop\n    if v_key not in ('shops', 'products', 'customers', 'members') then return false; end if;\n    if jsonb_typeof(v_val) <> 'number' then return false; end if;\n    if (v_val #>> '{}') !~ '^[0-9]+$' then return false; end if;\n    if (v_val #>> '{}')::bigint < 1 or (v_val #>> '{}')::bigint > 1000000 then return false; end if;\n  end loop;\n  return true;\nend;\n$$;\nrevoke execute on function banto_plan_limits_valid(jsonb) from public, anon, authenticated;\n\n-- ---------- site_settings_set（0038 の差し替え: plan_limits を足す） ----------\ncreate or replace function site_settings_set(p_key text, p_value jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_out jsonb; v_role text := auth.role();\nbegin\n  if p_key = 'plan_limits' then\n    -- service_role（ホスティングの提供者・Worker の特権経路）か、JWT の無い直接の SQL（SQL エディタ・Management API）だけ\n    if v_role is not null and v_role <> 'service_role' then raise exception 'forbidden' using errcode = '42501'; end if;\n    if not banto_plan_limits_valid(p_value) then raise exception 'invalid_value'; end if;\n  else\n    if not exists (select 1 from org_members m where m.user_id = auth.uid() and m.role in ('owner', 'admin')) then\n      raise exception 'forbidden' using errcode = '42501';\n    end if;\n    case p_key\n      when 'workers_plan' then\n        if p_value is null or jsonb_typeof(p_value) <> 'string' or p_value #>> '{}' not in ('free', 'paid') then raise exception 'invalid_value'; end if;\n      else raise exception 'invalid_key';\n    end case;\n  end if;\n  update banto_site_settings set settings = settings || jsonb_build_object(p_key, p_value), updated_at = now() where id\n  returning settings into v_out;\n  return v_out;\nend;\n$$;\nrevoke execute on function site_settings_set(text, jsonb) from public, anon;\ngrant execute on function site_settings_set(text, jsonb) to authenticated, service_role;\n\n-- ---------- 上限と使用量 ----------\ncreate or replace function banto_plan_limits()\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce((select settings->'plan_limits' from banto_site_settings where id), '{}'::jsonb);\n$$;\nrevoke execute on function banto_plan_limits() from public, anon, authenticated;\n\ncreate or replace function banto_plan_count(p_kind text)\nreturns bigint\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v bigint;\nbegin\n  case p_kind\n    when 'shops' then select count(*) into v from shops;\n    when 'products' then select count(*) into v from products;\n    when 'customers' then select count(*) into v from customers;\n    when 'members' then select count(*) into v from org_members;\n    else v := 0;\n  end case;\n  return v;\nend;\n$$;\nrevoke execute on function banto_plan_count(text) from public, anon, authenticated;\n\n-- 管理画面（/admin/site）用。組織の owner / admin と service_role\ncreate or replace function banto_plan_usage()\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_limits jsonb := banto_plan_limits();\nbegin\n  if auth.role() is distinct from 'service_role'\n     and not exists (select 1 from org_members m where m.user_id = auth.uid() and m.role in ('owner', 'admin')) then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n  return jsonb_build_object(\n    'limits', v_limits,\n    'usage', jsonb_build_object(\n      'shops', banto_plan_count('shops'),\n      'products', banto_plan_count('products'),\n      'customers', banto_plan_count('customers'),\n      'members', banto_plan_count('members')));\nend;\n$$;\nrevoke execute on function banto_plan_usage() from public, anon;\ngrant execute on function banto_plan_usage() to authenticated, service_role;\n\n-- ---------- 判定（文単位の AFTER INSERT） ----------\ncreate or replace function banto_plan_limit_guard()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_kind text; v_limit bigint; v_count bigint;\nbegin\n  v_kind := case tg_table_name when 'org_members' then 'members' else tg_table_name end;\n  v_limit := nullif(banto_plan_limits()->>v_kind, '')::bigint;\n  if v_limit is null then return null; end if;\n  v_count := banto_plan_count(v_kind);\n  if v_count > v_limit then\n    raise exception 'plan_limit_exceeded:%:%', v_kind, v_limit using errcode = 'P0001';\n  end if;\n  return null;\nend;\n$$;\nrevoke execute on function banto_plan_limit_guard() from public, anon, authenticated;\n\ndrop trigger if exists shops_plan_limit on shops;\ncreate trigger shops_plan_limit after insert on shops for each statement execute function banto_plan_limit_guard();\ndrop trigger if exists products_plan_limit on products;\ncreate trigger products_plan_limit after insert on products for each statement execute function banto_plan_limit_guard();\ndrop trigger if exists customers_plan_limit on customers;\ncreate trigger customers_plan_limit after insert on customers for each statement execute function banto_plan_limit_guard();\ndrop trigger if exists org_members_plan_limit on org_members;\ncreate trigger org_members_plan_limit after insert on org_members for each statement execute function banto_plan_limit_guard();\n\ninsert into banto_migrations (version) values ('0052_plan_limits');\n" },
  { version: "0053_plan_mail_limit", sql: "-- Banto 0053_plan_mail_limit: プランの上限に「1 日のメール」を足す（人間の決定 2026-10-23、docs/knowledge/02-decisions.md）。前方専用。\n--\n-- ホスティングの提供者がメールの送り手（Resend 等）を共有させる構成で、送り手の評判を守るため、Banto がその場で送るメールのうち\n-- 外から増やせるもの（会員のログインのコード = member_login_challenges、組織への招待 = org_invitations）を\n-- デプロイ全体で 1 日（UTC）いくつまで、を plan_limits.mail_per_day に置く。0029 のショップごとの上限は借り手が自分で上げられるので、その上のふた。\n-- 注文メールは注文の数に比例するだけなので数えない。\n-- 判定は 0052 と同じ文単位の AFTER INSERT トリガー。超えれば 'plan_limit_exceeded:mail_per_day:<上限>'。\n-- 書けるのは 0052 と同じく service_role と JWT の無い直接の SQL だけ（site_settings_set は変えない。鍵の検査だけ広げる）。\n\n-- ---------- 値の検査（0052 の差し替え: mail_per_day を足す） ----------\ncreate or replace function banto_plan_limits_valid(p_value jsonb)\nreturns boolean\nlanguage plpgsql\nimmutable\nas $$\ndeclare v_key text; v_val jsonb;\nbegin\n  if p_value is null or jsonb_typeof(p_value) <> 'object' then return false; end if;\n  for v_key, v_val in select * from jsonb_each(p_value) loop\n    if v_key not in ('shops', 'products', 'customers', 'members', 'mail_per_day') then return false; end if;\n    if jsonb_typeof(v_val) <> 'number' then return false; end if;\n    if (v_val #>> '{}') !~ '^[0-9]+$' then return false; end if;\n    if (v_val #>> '{}')::bigint < 1 or (v_val #>> '{}')::bigint > 1000000 then return false; end if;\n  end loop;\n  return true;\nend;\n$$;\nrevoke execute on function banto_plan_limits_valid(jsonb) from public, anon, authenticated;\n\n-- ---------- 今日（UTC）のメールの数 ----------\ncreate or replace function banto_plan_mail_count()\nreturns bigint\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select (select count(*) from member_login_challenges where created_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc')\n       + (select count(*) from org_invitations where created_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc');\n$$;\nrevoke execute on function banto_plan_mail_count() from public, anon, authenticated;\n\n-- 0052 の banto_plan_count に mail_per_day を足す\ncreate or replace function banto_plan_count(p_kind text)\nreturns bigint\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v bigint;\nbegin\n  case p_kind\n    when 'shops' then select count(*) into v from shops;\n    when 'products' then select count(*) into v from products;\n    when 'customers' then select count(*) into v from customers;\n    when 'members' then select count(*) into v from org_members;\n    when 'mail_per_day' then v := banto_plan_mail_count();\n    else v := 0;\n  end case;\n  return v;\nend;\n$$;\nrevoke execute on function banto_plan_count(text) from public, anon, authenticated;\n\n-- ---------- 上限と使用量（0052 の差し替え: mail_per_day を足す） ----------\ncreate or replace function banto_plan_usage()\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_limits jsonb := banto_plan_limits();\nbegin\n  if auth.role() is distinct from 'service_role'\n     and not exists (select 1 from org_members m where m.user_id = auth.uid() and m.role in ('owner', 'admin')) then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n  return jsonb_build_object(\n    'limits', v_limits,\n    'usage', jsonb_build_object(\n      'shops', banto_plan_count('shops'),\n      'products', banto_plan_count('products'),\n      'customers', banto_plan_count('customers'),\n      'members', banto_plan_count('members'),\n      'mail_per_day', banto_plan_count('mail_per_day')));\nend;\n$$;\nrevoke execute on function banto_plan_usage() from public, anon;\ngrant execute on function banto_plan_usage() to authenticated, service_role;\n\n-- ---------- 判定（文単位の AFTER INSERT） ----------\ncreate or replace function banto_plan_mail_guard()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_limit bigint; v_count bigint;\nbegin\n  v_limit := nullif(banto_plan_limits()->>'mail_per_day', '')::bigint;\n  if v_limit is null then return null; end if;\n  v_count := banto_plan_mail_count();\n  if v_count > v_limit then\n    raise exception 'plan_limit_exceeded:mail_per_day:%', v_limit using errcode = 'P0001';\n  end if;\n  return null;\nend;\n$$;\nrevoke execute on function banto_plan_mail_guard() from public, anon, authenticated;\n\ndrop trigger if exists member_login_challenges_plan_mail on member_login_challenges;\ncreate trigger member_login_challenges_plan_mail after insert on member_login_challenges for each statement execute function banto_plan_mail_guard();\ndrop trigger if exists org_invitations_plan_mail on org_invitations;\ncreate trigger org_invitations_plan_mail after insert on org_invitations for each statement execute function banto_plan_mail_guard();\n\ninsert into banto_migrations (version) values ('0053_plan_mail_limit');\n" },
  { version: "0054_operator_mfa", sql: "-- Banto 0054_operator_mfa: 運営者（管理画面）の二段階認証（人間の決定 2026-10-24、docs/knowledge/02-decisions.md）\n--\n-- 方式: Supabase Auth（GoTrue）の二段階認証（TOTP。認証アプリの 6 桁）。二段階目を済ませた JWT は aal = 'aal2'。\n-- 強制は DB で行う: 画面で求めるだけでは、パスワードを知る人が GoTrue に直接ログインして aal1 の JWT で PostgREST を叩ける\n-- （SUPABASE_URL と anon キーは公開されている）。PostgREST がすべてのリクエストの前に呼ぶ関数（db_pre_request）で、\n--   - 二段階認証を登録している人の aal1 の JWT        → 'mfa_required:challenge' で止める\n--   - 「全員必須」の組織にいて、まだ登録していない人 → 'mfa_required:enroll' で止める（登録は GoTrue だけで済むので詰まない）\n-- テーブルも RPC もまとめて 1 か所で止まる。anon（お客様の画面）と service_role（Worker の特権経路・AI 用トークンの api_*）は対象外。\n-- 会員（customers）は Supabase Auth を使わないので関係ない。\n--\n-- 登録していない人は今までどおり使える（任意で始める。組織の owner が「全員必須」にできる）。\n-- 認証アプリをなくしたとき: 同じ組織の owner / admin が外せる（org_member_mfa_reset_authorize → Worker が GoTrue の Admin API で消す）。\n-- owner が 1 人だけのときは、docs/hardening.md の SQL で外す。\n\n-- ---------- 組織の設定: 全員必須 ----------\nalter table organizations add column if not exists require_mfa boolean not null default false;\n\n-- ---------- 今の JWT の状態 ----------\n-- ok / challenge（登録済みなのに aal1）/ enroll（組織が必須なのに未登録）\ncreate or replace function banto_mfa_state()\nreturns text\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case\n    when auth.uid() is null then 'ok'\n    when coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2' then 'ok'\n    when exists (select 1 from auth.mfa_factors f where f.user_id = auth.uid() and f.status::text = 'verified') then 'challenge'\n    when exists (select 1 from org_members m join organizations o on o.id = m.org_id where m.user_id = auth.uid() and o.require_mfa) then 'enroll'\n    else 'ok'\n  end;\n$$;\n\n-- PostgREST のリクエストの前に必ず通る（下で authenticator に設定する）\ncreate or replace function banto_pre_request()\nreturns void\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_state text;\nbegin\n  if auth.role() is distinct from 'authenticated' then return; end if;\n  v_state := banto_mfa_state();\n  if v_state <> 'ok' then\n    raise exception 'mfa_required:%', v_state using errcode = '42501';\n  end if;\nend;\n$$;\n\n-- ---------- 組織の owner: 全員必須にする / 外す ----------\n-- 必須にするのは、自分が二段階認証を済ませた（aal2 の）owner だけ（自分の登録の無いまま全員を締め出さないため）\ncreate or replace function org_set_require_mfa(p_org_id uuid, p_required boolean)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if not exists (select 1 from org_members where org_id = p_org_id and user_id = auth.uid() and role = 'owner') then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n  if p_required and coalesce(auth.jwt() ->> 'aal', 'aal1') <> 'aal2' then\n    raise exception 'mfa_self_first';\n  end if;\n  update organizations set require_mfa = p_required where id = p_org_id;\n  perform banto_audit(p_org_id, null, 'org.require_mfa', 'organization', p_org_id::text, jsonb_build_object('required', p_required));\nend;\n$$;\n\n-- ---------- メンバーの二段階認証の有無（組織の owner / admin が見る） ----------\ncreate or replace function org_members_mfa(p_org_id uuid)\nreturns table (user_id uuid, has_mfa boolean)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select m.user_id, exists (select 1 from auth.mfa_factors f where f.user_id = m.user_id and f.status::text = 'verified')\n    from org_members m\n   where m.org_id = p_org_id and banto_org_admin(p_org_id);\n$$;\n\n-- ---------- 認証アプリをなくした人の登録を外す（許可と記録。消すのは Worker が GoTrue の Admin API で） ----------\n-- 呼べるのは、相手と同じ組織の owner / admin。相手が owner なら owner だけ。自分自身は外せない（自分は管理画面から）。\n-- 許せば監査ログに書いて true（同じ組織が複数あれば、それぞれに書く）\ncreate or replace function org_member_mfa_reset_authorize(p_user_id uuid)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_org record; v_ok boolean := false;\nbegin\n  if auth.uid() is null or p_user_id is null or p_user_id = auth.uid() then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n  for v_org in\n    select me.org_id, me.role as my_role, them.role as their_role\n      from org_members me join org_members them on them.org_id = me.org_id\n     where me.user_id = auth.uid() and them.user_id = p_user_id and me.role in ('owner', 'admin')\n  loop\n    if v_org.their_role = 'owner' and v_org.my_role <> 'owner' then continue; end if;\n    perform banto_audit(v_org.org_id, null, 'org_member.mfa_reset', 'user', p_user_id::text, '{}'::jsonb);\n    v_ok := true;\n  end loop;\n  if not v_ok then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n  return true;\nend;\n$$;\n\n-- ---------- 権限 ----------\n-- banto_pre_request は PostgREST がリクエストの役割のまま呼ぶので、anon と authenticated にも EXECUTE が要る（中身は JWT を読むだけ）\nrevoke execute on function banto_mfa_state() from public;\nrevoke execute on function banto_pre_request() from public;\ngrant execute on function banto_mfa_state() to anon, authenticated, service_role;\ngrant execute on function banto_pre_request() to anon, authenticated, service_role;\nrevoke execute on function org_set_require_mfa(uuid, boolean) from public, anon;\nrevoke execute on function org_members_mfa(uuid) from public, anon;\nrevoke execute on function org_member_mfa_reset_authorize(uuid) from public, anon;\ngrant execute on function org_set_require_mfa(uuid, boolean) to authenticated, service_role;\ngrant execute on function org_members_mfa(uuid) to authenticated, service_role;\ngrant execute on function org_member_mfa_reset_authorize(uuid) to authenticated, service_role;\n\n-- ---------- PostgREST に「リクエストの前の関数」を設定する ----------\n-- Supabase・selfhost/ とも PostgREST は authenticator で接続し、DB の設定（pgrst.*）を読む。テスト用の素の PostgreSQL には authenticator が無い\ndo $$\nbegin\n  if exists (select 1 from pg_roles where rolname = 'authenticator') then\n    execute 'alter role authenticator set pgrst.db_pre_request = ''public.banto_pre_request''';\n  end if;\nend;\n$$;\nnotify pgrst, 'reload config';\n\ninsert into banto_migrations (version) values ('0054_operator_mfa');\n" },
  { version: "0055_security_hardening_2", sql: "-- Banto 0055_security_hardening_2: 2026-10-25 の監査で見つかった「権限の項目（0024）の追従漏れ」を SQL で閉じる。前方専用。\n--\n-- 直すもの（すべて「判定は SQL」の原則どおり、Worker の分岐に頼らない）:\n--   1. AI 用トークン: api_require が返すスコープを、発行者が今も持つ項目のものだけに絞る（orders:pii の分岐が\n--      scopes 配列だけを見ていたため、発行者から customers の項目を外した後も個人情報が返っていた）。\n--   2. AI 用トークンの失効・帰属: 組織の owner / admin が member の発行したトークンを失効できなかった（with check の\n--      owner_id = auth.uid() が UPDATE にも効いていた）。逆に integrations の member は他人の行を DELETE・帰属を付け替え・\n--      失効を取り消せた。INSERT と UPDATE のポリシーを分け、変えてよい列を revoked_at（null → 時刻）と name だけにする。DELETE は無し。\n--   3. organizations.require_mfa: admin が直接 UPDATE で切り替えられた（owner + aal2 + 監査の org_set_require_mfa の迂回）。列の権限で止める。\n--   4. products.attributes: 「非公開（public: false）」の独自項目の値が anon キーで直接読めた。anon には列を見せず、\n--      お店の画面と公開 API は product_public_get（公開の項目だけ）で読む。public の settings に出す product_fields も公開の項目だけ。\n--   5. import_member_passwords: 既にログインしたことのある会員（コードやリンクで入っている普通の会員）には書かない\n--      （WordPress からの取り込みはログイン前の会員だけが対象。入口の項目は Worker で owner / admin に上げた）。\n--   6. 降格された初代 owner が org_id の無いショップを作れた → 組織に属する人は org_id 必須。\n--   7. settings の項目だけの member が headless（戻り先・中継元の IP）と oauth を書けた → integrations が要る。\n--   8. member_passkeys_reset は owner / admin だけ（member_set_email と同じ線。乗っ取りの救済は両方を合わせて使う）。\n--   9. orders.shipped_at を過去に書いて 180 日マスクを前倒しできた → 今の時刻の近くだけ。\n--  10. プランの上限の判定を advisory lock で直列にする（並行の INSERT で上限を越えられた）。\n--  11. skus / product_images の product_id に (product_id, shop_id) の複合 FK（catalog の項目で他ショップの商品に行を差し込めた）。\n-- 検査は scripts/check-rls.mjs（列の権限・トリガーの存在）と test/db/hardening2.test.ts。\n\n-- ---------- 1. api_require: 発行者が今も持つ項目のスコープだけを返す ----------\n-- 0051 の api_require と同じ判定に「返す scopes の絞り込み」を足す。api_* の 'orders:pii' = any(v_tok.scopes) はそのままで\n-- 発行者の項目を再評価したことになる（語彙に無いスコープは絞らない）。\ncreate or replace function api_require(p_token_hash text, p_scope text)\nreturns api_tokens\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'api_require: service_role only' using errcode = '42501';\n  end if;\n  select * into v_tok from api_tokens\n   where token_hash = p_token_hash\n     and revoked_at is null\n     and (expires_at is null or expires_at > now());\n  if not found or not (p_scope = any(v_tok.scopes)) or not banto_token_scope_ok(v_tok.owner_id, v_tok.shop_id, p_scope) then\n    raise exception 'unauthorized' using errcode = '42501';\n  end if;\n  v_tok.scopes := coalesce(array(select s from unnest(v_tok.scopes) s\n                                  where banto_scope_perm(s) is null or banto_token_scope_ok(v_tok.owner_id, v_tok.shop_id, s)), '{}'::text[]);\n  -- 最終利用は1分に1回だけ更新（書き込みを減らす）\n  if v_tok.last_used_at is null or v_tok.last_used_at < now() - interval '1 minute' then\n    update api_tokens set last_used_at = now() where id = v_tok.id;\n  end if;\n  perform set_config('banto.actor', 'api_token:' || v_tok.id::text, true);\n  return v_tok;\nend;\n$$;\n\n-- ---------- 2. api_tokens: 発行は自分の名義だけ、失効は integrations を持つ人なら誰でも、削除と書き換えは無し ----------\ndrop policy if exists api_tokens_integrations on api_tokens;\ncreate policy api_tokens_select on api_tokens for select using (banto_shop_perm(shop_id, 'integrations'));\ncreate policy api_tokens_insert on api_tokens for insert with check (banto_shop_perm(shop_id, 'integrations') and owner_id = auth.uid());\ncreate policy api_tokens_update on api_tokens for update\n  using (banto_shop_perm(shop_id, 'integrations')) with check (banto_shop_perm(shop_id, 'integrations'));\nrevoke delete on api_tokens from authenticated;\n\n-- 発行時: 発行者が持たない項目のスコープは付けられない（0028）。更新時: 変えてよいのは name と revoked_at（null → 時刻）だけ。\ncreate or replace function banto_api_tokens_guard()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if tg_op = 'INSERT' then\n    if not banto_token_scopes_ok(new.owner_id, new.shop_id, new.scopes) then\n      raise exception 'scope_not_permitted' using errcode = '42501';\n    end if;\n    return new;\n  end if;\n  if auth.role() = 'authenticated' then\n    if new.owner_id is distinct from old.owner_id or new.shop_id is distinct from old.shop_id or new.token_hash is distinct from old.token_hash\n       or new.prefix is distinct from old.prefix or new.scopes is distinct from old.scopes or new.expires_at is distinct from old.expires_at\n       or new.created_at is distinct from old.created_at or new.last_used_at is distinct from old.last_used_at then\n      raise exception 'token_immutable' using errcode = '42501';\n    end if;\n    -- 失効は取り消せない（最初の失効の時刻を保つ。もう一度「失効」を押しても変わらない）\n    if old.revoked_at is not null then new.revoked_at := old.revoked_at; end if;\n  elsif new.scopes is distinct from old.scopes or new.owner_id is distinct from old.owner_id or new.shop_id is distinct from old.shop_id then\n    if not banto_token_scopes_ok(new.owner_id, new.shop_id, new.scopes) then\n      raise exception 'scope_not_permitted' using errcode = '42501';\n    end if;\n  end if;\n  return new;\nend;\n$$;\nrevoke execute on function banto_api_tokens_guard() from public, anon, authenticated;\ndrop trigger if exists api_tokens_guard on api_tokens;\ncreate trigger api_tokens_guard before insert or update on api_tokens for each row execute function banto_api_tokens_guard();\n\n-- ---------- 3. organizations: authenticated が直接変えてよい列は name だけ ----------\nrevoke update on organizations from authenticated;\ngrant update (name) on organizations to authenticated;\n\n-- ---------- 4. products.attributes は anon に見せない ----------\n-- 0028 の shops と同じ形: 表の権限を剥奪して、列を選んで付け直す。products に列を足すときはここにも足す（check-rls.mjs が attributes を検査する）。\nrevoke all on products from anon;\ngrant select (id, shop_id, slug, name, description, published, created_at, updated_at, tags, category_id, brand, tax_class, extra_category_ids) on products to anon;\n\n-- 公開の項目だけに絞った attributes（product_fields の public が false でない鍵）。定義の読み方は src/products/fields.ts と同じ\ncreate or replace function banto_public_product_attributes(p_settings jsonb, p_attributes jsonb)\nreturns jsonb language sql immutable as $$\n  select coalesce((\n    select jsonb_object_agg(a.k, a.v)\n      from jsonb_each(case when jsonb_typeof(p_attributes) = 'object' then p_attributes else '{}'::jsonb end) a(k, v)\n     where exists (select 1 from jsonb_array_elements(case when jsonb_typeof(p_settings->'product_fields') = 'array' then p_settings->'product_fields' else '[]'::jsonb end) f\n                    where jsonb_typeof(f) = 'object' and f->>'key' = a.k and f->'public' is distinct from 'false'::jsonb)\n  ), '{}'::jsonb);\n$$;\nrevoke execute on function banto_public_product_attributes(jsonb, jsonb) from public, anon, authenticated;\n\n-- お店の画面・公開 API の商品詳細（anon）。公開中のショップの公開中の商品だけ。attributes は公開の項目だけ\ncreate or replace function product_public_get(p_shop_id uuid, p_slug text)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select to_jsonb(p) - 'attributes' || jsonb_build_object('attributes', banto_public_product_attributes(s.settings, p.attributes))\n    from products p join shops s on s.id = p.shop_id\n   where p.shop_id = p_shop_id and p.slug = p_slug and p.published and s.published\n   limit 1;\n$$;\nrevoke execute on function product_public_get(uuid, text) from public;\ngrant execute on function product_public_get(uuid, text) to anon, authenticated, service_role;\n\n-- 公開の settings に出す product_fields は公開の項目だけ（非公開の項目は定義（表示名）も見せない。0050 を差し替え）\ncreate or replace function banto_shop_public_settings(p jsonb)\nreturns jsonb language sql immutable as $$\n  select coalesce((select jsonb_object_agg(k, v) from jsonb_each(case when jsonb_typeof(p) = 'object' then p else '{}'::jsonb end) e(k, v)\n                    where k in ('theme', 'theme_settings', 'notice', 'shipping', 'modules', 'members_enabled', 'members_password',\n                                'checkout_terms', 'delivery_time', 'store_tryon', 'receipt',\n                                'tax_rate', 'tax_rate_reduced', 'tax_rounding', 'storefront', 'analytics', 'marketing_consent')), '{}'::jsonb)\n      || case when jsonb_typeof(p->'product_fields') = 'array'\n              then jsonb_build_object('product_fields', coalesce((select jsonb_agg(f) from jsonb_array_elements(p->'product_fields') f\n                                                                    where jsonb_typeof(f) = 'object' and f->'public' is distinct from 'false'::jsonb), '[]'::jsonb))\n              else '{}'::jsonb end\n      || case when jsonb_typeof(p->'headless') = 'object'\n              then jsonb_build_object('headless', jsonb_build_object('return_origins', coalesce(p->'headless'->'return_origins', '[]'::jsonb)))\n              else '{}'::jsonb end\n      || case when jsonb_typeof(p->'oauth') = 'object'\n              then jsonb_build_object('oauth', coalesce((\n                     select jsonb_object_agg(k, coalesce((select jsonb_object_agg(k2, v2) from jsonb_each(v) f(k2, v2) where k2 in ('client_id', 'bot_prompt')), '{}'::jsonb))\n                       from jsonb_each(p->'oauth') e(k, v) where jsonb_typeof(v) = 'object'), '{}'::jsonb))\n              else '{}'::jsonb end;\n$$;\nrevoke execute on function banto_shop_public_settings(jsonb) from public, anon, authenticated;\n\n-- ---------- 5. import_member_passwords: ログインしたことのある会員には書かない（0013 を差し替え） ----------\ncreate or replace function import_member_passwords(p_shop_id uuid, p_rows jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row jsonb;\n  v_email text;\n  v_hash text;\n  v_id uuid;\n  v_has boolean;\n  v_active boolean;\n  v_imported integer := 0;\n  v_created integer := 0;\n  v_format integer := 0;\n  v_has_password integer := 0;\n  v_bad_email integer := 0;\n  v_skipped_active integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'import_member_passwords: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id) then raise exception 'shop_not_found'; end if;\n  if jsonb_array_length(coalesce(p_rows, '[]'::jsonb)) > 100 then raise exception 'too_many_rows'; end if;\n  for v_row in select e from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) e loop\n    v_email := lower(btrim(coalesce(v_row->>'email', '')));\n    v_hash := btrim(coalesce(v_row->>'hash', ''));\n    if length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then v_bad_email := v_bad_email + 1; continue; end if;\n    if v_hash !~ '^(\\$wp)?\\$2[aby]\\$[0-9]{2}\\$[./A-Za-z0-9]{53}$' then v_format := v_format + 1; continue; end if;\n    v_id := null;\n    select id, password_hash is not null, last_login_at is not null into v_id, v_has, v_active\n      from customers where shop_id = p_shop_id and lower(email) = v_email;\n    if v_id is null then\n      insert into customers (shop_id, email) values (p_shop_id, v_email) returning id into v_id;\n      v_created := v_created + 1;\n      v_has := false;\n      v_active := false;\n    end if;\n    if v_has then v_has_password := v_has_password + 1; continue; end if;\n    -- 既にログインしたことのある会員は Banto の会員として確立している。取り込みで入口を足さない（乗っ取りの経路になる）\n    if v_active then v_skipped_active := v_skipped_active + 1; continue; end if;\n    update customers set legacy_password_hash = v_hash, legacy_password_expires_at = now() + interval '180 days'\n     where shop_id = p_shop_id and id = v_id;\n    v_imported := v_imported + 1;\n  end loop;\n  return jsonb_build_object('imported', v_imported, 'created', v_created, 'skipped_format', v_format,\n                            'skipped_has_password', v_has_password, 'skipped_invalid_email', v_bad_email, 'skipped_active', v_skipped_active);\nend;\n$$;\n\n-- ---------- 6 / 7. shops: 組織に属する人は org_id 必須、headless / oauth は integrations（0031 を差し替え） ----------\ncreate or replace function banto_shops_guard()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if tg_op = 'INSERT' then\n    if new.org_id is null and auth.uid() is not null then\n      select m.org_id into new.org_id from org_members m join organizations o on o.id = m.org_id\n       where m.user_id = auth.uid() and m.role in ('owner', 'admin') order by o.created_at limit 1;\n      -- 0024 以降、運営者は必ず組織に属する。owner / admin の組織が無い人（降格された初代 owner）は組織の外にショップを作れない\n      if new.org_id is null and auth.role() = 'authenticated' then raise exception 'org_required' using errcode = '42501'; end if;\n    end if;\n    if new.owner_id is not null and not exists (select 1 from owners where id = new.owner_id) then new.owner_id := null; end if;\n    return new;\n  end if;\n  if auth.role() = 'authenticated' then\n    if new.org_id is distinct from old.org_id and old.org_id is not null then raise exception 'org_immutable' using errcode = '42501'; end if;\n    if new.owner_id is distinct from old.owner_id then raise exception 'owner_immutable' using errcode = '42501'; end if;\n    if new.stripe_account_id is distinct from old.stripe_account_id and not banto_shop_perm(old.id, 'integrations') then\n      raise exception 'integrations_required' using errcode = '42501';\n    end if;\n    -- 連携の設定（決済後の戻り先・中継元の IP・外部ログインの client_id）は integrations の項目（0055）\n    if (new.settings->'headless' is distinct from old.settings->'headless' or new.settings->'oauth' is distinct from old.settings->'oauth')\n       and not banto_shop_perm(old.id, 'integrations') then\n      raise exception 'integrations_required' using errcode = '42501';\n    end if;\n    -- スラッグ・独自ドメイン・注文番号と試着の連番は、settings の項目では変えられない（0031）\n    if (new.slug is distinct from old.slug or new.domain is distinct from old.domain\n        or new.order_seq is distinct from old.order_seq or new.tryon_seq is distinct from old.tryon_seq)\n       and not banto_owns_shop(old.id) then\n      raise exception 'admin_required' using errcode = '42501';\n    end if;\n  end if;\n  return new;\nend;\n$$;\n\n-- ---------- 8. member_passkeys_reset は owner / admin だけ（0046 を差し替え） ----------\ncreate or replace function member_passkeys_reset(p_shop_id uuid, p_customer_id uuid)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_n integer;\nbegin\n  if not banto_owns_shop(p_shop_id) then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n  delete from member_passkeys where shop_id = p_shop_id and customer_id = p_customer_id;\n  get diagnostics v_n = row_count;\n  return v_n;\nend;\n$$;\n\n-- ---------- 9. orders.shipped_at は「今」の近くだけ（0028 を差し替え） ----------\ncreate or replace function banto_orders_guard()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if auth.role() = 'authenticated' then\n    if new.status is distinct from old.status and not (old.status = 'paid' and new.status = 'shipped') then\n      raise exception 'use_cancel_order' using errcode = '42501';\n    end if;\n    -- 発送日時を過去に書くと mask_shipped_orders（180 日）が前倒しで個人情報を消す。運営者が書けるのは今の時刻の近くだけ\n    if new.shipped_at is distinct from old.shipped_at\n       and (new.shipped_at is null or new.shipped_at < now() - interval '1 day' or new.shipped_at > now() + interval '1 hour') then\n      raise exception 'shipped_at_now' using errcode = '42501';\n    end if;\n  end if;\n  return new;\nend;\n$$;\n\n-- ---------- 10. プランの上限: 数える前に advisory lock（0052 / 0053 を差し替え） ----------\ncreate or replace function banto_plan_limit_guard()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_kind text; v_limit bigint; v_count bigint;\nbegin\n  v_kind := case tg_table_name when 'org_members' then 'members' else tg_table_name end;\n  v_limit := nullif(banto_plan_limits()->>v_kind, '')::bigint;\n  if v_limit is null then return null; end if;\n  -- 並行する INSERT は互いの未コミットの行を数えないので、数える前に直列にする（待った後の count は相手のコミットを見る）\n  perform pg_advisory_xact_lock(hashtextextended('banto_plan_limit|' || v_kind, 0));\n  v_count := banto_plan_count(v_kind);\n  if v_count > v_limit then\n    raise exception 'plan_limit_exceeded:%:%', v_kind, v_limit using errcode = 'P0001';\n  end if;\n  return null;\nend;\n$$;\n\ncreate or replace function banto_plan_mail_guard()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_limit bigint; v_count bigint;\nbegin\n  v_limit := nullif(banto_plan_limits()->>'mail_per_day', '')::bigint;\n  if v_limit is null then return null; end if;\n  perform pg_advisory_xact_lock(hashtextextended('banto_plan_limit|mail_per_day', 0));\n  v_count := banto_plan_mail_count();\n  if v_count > v_limit then\n    raise exception 'plan_limit_exceeded:mail_per_day:%', v_limit using errcode = 'P0001';\n  end if;\n  return null;\nend;\n$$;\n\n-- ---------- 11. skus / product_images は同じショップの商品にだけ付く ----------\n-- 既存の FK（on delete cascade）は残し、(product_id, shop_id) の複合 FK を足す。既存の行は shop_id が一致しているはずだが、\n-- 万一ずれていても適用は止めない（not valid のまま新しい行だけ検査し、validate は通れば通す）\nalter table products drop constraint if exists products_id_shop_id_key;\nalter table products add constraint products_id_shop_id_key unique (id, shop_id);\nalter table skus drop constraint if exists skus_product_shop_fkey;\nalter table skus add constraint skus_product_shop_fkey foreign key (product_id, shop_id) references products (id, shop_id) on delete cascade not valid;\nalter table product_images drop constraint if exists product_images_product_shop_fkey;\nalter table product_images add constraint product_images_product_shop_fkey foreign key (product_id, shop_id) references products (id, shop_id) on delete cascade not valid;\ndo $$\nbegin\n  alter table skus validate constraint skus_product_shop_fkey;\n  alter table product_images validate constraint product_images_product_shop_fkey;\nexception when foreign_key_violation then\n  raise notice 'banto 0055: skus / product_images に shop_id の合わない行があります。select * from skus k join products p on p.id = k.product_id where k.shop_id <> p.shop_id で確かめてください';\nend;\n$$;\n\ninsert into banto_migrations (version) values ('0055_security_hardening_2');\n" },
  { version: "0056_rate_limits_2", sql: "-- Banto 0056_rate_limits_2: 2026-10-25 の監査で見つかった「回数・資源の上限の穴」を SQL で閉じる。前方専用。\n--\n--   1. 0 円の注文（payment_provider = 'free'）は決済ページを作らずにその場で確定するので、「未確定（pending）の予約の数」の上限に\n--      一度も数えられなかった。同じ人・同じ IP の直近 1 時間の 0 円注文も数える（0029 の reserve_stock を差し替え）。\n--   2. 会員ログインの照合: 「アドレスごと 1 日の失敗 50 回」が、誰が出したチャレンジかを問わず合計されていたため、\n--      第三者が 10 枚のチャレンジを出して 5 回ずつ外すと本人のコードも expired になった。失敗は出した IP ごとに数え、\n--      アドレス全体の上限は別に大きく取る（0029 の member_login_verify を差し替え）。\n--   3. 運営者のログインと会員のパスワードのログインのロックが (アドレス) 単位で IP を見ないため、第三者が 5 回外すだけで\n--      本人を 15 分締め出せた。「同じ IP から同じアドレスへ」を先に数え、アドレス単体の上限は大きく取る（0030 / 0016 を差し替え）。\n--   4. hooks の配信が Workers のプラン（0038）を見ずに 1 回 50 件を並列に送るので、無料プランでは 1 回の実行の通信の上限に当たり、\n--      同じ回の後続（個人情報のマスキング・heartbeat）が止まった。取り出す数を SQL でプランに合わせる（0002 を差し替え）。\n\n-- ---------- 1. reserve_stock: 直近 1 時間の 0 円注文も数える ----------\ncreate or replace function reserve_stock(p_shop_id uuid, p_items jsonb, p_ttl_seconds integer default 900,\n                                         p_quote_id text default null, p_subject_hash text default null, p_ip_hash text default null)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_item jsonb;\n  v_sku_id uuid;\n  v_qty integer;\n  v_price integer;\n  v_updated integer;\n  v_items jsonb := '[]'::jsonb;\n  v_reservation_id uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'reserve_stock: service_role only' using errcode = '42501';\n  end if;\n  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then\n    raise exception 'empty_items';\n  end if;\n  if p_ttl_seconds is null or p_ttl_seconds <= 0 then\n    raise exception 'invalid_ttl';\n  end if;\n\n  -- 同じ quote で生きた予約があれば拒む（決済ページを開かずに在庫だけ押さえ続けるのを止める）\n  if p_quote_id is not null and exists (select 1 from reservations where shop_id = p_shop_id and quote_id = p_quote_id and status in ('pending', 'confirmed')) then\n    raise exception 'quote_already_used';\n  end if;\n  -- 同じ人・同じ IP の未確定の予約の数（数えてから入れるまでを直列にする）。\n  -- 0 円の注文はその場で confirmed になり pending が残らないので、直近 1 時間の 0 円注文（orders.payment_provider = 'free'）も数える（0056）\n  if p_subject_hash is not null then\n    perform pg_advisory_xact_lock(hashtextextended('reservation|' || p_shop_id::text || '|' || p_subject_hash, 0));\n    if (select count(*) from reservations r\n         where r.shop_id = p_shop_id and r.subject_hash = p_subject_hash\n           and (r.status = 'pending'\n                or (r.status = 'confirmed' and r.created_at > now() - interval '1 hour'\n                    and exists (select 1 from orders o where o.reservation_id = r.id and o.payment_provider = 'free'))))\n       >= banto_shop_limit(p_shop_id, 'checkout', 'max_pending_per_customer', 3) then\n      raise exception 'too_many_reservations' using detail = 'customer';\n    end if;\n  end if;\n  if p_ip_hash is not null then\n    perform pg_advisory_xact_lock(hashtextextended('reservation-ip|' || p_shop_id::text || '|' || p_ip_hash, 0));\n    if (select count(*) from reservations r\n         where r.shop_id = p_shop_id and r.ip_hash = p_ip_hash\n           and (r.status = 'pending'\n                or (r.status = 'confirmed' and r.created_at > now() - interval '1 hour'\n                    and exists (select 1 from orders o where o.reservation_id = r.id and o.payment_provider = 'free'))))\n       >= banto_shop_limit(p_shop_id, 'checkout', 'max_pending_per_ip', 20) then\n      raise exception 'too_many_reservations' using detail = 'ip';\n    end if;\n  end if;\n\n  -- sku_id 順に処理し、複数予約が同じ SKU 群を逆順でロックしてデッドロックするのを防ぐ\n  for v_item in select e from jsonb_array_elements(p_items) e order by e->>'sku_id' loop\n    v_sku_id := (v_item->>'sku_id')::uuid;\n    v_qty := (v_item->>'qty')::integer;\n    if v_sku_id is null or v_qty is null or v_qty <= 0 then\n      raise exception 'invalid_item' using detail = coalesce(v_item::text, 'null');\n    end if;\n\n    select k.price_jpy into v_price\n      from skus k\n      join products p on p.id = k.product_id\n      join shops s on s.id = k.shop_id\n     where k.id = v_sku_id and k.shop_id = p_shop_id and p.published and s.published;\n    if not found then\n      raise exception 'sku_not_available' using detail = v_sku_id::text;\n    end if;\n\n    update inventory\n       set available = available - v_qty, updated_at = now()\n     where sku_id = v_sku_id and shop_id = p_shop_id and available >= v_qty;\n    get diagnostics v_updated = row_count;\n    if v_updated = 0 then\n      raise exception 'insufficient_stock' using detail = v_sku_id::text;\n    end if;\n\n    v_items := v_items || jsonb_build_object('sku_id', v_sku_id, 'qty', v_qty, 'unit_price_jpy', v_price);\n  end loop;\n\n  insert into reservations (shop_id, items, expires_at, quote_id, subject_hash, ip_hash)\n  values (p_shop_id, v_items, now() + make_interval(secs => p_ttl_seconds), p_quote_id, p_subject_hash, p_ip_hash)\n  returning id into v_reservation_id;\n\n  return v_reservation_id;\nend;\n$$;\ncreate index if not exists reservations_recent_confirmed_idx on reservations (shop_id, created_at) where status = 'confirmed';\n\n-- ---------- 2. member_login_verify: 失敗はチャレンジを出した IP ごとに数える ----------\ncreate or replace function member_login_verify(p_shop_id uuid, p_challenge_id uuid, p_code_hash text, p_link_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_ch member_login_challenges%rowtype;\n  v_customer customers%rowtype;\n  v_created boolean := false;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_login_verify: service_role only' using errcode = '42501';\n  end if;\n  select * into v_ch from member_login_challenges where id = p_challenge_id and shop_id = p_shop_id for update;\n  if not found then return jsonb_build_object('ok', false, 'reason', 'invalid'); end if;\n  if v_ch.consumed_at is not null or v_ch.expires_at < now() or v_ch.attempts >= 5 then\n    return jsonb_build_object('ok', false, 'reason', 'expired');\n  end if;\n  -- 同じ IP が出したチャレンジの失敗は 1 日 50 回まで（第三者の失敗が本人のチャレンジを止めない）。アドレス全体は 1 日 300 回まで\n  if (select coalesce(sum(attempts), 0) from member_login_challenges\n       where shop_id = p_shop_id and email = v_ch.email and ip_hash is not distinct from v_ch.ip_hash and created_at > now() - interval '1 day') >= 50\n     or (select coalesce(sum(attempts), 0) from member_login_challenges\n          where shop_id = p_shop_id and email = v_ch.email and created_at > now() - interval '1 day') >= 300 then\n    return jsonb_build_object('ok', false, 'reason', 'expired');\n  end if;\n  if not ((p_code_hash is not null and v_ch.code_hash = p_code_hash) or (p_link_hash is not null and v_ch.link_hash = p_link_hash)) then\n    update member_login_challenges\n       set attempts = attempts + 1,\n           consumed_at = case when attempts + 1 >= 5 then now() else consumed_at end\n     where id = v_ch.id;\n    return jsonb_build_object('ok', false, 'reason', case when v_ch.attempts + 1 >= 5 then 'expired' else 'invalid' end);\n  end if;\n  update member_login_challenges set consumed_at = now() where id = v_ch.id;\n  if not exists (select 1 from shops where id = p_shop_id and coalesce(settings->>'members_enabled', 'false') = 'true') then\n    return jsonb_build_object('ok', false, 'reason', 'expired');\n  end if;\n\n  select * into v_customer from customers where shop_id = p_shop_id and lower(email) = v_ch.email;\n  if not found then\n    insert into customers (shop_id, email) values (p_shop_id, v_ch.email)\n    on conflict (shop_id, lower(email)) where email is not null do nothing\n    returning * into v_customer;\n    if v_customer.id is null then\n      select * into v_customer from customers where shop_id = p_shop_id and lower(email) = v_ch.email;\n    else\n      v_created := true;\n    end if;\n  end if;\n  update customers set last_login_at = now() where shop_id = p_shop_id and id = v_customer.id;\n  return jsonb_build_object('ok', true, 'customer_id', v_customer.id, 'session_epoch', v_customer.session_epoch,\n                            'email', v_customer.email, 'created', v_created, 'return_to', v_ch.return_to);\nend;\n$$;\n\n-- ---------- 3. ロックは「同じ IP から同じアドレスへ」を先に ----------\n-- 運営者: 同じ IP から同じアドレスへ 15 分 5 回、同じアドレス全体で 15 分 20 回、同じ IP 全体で 15 分 20 回（0030 を差し替え）\ncreate or replace function admin_login_check(p_email_hash text, p_ip_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_pair integer := 0; v_email integer; v_ip integer := 0;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'admin_login_check: service_role only' using errcode = '42501';\n  end if;\n  select count(*) into v_email from admin_login_attempts where email_hash = p_email_hash and not success and created_at > now() - interval '15 minutes';\n  if p_ip_hash is not null then\n    select count(*) into v_pair from admin_login_attempts where email_hash = p_email_hash and ip_hash = p_ip_hash and not success and created_at > now() - interval '15 minutes';\n    select count(*) into v_ip from admin_login_attempts where ip_hash = p_ip_hash and not success and created_at > now() - interval '15 minutes';\n  else\n    v_pair := v_email;\n  end if;\n  return jsonb_build_object('allowed', v_pair < 5 and v_email < 20 and v_ip < 20, 'retry_after_seconds', 900);\nend;\n$$;\n\n-- 会員のパスワード: 同じ IP から同じアドレスへ 15 分 5 回、同じアドレス全体で 15 分 20 回、同じ IP 全体で 1 時間 30 回（0016 を差し替え）\ncreate or replace function member_password_login(p_shop_id uuid, p_email text, p_password text, p_ip_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  v_email text := lower(btrim(coalesce(p_email, '')));\n  v_c customers%rowtype;\n  v_ok boolean := false;\n  v_found boolean;\n  v_from text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_password_login: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id\n                  and coalesce(settings->>'members_enabled', 'false') = 'true'\n                  and coalesce(settings->>'members_password', 'false') = 'true') then\n    return jsonb_build_object('ok', false, 'reason', 'disabled');\n  end if;\n  if p_password is null or length(p_password) = 0 or length(p_password) > 200 or length(v_email) > 254 then\n    return jsonb_build_object('ok', false, 'reason', 'invalid');\n  end if;\n  perform pg_advisory_xact_lock(hashtextextended('member_password|' || p_shop_id::text || '|' || v_email, 0));\n  if (select count(*) from member_login_failures where shop_id = p_shop_id and email = v_email and ip_hash is not distinct from p_ip_hash and created_at > now() - interval '15 minutes') >= 5\n     or (select count(*) from member_login_failures where shop_id = p_shop_id and email = v_email and created_at > now() - interval '15 minutes') >= 20\n     or (p_ip_hash is not null and (select count(*) from member_login_failures where shop_id = p_shop_id and ip_hash = p_ip_hash and created_at > now() - interval '1 hour') >= 30) then\n    return jsonb_build_object('ok', false, 'reason', 'locked');\n  end if;\n\n  select * into v_c from customers where shop_id = p_shop_id and lower(email) = v_email for update;\n  v_found := found;\n  if v_found and v_c.password_hash is not null then\n    v_ok := crypt(p_password, v_c.password_hash) = v_c.password_hash;\n  elsif v_found and v_c.legacy_password_hash is not null and (v_c.legacy_password_expires_at is null or v_c.legacy_password_expires_at > now()) then\n    -- WordPress は保存するときに前後の空白を落としている\n    v_ok := banto_wp_password_matches(p_password, v_c.legacy_password_hash)\n            or (btrim(p_password) <> p_password and banto_wp_password_matches(btrim(p_password), v_c.legacy_password_hash));\n    if v_ok then\n      update customers set password_hash = crypt(p_password, gen_salt('bf', 10)), password_updated_at = now(),\n                           legacy_password_hash = null, legacy_password_expires_at = null\n       where shop_id = p_shop_id and id = v_c.id;\n    end if;\n  else\n    -- 会員がいない・パスワードが無いときも同じくらいの時間をかける（応答の時間で登録の有無が分からないように）\n    perform crypt(p_password, '$2a$10$' || repeat('a', 53));\n  end if;\n  if not v_ok then\n    insert into member_login_failures (shop_id, email, ip_hash) values (p_shop_id, v_email, p_ip_hash);\n    return jsonb_build_object('ok', false, 'reason', 'invalid');\n  end if;\n  update customers set last_login_at = now() where shop_id = p_shop_id and id = v_c.id;\n  -- 知らせのメールの送信元（メール通知プラグインの設定。無ければ null = 送らない）\n  select nullif(btrim(e.settings->>'from'), '') into v_from\n    from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and e.url = 'https://banto.invalid/plugins/email_resend'\n   limit 1;\n  return jsonb_build_object('ok', true, 'customer_id', v_c.id, 'session_epoch', v_c.session_epoch, 'email', v_c.email, 'mail_from', v_from);\nend;\n$$;\n\n-- ---------- 4. hooks の配信はプランに合わせた数だけ取り出す（0002 を差し替え） ----------\n-- 無料プランの Worker は 1 回の実行で送れる通信の数が少ない（1 件 = fetch 1 + finish 1）。free は 12 件、paid は呼び手の上限（既定 50）まで\ncreate or replace function claim_hook_deliveries(p_limit integer default 50)\nreturns table (\n  id uuid, shop_id uuid, endpoint_id uuid, event text, payload jsonb, attempts integer,\n  url text, settings jsonb, created_at timestamptz\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_limit integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'claim_hook_deliveries: service_role only' using errcode = '42501';\n  end if;\n  v_limit := greatest(1, least(p_limit, case when banto_workers_plan() = 'paid' then 500 else 12 end));\n  return query\n  with picked as (\n    select d.id from hook_deliveries d\n      join hook_endpoints e on e.id = d.endpoint_id\n     where d.status = 'pending' and d.next_attempt_at <= now() and e.enabled\n     order by d.next_attempt_at\n     limit v_limit\n     for update of d skip locked\n  ),\n  leased as (\n    update hook_deliveries d\n       set attempts = d.attempts + 1, next_attempt_at = now() + interval '10 minutes'\n      from picked\n     where d.id = picked.id\n    returning d.id, d.shop_id, d.endpoint_id, d.event, d.payload, d.attempts, d.created_at\n  )\n  select l.id, l.shop_id, l.endpoint_id, l.event, l.payload, l.attempts, e.url, e.settings, l.created_at\n    from leased l join hook_endpoints e on e.id = l.endpoint_id;\nend;\n$$;\n\ninsert into banto_migrations (version) values ('0056_rate_limits_2');\n" },
  { version: "0057_member_reauth", sql: "-- Banto 0057_member_reauth: 盗まれた会員のセッションから「永続的なログイン手段」を足せないようにする。前方専用。\n--\n-- 2026-10-25 の監査: 0046（パスキーの追加はログインしてから 15 分以内のセッションだけ）と同じ守りが、パスワードの設定と\n-- LINE / Google の連携に無かった。Cookie か 15 分の access を手にした者が自分のパスワードや外部アカウントを足すと、本人が\n-- 全端末からログアウトしても入り続けられる。さらにパスワードを変えると Worker が新しいセッションの行を作っていたため、\n-- その行で 0046 の「15 分以内」も通ってしまった。\n--   - member_set_password / member_oauth_login（link）は、ログインしてから 15 分以内のセッション（p_session_id）だけ。\n--     過ぎていれば reauth（確かめのコードで入り直す）。\n--   - パスワードを変えたとき、今のセッションの行を新しい世代に付け替える（新しい行を作らない。created_at = ログインの時刻が残る）。\n--     ほかの端末は世代が変わって止まる。\n--   - どちらも本人に知らせるメールの送信元（mail_from）を返す（送るのは Worker）。\n--   - 運営者の二段階認証の登録・解除を監査ログに残す（org_member_mfa_self。GoTrue の表にはトリガーを張れないので Worker が呼ぶ）。\n\n-- ログインしてから p_minutes 以内の、生きたセッションか\ncreate or replace function banto_member_recent_auth(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_session_id uuid, p_minutes integer)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select p_session_id is not null\n     and banto_member_session_live(p_shop_id, p_customer_id, p_epoch, p_session_id)\n     and exists (select 1 from member_sessions where id = p_session_id and created_at > now() - make_interval(mins => p_minutes));\n$$;\nrevoke execute on function banto_member_recent_auth(uuid, uuid, integer, uuid, integer) from public, anon, authenticated;\n\n-- メール通知プラグインの送信元（無ければ null = 送らない）\ncreate or replace function banto_member_mail_from(p_shop_id uuid)\nreturns text\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select nullif(btrim(e.settings->>'from'), '') from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and e.url = 'https://banto.invalid/plugins/email_resend'\n   limit 1;\n$$;\nrevoke execute on function banto_member_mail_from(uuid) from public, anon, authenticated;\n\n-- ---------- パスワードの設定（0013 を差し替え: セッションの確かめと知らせ） ----------\n-- 戻り値: { ok: true, epoch, email, mail_from } / { ok: false, reason: 'session' | 'reauth' }\ndrop function if exists member_set_password(uuid, uuid, integer, text);\ncreate or replace function member_set_password(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_password text, p_session_id uuid default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare v_epoch integer; v_email text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_set_password: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from shops where id = p_shop_id and coalesce(settings->>'members_password', 'false') = 'true') then\n    raise exception 'password_disabled';\n  end if;\n  if p_password is null or length(p_password) < 8 or length(p_password) > 200 then raise exception 'weak_password'; end if;\n  if p_session_id is null or not banto_member_session_live(p_shop_id, p_customer_id, p_epoch, p_session_id) then\n    return jsonb_build_object('ok', false, 'reason', 'session');\n  end if;\n  if not banto_member_recent_auth(p_shop_id, p_customer_id, p_epoch, p_session_id, 15) then\n    return jsonb_build_object('ok', false, 'reason', 'reauth');\n  end if;\n  update customers\n     set password_hash = crypt(p_password, gen_salt('bf', 10)), password_updated_at = now(),\n         legacy_password_hash = null, legacy_password_expires_at = null,\n         session_epoch = session_epoch + 1\n   where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch\n  returning session_epoch, email into v_epoch, v_email;\n  if v_epoch is null then return jsonb_build_object('ok', false, 'reason', 'session'); end if;\n  -- この端末のセッションだけ新しい世代へ（ほかの端末は世代が合わなくなって止まる）\n  update member_sessions set session_epoch = v_epoch where id = p_session_id;\n  return jsonb_build_object('ok', true, 'epoch', v_epoch, 'email', v_email, 'mail_from', banto_member_mail_from(p_shop_id));\nend;\n$$;\nrevoke execute on function member_set_password(uuid, uuid, integer, text, uuid) from public, anon, authenticated;\ngrant execute on function member_set_password(uuid, uuid, integer, text, uuid) to service_role;\n\n-- ---------- LINE / Google の連携（0014 を差し替え: 連携はログインしてから 15 分以内のセッションだけ） ----------\ndrop function if exists member_oauth_login(uuid, text, text, text, boolean, uuid, integer);\ncreate or replace function member_oauth_login(p_shop_id uuid, p_provider text, p_subject text, p_email text, p_email_verified boolean,\n                                              p_link_customer_id uuid, p_link_epoch integer, p_link_session_id uuid default null)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_email text := nullif(lower(btrim(coalesce(p_email, ''))), '');\n  v_customer_id uuid;\n  v_c customers%rowtype;\n  v_created boolean := false;\n  v_linked boolean := false;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_oauth_login: service_role only' using errcode = '42501';\n  end if;\n  if p_provider not in ('line', 'google') or p_subject is null or length(p_subject) not between 1 and 200 then raise exception 'invalid_identity'; end if;\n  if not exists (select 1 from shops where id = p_shop_id\n                  and coalesce(settings->>'members_enabled', 'false') = 'true'\n                  and coalesce(settings->'modules'->>(p_provider || '_login'), 'false') = 'true') then\n    return jsonb_build_object('ok', false, 'reason', 'disabled');\n  end if;\n  if v_email is not null and (length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$') then v_email := null; end if;\n  perform pg_advisory_xact_lock(hashtextextended('member_oauth|' || p_shop_id::text || '|' || p_provider || '|' || p_subject, 0));\n\n  select customer_id into v_customer_id from member_identities where shop_id = p_shop_id and provider = p_provider and subject = p_subject;\n\n  if p_link_customer_id is not null then\n    -- ログイン中の会員が自分で連携する（ログインしてから 15 分以内のセッションだけ。0057）\n    if not exists (select 1 from customers where shop_id = p_shop_id and id = p_link_customer_id and session_epoch = coalesce(p_link_epoch, -1))\n       or p_link_session_id is null or not banto_member_session_live(p_shop_id, p_link_customer_id, p_link_epoch, p_link_session_id) then\n      return jsonb_build_object('ok', false, 'reason', 'session');\n    end if;\n    if not banto_member_recent_auth(p_shop_id, p_link_customer_id, p_link_epoch, p_link_session_id, 15) then\n      return jsonb_build_object('ok', false, 'reason', 'reauth');\n    end if;\n    if v_customer_id is not null and v_customer_id <> p_link_customer_id then return jsonb_build_object('ok', false, 'reason', 'already_linked'); end if;\n    if v_customer_id is null then\n      if exists (select 1 from member_identities where shop_id = p_shop_id and customer_id = p_link_customer_id and provider = p_provider) then\n        return jsonb_build_object('ok', false, 'reason', 'other_linked');\n      end if;\n      insert into member_identities (shop_id, provider, subject, customer_id) values (p_shop_id, p_provider, p_subject, p_link_customer_id);\n      v_linked := true;\n    end if;\n    v_customer_id := p_link_customer_id;\n  elsif v_customer_id is null then\n    -- 確認済みのアドレスなら、同じアドレスの会員に結びつける（その会員に同じ提供元の別アカウントが無いときだけ）\n    if v_email is not null and p_email_verified then\n      select id into v_customer_id from customers c where c.shop_id = p_shop_id and lower(c.email) = v_email\n         and not exists (select 1 from member_identities i where i.shop_id = p_shop_id and i.customer_id = c.id and i.provider = p_provider);\n    end if;\n    if v_customer_id is null then\n      insert into customers (shop_id, email)\n      values (p_shop_id, case when p_email_verified and v_email is not null\n                               and not exists (select 1 from customers where shop_id = p_shop_id and lower(email) = v_email) then v_email end)\n      returning id into v_customer_id;\n      v_created := true;\n    end if;\n    insert into member_identities (shop_id, provider, subject, customer_id) values (p_shop_id, p_provider, p_subject, v_customer_id);\n    v_linked := true;\n  end if;\n\n  update customers set last_login_at = now() where shop_id = p_shop_id and id = v_customer_id returning * into v_c;\n  return jsonb_build_object('ok', true, 'customer_id', v_c.id, 'session_epoch', v_c.session_epoch, 'email', v_c.email,\n                            'created', v_created, 'linked', v_linked,\n                            'mail_from', case when p_link_customer_id is not null and v_linked then banto_member_mail_from(p_shop_id) end);\nend;\n$$;\nrevoke execute on function member_oauth_login(uuid, text, text, text, boolean, uuid, integer, uuid) from public, anon, authenticated;\ngrant execute on function member_oauth_login(uuid, text, text, text, boolean, uuid, integer, uuid) to service_role;\n\n-- ---------- 運営者の二段階認証の登録・解除を監査ログに ----------\n-- GoTrue の auth.mfa_factors にはトリガーを張れない（Supabase の管理下）ので、Worker が登録・解除の直後に呼ぶ。\n-- 書くのは自分の分だけ（target = auth.uid()）。属する組織ごとに 1 行\ncreate or replace function org_member_mfa_self(p_action text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_org uuid;\nbegin\n  if auth.uid() is null then raise exception 'forbidden' using errcode = '42501'; end if;\n  if p_action not in ('enabled', 'disabled') then raise exception 'invalid_action'; end if;\n  for v_org in select org_id from org_members where user_id = auth.uid() loop\n    perform banto_audit(v_org, null, 'org_member.mfa_' || p_action, 'user', auth.uid()::text, '{}'::jsonb);\n  end loop;\nend;\n$$;\nrevoke execute on function org_member_mfa_self(text) from public, anon;\ngrant execute on function org_member_mfa_self(text) to authenticated, service_role;\n\ninsert into banto_migrations (version) values ('0057_member_reauth');\n" },
  { version: "0058_product_listing", sql: "-- Banto 0058_product_listing: 商品の一覧を DB で絞り込み・並べ替え・ページ送りする（10 万〜100 万件。人間の決定 2026-10-26）。前方専用。\n-- それまでのお店の画面と公開 API は、公開中の商品を全件読んで Worker のメモリで絞り込んでいた（PostgREST の 1,000 行で黙って欠け、\n-- 件数が増えると CPU 10ms とメモリに収まらない）。docs/knowledge/02-decisions.md「商品の一覧を DB に寄せる」。\n--   1. products.list_price_jpy / list_compare_at_jpy: いちばん安い SKU の価格と、その SKU の通常価格（並べ替えのため。在庫は写さない）。\n--      SKU の文単位のトリガーで保つ。値が変わると商品の updated_at も進む（updated_since での同期に価格の変更が載る）。\n--   2. product_facets: 公開中の商品のタグごと・カテゴリーごと（子孫を含み、1 商品は 1 回）の件数。文単位のトリガーで差分を足す。\n--      カテゴリーの木が変わったら（親の付け替え・削除）そのショップのカテゴリーの件数を作り直す。\n--   3. 検索: pg_trgm の GIN（式インデックス。名前・ブランド・タグ・説明の先頭 300 文字）。2 文字以下の語はインデックスが効かない。\n--   4. 並べ替えごとの部分インデックス（公開中だけ）と、キーセットのページ送り（offset は 10,000 まで）。\n--   5. product_public_list / product_public_facets（anon）。公開中のショップの公開中の商品だけ。attributes は返さない。\n\n-- ---------- pg_trgm ----------\n-- Supabase は拡張を extensions スキーマに置く。素の PostgreSQL ではスキーマを作ってそこに入れる。\n-- 既に別のスキーマに入っていればそれを使う（演算子クラスの場所は下で引く）\ncreate schema if not exists extensions;\ncreate extension if not exists pg_trgm with schema extensions;\n\n-- ---------- 1. いちばん安い SKU の価格 ----------\nalter table products\n  add column list_price_jpy integer,\n  add column list_compare_at_jpy integer;\n\n-- p_ids の商品の list_* を SKU から引き直す（変わった行だけ書く）。\n-- 商品ごとの副問い合わせにしない（同じトランザクションで大量に入れた直後は統計が古く、SKU を毎回全件見る計画になるため）。\n-- 対象の SKU をまとめて結び、商品ごとにいちばん安いものを 1 つ選ぶ\ncreate or replace function banto_product_list_price_refresh(p_ids uuid[])\nreturns void\nlanguage sql\nsecurity definer\nset search_path = public\nas $$\n  with ids as (select distinct x.id from unnest(p_ids) x(id) where x.id is not null),\n  best as (\n    select distinct on (k.product_id) k.product_id, k.price_jpy, k.compare_at_price_jpy\n      from skus k join ids on ids.id = k.product_id\n     order by k.product_id, k.price_jpy, k.created_at, k.id\n  )\n  update products p\n     set list_price_jpy = best.price_jpy, list_compare_at_jpy = best.compare_at_price_jpy\n    from ids left join best on best.product_id = ids.id\n   where p.id = ids.id\n     and (p.list_price_jpy is distinct from best.price_jpy or p.list_compare_at_jpy is distinct from best.compare_at_price_jpy);\n$$;\n\n-- SKU を足したとき: 足した SKU だけで決まる（いちばん安いものが今の価格より安ければ入れ替え。同額なら前からある SKU のまま）。\n-- SKU の表を読まないので、大量に入れた直後の統計の古さに左右されない\ncreate or replace function banto_skus_list_price_ins()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  update products p\n     set list_price_jpy = c.price_jpy, list_compare_at_jpy = c.compare_at_price_jpy\n    from (select distinct on (product_id) product_id, price_jpy, compare_at_price_jpy\n            from new_rows order by product_id, price_jpy, created_at, id) c\n   where p.id = c.product_id and (p.list_price_jpy is null or c.price_jpy < p.list_price_jpy);\n  return null;\nend;\n$$;\ncreate or replace function banto_skus_list_price_upd()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  -- 前後の行を突き合わせない（遷移表の結合は計画が崩れると行数の 2 乗）。値が同じなら refresh が書かない\n  perform banto_product_list_price_refresh(array(select product_id from new_rows union select product_id from old_rows));\n  return null;\nend;\n$$;\ncreate or replace function banto_skus_list_price_del()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  perform banto_product_list_price_refresh(array(select distinct product_id from old_rows));\n  return null;\nend;\n$$;\ncreate trigger skus_list_price_ins after insert on skus referencing new table as new_rows\n  for each statement execute function banto_skus_list_price_ins();\ncreate trigger skus_list_price_upd after update on skus referencing old table as old_rows new table as new_rows\n  for each statement execute function banto_skus_list_price_upd();\ncreate trigger skus_list_price_del after delete on skus referencing old table as old_rows\n  for each statement execute function banto_skus_list_price_del();\n\n-- ---------- 2. タグ・カテゴリーごとの件数 ----------\ncreate table product_facets (\n  shop_id uuid not null references shops(id) on delete cascade,\n  kind text not null check (kind in ('tag', 'category')),\n  key text not null,\n  count integer not null,\n  primary key (shop_id, kind, key)\n);\nalter table product_facets enable row level security;\n-- 運営者は読めるだけ（書くのはトリガーだけ）。お客様の画面は product_public_facets で読む\ncreate policy product_facets_catalog on product_facets for select using (banto_owns_shop(shop_id) or banto_shop_perm(shop_id, 'catalog'));\nrevoke insert, update, delete on product_facets from anon, authenticated;\n\n-- 商品の行（id, shop_id, tags, category_id, extra_category_ids を持つ jsonb の配列）が数える先。\n-- タグは重複を除き、カテゴリーは主・追加のそれぞれの祖先まで広げて重複を除く（1 商品はカテゴリーごとに 1 回）\ncreate or replace function banto_product_facet_keys(p_rows jsonb)\nreturns table (shop_id uuid, kind text, key text)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  with recursive r as (\n    select (e->>'id')::uuid as id, (e->>'shop_id')::uuid as shop_id,\n           case when jsonb_typeof(e->'tags') = 'array' then e->'tags' else '[]'::jsonb end as tags,\n           array_remove(array[(e->>'category_id')::uuid]\n                        || coalesce(array(select jsonb_array_elements_text(case when jsonb_typeof(e->'extra_category_ids') = 'array' then e->'extra_category_ids' else '[]'::jsonb end)::uuid), '{}'), null) as cats\n      from jsonb_array_elements(p_rows) e\n  ),\n  anc(id, anc) as (\n    select c.id, c.id from categories c where c.shop_id in (select distinct r.shop_id from r)\n    union all\n    select a.id, c.parent_id from anc a join categories c on c.id = a.anc where c.parent_id is not null\n  )\n  select r.shop_id, 'tag', t.value from r, lateral (select distinct value from jsonb_array_elements_text(r.tags) where value is not null) t\n  union all\n  select r.shop_id, 'category', x.anc::text\n    from r, lateral (select distinct a.anc from unnest(r.cats) d(cid) join anc a on a.id = d.cid) x;\n$$;\n\n-- 差分を足す。増える分は upsert、減る分は update か（0 以下になるなら）delete だけ\n-- （減る分で行を作らない: ショップの削除の連鎖の途中で、消えていくショップの行を作らないため）\ncreate or replace function banto_product_facets_apply(p_old jsonb, p_new jsonb)\nreturns void\nlanguage sql\nsecurity definer\nset search_path = public\nas $$\n  with d as (\n    select k.shop_id, k.kind, k.key, sum(k.d)::integer as d\n      from (select f.*, -1 as d from banto_product_facet_keys(p_old) f\n            union all\n            select f.*, 1 from banto_product_facet_keys(p_new) f) k\n     group by 1, 2, 3\n    having sum(k.d) <> 0\n  ),\n  ins as (\n    insert into product_facets (shop_id, kind, key, count)\n    select d.shop_id, d.kind, d.key, d.d from d where d.d > 0\n    on conflict (shop_id, kind, key) do update set count = product_facets.count + excluded.count\n    returning 1\n  ),\n  upd as (\n    update product_facets f set count = f.count + d.d\n      from d\n     where d.d < 0 and f.shop_id = d.shop_id and f.kind = d.kind and f.key = d.key and f.count + d.d > 0\n    returning 1\n  )\n  delete from product_facets f using d\n   where d.d < 0 and f.shop_id = d.shop_id and f.kind = d.kind and f.key = d.key and f.count + d.d <= 0;\n$$;\n\n-- 公開中の行だけを数える形に\ncreate or replace function banto_product_facet_rows_ins()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  perform banto_product_facets_apply('[]'::jsonb,\n    (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'shop_id', shop_id, 'tags', tags, 'category_id', category_id, 'extra_category_ids', extra_category_ids)), '[]')\n       from new_rows where published));\n  return null;\nend;\n$$;\n-- 更新: 前の行の分を引き、後の行の分を足す。変わっていない行は打ち消し合う（前後の行を突き合わせる結合は、\n-- 統計の無い遷移表で入れ子のループの計画になると行数の 2 乗になるので使わない）。数える材料の列が変わらない更新\n-- （価格の写し・説明の変更など）でも行の数に比例する手間はかかる\ncreate or replace function banto_product_facet_rows_upd()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  perform banto_product_facets_apply(\n    (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'shop_id', shop_id, 'tags', tags, 'category_id', category_id, 'extra_category_ids', extra_category_ids)), '[]')\n       from old_rows where published),\n    (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'shop_id', shop_id, 'tags', tags, 'category_id', category_id, 'extra_category_ids', extra_category_ids)), '[]')\n       from new_rows where published));\n  return null;\nend;\n$$;\ncreate or replace function banto_product_facet_rows_del()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  perform banto_product_facets_apply(\n    (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'shop_id', shop_id, 'tags', tags, 'category_id', category_id, 'extra_category_ids', extra_category_ids)), '[]')\n       from old_rows where published),\n    '[]'::jsonb);\n  return null;\nend;\n$$;\ncreate trigger products_facets_ins after insert on products referencing new table as new_rows\n  for each statement execute function banto_product_facet_rows_ins();\ncreate trigger products_facets_upd after update on products referencing old table as old_rows new table as new_rows\n  for each statement execute function banto_product_facet_rows_upd();\ncreate trigger products_facets_del after delete on products referencing old table as old_rows\n  for each statement execute function banto_product_facet_rows_del();\n\n-- ショップの件数を作り直す（p_kind が null なら両方）。カテゴリーの木が変わったときと、このマイグレーションの初期化に使う\ncreate or replace function banto_product_facets_rebuild(p_shop_id uuid, p_kind text default null)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  delete from product_facets where shop_id = p_shop_id and (p_kind is null or kind = p_kind);\n  if p_kind is null or p_kind = 'tag' then\n    insert into product_facets (shop_id, kind, key, count)\n    select p_shop_id, 'tag', t.value, count(distinct p.id)\n      from products p, unnest(p.tags) t(value)\n     where p.shop_id = p_shop_id and p.published and t.value is not null\n     group by t.value;\n  end if;\n  if p_kind is null or p_kind = 'category' then\n    insert into product_facets (shop_id, kind, key, count)\n    with recursive anc(id, anc) as (\n      select c.id, c.id from categories c where c.shop_id = p_shop_id\n      union all\n      select a.id, c.parent_id from anc a join categories c on c.id = a.anc where c.parent_id is not null\n    )\n    select p_shop_id, 'category', a.anc::text, count(distinct p.id)\n      from products p\n      cross join lateral unnest(array_remove(array[p.category_id] || p.extra_category_ids, null)) d(cid)\n      join anc a on a.id = d.cid\n     where p.shop_id = p_shop_id and p.published\n     group by a.anc;\n  end if;\nend;\n$$;\n\n-- カテゴリーの親の付け替え・削除（追加カテゴリーから外す 0042 のトリガーの後に動く文単位のトリガー）\ncreate or replace function banto_categories_facets_upd()\nreturns trigger language plpgsql security definer set search_path = public as $$\ndeclare v_shop uuid;\nbegin\n  for v_shop in select distinct n.shop_id from new_rows n join old_rows o on o.id = n.id where n.parent_id is distinct from o.parent_id loop\n    perform banto_product_facets_rebuild(v_shop, 'category');\n  end loop;\n  return null;\nend;\n$$;\ncreate or replace function banto_categories_facets_del()\nreturns trigger language plpgsql security definer set search_path = public as $$\ndeclare v_shop uuid;\nbegin\n  for v_shop in select distinct o.shop_id from old_rows o where exists (select 1 from shops s where s.id = o.shop_id) loop\n    perform banto_product_facets_rebuild(v_shop, 'category');\n  end loop;\n  return null;\nend;\n$$;\ncreate trigger categories_facets_upd after update on categories referencing old table as old_rows new table as new_rows\n  for each statement execute function banto_categories_facets_upd();\ncreate trigger categories_facets_del after delete on categories referencing old table as old_rows\n  for each statement execute function banto_categories_facets_del();\n\n-- ---------- 3. 検索 ----------\n-- 小文字にした「名前 ブランド タグ 説明の先頭 300 文字」。式インデックスと product_public_list で同じ式を使う\ncreate or replace function banto_product_search_text(p_name text, p_brand text, p_tags text[], p_description text)\nreturns text\nlanguage sql\nimmutable\nparallel safe\nas $$\n  select lower(coalesce(p_name, '') || ' ' || coalesce(p_brand, '') || ' ' || coalesce(array_to_string(p_tags, ' '), '') || ' ' || left(coalesce(p_description, ''), 300));\n$$;\n\ndo $$\ndeclare v_schema text;\nbegin\n  select n.nspname into v_schema from pg_opclass o join pg_namespace n on n.oid = o.opcnamespace\n   where o.opcname = 'gin_trgm_ops' limit 1;\n  execute format('create index products_search_trgm on products using gin (banto_product_search_text(name, brand, tags, description) %I.gin_trgm_ops) where published', v_schema);\nend;\n$$;\n\n-- ---------- 4. 並べ替えのインデックス（公開中だけ） ----------\ncreate index products_list_new on products (shop_id, created_at desc, id desc) where published;\ncreate index products_list_updated on products (shop_id, updated_at desc, id desc) where published;\ncreate index products_list_price_asc on products (shop_id, (coalesce(list_price_jpy, 2147483647)), id) where published;\ncreate index products_list_price_desc on products (shop_id, (coalesce(list_price_jpy, -1)) desc, id desc) where published;\ncreate index products_list_name on products (shop_id, name, id) where published;\ncreate index products_list_brand on products (shop_id, brand) where published and brand is not null;\n\n-- ---------- 5. お客様の画面・公開 API ----------\n-- p_sort: new | updated | price_asc | price_desc | name。p_after: 前のページの next（{\"k\": 並べ替えの値, \"id\": 商品 id}）。\n-- p_after が無いときだけ p_offset（0〜10,000）。p_category_ids は子孫まで広げた id（null = 絞らない、空 = 0 件）。\n-- p_count: total（10,000 まで数える。超えたら total_capped = true）。\n-- 返す形: { items: [...], next: {k, id} | null, total?: number, total_capped?: boolean }\ncreate or replace function product_public_list(\n  p_shop_id uuid,\n  p_sort text default 'new',\n  p_limit integer default 24,\n  p_after jsonb default null,\n  p_offset integer default 0,\n  p_tag text default null,\n  p_category_ids uuid[] default null,\n  p_brand text default null,\n  p_q text default null,\n  p_updated_since timestamptz default null,\n  p_count boolean default false\n)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_limit integer := least(greatest(coalesce(p_limit, 24), 1), 100);\n  v_offset integer := greatest(coalesce(p_offset, 0), 0);\n  v_offset_max integer;\n  v_key text;    -- 並べ替えの値の式\n  v_order text;  -- order by\n  v_cmp text;    -- キーセットの比較（> か <）\n  v_cast text;   -- p_after の k の型\n  v_where text;\n  v_like text;\n  v_rows jsonb;\n  v_total integer;\n  v_last jsonb;\n  v_next jsonb;\nbegin\n  if not exists (select 1 from shops where id = p_shop_id and published) then\n    return jsonb_build_object('items', '[]'::jsonb, 'next', null);\n  end if;\n  -- 検索の語があるときは 1,000 まで（深い位置まで読ませて DB を重くさせない。先は p_after で）\n  v_offset_max := 10000;\n  if nullif(btrim(coalesce(p_q, '')), '') is not null then v_offset_max := 1000; end if;\n  if v_offset > v_offset_max then raise exception 'offset_too_large' using errcode = '22023'; end if;\n  case coalesce(p_sort, 'new')\n    when 'new' then v_key := 'p.created_at'; v_order := 'p.created_at desc, p.id desc'; v_cmp := '<'; v_cast := 'timestamptz';\n    when 'updated' then v_key := 'p.updated_at'; v_order := 'p.updated_at desc, p.id desc'; v_cmp := '<'; v_cast := 'timestamptz';\n    when 'price_asc' then v_key := 'coalesce(p.list_price_jpy, 2147483647)'; v_order := 'coalesce(p.list_price_jpy, 2147483647), p.id'; v_cmp := '>'; v_cast := 'integer';\n    when 'price_desc' then v_key := 'coalesce(p.list_price_jpy, -1)'; v_order := 'coalesce(p.list_price_jpy, -1) desc, p.id desc'; v_cmp := '<'; v_cast := 'integer';\n    when 'name' then v_key := 'p.name'; v_order := 'p.name, p.id'; v_cmp := '>'; v_cast := 'text';\n    else raise exception 'invalid_sort' using errcode = '22023';\n  end case;\n  -- 2 文字以下の語は pg_trgm のインデックスが効かず全件を見るので、タグ・カテゴリー・ブランドで絞っているときだけ\n  -- （ログイン無しで何度も送られて DB を重くされないように。人間の決定 2026-10-26）\n  if p_q is not null and btrim(p_q) <> '' and char_length(btrim(p_q)) < 3\n     and p_tag is null and p_category_ids is null and p_brand is null then\n    raise exception 'q_too_short' using errcode = '22023';\n  end if;\n  if p_q is not null and btrim(p_q) <> '' then\n    v_like := '%' || replace(replace(replace(lower(left(btrim(p_q), 100)), '\\', '\\\\'), '%', '\\%'), '_', '\\_') || '%';\n  end if;\n\n  v_where := 'p.shop_id = $1 and p.published'\n    || case when p_tag is not null then ' and p.tags @> array[$2::text]' else '' end\n    || case when p_category_ids is not null then ' and (p.category_id = any($3) or p.extra_category_ids && $3)' else '' end\n    || case when p_brand is not null then ' and p.brand = $4' else '' end\n    || case when v_like is not null then ' and banto_product_search_text(p.name, p.brand, p.tags, p.description) like $5' else '' end\n    || case when p_updated_since is not null then ' and p.updated_at > $6' else '' end;\n\n  if p_count then\n    execute format('select count(*) from (select 1 from products p where %s limit 10001) x', v_where)\n      into v_total using p_shop_id, p_tag, p_category_ids, p_brand, v_like, p_updated_since;\n  end if;\n\n  execute format(\n    'select coalesce(jsonb_agg(r order by ord), ''[]'') from ('\n    || 'select row_number() over (order by %s) as ord, jsonb_build_object('\n    || '''id'', p.id, ''slug'', p.slug, ''name'', p.name, ''brand'', p.brand, ''category_id'', p.category_id,'\n    || '''extra_category_ids'', p.extra_category_ids, ''tags'', p.tags, ''created_at'', p.created_at, ''updated_at'', p.updated_at,'\n    || '''min_price_jpy'', p.list_price_jpy, ''compare_at_price_jpy'', p.list_compare_at_jpy, ''k'', %s,'\n    || '''image'', (select jsonb_build_object(''storage_key'', i.storage_key, ''thumb_key'', i.thumb_key, ''width'', i.width, ''height'', i.height)'\n    || '            from product_images i where i.product_id = p.id order by i.sort_order, i.created_at limit 1)'\n    || ') as r from products p where %s %s order by %s limit %s offset %s) t',\n    v_order, v_key, v_where,\n    case when p_after is not null then format(' and (%s, p.id) %s (($7->>''k'')::%s, ($7->>''id'')::uuid)', v_key, v_cmp, v_cast) else '' end,\n    v_order, v_limit + 1, case when p_after is not null then 0 else v_offset end)\n    into v_rows using p_shop_id, p_tag, p_category_ids, p_brand, v_like, p_updated_since, p_after;\n\n  if jsonb_array_length(v_rows) > v_limit then\n    v_rows := v_rows - v_limit;\n    v_last := v_rows -> (v_limit - 1);\n    v_next := jsonb_build_object('k', v_last->'k', 'id', v_last->'id');\n  end if;\n  return jsonb_build_object('items', (select coalesce(jsonb_agg(e - 'k'), '[]') from jsonb_array_elements(v_rows) e), 'next', v_next)\n      || case when p_count then jsonb_build_object('total', least(v_total, 10000), 'total_capped', v_total > 10000) else '{}'::jsonb end;\nend;\n$$;\n\n-- タグ（多い順に p_tag_limit 件まで、同数なら文字コード順）とカテゴリーごとの件数（{ category_id: 件数 }）\ncreate or replace function product_public_facets(p_shop_id uuid, p_tag_limit integer default 200)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when not exists (select 1 from shops where id = p_shop_id and published)\n              then jsonb_build_object('tags', '[]'::jsonb, 'categories', '{}'::jsonb)\n         else jsonb_build_object(\n           'tags', coalesce((select jsonb_agg(jsonb_build_object('tag', key, 'count', count) order by count desc, key collate \"C\")\n                               from (select key, count from product_facets where shop_id = p_shop_id and kind = 'tag'\n                                      order by count desc, key collate \"C\" limit least(greatest(coalesce(p_tag_limit, 200), 1), 1000)) t), '[]'::jsonb),\n           'categories', coalesce((select jsonb_object_agg(key, count) from product_facets where shop_id = p_shop_id and kind = 'category'), '{}'::jsonb))\n         end;\n$$;\n\nrevoke execute on function banto_product_list_price_refresh(uuid[]) from public, anon, authenticated;\nrevoke execute on function banto_skus_list_price_ins() from public, anon, authenticated;\nrevoke execute on function banto_skus_list_price_upd() from public, anon, authenticated;\nrevoke execute on function banto_skus_list_price_del() from public, anon, authenticated;\nrevoke execute on function banto_product_facet_keys(jsonb) from public, anon, authenticated;\nrevoke execute on function banto_product_facets_apply(jsonb, jsonb) from public, anon, authenticated;\nrevoke execute on function banto_product_facet_rows_ins() from public, anon, authenticated;\nrevoke execute on function banto_product_facet_rows_upd() from public, anon, authenticated;\nrevoke execute on function banto_product_facet_rows_del() from public, anon, authenticated;\nrevoke execute on function banto_product_facets_rebuild(uuid, text) from public, anon, authenticated;\nrevoke execute on function banto_categories_facets_upd() from public, anon, authenticated;\nrevoke execute on function banto_categories_facets_del() from public, anon, authenticated;\nrevoke execute on function product_public_list(uuid, text, integer, jsonb, integer, text, uuid[], text, text, timestamptz, boolean) from public;\ngrant execute on function product_public_list(uuid, text, integer, jsonb, integer, text, uuid[], text, text, timestamptz, boolean) to anon, authenticated, service_role;\nrevoke execute on function product_public_facets(uuid, integer) from public;\ngrant execute on function product_public_facets(uuid, integer) to anon, authenticated, service_role;\n\n-- ---------- 既存のデータ ----------\n-- 価格の初期化では updated_at を進めない（同期の差分に全商品が載らないように）\nalter table products disable trigger products_updated_at;\nselect banto_product_list_price_refresh(array(select id from products));\nalter table products enable trigger products_updated_at;\nselect banto_product_facets_rebuild(id) from shops;\n\ninsert into banto_migrations (version) values ('0058_product_listing');\n" },
  { version: "0059_admin_lists", sql: "-- Banto 0059_admin_lists: 管理画面の一覧を DB で検索・ページ送りする（10 万〜100 万件。人間の決定 2026-10-26）。前方専用。\n-- 管理画面の一覧（商品・注文・会員・クーポン・発行したクーポン）は、新しい順のキーセット（created_at desc, id desc）で 1 ページずつ読み、\n-- 名前・メールなどの部分一致は admin_search_ids（下）で id を探す（src/routes/admin/paging.tsx）。そのためのインデックスと、\n-- キャンペーンの「使われた数」を表示する分だけ数える coupon_stats_for、発行したクーポンの状態ごとの数 coupon_grant_counts。\n-- コードは適用前の DB でも動く（migrated() で分岐し、部分一致は PostgREST の ilike・数は行ごとに数える。結果は同じで遅いだけ）。\n\n-- ---------- 新しい順のページ送り ----------\ncreate index if not exists products_admin_list on products (shop_id, created_at desc, id desc);\ncreate index if not exists orders_admin_list on orders (shop_id, created_at desc, id desc);\ncreate index if not exists customers_admin_list on customers (shop_id, created_at desc, id desc);\ncreate index if not exists coupon_campaigns_admin_list on coupon_campaigns (shop_id, created_at desc, id desc);\ncreate index if not exists coupon_grants_admin_list on coupon_grants (campaign_id, created_at desc, id desc);\ncreate index if not exists coupon_grants_status on coupon_grants (campaign_id, status);\n\n-- ---------- 部分一致（ilike）: pg_trgm の GIN（0058 で入れた拡張。演算子クラスの場所を引く） ----------\ndo $$\ndeclare v_schema text;\nbegin\n  select n.nspname into v_schema from pg_opclass o join pg_namespace n on n.oid = o.opcnamespace where o.opcname = 'gin_trgm_ops' limit 1;\n  execute format('create index if not exists products_name_trgm on products using gin (name %I.gin_trgm_ops)', v_schema);\n  execute format('create index if not exists products_slug_trgm on products using gin (slug %I.gin_trgm_ops)', v_schema);\n  execute format('create index if not exists orders_email_trgm on orders using gin (customer_email %I.gin_trgm_ops)', v_schema);\n  execute format('create index if not exists orders_name_trgm on orders using gin (customer_name %I.gin_trgm_ops)', v_schema);\n  execute format('create index if not exists customers_email_trgm on customers using gin (email %I.gin_trgm_ops)', v_schema);\n  execute format('create index if not exists customers_name_trgm on customers using gin (name %I.gin_trgm_ops)', v_schema);\nend;\n$$;\ncreate index if not exists orders_payment_ref on orders (shop_id, payment_ref) where payment_ref is not null;\n\n-- ---------- キャンペーンの使われた数（表示する分だけ） ----------\n-- coupon_stats（0024）と同じ権限（marketing の項目）。p_campaign_ids は 200 個まで\ncreate or replace function coupon_stats_for(p_shop_id uuid, p_campaign_ids uuid[])\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when banto_shop_perm(p_shop_id, 'marketing') and cardinality(p_campaign_ids) <= 200 then coalesce((\n    select jsonb_object_agg(campaign_id, jsonb_build_object('used', used, 'held', held))\n      from (select campaign_id, count(*) filter (where status = 'used') as used, count(*) filter (where status = 'held') as held\n              from coupon_redemptions where shop_id = p_shop_id and campaign_id = any(p_campaign_ids) group by campaign_id) x), '{}'::jsonb) end;\n$$;\nrevoke execute on function coupon_stats_for(uuid, uuid[]) from public, anon;\ngrant execute on function coupon_stats_for(uuid, uuid[]) to authenticated, service_role;\n\n-- ---------- 部分一致の検索と大きな数え上げ（RLS の外で、権限は 1 回だけ確かめる） ----------\n-- RLS の掛かった表では ilike（漏れうる演算子）を権限の判定より先に評価できないので、pg_trgm のインデックスが使われず\n-- 全件を見る（10 万件で数百 ms、100 万件で数秒。test/db/scale.test.ts）。行ごとに権限の関数を呼ぶ数え上げも同じ。\n-- そこで、権限を 1 回確かめてから id だけを探す関数を置き、行そのものは今までどおり RLS 越しに読む（src/routes/admin/paging.tsx）。\n\n-- 管理画面の一覧の検索: 条件に合う行の id を新しい順（created_at desc, id desc）に p_limit 個（1,000 まで）、p_after より後ろから。\n--   products（catalog）: q = 名前・スラッグの部分一致、filters.state = published | draft\n--   orders（orders）: q = 注文番号・決済の参照の完全一致かメール・氏名の部分一致、filters.status\n--   customers（customers）: q = メール・氏名の部分一致、filters.field / filters.value = 独自項目の値の部分一致、filters.consent = yes | no | none\ncreate or replace function admin_search_ids(p_shop_id uuid, p_kind text, p_q text, p_filters jsonb, p_after_k timestamptz, p_after_id uuid, p_limit integer)\nreturns uuid[]\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_like text;\n  v_where text := 'shop_id = $1';\n  v_table text;\n  v_perm text;\n  v_q text := nullif(btrim(left(coalesce(p_q, ''), 100)), '');\n  v_f jsonb := coalesce(p_filters, '{}'::jsonb);\n  v_out uuid[];\nbegin\n  case p_kind\n    when 'products' then v_table := 'products'; v_perm := 'catalog';\n    when 'orders' then v_table := 'orders'; v_perm := 'orders';\n    when 'customers' then v_table := 'customers'; v_perm := 'customers';\n    else raise exception 'invalid_kind' using errcode = '22023';\n  end case;\n  if not banto_shop_perm(p_shop_id, v_perm) then raise exception 'forbidden' using errcode = '42501'; end if;\n  if v_q is not null then\n    v_like := '%' || replace(replace(replace(v_q, '\\', '\\\\'), '%', '\\%'), '_', '\\_') || '%';\n  end if;\n  if p_kind = 'products' then\n    if v_like is not null then v_where := v_where || ' and (name ilike $2 or slug ilike $2)'; end if;\n    if v_f->>'state' = 'published' then v_where := v_where || ' and published'; end if;\n    if v_f->>'state' = 'draft' then v_where := v_where || ' and not published'; end if;\n  elsif p_kind = 'orders' then\n    if v_like is not null then\n      v_where := v_where || ' and (customer_email ilike $2 or customer_name ilike $2 or payment_ref = $3'\n        || case when v_q ~ '^\\d{1,9}$' then ' or number = $3::integer' else '' end || ')';\n    end if;\n    if v_f->>'status' in ('paid', 'shipped', 'cancelled', 'refunded') then v_where := v_where || format(' and status = %L', v_f->>'status'); end if;\n  else\n    if v_like is not null then v_where := v_where || ' and (email ilike $2 or name ilike $2)'; end if;\n    if coalesce(v_f->>'field', '') ~ '^[a-z][a-z0-9_]{0,39}$' and nullif(v_f->>'value', '') is not null then\n      v_where := v_where || format(' and attributes->>%L ilike $4', v_f->>'field');\n    end if;\n    if v_f->>'consent' = 'yes' then v_where := v_where || ' and marketing_consent is true'; end if;\n    if v_f->>'consent' = 'no' then v_where := v_where || ' and marketing_consent is false'; end if;\n    if v_f->>'consent' = 'none' then v_where := v_where || ' and marketing_consent is null'; end if;\n  end if;\n  if p_after_k is not null and p_after_id is not null then\n    v_where := v_where || ' and (created_at < $5 or (created_at = $5 and id < $6))';\n  end if;\n  execute format('select coalesce(array_agg(id order by created_at desc, id desc), ''{}'') from (select id, created_at from %I where %s order by created_at desc, id desc limit %s) x',\n                 v_table, v_where, least(greatest(coalesce(p_limit, 50), 1), 1000))\n    into v_out\n    using p_shop_id, v_like, v_q,\n          '%' || replace(replace(replace(coalesce(v_f->>'value', ''), '\\', '\\\\'), '%', '\\%'), '_', '\\_') || '%',\n          p_after_k, p_after_id;\n  return v_out;\nend;\n$$;\nrevoke execute on function admin_search_ids(uuid, text, text, jsonb, timestamptz, uuid, integer) from public, anon;\ngrant execute on function admin_search_ids(uuid, text, text, jsonb, timestamptz, uuid, integer) to authenticated, service_role;\n\n-- 発行したクーポンの状態ごとの数（marketing の項目）。{ available, held, used, revoked }\ncreate or replace function coupon_grant_counts(p_shop_id uuid, p_campaign_id uuid)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when banto_shop_perm(p_shop_id, 'marketing') then\n    jsonb_build_object('available', 0, 'held', 0, 'used', 0, 'revoked', 0)\n    || coalesce((select jsonb_object_agg(status, n) from (select status, count(*) as n from coupon_grants\n                  where shop_id = p_shop_id and campaign_id = p_campaign_id group by status) x), '{}'::jsonb) end;\n$$;\nrevoke execute on function coupon_grant_counts(uuid, uuid) from public, anon;\ngrant execute on function coupon_grant_counts(uuid, uuid) to authenticated, service_role;\n\ninsert into banto_migrations (version) values ('0059_admin_lists');\n" },
  { version: "0060_catalog_pages", sql: "-- Banto 0060_catalog_pages: サイトマップと商品フィードを、商品の数に比例しない回数で作る（10 万〜100 万件。人間の決定 2026-10-26）。前方専用。\n-- それまではサイトマップも商品フィードも、公開中の商品を全件読んでから組んでいた（サイトマップは 1,000 件で欠け、\n-- フィードは 1,000 行ずつ全件を読むので Workers の 1 回あたりの問い合わせの上限に掛かる）。\n--   - サイトマップ: /sitemap.xml を索引にし、商品は 1 ファイル 10,000 件ずつ（product_public_count / product_public_slugs）。\n--   - 商品フィード: Cron が 1 回に数ページずつ（product_feed_page、id 順のキーセット、1 回 1,000 商品まで）作り、\n--     R2 に分けて置き、配信のときにつないで返す（src/modules/product-feed/job.ts）。1 回に進める量は workers_plan（banto_site_plan）。\n-- どれも anon（公開中のショップの公開中の商品だけ。説明・独自項目の非公開の値は返さない）。\n\ncreate index if not exists products_public_id on products (shop_id, id) where published;\n\n-- 公開中の商品の数（サイトマップのファイルの数を決める）\ncreate or replace function product_public_count(p_shop_id uuid)\nreturns integer\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when exists (select 1 from shops where id = p_shop_id and published)\n              then (select count(*)::integer from products where shop_id = p_shop_id and published) else 0 end;\n$$;\n\n-- サイトマップの 1 ファイル分: [[slug, 更新日時], …]（id 順。p_limit は 10,000 まで）\ncreate or replace function product_public_slugs(p_shop_id uuid, p_offset integer, p_limit integer)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce((select jsonb_agg(jsonb_build_array(slug, updated_at) order by id)\n                     from (select id, slug, updated_at from products\n                            where shop_id = p_shop_id and published\n                              and exists (select 1 from shops where id = p_shop_id and published)\n                            order by id offset greatest(coalesce(p_offset, 0), 0) limit least(greatest(coalesce(p_limit, 0), 0), 10000)) x), '[]'::jsonb);\n$$;\n\n-- 商品フィードの 1 ページ: id が p_after より後ろの公開中の商品を p_limit 件（1,000 まで）と、その SKU・在庫・画像。\n-- { products: [...], skus: [...], inventory: [{ sku_id, in_stock }], images: [...] }。products は説明つき（フィードの description）、attributes は返さない。\n-- 商品フィードのモジュールが ON のショップだけ（OFF なら空）\ncreate or replace function product_feed_page(p_shop_id uuid, p_after uuid, p_limit integer)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  with p as (\n    select id, shop_id, slug, name, description, tags, category_id, extra_category_ids, brand, tax_class, published, created_at, updated_at\n      from products\n     where shop_id = p_shop_id and published and (p_after is null or id > p_after)\n       and exists (select 1 from shops where id = p_shop_id and published\n                     and coalesce(settings->'modules'->>'product_feed', 'false') = 'true')\n     order by id\n     limit least(greatest(coalesce(p_limit, 0), 0), 1000)\n  ),\n  k as (select s.* from skus s where s.product_id in (select id from p))\n  select jsonb_build_object(\n    'products', coalesce((select jsonb_agg(to_jsonb(p) order by p.id) from p), '[]'::jsonb),\n    'skus', coalesce((select jsonb_agg(to_jsonb(k) order by k.product_id, k.created_at) from k), '[]'::jsonb),\n    -- 在庫は「あり / なし」だけ（フィードの availability に要るのはそれだけ。正確な数は返さない）\n    'inventory', coalesce((select jsonb_agg(jsonb_build_object('sku_id', i.sku_id, 'in_stock', i.available > 0)) from inventory i where i.sku_id in (select id from k)), '[]'::jsonb),\n    'images', coalesce((select jsonb_agg(to_jsonb(im) order by im.product_id, im.sort_order) from product_images im where im.product_id in (select id from p)), '[]'::jsonb)\n  );\n$$;\n\n-- このデプロイの Workers のプラン（free / paid）。裏の処理が 1 回に進める量を決める（0038 の workers_plan。秘密ではない）\ncreate or replace function banto_site_plan()\nreturns text\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce((select settings->>'workers_plan' from banto_site_settings where id), 'free');\n$$;\n\n-- workers_plan は service_role と JWT の無い直接の SQL からも書ける（0052 の site_settings_set を差し替え）。\n-- ホスティングの提供者が払い出しのときに有料の枠（paid）を置けるように。組織の owner / admin は今までどおり書ける。\n-- plan_limits は今までどおり service_role と直接の SQL だけ\ncreate or replace function site_settings_set(p_key text, p_value jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_out jsonb;\n  v_role text := auth.role();\n  v_platform boolean := v_role is null or v_role = 'service_role';\nbegin\n  if p_key = 'plan_limits' then\n    -- service_role（ホスティングの提供者・Worker の特権経路）か、JWT の無い直接の SQL（SQL エディタ・Management API）だけ\n    if not v_platform then raise exception 'forbidden' using errcode = '42501'; end if;\n    if not banto_plan_limits_valid(p_value) then raise exception 'invalid_value'; end if;\n  else\n    if not v_platform and not exists (select 1 from org_members m where m.user_id = auth.uid() and m.role in ('owner', 'admin')) then\n      raise exception 'forbidden' using errcode = '42501';\n    end if;\n    case p_key\n      when 'workers_plan' then\n        if p_value is null or jsonb_typeof(p_value) <> 'string' or p_value #>> '{}' not in ('free', 'paid') then raise exception 'invalid_value'; end if;\n      else raise exception 'invalid_key';\n    end case;\n  end if;\n  update banto_site_settings set settings = settings || jsonb_build_object(p_key, p_value), updated_at = now() where id\n  returning settings into v_out;\n  return v_out;\nend;\n$$;\nrevoke execute on function site_settings_set(text, jsonb) from public, anon;\ngrant execute on function site_settings_set(text, jsonb) to authenticated, service_role;\n\nrevoke execute on function product_public_count(uuid) from public;\ngrant execute on function product_public_count(uuid) to anon, authenticated, service_role;\nrevoke execute on function product_public_slugs(uuid, integer, integer) from public;\ngrant execute on function product_public_slugs(uuid, integer, integer) to anon, authenticated, service_role;\nrevoke execute on function product_feed_page(uuid, uuid, integer) from public;\ngrant execute on function product_feed_page(uuid, uuid, integer) to anon, authenticated, service_role;\nrevoke execute on function banto_site_plan() from public;\ngrant execute on function banto_site_plan() to anon, authenticated, service_role;\n\ninsert into banto_migrations (version) values ('0060_catalog_pages');\n" },
  { version: "0061_mod_inquiries", sql: "-- Banto 0061_mod_inquiries: 同梱モジュール「お問い合わせ」（inquiries、既定 OFF。docs/inquiries.md、docs/knowledge/14-inquiries.md）。前方専用。\n--\n-- お客様のお問い合わせをチケットにし、運営者とのやり取りを Banto の中で続ける（人間の決定 2026-10-27）。\n--  - メールはお知らせとチケットへのリンクだけ。本文は載せない。メールへの返信は受けない（受信の仕組みを持たない）\n--  - ログインしていない人・注文に結ばない問い合わせも受ける。ゲストはアドレスに届いたリンクを押した時点で「確認済み」\n--  - 注文に結ぶのは、会員の自分の注文・注文時のアドレス（注文から問い合わせた）・注文番号とメールアドレスが合ったときだけ。\n--    合わなければ「申告された注文番号」の文字として残す。会員に結ぶのは、確認済みで会員のアドレスと一致したときだけ\n--  - 送った人には「会員か」「どちらが違ったか」を返さない\n--  - 運営側の権限は新しい項目 support（組織のメンバーのショップごとの項目）\n--\n-- 表（書くのは下の関数だけ。運営側は support の項目で読む。お客様の経路は service_role の関数だけ）:\n--   inquiries         … チケット 1 件。連絡先は個人情報（終わったものは mask_inquiries で消す。未確認のまま 30 日で消す）\n--   inquiry_messages  … やり取り（お客様 / 運営者）。本文はテキスト（HTML は描画しない）\n--   inquiry_links     … チケットを開くリンクのトークン（Worker が HMAC にしたものだけ。30 日）\n--   inquiry_mails     … 送ったメールの記録（回数の制限と、プランの 1 日のメールの上限 0053 に数える。宛先は SHA-256 だけ）\n--   inquiry_checks    … 「注文を確かめる」「リンクを送り直す」の試行（回数の制限。メールアドレスは Worker の HMAC だけ）\n-- hooks: inquiry.created（アドレスが確認されたとき）・inquiry.updated（やり取り・状態）。ペイロードに個人情報は載せない\n-- AI 用トークン: inquiries:read / inquiries:write（→ support の項目）。連絡先は orders:pii もあるときだけ（下の api_inquiry_*）\n-- バックアップ: 書き出しは RLS の経路（運営者の JWT）、復元は restore_inquiries（注文番号・メールアドレスで結び直す）\n\nalter table shops add column if not exists inquiry_seq integer not null default 0;\n\n-- ---------- 権限の項目に support を足す（0024） ----------\ncreate or replace function banto_shop_perms_all()\nreturns text[]\nlanguage sql\nimmutable\nas $$ select array['catalog', 'orders', 'orders_cancel', 'customers', 'marketing', 'reports', 'stores', 'settings', 'integrations', 'support'] $$;\n\nalter table org_member_shops drop constraint if exists org_member_shops_perms_check;\nalter table org_member_shops add constraint org_member_shops_perms_check\n  check (perms <@ array['catalog', 'orders', 'orders_cancel', 'customers', 'marketing', 'reports', 'stores', 'settings', 'integrations', 'support']);\n\n-- ---------- 表 ----------\ncreate table inquiries (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  number integer not null,\n  category text not null check (category in ('product', 'order', 'account', 'other')),\n  -- waiting_shop = 運営者の返事待ち、waiting_customer = お客様の返事待ち、closed = 完了\n  status text not null default 'waiting_shop' check (status in ('waiting_shop', 'waiting_customer', 'closed')),\n  -- どこから来たか: form = フォーム（ゲスト）、member = ログイン中の会員、order = 注文照会の結果・会員の注文、checkout = 購入完了の画面\n  origin text not null check (origin in ('form', 'member', 'order', 'checkout')),\n  contact_email text check (contact_email is null or length(contact_email) between 3 and 254),\n  contact_name text check (contact_name is null or length(contact_name) <= 100),\n  email_verified_at timestamptz,\n  customer_id uuid,\n  order_id uuid references orders(id) on delete set null,\n  claimed_order_number integer check (claimed_order_number is null or claimed_order_number > 0),\n  ip_hash text check (ip_hash ~ '^[0-9a-f]{64}$'),\n  -- ヘッドレスの連携サイトのチケットの画面（Worker が return_origins の許可リストで確かめたもの）。メールのリンクの行き先\n  return_to text check (return_to is null or length(return_to) <= 500),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  last_message_at timestamptz not null default now(),\n  closed_at timestamptz,\n  masked_at timestamptz,\n  foreign key (shop_id, customer_id) references customers(shop_id, id) on delete set null (customer_id)\n);\ncreate unique index inquiries_number on inquiries(shop_id, number);\ncreate index on inquiries(shop_id, status, last_message_at desc);\ncreate index on inquiries(shop_id, lower(contact_email));\ncreate index on inquiries(shop_id, customer_id) where customer_id is not null;\ncreate index on inquiries(shop_id, ip_hash, created_at) where ip_hash is not null;\nalter table inquiries enable row level security;\ncreate policy inquiries_select on inquiries for select using (banto_shop_perm(shop_id, 'support'));\n\ncreate table inquiry_messages (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  inquiry_id uuid not null references inquiries(id) on delete cascade,\n  author text not null check (author in ('customer', 'shop')),\n  -- 返信した運営側の人（表示はしない。誰が返したかの記録）\n  author_user uuid references auth.users(id) on delete set null,\n  body text not null check (length(body) between 1 and 5000),\n  created_at timestamptz not null default now()\n);\ncreate index on inquiry_messages(inquiry_id, created_at);\nalter table inquiry_messages enable row level security;\ncreate policy inquiry_messages_select on inquiry_messages for select using (banto_shop_perm(shop_id, 'support'));\n\ncreate table inquiry_links (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  inquiry_id uuid not null references inquiries(id) on delete cascade,\n  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),\n  created_at timestamptz not null default now(),\n  expires_at timestamptz not null\n);\ncreate index on inquiry_links(inquiry_id);\nalter table inquiry_links enable row level security;\ncreate policy inquiry_links_none on inquiry_links for select using (false);\n\ncreate table inquiry_mails (\n  id bigserial primary key,\n  shop_id uuid not null references shops(id) on delete cascade,\n  inquiry_id uuid references inquiries(id) on delete set null,\n  -- verify = 確認のリンク、created = 受け付けた（確認済みの人）、reply = 運営者の返事、link = リンクの送り直し、shop = 運営者へのお知らせ\n  kind text not null check (kind in ('verify', 'created', 'reply', 'link', 'shop')),\n  to_hash text check (to_hash ~ '^[0-9a-f]{64}$'),\n  created_at timestamptz not null default now()\n);\ncreate index on inquiry_mails(shop_id, created_at);\ncreate index on inquiry_mails(shop_id, to_hash, created_at);\ncreate index on inquiry_mails(created_at);\nalter table inquiry_mails enable row level security;\ncreate policy inquiry_mails_none on inquiry_mails for select using (false);\n\ncreate table inquiry_checks (\n  id bigserial primary key,\n  shop_id uuid not null references shops(id) on delete cascade,\n  ip_hash text check (ip_hash ~ '^[0-9a-f]{64}$'),\n  email_hash text check (email_hash ~ '^[0-9a-f]{64}$'),\n  created_at timestamptz not null default now()\n);\ncreate index on inquiry_checks(shop_id, ip_hash, created_at);\ncreate index on inquiry_checks(shop_id, email_hash, created_at);\nalter table inquiry_checks enable row level security;\ncreate policy inquiry_checks_none on inquiry_checks for select using (false);\n\n-- 添付ファイル（人間の決定 2026-10-27）。実体は公開しないバケット（StorageAdapter の privateStorage）に置き、ここには鍵と形だけ。\n-- 配るのは Worker が権限を確かめてからだけ（inquiry_attachment_get / inquiry_attachment_admin_get）。行を消すと、実体を消す待ち行列に積む\ncreate table inquiry_attachments (\n  id uuid primary key default gen_random_uuid(),\n  shop_id uuid not null references shops(id) on delete cascade,\n  inquiry_id uuid not null references inquiries(id) on delete cascade,\n  message_id uuid not null references inquiry_messages(id) on delete cascade,\n  storage_key text not null unique check (storage_key ~ '^inq/[0-9a-f-]{36}/[A-Za-z0-9_-]{20,100}$'),\n  filename text not null check (length(filename) between 1 and 100),\n  content_type text not null check (content_type in ('image/jpeg', 'image/png', 'image/webp', 'application/pdf')),\n  size integer not null check (size between 1 and 5242880),\n  -- 1 通の中の順番（送った順。同じ取引の中では created_at が同じになるため）\n  position smallint not null default 0 check (position between 0 and 2),\n  created_at timestamptz not null default now()\n);\ncreate index on inquiry_attachments(message_id);\ncreate index on inquiry_attachments(inquiry_id);\nalter table inquiry_attachments enable row level security;\ncreate policy inquiry_attachments_select on inquiry_attachments for select using (banto_shop_perm(shop_id, 'support'));\n\n-- 実体（オブジェクト）を消す待ち行列。Cron が privateStorage から消して行を消す（ショップを消しても実体は消す）\ncreate table inquiry_attachment_trash (\n  storage_key text primary key,\n  created_at timestamptz not null default now(),\n  claimed_at timestamptz\n);\nalter table inquiry_attachment_trash enable row level security;\ncreate policy inquiry_attachment_trash_none on inquiry_attachment_trash for select using (false);\n\ncreate or replace function banto_inquiry_attachment_trash()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  insert into inquiry_attachment_trash (storage_key) values (old.storage_key) on conflict (storage_key) do nothing;\n  return old;\nend;\n$$;\nrevoke execute on function banto_inquiry_attachment_trash() from public, anon, authenticated;\ndrop trigger if exists inquiry_attachments_trash on inquiry_attachments;\ncreate trigger inquiry_attachments_trash after delete on inquiry_attachments for each row execute function banto_inquiry_attachment_trash();\n\nrevoke all on inquiries, inquiry_messages, inquiry_links, inquiry_mails, inquiry_checks, inquiry_attachments, inquiry_attachment_trash from anon;\nrevoke insert, update, delete on inquiries, inquiry_messages, inquiry_links, inquiry_mails, inquiry_checks, inquiry_attachments, inquiry_attachment_trash from authenticated;\n\n-- ---------- 部品（関数の中からだけ使う） ----------\ncreate or replace function banto_inquiries_on(p_shop_id uuid)\nreturns boolean language sql stable security definer set search_path = public as $$\n  select exists (select 1 from shops where id = p_shop_id and published and coalesce(settings->'modules'->>'inquiries', 'false') = 'true');\n$$;\n\n-- 送信元（会員のログインのメールと同じ。同梱のメール通知プラグインの「送信元」）\ncreate or replace function banto_inquiry_mail_from(p_shop_id uuid)\nreturns text language sql stable security definer set search_path = public as $$\n  select nullif(btrim(e.settings->>'from'), '') from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and e.url = 'https://banto.invalid/plugins/email_resend'\n   limit 1;\n$$;\n\n-- 運営者へのお知らせの宛先（モジュールの設定 → ショップの問い合わせ先）\ncreate or replace function banto_inquiry_notify_to(p_shop_id uuid)\nreturns text language sql stable security definer set search_path = public as $$\n  select coalesce(nullif(btrim(settings->'inquiries'->>'notify_email'), ''), nullif(btrim(settings->>'contact_email'), '')) from shops where id = p_shop_id;\n$$;\n\ncreate or replace function banto_inquiry_to_hash(p_email text)\nreturns text language sql immutable as $$\n  select encode(sha256(convert_to(lower(btrim(coalesce(p_email, ''))), 'UTF8')), 'hex');\n$$;\n\ncreate or replace function banto_enqueue_inquiry_hook(p_shop_id uuid, p_event text, p_payload jsonb)\nreturns void language sql security definer set search_path = public as $$\n  insert into hook_deliveries (shop_id, endpoint_id, event, payload)\n  select e.shop_id, e.id, p_event, coalesce(p_payload, '{}'::jsonb)\n    from hook_endpoints e\n   where e.shop_id = p_shop_id and e.enabled and p_event = any(e.events);\n$$;\n\n-- メールを 1 通送ってよいか。よければ記録して true（Worker が送る）。上限を超えたら false（送らないだけ。応答の形は変えない）\n--   お客様が増やせるもの（verify / link）: 同じ宛先に 1 時間 5 通・1 日 20 通\n--   運営者へのお知らせ（shop）: ショップで 1 時間 settings.inquiries.shop_notices_per_hour（既定 60）\n--   ショップ全体: 1 日 settings.inquiries.mails_per_day（既定 500）。デプロイ全体の上限は plan_limits.mail_per_day（0053、トリガー）\ncreate or replace function banto_inquiry_issue_mail(p_shop_id uuid, p_inquiry_id uuid, p_kind text, p_to text)\nreturns boolean language plpgsql security definer set search_path = public as $$\ndeclare v_to text;\nbegin\n  if p_to is null or position('@' in p_to) < 2 then return false; end if;\n  v_to := banto_inquiry_to_hash(p_to);\n  perform pg_advisory_xact_lock(hashtextextended('inquiry_mail|' || p_shop_id::text || '|' || v_to, 0));\n  if p_kind in ('verify', 'link') and (\n       (select count(*) from inquiry_mails where shop_id = p_shop_id and to_hash = v_to and kind in ('verify', 'link') and created_at > now() - interval '1 hour') >= 5\n       or (select count(*) from inquiry_mails where shop_id = p_shop_id and to_hash = v_to and kind in ('verify', 'link') and created_at > now() - interval '1 day') >= 20) then\n    return false;\n  end if;\n  if p_kind = 'shop' and (select count(*) from inquiry_mails where shop_id = p_shop_id and kind = 'shop' and created_at > now() - interval '1 hour')\n       >= banto_shop_limit(p_shop_id, 'inquiries', 'shop_notices_per_hour', 60) then\n    return false;\n  end if;\n  if (select count(*) from inquiry_mails where shop_id = p_shop_id and created_at > now() - interval '1 day')\n       >= banto_shop_limit(p_shop_id, 'inquiries', 'mails_per_day', 500) then\n    return false;\n  end if;\n  insert into inquiry_mails (shop_id, inquiry_id, kind, to_hash) values (p_shop_id, p_inquiry_id, p_kind, v_to);\n  return true;\nend;\n$$;\n\n-- 添付の行を作る（返事の関数から。Worker が privateStorage に置いた後）。1 通 3 個・1 件のチケットで 20 個まで。\n-- p_files: [{ key, filename, content_type, size }]。鍵はそのショップの接頭辞（inq/<shop_id>/）だけ\ncreate or replace function banto_inquiry_attach(p_shop_id uuid, p_inquiry_id uuid, p_message_id uuid, p_files jsonb)\nreturns integer language plpgsql security definer set search_path = public as $$\ndeclare v_f jsonb; v_n integer := 0;\nbegin\n  if p_files is null or jsonb_typeof(p_files) <> 'array' or jsonb_array_length(p_files) = 0 then return 0; end if;\n  if jsonb_array_length(p_files) > 3 then raise exception 'too_many_attachments'; end if;\n  if (select count(*) from inquiry_attachments where inquiry_id = p_inquiry_id) + jsonb_array_length(p_files) > 20 then raise exception 'too_many_attachments'; end if;\n  for v_f in select * from jsonb_array_elements(p_files) loop\n    if coalesce(v_f->>'key', '') not like 'inq/' || p_shop_id::text || '/%' then raise exception 'invalid_attachment'; end if;\n    if coalesce(v_f->>'size', '') !~ '^[0-9]{1,8}$' then raise exception 'invalid_attachment'; end if;\n    insert into inquiry_attachments (shop_id, inquiry_id, message_id, storage_key, filename, content_type, size, position)\n    values (p_shop_id, p_inquiry_id, p_message_id, v_f->>'key', left(coalesce(nullif(btrim(v_f->>'filename'), ''), 'file'), 100), v_f->>'content_type', (v_f->>'size')::integer, v_n);\n    v_n := v_n + 1;\n  end loop;\n  return v_n;\nexception when check_violation or unique_violation then\n  raise exception 'invalid_attachment';\nend;\n$$;\n\ncreate or replace function banto_inquiry_message_attachments(p_message_id uuid, p_filename boolean)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'content_type', a.content_type, 'size', a.size)\n                            || case when p_filename then jsonb_build_object('filename', a.filename) else '{}'::jsonb end order by a.position), '[]'::jsonb)\n    from inquiry_attachments a where a.message_id = p_message_id;\n$$;\n\n-- お客様に見せるチケット（連絡先・運営者の名前・IP は出さない）\ncreate or replace function banto_inquiry_view(p_id uuid)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select jsonb_build_object(\n    'id', i.id, 'number', i.number, 'status', i.status, 'category', i.category, 'created_at', i.created_at,\n    'last_message_at', i.last_message_at, 'verified', i.email_verified_at is not null, 'claimed_order_number', i.claimed_order_number,\n    'order', (select jsonb_build_object('number', o.number, 'status', o.status, 'created_at', o.created_at, 'total_jpy', o.total_jpy)\n                from orders o where o.id = i.order_id and o.shop_id = i.shop_id),\n    'messages', coalesce((select jsonb_agg(jsonb_build_object('author', m.author, 'body', m.body, 'created_at', m.created_at,\n                                                               'attachments', banto_inquiry_message_attachments(m.id, true)) order by m.created_at, m.id)\n                            from inquiry_messages m where m.inquiry_id = i.id), '[]'::jsonb))\n    from inquiries i where i.id = p_id;\n$$;\n\n-- 注文の要約（「注文を確かめる」・確認画面。住所・連絡先は出さない）\ncreate or replace function banto_inquiry_order_summary(p_order_id uuid)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select jsonb_build_object('number', o.number, 'status', o.status, 'created_at', o.created_at, 'total_jpy', o.total_jpy,\n    'items', (select coalesce(jsonb_agg(jsonb_build_object('name', coalesce(oi.item_name, p.name), 'qty', oi.qty) order by oi.id), '[]'::jsonb)\n                from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = o.id))\n    from orders o where o.id = p_order_id;\n$$;\n\n-- 試行の回数（注文を確かめる・リンクの送り直し）: 同じ IP から 1 時間 20 回、同じアドレスに 1 時間 10 回\ncreate or replace function banto_inquiry_check_limit(p_shop_id uuid, p_ip_hash text, p_email_hash text)\nreturns void language plpgsql security definer set search_path = public as $$\ndeclare v_ip text := case when p_ip_hash ~ '^[0-9a-f]{64}$' then p_ip_hash end;\n        v_em text := case when p_email_hash ~ '^[0-9a-f]{64}$' then p_email_hash end;\nbegin\n  if v_ip is not null and (select count(*) from inquiry_checks where shop_id = p_shop_id and ip_hash = v_ip and created_at > now() - interval '1 hour')\n       >= banto_shop_limit(p_shop_id, 'inquiries', 'checks_per_ip_per_hour', 20) then\n    raise exception 'too_many_requests' using detail = 'ip';\n  end if;\n  if v_em is not null and (select count(*) from inquiry_checks where shop_id = p_shop_id and email_hash = v_em and created_at > now() - interval '1 hour') >= 10 then\n    raise exception 'too_many_requests' using detail = 'email';\n  end if;\n  insert into inquiry_checks (shop_id, ip_hash, email_hash) values (p_shop_id, v_ip, v_em);\nend;\n$$;\n\n-- アドレスが確かめられた: 会員に結び（一致するときだけ）、hooks と運営者へのお知らせ\ncreate or replace function banto_inquiry_verified(p_id uuid)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_i inquiries%rowtype; v_send boolean; v_to text;\nbegin\n  select * into v_i from inquiries where id = p_id;\n  if v_i.customer_id is null and v_i.contact_email is not null then\n    update inquiries set customer_id = (select c.id from customers c where c.shop_id = v_i.shop_id and lower(c.email) = lower(v_i.contact_email) limit 1)\n     where id = p_id;\n  end if;\n  perform banto_enqueue_inquiry_hook(v_i.shop_id, 'inquiry.created',\n    jsonb_build_object('inquiry_id', v_i.id, 'number', v_i.number, 'shop_id', v_i.shop_id, 'category', v_i.category, 'status', v_i.status,\n                       'customer_id', (select customer_id from inquiries where id = p_id), 'order_id', v_i.order_id));\n  v_to := banto_inquiry_notify_to(v_i.shop_id);\n  v_send := banto_inquiry_issue_mail(v_i.shop_id, v_i.id, 'shop', v_to);\n  return jsonb_build_object('send', v_send, 'to', case when v_send then v_to end);\nend;\n$$;\n\n-- 会員のアクセス・リンクのアクセスからチケットを引く（どちらも合わなければ null）\n-- p_access: { link_hash } | { customer_id, epoch, number }\ncreate or replace function banto_inquiry_access(p_shop_id uuid, p_access jsonb)\nreturns uuid language plpgsql stable security definer set search_path = public as $$\ndeclare v_id uuid;\nbegin\n  if p_access ? 'link_hash' then\n    select l.inquiry_id into v_id from inquiry_links l join inquiries i on i.id = l.inquiry_id\n     where l.shop_id = p_shop_id and l.token_hash = p_access->>'link_hash' and l.expires_at > now() and i.masked_at is null;\n    return v_id;\n  end if;\n  if coalesce(p_access->>'number', '') !~ '^[0-9]{1,9}$' or coalesce(p_access->>'epoch', '') !~ '^-?[0-9]{1,9}$' then return null; end if;\n  select i.id into v_id from inquiries i join customers c on c.shop_id = i.shop_id and c.id = i.customer_id\n   where i.shop_id = p_shop_id and i.number = (p_access->>'number')::integer and c.id = nullif(p_access->>'customer_id', '')::uuid\n     and c.session_epoch = (p_access->>'epoch')::integer and i.email_verified_at is not null and i.masked_at is null;\n  return v_id;\nend;\n$$;\n\nrevoke execute on function banto_inquiries_on(uuid) from public, anon, authenticated;\nrevoke execute on function banto_inquiry_mail_from(uuid) from public, anon, authenticated;\nrevoke execute on function banto_inquiry_notify_to(uuid) from public, anon, authenticated;\nrevoke execute on function banto_inquiry_to_hash(text) from public, anon, authenticated;\nrevoke execute on function banto_enqueue_inquiry_hook(uuid, text, jsonb) from public, anon, authenticated, service_role;\nrevoke execute on function banto_inquiry_issue_mail(uuid, uuid, text, text) from public, anon, authenticated, service_role;\nrevoke execute on function banto_inquiry_view(uuid) from public, anon, authenticated, service_role;\nrevoke execute on function banto_inquiry_order_summary(uuid) from public, anon, authenticated, service_role;\nrevoke execute on function banto_inquiry_check_limit(uuid, text, text) from public, anon, authenticated, service_role;\nrevoke execute on function banto_inquiry_verified(uuid) from public, anon, authenticated, service_role;\nrevoke execute on function banto_inquiry_access(uuid, jsonb) from public, anon, authenticated, service_role;\n\n-- ---------- お客様の経路（service_role。同梱テーマとヘッドレス API から） ----------\n\n-- 注文を確かめる（ゲスト）: 注文番号とメールアドレスが合えば要約。合わなければ null（どちらが違うかは返さない）\ncreate or replace function inquiry_order_check(p_shop_id uuid, p_number integer, p_email text, p_ip_hash text, p_email_hash text)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_order uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'inquiry_order_check: service_role only' using errcode = '42501';\n  end if;\n  if not banto_inquiries_on(p_shop_id) then raise exception 'inquiries_disabled'; end if;\n  perform banto_inquiry_check_limit(p_shop_id, p_ip_hash, p_email_hash);\n  select o.id into v_order from orders o\n   where o.shop_id = p_shop_id and o.number = p_number and o.customer_email is not null and lower(o.customer_email) = lower(btrim(coalesce(p_email, '')));\n  if v_order is null then return null; end if;\n  return banto_inquiry_order_summary(v_order);\nend;\n$$;\n\n-- 注文 1 件の要約（会員の自分の注文・注文から問い合わせる画面。注文 ID か予約の quote で引く）。合わなければ null\n-- p_ref: { order_id } | { quote_id } | { number, email }（注文照会で合った組を Worker が署名したもの）| { customer_id, epoch, number }\ncreate or replace function inquiry_order_ref(p_shop_id uuid, p_ref jsonb)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\ndeclare v_order uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'inquiry_order_ref: service_role only' using errcode = '42501';\n  end if;\n  if p_ref ? 'quote_id' then\n    select o.id into v_order from reservations r join orders o on o.reservation_id = r.id\n     where r.shop_id = p_shop_id and r.quote_id = p_ref->>'quote_id' order by r.created_at desc limit 1;\n  elsif p_ref ? 'order_id' then\n    select o.id into v_order from orders o where o.shop_id = p_shop_id and o.id = nullif(p_ref->>'order_id', '')::uuid;\n  elsif p_ref ? 'email' and coalesce(p_ref->>'number', '') ~ '^[0-9]{1,9}$' then\n    select o.id into v_order from orders o\n     where o.shop_id = p_shop_id and o.number = (p_ref->>'number')::integer and o.customer_email is not null and lower(o.customer_email) = lower(btrim(p_ref->>'email'));\n  elsif coalesce(p_ref->>'number', '') ~ '^[0-9]{1,9}$' and coalesce(p_ref->>'epoch', '') ~ '^-?[0-9]{1,9}$' then\n    select o.id into v_order from orders o join customers c on c.shop_id = o.shop_id and c.id = o.customer_id\n     where o.shop_id = p_shop_id and o.number = (p_ref->>'number')::integer and c.id = nullif(p_ref->>'customer_id', '')::uuid and c.session_epoch = (p_ref->>'epoch')::integer;\n  end if;\n  if v_order is null then return null; end if;\n  return banto_inquiry_order_summary(v_order) || jsonb_build_object('order_id', v_order);\nend;\n$$;\n\n-- 送る。p_input:\n--   { category, body, name, basis, email?, customer_id?, epoch?, order_id?, quote_id?, order_number?, return_to? }\n--   basis = form（ゲスト。email を確かめるリンクを送る）/ member（ログイン中の会員。customer_id・epoch）/\n--           order（注文 ID。Worker が署名を確かめた注文トークンから）/ checkout（決済の状態トークンの quote_id）\n--   order / checkout は注文時のアドレスに返す（画面には出さない）\n-- 戻り値: { id, number, verified, to, mail_from, send, kind, notify: { send, to } }\ncreate or replace function inquiry_create(p_shop_id uuid, p_input jsonb, p_link_hash text, p_ip_hash text)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare\n  v_basis text := coalesce(p_input->>'basis', '');\n  v_category text := coalesce(p_input->>'category', '');\n  v_body text := left(btrim(coalesce(p_input->>'body', '')), 5000);\n  v_name text := left(nullif(btrim(coalesce(p_input->>'name', '')), ''), 100);\n  v_ip text := case when p_ip_hash ~ '^[0-9a-f]{64}$' then p_ip_hash end;\n  v_from text; v_email text; v_cid uuid; v_order uuid; v_claimed integer; v_verified boolean := false; v_origin text;\n  v_c customers%rowtype; v_o orders%rowtype; v_id uuid; v_number integer; v_kind text; v_send boolean; v_notify jsonb := null;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'inquiry_create: service_role only' using errcode = '42501';\n  end if;\n  if not banto_inquiries_on(p_shop_id) then raise exception 'inquiries_disabled'; end if;\n  v_from := banto_inquiry_mail_from(p_shop_id);\n  if v_from is null then raise exception 'mail_not_configured'; end if;\n  if v_category not in ('product', 'order', 'account', 'other') then raise exception 'invalid_category'; end if;\n  if length(v_body) = 0 then raise exception 'invalid_body'; end if;\n  if coalesce(p_link_hash, '') !~ '^[0-9a-f]{64}$' then raise exception 'invalid_link'; end if;\n  if coalesce(p_input->>'order_number', '') ~ '^[0-9]{1,9}$' then v_claimed := nullif((p_input->>'order_number')::integer, 0); end if;\n\n  -- 同じ IP から 1 時間・ショップ全体で 1 時間の上限\n  if v_ip is not null and (select count(*) from inquiries where shop_id = p_shop_id and ip_hash = v_ip and created_at > now() - interval '1 hour')\n       >= banto_shop_limit(p_shop_id, 'inquiries', 'per_ip_per_hour', 10) then\n    raise exception 'too_many_requests' using detail = 'ip';\n  end if;\n  if (select count(*) from inquiries where shop_id = p_shop_id and created_at > now() - interval '1 hour')\n       >= banto_shop_limit(p_shop_id, 'inquiries', 'per_hour', 100) then\n    raise exception 'too_many_requests' using detail = 'shop';\n  end if;\n\n  if v_basis = 'member' then\n    if coalesce(p_input->>'epoch', '') !~ '^-?[0-9]{1,9}$' then raise exception 'invalid_member'; end if;\n    select * into v_c from customers where shop_id = p_shop_id and id = nullif(p_input->>'customer_id', '')::uuid\n       and session_epoch = (p_input->>'epoch')::integer;\n    if not found or v_c.email is null then raise exception 'invalid_member'; end if;\n    v_email := lower(v_c.email); v_cid := v_c.id; v_verified := true; v_origin := 'member';\n    if v_claimed is not null then\n      select id into v_order from orders where shop_id = p_shop_id and number = v_claimed and customer_id = v_cid;\n    end if;\n  elsif v_basis in ('order', 'checkout') then\n    if v_basis = 'order' then\n      select * into v_o from orders where shop_id = p_shop_id and id = nullif(p_input->>'order_id', '')::uuid;\n    else\n      select o.* into v_o from reservations r join orders o on o.reservation_id = r.id\n       where r.shop_id = p_shop_id and r.quote_id = coalesce(p_input->>'quote_id', '') order by r.created_at desc limit 1;\n    end if;\n    if not found then raise exception 'order_not_found'; end if;\n    if v_o.customer_email is null then raise exception 'order_unavailable'; end if;\n    v_email := lower(v_o.customer_email); v_cid := v_o.customer_id; v_order := v_o.id; v_verified := true; v_origin := v_basis;\n    v_claimed := null;\n  elsif v_basis = 'form' then\n    v_email := lower(btrim(coalesce(p_input->>'email', '')));\n    if length(v_email) > 254 or v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then raise exception 'invalid_email'; end if;\n    v_origin := 'form';\n    -- 注文番号とメールアドレスが合えば注文に結ぶ（注文照会と同じ判定）。会員には、アドレスが確かめられるまで結ばない\n    if v_claimed is not null then\n      select id into v_order from orders where shop_id = p_shop_id and number = v_claimed and customer_email is not null and lower(customer_email) = v_email;\n    end if;\n  else\n    raise exception 'invalid_basis';\n  end if;\n  if v_order is not null then v_claimed := null; end if;\n\n  -- 同じアドレスの開いているチケットの上限\n  perform pg_advisory_xact_lock(hashtextextended('inquiry|' || p_shop_id::text || '|' || v_email, 0));\n  if (select count(*) from inquiries where shop_id = p_shop_id and lower(contact_email) = v_email and status <> 'closed')\n       >= banto_shop_limit(p_shop_id, 'inquiries', 'max_open_per_email', 5) then\n    raise exception 'too_many_requests' using detail = 'email';\n  end if;\n\n  update shops set inquiry_seq = inquiry_seq + 1 where id = p_shop_id returning inquiry_seq into v_number;\n  insert into inquiries (shop_id, number, category, origin, contact_email, contact_name, email_verified_at, customer_id, order_id, claimed_order_number, ip_hash, return_to)\n  values (p_shop_id, v_number, v_category, v_origin, v_email, coalesce(v_name, v_c.name), case when v_verified then now() end, v_cid, v_order, v_claimed, v_ip,\n          left(nullif(btrim(coalesce(p_input->>'return_to', '')), ''), 500))\n  returning id into v_id;\n  insert into inquiry_messages (shop_id, inquiry_id, author, body) values (p_shop_id, v_id, 'customer', v_body);\n  insert into inquiry_links (shop_id, inquiry_id, token_hash, expires_at) values (p_shop_id, v_id, p_link_hash, now() + interval '30 days');\n\n  v_kind := case when v_verified then 'created' else 'verify' end;\n  v_send := banto_inquiry_issue_mail(p_shop_id, v_id, v_kind, v_email);\n  if v_verified then v_notify := banto_inquiry_verified(v_id); end if;\n  return jsonb_build_object('id', v_id, 'number', v_number, 'verified', v_verified, 'to', v_email, 'mail_from', v_from, 'send', v_send, 'kind', v_kind, 'notify', v_notify);\nend;\n$$;\n\n-- リンクの確認画面（使わない）: 有効なリンクならチケットの番号\ncreate or replace function inquiry_peek(p_shop_id uuid, p_link_hash text)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\ndeclare v_id uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'inquiry_peek: service_role only' using errcode = '42501';\n  end if;\n  v_id := banto_inquiry_access(p_shop_id, jsonb_build_object('link_hash', coalesce(p_link_hash, '')));\n  if v_id is null then return null; end if;\n  return (select jsonb_build_object('number', number) from inquiries where id = v_id);\nend;\n$$;\n\n-- チケットを開く。リンクで初めて開いたら、アドレスを確認済みにする（会員に結ぶ・hooks・運営者へのお知らせ）\n-- 戻り値: { inquiry, notify: { send, to } | null, mail_from } か null\ncreate or replace function inquiry_get(p_shop_id uuid, p_access jsonb)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_id uuid; v_notify jsonb := null; v_verified timestamptz;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'inquiry_get: service_role only' using errcode = '42501';\n  end if;\n  v_id := banto_inquiry_access(p_shop_id, coalesce(p_access, '{}'::jsonb));\n  if v_id is null then return null; end if;\n  select email_verified_at into v_verified from inquiries where id = v_id for update;\n  if v_verified is null then\n    update inquiries set email_verified_at = now(), updated_at = now() where id = v_id;\n    v_notify := banto_inquiry_verified(v_id);\n  end if;\n  return jsonb_build_object('inquiry', banto_inquiry_view(v_id), 'notify', v_notify, 'mail_from', banto_inquiry_mail_from(p_shop_id));\nend;\n$$;\n\n-- 会員の問い合わせの一覧（確認済みのものだけ）\ncreate or replace function inquiry_member_list(p_shop_id uuid, p_customer_id uuid, p_epoch integer)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'inquiry_member_list: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then return null; end if;\n  return coalesce((\n    select jsonb_agg(x order by x.last_message_at desc) from (\n      select i.number, i.status, i.category, i.created_at, i.last_message_at, (select o.number from orders o where o.id = i.order_id) as order_number\n        from inquiries i\n       where i.shop_id = p_shop_id and i.customer_id = p_customer_id and i.email_verified_at is not null and i.masked_at is null\n       order by i.last_message_at desc limit 50) x), '[]'::jsonb);\nend;\n$$;\n\n-- お客様が続きを書く。完了したチケットには書けない（新しく問い合わせてもらう）\n-- 戻り値: { id, number, notify: { send, to }, mail_from }\ncreate or replace function inquiry_customer_reply(p_shop_id uuid, p_access jsonb, p_body text, p_ip_hash text, p_attachments jsonb default '[]'::jsonb)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_id uuid; v_i inquiries%rowtype; v_body text := left(btrim(coalesce(p_body, '')), 5000); v_send boolean; v_to text; v_msg uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'inquiry_customer_reply: service_role only' using errcode = '42501';\n  end if;\n  if not banto_inquiries_on(p_shop_id) then raise exception 'inquiries_disabled'; end if;\n  v_id := banto_inquiry_access(p_shop_id, coalesce(p_access, '{}'::jsonb));\n  if v_id is null then raise exception 'inquiry_not_found'; end if;\n  select * into v_i from inquiries where id = v_id for update;\n  if v_i.email_verified_at is null then raise exception 'inquiry_not_found'; end if;\n  if v_i.status = 'closed' then raise exception 'inquiry_closed'; end if;\n  if length(v_body) = 0 then raise exception 'invalid_body'; end if;\n  if (select count(*) from inquiry_messages where inquiry_id = v_id and author = 'customer' and created_at > now() - interval '1 hour') >= 10 then\n    raise exception 'too_many_requests' using detail = 'inquiry';\n  end if;\n  insert into inquiry_messages (shop_id, inquiry_id, author, body) values (p_shop_id, v_id, 'customer', v_body) returning id into v_msg;\n  perform banto_inquiry_attach(p_shop_id, v_id, v_msg, p_attachments);\n  update inquiries set status = 'waiting_shop', last_message_at = now(), updated_at = now() where id = v_id;\n  perform banto_enqueue_inquiry_hook(p_shop_id, 'inquiry.updated',\n    jsonb_build_object('inquiry_id', v_id, 'number', v_i.number, 'shop_id', p_shop_id, 'status', 'waiting_shop', 'change', 'message', 'author', 'customer'));\n  v_to := banto_inquiry_notify_to(p_shop_id);\n  v_send := banto_inquiry_issue_mail(p_shop_id, v_id, 'shop', v_to);\n  return jsonb_build_object('id', v_id, 'number', v_i.number, 'notify', jsonb_build_object('send', v_send, 'to', case when v_send then v_to end), 'mail_from', banto_inquiry_mail_from(p_shop_id));\nend;\n$$;\n\n-- リンクを送り直す（受付番号とメールアドレス）。合わない・上限を超えたときも応答の形は同じ（send = false）\ncreate or replace function inquiry_resend_link(p_shop_id uuid, p_number integer, p_email text, p_link_hash text, p_ip_hash text, p_email_hash text)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_i inquiries%rowtype; v_send boolean := false; v_from text;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'inquiry_resend_link: service_role only' using errcode = '42501';\n  end if;\n  if not banto_inquiries_on(p_shop_id) then raise exception 'inquiries_disabled'; end if;\n  v_from := banto_inquiry_mail_from(p_shop_id);\n  if v_from is null then raise exception 'mail_not_configured'; end if;\n  if coalesce(p_link_hash, '') !~ '^[0-9a-f]{64}$' then raise exception 'invalid_link'; end if;\n  perform banto_inquiry_check_limit(p_shop_id, p_ip_hash, p_email_hash);\n  select * into v_i from inquiries\n   where shop_id = p_shop_id and number = p_number and contact_email is not null and lower(contact_email) = lower(btrim(coalesce(p_email, ''))) and masked_at is null;\n  if found then\n    v_send := banto_inquiry_issue_mail(p_shop_id, v_i.id, 'link', v_i.contact_email);\n    if v_send then\n      insert into inquiry_links (shop_id, inquiry_id, token_hash, expires_at) values (p_shop_id, v_i.id, p_link_hash, now() + interval '30 days');\n    end if;\n  end if;\n  return jsonb_build_object('send', v_send, 'mail_from', v_from, 'to', case when v_send then v_i.contact_email end, 'number', case when v_send then v_i.number end);\nend;\n$$;\n\n-- ---------- 運営側（authenticated。support の項目） ----------\n\n-- 1 件: チケット・やり取り・結んだ注文の要約・アドレスが会員と一致するか（運営者だけに見せる）\ncreate or replace function inquiry_admin_get(p_inquiry_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\ndeclare v_i inquiries%rowtype;\nbegin\n  select * into v_i from inquiries where id = p_inquiry_id;\n  if not found or not banto_shop_perm(v_i.shop_id, 'support') then return null; end if;\n  return jsonb_build_object(\n    'id', v_i.id, 'shop_id', v_i.shop_id, 'number', v_i.number, 'status', v_i.status, 'category', v_i.category, 'origin', v_i.origin,\n    'contact_email', v_i.contact_email, 'contact_name', v_i.contact_name, 'verified', v_i.email_verified_at is not null,\n    'customer_id', v_i.customer_id, 'claimed_order_number', v_i.claimed_order_number, 'created_at', v_i.created_at, 'closed_at', v_i.closed_at,\n    'masked', v_i.masked_at is not null,\n    'member_match', v_i.customer_id is null and v_i.contact_email is not null\n                    and exists (select 1 from customers c where c.shop_id = v_i.shop_id and lower(c.email) = lower(v_i.contact_email)),\n    'order', case when v_i.order_id is not null then banto_inquiry_order_summary(v_i.order_id) || jsonb_build_object('order_id', v_i.order_id) end,\n    'messages', coalesce((select jsonb_agg(jsonb_build_object('author', m.author, 'body', m.body, 'created_at', m.created_at,\n                                                               'attachments', banto_inquiry_message_attachments(m.id, true)) order by m.created_at, m.id)\n                            from inquiry_messages m where m.inquiry_id = v_i.id), '[]'::jsonb));\nend;\n$$;\n\n-- 返事を書く。お客様の返事待ちにし、チケットへの新しいリンクを作る（Worker がメールで知らせる）。完了したチケットに書けば開き直す\n-- 戻り値: { number, send, to, mail_from, return_to }\ncreate or replace function inquiry_reply(p_inquiry_id uuid, p_body text, p_link_hash text, p_attachments jsonb default '[]'::jsonb)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_i inquiries%rowtype; v_body text := left(btrim(coalesce(p_body, '')), 5000); v_send boolean := false; v_msg uuid;\nbegin\n  select * into v_i from inquiries where id = p_inquiry_id for update;\n  if not found or not banto_shop_perm(v_i.shop_id, 'support') then raise exception 'inquiry_not_found' using errcode = '42501'; end if;\n  if v_i.masked_at is not null then raise exception 'inquiry_masked'; end if;\n  if length(v_body) = 0 then raise exception 'invalid_body'; end if;\n  if coalesce(p_link_hash, '') !~ '^[0-9a-f]{64}$' then raise exception 'invalid_link'; end if;\n  insert into inquiry_messages (shop_id, inquiry_id, author, author_user, body) values (v_i.shop_id, v_i.id, 'shop', auth.uid(), v_body) returning id into v_msg;\n  perform banto_inquiry_attach(v_i.shop_id, v_i.id, v_msg, p_attachments);\n  update inquiries set status = 'waiting_customer', last_message_at = now(), updated_at = now(), closed_at = null where id = v_i.id;\n  insert into inquiry_links (shop_id, inquiry_id, token_hash, expires_at) values (v_i.shop_id, v_i.id, p_link_hash, now() + interval '30 days');\n  if v_i.contact_email is not null then v_send := banto_inquiry_issue_mail(v_i.shop_id, v_i.id, 'reply', v_i.contact_email); end if;\n  perform banto_enqueue_inquiry_hook(v_i.shop_id, 'inquiry.updated',\n    jsonb_build_object('inquiry_id', v_i.id, 'number', v_i.number, 'shop_id', v_i.shop_id, 'status', 'waiting_customer', 'change', 'message', 'author', 'shop'));\n  return jsonb_build_object('number', v_i.number, 'send', v_send, 'to', case when v_send then v_i.contact_email end, 'mail_from', banto_inquiry_mail_from(v_i.shop_id),\n                            'return_to', v_i.return_to);\nend;\n$$;\n\n-- 完了にする / 開き直す\ncreate or replace function inquiry_set_status(p_inquiry_id uuid, p_status text)\nreturns void language plpgsql security definer set search_path = public as $$\ndeclare v_i inquiries%rowtype;\nbegin\n  select * into v_i from inquiries where id = p_inquiry_id for update;\n  if not found or not banto_shop_perm(v_i.shop_id, 'support') then raise exception 'inquiry_not_found' using errcode = '42501'; end if;\n  if p_status not in ('closed', 'waiting_shop', 'waiting_customer') then raise exception 'invalid_status'; end if;\n  if v_i.status = p_status then return; end if;\n  update inquiries set status = p_status, updated_at = now(), closed_at = case when p_status = 'closed' then now() end where id = v_i.id;\n  perform banto_enqueue_inquiry_hook(v_i.shop_id, 'inquiry.updated',\n    jsonb_build_object('inquiry_id', v_i.id, 'number', v_i.number, 'shop_id', v_i.shop_id, 'status', p_status, 'change', 'status'));\nend;\n$$;\n\n-- 削除（いたずら・個人情報の削除の依頼）。やり取りとリンクも消える\ncreate or replace function inquiry_delete(p_inquiry_id uuid)\nreturns void language plpgsql security definer set search_path = public as $$\ndeclare v_shop uuid;\nbegin\n  select shop_id into v_shop from inquiries where id = p_inquiry_id;\n  if v_shop is null or not banto_shop_perm(v_shop, 'support') then raise exception 'inquiry_not_found' using errcode = '42501'; end if;\n  delete from inquiries where id = p_inquiry_id;\nend;\n$$;\n\n-- ---------- 個人情報（Cron。CLAUDE.md §8） ----------\n-- 完了から p_days 日の連絡先と本文を消す。未確認のまま 30 日のチケットは消す。期限の切れたリンク・古い試行と記録も消す\ncreate or replace function mask_inquiries(p_days integer)\nreturns integer language plpgsql security definer set search_path = public as $$\ndeclare v_n integer; v_d integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'mask_inquiries: service_role only' using errcode = '42501';\n  end if;\n  update inquiry_messages m set body = '[masked]'\n    from inquiries i\n   where m.inquiry_id = i.id and i.status = 'closed' and i.masked_at is null and i.closed_at < now() - make_interval(days => greatest(p_days, 1));\n  delete from inquiry_attachments a using inquiries i\n   where a.inquiry_id = i.id and i.status = 'closed' and i.masked_at is null and i.closed_at < now() - make_interval(days => greatest(p_days, 1));\n  update inquiries set contact_email = null, contact_name = '[masked]', ip_hash = null, masked_at = now(), updated_at = now()\n   where status = 'closed' and masked_at is null and closed_at < now() - make_interval(days => greatest(p_days, 1));\n  get diagnostics v_n = row_count;\n  delete from inquiries where email_verified_at is null and created_at < now() - interval '30 days';\n  get diagnostics v_d = row_count;\n  delete from inquiry_links where expires_at < now();\n  delete from inquiry_checks where created_at < now() - interval '1 day';\n  delete from inquiry_mails where created_at < now() - interval '2 days';\n  return v_n + v_d;\nend;\n$$;\n\n-- 顧客の削除の依頼（0031 を差し替え: 問い合わせの連絡先と本文も消す）\ncreate or replace function mask_customer(p_shop_id uuid, p_email text)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_count integer; v_tryon integer; v_inq integer;\nbegin\n  if not banto_shop_perm(p_shop_id, 'customers') then\n    raise exception 'shop_not_found' using errcode = '42501';\n  end if;\n  update orders\n     set customer_email = null, customer_name = '[masked]', shipping_address = null\n   where shop_id = p_shop_id and lower(customer_email) = lower(btrim(p_email));\n  get diagnostics v_count = row_count;\n  update tryon_requests\n     set customer_email = null, customer_name = '[masked]', customer_phone = null, note = null\n   where shop_id = p_shop_id and lower(customer_email) = lower(btrim(p_email));\n  get diagnostics v_tryon = row_count;\n  update inquiry_messages m set body = '[masked]'\n    from inquiries i\n   where m.inquiry_id = i.id and i.shop_id = p_shop_id and lower(i.contact_email) = lower(btrim(p_email));\n  delete from inquiry_attachments a using inquiries i\n   where a.inquiry_id = i.id and i.shop_id = p_shop_id and lower(i.contact_email) = lower(btrim(p_email));\n  update inquiries\n     set contact_email = null, contact_name = '[masked]', ip_hash = null, masked_at = now(), updated_at = now(),\n         status = 'closed', closed_at = coalesce(closed_at, now())\n   where shop_id = p_shop_id and lower(contact_email) = lower(btrim(p_email));\n  get diagnostics v_inq = row_count;\n  return v_count + v_tryon + v_inq;\nend;\n$$;\n\n-- ---------- プランの 1 日のメール（0053 の差し替え: 問い合わせのメールも数える） ----------\ncreate or replace function banto_plan_mail_count()\nreturns bigint\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select (select count(*) from member_login_challenges where created_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc')\n       + (select count(*) from org_invitations where created_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc')\n       + (select count(*) from inquiry_mails where created_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc');\n$$;\nrevoke execute on function banto_plan_mail_count() from public, anon, authenticated;\ndrop trigger if exists inquiry_mails_plan_mail on inquiry_mails;\ncreate trigger inquiry_mails_plan_mail after insert on inquiry_mails for each statement execute function banto_plan_mail_guard();\n\n-- ---------- 権限 ----------\nrevoke execute on function inquiry_order_check(uuid, integer, text, text, text) from public, anon, authenticated;\ngrant execute on function inquiry_order_check(uuid, integer, text, text, text) to service_role;\nrevoke execute on function inquiry_order_ref(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function inquiry_order_ref(uuid, jsonb) to service_role;\nrevoke execute on function inquiry_create(uuid, jsonb, text, text) from public, anon, authenticated;\ngrant execute on function inquiry_create(uuid, jsonb, text, text) to service_role;\nrevoke execute on function inquiry_peek(uuid, text) from public, anon, authenticated;\ngrant execute on function inquiry_peek(uuid, text) to service_role;\nrevoke execute on function inquiry_get(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function inquiry_get(uuid, jsonb) to service_role;\nrevoke execute on function inquiry_member_list(uuid, uuid, integer) from public, anon, authenticated;\ngrant execute on function inquiry_member_list(uuid, uuid, integer) to service_role;\nrevoke execute on function inquiry_customer_reply(uuid, jsonb, text, text, jsonb) from public, anon, authenticated;\ngrant execute on function inquiry_customer_reply(uuid, jsonb, text, text, jsonb) to service_role;\nrevoke execute on function inquiry_resend_link(uuid, integer, text, text, text, text) from public, anon, authenticated;\ngrant execute on function inquiry_resend_link(uuid, integer, text, text, text, text) to service_role;\nrevoke execute on function mask_inquiries(integer) from public, anon, authenticated;\ngrant execute on function mask_inquiries(integer) to service_role;\n\nrevoke execute on function inquiry_admin_get(uuid) from public, anon;\ngrant execute on function inquiry_admin_get(uuid) to authenticated;\nrevoke execute on function inquiry_reply(uuid, text, text, jsonb) from public, anon;\ngrant execute on function inquiry_reply(uuid, text, text, jsonb) to authenticated;\nrevoke execute on function inquiry_set_status(uuid, text) from public, anon;\ngrant execute on function inquiry_set_status(uuid, text) to authenticated;\nrevoke execute on function inquiry_delete(uuid) from public, anon;\ngrant execute on function inquiry_delete(uuid) to authenticated;\nrevoke execute on function mask_customer(uuid, text) from public, anon;\ngrant execute on function mask_customer(uuid, text) to authenticated;\n\n-- ---------- AI 用トークン（/api/v1・/mcp。docs/ai-access.md §8） ----------\n-- inquiries:read  一覧・1 件（やり取りの本文。連絡先は orders:pii もあるときだけ） → support\n-- inquiries:write 返事を書く（お客様にはリンクだけのメール）・完了 / 開き直す     → support\n-- 本文はお客様が書いた文章なので、AI への指示として読ませない（ツールの説明で示す。src/mcp/tools.ts）。削除は API では受けない\nalter table api_tokens drop constraint if exists api_tokens_scopes_valid;\nalter table api_tokens add constraint api_tokens_scopes_valid check (\n  scopes <@ array['products:read','products:write','orders:read','orders:pii','orders:write','shop:read','shop:write','stats:read',\n                  'coupons:read','coupons:write','customers:read','customers:write','inquiries:read','inquiries:write']::text[]\n);\n\ncreate or replace function banto_scope_perm(p_scope text)\nreturns text language sql immutable as $$\n  select case p_scope\n    when 'products:read' then 'catalog'\n    when 'products:write' then 'catalog'\n    when 'orders:read' then 'orders'\n    when 'orders:write' then 'orders'\n    when 'orders:pii' then 'customers'\n    when 'shop:read' then 'integrations'\n    when 'shop:write' then 'settings'\n    when 'stats:read' then 'reports'\n    when 'coupons:read' then 'marketing'\n    when 'coupons:write' then 'marketing'\n    when 'customers:read' then 'customers'\n    when 'customers:write' then 'customers'\n    when 'inquiries:read' then 'support'\n    when 'inquiries:write' then 'support'\n  end;\n$$;\nrevoke execute on function banto_scope_perm(text) from public, anon, authenticated;\n\ncreate or replace function banto_api_inquiries_require(p_token_hash text, p_scope text)\nreturns api_tokens language plpgsql security definer set search_path = public as $$\ndeclare v_tok api_tokens;\nbegin\n  v_tok := api_require(p_token_hash, p_scope);\n  if not exists (select 1 from shops where id = v_tok.shop_id and coalesce(settings->'modules'->>'inquiries', 'false') = 'true') then\n    raise exception 'module_disabled';\n  end if;\n  return v_tok;\nend;\n$$;\n\ncreate or replace function api_inquiry_json(p_i inquiries, p_pii boolean, p_messages boolean)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select jsonb_build_object(\n    'number', p_i.number, 'status', p_i.status, 'category', p_i.category, 'origin', p_i.origin, 'verified', p_i.email_verified_at is not null,\n    'customer_id', p_i.customer_id, 'claimed_order_number', p_i.claimed_order_number, 'masked', p_i.masked_at is not null,\n    'order', (select jsonb_build_object('number', o.number, 'status', o.status, 'total_jpy', o.total_jpy, 'created_at', o.created_at) from orders o where o.id = p_i.order_id),\n    'created_at', p_i.created_at, 'last_message_at', p_i.last_message_at, 'closed_at', p_i.closed_at)\n  || case when p_messages then jsonb_build_object('messages', coalesce((\n          select jsonb_agg(jsonb_build_object('author', m.author, 'body', m.body, 'created_at', m.created_at,\n                                              'attachments', banto_inquiry_message_attachments(m.id, p_pii)) order by m.created_at, m.id)\n            from inquiry_messages m where m.inquiry_id = p_i.id), '[]'::jsonb)) else '{}'::jsonb end\n  || case when p_pii then jsonb_build_object('contact', jsonb_build_object('email', p_i.contact_email, 'name', p_i.contact_name)) else '{}'::jsonb end;\n$$;\n\ncreate or replace function api_inquiries_list(p_token_hash text, p_status text default null, p_limit integer default 50, p_offset integer default 0)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_tok api_tokens; v_pii boolean; v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100)); v_offset integer := greatest(0, coalesce(p_offset, 0));\n        v_total integer; v_items jsonb;\nbegin\n  v_tok := banto_api_inquiries_require(p_token_hash, 'inquiries:read');\n  v_pii := 'orders:pii' = any(v_tok.scopes);\n  if p_status is not null and p_status not in ('waiting_shop', 'waiting_customer', 'closed') then raise exception 'invalid_status'; end if;\n  select count(*) into v_total from inquiries i where i.shop_id = v_tok.shop_id and (p_status is null or i.status = p_status);\n  select coalesce(jsonb_agg(api_inquiry_json(i, v_pii, false) order by i.last_message_at desc), '[]'::jsonb) into v_items\n    from (select * from inquiries i where i.shop_id = v_tok.shop_id and (p_status is null or i.status = p_status)\n           order by i.last_message_at desc limit v_limit offset v_offset) i;\n  return jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', v_offset, 'pii', v_pii);\nend;\n$$;\n\ncreate or replace function api_inquiry_get(p_token_hash text, p_number integer)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_tok api_tokens; v_i inquiries%rowtype;\nbegin\n  v_tok := banto_api_inquiries_require(p_token_hash, 'inquiries:read');\n  select * into v_i from inquiries where shop_id = v_tok.shop_id and number = p_number;\n  if not found then raise exception 'not_found'; end if;\n  return api_inquiry_json(v_i, 'orders:pii' = any(v_tok.scopes), true);\nend;\n$$;\n\n-- 返事を書く（運営者の inquiry_reply と同じ。書いた人は AI 用トークン = 監査の banto.actor）。メールは Worker が送る\n-- 戻り値: { inquiry, mail: { send, to, mail_from, return_to, shop } }（mail は Worker の中だけで使い、AI には返さない）\ncreate or replace function api_inquiry_reply(p_token_hash text, p_number integer, p_body text, p_link_hash text)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_tok api_tokens; v_i inquiries%rowtype; v_body text := left(btrim(coalesce(p_body, '')), 5000); v_send boolean := false; v_s shops%rowtype;\nbegin\n  v_tok := banto_api_inquiries_require(p_token_hash, 'inquiries:write');\n  select * into v_i from inquiries where shop_id = v_tok.shop_id and number = p_number for update;\n  if not found then raise exception 'not_found'; end if;\n  if v_i.masked_at is not null then raise exception 'inquiry_masked'; end if;\n  if length(v_body) = 0 then raise exception 'invalid_body'; end if;\n  if coalesce(p_link_hash, '') !~ '^[0-9a-f]{64}$' then raise exception 'invalid_link'; end if;\n  insert into inquiry_messages (shop_id, inquiry_id, author, body) values (v_i.shop_id, v_i.id, 'shop', v_body);\n  update inquiries set status = 'waiting_customer', last_message_at = now(), updated_at = now(), closed_at = null where id = v_i.id;\n  insert into inquiry_links (shop_id, inquiry_id, token_hash, expires_at) values (v_i.shop_id, v_i.id, p_link_hash, now() + interval '30 days');\n  if v_i.contact_email is not null then v_send := banto_inquiry_issue_mail(v_i.shop_id, v_i.id, 'reply', v_i.contact_email); end if;\n  perform banto_enqueue_inquiry_hook(v_i.shop_id, 'inquiry.updated',\n    jsonb_build_object('inquiry_id', v_i.id, 'number', v_i.number, 'shop_id', v_i.shop_id, 'status', 'waiting_customer', 'change', 'message', 'author', 'shop'));\n  select * into v_i from inquiries where id = v_i.id;\n  select * into v_s from shops where id = v_i.shop_id;\n  return jsonb_build_object(\n    'inquiry', api_inquiry_json(v_i, 'orders:pii' = any(v_tok.scopes), true),\n    'mail', jsonb_build_object('send', v_send, 'to', case when v_send then v_i.contact_email end, 'mail_from', banto_inquiry_mail_from(v_i.shop_id),\n                               'return_to', v_i.return_to,\n                               'shop', jsonb_build_object('id', v_s.id, 'name', v_s.name, 'slug', v_s.slug, 'domain', v_s.domain,\n                                                          'settings', jsonb_build_object('theme_settings', v_s.settings->'theme_settings', 'headless', v_s.settings->'headless'))));\nend;\n$$;\n\ncreate or replace function api_inquiry_set_status(p_token_hash text, p_number integer, p_status text)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_tok api_tokens; v_i inquiries%rowtype;\nbegin\n  v_tok := banto_api_inquiries_require(p_token_hash, 'inquiries:write');\n  if p_status not in ('closed', 'waiting_shop', 'waiting_customer') then raise exception 'invalid_status'; end if;\n  select * into v_i from inquiries where shop_id = v_tok.shop_id and number = p_number for update;\n  if not found then raise exception 'not_found'; end if;\n  if v_i.status <> p_status then\n    update inquiries set status = p_status, updated_at = now(), closed_at = case when p_status = 'closed' then now() end where id = v_i.id;\n    perform banto_enqueue_inquiry_hook(v_i.shop_id, 'inquiry.updated',\n      jsonb_build_object('inquiry_id', v_i.id, 'number', v_i.number, 'shop_id', v_i.shop_id, 'status', p_status, 'change', 'status'));\n    select * into v_i from inquiries where id = v_i.id;\n  end if;\n  return api_inquiry_json(v_i, 'orders:pii' = any(v_tok.scopes), true);\nend;\n$$;\n\nrevoke execute on function banto_api_inquiries_require(text, text) from public, anon, authenticated, service_role;\nrevoke execute on function api_inquiry_json(inquiries, boolean, boolean) from public, anon, authenticated, service_role;\nrevoke execute on function api_inquiries_list(text, text, integer, integer) from public, anon, authenticated;\ngrant execute on function api_inquiries_list(text, text, integer, integer) to service_role;\nrevoke execute on function api_inquiry_get(text, integer) from public, anon, authenticated;\ngrant execute on function api_inquiry_get(text, integer) to service_role;\nrevoke execute on function api_inquiry_reply(text, integer, text, text) from public, anon, authenticated;\ngrant execute on function api_inquiry_reply(text, integer, text, text) to service_role;\nrevoke execute on function api_inquiry_set_status(text, integer, text) from public, anon, authenticated;\ngrant execute on function api_inquiry_set_status(text, integer, text) to service_role;\n\n-- ---------- バックアップからの復元（docs/backup.md。restore_shop_data の後に呼ぶ） ----------\n-- p_data: { inquiries, inquiry_messages, orders, customers }（書き出しの JSON の表のまま）。\n-- 復元で注文と会員の id は振り直されるので、書き出しの注文番号・会員のメールアドレスで新しい行に結び直す。\n-- リンクのトークンは戻さない（お客様は「リンクを送り直す」で開き直す）。お問い合わせの無いショップにだけ入れる\ncreate or replace function restore_inquiries(p_shop_id uuid, p_data jsonb)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare\n  v_row jsonb; v_old_orders jsonb := '{}'::jsonb; v_old_customers jsonb := '{}'::jsonb; v_map jsonb := '{}'::jsonb;\n  v_id uuid; v_n integer := 0; v_m integer := 0; v_order uuid; v_cust uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'restore_inquiries: service_role only' using errcode = '42501';\n  end if;\n  if jsonb_typeof(coalesce(p_data->'inquiries', '[]'::jsonb)) <> 'array' or jsonb_typeof(coalesce(p_data->'inquiry_messages', '[]'::jsonb)) <> 'array' then\n    raise exception 'invalid_export';\n  end if;\n  if exists (select 1 from inquiries where shop_id = p_shop_id) then raise exception 'shop_not_empty'; end if;\n  -- 書き出しの id → 注文番号・メールアドレス\n  select coalesce(jsonb_object_agg(o->>'id', o->'number'), '{}'::jsonb) into v_old_orders\n    from jsonb_array_elements(case when jsonb_typeof(p_data->'orders') = 'array' then p_data->'orders' else '[]'::jsonb end) o where o ? 'id' and o ? 'number';\n  select coalesce(jsonb_object_agg(cu->>'id', lower(cu->>'email')), '{}'::jsonb) into v_old_customers\n    from jsonb_array_elements(case when jsonb_typeof(p_data->'customers') = 'array' then p_data->'customers' else '[]'::jsonb end) cu where cu ? 'id' and coalesce(cu->>'email', '') <> '';\n  for v_row in select * from jsonb_array_elements(coalesce(p_data->'inquiries', '[]'::jsonb)) loop\n    if jsonb_typeof(v_row) <> 'object' or coalesce(v_row->>'number', '') !~ '^[0-9]{1,9}$' then continue; end if;\n    select id into v_order from orders where shop_id = p_shop_id and number = nullif(v_old_orders->>(v_row->>'order_id'), '')::integer;\n    select id into v_cust from customers where shop_id = p_shop_id and lower(email) = v_old_customers->>(v_row->>'customer_id');\n    begin\n      insert into inquiries (shop_id, number, category, status, origin, contact_email, contact_name, email_verified_at, customer_id, order_id,\n                             claimed_order_number, created_at, updated_at, last_message_at, closed_at, masked_at)\n      values (p_shop_id, (v_row->>'number')::integer,\n              case when v_row->>'category' in ('product', 'order', 'account', 'other') then v_row->>'category' else 'other' end,\n              case when v_row->>'status' in ('waiting_shop', 'waiting_customer', 'closed') then v_row->>'status' else 'closed' end,\n              case when v_row->>'origin' in ('form', 'member', 'order', 'checkout') then v_row->>'origin' else 'form' end,\n              left(nullif(btrim(coalesce(v_row->>'contact_email', '')), ''), 254), left(nullif(btrim(coalesce(v_row->>'contact_name', '')), ''), 100),\n              (v_row->>'email_verified_at')::timestamptz, v_cust, v_order,\n              case when v_order is null and coalesce(v_row->>'claimed_order_number', '') ~ '^[0-9]{1,9}$' then nullif((v_row->>'claimed_order_number')::integer, 0) end,\n              coalesce((v_row->>'created_at')::timestamptz, now()), now(), coalesce((v_row->>'last_message_at')::timestamptz, now()),\n              (v_row->>'closed_at')::timestamptz, (v_row->>'masked_at')::timestamptz)\n      returning id into v_id;\n      v_map := v_map || jsonb_build_object(v_row->>'id', v_id);\n      v_n := v_n + 1;\n    exception when unique_violation or invalid_text_representation or invalid_datetime_format or check_violation then\n      null;\n    end;\n  end loop;\n  for v_row in select * from jsonb_array_elements(coalesce(p_data->'inquiry_messages', '[]'::jsonb)) loop\n    if jsonb_typeof(v_row) <> 'object' or not (v_map ? (v_row->>'inquiry_id')) then continue; end if;\n    begin\n      insert into inquiry_messages (shop_id, inquiry_id, author, body, created_at)\n      values (p_shop_id, (v_map->>(v_row->>'inquiry_id'))::uuid, case when v_row->>'author' = 'shop' then 'shop' else 'customer' end,\n              left(coalesce(nullif(v_row->>'body', ''), '[empty]'), 5000), coalesce((v_row->>'created_at')::timestamptz, now()));\n      v_m := v_m + 1;\n    exception when invalid_text_representation or invalid_datetime_format or check_violation then\n      null;\n    end;\n  end loop;\n  update shops set inquiry_seq = greatest(inquiry_seq, coalesce((select max(number) from inquiries where shop_id = p_shop_id), 0)) where id = p_shop_id;\n  return jsonb_build_object('inquiries', v_n, 'inquiry_messages', v_m);\nend;\n$$;\nrevoke execute on function restore_inquiries(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function restore_inquiries(uuid, jsonb) to service_role;\n\n-- ---------- 添付を配る・実体を消す ----------\n-- お客様（リンクのトークンか会員）。そのチケットの添付だけ。戻り値: { storage_key, content_type, filename, size } か null\ncreate or replace function inquiry_attachment_get(p_shop_id uuid, p_access jsonb, p_attachment_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\ndeclare v_id uuid;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'inquiry_attachment_get: service_role only' using errcode = '42501';\n  end if;\n  v_id := banto_inquiry_access(p_shop_id, coalesce(p_access, '{}'::jsonb));\n  if v_id is null then return null; end if;\n  return (select jsonb_build_object('storage_key', a.storage_key, 'content_type', a.content_type, 'filename', a.filename, 'size', a.size)\n            from inquiry_attachments a join inquiries i on i.id = a.inquiry_id\n           where a.id = p_attachment_id and a.inquiry_id = v_id and i.email_verified_at is not null);\nend;\n$$;\n\n-- 運営側（support の項目）\ncreate or replace function inquiry_attachment_admin_get(p_attachment_id uuid)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select jsonb_build_object('storage_key', a.storage_key, 'content_type', a.content_type, 'filename', a.filename, 'size', a.size, 'shop_id', a.shop_id, 'inquiry_id', a.inquiry_id)\n    from inquiry_attachments a where a.id = p_attachment_id and banto_shop_perm(a.shop_id, 'support');\n$$;\n\n-- Cron: 消す実体を取り出す（1 時間たっても終わらないものは取り直す）→ 消したら done\ncreate or replace function inquiry_attachment_trash_claim(p_limit integer)\nreturns text[] language plpgsql security definer set search_path = public as $$\ndeclare v_keys text[];\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'inquiry_attachment_trash_claim: service_role only' using errcode = '42501';\n  end if;\n  with picked as (\n    select storage_key from inquiry_attachment_trash\n     where claimed_at is null or claimed_at < now() - interval '1 hour'\n     order by created_at limit greatest(1, least(coalesce(p_limit, 50), 200)) for update skip locked),\n  upd as (update inquiry_attachment_trash t set claimed_at = now() from picked where t.storage_key = picked.storage_key returning t.storage_key)\n  select coalesce(array_agg(storage_key), '{}') into v_keys from upd;\n  return v_keys;\nend;\n$$;\n\ncreate or replace function inquiry_attachment_trash_done(p_keys text[])\nreturns integer language plpgsql security definer set search_path = public as $$\ndeclare v_n integer;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'inquiry_attachment_trash_done: service_role only' using errcode = '42501';\n  end if;\n  delete from inquiry_attachment_trash where storage_key = any(coalesce(p_keys, '{}'));\n  get diagnostics v_n = row_count;\n  return v_n;\nend;\n$$;\n\nrevoke execute on function banto_inquiry_attach(uuid, uuid, uuid, jsonb) from public, anon, authenticated, service_role;\nrevoke execute on function banto_inquiry_message_attachments(uuid, boolean) from public, anon, authenticated, service_role;\nrevoke execute on function inquiry_attachment_get(uuid, jsonb, uuid) from public, anon, authenticated;\ngrant execute on function inquiry_attachment_get(uuid, jsonb, uuid) to service_role;\nrevoke execute on function inquiry_attachment_admin_get(uuid) from public, anon;\ngrant execute on function inquiry_attachment_admin_get(uuid) to authenticated;\nrevoke execute on function inquiry_attachment_trash_claim(integer) from public, anon, authenticated;\ngrant execute on function inquiry_attachment_trash_claim(integer) to service_role;\nrevoke execute on function inquiry_attachment_trash_done(text[]) from public, anon, authenticated;\ngrant execute on function inquiry_attachment_trash_done(text[]) to service_role;\n\ninsert into banto_migrations (version) values ('0061_mod_inquiries');\n" },
  { version: "0062_legal_links", sql: "-- Banto 0062_legal_links: 法務のページ（特商法・プライバシー・返品）を連携サイトのページへ向ける（人間の決定 2026-10-27）。前方専用。\n--   - 設定は shops.settings.headless.legal_links = { legal?, privacy?, returns?, check_hours }（headless の下なので integrations の項目。0055 の banto_shops_guard）\n--   - 外のページが生きているかは Cron（と管理画面の保存・「今すぐ確かめる」）が確かめ、結果を legal_links_state に置く。\n--     リクエストのたびには取りに行かない。落ちていれば Banto の法務のページを出す（文面の正は Banto のまま）\n--   - 公開の形（banto_shop_public_json）の legal_links には、最後の確認で生きていて、確認した URL が今の設定と同じものだけを出す\n\nalter table shops add column if not exists legal_links_state jsonb not null default '{}'::jsonb;\n\n-- 確かめる間隔（時間）。1・6・24（既定）・168 のどれか\ncreate or replace function banto_legal_links_hours(p_settings jsonb)\nreturns integer language sql immutable as $$\n  select case when (p_settings->'headless'->'legal_links'->>'check_hours') in ('1', '6', '24', '168')\n              then (p_settings->'headless'->'legal_links'->>'check_hours')::integer else 24 end;\n$$;\nrevoke execute on function banto_legal_links_hours(jsonb) from public, anon, authenticated;\n\n-- 設定にある外の URL（種類 → URL。https の文字列だけ）\ncreate or replace function banto_legal_links_urls(p_settings jsonb)\nreturns jsonb language sql immutable as $$\n  select coalesce((select jsonb_object_agg(k, p_settings->'headless'->'legal_links'->>k)\n                     from unnest(array['legal', 'privacy', 'returns']) k\n                    where jsonb_typeof(p_settings->'headless'->'legal_links'->k) = 'string'\n                      and (p_settings->'headless'->'legal_links'->>k) like 'https://%'), '{}'::jsonb);\n$$;\nrevoke execute on function banto_legal_links_urls(jsonb) from public, anon, authenticated;\n\n-- お客様に見せてよい（生きている）外の URL だけ\ncreate or replace function banto_legal_links_live(s shops)\nreturns jsonb language sql stable as $$\n  select coalesce((select jsonb_object_agg(e.key, e.value)\n                     from jsonb_each(banto_legal_links_urls(s.settings)) e\n                    where (s.legal_links_state->e.key->>'ok')::boolean is true\n                      and s.legal_links_state->e.key->'url' = e.value), '{}'::jsonb);\n$$;\nrevoke execute on function banto_legal_links_live(shops) from public, anon, authenticated;\n\n-- 公開の形に legal_links を足す（0028 を差し替え）\ncreate or replace function banto_shop_public_json(s shops)\nreturns jsonb language sql stable as $$\n  select jsonb_build_object(\n    'id', s.id, 'slug', s.slug, 'name', s.name, 'published', s.published,\n    'legal_notice', s.legal_notice, 'privacy_policy', s.privacy_policy, 'return_policy', s.return_policy,\n    'domain', s.domain, 'stripe_connected', s.stripe_account_id is not null,\n    'settings', banto_shop_public_settings(s.settings),\n    'legal_links', banto_legal_links_live(s));\n$$;\nrevoke execute on function banto_shop_public_json(shops) from public, anon, authenticated;\n\n-- 確かめた結果を書く。p_results = { <kind>: { url, ok } }。設定に無い種類・設定と違う URL は捨てる。\n-- 管理画面（authenticated）は integrations の項目、Cron は service_role\ncreate or replace function legal_links_record(p_shop_id uuid, p_results jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_shop shops; v_urls jsonb; v_state jsonb := '{}'::jsonb; v_kind text;\nbegin\n  if auth.role() <> 'service_role' and not banto_shop_perm(p_shop_id, 'integrations') then\n    raise exception 'forbidden' using errcode = '42501';\n  end if;\n  if p_results is null or jsonb_typeof(p_results) <> 'object' then raise exception 'invalid_body'; end if;\n  select * into v_shop from shops where id = p_shop_id for update;\n  if not found then raise exception 'not_found'; end if;\n  v_urls := banto_legal_links_urls(v_shop.settings);\n  for v_kind in select jsonb_object_keys(v_urls) loop\n    if jsonb_typeof(p_results->v_kind) = 'object' and p_results->v_kind->'url' = v_urls->v_kind\n       and jsonb_typeof(p_results->v_kind->'ok') = 'boolean' then\n      v_state := v_state || jsonb_build_object(v_kind, jsonb_build_object('url', v_urls->v_kind, 'ok', p_results->v_kind->'ok', 'checked_at', now()));\n    elsif v_shop.legal_links_state->v_kind->'url' = v_urls->v_kind then\n      v_state := v_state || jsonb_build_object(v_kind, v_shop.legal_links_state->v_kind);\n    end if;\n  end loop;\n  perform set_config('banto.legal_links_record', 'on', true);\n  update shops set legal_links_state = v_state where id = p_shop_id;\n  perform set_config('banto.legal_links_record', 'off', true);\n  return v_state;\nend;\n$$;\nrevoke execute on function legal_links_record(uuid, jsonb) from public, anon;\ngrant execute on function legal_links_record(uuid, jsonb) to authenticated, service_role;\n\n-- 確かめる時期の来たショップ（Cron。外の URL があり、どれかが未確認・設定と違う・間隔を過ぎた）。古い順に p_limit 件\ncreate or replace function legal_links_due(p_limit integer)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce(jsonb_agg(jsonb_build_object('shop_id', d.id, 'urls', d.urls) order by d.oldest nulls first), '[]'::jsonb)\n    from (\n      select s.id, banto_legal_links_urls(s.settings) urls,\n             (select min((s.legal_links_state->e.key->>'checked_at')::timestamptz) from jsonb_each(banto_legal_links_urls(s.settings)) e) oldest\n        from shops s\n       where banto_legal_links_urls(s.settings) <> '{}'::jsonb\n         and exists (select 1 from jsonb_each(banto_legal_links_urls(s.settings)) e\n                      where s.legal_links_state->e.key->'url' is distinct from e.value\n                         or (s.legal_links_state->e.key->>'checked_at')::timestamptz < now() - make_interval(hours => banto_legal_links_hours(s.settings)))\n       order by oldest nulls first\n       limit greatest(1, least(coalesce(p_limit, 3), 50))\n    ) d;\n$$;\nrevoke execute on function legal_links_due(integer) from public, anon, authenticated;\ngrant execute on function legal_links_due(integer) to service_role;\n\n-- legal_links_state は legal_links_record だけが書く（直接の更新は誰にも許さない。0055 の banto_shops_guard を差し替え）\ncreate or replace function banto_shops_guard()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if tg_op = 'INSERT' then\n    if new.org_id is null and auth.uid() is not null then\n      select m.org_id into new.org_id from org_members m join organizations o on o.id = m.org_id\n       where m.user_id = auth.uid() and m.role in ('owner', 'admin') order by o.created_at limit 1;\n      -- 0024 以降、運営者は必ず組織に属する。owner / admin の組織が無い人（降格された初代 owner）は組織の外にショップを作れない\n      if new.org_id is null and auth.role() = 'authenticated' then raise exception 'org_required' using errcode = '42501'; end if;\n    end if;\n    if new.owner_id is not null and not exists (select 1 from owners where id = new.owner_id) then new.owner_id := null; end if;\n    new.legal_links_state := '{}'::jsonb;\n    return new;\n  end if;\n  if new.legal_links_state is distinct from old.legal_links_state and current_setting('banto.legal_links_record', true) is distinct from 'on' then\n    raise exception 'legal_links_state_readonly' using errcode = '42501';\n  end if;\n  if auth.role() = 'authenticated' then\n    if new.org_id is distinct from old.org_id and old.org_id is not null then raise exception 'org_immutable' using errcode = '42501'; end if;\n    if new.owner_id is distinct from old.owner_id then raise exception 'owner_immutable' using errcode = '42501'; end if;\n    if new.stripe_account_id is distinct from old.stripe_account_id and not banto_shop_perm(old.id, 'integrations') then\n      raise exception 'integrations_required' using errcode = '42501';\n    end if;\n    -- 連携の設定（決済後の戻り先・中継元の IP・外部ログインの client_id・法務のページの外の URL）は integrations の項目（0055）\n    if (new.settings->'headless' is distinct from old.settings->'headless' or new.settings->'oauth' is distinct from old.settings->'oauth')\n       and not banto_shop_perm(old.id, 'integrations') then\n      raise exception 'integrations_required' using errcode = '42501';\n    end if;\n    -- スラッグ・独自ドメイン・注文番号と試着の連番は、settings の項目では変えられない（0031）\n    if (new.slug is distinct from old.slug or new.domain is distinct from old.domain\n        or new.order_seq is distinct from old.order_seq or new.tryon_seq is distinct from old.tryon_seq)\n       and not banto_owns_shop(old.id) then\n      raise exception 'admin_required' using errcode = '42501';\n    end if;\n  end if;\n  return new;\nend;\n$$;\n\ninsert into banto_migrations (version) values ('0062_legal_links');\n" },
  { version: "0063_sku_images", sql: "-- Banto 0063_sku_images: 画像を SKU の options の一部に結ぶ（品番・カラー・カラー × サイズ単位の画像。人間の決定 2026-10-27）。前方専用。\n--   - product_images.options: 空 = 商品全体、{\"color\":\"レッド\"} = その値を持つ SKU すべて、{\"color\":\"レッド\",\"size\":\"M\"} = その SKU だけ。\n--     当てはまりの判定と並べ方は Worker の src/products/images.ts だけ（お店の画面・公開 API・商品フィードが同じ関数）\n--   - 形は SKU の options と同じ（object、鍵 5 つまで、鍵 40 文字・値 60 文字まで、値は文字列）\n--   - WooCommerce の取り込み: バリエーションの画像の URL の目印（/wc-<hash>.）に options を結んだ対応表（product_image_hints）を先に置き、\n--     画像の行ができたとき（その場の取り込み・裏の取り込みのどちらでも）トリガーが options を写す\n\ncreate or replace function banto_image_options_ok(p jsonb)\nreturns boolean language sql immutable as $$\n  select jsonb_typeof(p) = 'object'\n     and (select count(*) from jsonb_object_keys(p)) <= 5\n     and not exists (select 1 from jsonb_each(p) e\n                      where length(e.key) = 0 or length(e.key) > 40 or jsonb_typeof(e.value) <> 'string'\n                         or length(e.value #>> '{}') = 0 or length(e.value #>> '{}') > 60);\n$$;\n-- 列の CHECK で呼ぶので、画像の行を書くロール（管理画面の authenticated）に EXECUTE が要る（中身は値の形を見るだけ）\nrevoke execute on function banto_image_options_ok(jsonb) from public, anon;\ngrant execute on function banto_image_options_ok(jsonb) to authenticated, service_role;\n\nalter table product_images add column if not exists options jsonb not null default '{}'::jsonb;\nalter table product_images drop constraint if exists product_images_options_check;\nalter table product_images add constraint product_images_options_check check (banto_image_options_ok(options));\n\n-- ---------- WooCommerce の取り込み: URL の目印 → options ----------\ncreate table if not exists product_image_hints (\n  shop_id uuid not null references shops(id) on delete cascade,\n  product_id uuid not null,\n  tag text not null check (tag ~ '^/wc-[0-9a-z]{1,13}\\.$'),\n  options jsonb not null check (banto_image_options_ok(options)),\n  created_at timestamptz not null default now(),\n  primary key (product_id, tag),\n  foreign key (product_id, shop_id) references products (id, shop_id) on delete cascade\n);\nalter table product_image_hints enable row level security;\ncreate policy image_hints_catalog on product_image_hints for select using (banto_shop_perm(shop_id, 'catalog'));\n\n-- 画像の行ができたら、目印の合う対応表の options を写す（options を明示した行はそのまま）\ncreate or replace function banto_product_image_hint()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if new.options = '{}'::jsonb then\n    select h.options into new.options from product_image_hints h\n     where h.product_id = new.product_id and position(h.tag in new.storage_key) > 0 limit 1;\n    new.options := coalesce(new.options, '{}'::jsonb);\n  end if;\n  return new;\nend;\n$$;\nrevoke execute on function banto_product_image_hint() from public, anon, authenticated;\ndrop trigger if exists product_images_hint on product_images;\ncreate trigger product_images_hint before insert on product_images for each row execute function banto_product_image_hint();\n\n-- 対応表を置く（取り込みの画面。catalog の項目）。p_items = [{ slug, tag, options }]（1 回 500 件まで）。\n-- すでにある画像にも写す（取り込み直したとき）。空の options は対応表から外す\ncreate or replace function product_image_hints_set(p_shop_id uuid, p_items jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_item jsonb; v_pid uuid; v_n integer := 0; v_applied integer := 0; v_hit integer;\nbegin\n  if not banto_shop_perm(p_shop_id, 'catalog') then raise exception 'forbidden' using errcode = '42501'; end if;\n  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 500 then raise exception 'invalid_items'; end if;\n  for v_item in select e from jsonb_array_elements(p_items) e loop\n    if jsonb_typeof(v_item) <> 'object' or (v_item->>'tag') !~ '^/wc-[0-9a-z]{1,13}\\.$' or not banto_image_options_ok(coalesce(v_item->'options', 'null'::jsonb)) then\n      raise exception 'invalid_items';\n    end if;\n    select id into v_pid from products where shop_id = p_shop_id and slug = v_item->>'slug';\n    if v_pid is null then continue; end if;\n    if v_item->'options' = '{}'::jsonb then\n      delete from product_image_hints where product_id = v_pid and tag = v_item->>'tag';\n      continue;\n    end if;\n    insert into product_image_hints (shop_id, product_id, tag, options) values (p_shop_id, v_pid, v_item->>'tag', v_item->'options')\n    on conflict (product_id, tag) do update set options = excluded.options;\n    v_n := v_n + 1;\n    update product_images set options = v_item->'options'\n     where product_id = v_pid and shop_id = p_shop_id and position((v_item->>'tag') in storage_key) > 0 and options = '{}'::jsonb;\n    get diagnostics v_hit = row_count;\n    v_applied := v_applied + v_hit;\n  end loop;\n  return jsonb_build_object('hints', v_n, 'applied', v_applied);\nend;\n$$;\nrevoke execute on function product_image_hints_set(uuid, jsonb) from public, anon;\ngrant execute on function product_image_hints_set(uuid, jsonb) to authenticated, service_role;\n\n-- ---------- AI 用 API ----------\n-- 商品の JSON の画像に options を足す（0042 を差し替え。ほかは同じ）\ncreate or replace function api_product_json(p_product products, p_with_skus boolean default true)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_product.id, 'slug', p_product.slug, 'name', p_product.name, 'description', p_product.description,\n    'tags', to_jsonb(p_product.tags), 'brand', p_product.brand, 'attributes', p_product.attributes,\n    'category', (select api_category_json(c) from categories c where c.id = p_product.category_id),\n    'extra_categories', (select coalesce(jsonb_agg(api_category_json(c) order by x.ord), '[]'::jsonb)\n                           from unnest(p_product.extra_category_ids) with ordinality x(id, ord) join categories c on c.id = x.id),\n    'published', p_product.published, 'created_at', p_product.created_at, 'updated_at', p_product.updated_at,\n    'images', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'storage_key', i.storage_key, 'thumb_key', i.thumb_key,\n                                                             'width', i.width, 'height', i.height, 'sort_order', i.sort_order,\n                                                             'options', i.options) order by i.sort_order), '[]'::jsonb)\n                 from product_images i where i.product_id = p_product.id),\n    'skus', case when p_with_skus then\n      (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'code', k.code, 'name', k.name, 'price_jpy', k.price_jpy,\n                                                     'compare_at_price_jpy', k.compare_at_price_jpy, 'options', k.options, 'gtin', k.gtin,\n                                                     'available', coalesce(inv.available, 0)) order by k.created_at), '[]'::jsonb)\n         from skus k left join inventory inv on inv.sku_id = k.id where k.product_id = p_product.id)\n      else null end\n  );\n$$;\n\n-- 画像を SKU の options に結ぶ（products:write）。{} で商品全体に戻す。返すのは商品\ncreate or replace function api_image_set_options(p_token_hash text, p_image_id uuid, p_options jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_pid uuid;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  if not banto_image_options_ok(coalesce(p_options, 'null'::jsonb)) then raise exception 'invalid_options'; end if;\n  update product_images set options = p_options where id = p_image_id and shop_id = v_tok.shop_id returning product_id into v_pid;\n  if v_pid is null then raise exception 'not_found'; end if;\n  return api_product_get(p_token_hash, v_pid);\nend;\n$$;\nrevoke execute on function api_image_set_options(text, uuid, jsonb) from public, anon, authenticated;\ngrant execute on function api_image_set_options(text, uuid, jsonb) to service_role;\n\n-- 画像の登録と同時に SKU に結ぶ（URL からの取り込み・ファイルでの登録。0003・0037 を差し替え、引数 p_options を足す）。\n-- 登録と結びつけを 1 回で行う（途中で落ちて、結べていない画像が残らないように）。{}（既定）は商品全体（対応表があればトリガーが写す）\ndrop function if exists api_image_add(text, uuid, text, integer);\ncreate or replace function api_image_add(p_token_hash text, p_product_id uuid, p_storage_key text, p_sort_order integer default null, p_options jsonb default '{}'::jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_sort integer;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  if not banto_image_options_ok(coalesce(p_options, 'null'::jsonb)) then raise exception 'invalid_options'; end if;\n  if not exists (select 1 from products where id = p_product_id and shop_id = v_tok.shop_id) then raise exception 'not_found'; end if;\n  if p_storage_key !~ ('^shops/' || v_tok.shop_id::text || '/') then raise exception 'invalid_storage_key'; end if;\n  select coalesce(p_sort_order, coalesce(max(sort_order), -1) + 1) into v_sort from product_images where product_id = p_product_id;\n  insert into product_images (shop_id, product_id, storage_key, sort_order, options) values (v_tok.shop_id, p_product_id, p_storage_key, v_sort, p_options);\n  return api_product_get(p_token_hash, p_product_id);\nend;\n$$;\nrevoke execute on function api_image_add(text, uuid, text, integer, jsonb) from public, anon, authenticated;\ngrant execute on function api_image_add(text, uuid, text, integer, jsonb) to service_role;\n\ndrop function if exists api_image_add_file(text, uuid, text, text, integer, integer);\ncreate or replace function api_image_add_file(p_token_hash text, p_product_id uuid, p_storage_key text,\n                                              p_thumb_key text default null, p_width integer default null, p_height integer default null,\n                                              p_options jsonb default '{}'::jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_sort integer; v_prefix text; v_id uuid;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  if not banto_image_options_ok(coalesce(p_options, 'null'::jsonb)) then raise exception 'invalid_options'; end if;\n  if not exists (select 1 from products where id = p_product_id and shop_id = v_tok.shop_id) then raise exception 'not_found'; end if;\n  v_prefix := 'shops/' || v_tok.shop_id::text || '/products/' || p_product_id::text || '/';\n  if p_storage_key is null or left(p_storage_key, length(v_prefix)) <> v_prefix\n     or substr(p_storage_key, length(v_prefix) + 1) !~ '^[0-9a-f]{24}\\.(jpg|png|webp|gif|avif)$' then\n    raise exception 'invalid_storage_key';\n  end if;\n  if p_thumb_key is not null and (left(p_thumb_key, length(v_prefix)) <> v_prefix\n     or substr(p_thumb_key, length(v_prefix) + 1) !~ ('^' || substr(p_storage_key, length(v_prefix) + 1, 24) || '\\.thumb\\.(jpg|png|webp|gif|avif)$')) then\n    raise exception 'invalid_thumb_key';\n  end if;\n  if (p_width is null) <> (p_height is null) or p_width not between 1 and 20000 or p_height not between 1 and 20000 then\n    raise exception 'invalid_dimensions';\n  end if;\n  select coalesce(max(sort_order), -1) + 1 into v_sort from product_images where product_id = p_product_id;\n  insert into product_images (shop_id, product_id, storage_key, thumb_key, width, height, sort_order, options)\n  values (v_tok.shop_id, p_product_id, p_storage_key, p_thumb_key, p_width, p_height, v_sort, p_options)\n  returning id into v_id;\n  -- products:write だけのトークンでも結果を返せるよう、api_product_get（products:read）ではなく整形だけを使う\n  return jsonb_build_object('image_id', v_id, 'product', (select api_product_json(p) from products p where p.id = p_product_id));\nend;\n$$;\nrevoke execute on function api_image_add_file(text, uuid, text, text, integer, integer, jsonb) from public, anon, authenticated;\ngrant execute on function api_image_add_file(text, uuid, text, text, integer, integer, jsonb) to service_role;\n\n-- ---------- 復元: restore_shop_data（0012）は options を知らないので、あとから写す ----------\n-- p_items = [{ storage_key, options }]。そのショップの、同じキーの画像に写す（1 回 5,000 件まで）\ncreate or replace function restore_product_image_options(p_shop_id uuid, p_items jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_item jsonb; v_n integer := 0; v_hit integer;\nbegin\n  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 5000 then raise exception 'invalid_items'; end if;\n  for v_item in select e from jsonb_array_elements(p_items) e loop\n    if jsonb_typeof(v_item) <> 'object' or jsonb_typeof(v_item->'storage_key') <> 'string'\n       or not banto_image_options_ok(coalesce(v_item->'options', 'null'::jsonb)) or v_item->'options' = '{}'::jsonb then\n      continue;\n    end if;\n    update product_images set options = v_item->'options' where shop_id = p_shop_id and storage_key = v_item->>'storage_key';\n    get diagnostics v_hit = row_count;\n    v_n := v_n + v_hit;\n  end loop;\n  return jsonb_build_object('product_image_options', v_n);\nend;\n$$;\nrevoke execute on function restore_product_image_options(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function restore_product_image_options(uuid, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0063_sku_images');\n" },
  { version: "0064_inquiry_api_attachments", sql: "-- Banto 0064_inquiry_api_attachments: AI 用 API（/api/v1）でお問い合わせの添付を扱う（人間の決定 2026-10-27）。前方専用。\n--   - 返事に添付する: api_inquiry_reply に p_attachments（管理画面の inquiry_reply と同じ形・同じ上限。banto_inquiry_attach が確かめる）\n--   - お客様の添付を受け取る: api_inquiry_attachment_get。inquiries:read に加えて orders:pii が要る\n--     （添付は写真・書類で、連絡先と同じく個人情報を含みうる。0061 でファイル名を orders:pii のときだけ返すのと同じ線）\n--   - 実体は Worker が公開しない置き場（privateStorage）に置き・配る。ここは行と権限だけ\n\ndrop function if exists api_inquiry_reply(text, integer, text, text);\ncreate or replace function api_inquiry_reply(p_token_hash text, p_number integer, p_body text, p_link_hash text, p_attachments jsonb default '[]'::jsonb)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_tok api_tokens; v_i inquiries%rowtype; v_body text := left(btrim(coalesce(p_body, '')), 5000); v_send boolean := false; v_s shops%rowtype; v_msg uuid;\nbegin\n  v_tok := banto_api_inquiries_require(p_token_hash, 'inquiries:write');\n  select * into v_i from inquiries where shop_id = v_tok.shop_id and number = p_number for update;\n  if not found then raise exception 'not_found'; end if;\n  if v_i.masked_at is not null then raise exception 'inquiry_masked'; end if;\n  if length(v_body) = 0 then raise exception 'invalid_body'; end if;\n  if coalesce(p_link_hash, '') !~ '^[0-9a-f]{64}$' then raise exception 'invalid_link'; end if;\n  insert into inquiry_messages (shop_id, inquiry_id, author, body) values (v_i.shop_id, v_i.id, 'shop', v_body) returning id into v_msg;\n  perform banto_inquiry_attach(v_i.shop_id, v_i.id, v_msg, p_attachments);\n  update inquiries set status = 'waiting_customer', last_message_at = now(), updated_at = now(), closed_at = null where id = v_i.id;\n  insert into inquiry_links (shop_id, inquiry_id, token_hash, expires_at) values (v_i.shop_id, v_i.id, p_link_hash, now() + interval '30 days');\n  if v_i.contact_email is not null then v_send := banto_inquiry_issue_mail(v_i.shop_id, v_i.id, 'reply', v_i.contact_email); end if;\n  perform banto_enqueue_inquiry_hook(v_i.shop_id, 'inquiry.updated',\n    jsonb_build_object('inquiry_id', v_i.id, 'number', v_i.number, 'shop_id', v_i.shop_id, 'status', 'waiting_customer', 'change', 'message', 'author', 'shop'));\n  select * into v_i from inquiries where id = v_i.id;\n  select * into v_s from shops where id = v_i.shop_id;\n  return jsonb_build_object(\n    'inquiry', api_inquiry_json(v_i, 'orders:pii' = any(v_tok.scopes), true),\n    'mail', jsonb_build_object('send', v_send, 'to', case when v_send then v_i.contact_email end, 'mail_from', banto_inquiry_mail_from(v_i.shop_id),\n                               'return_to', v_i.return_to,\n                               'shop', jsonb_build_object('id', v_s.id, 'name', v_s.name, 'slug', v_s.slug, 'domain', v_s.domain,\n                                                          'settings', jsonb_build_object('theme_settings', v_s.settings->'theme_settings', 'headless', v_s.settings->'headless'))));\nend;\n$$;\nrevoke execute on function api_inquiry_reply(text, integer, text, text, jsonb) from public, anon, authenticated;\ngrant execute on function api_inquiry_reply(text, integer, text, text, jsonb) to service_role;\n\n-- 添付を受け取る（そのショップの、その受付番号のチケットの添付だけ）。戻り値: { storage_key, content_type, filename, size }\ncreate or replace function api_inquiry_attachment_get(p_token_hash text, p_number integer, p_attachment_id uuid)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_tok api_tokens; v_r jsonb;\nbegin\n  v_tok := banto_api_inquiries_require(p_token_hash, 'inquiries:read');\n  if not ('orders:pii' = any(v_tok.scopes)) then raise exception 'pii_scope_required'; end if;\n  select jsonb_build_object('storage_key', a.storage_key, 'content_type', a.content_type, 'filename', a.filename, 'size', a.size) into v_r\n    from inquiry_attachments a join inquiries i on i.id = a.inquiry_id\n   where a.id = p_attachment_id and i.shop_id = v_tok.shop_id and i.number = p_number;\n  if v_r is null then raise exception 'not_found'; end if;\n  return v_r;\nend;\n$$;\nrevoke execute on function api_inquiry_attachment_get(text, integer, uuid) from public, anon, authenticated;\ngrant execute on function api_inquiry_attachment_get(text, integer, uuid) to service_role;\n\ninsert into banto_migrations (version) values ('0064_inquiry_api_attachments');\n" },
  { version: "0065_sku_option_axes", sql: "-- Banto 0065_sku_option_axes: SKU を分ける軸（人間の決定 2026-10-28）。前方専用。\n--   - 形: [{ \"key\": \"カラー\", \"values\": [\"レッド\", ...] }, ...]（3 つまで、鍵は重ならない）。[] = 品番だけ（SKU の options は空）。\n--     null = 決めていない（今までどおり SKU の options は自由。既存の商品・取り込んだ商品）\n--   - 決める場所はショップ → カテゴリー（親から子へ）→ 商品。上の段は「ひな形」で、商品を作ったとき・主カテゴリーを決めたとき\n--     （SKU がまだ無く、商品で上書きしていないとき）に商品へ写す。あとで上の段を変えても、既存の商品は変わらない\n--   - 守るのは DB: 軸を決めた商品の SKU は options の鍵が軸とちょうど同じで値が空でない・同じ組み合わせの SKU は 1 つだけ。\n--     商品の軸を変えるときは、今の SKU が新しい軸に合わなければ断る\n--   - 値の候補（values）は入力と一括作成のためで、守らない（候補に無い値も入れられる）\n\ncreate or replace function banto_option_axes_ok(p jsonb)\nreturns boolean language sql immutable as $$\n  select p is null or (\n    jsonb_typeof(p) = 'array' and jsonb_array_length(p) <= 3\n    and not exists (\n      select 1 from jsonb_array_elements(p) a\n       where jsonb_typeof(a) <> 'object'\n          or jsonb_typeof(a->'key') <> 'string' or length(a->>'key') not between 1 and 40 or btrim(a->>'key') <> a->>'key'\n          or exists (select 1 from jsonb_object_keys(a) k where k not in ('key', 'values'))\n          or (a ? 'values' and (jsonb_typeof(a->'values') <> 'array' or jsonb_array_length(a->'values') > 100\n              or exists (select 1 from jsonb_array_elements(a->'values') v where jsonb_typeof(v) <> 'string' or length(v #>> '{}') not between 1 and 60))))\n    and (select count(distinct a->>'key') from jsonb_array_elements(p) a) = jsonb_array_length(p));\n$$;\n-- 列の CHECK で呼ぶので、行を書くロール（管理画面の authenticated）に EXECUTE が要る（中身は値の形を見るだけ）\nrevoke execute on function banto_option_axes_ok(jsonb) from public, anon;\ngrant execute on function banto_option_axes_ok(jsonb) to authenticated, service_role;\n\nalter table shops add column if not exists option_axes jsonb;\nalter table shops drop constraint if exists shops_option_axes_check;\nalter table shops add constraint shops_option_axes_check check (banto_option_axes_ok(option_axes));\nalter table categories add column if not exists option_axes jsonb;\nalter table categories drop constraint if exists categories_option_axes_check;\nalter table categories add constraint categories_option_axes_check check (banto_option_axes_ok(option_axes));\nalter table products add column if not exists option_axes jsonb;\nalter table products add column if not exists option_axes_custom boolean not null default false;\nalter table products drop constraint if exists products_option_axes_check;\nalter table products add constraint products_option_axes_check check (banto_option_axes_ok(option_axes));\n\n-- SKU の options が軸に合うか（鍵がちょうど同じ・値が空でない）\ncreate or replace function banto_sku_fits_axes(p_options jsonb, p_axes jsonb)\nreturns boolean language sql immutable as $$\n  select (select coalesce(array_agg(k order by k), '{}'::text[]) from jsonb_object_keys(coalesce(p_options, '{}'::jsonb)) k)\n       = (select coalesce(array_agg(a->>'key' order by a->>'key'), '{}'::text[]) from jsonb_array_elements(p_axes) a)\n     and not exists (select 1 from jsonb_each(coalesce(p_options, '{}'::jsonb)) e where coalesce(btrim(e.value #>> '{}'), '') = '');\n$$;\nrevoke execute on function banto_sku_fits_axes(jsonb, jsonb) from public, anon, authenticated;\n\n-- 主カテゴリーから上へたどり、最初に決めてある軸。どこにも無ければショップの軸（null もありうる）\ncreate or replace function banto_option_axes_resolve(p_shop_id uuid, p_category_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\ndeclare v_cat uuid := p_category_id; v_axes jsonb; v_parent uuid; v_i integer := 0;\nbegin\n  while v_cat is not null and v_i < 10 loop\n    select option_axes, parent_id into v_axes, v_parent from categories where id = v_cat and shop_id = p_shop_id;\n    if not found then exit; end if;\n    if v_axes is not null then return v_axes; end if;\n    v_cat := v_parent;\n    v_i := v_i + 1;\n  end loop;\n  return (select option_axes from shops where id = p_shop_id);\nend;\n$$;\nrevoke execute on function banto_option_axes_resolve(uuid, uuid) from public, anon, authenticated;\n\n-- 商品: 作ったとき・主カテゴリーを変えたとき（SKU がまだ無く、上書きしていない）に上の段の軸を写す。軸を変えるときは今の SKU を確かめる\ncreate or replace function banto_product_option_axes()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if tg_op = 'INSERT' then\n    -- WooCommerce の取り込み（import_catalog）は写さない（属性の鍵が軸と合わないと取り込みが止まるため）\n    if new.option_axes is null and not new.option_axes_custom and coalesce(current_setting('banto.skip_option_axes', true), '') <> 'on' then\n      new.option_axes := banto_option_axes_resolve(new.shop_id, new.category_id);\n    end if;\n    return new;\n  end if;\n  if new.category_id is distinct from old.category_id and not new.option_axes_custom and new.option_axes is not distinct from old.option_axes\n     and not exists (select 1 from skus where product_id = new.id)\n     and coalesce(current_setting('banto.skip_option_axes', true), '') <> 'on' then\n    new.option_axes := banto_option_axes_resolve(new.shop_id, new.category_id);\n  end if;\n  if new.option_axes is distinct from old.option_axes and new.option_axes is not null then\n    if exists (select 1 from skus k where k.product_id = new.id and not banto_sku_fits_axes(k.options, new.option_axes)) then\n      raise exception 'option_axes_mismatch';\n    end if;\n    if jsonb_array_length(new.option_axes) > 0 and exists (select 1 from skus k where k.product_id = new.id group by k.options having count(*) > 1) then\n      raise exception 'option_combination_exists';\n    end if;\n  end if;\n  return new;\nend;\n$$;\nrevoke execute on function banto_product_option_axes() from public, anon, authenticated;\ndrop trigger if exists products_option_axes on products;\ncreate trigger products_option_axes before insert or update of category_id, option_axes on products for each row execute function banto_product_option_axes();\n\n-- SKU: 軸を決めた商品なら options が軸に合うこと・同じ組み合わせが無いこと（品番だけ [] の商品は組み合わせを確かめない）\ncreate or replace function banto_sku_option_axes()\nreturns trigger language plpgsql security definer set search_path = public as $$\ndeclare v_axes jsonb;\nbegin\n  -- 同じ商品の SKU を同時に足したときに、重なりの確かめをすり抜けないよう商品の行で順番にする\n  select option_axes into v_axes from products where id = new.product_id for update;\n  if v_axes is null then return new; end if;\n  if not banto_sku_fits_axes(new.options, v_axes) then raise exception 'option_axes_mismatch'; end if;\n  if jsonb_array_length(v_axes) > 0 and exists (select 1 from skus k where k.product_id = new.product_id and k.id <> new.id and k.options = new.options) then\n    raise exception 'option_combination_exists';\n  end if;\n  return new;\nend;\n$$;\nrevoke execute on function banto_sku_option_axes() from public, anon, authenticated;\ndrop trigger if exists skus_option_axes on skus;\ncreate trigger skus_option_axes before insert or update of options, product_id on skus for each row execute function banto_sku_option_axes();\n\n-- 取り込み（0042 の import_catalog）を包み、取り込みの間は軸を写さない。中身は 0042 のまま\nalter function import_catalog(uuid, jsonb) rename to banto_import_catalog_0042;\nrevoke execute on function banto_import_catalog_0042(uuid, jsonb) from public, anon, authenticated, service_role;\ncreate or replace function import_catalog(p_shop_id uuid, p_batch jsonb)\nreturns jsonb language plpgsql security definer set search_path = public as $$\nbegin\n  perform set_config('banto.skip_option_axes', 'on', true);\n  return banto_import_catalog_0042(p_shop_id, p_batch);\nend;\n$$;\nrevoke execute on function import_catalog(uuid, jsonb) from public, anon;\ngrant execute on function import_catalog(uuid, jsonb) to authenticated, service_role;\n\n-- 上の段（ショップか、カテゴリーとその子孫）の軸を、上書きしていない商品に当てる（catalog の項目）。\n-- 当てる軸は商品ごとに主カテゴリーから引き直す（子のカテゴリーで別の軸を決めていればそちら）。SKU が合わない商品は飛ばして返す\ncreate or replace function option_axes_apply(p_shop_id uuid, p_category_id uuid default null)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_p record; v_axes jsonb; v_applied integer := 0; v_same integer := 0; v_skipped jsonb := '[]'::jsonb;\nbegin\n  if not banto_shop_perm(p_shop_id, 'catalog') then raise exception 'forbidden' using errcode = '42501'; end if;\n  if p_category_id is not null and not exists (select 1 from categories where id = p_category_id and shop_id = p_shop_id) then raise exception 'not_found'; end if;\n  for v_p in\n    with recursive tree(id) as (\n      select id from categories where id = p_category_id\n      union all select c.id from categories c join tree t on c.parent_id = t.id where c.shop_id = p_shop_id\n    )\n    select p.id, p.slug, p.category_id, p.option_axes from products p\n     where p.shop_id = p_shop_id and not p.option_axes_custom\n       and (p_category_id is null or p.category_id in (select id from tree))\n     order by p.created_at\n  loop\n    v_axes := banto_option_axes_resolve(p_shop_id, v_p.category_id);\n    if v_axes is not distinct from v_p.option_axes then v_same := v_same + 1; continue; end if;\n    begin\n      update products set option_axes = v_axes where id = v_p.id;\n      v_applied := v_applied + 1;\n    exception when raise_exception then\n      if jsonb_array_length(v_skipped) < 100 then v_skipped := v_skipped || jsonb_build_object('slug', v_p.slug, 'reason', sqlerrm); end if;\n    end;\n  end loop;\n  return jsonb_build_object('applied', v_applied, 'unchanged', v_same, 'skipped', v_skipped);\nend;\n$$;\nrevoke execute on function option_axes_apply(uuid, uuid) from public, anon;\ngrant execute on function option_axes_apply(uuid, uuid) to authenticated, service_role;\n\n-- ---------- AI 用 API ----------\n-- 商品の JSON に軸を足す（0063 を差し替え。ほかは同じ）\ncreate or replace function api_product_json(p_product products, p_with_skus boolean default true)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'id', p_product.id, 'slug', p_product.slug, 'name', p_product.name, 'description', p_product.description,\n    'tags', to_jsonb(p_product.tags), 'brand', p_product.brand, 'attributes', p_product.attributes,\n    'category', (select api_category_json(c) from categories c where c.id = p_product.category_id),\n    'extra_categories', (select coalesce(jsonb_agg(api_category_json(c) order by x.ord), '[]'::jsonb)\n                           from unnest(p_product.extra_category_ids) with ordinality x(id, ord) join categories c on c.id = x.id),\n    'option_axes', p_product.option_axes,\n    'published', p_product.published, 'created_at', p_product.created_at, 'updated_at', p_product.updated_at,\n    'images', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'storage_key', i.storage_key, 'thumb_key', i.thumb_key,\n                                                             'width', i.width, 'height', i.height, 'sort_order', i.sort_order,\n                                                             'options', i.options) order by i.sort_order), '[]'::jsonb)\n                 from product_images i where i.product_id = p_product.id),\n    'skus', case when p_with_skus then\n      (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'code', k.code, 'name', k.name, 'price_jpy', k.price_jpy,\n                                                     'compare_at_price_jpy', k.compare_at_price_jpy, 'options', k.options, 'gtin', k.gtin,\n                                                     'available', coalesce(inv.available, 0)) order by k.created_at), '[]'::jsonb)\n         from skus k left join inventory inv on inv.sku_id = k.id where k.product_id = p_product.id)\n      else null end\n  );\n$$;\n\n-- 商品の軸を決める（products:write）。null で「決めない」（自由）に戻す。商品で上書きした扱いになる。返すのは商品\ncreate or replace function api_product_set_option_axes(p_token_hash text, p_product_id uuid, p_axes jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_tok api_tokens; v_axes jsonb := case when p_axes is null or jsonb_typeof(p_axes) = 'null' then null else p_axes end;\nbegin\n  v_tok := api_require(p_token_hash, 'products:write');\n  if not banto_option_axes_ok(v_axes) then raise exception 'invalid_option_axes'; end if;\n  update products set option_axes = v_axes, option_axes_custom = v_axes is not null where id = p_product_id and shop_id = v_tok.shop_id;\n  if not found then raise exception 'not_found'; end if;\n  return api_product_get(p_token_hash, p_product_id);\nend;\n$$;\nrevoke execute on function api_product_set_option_axes(text, uuid, jsonb) from public, anon, authenticated;\ngrant execute on function api_product_set_option_axes(text, uuid, jsonb) to service_role;\n\n-- ---------- 復元: restore_shop_data（0012）は軸を知らないので、あとから写す ----------\n-- p_data = { shop: axes | null, categories: [{ slug, option_axes }], products: [{ slug, option_axes, option_axes_custom }] }。\n-- 商品の軸は SKU を戻した後に当てる（合わない商品は飛ばす）\ncreate or replace function restore_option_axes(p_shop_id uuid, p_data jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_item jsonb; v_c integer := 0; v_p integer := 0; v_skip integer := 0;\nbegin\n  if jsonb_typeof(p_data) <> 'object' then raise exception 'invalid_items'; end if;\n  if p_data ? 'shop' and banto_option_axes_ok(case when jsonb_typeof(p_data->'shop') = 'null' then null else p_data->'shop' end) then\n    update shops set option_axes = case when jsonb_typeof(p_data->'shop') = 'null' then null else p_data->'shop' end where id = p_shop_id;\n  end if;\n  for v_item in select e from jsonb_array_elements(case when jsonb_typeof(p_data->'categories') = 'array' then p_data->'categories' else '[]'::jsonb end) e limit 5000 loop\n    if jsonb_typeof(v_item->'option_axes') is distinct from 'array' or not banto_option_axes_ok(v_item->'option_axes') then continue; end if;\n    update categories set option_axes = v_item->'option_axes' where shop_id = p_shop_id and slug = v_item->>'slug';\n    if found then v_c := v_c + 1; end if;\n  end loop;\n  for v_item in select e from jsonb_array_elements(case when jsonb_typeof(p_data->'products') = 'array' then p_data->'products' else '[]'::jsonb end) e limit 50000 loop\n    if jsonb_typeof(v_item->'option_axes') is distinct from 'array' or not banto_option_axes_ok(v_item->'option_axes') then continue; end if;\n    begin\n      update products set option_axes = v_item->'option_axes', option_axes_custom = coalesce((v_item->>'option_axes_custom')::boolean, false)\n       where shop_id = p_shop_id and slug = v_item->>'slug';\n      if found then v_p := v_p + 1; end if;\n    exception when raise_exception or invalid_text_representation then\n      v_skip := v_skip + 1;\n    end;\n  end loop;\n  return jsonb_build_object('option_axes_categories', v_c, 'option_axes_products', v_p, 'option_axes_skipped', v_skip);\nend;\n$$;\nrevoke execute on function restore_option_axes(uuid, jsonb) from public, anon, authenticated;\ngrant execute on function restore_option_axes(uuid, jsonb) to service_role;\n\ninsert into banto_migrations (version) values ('0065_sku_option_axes');\n" },
  { version: "0066_headless_order_lookup", sql: "-- Banto 0066_headless_order_lookup: 注文照会・領収書をヘッドレスで（人間の決定 2026-10-28）。前方専用。\n--   - Banto はデータ（JSON）だけを渡し、レイアウト・印刷の体裁は連携サイトが決める\n--   - 注文照会のページ（連携サイト）は shops.settings.headless.order_page_url（許可リストのオリジンの https。確かめるのは Worker の保存）。\n--     注文メールのリンク（?banto_order=<番号>&banto_member=1）と、Banto の注文照会の画面の転送先に使う\n--   - 会員の注文は会員トークンで（member_order、0023）、ゲストの注文は番号とメールアドレスで（lookup_order、今までどおり）\n\n-- 注文の中身（lookup_order と会員の注文で同じ形。住所・アドレスは入れない）\ncreate or replace function banto_order_view(p_o orders)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select jsonb_build_object('number', p_o.number, 'status', p_o.status, 'created_at', p_o.created_at, 'shipped_at', p_o.shipped_at,\n                            'total_jpy', p_o.total_jpy, 'shipping_jpy', p_o.shipping_jpy, 'discount_jpy', p_o.discount_jpy,\n                            'shipping_tax_rate', p_o.shipping_tax_rate, 'tax_rounding', p_o.tax_rounding, 'payment_provider', p_o.payment_provider,\n                            'tracking', case when p_o.tracking_number is not null then jsonb_build_object('carrier', p_o.tracking_carrier, 'number', p_o.tracking_number) end,\n                            'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                                            from jsonb_array_elements(coalesce(p_o.discounts, '[]'::jsonb)) d),\n                            'items', (select coalesce(jsonb_agg(jsonb_build_object('name', coalesce(oi.item_name, p.name), 'sku', coalesce(oi.item_variant, k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy, 'tax_rate', oi.tax_rate, 'discount_jpy', oi.discount_jpy) order by oi.id), '[]'::jsonb)\n                                        from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = p_o.id));\n$$;\nrevoke execute on function banto_order_view(orders) from public, anon, authenticated;\n\n-- ゲストの注文照会（0023 を差し替え。中身は banto_order_view にまとめただけで、形は同じ）\ncreate or replace function lookup_order(p_shop_id uuid, p_number integer, p_email text)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select banto_order_view(o)\n    from orders o join shops s on s.id = o.shop_id\n   where o.shop_id = p_shop_id and o.number = p_number and s.published\n     and o.customer_email is not null and lower(o.customer_email) = lower(btrim(p_email))\n   limit 1;\n$$;\nrevoke execute on function lookup_order(uuid, integer, text) from public;\ngrant execute on function lookup_order(uuid, integer, text) to anon, authenticated, service_role;\n\n-- 会員の注文（0023 を差し替え。その会員の注文だけ・世代を確かめる。中身は banto_order_view にまとめただけで、形は同じ）\ncreate or replace function member_order(p_shop_id uuid, p_customer_id uuid, p_epoch integer, p_number integer)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare v_o orders%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'member_order: service_role only' using errcode = '42501';\n  end if;\n  if not exists (select 1 from customers where shop_id = p_shop_id and id = p_customer_id and session_epoch = p_epoch) then return null; end if;\n  select * into v_o from orders where shop_id = p_shop_id and customer_id = p_customer_id and number = p_number;\n  if not found then return null; end if;\n  return banto_order_view(v_o);\nend;\n$$;\nrevoke execute on function member_order(uuid, uuid, integer, integer) from public, anon, authenticated;\ngrant execute on function member_order(uuid, uuid, integer, integer) to service_role;\n\n-- 注文メールの材料（0022 を差し替え: 会員の注文か・注文照会のページ・許可リストを足す）\ncreate or replace function order_contact(p_order_id uuid, p_shop_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare v_o orders%rowtype; v_s shops%rowtype;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'order_contact: service_role only' using errcode = '42501';\n  end if;\n  select * into v_o from orders where id = p_order_id and shop_id = p_shop_id;\n  if not found then raise exception 'not_found'; end if;\n  select * into v_s from shops where id = p_shop_id;\n  return jsonb_build_object(\n    'order_id', v_o.id, 'number', v_o.number, 'status', v_o.status, 'created_at', v_o.created_at,\n    'total_jpy', v_o.total_jpy, 'shipping_jpy', v_o.shipping_jpy, 'discount_jpy', v_o.discount_jpy, 'payment_provider', v_o.payment_provider,\n    'shipping_tax_rate', v_o.shipping_tax_rate, 'tax_rounding', v_o.tax_rounding,\n    'tracking', case when v_o.tracking_number is not null then jsonb_build_object('carrier', v_o.tracking_carrier, 'number', v_o.tracking_number) end,\n    'discounts', (select coalesce(jsonb_agg(jsonb_build_object('code', d->>'code', 'name', d->>'name', 'amount_jpy', (d->>'amount_jpy')::integer)), '[]'::jsonb)\n                    from jsonb_array_elements(coalesce(v_o.discounts, '[]'::jsonb)) d),\n    'customer_email', v_o.customer_email, 'customer_name', v_o.customer_name, 'shipping_address', v_o.shipping_address,\n    -- 0066: 会員の注文か（メールのリンクの目印）と、注文照会のページ（連携サイト）。どちらも鍵ではない\n    'member', v_o.customer_id is not null,\n    'shop', jsonb_build_object('name', v_s.name, 'slug', v_s.slug, 'domain', v_s.domain,\n                               'order_page_url', v_s.settings->'headless'->>'order_page_url',\n                               'return_origins', coalesce(v_s.settings->'headless'->'return_origins', '[]'::jsonb),\n                               'contact_email', v_s.settings->>'contact_email', 'return_policy', v_s.return_policy,\n                               'tax', jsonb_build_object('tax_rate', v_s.settings->'tax_rate', 'tax_rate_reduced', v_s.settings->'tax_rate_reduced', 'tax_rounding', v_s.settings->'tax_rounding')),\n    'items', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'sku', coalesce(k.name, k.code), 'qty', oi.qty, 'unit_price_jpy', oi.unit_price_jpy,\n                                                           'tax_rate', oi.tax_rate, 'discount_jpy', oi.discount_jpy) order by oi.id), '[]'::jsonb)\n                from order_items oi left join skus k on k.id = oi.sku_id left join products p on p.id = k.product_id where oi.order_id = v_o.id));\nend;\n$$;\n\n-- 公開の settings に注文照会のページを出す（0055 を差し替え。お客様の画面の転送に使う。鍵ではない）\ncreate or replace function banto_shop_public_settings(p jsonb)\nreturns jsonb language sql immutable as $$\n  select coalesce((select jsonb_object_agg(k, v) from jsonb_each(case when jsonb_typeof(p) = 'object' then p else '{}'::jsonb end) e(k, v)\n                    where k in ('theme', 'theme_settings', 'notice', 'shipping', 'modules', 'members_enabled', 'members_password',\n                                'checkout_terms', 'delivery_time', 'store_tryon', 'receipt',\n                                'tax_rate', 'tax_rate_reduced', 'tax_rounding', 'storefront', 'analytics', 'marketing_consent')), '{}'::jsonb)\n      || case when jsonb_typeof(p->'product_fields') = 'array'\n              then jsonb_build_object('product_fields', coalesce((select jsonb_agg(f) from jsonb_array_elements(p->'product_fields') f\n                                                                    where jsonb_typeof(f) = 'object' and f->'public' is distinct from 'false'::jsonb), '[]'::jsonb))\n              else '{}'::jsonb end\n      || case when jsonb_typeof(p->'headless') = 'object'\n              then jsonb_build_object('headless', jsonb_build_object('return_origins', coalesce(p->'headless'->'return_origins', '[]'::jsonb))\n                                                || case when jsonb_typeof(p->'headless'->'order_page_url') = 'string'\n                                                        then jsonb_build_object('order_page_url', p->'headless'->'order_page_url') else '{}'::jsonb end)\n              else '{}'::jsonb end\n      || case when jsonb_typeof(p->'oauth') = 'object'\n              then jsonb_build_object('oauth', coalesce((\n                     select jsonb_object_agg(k, coalesce((select jsonb_object_agg(k2, v2) from jsonb_each(v) f(k2, v2) where k2 in ('client_id', 'bot_prompt')), '{}'::jsonb))\n                       from jsonb_each(p->'oauth') e(k, v) where jsonb_typeof(v) = 'object'), '{}'::jsonb))\n              else '{}'::jsonb end;\n$$;\nrevoke execute on function banto_shop_public_settings(jsonb) from public, anon, authenticated;\n\ninsert into banto_migrations (version) values ('0066_headless_order_lookup');\n" },
  { version: "0067_order_lookup_limits", sql: "-- Banto 0067_order_lookup_limits: ゲストの注文照会に回数の上限（人間の決定 2026-10-28）。前方専用。\n--   - lookup_order は anon キー（公開の値）で直接呼べたので、Worker で数えても PostgREST を直接叩けば上限が無かった。\n--     anon・authenticated から実行の権限を外し、Worker が service_role で order_lookup を呼ぶ形にする\n--   - 数えるのは外れた照会だけ（合った照会は数えない）。同じ IP から 1 時間に settings.order_lookup.per_ip_per_hour 回（既定 20）、\n--     同じ注文番号へ 1 時間に 50 回（IP を変えて 1 つの注文のアドレスを当てに行くのを止める。数えるのは外れだけなので、\n--     第三者が外し続けてもその注文の照会が止まるのは 1 時間だけ）\n--   - IP は Worker の HMAC だけ（素の IP は置かない）。1 日より古い行は外れを数えるついでに消す\n\ncreate table if not exists order_lookup_failures (\n  id bigserial primary key,\n  shop_id uuid not null references shops(id) on delete cascade,\n  number integer not null,\n  ip_hash text check (ip_hash ~ '^[0-9a-f]{64}$'),\n  created_at timestamptz not null default now()\n);\ncreate index if not exists order_lookup_failures_ip on order_lookup_failures (shop_id, ip_hash, created_at) where ip_hash is not null;\ncreate index if not exists order_lookup_failures_number on order_lookup_failures (shop_id, number, created_at);\ncreate index if not exists order_lookup_failures_created on order_lookup_failures (created_at);\nalter table order_lookup_failures enable row level security;\ncreate policy order_lookup_failures_none on order_lookup_failures for select using (false);\nrevoke all on order_lookup_failures from anon, authenticated;\n\n-- 注文照会（ゲスト）: 番号とメールアドレスが合えば lookup_order と同じ形。合わなければ null（どちらが違うかは返さない）。\n-- 上限を超えていれば too_many_requests（detail = ip / order）。合ったかどうかを確かめる前に判定する\ncreate or replace function order_lookup(p_shop_id uuid, p_number integer, p_email text, p_ip_hash text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_ip text := case when p_ip_hash ~ '^[0-9a-f]{64}$' then p_ip_hash end;\n  v_r jsonb;\nbegin\n  if auth.role() is distinct from 'service_role' then\n    raise exception 'order_lookup: service_role only' using errcode = '42501';\n  end if;\n  if v_ip is not null and (select count(*) from order_lookup_failures f where f.shop_id = p_shop_id and f.ip_hash = v_ip and f.created_at > now() - interval '1 hour')\n       >= banto_shop_limit(p_shop_id, 'order_lookup', 'per_ip_per_hour', 20) then\n    raise exception 'too_many_requests' using detail = 'ip';\n  end if;\n  if (select count(*) from order_lookup_failures f where f.shop_id = p_shop_id and f.number = p_number and f.created_at > now() - interval '1 hour') >= 50 then\n    raise exception 'too_many_requests' using detail = 'order';\n  end if;\n  v_r := lookup_order(p_shop_id, p_number, p_email);\n  if v_r is null then\n    delete from order_lookup_failures where created_at < now() - interval '1 day';\n    insert into order_lookup_failures (shop_id, number, ip_hash) values (p_shop_id, p_number, v_ip);\n  end if;\n  return v_r;\nend;\n$$;\nrevoke execute on function order_lookup(uuid, integer, text, text) from public, anon, authenticated;\ngrant execute on function order_lookup(uuid, integer, text, text) to service_role;\n\n-- lookup_order は service_role だけ（order_lookup と、注文トークンで引き直す領収書の経路）\nrevoke execute on function lookup_order(uuid, integer, text) from public, anon, authenticated;\ngrant execute on function lookup_order(uuid, integer, text) to service_role;\n\ninsert into banto_migrations (version) values ('0067_order_lookup_limits');\n" },
  { version: "0068_mod_inquiries_assignee", sql: "-- Banto 0068_mod_inquiries_assignee: お問い合わせの担当者（同梱モジュール inquiries、人間の決定 2026-10-28）。前方専用。\n--   - 担当者にできるのは、そのショップの support の項目を持つ人（組織の owner / admin、組織の無いショップは owner）。判定は banto_user_shop_perm\n--   - 割り当ては運営者（support の項目）と AI 用トークン（inquiries:write）。担当になった本人に、チケットへのリンクだけのメールで知らせる\n--     （本文は載せない。自分で自分に割り当てたときは送らない）。メールの回数は banto_inquiry_issue_mail の上限に入る（kind = 'assign'）\n--   - 未割り当てのチケットに運営者が最初に返事をしたら、その人を担当にする（inquiry_messages のトリガー。AI 用トークンの返事は人ではないので当てない）\n--   - 担当者が support の項目を失っても、割り当ては残す（画面で付け替える）。運営者のアカウントが消えたら外れる（on delete set null）\n--   - お客様には担当者を見せない。hooks の inquiry.updated は change = 'assignee'（担当者の id もアドレスも載せない）\n--   - バックアップの復元では担当者を戻さない（運営者のアカウントはデプロイごとに違うため）\n\nalter table inquiries add column if not exists assignee_id uuid references auth.users(id) on delete set null;\ncreate index if not exists inquiries_assignee on inquiries(shop_id, assignee_id, last_message_at desc) where assignee_id is not null;\n\nalter table inquiry_mails drop constraint if exists inquiry_mails_kind_check;\nalter table inquiry_mails add constraint inquiry_mails_kind_check check (kind in ('verify', 'created', 'reply', 'link', 'shop', 'assign'));\n\n-- 担当者にできる人（そのショップの support の項目を持つ人）。運営者の画面と AI 用 API の選択肢\ncreate or replace function banto_inquiry_assignees(p_shop_id uuid)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select coalesce(jsonb_agg(jsonb_build_object('user_id', u.id, 'email', u.email) order by lower(u.email)), '[]'::jsonb)\n    from auth.users u\n   where u.id in (\n           select s.owner_id from shops s where s.id = p_shop_id and s.org_id is null\n           union\n           select m.user_id from shops s join org_members m on m.org_id = s.org_id where s.id = p_shop_id and m.role in ('owner', 'admin')\n           union\n           select ms.user_id from shops s join org_member_shops ms on ms.org_id = s.org_id and ms.shop_id = s.id where s.id = p_shop_id and 'support' = any(ms.perms))\n     and banto_user_shop_perm(u.id, p_shop_id, 'support');\n$$;\nrevoke execute on function banto_inquiry_assignees(uuid) from public, anon, authenticated, service_role;\n\n-- 担当者を決める・外す（共通）。戻り値: { inquiry_id, number, send, to, mail_from }。to は担当になった人のアドレス（知らせるときだけ）\ncreate or replace function banto_inquiry_assign(p_inquiry inquiries, p_user uuid, p_actor uuid)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_send boolean := false; v_to text;\nbegin\n  if p_user is not null and not banto_user_shop_perm(p_user, p_inquiry.shop_id, 'support') then raise exception 'invalid_assignee'; end if;\n  if p_inquiry.assignee_id is not distinct from p_user then\n    return jsonb_build_object('inquiry_id', p_inquiry.id, 'number', p_inquiry.number, 'send', false, 'to', null, 'mail_from', null);\n  end if;\n  update inquiries set assignee_id = p_user, updated_at = now() where id = p_inquiry.id;\n  perform banto_enqueue_inquiry_hook(p_inquiry.shop_id, 'inquiry.updated',\n    jsonb_build_object('inquiry_id', p_inquiry.id, 'number', p_inquiry.number, 'shop_id', p_inquiry.shop_id, 'status', p_inquiry.status, 'change', 'assignee'));\n  if p_user is not null and p_user is distinct from p_actor then\n    select email into v_to from auth.users where id = p_user;\n    if v_to is not null then v_send := banto_inquiry_issue_mail(p_inquiry.shop_id, p_inquiry.id, 'assign', v_to); end if;\n  end if;\n  return jsonb_build_object('inquiry_id', p_inquiry.id, 'number', p_inquiry.number, 'send', v_send, 'to', case when v_send then v_to end, 'mail_from', banto_inquiry_mail_from(p_inquiry.shop_id));\nend;\n$$;\nrevoke execute on function banto_inquiry_assign(inquiries, uuid, uuid) from public, anon, authenticated, service_role;\n\n-- ---------- 運営者（authenticated、support の項目） ----------\ncreate or replace function inquiry_assignees(p_shop_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  if not banto_shop_perm(p_shop_id, 'support') then raise exception 'shop_not_found' using errcode = '42501'; end if;\n  return banto_inquiry_assignees(p_shop_id);\nend;\n$$;\nrevoke execute on function inquiry_assignees(uuid) from public, anon;\ngrant execute on function inquiry_assignees(uuid) to authenticated;\n\ncreate or replace function inquiry_assign(p_inquiry_id uuid, p_user uuid)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_i inquiries%rowtype;\nbegin\n  select * into v_i from inquiries where id = p_inquiry_id for update;\n  if not found or not banto_shop_perm(v_i.shop_id, 'support') then raise exception 'inquiry_not_found' using errcode = '42501'; end if;\n  return banto_inquiry_assign(v_i, p_user, auth.uid());\nend;\n$$;\nrevoke execute on function inquiry_assign(uuid, uuid) from public, anon;\ngrant execute on function inquiry_assign(uuid, uuid) to authenticated;\n\n-- 1 件（0061 を差し替え: assignee_id を足す）\ncreate or replace function inquiry_admin_get(p_inquiry_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\ndeclare v_i inquiries%rowtype;\nbegin\n  select * into v_i from inquiries where id = p_inquiry_id;\n  if not found or not banto_shop_perm(v_i.shop_id, 'support') then return null; end if;\n  return jsonb_build_object(\n    'id', v_i.id, 'shop_id', v_i.shop_id, 'number', v_i.number, 'status', v_i.status, 'category', v_i.category, 'origin', v_i.origin,\n    'contact_email', v_i.contact_email, 'contact_name', v_i.contact_name, 'verified', v_i.email_verified_at is not null,\n    'customer_id', v_i.customer_id, 'claimed_order_number', v_i.claimed_order_number, 'created_at', v_i.created_at, 'closed_at', v_i.closed_at,\n    'masked', v_i.masked_at is not null, 'assignee_id', v_i.assignee_id,\n    'member_match', v_i.customer_id is null and v_i.contact_email is not null\n                    and exists (select 1 from customers c where c.shop_id = v_i.shop_id and lower(c.email) = lower(v_i.contact_email)),\n    'order', case when v_i.order_id is not null then banto_inquiry_order_summary(v_i.order_id) || jsonb_build_object('order_id', v_i.order_id) end,\n    'messages', coalesce((select jsonb_agg(jsonb_build_object('author', m.author, 'body', m.body, 'created_at', m.created_at,\n                                                               'attachments', banto_inquiry_message_attachments(m.id, true)) order by m.created_at, m.id)\n                            from inquiry_messages m where m.inquiry_id = v_i.id), '[]'::jsonb));\nend;\n$$;\n\n-- 未割り当てのチケットに運営者が最初に返事をしたら、その人を担当にする（知らせない。自分の返事なので）\ncreate or replace function banto_inquiry_assign_on_reply()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if new.author = 'shop' and new.author_user is not null then\n    update inquiries i set assignee_id = new.author_user\n     where i.id = new.inquiry_id and i.assignee_id is null and banto_user_shop_perm(new.author_user, i.shop_id, 'support');\n  end if;\n  return new;\nend;\n$$;\nrevoke execute on function banto_inquiry_assign_on_reply() from public, anon, authenticated, service_role;\ndrop trigger if exists inquiry_messages_assign_on_reply on inquiry_messages;\ncreate trigger inquiry_messages_assign_on_reply after insert on inquiry_messages for each row execute function banto_inquiry_assign_on_reply();\n\n-- ---------- AI 用トークン（inquiries:read / inquiries:write） ----------\n-- 0061 を差し替え: assignee（{ user_id, email }、未割り当ては null）を足す\ncreate or replace function api_inquiry_json(p_i inquiries, p_pii boolean, p_messages boolean)\nreturns jsonb language sql stable security definer set search_path = public as $$\n  select jsonb_build_object(\n    'number', p_i.number, 'status', p_i.status, 'category', p_i.category, 'origin', p_i.origin, 'verified', p_i.email_verified_at is not null,\n    'customer_id', p_i.customer_id, 'claimed_order_number', p_i.claimed_order_number, 'masked', p_i.masked_at is not null,\n    'order', (select jsonb_build_object('number', o.number, 'status', o.status, 'total_jpy', o.total_jpy, 'created_at', o.created_at) from orders o where o.id = p_i.order_id),\n    'assignee', (select jsonb_build_object('user_id', u.id, 'email', u.email) from auth.users u where u.id = p_i.assignee_id),\n    'created_at', p_i.created_at, 'last_message_at', p_i.last_message_at, 'closed_at', p_i.closed_at)\n  || case when p_messages then jsonb_build_object('messages', coalesce((\n          select jsonb_agg(jsonb_build_object('author', m.author, 'body', m.body, 'created_at', m.created_at,\n                                              'attachments', banto_inquiry_message_attachments(m.id, p_pii)) order by m.created_at, m.id)\n            from inquiry_messages m where m.inquiry_id = p_i.id), '[]'::jsonb)) else '{}'::jsonb end\n  || case when p_pii then jsonb_build_object('contact', jsonb_build_object('email', p_i.contact_email, 'name', p_i.contact_name)) else '{}'::jsonb end;\n$$;\nrevoke execute on function api_inquiry_json(inquiries, boolean, boolean) from public, anon, authenticated, service_role;\n\n-- 一覧（0061 を差し替え: p_assignee = 'none'（未割り当て）か担当者の user_id で絞る）\ndrop function if exists api_inquiries_list(text, text, integer, integer);\ncreate or replace function api_inquiries_list(p_token_hash text, p_status text default null, p_limit integer default 50, p_offset integer default 0, p_assignee text default null)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_tok api_tokens; v_pii boolean; v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100)); v_offset integer := greatest(0, coalesce(p_offset, 0));\n        v_total integer; v_items jsonb; v_none boolean := p_assignee = 'none'; v_user uuid;\nbegin\n  v_tok := banto_api_inquiries_require(p_token_hash, 'inquiries:read');\n  v_pii := 'orders:pii' = any(v_tok.scopes);\n  if p_status is not null and p_status not in ('waiting_shop', 'waiting_customer', 'closed') then raise exception 'invalid_status'; end if;\n  if p_assignee is not null and not v_none then\n    if p_assignee !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid_assignee'; end if;\n    v_user := p_assignee::uuid;\n  end if;\n  select count(*) into v_total from inquiries i\n   where i.shop_id = v_tok.shop_id and (p_status is null or i.status = p_status)\n     and (not v_none or i.assignee_id is null) and (v_user is null or i.assignee_id = v_user);\n  select coalesce(jsonb_agg(api_inquiry_json(i, v_pii, false) order by i.last_message_at desc), '[]'::jsonb) into v_items\n    from (select * from inquiries i\n           where i.shop_id = v_tok.shop_id and (p_status is null or i.status = p_status)\n             and (not v_none or i.assignee_id is null) and (v_user is null or i.assignee_id = v_user)\n           order by i.last_message_at desc limit v_limit offset v_offset) i;\n  return jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', v_offset, 'pii', v_pii);\nend;\n$$;\nrevoke execute on function api_inquiries_list(text, text, integer, integer, text) from public, anon, authenticated;\ngrant execute on function api_inquiries_list(text, text, integer, integer, text) to service_role;\n\n-- 担当者にできる人（user_id と運営者のメールアドレス。お客様の連絡先ではない）\ncreate or replace function api_inquiry_assignees(p_token_hash text)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_tok api_tokens;\nbegin\n  v_tok := banto_api_inquiries_require(p_token_hash, 'inquiries:read');\n  return banto_inquiry_assignees(v_tok.shop_id);\nend;\n$$;\nrevoke execute on function api_inquiry_assignees(text) from public, anon, authenticated;\ngrant execute on function api_inquiry_assignees(text) to service_role;\n\n-- 担当者を決める・外す（p_user = null で外す）。戻り値: { inquiry, mail: { send, to, mail_from, shop } }（mail は Worker の中だけで使い、AI には返さない）\ncreate or replace function api_inquiry_assign(p_token_hash text, p_number integer, p_user uuid)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_tok api_tokens; v_i inquiries%rowtype; v_r jsonb; v_s shops%rowtype;\nbegin\n  v_tok := banto_api_inquiries_require(p_token_hash, 'inquiries:write');\n  select * into v_i from inquiries where shop_id = v_tok.shop_id and number = p_number for update;\n  if not found then raise exception 'not_found'; end if;\n  v_r := banto_inquiry_assign(v_i, p_user, null);\n  select * into v_i from inquiries where id = v_i.id;\n  select * into v_s from shops where id = v_i.shop_id;\n  return jsonb_build_object(\n    'inquiry', api_inquiry_json(v_i, 'orders:pii' = any(v_tok.scopes), false),\n    'mail', v_r || jsonb_build_object('shop', jsonb_build_object('id', v_s.id, 'name', v_s.name, 'slug', v_s.slug, 'domain', v_s.domain,\n                                                                 'settings', jsonb_build_object('theme_settings', v_s.settings->'theme_settings'))));\nend;\n$$;\nrevoke execute on function api_inquiry_assign(text, integer, uuid) from public, anon, authenticated;\ngrant execute on function api_inquiry_assign(text, integer, uuid) to service_role;\n\ninsert into banto_migrations (version) values ('0068_mod_inquiries_assignee');\n" },
];
